INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özür Dilerim...', 'ozur-dilerim-hulya-karaca-59xvl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül gözü kapalı olmaz, sevgiler de asla son bulmaz babam

Hasretlere doyulmaz bu yüzden de  hasretler son bulmaz

Hele de babayla kızın arasında dargınlık hiç olmaz

Kızlar babalarına kötülük etmez aklında olsun babam

Belki bir hayali vardır belkide bir hevesi, mutlu olmak için sadece

Ama babalarda bunu farklı deyimlerle nitelendirmez

Babalar günün kutlu olsun söyleyemedim karşında babam

Sana yaranmak için söylediğimi düşünme diye sırf ondan

Sevgini asla esirgeme, hor gözlerle bakma ne olur

Benim güleç sevecen olduğumu söylersin hep babam

İnsan hiç somurtamaz morali bozulmaz diye bir kaide mi var

O da benim içimde bir sorundu kusuruma bakma olur mu? 

Her şeyin güzelini layık gördün sakınmadın babam

Allah senden razı olsun gönlümü aldığın mutlu ettiğin için

Ama ne olur cahilliğime ver affet beni BABAM...', 'Gönül gözü kapalı olmaz, sevgiler de asla son bulmaz babam Hasretlere doyulmaz bu yüzden de  hasretler son bulmaz Hele de babayla kızın aras...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ozur-dilerim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi yazar kendi bozar', 'kendi-yazar-kendi-bozar-ali-riza-unal-whzvj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aman Allahım aman, medet ya alemlerin Rabbı.

Ya ya hayyul ya kayyum Ya Hz Allah cc huuuuu.

     Şiirin tamamı deyildir', 'Aman Allahım aman, medet ya alemlerin Rabbı. Ya ya hayyul ya kayyum Ya Hz Allah cc huuuuu.      Şiirin tamamı deyildir...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kendi-yazar-kendi-bozar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyzene 21.Yüzyıldan Selam 5', 'neyzene-21-yuzyildan-selam-5-ali-osman-yilmaz-at9wq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey tanrı,Var mısın,yok musun,

Akıl erer mi senin sırrına,de bana

İçeriz ya sabır diye peymaneni,

Hekmetinden bir kez olsun vermezsin.

Gizlenirsin  bir yokluğun içinde,

Hem ademin,hem şeytanın içinde,

Her bir dinin ayrı ayrı cininde,

Kendine eş,bizi küfre ortak edersin.

Aşk olursun,canımızı yakarsın,

Leylaları karşımıza dikersin,

Acımadan  ayrılığa düçar edersin,

Sevilmeyi bile,bize haram edersin.

Bozuktur kurduğun düzen,

Kimse edemez asla akort,

Ceylana kaç dersin,aslana aport,

Hikmetini  kimse bilmez,ayan edersin.

Şeytan olur görünürsün ateşte,

Dile gelirsin seher vakti bülbülde,

Bir parlayış parlarsın ki güneşte,

Yalanına kendin bile iman edersin.

Bir iradenle adam edersin eşeği,

Karnı tokken,batar ona döşeği,

Gazabından korkarız çakınca şimşeğin,

Tufan olur,.memleketi viran edersin.

Görürler seni her velide,delide,

Hem  Alide,hem pandelide,

Maymuncuk gibi her kilide,

Hem uyar,hem de viran edersin.

Zengin eder,kasalara kitlersin,

Fakir kılar,garip başım bitlersin,

Bir deri,bir kemik,beni ciltlersin,

Acılara canlı  canlı kor edersin.', 'Ey tanrı,Var mısın,yok musun, Akıl erer mi senin sırrına,de bana İçeriz ya sabır diye peymaneni, Hekmetinden bir kez olsun vermezsin. Gizlen...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/neyzene-21-yuzyildan-selam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Kızım Feyza2', 'sevgili-kizim-feyza2-yavuz-selim-tastekne-0mgjy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgili kızım Feyza

canıma can katan

bir çift 

siyah göz içinde

bana 

gizlenen müjde', 'Sevgili kızım Feyza canıma can katan bir çift  siyah göz içinde bana  gizlenen müjde...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Selim Taştekne']::text[], 8.5, '{"poet":"Yavuz Selim Taştekne","poet_slug":"yavuz-selim-tastekne","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevgili-kizim-feyza2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diller bal olur', 'diller-bal-olur-ali-riza-unal-dxwza', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hastane önünde hemşire dikili.

Neredesin derdimin hekimi.

   Eserin tamamı deyildir', 'Hastane önünde hemşire dikili. Neredesin derdimin hekimi.    Eserin tamamı deyildir...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/diller-bal-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirleri Öldürmeyin', 'siirleri-oldurmeyin-mustafa-sekerci-9ey8v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocukluğum yoklara açtı ilk penceresini 

İlk ayrılıklara yürüdüm 

Daha ilk adımlarımda 

Yırtarken ayaklarımı hayatın dikenleri 

Ne anamın sıcak göğsü vardı dayanıp ağladığım. 

Ne babamın saçlarımı okşayan elleri 

Ben hayata dair düşlerimi 

Çocuksu sevdalarımı 

Minicik ellerimle çocukken yaktım 

Çocukken bile ben 

Çocukluğumdan ıraktım 

Bin asırlık bir ömürde 

Ancak birkaç nefes alımı yaşayabildiğimdi bahar 

Yolculara kızılcık satarken tren istasyonlarında 

Hayallerim asılı kaldı hep akranlarımın sokak oyunlarında 

Uçurtmam olmadı hiç uçurup tellere takacağım. 

Bilyelerim yoktu yuvarlayacağım 

Yaz hep başkaları için yazdı 

Zira benim baharlarım zemheri 

Yazlarım ayazdı 

Üşüdü yüreğim baharı gelmeyen kışlarda 

Dizlerim titreyip durdu 

Tökezledim düzü yok yokuşlarda 

Yoruldum 

Tükendim bunca yıl beyhude arayışlarda 

Hani 

Son bir demi olur ya insan hayatının 

Duyacağı son ses 

Alacağı son nefes 

Hani 

Ondan sonrada bir fatiha okur ya ona herkes 

O son demimde işte 

İnsan gibi olmaktı istediğim sadece 

Hasretimi dindirmek 

Alevlerimi söndürmek istedim bir kere 

Can damarım 

Hayat pınarım yanımda olsun istedim 

Yanımda tomurcuklasın istedim 

Yanımda gonca olsun yabandaki gülüm 

Göğsüme çökmeden yakınımdaki ölüm 

Nerde yarım kaldıysa, bıraktımsa nerden 

Yeniden sürsün istedim mutluluğum, 

Hiç başlamadığı yerden 

Tükenip sona ermeden yıllar süren feryadım. 

Şiir tadında olsun istedim kalan kısacık hayatım. 

Ne büyük suç işlemişim meğer 

Ne günaha girmişim. 

Meğer şiir okunmak içinmiş sadece 

Ölürmüş yaşanırsa 

Katili olurmuş şiirin 

Kim şiir gibi yaşadım sanırsa 

Şiirler ölecek ha? 

Öldürmeyin 

Her şiir bir çiçektir 

Soldurmayın 

Umuttur sevda yüklü yüreklere 

Kırmayın 

Veysel’e ışıktır şiir 

Nazıma vatan 

Karacaoğlan’da sevda 

Köroğlun’da isyan 

Ana dilinde ninnidir şiir yavuklu gönlünde hasret 

Gurbet akşamlarında buram, buram sıla 

Yol gözleyende gurbet 

Sevilende nazdır şiir, 

Saz telinde sözdür 

İşitmeyende kulak görmeyende gören gözdür 

ÖZDÜR BE! .. 

İNSAN OLANDA ÖZDÜR.. 

Şiirleri üzmeyin 

Ne olur şiire dokunmayın 

Beni ağlattığınız yeter bari şiiri ağlatmayın 

Ben vazgeçtim türkü güzelliğinde kalmaktan 

Vazgeçtim şiir gibi yaşamaktan 

Vazgeçtim inanın 

Vazgeçtim 

İnsan bile olmaktan 

Tek ölmesin şiirler 

Yaşasın 

Ben vazgeçerim hayattan 

Beni ağlatan sizler, gene beni güldürmeyin 

Bırakın onlar yaşasın 

ŞİİRLERİ ÖLDÜRMEYİN 

Ben ki parkamın yaka cebinde 

Katlime imzalanmış fermanla dolaşırken bile 

Her çiçeği dalında sevdim, 

Toprağında yokladım 

Kıymadım koparmaya, soldurmaya kıyamadım 

Gülü uzaktan seyrettim, karanfili uzaktan kokladım 

Adım arananlar listesinde asılı dururken istasyonlarda 

Bir karıncayı ezmemek için 

Gözlerim ayak uçlarıma çakılı yürüdüm sokaklarda 

Yetimlerle içtim çorbamı, garibanlarla yattım 

Siz kuş tüyü yataklarınızda dönerken sağa sola 

Ben küflü zindanlarda sizden daha rahattım 

Bizim sırtımız alışıktır bıçaklanmaya 

Yüreğimiz parçalanmaya yatkın 

Yaşatın şiirleri 

Yapacağınızı bana yapın 

Demek ben yaşayınca ölecek şiir öylemi? 

Ve sizler tutacaksınız yasını 

Vay anasını be! .. 

VAY ANASINI.... 

Götürün güzel dediğiniz ne varsa benden 

Alın hiç vermediğiniz sevgilerinizi de 

Sizin olsun 

Bırakın umutlarım gene ufuklarda kaybolsun 

Olsun be.. 

Bu seferde gene dediğiniz olsun 

Yeter ki yaşasın güzel olan ne varsa 

Şiire dair 

Bırakın bulacaksa bulsun belasını 

ŞEKERCİ DENEN ŞAİR...', 'Çocukluğum yoklara açtı ilk penceresini  İlk ayrılıklara yürüdüm  Daha ilk adımlarımda  Yırtarken ayaklarımı hayatın dikenleri  Ne anamın sı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şekerci']::text[], 8.5, '{"poet":"Mustafa Şekerci","poet_slug":"mustafa-sekerci","theme":"Türk Şiiri","is_hero":false,"total_lines":113,"source_url":"https://www.antoloji.com/siirleri-oldurmeyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-ali-i-nal-hyx5w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tek istediğim ölüm artık,

Yalan koskoca bir yalan bu, 

Neler isterdim neler

O bal rengi gözler benim olsun, 

Sadece ben kakayım isterdim, 

Kolları sadece beni sarsın,

Elleri sadece benim ellerimi tutsun isterdim,

Böyle bir ayrılık olmasın isterdim, 

Ölesiye sevdiğim gibi, 

O da beni sevsin isterdim

Onunla yaşamak, onunla ağlamak onunla gülmek,

Ve onunla yaşlanıp, onunla ölmek isterdim

Artık yoksa böyle bir ihtimal, 

Kader denilen dikenli tacı takmışsak başımıza,

Bize rava görülen

Sadece onsuz yaşamaya alışmak ise,

Onun için ölmek isterdim,

Bir kez olsun gözlerime baksın, 

Bir kez olsun beni çağırsın, 

Bir kez olsun beni istesin isterdim,

Yaşamak bu batağa saplanmak ise eğer,

Atın beni bir çöplüğe, 

Kargalar yesin 

Ona bakamayan gözlerimi, 

Fareler kemirsin

Ona dokunamayan ellerimi, 

Çürüyüp kokuşup gideyim, 

Neyleyim böyle nefes almayı

Ciğerlerime çektiğim 

Hava değil zehir ise

Her nefeste, 

Tek isteğim ölümdür benim artık

Yalan koskoca bir yalan bu,

Sensiz ölmek, ölmekten beter gelir,

Sensiz olmanın yanında, ölüm ne

Güzel bir hayaldir.', 'Tek istediğim ölüm artık, Yalan koskoca bir yalan bu,  Neler isterdim neler O bal rengi gözler benim olsun,  Sadece ben kakayım isterdim,  K...', ARRAY['Türk Edebiyatı','Şiir','Ali İnal']::text[], 8.5, '{"poet":"Ali İnal","poet_slug":"ali-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yalan-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demir çelik ve Ereğli', 'demir-celik-ve-eregli-huseyin-cayikli-7p3qk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'üç milyon altıyüz bin ton sıvı çelik...

Üreten; yanmış el,nasırlaşmış parmaklar

Yüzde yüz İnsan

hep bir ağızdan 

Tam bağımsız Türkiye diyor

EREĞLİ...', 'üç milyon altıyüz bin ton sıvı çelik... Üreten; yanmış el,nasırlaşmış parmaklar Yüzde yüz İnsan hep bir ağızdan  Tam bağımsız Türkiye diyor ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/demir-celik-ve-eregli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk', 'turk-halil-colak-nk24h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeter uyudun Müslüman olan Türk oğlu Türk

Dünya senden imdat bekliyor ey asıl Türk

Cihan can çekişiyor kurtar cengaver Türk

 Kendine gel tarihe yön veren kahraman Türk

Halil Çolak 20.6.2005 Ankara

.', 'Yeter uyudun Müslüman olan Türk oğlu Türk Dünya senden imdat bekliyor ey asıl Türk Cihan can çekişiyor kurtar cengaver Türk  Kendine gel tar...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/turk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barışmadı Yıldızımız', 'barismadi-yildizimiz-veysel-alkan-y4z1a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben herşeyi gömdüm inan maziye

Sevdiğim her daim sendin vefasız.

Unuttum hep geriye dönersin diye,

Barışmadı seninle hiç yıldızımız.

Ha bugün ha yarın çilen bitmedi

Vuruldu aşkınla gönül amansız.

Dilimin ucundan adın gitmedi,

Barışmadı seninle hiç yıldızımız.

Hani kime göre bu aşk sonsuzdu? 

Ayrılığın rüzgarı esti apansız.

Anladım gerçeği kalpler mutsuzdu

Barışmadı seninle hiç yıldızımız.

Gökyüzümden kayınca aşkın sır oldu

Ve kaybettik herşeyi böyle zamansız.

İkimizin de gönlüne bin çile doldu

Barışmadı seninle hiç yıldızımız.

Şimdi sor bir kendine hata kimdeydi? 

Kim arayıp sormazdı,seni hayırsız.

Umudumu bağladım sonu bu muydu? 

Barışmadı seninle hiç yıldızımız.', 'Ben herşeyi gömdüm inan maziye Sevdiğim her daim sendin vefasız. Unuttum hep geriye dönersin diye, Barışmadı seninle hiç yıldızımız. Ha bugü...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/barismadi-yildizimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninki Bitli Bakla', 'seninki-bitli-bakla-emin-eren-5m731', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dilinden düşmez şarkı ah şu kötü ayrılık

Güneş tam tepedeyken hep gece hep karanlık

Maziden kalan bana bin eyvah bin pişmanlık

Görmedi seni seven bak bunca yıl aydınlık

Sendekinin birine el atarken beş takla

Bir tebessüm yok sende yetinmek hep askıda

Elinki yakut sana sendeki bitli bakla

Sendeki sende sana mutluluğa pusuda', 'Dilinden düşmez şarkı ah şu kötü ayrılık Güneş tam tepedeyken hep gece hep karanlık Maziden kalan bana bin eyvah bin pişmanlık Görmedi seni ...', ARRAY['Türk Edebiyatı','Şiir','Emin Eren']::text[], 8.5, '{"poet":"Emin Eren","poet_slug":"emin-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seninki-bitli-bakla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sevgili Babalar', 'ey-sevgili-babalar-sukru-oksuz-j3vbq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bıkmadan, usanmadan, sıcak, soğuk demeden

Ömür boyu çalışır, boşa gitmez çabalar

Evladını düşünür, içmeden ve yemeden

Gününüz kutlu olsun ey sevgili babalar.

Kimisi şarkı dinler, kimisi türkü, gazel

Erkek kız ayırmadan hepsi de size özel

Yılda bir defa olsun, hatırlanmak da güzel

Gününüz kutlu olsun ey sevgili babalar.

Kim hayırlı, hayırsız araştırarak sordur

Babalar içimizde sönmeyecek bir nurdur

Hakkınızı ödemek biliyorum çok zordur

Gününüz kutlu olsun ey sevgili babalar.

Sizden özür dileriz, ihtiyar, moruk dedik

Kapınıza koşarız, kapanmayınca gedik

Biz evlatlar olarak daima sizden yedik

Gününüz kutlu olsun ey sevgili babalar.

Bizdeki hakkınızı sizler helal ettiniz

Gelin surat asınca evinize gittiniz

Bizlerin iyiliği, tertemiz niyetiniz

Gününüz kutlu olsun ey sevgili babalar.', 'Bıkmadan, usanmadan, sıcak, soğuk demeden Ömür boyu çalışır, boşa gitmez çabalar Evladını düşünür, içmeden ve yemeden Gününüz kutlu olsun ey...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Öksüz']::text[], 8.5, '{"poet":"Şükrü Öksüz","poet_slug":"sukru-oksuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ey-sevgili-babalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-İkiyüzlü AB', 'a-i-kiyuzlu-ab-mikdat-bal-ql185', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İkiyüzlü AB

Dost olurlar mı ki dost dersek şayet? 

Alenen ve gizli düşmanken gayet.

Senden asla razı olmaz der: ayet! 

Bundan büyük delil var mı, ey dostum! 

Bizleri kapıda hep beklettiler

Tavizden tavize şart eklediler

Hristiyanları desteklediler

Anlayış kıt, kafa dar mı ey dostum! 

Bizi tersyüz edip sattıktan sonra

Batık ülkeleri kattıktan sonra

Avrupa birliği battıktan sonra

Oraya girmemiz kâr mı ey dostum! 

Her şeyi bitince kalkıp gelirler

Zaten bizi hazır lokma bilirler

Haklı mıyım, bunu zaman belirler

Şimdi anlamanız zor mu ey dostum! 

Yeter artık yeter çekmeli resti 

Bunlar insanlıkta geçemez testi

Mikdadî bunlardan umudu kesti

Yoksa böyle bir şey der mi ey dostum! 

Ozan Mikdadî', 'İkiyüzlü AB Dost olurlar mı ki dost dersek şayet?  Alenen ve gizli düşmanken gayet. Senden asla razı olmaz der: ayet!  Bundan büyük delil va...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/a-ikiyuzlu-ab-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sunay''ın Kız Kulesine', 'sunay-in-kiz-kulesine-sait-muharrem-say-2q3uf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nedir üzerindeki bu büyü,

Bu kadar dillerde olman neden

Sadece bir kez görsemde seni,

Üzerine yazılan şiirleri okumuşluğumdur

Beni sana çeken,

Epeydir

Anlayanı olmayan bir şey

anlatmak istiyor gibisin

Bir şey

Bir şeyi bu kadar mı anlatamaz

Ya da bir şey

Bu kadar çırpınırken yanlızlığına

Bu kadar mı aşığı vardır aslında

Sendeki bu büyü,

Bu tılsım

Ya da adına ne dersen

Seni çekici kılan

Sanki çok şeysin İstanbul için

Sanki 

tanrının eli 

Uzanıp usulca

çekip çıkarıverse seni

Koskoca bir şehir akıp gidecek boşluğundan

(20.06.2005)', 'Nedir üzerindeki bu büyü, Bu kadar dillerde olman neden Sadece bir kez görsemde seni, Üzerine yazılan şiirleri okumuşluğumdur Beni sana çeke...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sunay-in-kiz-kulesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalıntı Saatler', 'calinti-saatler-muhsin-aktas-3y1tk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceler bir kat daha karanlık

Gündüzler daha da gri

Net görünmüyor artık hiç bir şey

Alacakaranlıkta kaldı hayat

Soyulmuş,dolandırılmış

Tek başına

Buzlar arasında çırıl çıplak

Çalıntı saatlerde kalmış

Bir başına sevdam....', 'Geceler bir kat daha karanlık Gündüzler daha da gri Net görünmüyor artık hiç bir şey Alacakaranlıkta kaldı hayat Soyulmuş,dolandırılmış Tek ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/calinti-saatler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmeden ölmüş gibi', 'olmeden-olmus-gibi-ali-riza-unal-cczrj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seyrana daldım can ile, şu alemi fenayı.

Berzahı kabirden, sanki izinli kul gibi.

   Eserin tamamı deyildir.', 'Seyrana daldım can ile, şu alemi fenayı. Berzahı kabirden, sanki izinli kul gibi.    Eserin tamamı deyildir....', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/olmeden-olmus-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Bir Esinti', 'tatli-bir-esinti-muhsin-aktas-xbh41', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur,önce çisil çisil yağmaya başladı

Sonra sicim gibi akmaya

Soğuk ve kederli yağmaya

Denizi göremiyordum ama

Kokusu ve serinliğini 

Duyuyordum tenimde

Denizin kokusunu taşıyan 

Tatlı bir esinti gibi

Dolaşıyorsun ılık ılık

Pervarsız duygularla

                   Bedenimde......', 'Yağmur,önce çisil çisil yağmaya başladı Sonra sicim gibi akmaya Soğuk ve kederli yağmaya Denizi göremiyordum ama Kokusu ve serinliğini  Duyu...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Aktaş']::text[], 8.5, '{"poet":"Muhsin Aktaş","poet_slug":"muhsin-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tatli-bir-esinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Güzel Sey', 'sevmek-guzel-sey-mehmet-sait-akkus-08ids', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmek güzel Sey

Sevilmek güzel sey

Hele birde sevmek

Egilipte alnindan öpmek 

Lazim sevginin

Masuk olmak güzel sey

Hele birde asik

Bir deste kasik 

Olmak lazim sevginin

Oksanmak güzel sey

Hele birde oksamak

Doyasiya yasamak 

Lazim sevginin', 'Sevmek güzel Sey Sevilmek güzel sey Hele birde sevmek Egilipte alnindan öpmek  Lazim sevginin Masuk olmak güzel sey Hele birde asik Bir dest...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevmek-guzel-sey-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi', 'simdi-cel-lettin-cevik-7ze62', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi, bu şehrin gizli yollarında

Sunulur ateş pahası en yosma gül

Yalnızlığın mühürlü izleri kollarında zûl

Gölgesi düşer bodrumlara tükrük tükrük

                                Ah! Şu ölümün ötesi. Yoksa...

Gece yarısı iki kumru çiçekler üstünde

Apaçık sevişir gözbebekleriyle yıldızlar

Kimse bilmez, yalnız geçkin kızlar

Cehiz sandıklarını okunmuş sulara açar

                                Ah! Şu ölümün ötesi. Yoksa...

Vurgun yemiş susuzluğum dudaklarında

Yüreğimde taşkın baharca bir edâ

Gökkuşağı ve bulutlarla gelen sedâ

Gel diyor akşam olmadan

                                Ah! Şu ölümün ötesi. Yoksa...', 'Şimdi, bu şehrin gizli yollarında Sunulur ateş pahası en yosma gül Yalnızlığın mühürlü izleri kollarında zûl Gölgesi düşer bodrumlara tükrük...', ARRAY['Türk Edebiyatı','Şiir','Celâlettin Çevik']::text[], 8.5, '{"poet":"Celâlettin Çevik","poet_slug":"cel-lettin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/simdi-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahmaranlar(6)', 'sahmaranlar-6-i-smet-barlioglu-l9qru', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '2

‘Çalçı köye gittiğime pişmanım

Gamyon değil, şüfer benim düşmanım’

Akdeniz Caddesi tamamen ıssızdı.

Delikanlı Battal Gazi Sokağı ‘nı geçerken kendi evinin bulunduğu yere doğru baktı. Cami önündeki çıplak ampullü direğin durduğu bölüm epeyce aydınlıktı. Ondan ilerisi gecenin karanlığına gömülmüştü. Yukarı doğru yürürken, sol avucu içindeki kibrit kutusunu binaların kırçıllı beton duvarlarına sürtüyor, duvardan içerlek kapı boşluklarına rastgeldikçe kaldırıyordu. Şemsettin Sami Sokak ‘taki öğrenci yurdunun yanından geçerken içinde bir damar koptu. Biryerlerden boşalan kan sıcak sıcak vücudunun her yanına yayıldı.

‘Anılarımla dolu. Tüm anılarımla. Yirmidört yaşımda girdim, yirmialtıda çıktım. Dile kolay. İki yıl. Hapishanede geçenler gibi iki uzun yıl. Oniki yıl, kırkiki yıl. Ama şimdi iki saniye.’

Yurdun ışıklarına göz gezdirdi. Bütün pencereler karanlıktı.

‘Yatıyorlar. Tümü yatıyor gene. Yatın babam, yatın. Kavun-karpuz yata yata büyür. Kulakların çınlasın Yüksel Büyür. Kimbilir nerelerdesin şimdi? Feleğin bok işleri. Akıllılar içerde, deliler dışarıda. Akıllılar pulsuz parasız, susuz ekmeksiz, deliler pullu paralı, sulu ekmekli. Deliler hür, deliler diplomalı. Deli Tüksel diplomalı. ‘Kubi, dün Amme Hukuku ‘ndan, anladın mı yani, sınavım vardı. Amme ‘yi bilirsin; Hukuk Fakültesi ‘nin bel kemiği. Belkemiği dediğin bir barsaktır. Çok kalın, Kubi. Biliyorsun; ben çok fazla çalışamıyorum: Başım ağırıyor. Hastalık geçirdimdi o olaydan sonra. Lisede inşaattan geçerken başıma kalas düşmüştü. Kafamı yardı ya, ben bayılmışım. İnşaatın sahibini Hicaz bayrağı gibi boyadım rüyamda. Sonraları bana, anladın mı yani, sinir bozukluğu gelmiş, zırt, nasıl gelmişse. Sinir kliniklerinde iki ay yattım ya Kubi, anladın mı yani, paşa gibi yattım. Hastabakıcılar beni çok dövüyorlardı.Bağırıp hastaları rahatsız ediyormuşum diye. Tabii bağırırım, anladın mı yani, herkese pijamalar veriyorlardı, çubuklu, bana ise beyaz gömlek giydiriyorlardı, kolları sırtında bağlanan. Gündüz gözü pencereden adamlar giriyordu hastanedeki odama. Yanlarında köpekler, nah böyle böyle. Oysa benim kollarım bağlı. Bre aman, her yerimi ısıracaklar. Bağırıyorum. Bağırınca da, vay deliymişim de ondan bağırıyprmuşum oluyordu. Var mı bunda delilik, Kubi? Anladın mı yani. Babadan da hayır yok insana. Babam karşımda ağlıyordu, o kadar. Bre baba, aç şu ellerimi, sen kovamıyorsan ben kovayım şu köpekleri. Hayır. Bre baba, soba borusundan adamlar inecek şimdi içeriye. Bilmezsin sen bu hastaneyi. Gündüzleri küçük görünür bu borular. Ama sen gece gör. Aç şu ellerimi, anladın mı yani. Hayır. Babamda iş yok Kubi. Takmış başına bir köpek maskesi, oturmuş havlıyor oturduğu yerde. Yani ki; babam çoban köpeği de, öbürleri fino olduklarından havlayıp kaçıracak. Neyse, bir doktor geldi bir gün. Başımın her iki yanlarına, anladın mı yani, anotlar, katotlar bağladı. Adları öyleymiş onların. Herif beni ampul gibi yakacak besbelli. Ceryanı verince; zırt, ağzımda tek altın dişim vardı, anladın mı yani, o da fırladı ta karşı duvara. Kubi, haşa senden, anladın mı yani, altımı ıslatmışım. Neyse. Benim deli-meli olmadığımı anladılar ama aradan da iki yıl geçti. Sonra, okudum okudum. İşte de hukukun sonundayım. Tabii hiç sürekli çalışamıyorum. Olur tabii. Amme ‘ ye de çalışmak, anladın mı yani, pek para etmez. Sınıf geçen kurban kesiyorsa boşuna mı? Ben sınava gireceğim ya, şansına-mansına. Geçersem geçerim, geçemezsem kalırım, ağlayıp da iki gözden mi olayım? Kubi, ben gittim sabahleyin hamama. Haşa senden, anladın mı yani, gece şeytan aldatmış. Ben gittim hamama. Sanıyorum ki; sınav öğleden sonradır. Olur a, listeye yanlış bakmışım. Ben gitmişim hamama, fakültede mille sınavdayken. Şöyle bir sınava temiz gireyim, belki geçerim diye. Pis oldum mu işim rastgitmez. Kubi, meğer sınav sabahleyinmiş, anladın mı yani. Ben, öğle yemeğimi falan da yedim. Enam-ı Şerif ‘imi muşambaya sarıp koynuma koydum. Saat ondörtte sanıyorum ya, tam o saatte fakülteye gittim, dualar okuyarak. Bir de gittim ki, Kubi, anladın mı yani, sınıflar bomboş. Zırt. Hiç kimseler yok. Eğildim. Kapının anahtar deliğinden bakmak isterken, anladın mı yani, bizim profla çarpışmayalım mı? Meğer, ben bakarken, o da sabahki sınavı yeni bitirmiş, son sınav kağıdını da alıp hepsini sıraladıktan sonra çıkıyormuş. Elinde sınav kapıtlarından tomar, ne aradığımı sordu. Zırt. Söyledim. Açtı kapıyı, salon boş. Dedi ki; sınav sabahleyinmiş, şimdi bitmişmiş. Bir dahaki yıl gelirmişim, anladın mı yani. Kubi, dedim ki; zırt. Bura Hukuk Fakültesi değil mi? Hakkı-hukuku biz burada öğrenmiyor muyuz? Siz hakkın-hukukun profu değil misiniz? Ben saat çizelgesine yanlış bakmışsam şeriattan taş mı düşmüştür? Siz benim bilgimi ölçeceksiniz, gözümün bozukluk derecesini değil. Zırt. Hicaz bayrağı gibi boyadım, Kubi. Sen, dedim, hakkı-hukuku öğretme pozundasın ama ben jilet-peştamal takımını sokakta yitirdim. Ben, anladın mı yani, böyle dedim, artık o nasıl anladı bilmem, Kubi. Yüzüme baktı, baktı, baktı, güldü. Soruları dışarı çıkmışlardan duyup duymadığımı sordu.Hamamda yıkayıcılardan, hamamcıdan duyduğumu söyledim. Güldü. Zırt. Aldı beni, Kubi, tek başıma o bomboş salona. Koydu soruları önüme. Ben şimdi, anladın mı yani, sorulara baktım; hiçbirini bilemiyorum. Bilmediğim şeyleri de düşünsem, az sonra başım ağrımaya, zonklamaya başlayacak. Tükürüğümü, anladın mı yani, alıp alıp gözlerime sürmeye başladım. Yani ki, ben ağlıyorum. Geldi yanıma. Gözlerimin yaşına, ellerimin titremesine, ağzımın seğirmesine baktı. Dedi ki, ben terliyormuşum. Zırt. Hamamdan çıkan terler mi? Aldı soruları önümden, boş kağıdı nıraktı. Bildiğim bir tek soruluk bir şeyi yazmamı istedi. Ben de, inşaatta başıma kalasın nasıl düşüp tepemi yardığını yazdım. Kağıdı verip hatırlattım ki, anladın mı yani, harmana giren porsuk dirgene dayanır. Yani, ettin bana bir hayır, bari bacaklarını iyice ayır ‘a getirdim. Kubi, sınav çizelgeleri asıldı ki; adam gerçekten ayırmış bacaklarını. Yani, ben Amme ‘den geçmişim Kubi. Yani ben fakülteden mezun olmuşum. Zırt. Anladın mı yani, ben mezun olmuşum Kubi. Kubi… Kubi… Kubi…’

Birisi kolunu kuvvetle sarsıp yeniden bağırdı:

- Kubi…

Mahallenin bekçisi Kazım Ağa karşısında duruyordu. Ortadan az kısa boylu, tombul-topalak yüzlü, şağkası başından büyük, sigara içmez, sakız çiğnemez Kazım Ağa.

- Kubi neyin var? 

- bir şeyim yok.

- ‘Merhaba’ dedim, duymadın. ‘Kubi’ dedim, duymadın.

- Duymadım.

- Kaç dakikadır ayakta durmuş, yurda bakıyorsun.

- Yurda bakıyorum.

- Tanrı ‘ya şükret ki kurtulalı epey oldu.

- Epey oldu.

- ‘Yurt’ dediğin hapishane.

- Hapishane.

- Ya da o ki; yoksullar evi.

- Yoksullar evi.

- Ama ilim-irfan yuvası.

- İlim-irfan yuvası.

- Yarının büyükleri hep buralardan çıkıyor.

- Yarının büyükleri.

Kazım Ağa karanlıklara, boş sokaklara, havlayıp koşuşan köpeklere düdük öttürdü:

- Hanımı almaya mı? 

- Hanımı almaya.

- Ta Tophane ‘ye? 

- Tophane ‘ye.

- Git, git; beklenmesin..Eyvallah.

- Eyvallah.

Kazım Ağa Şemsettin Sokağa saptı.

‘Kazım Ağa ‘nın postalları yeni. Boyu bir-iki milim büyümüş. Büyümüş. Yüksel Büyür. Yüksel Büyür sen bu anda biryerlerdesin. Bu anda şu uyuyan toplumun içinde biryerlerde. Terazisin, hakkı tartıyorsun, müvezzisin hakkı dağıtıyorsun. Ölümlere karar verip ‘Uğursuz karar yazdı.’ Diyerek kalemini kırıyorsun. Sen buralardasın. Buralarda biryerlerde. Bu toplumun içinde.’

(Devam edecek…)', '2 ‘Çalçı köye gittiğime pişmanım Gamyon değil, şüfer benim düşmanım’ Akdeniz Caddesi tamamen ıssızdı. Delikanlı Battal Gazi Sokağı ‘nı geçer...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sahmaranlar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Dön', 'geri-don-hasan-can-srmp3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bitmedi geçen yılların acısı,

Geçmedi yüreğimin derin sancısı.

Oturup ağlıyorum hergün kederimden,

Yağmur gibi akıyor damlalar gözlerimden.

Yürüyorum senden kalan anılara,

Sağımda solumda bitmeyen hatıralara.

Durgun anlarımda geçiyor önümden bir masal gemisi,

Her an gözlerimde hiç düşmeyen hayal perisi.

Her akşam başka telden çalıyorum kederleri,

Buruk bir sevinç çocukların gülümsemesi,

Her akşam kısa bir haykırış dudaklarımda,

Bitmedi hala kalbimin acılardan inlemesi.

Senden başka sığınacak yeri yok bu yüreğin,

Görecek başka bir umudu kalmadı bu gözlerin,

Ne olur geri dön gecelere hapsetme bu bedeni,

Ortasında bırakma beni nefes tüketen kederlerin.', 'Bitmedi geçen yılların acısı, Geçmedi yüreğimin derin sancısı. Oturup ağlıyorum hergün kederimden, Yağmur gibi akıyor damlalar gözlerimden. ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geri-don-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen kendine bakıyorsun', 'sen-kendine-bakiyorsun-mikdat-bal-kq2si', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle ters ters bakıp durma

Yüreğimi yakıyorsun

Mü’min mü’minin aynası

Sen kendine bakıyorsun

Sende idi her bir halim

Şeytan düşman,nefis zalim

Ne zaman kesildin alim

Bana nerden okuyorsun

Bilirmisin kitabını

Günahını sevabını

Beğendin mi hitabını

Bana lakap takıyorsun

Allah sana etti minnet

Nasip eyledi hidayet

Sanki sana kalmış cennet

Başkasını yakıyorsun

Dünyada her şey müşterek

Bu gerçeği bilmek gerek

Olsun sende geniş yürek

Sen canımı sıkıyorsun', 'Öyle ters ters bakıp durma Yüreğimi yakıyorsun Mü’min mü’minin aynası Sen kendine bakıyorsun Sende idi her bir halim Şeytan düşman,nefis zal...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-kendine-bakiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle de Gör', 'bekle-de-gor-cel-lettin-cevik-p5m4q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmur çok sonra gelecek

Kenger çiçekleri bilir

Bozkırın her hâlini

Bekle de gör...

Dağ başlarına vurur

Düşlere girer

Şehrin ışıkları pul pul

Pervanelerin

Ateşte yanmak mıdır yazısı

Bir şehir

Derkenar ettiklerim

Evler ve insanlar

Bir sokak

İki çerçeve

İçerdekiler ve dışardakiler

Yarın sancılı

Bekle de gör...

Yağmur çok sonra gelecek

Deli taylar bile bilir

Bozkırın ısırgan otlarını

Bekle de gör...

Kara çarşaflar sarıp bizi

Düşler ülkesine

Korkulara götürür

Yalnızlığın soluğu ensemizde

Ölüm nedir ki

Bir ip 

Yağlı kendir otu

Bir ip

Gündoğumlarında

Ucunda yalnızlığım

Toprak aç bir ana

Doyurur açlığını

Bekle de gör', 'Yağmur çok sonra gelecek Kenger çiçekleri bilir Bozkırın her hâlini Bekle de gör... Dağ başlarına vurur Düşlere girer Şehrin ışıkları pul pu...', ARRAY['Türk Edebiyatı','Şiir','Celâlettin Çevik']::text[], 8.5, '{"poet":"Celâlettin Çevik","poet_slug":"cel-lettin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bekle-de-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine sensizim...', 'yine-sensizim-sibel-uygun-lgz4m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat ellerimden akıp gitti az önce.

Günler yirmidört saat değil artık.

Zaman da kaybolmuş...

Gecenin yıldızları,

Gündüzün güneşi de yok! ..

Okyanusların suyu bile çekilmiş.

Ağacın yeşili, papatyanın sarısı...

Senin peşin sıra hepsi terketmiş evreni...

Karanlık dört duvarın içindeyim.

Çaresizliği kendimle çarpıp, 

Sensiz yaşadığım günlere böldüm.

Yokluğun bir kez daha yüreğimi acıttı.

Gücüm kalmadı artık! ..

Şimdi, nefesimi tuttuyorum.

Ha öldüm, ha öleceğim...', 'Hayat ellerimden akıp gitti az önce. Günler yirmidört saat değil artık. Zaman da kaybolmuş... Gecenin yıldızları, Gündüzün güneşi de yok! .....', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yine-sensizim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Unutma', 'unutma-nurten-altinok-jtmwv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin adın güven kıran olmalı

Senin adın dost kıran

Senin adın dalga

Benim adım dalgakıran

Unutma…', 'Senin adın güven kıran olmalı Senin adın dost kıran Senin adın dalga Benim adım dalgakıran Unutma…...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/unutma-208-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Kurmak', 'hayal-kurmak-ayhan-akdogan-26g4a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'umudu hayale bağlayıp karadenize açılmak gibi birşey 

gecnin herhengi bir yarısında toprak kokusuna cıkmak 

sessizliğin gürültüsünde senin hasretinle sevişmek

yoklugunda satıh yollardan medet ummak seni aramak

düşen herbir yağmur damlasında adını sayıklamak

boztepenin o serin siyahından ordunun ışıgı olmak

deniz kenarına geçip bir sigarada seni anmak

üstüne hiçbir şey almadan geceyi içine cekmek seni özlemek

şu ucube hayatı düşkünlere verip bu diyarlardan gitmek

yüzünde bir tebessüm resmini duvarlara afiş yapmak

yorgun ama ümitli gözlerde seni görmek hayallerde

her gece düşlerde ellerini hissetmek gibi birşey seni sevmek

zemheri ayazında sokğın başında baharı beklemek

ellerimde solgun gülleri toplayıp suya bırakmak

kış güneşinin ardından bakıp seni görebilmek

senin olmadıgın herbir toprak damında seni hayal etmek...', 'umudu hayale bağlayıp karadenize açılmak gibi birşey  gecnin herhengi bir yarısında toprak kokusuna cıkmak  sessizliğin gürültüsünde senin h...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Akdogan']::text[], 8.5, '{"poet":"Ayhan Akdogan","poet_slug":"ayhan-akdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayal-kurmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Şehir', 'buyuk-sehir-muhammet-faruk-koca-5tuh2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah be güzelim ah, 

Nereden geldik bu koca şehre, 

İstanbul’un toprağı altın derler, 

Hani bulamadık ya, 

Hani nerede bizim köydeki evler, 

Şehrin hali Allaha galmış gardaş, 

Burada kocaman kocaman apartman dikmişler, 

Ah be koca şehir insanları yutarsın doymasın ya, 

Şehrin hali değişmiş, 

Avratlar erkek olmuş, 

Erkekler avrat olmuş, 

Kıyamet kopmuş bu şehirde gardaş kıyamet, 

Yine şehre gelmek istersen adresim, 

İstanbul’un ilk göbeğinden döndüğünde ilk meyhane, 

Bekler em ha. 

(09.05.2000)', 'Ah be güzelim ah,  Nereden geldik bu koca şehre,  İstanbul’un toprağı altın derler,  Hani bulamadık ya,  Hani nerede bizim köydeki evler,  Ş...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/buyuk-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayellerim', 'hayellerim-muhammet-faruk-koca-ynan6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstanbul’a bir yağmur yağıyor, 

Sarıyor tüm benliğimi, 

Nisan yağmurları galiba bunlar, 

Dolaşıyor âşıklar yine bu akşam, 

Kafamı çeviriyorum gökyüzüne, 

Perde misali iniyor yağmur yüzüme, 

Âşıklar dolaşıyor parklarda, 

Yağmur altında o romantik havada, 

Eriyorum şimdilerde o yağmur taneciklerinin altında, 

O ıssız sahilde hayallerimle. 

(06.01.2000)', 'İstanbul’a bir yağmur yağıyor,  Sarıyor tüm benliğimi,  Nisan yağmurları galiba bunlar,  Dolaşıyor âşıklar yine bu akşam,  Kafamı çeviriyoru...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Faruk Koca']::text[], 8.5, '{"poet":"Muhammet Faruk Koca","poet_slug":"muhammet-faruk-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hayellerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zordur yaslilik bilemezsin', 'zordur-yaslilik-bilemezsin-ulya-erkman-mlk9b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sairimizin yazdigi gibi

  ''Yolun yarisi''nda degilim

   Yolun sonundayim belki simdi

   Bitmedi ama yol yuruyecegim bilirim

      Zordur yaslilik bilemezsin

   Sunlari yapardin eskiden

   Simdi rica ediyorsun birine

   Gururum ne oldu derken

   Eskisi gibi degilsin kime ne

      Zordur yaslilik bilemezsin

   Carsi pazar dolasamazsin

   Veya sinema tiyatro lokanta

   Cunki sen yanliz olamazsin

   Goturen olursa cikarsin sokaga

      Zordur yaslilik bilemezsin

   Yanlizsindir evde bu yasta

   Konusacak insan ararsin haliyle

   Telefondaki ses bile yeter sana

   Aradi biri diye sevinirsin sessizce

      Zordur yaslilik bilemezsin

   Hayatin sanki bir sinema

   Kapatip gozlerini seyredersin sessizce

   Muvaffak olmussun bircok sahada

   Gurur duymuyorsun yinede kendinle

      Zordur yaslilik bilemezsin

   Keski senin yasina gelince

   Senin gibi olsak demisler

   Kendileri gibi olsunlar bence

   Icimdeki firtinayi sezmemisler', 'Sairimizin yazdigi gibi   ''Yolun yarisi''nda degilim    Yolun sonundayim belki simdi    Bitmedi ama yol yuruyecegim bilirim       Zordur yasl...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/zordur-yaslilik-bilemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karasevda', 'karasevda-ahmet-yalcinkaya-aefd4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kenara bıraktım işimi 

Evimi, 

Sözümü, sazımı, 

Bıraktım bir kenara erişimi 

Bıraktım değişimi 

Dünyayı 

Baharımı, kışımı ve yazımı 

Var/yok ne varsa 

Her şeyi 

Ne varsa aşktan başka 

Yeniden kurdum semayı 

Seninle 

Bilimsiz, sessiz, cebirsiz 

Gece karanlığında 

Sen bilmesen de 

Yere indirdim Ay’ı 

Seninle hülyalarım, düşlerim 

Uzaklara yelken açmış gemiler 

Seninle 

Gülüşlerim, ölüşlerim 

Her saati yıla denk ikindiler 

Ya senin ümidinde 

Ey beni muma çeviren sihir 

Ya senin 

Hayallerinde dolaşan kimler 

Özsuyumu damla damla akıtan 

Aşk pazarında sattıran süzgeç sende 

Benim külümü göğe 

Savuran eller kimde 

İçimde kanatlanan bir kuş 

Coşkun bir ırmak 

Ve yeşeren filiz 

Seninle 

Kanayan gül 

Göçüp giden turnalar 

Seninle hüzünlü 

Yine de 

Seninle güzel ağlayan gül 

Tüm çiçekler seninle güzel 

Seninle bana ilham verir 

Gerçek dost gibi sadık aynalar 

Ufuk kızıla çalar 

Ey beni dipsiz kuyuya atan adım 

Dişleri arasında bir kâbusun 

Çiğnenir giderim 

Seninle… 

Ummanlara salar, dertlere salar 

Saçların beni 

Ve engin kucağında suyun 

Senin için feda ederim 

Ne varsa istediğin. 

Ne varsa aşktan başka 

Yine bırakırım bir kenara 

Giderim 

Ey alınyazımda varlığı belli 

Celladım, 

Sabrım yeter senin toprağına 

Yeter mezar taşına 

Erise de zamanın kor ateşinde 

Öyle mecalsiz 

Halsiz beklerim… 

Ne var ki ah, 

Ne var ki kalmadı tadım. 

Belki bir ân olur 

Değer bulursun bakmaya, 

Ömrüme mal olsa da razı köleyim 

Değer bulursun belki itip kakmaya 

Ve her şey yerini bulur 

Diye karanfiller derdim sana deseydim 

Ne değişirdi şu ufkun ardında 

Eğer ufuk karaysa 

Eğer esirse gözlerim gözlerinin izinde 

Eğer benim zenginliğim, sevincim 

Senden aldığım onulmaz yaraysa… 

Benim istediğim ne yer 

Benim istediğim ne gök 

Eller fezaya çıksınlar 

Eller kanlara girsinler, ya da canlara girsinler 

Benim istediğim sensin 

Diye kalan canımı 

Verip önünde diz çöksem 

Ne değişir avcundaki ruhumun 

Katili kanlı kılıcın kınında 

Değil mi ki sen yerini bulmuşsun 

Beni yılanlarla yola koyarak 

Gözümün kuraklığını görmeden 

Bilmeden 

Çarmıha gerdiğin beni 

Bir dilenciden bile saymayarak 

Değil mi ki başkasının olmuşsun', 'Bir kenara bıraktım işimi  Evimi,  Sözümü, sazımı,  Bıraktım bir kenara erişimi  Bıraktım değişimi  Dünyayı  Baharımı, kışımı ve yazımı  Var...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yalçınkaya']::text[], 8.5, '{"poet":"Ahmet Yalçınkaya","poet_slug":"ahmet-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/karasevda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollarımız Toz Dostum', 'yollarimiz-toz-dostum-murat-nail-guney-sdj00', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Selam verdik, borçlu çıktık derler ya,

Gönül verdik, dertli olduk biz dostum.

Çileleri kader yazmış alnıma,

Bir de yardan ihaneti yaz dostum...

Çok yaşayan değil, gezen bilirmiş,

Bizim gibi gurbet gurbet gez dostum.

Hasret kaldık selamına burada,

İki satır mektup yolla tez dostum...

Vefasızlar çıkar hayat yoluna,

Eğlemez gönlünü şarkı, saz dostum.

Gelmez miydik sanıyorsun yanına,

Görünmüyor yollarımız, toz dostum...

Çiçek olsan koparırlar dalından,

Derviş olsan çevirirler yolundan,

Bülbül olsan bıktırırlar gülünden,

Dostun ile düşmanını sez dostum...

Sezar''ın hakkını vermez Sezar''a,

Gözün açık götürürler mezara,

Çok sevenler gelir imiş nazara,

Sevdalara tez değiyor göz dostum...

Muradım der; hayat kapısız bir han,

Kimseye miras kalmıyor babadan,

Ne kazandık bunca emek, çabadan,

Sen gel de bu bilmeceyi çöz dostum...

Murat Nail Güney

19/06/2005   Anamur -Mersin', 'Selam verdik, borçlu çıktık derler ya, Gönül verdik, dertli olduk biz dostum. Çileleri kader yazmış alnıma, Bir de yardan ihaneti yaz dostum...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yollarimiz-toz-dostum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Babam', 'can-babam-abbas-yurt-kmxjd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mümkün mü kaybetmen ağırlığından,

Ağır ama saygı dolu can babam.

Hiç ödün vermezsin mağrurluğundan,

Mağrur ama kaygı dolu can babam.

Uğruna geçersin hemen canından,

Tek saygı beklersin evlatlarından.

Çok sırlar yatıyor vakurluğundan,

Vakur ama şevkat dolu can babam.

Ödün verme sakın sen mertliğinden,

Bıksan da hayatın namertliğinden.

Kendini bulursun hep sertliğinden,

Hep sert ama sevgi dolu can babam.

Hayatı ölçersin tam kertlerinden,

Darbeler yemişsin en sertlerinden.

Yine de yılmadın bu dertlerinden,

Dertli ama güven dolu can babam.

Bıktın hayatın dik başlılığında,

Yoruldun yolların taşlılığında,

Yanında istersin yaşlılığında,

Yaşlı ama hayat dolu can babam.

                                        19.06.2005

                                         Abbas YURT

(Zirve Gazetesinde Yayımlanmıştır.)', 'Mümkün mü kaybetmen ağırlığından, Ağır ama saygı dolu can babam. Hiç ödün vermezsin mağrurluğundan, Mağrur ama kaygı dolu can babam. Uğruna ...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/can-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azımsama Raporu', 'azimsama-raporu-humeyra-yilmaz-zwkvb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“Ben aydınlık istedim

Sen beni karanlığın kör dibine hapsettin”

Bir yalanlık ömrü kalmıştı aşkımın / sana yenildi 

Hala öyle gülümseyebiliyor musun, merak ediyorum

Hani var ya mutluluğa yenik düşmüş / pişman gülüşün

Adını, aşkın bilinmeyen harfleriyle gökyüzüne işleyen adam

Bu yazlara aldanma, günü gelip mevsim sonbahar olduğunda 

Sen de düşeceksin damla damla / hak ettiğin büyük yalnızlığa

Belki ikinci tekil şahıs sevişlerin gelecek aklına 

Ya da birinci tekil şahıs sevişmelerin 

Olur ya, üzüm gözlerinin sarhoşu bir bedene akarsan yine

Daha küçük yalanlar söylemeyi dene...! 

Savaş mıydı istediğin? 

İşgale hazır ve teslim bayrağının çıtasına yüreğini bağlamış 

Masum yoncaları ezmek miydi amacın? 

Kazandın / artık zafer senin 

Şayet bağrını delip geçmezse / dilediğin gibi taşı göğsünde...! 

Bir aşkı kundaklayıp, başka bir aşka saklanmakta ne demek? 

Asıl yanan sen değil misin bu yangında? 

Ortaya koymadığın bir yürek varsa / unut gitsin...

Bırak rüzgar taklidi yapıp da yangını körüklemeyi

En iyisi, öfkemi de al yanına git buralardan

Olur ya, titreyen avuçlarının sıcağına muhtaç bir ele uzanırsan yine

Daha  küçük yangınlar çıkarmayı dene...! 

Artık hangi şiirin arkasına saklanabilirsin bu oyunlarınla 

Sözcüklerle sevişip ihanete gebe bıraktığın cümleleri

Dök gitsin, hırçın dalgalarına sevdalandığın kara denize

O bile köpürmezse / namerdim...! 

Duruşundaki asalete kurban olduğum Ağrı

Keşke seni bassaydım bağrıma ya da Nemrut’u

Hiç değilse bilirdim yıkılmayacağınızı / yıkmayacağınızı

Zirvenizde içime çektiğim ve genzimi yakan bu hüzün bana ait değil

Ben sadece kırgınım / biraz da yorgun

Sana gelince,

Olur ya, cesur duruşunun gücüne kapılan bir yürekte esersen yine

Daha küçük dağları yıkmayı dene...', '“Ben aydınlık istedim Sen beni karanlığın kör dibine hapsettin” Bir yalanlık ömrü kalmıştı aşkımın / sana yenildi  Hala öyle gülümseyebiliyo...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/azimsama-raporu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme', 'anneme-mehmet-yilmaz-bulancakli-23ctf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anne ayrı düştüm senden,					

Gurbet elde ağlarım ben,					

Gülemem sen de yokken,					

Her yerde seni ararım ben.					

					

Anne uzaktan gelir sesin,					

Sılada hangi kederlesin,					

Yüreğim kanar,gelmez sesin,					

İnan sensiz yaşayamam ben.					

					

Anne sevgine dünya değişilmez,					

Kıymetini bilmeyen hiç bilmez,					

Sensiz dünyalarda gülünmez,					

Hasretine artık dayanamam ben.					

								

1990-Ana Dergisi-İSTANBUL					

20.06.2005-Antoloji.com', 'Anne ayrı düştüm senden,					 Gurbet elde ağlarım ben,					 Gülemem sen de yokken,					 Her yerde seni ararım ben.					 					 Anne uzaktan g...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anneme-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram oldu', 'haram-oldu-mehmet-yilmaz-bulancakli-m243g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmeden geçti en güzel yıllarım,					

Artık ümitsiz aşkıma ben ağlarım,					

Yaşamadan soldu hep baharım,					

İçimde sevgin bir mezar oldu.					

					

Yaşamadım gönlümce bu dünyayı,					

Sen yoksun gülmez bana yıllarım,					

Genç ömrümde çekerim bu acıyı,					

Acılar çekmek hep kaderim oldu.					

					

Hayal kurdum sana hep gece gündüz,				

Senden ayrı gülmedi bana bir yüz,					

Ağlayan kalbimi artık güldürünüz,					

Bu dünyada gülmek bana haram oldu.										

Ekim1993-Avcıların Sesi-İSTANBUL					

20.06.2005-Antoloji.com', 'Sevmeden geçti en güzel yıllarım,					 Artık ümitsiz aşkıma ben ağlarım,					 Yaşamadan soldu hep baharım,					 İçimde sevgin bir mezar oldu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/haram-oldu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sevgi arıyorum', 'bir-sevgi-ariyorum-mehmet-yilmaz-bulancakli-9f0vb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevgi arıyorum, 					

Kışımı yaz edecek,					

Onu herkese soruyorum,					

Kalbini bana verecek.					

					

Gönlümle gül gibi geçinecek,					

Hayatım boyu beni sevecek,					

Sevgimizi dile düşürmeyecek,					

Bir sevgi arıyorum.					

					

Umutlarım onunla gülecek,					

Beni candan hep sevecek,					

Elemi,kederi kalpten silecek,					

Bir sevgi arıyorum.					

								

26.01.1997-İSTANBUL					

N.00926					

20.06.2005-Antoloji.com', 'Bir sevgi arıyorum, 					 Kışımı yaz edecek,					 Onu herkese soruyorum,					 Kalbini bana verecek.					 					 Gönlümle gül gibi geçinecek,	...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-sevgi-ariyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban olayım', 'kurban-olayim-mehmet-yilmaz-bulancakli-grmj2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzelim geliyor fidan boylu,					

Diyorlar pek de güzel huylu,					

Biraz da nazlı,asil soylu,					

Kaşına,gözüne kurban olayım.					

					

Her köşe başı onu beklerim,					

Cilvesini,nazını sineme çekerim,					

Uğruna ölüme bile giderim,					

Gerdanına,özüne kurban olayım. 					

					

Dertlerimi kendimle bölüşürüm,					

Rüyalarımda bile onu görürüm,					

Gece gündüz seni düşünürüm,					

Yaradana,özüne kurban olayım.					

								

26.01.1997-İSTANBUL					

N.009261					

20.06.2005-Antoloji.com', 'Güzelim geliyor fidan boylu,					 Diyorlar pek de güzel huylu,					 Biraz da nazlı,asil soylu,					 Kaşına,gözüne kurban olayım.					 					 ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kurban-olayim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttun sevdiğim beni', 'unuttun-sevdigim-beni-mehmet-yilmaz-bulancakli-w5759', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllar su gibi geçti,					

Bilinmedi şu halim,					

Anlatamadım derdimi,					

Gülmedi yüzüm benim.					

					

Ne dost ne arkadaş,					

Sormaz oldu beni,					

Gözlerimde artık yaş,					

Sen gittin gideli.					

					

Nasıl mutlu olayım,					

Bu dertler içinde,					

Kimden umut bulayım,					

Ağlatan yıllar peşimde.					

							

1985-Merhaba-İSTANBUL					

20.06.2005-Antoloji.com', 'Yıllar su gibi geçti,					 Bilinmedi şu halim,					 Anlatamadım derdimi,					 Gülmedi yüzüm benim.					 					 Ne dost ne arkadaş,					 Sorma...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unuttun-sevdigim-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski resimler', 'eski-resimler-mehmet-yilmaz-bulancakli-ehwxw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevemedim bir sevgili,					

Sevgi yaprağım döküldü,					

Gülmedi yüzüm sen gideli,					

Gurbet elde boynum büküldü.					

					

Sevmeden yaşayamazdım,					

Artık sensiz hiç olamazdım,					

Aşkınla böyle hiç yanmazdım,					

Hasretinle gözyaşım döküldü.					

					

Sevemedim senin gibi,					

Ömrümden geçti mevsimler,					

Sevda çeken varmı benim gibi,					

Elimde kaldı eski resimler.					

								

Şubat 1994-Ana Dergisi-İSTANBUL					

20.06.2005-Antoloji.com', 'Sevemedim bir sevgili,					 Sevgi yaprağım döküldü,					 Gülmedi yüzüm sen gideli,					 Gurbet elde boynum büküldü.					 					 Sevmeden yaşa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eski-resimler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-mehmet-yilmaz-bulancakli-6c64n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günün kutlu olsun baba,					

Ak saçların dağılmış yüzüne, 					

Yıllarmı koydu seni bu hale,					

Yinede kalmışsın özünde. 					

					

Yüzünde çizgiler belirli,					

Artık yıllar götürmüş seni,					

Anlat artık bana tecrübeni,					

Hep severler baba gibi bileni.					

					

Günün kutlu olsun baba,					

Al şu gömleği senin olsun,					

Giy bak bedenine uysun,					

İyi bak kendine baba.					

								

19.06.2005-Bulancak-GİRESUN					

20.06.2005-Antoloji.com', 'Günün kutlu olsun baba,					 Ak saçların dağılmış yüzüne, 					 Yıllarmı koydu seni bu hale,					 Yinede kalmışsın özünde. 					 					 Yüzün...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/baba-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Seni yazmalıyım şimdi', 'seni-yazmaliyim-simdi-nurten-altinok-qrfcn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'oturup seni yazmalıyım

nefes nefes

kumrular kıskanmalı gözlerimizi

kumrular ellerimizi

kumrular sevişmelerimizi

oturup seni yazmalıyım şimdi

sonra beni ve bizi

oturup seni yazmalıyım

şiir şiir

öpüşen dalgalara çakıl taşlarıyla

martı kanatlarında bulutlara yüklenmeliyim

damla damla çiy tanesi düşmeliyim dudaklara

girebilmeliyim aynadaki zamana

oturup seni yazmalıyım şimdi

sonra beni ve bizi

oturup seni yazmalıyım

duman duman

rüzgarlar yolunu şaşırmış olmalı

geceler kördüğüm yangınımdan

göçmen kuşlar halaya katılmalı

-mevsimleri kanatlarında taşıyan

oturup seni yazmalıyım şimdi

sonra beni ve bizi

oturup seni yazmalıyım

duman duman

aslı gibi şirin gibi zühre gibi…

oturup seni yazmalım şimdi

kerem gibi tahir gibi ferhat gibi olamasan da

sen gibi kendin gibi gelebilmeni

çatlatıp göklerin gözbebeklerini

avuçlarıma inebilmeni

oturup seni yazmalıyım şimdi

sonra beni ve bizi

geldiğin gün bayram olmalı…', 'oturup seni yazmalıyım nefes nefes kumrular kıskanmalı gözlerimizi kumrular ellerimizi kumrular sevişmelerimizi oturup seni yazmalıyım şimdi...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/seni-yazmaliyim-simdi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahibinin Sesinden Sahipsiz Aşk', 'sahibinin-sesinden-sahipsiz-ask-atilla-guler-zgoq9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dur dediğim yerde durmuyor deli yürek

söz dinlemez başıboş bir gezgin

dağ bayır

dereler hırçın

alevlerin içinde

sırtına vurulmuş yükü

yok kurtuluşu

kuruyan dudaklarında bir damla su

…aşk

usuna düşmüş gözlerin vurgunu

masumiyet sızar inceden

salya sümük hatıralar

geçmişe dönüşte takılır hayat

bodoslama dalınan bir boşluk

…aşk

vuruldukça daha da arsız

arsızlaştıkça hesapsız

bağ bahçe talan

yangın yeri gönül

viran

susmadıkça çoğalan susmalar

susunca çoğalan sözler gibi

aşk içimde velhasıl

sahipsizliğini bile bile', 'dur dediğim yerde durmuyor deli yürek söz dinlemez başıboş bir gezgin dağ bayır dereler hırçın alevlerin içinde sırtına vurulmuş yükü yok ku...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sahibinin-sesinden-sahipsiz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kur’an Okumak', 'kur-an-okumak-ali-tosmer-ouw8a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biricik Kitâb’ımı ne de az okuyorum

Nefsime ilmek ilmek günahlar dokuyorum

Bir O’na kul olmasam zehirli bir akrebim

Ateşlere dalıp da kendimi sokuyorum.

(canımaokuyorum’05)', 'Biricik Kitâb’ımı ne de az okuyorum Nefsime ilmek ilmek günahlar dokuyorum Bir O’na kul olmasam zehirli bir akrebim Ateşlere dalıp da kendim...', ARRAY['Türk Edebiyatı','Şiir','Ali Tosmer']::text[], 8.5, '{"poet":"Ali Tosmer","poet_slug":"ali-tosmer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kur-an-okumak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
