INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A11 - Çok mu Adil', 'a11-cok-mu-adil-tahir-gungor-eoxn8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birlikte gezip, yiyip içtiğimiz,

Hem kucak, hem de gönül açtığımız,

Uğruna çok savurup saçtığımız,

.......................Dostların bize selamı,

.......................Çok mu içten,

.......................Çok mu adil.

Afacan ürkek, yaramaz uslumuz,

Geleceğe yetişecek neslimiz,

Et ve kemik ellerine teslimiz,

.......................Eğiten hocalar bize,

.......................Çok mu candan,

.......................Çok mu adil.

Onlarla kale, evimiz, hanemiz,

Dünya bir yana, baş tacı, bir tanemiz,

Varlık sebebi babamız, annemiz,

...................... Büyüklerimiz bizlere,

.......................Çok mu sıcak,

.......................Çok mu adil. 

Dikil ağacımız yokken bir tek,

Ederiz mal ve canımıza ortak,

Yoluna ölsek, ne kefen, ne mertek,

.......................Koca devletimiz bize,

.......................Çok mu sahip,

.......................Çok mu adil.

Kimi boğulmuş da, varlıkdan, vardan,

Geçilmiyor sefil, bahtı karadan,

Her şeye kadir olan Hak, Yaradan,

.......................Ulu tanrı biz kullara,

.......................Çok mu cömert,

.......................Çok mu adil.', 'Birlikte gezip, yiyip içtiğimiz, Hem kucak, hem de gönül açtığımız, Uğruna çok savurup saçtığımız, .......................Dostların bize sel...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/a11-cok-mu-adil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son bulsun! ! (% 100 Şematik)', 'son-bulsun-100-sematik-mikdat-bal-x5pjk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haram olsun………...ateş olsun…………….rüşvetle………………aldıkları

Ateş olsun…………..bu milletten…………..hileyle………………..çaldıkları

Rüşvetle,……………hileyle………………..bunlar, çok oldu……...kaldıkları

Aldıkları,……………çaldıkları,…………….kaldıkları…………….son bulsun

Bunlar soyar………...her birini……………..gariban……………….buldukları

Her birini…………...insafsızca……………..sömürüp……………..yoldukları

Gariban……………..sömürüp, …………….şişer, kabarır…………koltukları

Buldukları…………..yoldukları,……………koltukları……..…….son bulsun

En ufak bir………….küçük işten…………...bahşiş, ya……………rüşvet alan

Küçük işten…………isteyene………………demeli………...……..yeter ulan! 

Bahşiş ya……………demeli………………..buna, düpedüz………yalan dolan

Rüşvet alan,…………yeter ulan! ...................yalan dolan………….son bulsun

Mikdat der ki……….keneleri………………çatlatsın……………… yedikleri.

Keneleri…………….şişirmiştir…………….bunca kan……………. Içtikleri

Çatlatsın…………….bunca kan……………onları, yeter bu……….şiştikleri

Yedikleri,…………...içtikleri,……………...şiştikleri………………son bulsun', 'Haram olsun………...ateş olsun…………….rüşvetle………………aldıkları Ateş olsun…………..bu milletten…………..hileyle………………..çaldıkları Rüşvetle,……………hileyle……...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-bulsun-100-sematik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kadar Zor Kİ', 'o-kadar-zor-ki-murat-aydindag-fxpc6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O kadar zar ki yanlızlık,

anlatılmaz bir duygu sanki,

bir köşede kalmak amansızca,

anlamamak sölenen yalanları,

ama bazen güzel bir duygu yanlızlık,

düşünmek yok yarını aşkını,

bırakacak bir acı ardından diye,

giderken ardından akacak yaşlar,

korku yok kısaca aklında,

ama yaşanılmaz aşksız,

elini tutacak bi zalimsiz,

sesini özleyecek bir sevgilisiz,

herşey bizim içinmiş oysa,

yanlızlık ta,acıda,üzünde,

çaresis kaçışlar hayattan,

ölümde var aşkların sonunda,

gülmekte sonsuzluğa...', 'O kadar zar ki yanlızlık, anlatılmaz bir duygu sanki, bir köşede kalmak amansızca, anlamamak sölenen yalanları, ama bazen güzel bir duygu ya...', ARRAY['Türk Edebiyatı','Şiir','Murat Aydındağ']::text[], 8.5, '{"poet":"Murat Aydındağ","poet_slug":"murat-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/o-kadar-zor-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A12 - Olmayınca', 'a12-olmayinca-tahir-gungor-c4h1k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevinçler, ah vah olur,

Yalanlar mübah olur,

Arzular günah olur,

...........Bilgi görgü olmayınca.

Dert, bela sargın olur,

Yakınlar dargın olur,

Gönüller dargın olur,

...........İnan güven olmayınca.

Acıların yadı mı olur,

Güzel günün adı mı olur,

Sofraların tadı mı olur,

...........Dirlik birlik olmayınca.

İkramlar azık olur,

Tutkular ezik olur,

Gençliğe yazık olur,

...........Yaşam kuşam olmayınca.

Mevsimler dönük olur,

Rüyalar bölük olur,

Bayramlar sönük olur,

...........Huzur sükun olmayınca.

Geceler korku olur,

Hayaller ürkü olur,

Feryatlar türkü olur,

...........Hazla nazla olmayınca.

Gönüller doluk olur,

Benizler soluk olur,

Göz yaşı oluk olur,

...........Eşi dengi olmayınca.

Sabırlar doruk olur,

Hevesler buruk olur,

Zevkler koruk olur,

...........Sevgi saygı olmayınca.', 'Sevinçler, ah vah olur, Yalanlar mübah olur, Arzular günah olur, ...........Bilgi görgü olmayınca. Dert, bela sargın olur, Yakınlar dargın o...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/a12-olmayinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severim', 'severim-i-lhan-koruyucu-ih7gc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğayı severim ben.

                         Balı ve çiçeği de,

                         Dalında öten kuşu, böceğide.

                         Şaçlarım ıslak olsa yağmuru da.

                   Kafamı dinlemeyi sevdiğim gibi.

                  Çocuk seslerini de severim neden mi.? 

                 Çünkü onlar gürültü değildir ki.

                 Ben güneşi ve ayı da severim.

                      Severim mehtaplı gecelerde dolaşmayı,

                      Dağda bayırda kıran kırana güreşmeyi.

                      Neden severim güzeli bilirmisin.? 

                     Bilmene gerek yok güzel sevilirde ondan.', 'Doğayı severim ben.                          Balı ve çiçeği de,                          Dalında öten kuşu, böceğide.                       ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/severim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Doğdun (Narin İnci Çiçeği)', 'sen-dogdun-narin-i-nci-cicegi-volkan-yoruc-7azhi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen doğdun

Bir haziran sonunda kundağa kondun

Gülücük saçtın

Bir bahar bahçesinden yayılan o hoş kokuyu gönüllere bıraktın

Sen bugün doğdun

Doğduğun her günden beri umuda tutundun

Hoşgelmişin dünyamıza

İyiki buyurmuşun yürek soframıza

Al benden de bir demet gül avuçlarına

Sen iyiki doğdun

Bir güneş misali yüreğimize doldun

Neylenir ki artık sensiz bir şiir mısrası

Hoş merhabanla yanağımıza tatlı bir buse gamzelerimize kondurdun

Sen, güzel ve narin çiçek, iyiki doğdun.', 'Sen doğdun Bir haziran sonunda kundağa kondun Gülücük saçtın Bir bahar bahçesinden yayılan o hoş kokuyu gönüllere bıraktın Sen bugün doğdun ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-dogdun-narin-inci-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha dün gibi', 'daha-dun-gibi-i-lhan-koruyucu-ucax4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'DAHA DÜN GİBİ

                                   Sevgilinin kolarında oluşum.

                             Kalbimin sevgin ile doluşum,

                             Seni ilk öpüşüm koklayışım.

                             Ve sana öylesine alışmışım ki! 

                             Daha dün gibi.

                             Sere serpe çayırlara uzanışım.

                             O sarı gülü elime alıp koklayaşım,

                             Alev, alev ipek şaçlarına dokunuşum.

                             Unutamam  ki melekten güzel yüzünü.

                             Daha dün gibi.

                                              

                             Aşık olmam derdim, doğru mu söyledim.? 

                            Ben niçin böyleyim, hissederim için için,

                            Kaybetmişim ıssız bir obada kendimi niçin? 

                            Her anım  güneşim  sevgili, sevgili yarim.

                            Daha dün gibi, ama sen bugündesin.! 

                                                                         İlhan KORUYUCU', 'DAHA DÜN GİBİ                                    Sevgilinin kolarında oluşum.                              Kalbimin sevgin ile doluşum,     ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/daha-dun-gibi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşım', 'arkadasim-emine-sonmez-k9v95', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben kelebek olsaydım,çiçekler arkadaşım,

Hayat sırdaşım benim,gerçekler arkadaşım,

Bu günler gelir,geçer gam çekme arkadaşım,

Ben bir güle aşığım, tabiat arkadaşım.

Benim sevda çiçeğim, solsa da yine açar,

Vefasız sevgililer, bir görünür, bir kaçar,

Gurbet ellerde yalnız gezsem de böyle naçar,

Sevip sevilmek güzel, sen de tat arkadaşım.

Suyun çağlayışını, yüreğimde duyarım,

Sılayı özlesem de, gurbet benim diyarım,

Gurbet bana uymazsa, ben gurbete uyarım,

Böyle gelip geçecek bu hayat, arkadaşım.

Dünyâ cennete benzer, sevdalar çiçek gibi,

Hep seni diliyorum, tanrıdan dilek gibi,

Bu sefer de sen vurma şu zalim felek gibi,

Hasretinden çıkıyor bu feryat, arkadaşım.

Bir zaman, ben de kırda koşardım, deli gibi,

Yar  kokusu  gelirdi  baharın  gülü  gibi,

Aramıza  girdiler,  kara  bir  çalı  gibi,

Biz gibi gariplere, yok murat, arkadaşım.

Düşlerimde yaşarsın, gonca gülüm, kanaryam,

Senden ayrı kaldıkça durmadan kanar yaram,

Tabip derman bulamaz, yar elindeymiş çarem,

Benden geçti bu hayat, kaldır at, arkadaşım.

Ele nasihat verir tutamazsın sözünü,

Felek kara yazmışsa, silemezsin yazını,

Hasretten açık kalır, kapatırlar gözünü,

Kendi özüne geçmez nasihat, arkadaşım.', 'Ben kelebek olsaydım,çiçekler arkadaşım, Hayat sırdaşım benim,gerçekler arkadaşım, Bu günler gelir,geçer gam çekme arkadaşım, Ben bir güle a...', ARRAY['Türk Edebiyatı','Şiir','Emine Sönmez']::text[], 8.5, '{"poet":"Emine Sönmez","poet_slug":"emine-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/arkadasim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ten Tene Bulandı', 'ten-tene-bulandi-hikmet-karakus-93rob', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ı

sesin titrek

avuçlarıma düştüğünde gözyaşların

eridim sanki yüreğinde

hece hece

ten tene bulandı

gözlerinde şafak

ellerinde ellerim

sen güne 

ben aşka yetim

ıı

ömrümün zulasında

bir sır gibi

aradım hep seni

buldum..

sevdim

yüreğine bıraktığım sevda ateşi

artık sana teslim

aşkla bak ona 

bak da 

sönmesin karartma gecelerinde

döner dururum yana yana

sana...

Kartal / Haziran 2005', 'ı sesin titrek avuçlarıma düştüğünde gözyaşların eridim sanki yüreğinde hece hece ten tene bulandı gözlerinde şafak ellerinde ellerim sen gü...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Karakuş']::text[], 8.5, '{"poet":"Hikmet Karakuş","poet_slug":"hikmet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ten-tene-bulandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakışır', 'yakisir-i-lhan-koruyucu-raj9t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kadın kolunda çiçek sepeti

Ekmeğini kazanmak için çabalıyor,

Belli ki belkide sevgi satıyor bilmeden

Geziyor, dolaşıyor baştan başa sokakları

Bağırmadan, gülümseyerek sevgili arıyor,

Satabilmek için bir gülü sevgiliye

Demet demet, buket buket bir dal gülü

Sadece diyor size yakışır, alır mısınız.? 

                       01.07.2001', 'Bir kadın kolunda çiçek sepeti Ekmeğini kazanmak için çabalıyor, Belli ki belkide sevgi satıyor bilmeden Geziyor, dolaşıyor baştan başa soka...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yakisir-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'E03 - Neden', 'e03-neden-tahir-gungor-bpmu2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaradan sen,

Beni yaratan sen,

Bu canı veren sen, 

Alacak olan da sen,

Akla takılıyor istemeden,

Madem geri alacaktın,

Bu canı vermen neden.

Bu can gidiciyse benden,

Nasıl çıkarsa çıksın bedenden,

Boşuna deirenmek neden,

Belki sırayı bilmemekten,

İnatsa, bu inadı veren sen,

Bir terslik varsa bu fikirden,

Bu aklı fikri veren de sen.', 'Yaradan sen, Beni yaratan sen, Bu canı veren sen,  Alacak olan da sen, Akla takılıyor istemeden, Madem geri alacaktın, Bu canı vermen neden....', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/e03-neden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yudumluyorum', 'seni-yudumluyorum-ali-fikri-karadeniz-7t9bn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yorgunum; 

Hemde çok yorgun.

Masamın üzerinde rakım

Düştüm, düşüyorum,

Ve kadehimde yine Sen

Seni yudumluyorum...

Yüreğim alev alev,

Gözlerimde bitmeyen yağmurlar var,

Dağlar devriliyor üzerime,

Hasret denizinde boğuluyorum; 

Seni yudumluyorum...

Kalbimi çıkarttım ve astım,

Karaya boyanmış gök yüzüne.

Adını yazdığım yıldızlarım,

Bir bir dolar Da çevreme,

Ve Sen kutup yıldızım,

Gölgen düşer kadehime,

Acılar yüreğime,

Lanet olsun, Seni çok seviyorum,

Ve ben; 

Her gece Seni yudumluyorum....!', 'Yorgunum;  Hemde çok yorgun. Masamın üzerinde rakım Düştüm, düşüyorum, Ve kadehimde yine Sen Seni yudumluyorum... Yüreğim alev alev, Gözleri...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-yudumluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mantinuta', 'mantinuta-asima-azra-pia1u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mile çapa atınca o camgüzeli

Ardında düşlerinin gölgesi kaldı…

Nezih sofraların zevk tadımıyken

Tabakta bırakılmış gözyaşı kaldı…

İlk ışıklar şafakla ipten dönerken

Nice karanlıklarda asılı kaldı

Utancı uykusunun celladı iken….

Tüm günahlarının zarfı kapandı

Azrail’i salonda bekletiyorken…

***Mantinuta: Kapatma', 'Mile çapa atınca o camgüzeli Ardında düşlerinin gölgesi kaldı… Nezih sofraların zevk tadımıyken Tabakta bırakılmış gözyaşı kaldı… İlk ışıkla...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/9830-9830-mantinuta-9830-9830-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'E04 - Ne Oluyor', 'e04-ne-oluyor-tahir-gungor-e3tu3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başım ağır ağır apansız,

Ellerim kıruk, kollarım dermansız,

Bir sıkıntı ki, amansız, zamansız,

Solumda birşeyler kıpır kıpır,

Derinden derine AĞRI gibi.

Boğuluyorum, sesim boğuk boğuk,

gözlerim donuki yüzüm soluk,

Alnımda terler soğuk soğuk,

Göğsüm de yanıyor, yanıyor,

Yanardağın BAĞRI gibi.

Sanki gök karardı, yer toz duman,

Rüzgar, fırtına, yağmur ve tufan, 

Bu ne karmaşa gümbürtü aman,

Kulaklarım da uğul uğul,

Kıyamete ÇAĞRI gibi.', 'Başım ağır ağır apansız, Ellerim kıruk, kollarım dermansız, Bir sıkıntı ki, amansız, zamansız, Solumda birşeyler kıpır kıpır, Derinden derin...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/e04-ne-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'E05 - Burada', 'e05-burada-tahir-gungor-hzean', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sessizi hakim, şarkınn, türkünün,

Eseri yok çekinmenin korkunun,

Gereği de yok, dayının, arkanın,

.......................................... B u r a d a.

Ne iş derdi, ne harman, ne de ekin,

Sorunlar halledilmiş de topyekun,

Sarmış ortalığı ulvi bir sükun,

.......................................... B u r a d a.

Büyük ve küçük herkes çok saygılı,

Kimse, ne dün, ne bugünden kaygılı,

Hava çok esrarlı, çok da duygulu,

.......................................... B u r a d a.

Aldıran yok, o veya bu farka,

Ne kürk kavgası var ne de hırka,

İtibar yok üçbeşe, otuza kırka,

.......................................... B u r a d a.

Ne kuşam derdi, ne gegeçim tasası,

Bu kimin kanunu, neyin yasası,

Nedir bilmem, işin aslı esası,

.......................................... B u r a d a.

Yol, ister yakın olsun ister ırak,

İstersen servet ve sevenler bırak,

Gerçek şu ki, herkes için son durak,

.......................................... B u r a d a.', 'Sessizi hakim, şarkınn, türkünün, Eseri yok çekinmenin korkunun, Gereği de yok, dayının, arkanın, .............................................', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/e05-burada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doktor', 'doktor-turan-civelek-dp2un', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vurdum gönül sazıma 

Belki yürek sızıma 

Sevda denen acıma 

Bir merhem sür ey doktor. 

Kitap yazmaz derdimi 

Gel sen bul bi çaremi 

Kimse bilmez yaremi 

Sen kanattın ey doktor. 

Yarın doğmaz günümü 

Kalpte açan gülümü 

Solmuş, garip yüzümü 

Gel sen güldür ey doktor 

Umut tütmez hanemi 

Sevda denen çaremi 

Kalpte yanan haremi 

Gel sen söndür ey doktor. 

Yare buldun yareni 

Bulup geldin çaremi 

Bu sevdanın kalemi 

Durma yaz sen ey doktor.', 'Vurdum gönül sazıma  Belki yürek sızıma  Sevda denen acıma  Bir merhem sür ey doktor.  Kitap yazmaz derdimi  Gel sen bul bi çaremi  Kimse bi...', ARRAY['Türk Edebiyatı','Şiir','Turan Civelek']::text[], 8.5, '{"poet":"Turan Civelek","poet_slug":"turan-civelek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/doktor-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haçlı zihniyeti bitmedi', 'hacli-zihniyeti-bitmedi-muzaffer-uzunkaya-jx9q6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün haçlı ordularıyla saldırmışlardı dört bir yandan,

Her geri püskürtülmesiyle yeni destanlar yazdık,

Başaramadılar Anadolu''yu işgal etmeyi savaşlarla,

Türk''ün ne olduğunu anladılar,ama vazgeçmediler.

Yeniden saldırdılar her seferinde başka yöntemlerle,

En son Türk''ün gücünü nereden aldığını anladılar,

Bunu yok etmeye çalıştılar ve çalışmaktalar,

İslamla aramızı ayırmaktır hedefleri ama yanıldılar.

Esasen tek hedefleri vardır onların Tarih boyunca,

Hangi silahlarla gelseler yine yatacaklar boylu boyunca,

Anadolu Türk''ündür sonsuza kadar,

Onu bizden alamayacak hiçbir güç.

26.05.2005-Bulancak-GİRESUN', 'Dün haçlı ordularıyla saldırmışlardı dört bir yandan, Her geri püskürtülmesiyle yeni destanlar yazdık, Başaramadılar Anadolu''yu işgal etmeyi...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Uzunkaya']::text[], 8.5, '{"poet":"Muzaffer Uzunkaya","poet_slug":"muzaffer-uzunkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hacli-zihniyeti-bitmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek müslüman olsaydık eğer', 'gercek-musluman-olsaydik-eger-muzaffer-uzunkaya-5pcz4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gerçek müslüman olsaydık eğer geri kalmazdık,

Gerçek müslüman olsaydık eğer borç almazdık,

Gerçek müslüman olsaydık eğer perişan olmazdık,

Gerçek müslüman olsaydık eğer yalancı olmazdık.

Gerçek müslüman olsaydık eğer düşmanlarımıza kanmazdık,

Gerçek müslüman olsaydık eğer onlara inanmazdık,

Gerçek müslüman olsaydık eğer güçlü olurduk,

Gerçek müslüman olsaydık eğer çalışkan olurduk.

Gerçek müslüman olsaydık eğer üstün olurduk,

Gerçek müslüman olsaydık eğer adil olurduk,

Gerçek müslüman olsaydık eğer dünyayı biz yönetirdik,

Eğer inanmayan varsa Türk Tarihini okusun.

Gerçek müslüman olsaydık eğer İMF''ye bu kadar borçlanmazdık,

Gerçek müslüman olsaydık eğer fakir kalmazdık,

Gerçek müslüman olsaydık eğer kimseye boyun eğmezdik,

Gerçek müslüman olsaydık eğer cahil kalmazdık.

11.06.2005-Bulancak-GİRESUN', 'Gerçek müslüman olsaydık eğer geri kalmazdık, Gerçek müslüman olsaydık eğer borç almazdık, Gerçek müslüman olsaydık eğer perişan olmazdık, G...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Uzunkaya']::text[], 8.5, '{"poet":"Muzaffer Uzunkaya","poet_slug":"muzaffer-uzunkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gercek-musluman-olsaydik-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Yanmasa Suya', 'can-yanmasa-suya-turan-civelek-ht9w5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Can yanmasa suya 

Su kendini bilmezdi! 

Can cananı arar da 

Hastalanır ölmezdi! 

Bir garip gönlün o, 

O şahına vermezdi! 

Leyla’ya Mecnun kalbi 

Dar mı gelirdi hiç... 

Can yanmasa suya 

Mecnun Leyla demezdi! ! !', 'Can yanmasa suya  Su kendini bilmezdi!  Can cananı arar da  Hastalanır ölmezdi!  Bir garip gönlün o,  O şahına vermezdi!  Leyla’ya Mecnun ka...', ARRAY['Türk Edebiyatı','Şiir','Turan Civelek']::text[], 8.5, '{"poet":"Turan Civelek","poet_slug":"turan-civelek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/can-yanmasa-suya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elifim', 'elifim-ali-fikri-karadeniz-1n46o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben seni tanıdığım gün,

Hayat doluydu gözlerin.

Gülünce gamzeler dolardı yüzüne

Güller yeniden açar; 

Ve güvercinler havalanırdı gök yüzüne...

''Sıcaklığını bu güneşten aldı'' derdim

Sözlerini Mevlana''dan,

Sevecenliğini Yaradan''dan,

Sen başkaydın inan bana inan...

Biliyor musun? 

Hayatı sevmedim hiç,

Menfaat dünyası ya bu dünya; 

En karamsar anımda,

Seni tanıdım,

Ve yaşama yeniden bağlandım...

Sendin sebep,

Sendin insan değeri,

İyi ki tanıdım be Seni,

İyi ki yanında çalıştım.

Hani derler ya; 

Öğreneceğim çok şeyler var

Ben Sende hayatın baharını; 

Ve solmayacak anılar yaşadım...

Hani bizden ayrıldığın gün var ya; 

Sana bir şiir yazmıştım

Duydum ki okuyunca ağlamışsın

Yüreğim buruktu,

Gözler öylesine bulut doluydu...

Acı haber tez duyulurmuş

Kızıl saçlarında 

Gün doğardı bakışlarında

Duydum inanamadım

Elif''im

Benim bahtı kara kardeşim

Nasıl kıydın o canına? 

Dünyayı karartmışlar, bir kutuya koymuşlar,

Hani nasıl desem? 

Yüreğime bombalar yağdırmışlar,

Seni hangi dipsiz kuyuya atmışlar? 

Nasıl dayanacak yürek 

Elif''im; 

Benim bahtı kara kardeşim...

Keşke Seni tanımamış olsaydım,

Canımdan can aldın, damarımdan kan

Kara toprak beni alsaydı; 

And olsun verirdim inan

Elif''im; 

Benim bahtı kara kardeşim...

Sanma ki gittin her şey bitti! 

Sanma ki bütün dertler tükendi

Geride; 

Geride adına ağıtlar yaktım

Ciğerimi dağladım, yüreğimi kanattım

Elif''im; 

Benim bahtı kara kardeşim...

Şimdi hangi yıldızlardan bakıyorsun? 

Yattığın yer kardeşim; 

Cennet mekanın olsun

Ahhh... Bu acıya nasıl, nasıl dayanacak yüreğim? 

Dua''lar kalbimden

Bekle beni, sırası geldiğinde geleceğim...!', 'Ben seni tanıdığım gün, Hayat doluydu gözlerin. Gülünce gamzeler dolardı yüzüne Güller yeniden açar;  Ve güvercinler havalanırdı gök yüzüne....', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/elifim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak', 'uzak-meyus-cetin-667lh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzun olacak geceler 

Ayazlı, soğuk, yalnız

Uzak olacak senden

Ve tabi ki benden

Titrek bakışlarla ürkek

Titreyen bedenimle

Yorgunluğu bütün günün

Hücum edecek gözlerime

Sen belireceksin

Kalbimden gözüme

Ilık bir ürperme ile

Sevecen gülüşün bende

Vakti geldi artık

Bırakmanın ana ocağını

Seveceğim artık zorla

Asker ocağını.....', 'Uzun olacak geceler  Ayazlı, soğuk, yalnız Uzak olacak senden Ve tabi ki benden Titrek bakışlarla ürkek Titreyen bedenimle Yorgunluğu bütün ...', ARRAY['Türk Edebiyatı','Şiir','Meyus Çetin']::text[], 8.5, '{"poet":"Meyus Çetin","poet_slug":"meyus-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzak-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fani dünya', 'fani-dunya-muzaffer-uzunkaya-lpo2x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fani dünya,fani dünya,

Yalansın sen fani dünya,

Boş işlerle oyalayıp,

Ahireti unutturan dünya.

Sana geldiğimden beri,

Güldürmedin fani dünya,

Muradımı alamadan,

Beni benden alan dünya.

Genç yaşıma doyamadım,

Sevdiğimi alamadım,

Mutluluğu bulamadım,

Her şey bitti fani dünya.

Toprak oldu benim tenim,

Yok fazla gidip gelenim,

Üzerimde otlar bitti,

Duacım yokmu fani dünya.

Ahirette şikayetim var,

Suçum neydi hain canavar,

İki elim iki yakanda,

Yoktur adlin fani dünya.

Mizan terazi kurulunca,

Gerçek adalet sorulunca,

Hakkımı alacağım o gün,

Sen fanisin fani dünya.

12.06.2005-Bulancak-GİRESUN', 'Fani dünya,fani dünya, Yalansın sen fani dünya, Boş işlerle oyalayıp, Ahireti unutturan dünya. Sana geldiğimden beri, Güldürmedin fani dünya...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Uzunkaya']::text[], 8.5, '{"poet":"Muzaffer Uzunkaya","poet_slug":"muzaffer-uzunkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/fani-dunya-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Deyiş', 'son-deyis-turan-civelek-hfybg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugünlerin sondur, belki başıdır 

Geçtiğin son kapı yolun başıdır 

Hayat denen yolun bu son taşıdır, 

Yürü ey dost sen de, yollar karşında! ! 

Bekliyor seni o yar yolun başında.', 'Bugünlerin sondur, belki başıdır  Geçtiğin son kapı yolun başıdır  Hayat denen yolun bu son taşıdır,  Yürü ey dost sen de, yollar karşında! ...', ARRAY['Türk Edebiyatı','Şiir','Turan Civelek']::text[], 8.5, '{"poet":"Turan Civelek","poet_slug":"turan-civelek","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/son-deyis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gibi', 'gun-gibi-murat-arif-cahf4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herdem doguyorsun ufkuma,

Güneş ufkuma batıyor ufkuma,

Batıyor yalnızlık,

Yalnızlık sarı bir hastalık.', 'Herdem doguyorsun ufkuma, Güneş ufkuma batıyor ufkuma, Batıyor yalnızlık, Yalnızlık sarı bir hastalık....', ARRAY['Türk Edebiyatı','Şiir','Murat Arif']::text[], 8.5, '{"poet":"Murat Arif","poet_slug":"murat-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gun-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Ardından', 'senin-ardindan-yucel-karakilic-fzi4a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geri dönemezsin, gittin bir kere,

Ben öksüz çocuktum, senin ardından.

Trene, vapura, otobüslere,

Boynu bükük baktım, senin ardından.

Giderken beni de sanki götürdün,

Hayattam her türlü zevki götürdün,

Neşeyi, huzuru, şevki götürdün,

Yaşamaktan bıktım, senin ardından.

Hasretin sancısı ne zormuş meğer,

Mecnun''un çektiği derde eş değer,

Ellrerim havada dilim de Makber,

Ne ağıtlar yaktım, senin ardından.

Gözlerime cazip gelen her şeye,

Saldırdım teselli bulurum diye,

Şaşkın vücudumu bir meyhaneye,

Bir camiye yıktım, senin ardından.

Tiryaki olmuşum artık ismine,

Sayıklar dururum kendi kendime,

Seninle beraber giden beynime,

Son kurşunu sıktım, senin ardından.', 'Geri dönemezsin, gittin bir kere, Ben öksüz çocuktum, senin ardından. Trene, vapura, otobüslere, Boynu bükük baktım, senin ardından. Giderke...', ARRAY['Türk Edebiyatı','Şiir','Yücel Karakılıç']::text[], 8.5, '{"poet":"Yücel Karakılıç","poet_slug":"yucel-karakilic","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senin-ardindan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağabeyim', 'agabeyim-muzaffer-uzunkaya-wwaxo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağabeyim,canım ağabeyim,

İçim yanıyor ağabeyim,

Uçup gittin elimden,

Bir şey yapamadım ağabeyim.

Genç yaşta yitirdim seni,

Bu acı,bu hasret bitirdi beni,

Nasıl katlandım yokluğuna,

Seni unutamam sevgili ağabeyim.

Arkadaş uğruna can feda ettin,

Keşke gitmeseydin ağabey ne ettin,

Bizi garkettin derin acılara,

Düçar oldu gönlüm çekilmez sancılara.

Yıllarca dolaştım deli divane gibi,

Ummana düşmüş dal parçası gibi,

Sen de gözümden kayboldun yıldız düşer gibi,

Kolum kanadım kırıldı can verir gibi.

Gönlüm katılaştı sen gittikten sonra,

Arkadaşım olmadı sen bittikkten sonra,

Yaş geldi,ömür bitti,bak senden sonra,

Nasıl yaşadım bunca yılı ben senden sonra.

İçim yanıyor hala,gözümde hep sen,

Nasıl kahroluyorum inan bir bilsen,

Tekrar uçarcasına yanıma gelebilsen,

Dünyalar benim olurdu canım ağabeyim.

12.06.2005-Bulancak-GİRESUN', 'Ağabeyim,canım ağabeyim, İçim yanıyor ağabeyim, Uçup gittin elimden, Bir şey yapamadım ağabeyim. Genç yaşta yitirdim seni, Bu acı,bu hasret ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Uzunkaya']::text[], 8.5, '{"poet":"Muzaffer Uzunkaya","poet_slug":"muzaffer-uzunkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/agabeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğun Resmi', 'mutlulugun-resmi-ufuk-coban-ej4gn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutluluğun resmini çiz bugün hasretin rüzgarında,

Biraz yürek, biraz gülüş koy en güzel köşesine,

Biraz benden, biraz senden çiz sevdayı anlatan,

Silinmesin aşkımız derin çiz resmi kalbine.

Akşamın karanlığını resmine koy yalnızlıkla,

Bizden başka kimse gözükmesin gözlerinde,

Bir kağıda sığdırabilirsen bir yuva koy,

Hayalinde bile olmayan binbir güzellikte.

Bugün beni ısıt yüreğinde beyazın soğukluğunda,

Bir hayal tut elinde gerçekleşir diye,

Umudunu hiç yitirme bırakma geleceğini gözyaşına

Bir resim çiz bugün, içinde mutluluk olsun.

02/02/2005', 'Mutluluğun resmini çiz bugün hasretin rüzgarında, Biraz yürek, biraz gülüş koy en güzel köşesine, Biraz benden, biraz senden çiz sevdayı anl...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mutlulugun-resmi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur içinde yat ağabeyim', 'huzur-icinde-yat-agabeyim-muzaffer-uzunkaya-0vk81', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gece yarısı irkilerek uyandım,

Silah sesleriyle sanki ben yandım,

Canım bedenimden ayrıldı sandım,

Ter içinde kaldı bütün bedenim,

Kara haber çok geçmeden duyuldu,

Dediler ağabeyin yeni vuruldu,

Hastanede son demlerini yaşıyor,

Son kez görmek istermisiniz? .

Ben şok oldum habere sanki oldum taş,

Elim ayağım kurudu inanki gardaş,

Haberci dedi Muammer öldü hüküm ALLAH''ın,

Bol sabırlar ihsan eylesin ALLAH''ım.

Dün yaşayan ağabeyim yatıyor cansız,

Dünya ile işi kalmamış,şimdi heyecansız,

Gül yüzü sararmış,ölüm gelmiş apansız,

Nasıl kıydın ağabeyime,nasıl be kansız.

Gözyaşları içinde yatırdım kara toprağa,

Mevlam böyle acı vermesin kimseye bir daha,

Ama ölüm var dünyada,kurtuluş yok,

 '' Her can ölümü tadıcıdır '' demiş yaradan.

O gün bu gündür ben kendime gelemedim,

Yıllarca içim yandı,yanıyor hala,

Kimse güvenmesin demesin ağayım,beyim,

ALLAH günahını affetsin,huzur içinde yat ağabeyim.

12.06.2005-Bulancak-GİRESUN', 'Bir gece yarısı irkilerek uyandım, Silah sesleriyle sanki ben yandım, Canım bedenimden ayrıldı sandım, Ter içinde kaldı bütün bedenim, Kara ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Uzunkaya']::text[], 8.5, '{"poet":"Muzaffer Uzunkaya","poet_slug":"muzaffer-uzunkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/huzur-icinde-yat-agabeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryat', 'feryat-yucel-karakilic-9akxh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerden başlasam, nasıl anlatsam? 

Hasretin bir türlü dile gelmiyor.

Dinlesen de usul usul anlatsam,

Gururun şahlanmış ele gelmiyor.

Bir kere yanmışım aşkın narına,

Çıkmam bile meçhul böyle yarına,

Bedenim ölümle burun buruna,

Senden daha öte çile gelmiyor.

Unuturum diye boşuna umma,

Aşk geçer deseler sakın inanma,

Belki kavuşmamız imkansız amma,

Seni terkedesim bile gelmiyor.

Seven hoş görüyle kini yenerdi,

Kahrolası şansı son kez denerdi,

Dönseydi Mecnun''a Leyla dönerdi,

Yar geriye, feryat ile gelmiyor.', 'Nerden başlasam, nasıl anlatsam?  Hasretin bir türlü dile gelmiyor. Dinlesen de usul usul anlatsam, Gururun şahlanmış ele gelmiyor. Bir kere...', ARRAY['Türk Edebiyatı','Şiir','Yücel Karakılıç']::text[], 8.5, '{"poet":"Yücel Karakılıç","poet_slug":"yucel-karakilic","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/feryat-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabirler', 'kabirler-muzaffer-uzunkaya-vk61p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bayram günlerinde ziyaret edilen,

Garip garip bekleşirler kabirler,

Bir fatiha yokmu diye ağlarlar,

Dünya ile işi bitmiş kabirler.

Kimi mermer ile yapılmış taşları,

Kimi düzlenmiş toprağı belli olmaz başları,

Kiminin kabrini bulamaz dostları,arkadaşları,

Farklı farklı görünür hep kabirler.

Onlar da bir vakit yaşadı bu fanide,

Kimi gün acı çekti,kimi gün güldü,

Hayat müddetleri bittiği zaman,

Hak''kın emri gelip can vererek öldü.

Peşinden ağladı ana,baba,kız,oğul, 

Kabre bıraktılar ağlayarak onları,

Çabuk unuttular hemen olanları,

Bizlere ibrettir hep kabirler.

12.06.2005-Bulancak-GİRESUN', 'Bayram günlerinde ziyaret edilen, Garip garip bekleşirler kabirler, Bir fatiha yokmu diye ağlarlar, Dünya ile işi bitmiş kabirler. Kimi merm...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Uzunkaya']::text[], 8.5, '{"poet":"Muzaffer Uzunkaya","poet_slug":"muzaffer-uzunkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kabirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-adnan-gordum-tp0xp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninle biz,

İkimiz,

Mutluluğu hiç bilmeyiz.

Sanki birbirimize 

Uzaktan bakmaya,

Gizlice söz vermişiz.

Hep iç çekmişiz,

Sevmişiz,

Belli etmemişiz..', 'Seninle biz, İkimiz, Mutluluğu hiç bilmeyiz. Sanki birbirimize  Uzaktan bakmaya, Gizlice söz vermişiz. Hep iç çekmişiz, Sevmişiz, Belli etme...', ARRAY['Türk Edebiyatı','Şiir','Adnan Gördüm']::text[], 8.5, '{"poet":"Adnan Gördüm","poet_slug":"adnan-gordum","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/biz-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hendese', 'hendese-kader-sevinc-ltnny', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I  

                     Gün içinin patikasında yol alırken

                     ibriklerden sızan düşgelimlerdir kuşatan toprağını

.                     Güneşin sustuğu yere gidelim,

                      gölge oyunlarını  güvez rengi  bir fular gibi 

                      yele verdiği tek anına ömrümüzün.

                

              II

                      Seirenlerin şarkılarını duyduğun gün,

                      seslerimin dağınıklığı bulacak yerlerini.

                    

             III

                      Özüme varmak için; 

                      En şaraplı yüzünü der bahçenin,

                      çoğalt içindeki ıssızlığı.                      

                      Zeytin dallarının şavkıyla dolmuş benliğimi 

                      anlamaya çalışma şimdi,

                      uzakları düşünme.

             IV

                      Afrodit de Hephaistos''u sevmişti, 

                      Ares''in rüzgarıyla kavillerini unutuverdi...

                      Geleceksen  düne miras bırak kavilleri. 

                      Yolumuzdaki en büyük tuzak

                      bilemememizdir küllerimizi alevlendirecek

                      rüzgarların hendesesini. 

                      Azlolunmuş delişmen burağanlarımı bana bırak.

           2002/..', 'I                        Gün içinin patikasında yol alırken                      ibriklerden sızan düşgelimlerdir kuşatan toprağını .       ...', ARRAY['Türk Edebiyatı','Şiir','Kader Sevinç']::text[], 8.5, '{"poet":"Kader Sevinç","poet_slug":"kader-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hendese-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen-1', 'sen-1-suleyman-yavuz-u9c18', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen hayaldin

Bazen düş

Hep aşkıma oldun

Aşılmaz bir bent

Çıkılmaz bir yokuş

Bazen gecemdin

Bazen gündüzüm

Ama hep yalnızdım

Hayalin karşımda 

Sen hiç yoktun ki yanım da

Bazen gülüşümdün

Bazen göze yaşım

Ne zaman eğilse 

O yıkılmaz 

Düşmez başım

Hep sen gelirdin aklıma

Ama sen hiç güldürmedin beni

Hep eğdirdin o yüzümü

Zaten sen hiç

Sevmedin ki

Avuttun şu garip gönlümü', 'Bazen hayaldin Bazen düş Hep aşkıma oldun Aşılmaz bir bent Çıkılmaz bir yokuş Bazen gecemdin Bazen gündüzüm Ama hep yalnızdım Hayalin karşım...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-1-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuturmuyum Seni', 'unuturmuyum-seni-suleyman-yavuz-qq2nv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaybettin beni

Yıktın bir anda

Tüm hayallerimi

Kararttın dünyamı

Kırdın kalbimi

Severken seni

Bırakıp ta gittin beni

Sildim desem de seni

O kırık kalpten seni

Unutulmuyorsun

Sen değil kalbimde

Damarda kanımda

Vücudumun her bir yerinde

Hücrelerimdesin

Unutmak için seni

Gelse bile ölüm

İnan bana gülüm

Toprağa karışıp 

Bir kır çiçeği gibi

Açıp yinede yaşatırım seni 

Sen ne kadarda sevmesen de  beni', 'Kaybettin beni Yıktın bir anda Tüm hayallerimi Kararttın dünyamı Kırdın kalbimi Severken seni Bırakıp ta gittin beni Sildim desem de seni O ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/unuturmuyum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma Beni', 'sorma-beni-muammer-oz-vo84e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akşam güneş batarken, seyrettiğin yerdeyim.

Çok uzakta değilim, düşlediğin yerdeyim.

Açıp baksan kalbine, o bildiğin yerdeyim.

Bulmak için boşuna, kimseye sorma beni.

Sevgi dolu kalbinde, hissettiğin yerdeyim.

Sonbaharda yağmurlar, üstümüze yağardı.

Karakışta buzlardan, ayağımız kayardı.

Sen olunca yanımda, canım nasıl kaynardı.

Bulmak için boşuna, kimseye sorma beni.

Beni seven kalbinde, hissettiğin yerdeyim.

Baharları o güzel, çiçekleri severdik.

Yazları da sahilde,  ne de güzel gezerdik.

Sevgi açan kırlarda, biz nöbette beklerdik.

Bulmak için boşuna, kimseye sorma beni.

Aşkla dolu gönlünde, hissettiğin yerdeyim.

                                            (1995)', 'Akşam güneş batarken, seyrettiğin yerdeyim. Çok uzakta değilim, düşlediğin yerdeyim. Açıp baksan kalbine, o bildiğin yerdeyim. Bulmak için b...', ARRAY['Türk Edebiyatı','Şiir','Muammer Öz']::text[], 8.5, '{"poet":"Muammer Öz","poet_slug":"muammer-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sorma-beni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gri Aşk Olmaz', 'gri-ask-olmaz-zumrut-demirtas-0i7ah', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu akşam bir başka gri,

Ruhumu saran duygular,

Ya siyah olsa ya beyaz,

Beynimi yiyen kaygılar...

Siyah olsa üzülürüm,

Ağlarım, yüreğim yanar,

Beyaz olsa sevinirim,

Gönlümde çiçekler açar…

Ürkek ruhuma sığmayan,

Mutluluklar ve acılar,

Gri rengi tanımayan,

Kalbim şaşırır, bocalar…

Aşkın rengi gri olmaz,

Ya sev beni ya da sevme,

Siyah beyaza dost olmaz,

Kararsızsan bana gelme…', 'Bu akşam bir başka gri, Ruhumu saran duygular, Ya siyah olsa ya beyaz, Beynimi yiyen kaygılar... Siyah olsa üzülürüm, Ağlarım, yüreğim yanar...', ARRAY['Türk Edebiyatı','Şiir','Zümrüt Demirtaş']::text[], 8.5, '{"poet":"Zümrüt Demirtaş","poet_slug":"zumrut-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gri-ask-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalanmışım', 'sevdalanmisim-zulfikar-yapar-kaleli-n3dmp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çalışalım mutlu olsun Türkiye

Sevdalanmışız hey  sevdalıyım ben

Bir olalım huzur bulsun Türkiye

Sevdalanmışız hey  sevdalıyım ben

Allah bir,  Resul hak  diyelim önce

Dünyanın güzeli Türkiye bence

Zindanlarda çile dolduran gence

Sevdalanmışız hey  sevdalıyım ben

Uçurun hey! ! Zaman mı var törene? 

Bu uğurda canı veren verene

Güzel yurdum ananene, törene

Sevdalanmışız hey  sevdalıyım ben

Kaderimiz buymuş ağlama ana

Sevgimizi taşımışız zindana

Gece gündüz gözlediğim hakana

Sevdalanmışız hey  sevdalıyım ben

Gece biter ne kaldı ki sabaha

Gönlümüzü verdik Resulullah''a

Aleme nizamı veren Allah''a

Sevdalanmışız hey sevdalıyım ben

                                    1986', 'Çalışalım mutlu olsun Türkiye Sevdalanmışız hey  sevdalıyım ben Bir olalım huzur bulsun Türkiye Sevdalanmışız hey  sevdalıyım ben Allah bir,...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdalanmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebep Ne?', 'sebep-ne-zulfikar-yapar-kaleli-3wh0a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anında bürünüp muradı renge

Ersin diye, fırsat vermek nedendir? 

Milli ruh düşmanı şu pezevenge

Yorsun diye fırsat vermek nedendir? 

Bir kulak ver, dinle, gönül ağrımı

Özünde duy,  tâ yürekten çağrımı

Şu T.V.ler hançer gibi bağrımı

Yarsın diye fırsat vermek nedendir? 

Yalan, talan, vurgun ile kasayı

Doldur, ters yüz edip aciz yasayı

Hep emir aldığı malum U.S.A.yı

Sorsun diye fırsat vermek nedendir? 

Sıçan gibi yavaş yavaş kemirip

Sonra tırman diyor, dayanır mı ip? 

Milletin malını yiyip, semirip

Dursun diye fırsat vermek nedendir

Milleti ağlatmış, yadı güldürmüş

Bir koymamış, parça parça böldürmüş

Maziyi karartmış, ruhu öldürmüş

Vursun diye fırsat vermek nedendir? 

1991', 'Anında bürünüp muradı renge Ersin diye, fırsat vermek nedendir?  Milli ruh düşmanı şu pezevenge Yorsun diye fırsat vermek nedendir?  Bir kul...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sebep-ne-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B09 - Ol', 'b09-ol-tahir-gungor-k12yn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanımda yandaşım ol,

Kolumda koldaşım ol,

Yönü bir, yöntemi bir,

Yolumda yoldaşım ol.

Yazım ol, kışım ol,

Uykum ol düşüm ol,

Sabahı bir akşamı bir,

Neşem ol coşum  ol.

Dağımdaağdaşım ol, 

Bağımda bağdaşım ol,

Yaşamı bir, kuşamı bir,

Çağımda çağdaşım ol.

Dolum ol boşum ol,

Kepçem ol kaşığım ol,

Acısı bir tatlısı bir,

Yavanyaşık aşım ol. 

Kardeş değil kandaşım ol,

Sözlüm değil, andaşım ol,

Havası bir, davası bir,

Cananım, candaşım ol.

Toprağım ol, taşım ol,

Görülecek işim ol,

Sevgi bir, saygı bir,

Aşkım ol, eşim ol.', 'Yanımda yandaşım ol, Kolumda koldaşım ol, Yönü bir, yöntemi bir, Yolumda yoldaşım ol. Yazım ol, kışım ol, Uykum ol düşüm ol, Sabahı bir akşa...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/b09-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canların Divanesiyim', 'canlarin-divanesiyim-zulfikar-yapar-kaleli-xc893', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Candan geçer ama geçmez vadinden

Kurulan canların divanesiyiz

Vatan acısıyla ta can evinden

Vurulan canların divanesiyiz 

Doğruyu konuşan tatlı dil gibi

Vatana sevdalı bir bülbül gibi

Hazan yeli vurmuş gonca gül gibi

Burulan canların divanesiyiz 

Hep vatanı sevdi hep gözünde ip

İpi çeken eli bile bilmeyip

Hücrelerde bin bir dilek dileyip

Yorulan canların divanesiyiz

Yetmez mi çekilen ayıp be ayıp? 

Bu ayıbı size yeterli sayıp

İslam''ın tevekkül emrine uyup

Durulan canların divanesiyiz

Yurt için,din için divane olup

Bunlar ile hamur gibi yoğrulup

Milleti sevmekten suçlu bulunup

Sorulan canların divanesiyiz 

                                                1986', 'Candan geçer ama geçmez vadinden Kurulan canların divanesiyiz Vatan acısıyla ta can evinden Vurulan canların divanesiyiz  Doğruyu konuşan ta...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/canlarin-divanesiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulur Mu?', 'unutulur-mu-zulfikar-yapar-kaleli-yswyj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu yusuf çehreli süleymanlara 

Ölürken gülenler utanmadılar. 

Çileli günlere, dertli anlara 

Seyirci kalanlar utanmadılar.

Ellerinden her geleni yapanlar 

Hakkı koyup haksızlığa sapanlar 

Lenin’''e, Mao’''ya, Marx’a tapanlar 

Vatanı bölenler utanmadılar.

Bu millete hasım kesilip dünden 

Mazluma dokunup on iki binden 

Lenin moskova’dan, mao pekinden 

Talimat alanlar utanmadılar.

Sanmayın unuttu, unutur, yazmaz 

Yurdu seven, ölüm kuyusu kazmaz 

İnsan olan dirlik düzeni bozmaz 

Şu kurşun salanlar utanmadılar.

                                   1976', 'Şu yusuf çehreli süleymanlara  Ölürken gülenler utanmadılar.  Çileli günlere, dertli anlara  Seyirci kalanlar utanmadılar. Ellerinden her ge...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/unutulur-mu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimeyen Sevda', 'eskimeyen-sevda-zulfikar-yapar-kaleli-01qdc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni hiç kimseyi sevmez sanmayın 

Ülkü denen ela gözlü yar benim 

Gülemiyor diye bana yanmayın 

Kafkaslarda hiç kalkmayan kar benim 

Türk''ü sever, milletimi överim 

Rahman bana gül demezse kaderim 

Ben Turan''ı Türklük için severim 

Anadolu milletime dar benim 

Dağı bilmem bayır demem aşarım 

Türk''e kement vuracağa şaşarım 

''Bir ölürüm bin dirilir yaşarım '' 

Turan diye yüce ülküm var benim 

Gün gelir Buhara, Türkistan''da şen 

Bülbül olur şakıyarak ötüşen 

Kaleli der: Türkili''nde yetişen 

Ağaç benim yaprak benim nar benim 

1978', 'Beni hiç kimseyi sevmez sanmayın  Ülkü denen ela gözlü yar benim  Gülemiyor diye bana yanmayın  Kafkaslarda hiç kalkmayan kar benim  Türk''ü ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/eskimeyen-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoyratlar', 'hoyratlar-zulfikar-yapar-kaleli-8ac4u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Zaman geçer yaş akar 

Gökler ağlar yaş akar 

Yurdumda yurttaşımın 

Yüreğine yaş akar. 

Er olsa başa değse 

Kirpikler kaşa değse 

Kalbinizi yoklayın 

Ayaklar taşa değse. 

Coşunca Çoruh Gediz 

Atiye kalır mı iz? 

İki yirmiden yeğse 

İşin suçlusu biziz. 

Başa bela düşünce 

Alır beni düşünce 

Dostluklar belli olur 

Vardan dara düşünce.', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Zaman geçer yaş akar  Gökler ağlar yaş akar  Yurdumda yurttaşımın  Yüreğine yaş akar.  Er...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hoyratlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetişemedim', 'yetisemedim-zulfikar-yapar-kaleli-g7y5t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne diyeyim, ne söyleyim ben sana, 

Rahat, huzur kaçtı, yetişemedim. 

Dakikalar sene geliyor bana, 

Ay geçti, yıl geçti, yetişemedim. 

Bülbüllerin vardır zarı, sevdası, 

Herkesin erişmek elbet hevesi, 

Resul-ü Ekrem’in sünnet havası, 

Etrafa nur saçtı, yetişemedim. 

Kimse derdim anlamadı, sormadı, 

Selam saldım, nazlı yare varmadı, 

Hapis ettim, kafeslerde durmadı, 

Gönül kuşum uçtu, yetişemedim. 

Sevdam vardı, sevdalıydım ezelden, 

Sanma sakın geçerim bu güzelden, 

Bırakın sevdiğim gelsin tez elden, 

Başlardaki taçtı, yetişemedim. 

Yurdumun halayı, barı, köçeği, 

Kaleliyim çok aradım gerçeği, 

Huzur gölündeki sevda çiçeği, 

Ab-ı hayat saçtı, yetişemedim', 'Ne diyeyim, ne söyleyim ben sana,  Rahat, huzur kaçtı, yetişemedim.  Dakikalar sene geliyor bana,  Ay geçti, yıl geçti, yetişemedim.  Bülbül...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yetisemedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Bilincinin Tutsağısın Sen', 'kendi-bilincinin-tutsagisin-sen-melih-coskun-v65n0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerin kayıp

Ve durmadan titriyor dizlerin

Paltosu yamalı bir çocuk üşüyor

Yüreğinin saçaklarında  

Yanı başındaki serinlik 

Yalancı bir dünyanın sahte esintisi

Kollarına bağlı değil o ipler 

O ipler beynindedir artık senin

Kayıp yüzleriyle 

Bakıyorlar yüzüne 

Yüksek binaların tek yüzü karanlık pencerelerinden. 

Sen onları göremesen de

Kitapları, şifreleri

Ve ordularıyla

Hizaya sokuyorlar 

İtaatkar bedenini.

Yüzün silik

Yüzün kayıp ilanlarının ezik çehresi 

Işıksız bir bahçede yeşili aramak gibi 

Tanıyamıyor artık seni 

En sevdiklerin bile 

Adına kader dedikleri bu dayatma 

Doğmadan adı konmuş bir çocuk gibidir artık

Ve düşünmek 

Değiştirmeyecektir gideni ve gelmekte olanı 

Kollarında değil asıl o paslı zincirler 

Beyninin her hücresinde hapis yatan 

Binlerce tutsak

Dünyanın en özgür insanlarıdır aslında 

Düşündüğünü yaşar insan nerede olursa olsun

Düşündüğü kadar aşıktır

Ve düşündüğü kadar asi

Kimse kapatmadı seni 

Bu karanlık hücreye 

Kendi bilincinin tutsağısın yani sen 

Kendin kardın harcını

O güneş geçirmeyen duvarların 

Kollarına bağlı o ipler, 

Kendi ellerinin emeği 

Çeliğini bile kendi ellerinle soğuttuğun 

Bedenini paramparça eden silah. 

Kendi ellerinde 

Büyüttüğün bir canavardır artık 

O esaret denilen 

Ve yine 

Kendi marifetli ellerinle 

Yok edilecek olan...', 'Ellerin kayıp Ve durmadan titriyor dizlerin Paltosu yamalı bir çocuk üşüyor Yüreğinin saçaklarında   Yanı başındaki serinlik  Yalancı bir dü...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/kendi-bilincinin-tutsagisin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B10 - Geç Değil', 'b10-gec-degil-tahir-gungor-pjf6y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evet, saçlarımız kır, şakaklarımız ak,

Yüzümüze şöyle dikkatli bir bak,

Yaşam hırsımızı gör, sen de ver hak,

...........................El ele engel tanımaz aşarız,

...........................Kalan günleri hep çifter yaşarız.

Aklar, ak süs eder başımıza,

Seneleri us eder başımıza,

Terimizi tuz eder aşımıza,

...........................Biz de yaşamı tozpembe görürüz,

...........................Alnımız ak, başımız dik yürürüz. 

Sorulursa, karıkoca künyemiz,

Heves dolu kafamız, bünyemiz,

Sığsak, ceviz kabuğu dünyamız,

...........................İstemez ne han, ne hamam kapısı,

...........................Var sizin olsun dünyanın hepisi.', 'Evet, saçlarımız kır, şakaklarımız ak, Yüzümüze şöyle dikkatli bir bak, Yaşam hırsımızı gör, sen de ver hak, ...........................El e...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/b10-gec-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgamın Gerçeği...', 'kavgamin-gercegi-zulfikar-yapar-kaleli-8g8rs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birbiriyle barışır da nesneler

Dilimin sözüyle kavgası bitmez

Sana verdik dünya senin deseler

Yazgımın yazıyla kavgası bitmez 

Bana ''er'' dediler, ben eremedim

Aynaydı bu dünya, hiç göremedim

Ölmeden ölmeyi beceremedim

Yüreğin közüyle kavgası bitmez

Dertlerimi deryelera dökerim

Ağ atarım, yavaş yavaş çekerim

Ruhsuz yamaçlara tohum ekerim

Emeğin iziyle kavgası bitmez

Ölçüp hesapladım karış be karış

Kırk beş yıl savaştım gelmedi barış

Takıldım peşine yarış ha yarış

Acımın sızıyla kavgası bitmez

Kayalıktan hayır gelmez, bar olmaz

Pervasızda şükür olmaz ar olmaz

Anasına asi yavru, yar olmaz

Koyunun kuzuyla kavgası bitmez

Güneşler susamış su içiremem

Buluta bir kapı açıp giremem    

Beni dinletemem, söz geçiremem 

Özümün yüzüyle kavgası bitmez', 'Birbiriyle barışır da nesneler Dilimin sözüyle kavgası bitmez Sana verdik dünya senin deseler Yazgımın yazıyla kavgası bitmez  Bana ''er'' ded...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kavgamin-gercegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saran Sarana', 'saran-sarana-huseyin-sigirtmac-0fqbw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne edep, ne haya, bozuldu zaman.

Sarılıp can cana duran durana.

Hırsız suç bastırıp vermiyor aman.

Hak hukuk diyerek vuran vurana.

Kimi Paris’lerde eder kahvaltı.

Kimi paylaşamaz taç ile tahtı.

Varlığa bir dönmez yoksulun bahtı.

Anonim şirketler kuran kurana.

Hep Hak’ka yalvarmak oldu işimiz.

Mahşere bağladık hayal düşümüz.

Koskoca dünyaya sığmaz başımız.

Kiralık ev deyip soran sorana.

Açlık sınırında memur maaşı.

Fakülte bitiren pazarcı başı.

Bir Ata çıkıpta silmedi yaşı.

Her yerde birbirin yoran yorana.

Adaletin çarkı kim için döner.

Zalimin pençesi mazluma iner.

Sığırtmaç bu dertle ne canlar gider.

Genç yaşta toprağı saran sarana.', 'Ne edep, ne haya, bozuldu zaman. Sarılıp can cana duran durana. Hırsız suç bastırıp vermiyor aman. Hak hukuk diyerek vuran vurana. Kimi Pari...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/saran-sarana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusura Bakma', 'kusura-bakma-ahmet-kurt-tg5pg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söylenecek sözü, komam içimde,

Bu gidişte vebal almam gardaşım.

Süsleyip,sunamam başka biçimde,

Bu gidişte vebal almam gardaşım.

Özümden dönemem, yıkılsa cihan,

Değil beylik vermek, etseler de han,

Şu ana kadar hiç, olmadım pişman,

Bu gidişte vebal almam gardaşım.

Herkes cürmü kadar yüke yakışır,

Kimi zerre, kimi batmanlar taşır,

İster yollarda koy, ister dağ aşır,

Bu gidişte vebal almam gardaşım.

Kendime küsüp de, düşman olamam,

Nefsime yenilip, yolda kalamam,

Hiçlerin uğruna pişman olamam,

Bu gidişte vebal almam gardaşım.

Kurdoğlu ki Hakkın hakkına vurgun,

Hükmeder kendine o yüzden durgun,

Bu hesapla bitkin, bununla yorgun,

Bu gidişte vebal almam gardaşım.', 'Söylenecek sözü, komam içimde, Bu gidişte vebal almam gardaşım. Süsleyip,sunamam başka biçimde, Bu gidişte vebal almam gardaşım. Özümden dön...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kusura-bakma-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Sevda', 'oyle-bir-sevda-sahin-yenilmez-5u9fq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlığına sakladığım bu düş

Gerisi kalmayacak yaşantımın

Geleceği de,

Hançerler saplanıyor her gece umutlara

İnsan avcıları dolaşıyor bu şehirde

Ve ben 

Kimse görmeden

Çekip gidiyorum bilinmez uçurumlara.

Acısını gizlediğim sevdalarım

Birer tebessüm oldu çocukların gözünde

Her gülüşlerinde

Yeni sevdalar yetişecek küçücük yüreklerinde.

Sahipsiz değil hiçbir ümit ama

İnsanlar kendi geleceklerinden kaçar oldu

Korkar oldu kendi ümitlerinden

Bir bilinmezliğe doğru gidiyoruz

Sonumuz nasıl olur bilinmez.

Geleceğe pervane gerip 

Uçuruyorum bütün ümitleri 

Bırakıyorum içine tüm iyi dileklerimi,

Öyle bir sevda bırakıyorum ki giderken

Kaldıramaz her yürek,

Her yağmur yağışında

Islanacak ve filiz verecek

Öyle bir sevda bırakıyorum ki giderken

Sevmesini bilen herkes

Bir gün mutlaka sevilecek..', 'Karanlığına sakladığım bu düş Gerisi kalmayacak yaşantımın Geleceği de, Hançerler saplanıyor her gece umutlara İnsan avcıları dolaşıyor bu ş...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/oyle-bir-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapısını Araladım Ölümün', 'kapisini-araladim-olumun-sahin-yenilmez-8u66f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sustukça çoğaldı karanlığım

Kaçtıkça büyüdü

Tam ortasındayım çizginin

Ölmek nedir ki kaçmaktan başka? 

Gölgelerden korkar oldum

Kendi yansımam kalmadı artık dünyada

Berbat bir şarap tadı gibi artık umutlar

Ve yüreğim yıllanmış ümitler mezarlığı gibi artık.

Çıkarı yok kaçışı yok yaşamanın

Sonuna kadar gitmek zorundasın..

Kapısını araladım ölümün

Gidemedim..

Sınırları sen çizemiyorsun

Kendi sınırlarının içinde özgürsün sadece

Gitmek istediğin her yere

Düşlerini gönderebilirsin sadece.

Sustukça çoğaldı karanlığım

Kaçtıkça büyüdü

Tam ortasındayım çizginin

Ölmek nedir ki kaçmaktan başka? 

Kapısını araladım ölümün

Kaçamadım..', 'Sustukça çoğaldı karanlığım Kaçtıkça büyüdü Tam ortasındayım çizginin Ölmek nedir ki kaçmaktan başka?  Gölgelerden korkar oldum Kendi yansım...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kapisini-araladim-olumun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçını Yol..', 'sacini-yol-veysel-alkan-spdyw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Savrul ve kaybol benim ahımla,

Acı çekip heder ol biten aşkımla

Saçını yol.!  ve hatanı anla zamanla,

Kaybettiğin sevdaya ben sahip çıktım.

Ne sana günyüzü var bundan sonra,

Ne de tutunduğun o anılara,

Saçını yol.! uykusuz var sabahlara,

Kaybettiğin sevdaya ben sahip çıktım.

Hasretimi doyunca tat ve yudumla,

Dalganı geçmiştin güya benimle,

Saçını yol.! sabrını yitir akşamla,

Kaybettiğin sevdaya ben sahip çıktım.

Kala kala elimde yokluğun kaldı,

Benim gönül aşktan yana payını aldı,

Anlamıştır herhal aşkın yalandı,

Kaybettiğin sevdaya ben sahip çıktım.

18/03/2002-İstanbul', 'Savrul ve kaybol benim ahımla, Acı çekip heder ol biten aşkımla Saçını yol.!  ve hatanı anla zamanla, Kaybettiğin sevdaya ben sahip çıktım. ...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sacini-yol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sapıtıyorum', 'sapitiyorum-suheyl-turkoglu-1q10o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlüm bir hoş,

İçim tuhaf,

Beynim sarhoş.

Kaçırma bakıişlarını,

Hırsızın oluyorum.

Sülük gibi,

Yapışasım geliyor,

Dudaklarına,

Manyaklaşıp,

Duruyorum.

Zındanlarda,

Zincirlenmiş,

Körolası duygular,

İstiyorum,

Kahrımdan ölüyorum.

Yasak aşk,

Arzu,

Ve sevgi,

Karabasan,

Boğuluyorum.', 'Gönlüm bir hoş, İçim tuhaf, Beynim sarhoş. Kaçırma bakıişlarını, Hırsızın oluyorum. Sülük gibi, Yapışasım geliyor, Dudaklarına, Manyaklaşıp,...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sapitiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş suya uyduğunda...', 'ates-suya-uydugunda-zafer-zengin-etnika-o1e51', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yaşımı almamışken

| bedeli nedir bilirsin |

son yokken

el kadardım

beden yüz güldüren

| neden küçük doğarız bilmem..fabrikasyon olsaydı..

kıçımıza şaplak yemeden

çözseydik hayatı ve küçülmeden irileşsek..

zorluklar hikaye gelse..değermiydi büyük doğsak..

büyülü ve ölümsüz olsak..sorgula neden kırmızı gül..

neden gri değil |

saçlarım sarı

gülüşüm az

dikensi duruşumla

oyun çatardım kendime

türküler söylerdim 

küçük yüreğimle

acı diyorsun 

çekilmiyor bilirim

tırnaklarımda kesik

etimde fazlalık

| mesela iç acısını kaç vinç kaldırır yürekten.. ne oynatır yerinden |

tarla süren kambur adam

ot ayıklayan kadın kadar

yakınsın akşama

desem ki ekin var

rüzgar gelir

yangın sarar

ciğerin yandığından beri

duman edersin

düşersin

is kalır elinde

canım; 

habersiz gidenlerden bıkmadım

yıldım özletenden

usandım

uslanmadım

bilir misin

giden gelmediğinden

ben hasrete alıştım

nasıl deme

başa gelsin gör

tufan dünkü çocuk yüreğimde

göz çanağı yaylada göl

ışıklar kesilir şimdi

hem kör dillerim

hem kekeme

can almak dokunmaz ölüme

sussunlar

sen adımı söyle

selam söyle gelmeyene

sayfam koptu

iki satırım kalmış okunmaya

kimi der dua

kimi der beddua

karışma sen

sarıl boynuma

ki en çok

ağlarken mutlu oldum

bu yüzden sabaha karşı doğdum



bizim orada

ekmek fırında kururdu

buharı soğuğa hapis

ciğerimize vurduğunda

su erken uyurdu

aşık çıkınca yakından

alnına sevda vuruldu

bir ben derim işte

ateş suya uydu

türkü yanmış dilimde

sus dinle

sus dinle

09.11.2004', 'yaşımı almamışken | bedeli nedir bilirsin | son yokken el kadardım beden yüz güldüren | neden küçük doğarız bilmem..fabrikasyon olsaydı.. kı...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/ates-suya-uydugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelliğin Tutkum Oldu', 'guzelligin-tutkum-oldu-suheyl-turkoglu-c99jl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cengaver sandım kendimi,

Ok attım,

Hani aşıklarda,

Kalbe saplanır ya,

Elim dolaştı,

Ayağıma,

Iskaladım.

Destana yatırdım,

Aşkımı,

Abarttım,

Kendimi,

Bulamadım.

Avazım kadar,

Sevdamı bağırdım,

Sağır oldum,

Yasaklarda,

Duyamadım.

Dengesizlik,

Dengem oldu,

Dokun bana,

İltifat et.

Güzelliğin tutkum oldu.', 'Cengaver sandım kendimi, Ok attım, Hani aşıklarda, Kalbe saplanır ya, Elim dolaştı, Ayağıma, Iskaladım. Destana yatırdım, Aşkımı, Abarttım, ...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/guzelligin-tutkum-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanındayken Ayrılık', 'yanindayken-ayrilik-zeki-akcali-zstnp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Zorlaştırma bu ayrılığı bana''

Deme ne olur.

Hayat zor...

İnsanlar zor...

Yaşamak zor...

Seni sevmek ise

En kolayıydı gözlerinde.

''Seni özledim...

Sesini, sohbetini...'' demiş

Derin bir sessizlikte boğulmuştun.

Sözler tıkanmış,

Yaşlar boşanmış,

Zaman sanki durmuştu bende

Elin kaçamak dokunuşlarla

Tenime dokunmak istercesine

Kolumdaki saatle oynarken.

Herkes gibi

Ben de mükemmel değilim.

Ne yazık...

Ne kadar zor yanındayken ayrılık.

(29/06/2005, Çarşamba, B.Çekmece)

(2. dönem)', '''Zorlaştırma bu ayrılığı bana'' Deme ne olur. Hayat zor... İnsanlar zor... Yaşamak zor... Seni sevmek ise En kolayıydı gözlerinde. ''Seni özle...', ARRAY['Türk Edebiyatı','Şiir','Zeki Akçalı']::text[], 8.5, '{"poet":"Zeki Akçalı","poet_slug":"zeki-akcali","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yanindayken-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-zeki-akcali-hb0rn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korkuyorum

Sende bu inat varken.

Sev desem yeniden

Sever misin? 

Gel desem yeniden

Gelir misin? 

Korkuyorum:

Sevmeyeceğinden...

Gelmeyeceğinden...

Eminim:

İstesen de

Dönmeyeceğinden...

Korkuyorum

Sende bu inat varken.

(29/06/2005, Çarşamba, B.Çekmece) 

(2. dönem)', 'Korkuyorum Sende bu inat varken. Sev desem yeniden Sever misin?  Gel desem yeniden Gelir misin?  Korkuyorum: Sevmeyeceğinden... Gelmeyeceğin...', ARRAY['Türk Edebiyatı','Şiir','Zeki Akçalı']::text[], 8.5, '{"poet":"Zeki Akçalı","poet_slug":"zeki-akcali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/korkuyorum-96-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Boş, Ya Hoş! ! ! (Şematik)', 'ya-bos-ya-hos-sematik-mikdat-bal-fmg7j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kurtulmuştur.............tövbe eden................böylece......................Hakka koşan

Tövbe eden..............pişman olan..............o mağrur.....................nefsi aşan

Böylece....................o mağrur....................insan olmuştur,..........iman çoşan

Hakka koşan............nefsi aşan.................iman çoşan.................sonu hoş.

Uyanmalı..................ölüm vardır.................hazır ol.......................bu gün yarın

Ölüm vardır..............gafil olma....................gafletten.....................olmaz kârın

Hazır ol....................gafletten.....................uyan, sonu yaş...........günahkarın

Bu gün yarın............olmaz kârın.................günahkarın................sonu boş

Mütevazi..................ol her zaman..............unutma.......................Hakkın kulu

Ol her zaman...........Hakka layık................ey kalbi.......................iman dolu

Unutma....................ey kalbi......................geniş, arayan..............bulmuş yolu

Hakkın kulu..............iman dolu...................bulmuş yolu...............sonu hoş

Sanki Kabe..............yıkılmıştır..................ol ma, ha! ....................gönül yıkan! 

Yıkılmıştır.................alemleri....................dünya da.....................canlar sıkan

Olma ha! ..................dünya da..................zalim, azıp ta...............yoldan çıkan

Gönül yıkan,............canlar sıkan,.............yoldan çıkan................sonu boş

Günahları.................sevap olmuş..............her kim ki...................tövbe etmiş

Sevap olmuş............ihlas ile......................inanmış......................Hakka gitmiş

Her kim ki.................inanmış......................sonra. böylece..........ömrü bitmiş

Tövbe etmiş.............Hakka gitmiş..............ömrü bitmiş...............sonu hoş

Dostu kalmaz...........yanlız kalır.................herkesle.....................çekişenin

Yanlız kalır...............mutsuz olur................durmadan..................takışanın

Herkesle...................durmadan..................kavga,durmadan.......kakışanın

Çekişenin,................takışanın,...................kakışanın...................sonu boş

Mikdat Bal der..........dara kalmaz..............kurtulur......................Hakkı bilen

Dara kalmaz.............Hakkın kulu...............sonunda....................odur gülen

Kurtulur....................sonunda....................tövbe edip te.............böyle ölen

Hakkı bilen...............odur gülen.................böyle ölen..................sonu hoş', 'Kurtulmuştur.............tövbe eden................böylece......................Hakka koşan Tövbe eden..............pişman olan................', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ya-bos-ya-hos-sematik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoşluğunla Sarhoşum', 'sarhoslugunla-sarhosum-nesrin-gocmen-4fwpy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönül masamdaki 

Egenin mavisinden içtiğim aşkla

Sarhoşum sevdiğim

Sarhoşum bu gece.

. 

Yediğim özlem mezeleri

Şarkılarım tasa 

Ve ağıt içtiğim düşlerimle 

Başım dönüyor durmadan

Saçlarımın telleri

Yüreğine takılmış

Umut ağlıyor yaslarla

. 

Gece ıssız, sakin

Askıda bir yüz 

“Sarhoşsun” diyor 

Kısık dudaklarıyla gülümsüyor 

Ve gidiyor alayla

. 

Sevda kadehim

Yokluğun şerefine kalkıyor 

Devrilen gözlerin

Yaban uzaktaki sevdamın 

Hüzün barında

. 

Bu gece değil sevdiğim

Her gece sarhoşum 

Yalan gerçeğimdeki 

Yitik yalnızlığın kahrı 

Ve senin sarhoşluğunla 

.

30/06/2005', 'Gönül masamdaki  Egenin mavisinden içtiğim aşkla Sarhoşum sevdiğim Sarhoşum bu gece. .  Yediğim özlem mezeleri Şarkılarım tasa  Ve ağıt içti...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sarhoslugunla-sarhosum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazılamayan şiir', 'yazilamayan-siir-gulseren-onay-qisxm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin içinden

Bir şiir düşer kalemime.....

Sevdamla başlar,

Hüzün kokulu,

Sitem dolu 

Ardı ardına satırlar...

Yazamam...

Okuyunca ağlarsın...

Gözlerine kıyamam....

GÜLSEREN ONAY

30/06/2005/ANTALYA', 'Gecenin içinden Bir şiir düşer kalemime..... Sevdamla başlar, Hüzün kokulu, Sitem dolu  Ardı ardına satırlar... Yazamam... Okuyunca ağlarsın...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yazilamayan-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rakı', 'raki-ayten-ozlem-yesilcali-z2z47', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sarhoş ettin beni rakı...

Çakırkeyif değil.

Sen ne insafsızsın,ne acımazsızsın..

Kimlere vurdurdun beni.

Bazen neşeli yaptın,bazen hüzünlü.

Hıçkırıklarla ağlatın beni.

Gözyaşlarım sel oldu,güldürdün bana hainleri.

Ağlatın benimle gerçek dostları.

Bazen çok güzel hayaller kurdurdun.

Bazen çocukluğumun en acılı yıllarını; 

Getirdin gözümün önüne..

Bana olmayan acıları yaşattın.

Seni çok içtiğimde bana içli şiirler yazdırdın.

Sevgiyi özlemi hiç eksik etmedin soframdan.

Gah içli türküler söyletin,gah sevdiğimi özletin.

Kimi sevdiğimi bilmeden.

Ama yinede benim yalnızlığımda gerçek arkadaşım oldun.

Beni aşk sofralına meze yapmana katlanamadığım geceler oldun

Yalan riyakar aşklara senle isyan ettim.

Sevği nin  en güzelini senle yaşadım.

Seninle beraber dostlarımla sabahladım.

Sen neymişsin be rakı..

Ne senden vaz geçtim.

Nede senle yaşamaktan mutlu oldum.

Seninle ne zaman paylaştımsa geceleri; 

Hep benim mutsuzluğum oldun.

Bana inadın kinin ne rakı.

Seni hiç incitmeden,hor görmeden başımın tacı yaptım.

Bana şimdi söyle rakı.

Senle ne zaman mutlu olacağım.

Zehir zıkkımsın be rakı.

Hatırlar mısın bilmem senle yaşadığım acıları.

Sabahlara kadar ağladığımı.

Özlemimi hasretimi kaleme döktüğümü.

İnsanlara anlatamadığım dertlerimi; 

Mutluluğumu seninle paylaştığımı.

Sen neymişsin be rakı.

Şimdi sensizim versene bana senle olmadan mutluluğu.

Bu gidişle sen beni bırakmadan.

Ben seni bırakacağım rakı..', 'Sarhoş ettin beni rakı... Çakırkeyif değil. Sen ne insafsızsın,ne acımazsızsın.. Kimlere vurdurdun beni. Bazen neşeli yaptın,bazen hüzünlü. ...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/raki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benide al', 'benide-al-ayten-ozlem-yesilcali-x8ycj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabahladım yine,dertlerimle senden çektiklerimle.

Nereye kadar bu böyle söylesene..

Nasıl inanayım sana,nasıl aldanayım de sene

Efkarımı atarım içime.

Gömülürüm kimsesizlik lere.

Sararıp solarım güller gibi.

Tek tesellim sendin.

Sende gittin eller gibi.

Neden niçin beni de götürmedin o meçhule.

Bıraktın bu değirmenin içinde.

Ne bir buğday tanesiyim,nede darı.

Katın beni bilinmezliklere.

Öğretmedin bana zulümleri acımasızlığı.

Bir güldüm,yalnız bıraktın iki tomurcuğumla.

Sen olmadan nasıl tomurcuklar gül olsun.

Ben sen olamam ki,sende ben.

Geri gel al beni de seninle o meçhule.

Boynu bükük koma beni.

Atma beni bilinmezliklere.

Yol yordam bilmeden.

Aklımı gururumu koynuna bıraktım.

Sende beni bilinmezliklere attın.

Gel al beni de götür seninle meçhule.

Her günümü zehir etme.

Gözyaşlarımı sele döndürme.

Mutluluğu bana çok görme..

Al beni de götür o güzel meçhule.

Koma beni zalim dünyada.

İnsafsızların otağına atma beni.

Bak çok uykum var albenide koynuna.

Uyut o güzelim ninilerinle..

Sana kıyan bu dünya bana da kıyar.

Tomurcuklarıma da.

Gel al beni de gittiğin o meçhule.', 'Sabahladım yine,dertlerimle senden çektiklerimle. Nereye kadar bu böyle söylesene.. Nasıl inanayım sana,nasıl aldanayım de sene Efkarımı ata...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/benide-al-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alacaklı', 'alacakli-sair-pirinc-6ry6m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'can hep bılmedıgını ıster

tanımadıgı ınsanları

dokunmadıgı tenlerı

daha cok sever

boylece aşinalıkların tadını daha ıyı bılır

o lezzetı cıkarmayı ogrenir

agızda yavasca tadına varılan

lımonlu akıde şekeri gıbı

uzun uzun

.........

bir ada gezintisi borcun var bana

alacaklı kalmak guzel şey....', 'can hep bılmedıgını ıster tanımadıgı ınsanları dokunmadıgı tenlerı daha cok sever boylece aşinalıkların tadını daha ıyı bılır o lezzetı cıka...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alacakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş ev', 'tas-ev-sair-pirinc-jd00a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kağıt bitmesin diye 

Son yazdıgım cumleyı yazdıkca siliyorum

Hayatı oyalama oyunundan sıkılınca

Golgeli bir  sakakta eski bir ev benzeri

Taş taş sökulecegim….', 'Kağıt bitmesin diye  Son yazdıgım cumleyı yazdıkca siliyorum Hayatı oyalama oyunundan sıkılınca Golgeli bir  sakakta eski bir ev benzeri Taş...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tas-ev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrının Gazabı Maskelerimiz', 'tanrinin-gazabi-maskelerimiz-sair-pirinc-77x81', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1

bu kış gecesinde biz bize oturalım

eskilerden konuşalım

nasıl tanıştıgımızdan

nasıl seviştiğimizden

nasıl vazgecemediğimizden

lambayı yakmayalım

aramıza ışığı bile sokmayalım

2

aşk var sende

kadehte dudak

dudakta heves

tende tuz

tuzda izim

....

şerefine deniz yıldızım

3

kimi sevdiysem gölgesi sindi üstüme

sevmekten sevişmekten yorgun istanbul

bir kış günü ikindi vakti kabristan ziyareti

kafir aklımla dua okuyup topraga uzandım

soyundum

öldüm

dirildim

arındım

...', '1 bu kış gecesinde biz bize oturalım eskilerden konuşalım nasıl tanıştıgımızdan nasıl seviştiğimizden nasıl vazgecemediğimizden lambayı yakm...', ARRAY['Türk Edebiyatı','Şiir','Şair Pirinç']::text[], 8.5, '{"poet":"Şair Pirinç","poet_slug":"sair-pirinc","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tanrinin-gazabi-maskelerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankaralı Kız', 'ankarali-kiz-sukru-oksuz-gy2ki', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaçan kurtulurdu inan elimden

Şu aşık halime şimdi bakınız

Niceleri gelip geçti kalbimden

Kalbimde sen durdun Ankaralı Kız.

O tatlı gözlerle tatlıca bakan

Başka yere değil kalbime akan

Son hücreme kadar beni de yakan

Ateşten bir nurdun Ankaralı Kız.

Şiiri severim demiştin hani

Şiirime konu seçmiştim seni

Unutma dediğim zamanda beni

İnsafsızca vurdun Ankaralı Kız.

Kötü kalplilerin her an korktuğu

Gölgesinde nice er uyuttuğu

Binlerce askerin nöbet tuttuğu

Aşılmaz bir surdun Ankaralı Kız.', 'Kaçan kurtulurdu inan elimden Şu aşık halime şimdi bakınız Niceleri gelip geçti kalbimden Kalbimde sen durdun Ankaralı Kız. O tatlı gözlerle...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Öksüz']::text[], 8.5, '{"poet":"Şükrü Öksüz","poet_slug":"sukru-oksuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ankarali-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Sevdana Yenildim', 'senin-sevdana-yenildim-huseyin-erdogan-48b53', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gecene ay ve yıldızım

sen yoksan yanımda

her anımda 

binlerce 

insan arasında

olsam da

inan ki ben

sensiz yapayalnızım

ben hasretin

kitabını yazan

yokluğunda ağlayan

acı acı çalan

bir sazım

bana yalnızca

sen lazım

geceni bile

gün eder sevgim

kışını 

bahara çevirdim

sensizliktir

benim tek derdim

bil ki yüreğimi

bir tek sana verdim

ömrüm boyunca

yalnızca

senin sevdana yenildim

                  30.06.2005', 'gecene ay ve yıldızım sen yoksan yanımda her anımda  binlerce  insan arasında olsam da inan ki ben sensiz yapayalnızım ben hasretin kitabını...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/senin-sevdana-yenildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım''dı Adım', 'askim-di-adim-serdar-uzunoner-zn710', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkım’dı adım

Seslenirken kulağıma ismimi

Şimdi Serdar oldum

Senin için sıradan biri işte

Ben sebep oldum aşkın Serdar oluşuna

Her aşkın bir bedeli 

Her sevginin bir isteği vardı

İstenilen bedel belki ağır değildi ama

Bir kiloyu kilometrelerce taşısan

Taşınmaz bir yük olurdu

Bana da işte öyle oldu

Günlerce aylarca içimi kemiren sorular

İçinden çıkılmaz sorunlara dönüştü

İçimde füg böyle oluştu

Yörüngeden çıkıp sonsuzluğa yönelmek

Hayattan kopup bir sonu seçmek demek

Bende öyle yaptım

Sonsuzluk içinde kayboldum

Kilitlenmiş dilimin kurşunuyla vurdum kendimi

Döküldüm parça parça toprağa

Çizilmiş bir siluettim silindim hayattan

Yaktım geçmişimi ve geleceğimi 

Yırtılsın ya da yansın tüm resimlerim

Benim gibi', 'Aşkım’dı adım Seslenirken kulağıma ismimi Şimdi Serdar oldum Senin için sıradan biri işte Ben sebep oldum aşkın Serdar oluşuna Her aşkın bir...', ARRAY['Türk Edebiyatı','Şiir','Serdar Uzunöner']::text[], 8.5, '{"poet":"Serdar Uzunöner","poet_slug":"serdar-uzunoner","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/askim-di-adim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai - IX', 'rubai-ix-kenan-mim-eryigit-6y6ln', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şekiller değişir, renkler değişir.

Ölümlü dünyadan her şey sislenir.

Rıhtıma yanaşır beklenen gemi; 

“Binin çekinmeden” diye seslenir.!', 'Şekiller değişir, renkler değişir. Ölümlü dünyadan her şey sislenir. Rıhtıma yanaşır beklenen gemi;  “Binin çekinmeden” diye seslenir.!...', ARRAY['Türk Edebiyatı','Şiir','Kenan Mim Eryiğit']::text[], 8.5, '{"poet":"Kenan Mim Eryiğit","poet_slug":"kenan-mim-eryigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-ix-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç İhtiyar Adam - l', 'uc-i-htiyar-adam-l-ozan-ozel-9kpoz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'üç ihtiyar adam

her gün pabuç eskittiğim 

yola denk düşerdi gölgeleri

kulağıma değerdi

demli çay kıvamındaki sohbetleri

ruhuma ses verirdi

sıkça tekrarladıkları

dost makamındaki şen gülüşleri', 'üç ihtiyar adam her gün pabuç eskittiğim  yola denk düşerdi gölgeleri kulağıma değerdi demli çay kıvamındaki sohbetleri ruhuma ses verirdi s...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uc-ihtiyar-adam-l-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamze', 'gamze-gorkem-kaya-2fdr0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabah traş olurken bir an gözlerime takıldı bakışlarım, 

O kadar güzel oturmuştun ki mahmurluğuma 

Hiçbir manzara bu kadar yakışmamıştı bana 

Kıyamadım, 

Yüzümü bile yıkamadım 

Sen ıslanma diye 

Bu yağmur ikimize de fazlaydı zaten 

Kuru bir havlu ile sildim yüzümü 

Yavaş ve okşar gibi. 

Toparladım geceden kalanları, 

Ceplerime doldurdum, sonra düşünürüm diye 

Bir tek gamzelerini avuçlarıma aldım 

Avuç açayım 

Gerekirse bir gamze için diye.

2004', 'Sabah traş olurken bir an gözlerime takıldı bakışlarım,  O kadar güzel oturmuştun ki mahmurluğuma  Hiçbir manzara bu kadar yakışmamıştı bana...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gamze-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgesinde', 'golgesinde-gorkem-kaya-hdw6i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gölgesinde saklandığım kulenin bir adı var mıydı? 

Serindi, 

Kenarından deniz görünürdü... 

Geceleri, köprü altından transfer bir sarhoş; 

günün ilk ışıklarında sersem bir martı paylaşırdı. 

Hüzünlenince hava, upuzun uzanırdı gölge yola.. 

Var mıydı gölgesinde saklandığım kulenin adı? 

“Çıkmam gölgenden..”, derdim ta ki güneşin 

sadece doğudan batmadığını öğreninceye dek.. 

Şimdi akşam.. 

Gölge artık kulenin bana ait olmayan dibinde. 

Yakmıyor güneş de eskisi kadar. 

Kulenin adı hâlâ aklımda değil 

ve gece, her zamankinden daha yakın gözlerime...

02 05 2005', 'Gölgesinde saklandığım kulenin bir adı var mıydı?  Serindi,  Kenarından deniz görünürdü...  Geceleri, köprü altından transfer bir sarhoş;  g...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/golgesinde-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-gorkem-kaya-d1e25', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir küsüp 

Bir barışıyoruz seninle 

Aldırmadan geçiyor zaman bize 

Ne seninle 

Ne sensiz olan bu sevda 

Bitecek 

Ayın bile saklandığı bir gecede 

Ve 

Sabah olduğunda 

Ya ben sana mahkum 

Ya sen bensiz 

Doğacağız güne...

15 05 2005', 'Bir küsüp  Bir barışıyoruz seninle  Aldırmadan geçiyor zaman bize  Ne seninle  Ne sensiz olan bu sevda  Bitecek  Ayın bile saklandığı bir ge...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayat-220-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''u izlemek', 'i-stanbul-u-izlemek-gorkem-kaya-ay17g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen hırsız bir martının gözleri ile izlersin İstanbul’u, 

Galata Köprüsü’nde bir duble rakının kokusunu takip edersin 

Gözün uzaklardaki Kız Kulesi’ne takılır 

Ama çaktırmazsın, 

Çaktıramazsın manzaranın bekçisi vardır 

Bir garson edasında gelir dikilir, rakı kadehinin dudak izi olan en nadide yerine 

Uzakları gösterirsin parmağınla 

”gördün mü martıyı? 

ne güzel süzülüyor Marmara’nın semasında.” 

..........''? ''......... 

Bir tek sen görürsün martının gagasında tuttugu Kız Kulesi’ni 

Ve bir tek sen bilirsin Leandros’a inat manzaradan kaçırıldığını 

Ama oturursun yine de bir gamzenin en nemli köşesine 

Bekçiye gıcık, 

Rakıya uyuz, 

Manzaraya inat 

Bazen de hırsız bir martının gözleri izler seni İstanbul’da..............

05 05 2004', 'Bazen hırsız bir martının gözleri ile izlersin İstanbul’u,  Galata Köprüsü’nde bir duble rakının kokusunu takip edersin  Gözün uzaklardaki K...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/istanbul-u-izlemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firar', 'firar-i-brahim-cetinkaya-uvaar', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çay bardağında bıraktığın 

dudak payı kadar bile 

uzak kalmak istememiştim gözlerinden.

Firarı gözlerinden gözlerimin sendendir bilesin.', 'Bir çay bardağında bıraktığın  dudak payı kadar bile  uzak kalmak istememiştim gözlerinden. Firarı gözlerinden gözlerimin sendendir bilesin....', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çetinkaya']::text[], 8.5, '{"poet":"İbrahim Çetinkaya","poet_slug":"i-brahim-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/firar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Bekler Bizi', 'i-stanbul-bekler-bizi-gorkem-kaya-1ma03', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen kapa gözlerini bu gece 

İstanbul bekler bizi, 

Huzur içinde uyu 

Uzandığın sessizlikte, 

Aşiyan diye söz verdiğimiz buluşma yerinde 

Yoksan, zamanı geldiğinde 

Ben bulurum seni 

Gamzelerinin bıraktığı izde 

Sanki sessiz bir gemiyi izler gibi yakamozların izinde 

Sen kapa gözlerini saklambaç oynar gibi, 

21’e kadar say, 

22 demeden ben ve İstanbul saklanırız sensizliğe. 

Ebe olma sırası geldiğinde 

Yoksan, meycinin cebinde 

Ben bulurum seni 

Gizlendiğin kadehin en buğulu yerinde. 

Sen kapa gözlerini gözlerime 

Mümkünse bir günün martı çığlıkları ile doğduğu günde 

ve ört üzerimi eskisi gibi yeşil kokan örtünle.... 

Sakın merak etme, 

İstanbul bekler bizi 

Hem de çok bekler bu gidişle....

19 04 2005', 'Sen kapa gözlerini bu gece  İstanbul bekler bizi,  Huzur içinde uyu  Uzandığın sessizlikte,  Aşiyan diye söz verdiğimiz buluşma yerinde  Yok...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/istanbul-bekler-bizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte o zamanlar', 'i-ste-o-zamanlar-gorkem-kaya-oosj9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanki Japon çizgi fimlerinden fırlamış gibi bakıyorsun ya 

Üzülünce 

Gözlerin iri 

İçleri bulut yüklü 

Dudakların titrek ve ıslak 

İşte o zamanlar öpmek geçiyor içimden seni 

Sanki Japon 

çizgi filmlerinden fırlamış gibi konuşuyorsun ya 

Üzülünce 

Kelimeler masum 

Geldiği yürek kırgın 

Ve sesinin tonu çocuksu 

İşte o zamanlar öpmek geçiyor içimden seni 

Sanki Japon çizgi filmlerinden fırlamış gibi yüzünü kapatıyorsun ya 

Üzülünce 

Ellerin ıslak gözlerine batık 

Yorgun gamzelerine teğet 

Ve terli 

İşte o zamanlar öpmek geçiyor içimden seni 

Hani öpmek geçiyor ya içimden seni 

Sen bakarken nemli 

Titrek konuşurken dudakların 

Ve saklarken yüzünü avuçlarının arasına 

İşte o zamanlar Japon çizgi filmlerinde oynatmak geçiyor içimden seni...

2000', 'Sanki Japon çizgi fimlerinden fırlamış gibi bakıyorsun ya  Üzülünce  Gözlerin iri  İçleri bulut yüklü  Dudakların titrek ve ıslak  İşte o za...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/iste-o-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Japon mucizesi', 'japon-mucizesi-gorkem-kaya-0h3nq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin dudaklarında açan sözcükler 

Düşük tümceli kurulmuş 

Kilitli pencerelerden sızan hikayeler 

Kapının önüne dizilmiş 

Hayallerim bir daktilonun tuşlarında ritmini kaybetmiş 

Ve tükenmez kalem ile yazılan kadere 

Japonlar tükenmez silgisi bulmuş

2000', 'Senin dudaklarında açan sözcükler  Düşük tümceli kurulmuş  Kilitli pencerelerden sızan hikayeler  Kapının önüne dizilmiş  Hayallerim bir dak...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/japon-mucizesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılar ve ben', 'martilar-ve-ben-gorkem-kaya-od2t9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırık kanatlı martılar 

Bir de ben 

Uçamayan sadece ikimiz varız 

Kalbi kırık ben 

Bir de martılar 

Sevemeyen sadece ikimiz varız

1998', 'Kırık kanatlı martılar  Bir de ben  Uçamayan sadece ikimiz varız  Kalbi kırık ben  Bir de martılar  Sevemeyen sadece ikimiz varız 1998...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/martilar-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mı? -2', 'mi-2-gorkem-kaya-ys42b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saat kaç? 

Bilmesem cezası var mı? 

Ya da 

Sabahın dördünü gösteriyorsa 

Umursayan var mı? 

Sevgi saatim gelmiş 

Bas bas bağırıyorum 

Duyan var mı? 

1999', 'Saat kaç?  Bilmesem cezası var mı?  Ya da  Sabahın dördünü gösteriyorsa  Umursayan var mı?  Sevgi saatim gelmiş  Bas bas bağırıyorum  Duyan ...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mi-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-murat-kok-ccaqg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi uzaklardasın 

ve aramızda yollar 

ve aramızda yıllar 

ve aramızda kalabalıklar 

biliyorum 

biliyorum... 

Bense boş zamanlardayım 

kırık masa 

eğreti bir sandalye 

düşler ülkesindeyim 

aşkın siluetlerini çiziyorum 

mavi boşluğa 

kalmıyor ki izler 

yürekteki gibi 

tükenen zaman değil 

yarım aşklar 

biliyorum 

biliyorum 

ve bilmiyorum...

29.6', 'Şimdi uzaklardasın  ve aramızda yollar  ve aramızda yıllar  ve aramızda kalabalıklar  biliyorum  biliyorum...  Bense boş zamanlardayım  kırı...', ARRAY['Türk Edebiyatı','Şiir','Murat Kök']::text[], 8.5, '{"poet":"Murat Kök","poet_slug":"murat-kok","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biliyorum-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mı?', 'mi-gorkem-kaya-8ocva', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl yapmalı? 

Saatin kadranı ile mi oynamalı? 

Kadranı açıp akrebi dışarı mı salmalı? 

Yelkovan ısrarla içeride hapis bırakılıp 

Prangalara mı vurulmalı? 

Akrebe tut oğlum diyerek 

En masumundan bir aşığa mı saldırtmalı? 

Zamanla oynamak için yoksa başka bir yol mu bulmalı? 

Geleceğe bir ihtarname çekip 

Geçmişim gelecek hayallerimden çık mı demeli? 

Bugünü dünün piçiymiş gibi 

Duygularımızla emzirmeden bir cami avlusuna mı bırakmalı? 

Zamanla oynamak için yoksa başka bir yol mu bulmalı? 

................................. 

Seni bir kum saatine gömüp 

Kumdan kaleler mi yapmalı? 

1999', 'Nasıl yapmalı?  Saatin kadranı ile mi oynamalı?  Kadranı açıp akrebi dışarı mı salmalı?  Yelkovan ısrarla içeride hapis bırakılıp  Prangalar...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muerte', 'muerte-gorkem-kaya-on841', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorgunum diyebilseydim 

Ve çömelebilseydim dizlerinin dibine 

Ellerin şakaklarımda dolaşırken 

Ve saçlarımı okşarken ellerin 

Yumabilseydim gözlerimi 

Doğrulsaydik sonra 

Beline dolansaydı kollarım bir düğüm gibi 

Farketmeden omuzuna yaslanabilseydim 

Ve yürüseydik 

Giderken beni götürmediğin yere 

Sahipsiz bir özlem esseydi 

Sarmalasaydı bizi 

Ve henüz sıcakken ellerim 

Kucağına devrilseydi bedenim

16 05 2005', 'Yorgunum diyebilseydim  Ve çömelebilseydim dizlerinin dibine  Ellerin şakaklarımda dolaşırken  Ve saçlarımı okşarken ellerin  Yumabilseydim ...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/muerte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-gorkem-kaya-xgd0y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat bu kadar güzelken 

Ben neden üzüleyim 

Neden seni özlüyormuş gibi yapayım 

Bu kadar güzelken hayat 

Seninle neden savaşayım 

Neden seni seviyormuş gibi yapayım 

Güzelken hayat bu kadar 

Seni neden isteyeyim 

Neden sen yokken, ben de yokmuşum gibi yapayım 

Ve hayat kadar güzelken bu, 

Neden vazgeçeyim? 

2001', 'Hayat bu kadar güzelken  Ben neden üzüleyim  Neden seni özlüyormuş gibi yapayım  Bu kadar güzelken hayat  Seninle neden savaşayım  Neden sen...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neden-159-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı', 'kirmizi-i-brahim-cetinkaya-c54bk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yağmur ki sorma 

gözlerim kupkuru 

geçmişin ıslak elleri kurulamış 

el değmemiş dudaklarını 

gerçek olsun istiyor yüreğim 

bir kaza daha atlattığını 

bilmeli ki yeniden? 

Belki zor, ki yeniden 

hayal yaşatır insanı 

tek heceden kitap olur gözlerin 

kaçamak bakışlarda aşk saklanırmı? 

kandırma kendini gözlerin tutuklu neye yarar.

Bu sen misin 

yoksa kim o sor kendine 

sonra gözlerin gelsin aklına

dudaklarının kırmızısı sölerine bulaşsın 

delilik bu sakın kırmızı kırmızı konuşma! 

Sözlerin hürmüş 

neye yarar aşk...

kaba sığmaz sende aşk mısın? 

dudaklarının kırmızısı gözlerinden akarken 

kimsin sen? 

sen tanıyormusun aynada kendini?', 'Bir yağmur ki sorma  gözlerim kupkuru  geçmişin ıslak elleri kurulamış  el değmemiş dudaklarını  gerçek olsun istiyor yüreğim  bir kaza daha...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çetinkaya']::text[], 8.5, '{"poet":"İbrahim Çetinkaya","poet_slug":"i-brahim-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kirmizi-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye İlham Vapuru', 'nereye-i-lham-vapuru-gorkem-kaya-xf62z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adını bir şair koyduysa 

Öyle elini kolunu sallayarak gidemezsin 

Senin bir sorumluluğun var 

Dik dur! 

Biraz toparlan! 

Unutma adını Nazım koyduysa Sunay 

Ya da kardeşin Edip ise 

Vardır bildiği şairin 

Şimdi kulaçlarını daha bir heybetli at boğazda 

Görenler görmemezlikten gelemesin 

O şımarık Kız Kulesi’ni bile baştan çıkar 

Aklı sende kalsın 

Unutma Orhan Veli ismini taşımak o kadar kolay değil 

Boğazın diğer ucundaki martılar da söylesin adını 

Kaldır başını yerden 

Kırgınlık sana yakışmıyor 

Gideceksek beraber gideceğiz 

Sen köhne bir tersaneye 

Ben denizi olmayan bir şehre 

Unutma İstanbul’un Cemal’i sana emanet 

Hele kızdırırsan Atilla’yı 

Kimin sevgilileri kucaklaşır güvertende 

Şimdi dik durma zamanı 

Artık şair bir martı var kaptan köşkünde 

Unutma adını Can koyduysa Sunay 

Su’ya daha yakın olasın diyedir. 

Sana bir yolluk bıraktım 

Üst güvertenin üçüncü koltuğunda... 

Biraz dikkatli bak 

Gizlice el ele tutuştuğum ilk gün orada 

.............. 

Sana da İstanbul 

Yazığı bol olsun 

Şairsiz 

Güzelliğini kim anlatacak sana İstanbul

06 05 2005', 'Adını bir şair koyduysa  Öyle elini kolunu sallayarak gidemezsin  Senin bir sorumluluğun var  Dik dur!  Biraz toparlan!  Unutma adını Nazım ...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/nereye-ilham-vapuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleyen Bahçe', 'ozleyen-bahce-gorkem-kaya-qaecs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaslanma deseydin sadece 

Anlardım çekilmeden önce 

O kadar mı ağır geldi sana bedenim 

Oysa ki başımı göğsüne yasladığım zaman 

Huzur kaplardı içimi 

Teninin kokusu bulanırdı yüzüme 

Salıncak kurduğumuz günleri anımsar 

Bulutları düşlerdim 

Keşke yaslanma deseydin sadece 

Ne gerek vardı 

Bahçemizden bir sonbahar sessizce ayrılıp 

Beni gölgesiz bırakacak 

Seni çok özleyeceğim Ihlamur Ağacım 

Belki başka bir baharda 

Başka bir bahçede.

05 05 2005', 'Yaslanma deseydin sadece  Anlardım çekilmeden önce  O kadar mı ağır geldi sana bedenim  Oysa ki başımı göğsüne yasladığım zaman  Huzur kapla...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozleyen-bahce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece bir gün', 'sadece-bir-gun-gorkem-kaya-9xp9h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu topraklarda 

Birinin adı Nazım 

Digerininki Adnan cok kardeş yaşadı 

Aynı toprak damlı evde doğdular 

Sürdükleri toprak aynıydı 

Aynıydı doydukları toprak 

Elini öptükleri ana aynı 

Aynıydı aldıkları dua 

Sadece bir gün 

Bir gün birisi al yıldızlı bayrağını sağ omuzunda 

Diğeri sol omuzunda taşıdı 

Aynıydı baş koydukları dava 

Vurulan yürek aynı 

Aynıydı yığılan beden 

Gömüldükleri toprağın kokusu aynı 

Sadece bir gün 

Bir gün birisi al yıldızlı bayrağını sol omuzunda 

Diğeri sağ omuzunda taşıdı

13 06 2005', 'Bu topraklarda  Birinin adı Nazım  Digerininki Adnan cok kardeş yaşadı  Aynı toprak damlı evde doğdular  Sürdükleri toprak aynıydı  Aynıydı ...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sadece-bir-gun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideli-I', 'sen-gideli-i-gorkem-kaya-xl613', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gideli 

Kaç balık akını oldu Marmara’da 

Kaç taka 

Kaç tekne çekildi kızağa 

Senden sonra 

Kaldırma kararı aldılar vapurları 

Gerek yok artık dediler 

Eskidi dediler 

Yenileri gelecek dediler 

Hem de güvertesiz dediler 

Kızdı şairler 

Ben gülümsedim 

Vapurlar gülümsedi 

Senin yanına geleceklerini duymuş 

Kız Kulesi 

Bir de martılar 

Şimdi onlar da bekliyor 

Kaldırılacakları günü 

................... 

Sen gideli 

Ben de bekliyorum 

Masamdaki fotoğraftan birlikte 

Haliç’i seyredeceğimiz günü

10 05 2005', 'Sen gideli  Kaç balık akını oldu Marmara’da  Kaç taka  Kaç tekne çekildi kızağa  Senden sonra  Kaldırma kararı aldılar vapurları  Gerek yok ...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-gideli-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan Yıllar', 'kaybolan-yillar-belgin-kistavul-k29os', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'KaYbOLaN YıLlaR

Bir nehir gibi akıyor ömrüm

Uzak denizlere doğru

Hayallerim dalgalar gibi

Çarpıp duruyor kayalara

Renkli Rüyalarım şimdi,

Bir Sevda Barajı gerekiyor, 

Bir zaman diliminde

Akışı durduracak,

Kumsalla buluşacak

Varsın denizler beklesin

Benden başka suyu yokmu? 

Gecikmelide olsa birgün akacak,

Uzak denizler sonunda buluşak....', 'KaYbOLaN YıLlaR Bir nehir gibi akıyor ömrüm Uzak denizlere doğru Hayallerim dalgalar gibi Çarpıp duruyor kayalara Renkli Rüyalarım şimdi, Bi...', ARRAY['Türk Edebiyatı','Şiir','Belgin Kistavul']::text[], 8.5, '{"poet":"Belgin Kistavul","poet_slug":"belgin-kistavul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kaybolan-yillar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideli-II', 'sen-gideli-ii-gorkem-kaya-21hhi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen gideli 

Dört mevsim geçti 

Bir çok çiçek açtı 

Hepsi soldu İstanbul’da 

Biz yine uçurtma uçurtmaya gittik baharla 

Ağırlık yapsın diye 

Kuyruğuna 

Özlemimi bağladım sana olan 

Ama dinlemedi 

Sicim gibi bir ıslaklık kopuverdi 

El bile sallamadan gidiverdi uçurtma

10 05 2005', 'Sen gideli  Dört mevsim geçti  Bir çok çiçek açtı  Hepsi soldu İstanbul’da  Biz yine uçurtma uçurtmaya gittik baharla  Ağırlık yapsın diye  ...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-gideli-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideli-III', 'sen-gideli-iii-gorkem-kaya-hmnwa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gideli 

Galata Köprüsü iki kere açıldı 

Hayret birşey ikisinde de kapandı 

Soldan üçüncü dükkan sahibi şikayet etmiş 

Balık ekmekçileri kaldırdılar 

Artık takılmıyor boğazımıza 

Kılçık gibi ayrılık 

Sadece iki tek atmak için oturduğumuzda köprüye 

Bir kadeh nasıl öksüz kalır 

Anlatıyor maliyetini bile kurtarmayan hesap

10 05 2005', 'Sen gideli  Galata Köprüsü iki kere açıldı  Hayret birşey ikisinde de kapandı  Soldan üçüncü dükkan sahibi şikayet etmiş  Balık ekmekçileri ...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-gideli-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideli-IV', 'sen-gideli-iv-gorkem-kaya-qw7x8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gideli 

Koskoca bir yıl oldu 

Senden sonra çok şey değisti İstanbul’da 

Karaköy’e tramvay yaptılar 

Aksın diye trafik daha rahat 

Almaya gelebil diye beni akşamları 

Görebileyim seni daha çok diye 

Ama.....olmadı. 

Daha çok kapadı yolu tramvay

10 05 2005', 'Sen gideli  Koskoca bir yıl oldu  Senden sonra çok şey değisti İstanbul’da  Karaköy’e tramvay yaptılar  Aksın diye trafik daha rahat  Almaya...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-gideli-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideli-V', 'sen-gideli-v-gorkem-kaya-kih4p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen gideli 

Koskoca bir yıl oldu 

Senden sonra çok şey değişti 

İçimdeki İstanbul’da 

Dilekçe verdim ben de 

Amortisman masraflarım çok 

Tedavülden kaldırın beni de diye 

Ama...olmadı. 

Şimdilik reddettiler 

Ama söz verdiler 

Kaldıracaklar beni de zamanı geldiğinde

10 05 2005', 'Sen gideli  Koskoca bir yıl oldu  Senden sonra çok şey değişti  İçimdeki İstanbul’da  Dilekçe verdim ben de  Amortisman masraflarım çok  Ted...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-gideli-v-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideli VI', 'sen-gideli-vi-gorkem-kaya-8fy13', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gideli 

Sene de bir çıkıyor İstanbul’da dolunay 

Onu da görebilmek için 

Kalkıp gidiyoruz Balat’a 

Çeviriyoruz masayı kuleye 

Ayıda bir kürekci çekiyor meyhaneye

10 05 2005', 'Sen gideli  Sene de bir çıkıyor İstanbul’da dolunay  Onu da görebilmek için  Kalkıp gidiyoruz Balat’a  Çeviriyoruz masayı kuleye  Ayıda bir ...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-gideli-vi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen misin Mayıs?', 'sen-misin-mayis-gorkem-kaya-jhoa3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevsimiydi piknik yapmanın 

Aşık olmanın mevsimiydi 

Balkon sohbetlerinin 

Bakırköy sahilinde tavla oynamanın 

Mevsimiydi 

Sevmenin 

Dokunmanın 

Gülümsemenin 

Kaçacağını bile bile 

Uçurtma uçurtmanın mevsimiydi 

Arnavutköy’de balık tutmanın 

Akşam üzeri bilinmeyen bir meyhanede sarhoş olup 

Fasıl dinlemenin mevsimiydi 

Geceleri yıldızlara bakmanın 

Ateş böceklerini yakalamanın 

Mevsimiydi 

Yan bahçeden gül aşırmanın 

Ve yalın ayak çimenlere basmanın 

Mevsimiydi 

Hayata daha sıkı sarılmanın mevsimiydi 

Değildi veda etmenin 

Seni özlemenin mevsimi değildi 

................................ 

Mayıs ayını seyrederken 

Yağmur penceremin arkasında yağıyor artık.....

07 06 2005', 'Mevsimiydi piknik yapmanın  Aşık olmanın mevsimiydi  Balkon sohbetlerinin  Bakırköy sahilinde tavla oynamanın  Mevsimiydi  Sevmenin  Dokunma...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-misin-mayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdiğim Ülke', 'seni-sevdigim-ulke-gorkem-kaya-9nn7c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eğer hayal kuracak kadar cesur olsaydım 

Tırmanırdım bakışlarına önce 

Seslenirdim kimse var mı orada diye 

Ve umut ederdim 

Yüreğime bir yankı ile karşılık verişini 

Şimdi sadece dikiliyorum 

Bakışlarının düştüğü yerde 

Ama sen de biliyorsun 

Bunların hepsi senin yüreğinde 

Benim yüreğimde 

Sadece 

Eğer baharda tomurcuklanan ağaç kadar cesur olsaydım 

Ayrılık saatini takvimde işaretler 

Dalgaların bile sessizce sarıldığı kumsalda 

Kolkola yürürdüm seninle 

En derin izi bırakırdık kumlarda 

Önce 

Ardımıza döner 

Akdeniz’in izleri kucaklayıp 

Kayıp şehre götürüşünü seyrederdik 

Sonra 

Gülümserdik 

Herşeyin 

Hayallerde yaşandığı şehirde 

Bir uyku öncesi masal olduğunu bile bile 

Eğer cesur olsaydım ellerin kadar 

Sarılırdım 

Sanki toprağa sarılırcasına 

Sadece kokunu içime çekerdim 

Yüzümü, yüzüne değdirirdim 

Bir tomurcuk açardı gülüşümde 

Sen henüz büyümeden 

Koparırdın 

Ben de can verirdim 

Dudaklarının kucaklaştığı yerde 

Seve seve 

Seni... 

.................... 

Şimdi 

Sen 

Seni bekleyen sevgiliye git 

Merak etme 

Ben 

Cesaretle 

Bir yıldızın kuşağına oturmus 

Çıplak ayaklarım bulutların içinde 

Sevgini seyrediyor olacağım 

Seni sevdiğim ülkede.

09 05 2005', 'Eğer hayal kuracak kadar cesur olsaydım  Tırmanırdım bakışlarına önce  Seslenirdim kimse var mı orada diye  Ve umut ederdim  Yüreğime bir ya...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/seni-sevdigim-ulke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşgallerin Şehri', 'i-sgallerin-sehri-tarhan-simsek-vlihr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşanmışlığın

En güzel serüveni olan

Seni sevmekle başlamıştı

Yüreğimin tarihi

Ve sen benim tarihimdin

Tarihler aynasında / atlasında

Bu tarihe dair

Tarihleri belli olmayan savaşlardan

İbaretti tüm uğraşım

En kadim düşmanlarla meşk ediyordum

Huzursuzluğun bolca olduğu bu meydanlarda

Tanrı huzurunda

Hasbel kader 

En girilmez çocuk bahçeleri misali

Savaş alanlarındaki 

Barut kokusuna meyl eder

Sevda oyunum.

Ve 

Tanrının kırbacı hakikatliğinde 

Bir oyundur sevda masalı.

En hiçleri sahneler bahçesinde

Neyin var: Hiç

Neden böyle suskunsun: Hiç

Bana mı kızdın: Hiç

Ve bitmez tükenmez

Hiçler sahnelenir 

İşgale maruz şehrin 

En batık limanlarında

En yengi ve yenilgi dolu meydanlarda

Tüm ölümleri

Tek bir söz bağlar sulha

“Ölene dek ve hatta ölümden sonra bile”

En keskin mavzer sıkımında 

Ölene dek

Ve hatta ölümden sonrasına dair

Terennüm eden ziyadesiz yalanlar.

Ve düşman işgaliyle

Şehrin en na-mahrem pasajları

Düşerken gözlerinde

Sana mektuplar dolusu pasajlar gömüyordum

Şehrin tüm mezarlıklarına

Her mezar taşında yazılmış 

Şu tek satırdır belki de tek zaferim:

“Ölene dek ve hatta ölümden sonra bile”

Ve savaş sonrası

Devam eden savaş çığırtkanlığı

Tüm gizemiyle Midye içinde

Açılmamış inci misalidir

Olabildiğine güzel 

Ve alabildiğine ölümcül

Rengârenk bir gölge oyununda 

En orijinal sevişmeleri yaşayan

Ölü bedenlerimizden 

Bu renk cümbüşüne dair tek alametti

Dudaklarından süzülen

Kızıl bir ruj dinginliği

Ve saatler günün deminde 

Ölümü vururken 

Akrebin yelkovana olan tutkusundan

Elbette ki haberdardır 

Oysaki beni zafere taşıyacak

Sana dair yazılmış olan

Bu ölüm fermanımdan

Mesul ulan 

Habercidir asıl cellâdım

Haberdarlığı zaferi değil

Yüreğimin işgalini müjdeler sana

Yelkovan yenik düşmüştür anlayacağın

Saatler sulha vururken durmuştur

Ve duran saatler bile

Günde iki dem doğruya isabet ediyorsa

Sana dair 

Bir yığın ölü savaşçıya karşı savaşım

Günde iki dem de hakikate vurmaktadır

Bilinen olan

En hırçın havalarda

En hırçın yele karşı

Uçan bir martı misaliydi

Ebabil kanatlı gönlüm

Ama hülasası 

En dingin havada

Vuruldum sana/

Veyahut keman misali kaşlarından

Bedenime saplanan 

Panzehiri malum olmayan

Zemheri oklara

Kırık bir nağmeden

Kırık bir sesle

Havada sıyrılan 

“Ölene dek ve hatta ölümden sonra bile”

Haykırışlarının kestiği

Dağ doruklarındaki aksi

Bir destan gibi yazılır

En ilahi söylencelere

Başı senle

Sonu benle biter

Nakaratı ise şu olmalıdır

“Ölene dek ve hatta ölümden sonra bile”

Ve en korsan baskılı kitaplardaki

En harami aşklara inat

Meçhuliyet arar yazgım

Yolculuk ebedidir sen gibi

Na-ebet olanıysa 

Kitaplardan yazgımıza dair 

Yazılmış olan asılsız çöl kuraklıkları

Ve bu kuraklıklardaki

Çöl bedevilerinin 

Sana olan ıslak duyguları

Düşlerle örülü bir şehrin

Esir uyurgezerleri misali

İşgale aşina rüyalarıdır seni sevmelerim

En ağır intihar bombardımanlarında

Sana göğüs geriyorsa şehrin izbe meyhaneleri

Hancıdan bir tutam seni dilemektir asıl gayeleri

Sarhoş edilmiş bir şehir

Ve bu şehrin en imansız yeri

Ve bunların tamamı 

Veyahut hiçbiri (leri)

Seni sunmaktadır

Çelikten medeniyete

Tüm ihtişamıyla

Şehrin en mabedi alanlarına

Yığınak yapılıyorken

Çelikten ölüm uçları

En biçare savunmadır 

Sana olan duruşum

Şehir işgale maruzdur 

Napolyon düşer aklıma

Josephin’e düşkünlüğü

En umarsız savaşlarda 

Nehirlerden akan kanlarda

Kana kana 

Seni içmeleri

Dumanlar yükselir işgalden

İşgalden dumanlar yükselir

En hasat mevsiminde 

Talan edilir umutlar

Nadaslanır sevdalar 

Tek bir kıvılcıma 

Teslim olur koca şehir

Gözlerinin akından 

Görülmez beyaz bayrak

Karanlıklar basar beyazlığı

Sulh asılı kalır cellâdın ilmiğinde 

Ve bir şehir direnişe başlar gözlerinde

İşgalden yükselen kara bulutlar

Gökyüzünü kaplar usulca

Ve kaybolur yüreğindeki martı

Uçtukça gömülür bu karanlığa

Mahur Bir beste çalınmaktadır

Şehrin radyolarında 

Kesilir nağmeler

Besteler İşgali duyurur 

Şehrin radyoları

Senden uzak durmayı tembihler

Aniden belirsizleşir siluetin

Bir zayi ilanı düşer 

Çamurlara bulanan

Gazete sayfalarına

Yollara dökülür umutlar

Sırtlara vurulan öteberi

Ve çalınmış yaşamlarla

Vurulur yollara

Direniş savaşçılara kalır

Kaçış ise

Sen gibilere

Keskin bir sessizlik

Ve ardlara bakılmaksızın

En ucube gözyaşlarıyla

Terk-i diyar yaşatılır

İşgallerin şehrine

En ruhani duygular kırılır

Hırpani ruhlar sıyrılır bedenimden

Ve icad edilir ölüm

Mucidi sen

Yani

Giden Sen

Rayların çelik soğukluğunda ben

Yol uzar 

Ve sen kaybolursun

Geride kalan

Yıkık bir şehir

Bir işgal

Küllenen umutlar

Esarete mahkûm gözyaşları

İşgal hakikattedir

Bir şehir işgal altındadır

Bir ben işgaldeyim', 'Yaşanmışlığın En güzel serüveni olan Seni sevmekle başlamıştı Yüreğimin tarihi Ve sen benim tarihimdin Tarihler aynasında / atlasında Bu tar...', ARRAY['Türk Edebiyatı','Şiir','Tarhan Şimşek']::text[], 8.5, '{"poet":"Tarhan Şimşek","poet_slug":"tarhan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":188,"source_url":"https://www.antoloji.com/isgallerin-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin', 'sensin-gorkem-kaya-0n7fg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sahibi kayıp bir arayışın izi avuçlarımda, 

İstanbul gecelerinde tanıdık bir iz sürüyorum, 

Sokak lambalarını sayıyorum 

1,2,3......30...! 

Bir rüzgar esiyor hepsini söndürüyor 

ve başımda şimdi bir sürü bela var 

ama en büyüğü sensin 

Zaman çok hızlı geçiyor 

Beklerken büyümeyi 

Şimdi yetişemiyorum bile doğumgünlerime 

Polisler arıyorlar köşe bucak beni 

Şaka degil 

Posta kutuma kağıtlar bırakıyorlar 

Gelmem gerekiyormuş karakola kadar 

ve başımda şimdi bir sürü bela var 

ama en büyüğü sensin 

Bazan cok fazla özlüyorum siyah beyaz günleri 

Geçmişe ait tüm manzaralar TRT kokusunda, 

Yayın koptuğunda Bitlis İbriğini seyrettiğim günler, 

Diğer kanalda karşıma çıkacakmış gibi 

Bahar kokuyor yine gece 

Henüz açmadı evimizin önündeki ıhlamur 

Açacak o da zamanı gelince 

Bir yarayı arıyorum 

Aklımda Elmadağ ile el ele dolaştığım Taksim geceleri 

ve başımda şimdi bir sürü bela var 

ama en büyüğü sensin 

Şimdi başımda bir sürü bela varken düşünüyorum 

Ben miydim o 

Yoksa müsveddesi miydi insanın 

Fotokopi anılarım gözlerinin çekmecesinde 

Yumarsan gözlerini 

Yazarım bir satır daha bakışlarının düştüğü yere 

Dedim ya 

başımda şimdi bir sürü bela var 

ve bil ki en büyüğü sensin.

26 04 2004', 'Sahibi kayıp bir arayışın izi avuçlarımda,  İstanbul gecelerinde tanıdık bir iz sürüyorum,  Sokak lambalarını sayıyorum  1,2,3......30...!  ...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sensin-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz', 'soz-gorkem-kaya-dzefx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim olmayan bir sürü kelime var dilimde 

ve kimsenin olmayan bir sürü duygu gözlerimde.. 

Benim olmayanlar ile kimsenin olmayan 

kelimeleri yoğurursam ellerimle ve 

bir mürekkep izi yaşam bulursa 

herkese ait çizgisiz bir saman kağıt üzerinde.. 

Söz! 

Ben de imza atarım “ŞAİR” diye..

02 05 2005', 'Benim olmayan bir sürü kelime var dilimde  ve kimsenin olmayan bir sürü duygu gözlerimde..  Benim olmayanlar ile kimsenin olmayan  kelimeler...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/soz-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus pus', 'sus-pus-gorkem-kaya-itttz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bazı sabahlar sessiz kalır İstanbul 

Seni dinler 

Balıkçılar oltadaki balığa sus işareti yapar 

Parmak uçlarında gidilir işlere 

Bazı sabahlar sessiz kalır İstanbul 

Sen sus olursun 

Ben pus 

Yağmur yağar 

En çok dudaklarıma 

Bazı sabahlar ben İstanbul olurum 

Sen bana sessiz kalırsın 

Dudakların İstanbul’un ıslaklığında.

2003', 'Bazı sabahlar sessiz kalır İstanbul  Seni dinler  Balıkçılar oltadaki balığa sus işareti yapar  Parmak uçlarında gidilir işlere  Bazı sabahl...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kaya']::text[], 8.5, '{"poet":"Görkem Kaya","poet_slug":"gorkem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sus-pus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşırır', 'sasirir-gorkem-kaya-8o21i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakışlarında bir martı süzülür 

