INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarken Avunduğum Ninni', 'aglarken-avundugum-ninni-mehmet-tas-w5uyp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlarken avunduğum ninni

Gülerken  saçtığım gün ışığımdın.

Geceler dolarken ıssız odama

En onulmaz korkularımda

Üstüme çektiğim yorgan

Beklediğim sabahımdın…

Serin söğüt gölgelerinde

Güttüğüm kuzuların yorgunluğunu atarken

Ufukların ötelerine

Uzanan hayallerimdin.

Beklediğimdin, beklenenimdin…

Bir başıma çıktığım yolda

Heybemde bir kuru azık

Bir yudum su mataramda

Ve başımda kavak yelleri gibi esen

Bilmediğim görmediğim sendin…

Bir yağmur gibi indin

Kararan göklerin ardından

Can çeken gönül ırmağıma

Yeşeren otlarım sen

Yeni doğan filizim sen

Sen oldun bahar sevincim….', 'Ağlarken avunduğum ninni Gülerken  saçtığım gün ışığımdın. Geceler dolarken ıssız odama En onulmaz korkularımda Üstüme çektiğim yorgan Bekle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aglarken-avundugum-ninni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilesin Gülüm! ..', 'bilesin-gulum-dursun-elmas-9daif', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda yürek işi,bir heves değil

Seni unutmak mı,hiç mümkün değil

Sevgim sadakattir,bu bendeki aşk değil

İsmin en derinde, bilesin gülüm! ..

Seni sevdiğimi,sana yazamam

Yeminim var,yeminimi bozamam

Hakkım yoktur,asla sana kızamam

Yerin yüreğimde,bilesin gülüm! ..

Namerdim demişim, yazarsam sana

Bu saatten sonra ar gelir bana.

Muhabbet gönderdim,iç kana kana

İçimde saklısın,bilesin gülüm! ..

Mısralara gizlemişim adını

Silemedim,silinmiyor ay gülüm! ..

Başka yerde aramadım tadını

Sevda gözlerimde çilesin gülüm! ..', 'Sevda yürek işi,bir heves değil Seni unutmak mı,hiç mümkün değil Sevgim sadakattir,bu bendeki aşk değil İsmin en derinde, bilesin gülüm! .. ...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilesin-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Uykumdan Uyandıran Güneş', 'beni-uykumdan-uyandiran-gunes-ertugrul-sakar-48ayy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni uykumdan uyandıran güneş

Elimden tut Ankara '' da

Beni en sevdiğin tepelere götür

En sevdiğin yapraklara tak gönlümü

Nerede rüzgarlar varsa serin

Nerede renkler güzel ve derin

Neresiyse bulup göstereceğin

Bana nereyi layık görüyorsan

Hani çocukların salıncaklarına takıl

Hani zürafalar gibi hayran bakıl

Hani biraz şaşırsın akıl

Belki de bir Ankara Kalesi diyorsan

Elimden tut Ankara '' da

Ankara deyince seni hatırlayayım

Hayatı sevince seni hatırlayayım

Hani bir günün içine ne sığdırabiliyorsan

Ne varsa marifetin Ankara '' da

Birazda seninle yaşayayım

Beni en sevdiğin tepelere götür

Belki de rüzgar solursun Ankara ''da

Ya da dökülür müsün insanlarla

Sereserpe yürürken Kızılay '' da

Şelalelerine de konarsın Keçiören '' in

Deli gibi yaşamak istiyorum bu ayda

En sevdiğin yapraklara tak gönlümü

Sevdaların saçlarında kıvrılayım

Sende gör doya doya güldüğümü

Bugün Ankara '' da senin olayım

Ankara  dedin mi, ne Meclis, ne sitem, ne dert

Altın Park'' ta yörük çadırı olsun memleket

                           26.O8.200l / Keçiören', 'Beni uykumdan uyandıran güneş Elimden tut Ankara '' da Beni en sevdiğin tepelere götür En sevdiğin yapraklara tak gönlümü Nerede rüzgarlar va...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/beni-uykumdan-uyandiran-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen artık bana kapkaç mesafesi kadar bile yakın değilsin! ! ! ! ! ! !', 'sen-artik-bana-kapkac-mesafesi-kadar-bile-yakin-degilsin-ozan-rudolfo-w1v8z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevgilim sanıyorladı, lakin değildin,

En huzurlu ortamlarda bile sakin değildin,

Git uzaklara dizlerine başka enayi eğilsin,

Sen artık bana kapkaç mesafesi kadar bile yakın değilsin....', 'Seni sevgilim sanıyorladı, lakin değildin, En huzurlu ortamlarda bile sakin değildin, Git uzaklara dizlerine başka enayi eğilsin, Sen artık ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rudolfo']::text[], 8.5, '{"poet":"Ozan Rudolfo","poet_slug":"ozan-rudolfo","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-artik-bana-kapkac-mesafesi-kadar-bile-yakin-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sel olmuşum gidiyorum...', 'bir-sel-olmusum-gidiyorum-dilan-tan-1kbxq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Serin sokaklarda,

Derin gecelerde,

Karanlıklarda ıslıkların arkasına sıgınmıs korkak bedenim.

Sensizlik türküsü paylaşıyorum geceyle ağlaşıp.

Her nefeste,

Her adımda,

Beynimde sen, yüreğimde sen.

Ben sen olmuşum yürüyorum.

Bir sel olmuşum gidiyorum

Hiç olmuşum bitiyorum...', 'Serin sokaklarda, Derin gecelerde, Karanlıklarda ıslıkların arkasına sıgınmıs korkak bedenim. Sensizlik türküsü paylaşıyorum geceyle ağlaşıp...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-sel-olmusum-gidiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görüyorum', 'goruyorum-i-brahim-kilinc-r16wd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yazılmamış bir şiirin

Mısraları mı dilimde

Yaşanmamış bir sevdanın

Burukluğu mu içimde

Bestelenmemiş şarkının

Sözlerini duyuyorum

Açılmamış bir çığırdan

Sonsuzluğa yürüyorum

Bakışların aşkın dili

Gülüşlerin sevda gülü

Dünde yitirdim bu günü

Artık nuru görüyorum

Karanlıkta parıldayan 

Bir yıldızsın biliyorum

Ömrüm yetmez belki ama

Yine sana geliyorum', 'Yazılmamış bir şiirin Mısraları mı dilimde Yaşanmamış bir sevdanın Burukluğu mu içimde Bestelenmemiş şarkının Sözlerini duyuyorum Açılmamış ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/goruyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Yaşıyorum', 'kendimi-yasiyorum-herdem-ankara-fns68', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendimi Yaşıyorum

Yıllarca senin sesinle uyurdum,

Şefkatli kollarında olmayı, 

Sevdiğini anlamaya çalıştım. 

Seni kazandığımı sandım,

O günü unutmak istiyorum 

O karanlık kuyu varya anne

O yeri sildim tekrar döndüm hayata anne

Karanlık bir kuyunun içinde bir ışık vardı

Beni çağırıyordu 

Sen bunu yapamazsın yaşamalısın diyordu

Bak sana anlatırken bile 

Tüylerimi diken diken etti o karanlık kuyu

Biri var anne sana şimdi söyleyemediğim

Beni sen doğurdun ama o yaşatıyor ana

Sen de bil artık anne

O bir çiçek goncası 

O benim nazlı meleğim

Koklarken kıyamıyorum

Sevdiğini özlemek nedir bilirmisin anne

Ben onunla öğrendim anne 

Sevmeyi öğrendim

Yaşamayı seviyorum anne

Seninle de sensizde yaşıyorum 

Kendimi sevmeyi öğrendim anne

Kendimi buldum anlıyormusun 

Kendimi yaşıyorum artık anne

HERDEM

30/06/2005

13:25', 'Kendimi Yaşıyorum Yıllarca senin sesinle uyurdum, Şefkatli kollarında olmayı,  Sevdiğini anlamaya çalıştım.  Seni kazandığımı sandım, O günü...', ARRAY['Türk Edebiyatı','Şiir','Herdem Ankara']::text[], 8.5, '{"poet":"Herdem Ankara","poet_slug":"herdem-ankara","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kendimi-yasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kraker sevdalısı yarim', 'kraker-sevdalisi-yarim-ozan-rudolfo-lc693', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En sevdiği bisküvi çeşidi krakerdi,

Ayaklarının kokusu çok beterdi,

Koçbank sigorta şirketinde sekreterdi,

A benim kraker sevdalısı yarim..

Ne zaman bir şey atıştırmak istese hep kraker alırdı,

Çünkü o krakere inanılmaz bayılırdı,

Kraker onun için vazgeçilmez sayılırdı,

A benim kraker sevdalısı yarim..', 'En sevdiği bisküvi çeşidi krakerdi, Ayaklarının kokusu çok beterdi, Koçbank sigorta şirketinde sekreterdi, A benim kraker sevdalısı yarim.. ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rudolfo']::text[], 8.5, '{"poet":"Ozan Rudolfo","poet_slug":"ozan-rudolfo","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kraker-sevdalisi-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımasanda', 'tanimasanda-utku-demir-wyzg9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aklın ile kasların arasındaki mesafe ölçülemiyorsa

Düşüncelerin davranışlarınla eşgüdümleniyorsa

Hesaplaşmaların karşılaştırmalı değilse

ve

Kalbinle sen her an uyumlu dans edebiliyorsan

Beni tanımasanda bil ki hep yanındayım

Belki soluğunu donduran kutuplardayım

Belki tenini yakan ekvatordayım

ama yine de

Sevgimden bir parçayı, hak eden sana adamaktayım

Kelimelerin derinliğine dalabiliyorsan

Sessizliğin de manasını çözümleyebiliyorsan

Yerle göğü çok yakın görüyorsan

ve

Yaşamayı doludizgin seviyorsan

Beni tanımasanda bil ki hep yanındayım

Belki yerin hareketli kabuğundayım

Belki ıssız bir gezegende yalnızım

ama yine de

Gerçekliğe ulaşmanda sonuna dek yoldaşınım

Biliyorum algılayamasan da sıradan duyularınla

Hissediyorsun sen beni, benim hissettiğim gibi seni

Dertlerimiz derdimiz, acılarımız acımızdır

Mutlulukları ise hiç almayız hep vermekten yanayız

Çünkü biz sevilmeye değil sevmeye hayranız...', 'Aklın ile kasların arasındaki mesafe ölçülemiyorsa Düşüncelerin davranışlarınla eşgüdümleniyorsa Hesaplaşmaların karşılaştırmalı değilse ve ...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tanimasanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ha Eşek Ha Sen', 'ha-esek-ha-sen-ali-kilic-kakiz-rux7q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ecdat yadigarı, kervan saray han hamam. 

Buz gibi bir bardak ayran, kusursuz ikram. 

Her halde burada, bize de kalacak bir yer var. 

Adamın biri eşeğiyle, ahım şahım bir hana uğrar. 

Selam vererek hancıya der bu gece burdayım. 

Bilirmisin? üç dört gündür uzun bir yoldayım. 

Merak etme, hayvan için, sap saman arpa bol. 

Yediğin ve içtiğin kadar yemek, sen rahat ol. 

Ben ve eşeğe ne ödeyeceğim söylermisin bana. 

On beş bin versen kurtarır, indirimli hali bu sana. 

Kendisini, eşeğin hesabına katmaz ayrı öder. 

Bak bu benim için, ha buda şu eşek için der. 

Hancı der ki, ne farkeder ha sen, ha eşek canım. 

Hayır, hayatımda eşekle kendimi bir tutmadım. 

Tokat / 1973', 'Ecdat yadigarı, kervan saray han hamam.  Buz gibi bir bardak ayran, kusursuz ikram.  Her halde burada, bize de kalacak bir yer var.  Adamın ...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ha-esek-ha-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Ayrımı...', 'yol-ayrimi-tulay-sustam-e914y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen kaldırım taşlarını dize dur önüme

ben toprağa basa basa senden uzaklaşıyorum', 'sen kaldırım taşlarını dize dur önüme ben toprağa basa basa senden uzaklaşıyorum...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yol-ayrimi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul''da Bir Vapur', 'istanbul-da-bir-vapur-leyla-ayyildiz-85qwa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vakit; kavuşma zamanı,

Aylardan Haziran.

Bir adam bekliyor iskelede,

Gözlerine mavi düşmüş.

Gazetesi koltuğunun altında,

Omuzları yorgun,

Poyraza açık elleri titrek.

Bacakları mecalsiz.

Güneş; kırmızı bir top, 

Saklanacak Yeditepe’den birinin ardına.

Kafasının üzerinde tepsisi.

Yeni yetme bir çocuk bağırıyor,

‘Çıtır, çıtııır, akşam siimiiidiiii’

Yirmibeş kuruşluk umudunu sarıyor, 

Çeyrek gazete kağıdı arasına.

İstanbul kavrulmuş susam kokuyor.

Vakit; kavuşma zamanı,

Aylardan Haziran.

Bir adam bekliyor iskelede,

Köpük, köpük aklar düşmüş saçlarına.

Buğulu bakışları Boğaz’a dönük.

Bir sigara daha yakıyor.

Dumanında hasret tüten.

Kız Kulesi, şımarık bir yosma olmuş,

Oynaşıyor dalgalarla.

Gün batımında büyüyen gölgesi.

Raks ediyor sularla.

Kıyıda bir balıkçı, 

Maharetli elleriyle sarıyor misinasını,

Parlak gri pullar parlıyor kovanın içinden.

Bir martı havalanıyor Galata’nın üzerinden.

Kanatlarında tel tel sevda yükü.

Bir adam bekliyor iskelede.

Gözlerinde hüzün,

Boğazında kocaman bir düğüm.

Elleri titrek, bacakları mecalsiz.

Bana bir aşk masalı anlat İstanbul

İçine gelmiş geçmiş tüm aşkları sığdır,

Bana bir aşk masalı anlat İstanbul,

Dinleyeni titreten.

Bana bir aşk masalı anlat İstanbul,

Hiç unutulmayacak.

Vakit; kavuşma zamanı,

Aylardan Haziran.

Bir adam bekliyor iskelede.

Gözlerinde yılların yorgunluğu.

Yüzünde çizgiler.

Beyaz bir gelin salınıyor uzaklardan.

Eteklerinde deli dalgalı fırfırlar.

Kıvrıla kıvrıla süzülüyor.

Bir düdük sesi; sessizliği yarıp,

Sevinç çığlığı atıyor.

Vakit; kavuşma zamanı,

Aylardan Haziran.

Adam gülümsüyor.

İstanbul gülümsüyor.

Bir adam bekliyor iskelede.

Bir vapur süzülerek geliyor.

Eteklerinde deli dalgalı fırfırlar.

Rüzgara çırpmış bayraklarını.

Düğün oluyor, 

Şenlik kuruluyor.

Vakit; kavuşma zamanı,

Aylardan Haziran.

Bir vapur almış adamı,

Sevdasına yol alıyor.

Ay doğmak üzere,

Dalgalar laciverde boyanmış,

Güvertede bir adam,

Damağında taze çay yudumu.

İstanbul’u izliyor.

Vakit; kavuşma zamanı,

Aylardan Haziran.', 'Vakit; kavuşma zamanı, Aylardan Haziran. Bir adam bekliyor iskelede, Gözlerine mavi düşmüş. Gazetesi koltuğunun altında, Omuzları yorgun, Po...', ARRAY['Türk Edebiyatı','Şiir','Leyla Ayyıldız']::text[], 8.5, '{"poet":"Leyla Ayyıldız","poet_slug":"leyla-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/istanbul-da-bir-vapur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alçak', 'alcak-isik-aktas-3nr6u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir düş kurmuştuk Küba''ya,

sevdamız yarım kaldı ya,

içimiz acımıştı hani,

yüreğimiz kanamıştı,

birlikte ağlamıştık

imkansız aşkımıza.

Öyküler okumuştuk, şiirler yazmıştık bir zaman,

sonra Leyla Mısır''a gitmişti hani,

''gün biter, gülüşlerimiz kalırdı bizde'',

hani ben rüzgardım,

sen, okyanusta sarhoş bir gemi,

içimiz hazan olsa da,

sevdamız hala bahardı ya,

Ne oldu? 

Alçak! .... Alçak! .... Küskünüm sana

                                                              (27.07.2001-03.00)', 'Bir düş kurmuştuk Küba''ya, sevdamız yarım kaldı ya, içimiz acımıştı hani, yüreğimiz kanamıştı, birlikte ağlamıştık imkansız aşkımıza. Öyküle...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alcak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Öncesi', 'bayram-oncesi-mehmet-tas-pvtys', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Korlaşan akşamlarda bir hüzün sağanağı

Öksüz  kalmış gönlüme şimşek şimşek doluyor

Biz ikimiz

Yetim gönlümüzde saklı çaresizliğimiz.

Sen gözlerinde ki  yaşla

Benim vazgeçilmez hasretimsin.

Gülmem gülmene bağlıyken çocuğum

Senin hıçkırıklarında boğulur mutluluğum...

Gün gelecek,

Bayramlarda sevdalar kucaklaşacak

Zulmün çizdiği sınırlarda

Taş taş üstünde kalmayacak...

Sabır en büyük silahtır bilesin

Ve yalnız Allah’a güvenesin...

Bir gün batımı öncesinde

Ya da ilk ezan süslerken  dağların doruğunu

Göreceksin zulmün imanda nasıl boğulduğunu...

Sen Bakü’de garip

Kerkük’de öksüz çocuğum

Bu bayram içimde duymuyorsam

Anlamıyorsam çaresizliğini

Bil ki affedilmez suçluyum.

Gülmem gülmene bağlıdır dedim ya

Şimdi kilitledim tebessüme dudaklarımı

Sen gülmeden çocuğum

Hiçbir tebessüm okşamaz yanaklarımı.

Sen Gümülcine’de garip

Kırcali’de öksüz çocuğum

Hasretken Allahuekber sedasına semanın

Ben mil çekmez miyim gözlerine zamanın.? 

Bu kararan akşamlar bin hasrete gebeyken

Bayram sevinçlerimi mahkum ettim

Şimdi sevinçlerim kırık aynada saklı

İnan çocuğum

Gülmem gülmene bağlı...', 'Korlaşan akşamlarda bir hüzün sağanağı Öksüz  kalmış gönlüme şimşek şimşek doluyor Biz ikimiz Yetim gönlümüzde saklı çaresizliğimiz. Sen göz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bayram-oncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Öykü Anlattım Karanlıklara', 'bir-oyku-anlattim-karanliklara-mehmet-tas-xit0v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saatler durağan tik taklarında

Takvimler duvarları eskitiyor.

Gece erken iniyor  eteklerine dağların.

Kopup gelen karanlıklara

Bir öykü anlatıyorum

Kurtların solumaları doluyor satır aralarına

Ayrılık yaman kelime can

Ayrılıktan öte duramıyorum.

Gece korkulu bir düş dağ başlarında

Uyumak var 

Uyanmamak pahasına.

Yıldızlara yüklüyorum

Hasretten yana ne varsa türkülerimde

Yüreğimde hiç  sönmeyen bir ateş

Volkanlarla yarışıyorum.

Bir öykü anlatıyorum karanlıklara

Karanlık derin

Karanlık sessiz

Karanlık çıldırtasıya

Sesim yankılanıyor kayalardan

Rüzgarın kahrına inat

Sevdanla ısınıyorum.

Tutsağıyım bu dağların 

Çağrına uymaya gücüm yok şimdi.

Takvimler inatçı

Yollar kırk kuyu

Haramiler can istiyor baç diye

Şimdi selamımı yazdım gönülden

Kayan bir yıldızın kanatlarına

Mürekkebim  hüzündendi 

Hüzün ki gönlümde bir dağ çiçeği

Seni yüreğine emanet ettim

Yüreğin sevdama değişmez mekân

Bu dağları aşıp gelemezsem 

Gelip de sevdanı bulamazsam 

Yitik bir diyarın öksüz çocuğu

Mavi sularına denizlerinin

Akça sevdasını yolladı diye

İnen gecelerde dinle öykümü

Bir öykü anlattım karanlıklara', 'Saatler durağan tik taklarında Takvimler duvarları eskitiyor. Gece erken iniyor  eteklerine dağların. Kopup gelen karanlıklara Bir öykü anla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bir-oyku-anlattim-karanliklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Ve Karanlık', 'gunes-ve-karanlik-isik-aktas-ovkin', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneş, 

her akşam battığı gibi,

her sabah doğuyor yeniden.

ve her bitiş,

yeni bir başlangıç,

ya da her ölüm

yeniden bir doğumu getiriyor,

her şeye üzengi vurunca da işte,

hayat çekilmiyor.

bırak kendini o zaman,

yaşam ne ki,

göz açıp kapayıncaya kadar 

geçiyor zaman,

bırak kendini aşkın kucağına,

bitirirken birini, koş yeni yaşamlara.

şimdi seviyorum işte deniz''i

beni sevdiği için.

merhaba,

merhaba,

merhaba.

                (17.05.2005/Salı-22.15)', 'Güneş,  her akşam battığı gibi, her sabah doğuyor yeniden. ve her bitiş, yeni bir başlangıç, ya da her ölüm yeniden bir doğumu getiriyor, he...', ARRAY['Türk Edebiyatı','Şiir','Işık Aktaş']::text[], 8.5, '{"poet":"Işık Aktaş","poet_slug":"isik-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gunes-ve-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen Kaldın', 'bir-sen-kaldin-murat-demir-ulk4h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerime baka baka

Kalmadı ki incitmeyen

Yüreğimi yaka yaka

Bir sen kaldın terk etmeyen

Hiç fark etmez sende bırak

Ben alıştım gel sende yak

Bu gün değil belki yarın

Nasıl olsa bu olacak

Tersi olur sanmıyorum

Artık iyi anlıyorum

Havadandır ıslaklığım

Sen sanma ki ağlıyorum

Hangi yöne dönüp baksam

Kimse yok ki taş atmayan

Sapanına sıkıştırıp

Bir sen kaldın fırlatmayan

Tut dalımdan tutta kopart

Hiç fark etmez sende tut at

Daha fazla geç kalmadan

Bu defteri sende kapat

Nasıl olsa bu olacak

Bu aşk bir gün son bulacak

Ayrılığın nevalesi

Masamıza konulacak!', 'Gözlerime baka baka Kalmadı ki incitmeyen Yüreğimi yaka yaka Bir sen kaldın terk etmeyen Hiç fark etmez sende bırak Ben alıştım gel sende ya...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-sen-kaldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Verseydin', 'umut-verseydin-sair-gaddar-16-ow4lg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Peşinden geldim olmadı,

Kalbimi verdim olmadı,

Konuşmaya çalıştım olmadı,

Ne olurdu be ezgim biraz umut verseydin.

...

Kalbim kırık parçalanmış,

Hayat insana herşeyi yaparmış,

ßen hayattan değil senden aldım,

Ne olurdu be gülüm biraz umut verseydin.

...', 'Peşinden geldim olmadı, Kalbimi verdim olmadı, Konuşmaya çalıştım olmadı, Ne olurdu be ezgim biraz umut verseydin. ... Kalbim kırık parçalan...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/umut-verseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkındalıklar -II-', 'farkindaliklar-ii-gulay-yildiz-rmbhc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gök ve de bir yer soluklandığın; 

Memleket; 

İçine yol diye mısra kazıdığın

Kutsal kan 

Amini bol dualar toprağın

Kılıksızdan hatta lanetliden sakındığın...

Gömülen

Anne ve gözyaşı; 

Sadece şehit değil...

Uçsuz ve hani derler ya bucaksız

Acı bu! 

Tarif bu! 

Kılıksız ve lanetli; 

Bilsen diyorum haddini

Ve çek artık kutsaldan elini...', 'Bir gök ve de bir yer soluklandığın;  Memleket;  İçine yol diye mısra kazıdığın Kutsal kan  Amini bol dualar toprağın Kılıksızdan hatta lane...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/farkindaliklar-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mangal Keyfi 3', 'mangal-keyfi-3-ali-osman-yilmaz-7m2d9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'MANGAL KEYFİ (3)  

Siz  küçük bir çocuğun neler düşleyebileceğini hiç düşündünüz mü? Hele bir düşünün şöyle.Biz 68 kuşağı gençliğini oluşturan yaş gurubunun çocukluk ve yetişme yıllarındaki  yaşadığı koşulları ve o koşullardaki yaşam biçimimizi  bir düşünün önce. Öyle kolayına kaçmadan  ama.

	Küçük bir çocukken ve babaannemin esareti altındayken,neler yaşadım neler.Aslında esaret gibi görünen yaşamımın ne büyük dersler almama sebep olduğunu yıllar sonra anladım.

	Bizim çocukluğumuz teknoloji yoksunluğu içerisinde geçti.Yalnızca evlerde

Radyo,pikap bulunur,arasıra da özellikle yaz mevsimlerinde açık alanlardaki yazlık sinemalara giderek eğlenmeye  çalışırdık.Hele  mevsimsel olarak gelen,hıdrellez, bahar  aylarına özgü piknik gezmeleri  olurdu ki her bir piknik ayrı bir öykü olurdu.

	O zamanlarda biz erkek çocuklar,bizim orada cilli denir,misket oynamaya bayılırdı.Birde döndürek oynardık ki,şimşir döndüreği olanlar takoz döndürekleri kırmak ve  gol atmak için   elimizden ne gelirse  yapardık.Oynadığımız oyunlarda kullandığımız oyuncakları genellikle kendimiz tasarlar ve yapardık.Yani oyuna göre oyuncak tasarlardık.Karamela kağıtları,alt mı,üstmü oyunları? Daha neler neler.

	Arada çeşitli satıcılar mahallemize geldiklerinde başlarına toplanır,parası olanlar,koz helva,pamuk helva,kancık helva,çalgılı macun,manili damla sakızı,ve illede tatar ramazanın  o tekerlemeleri ile süslü bol şerbetli tatlısından yerdik.Yaz ayları geldiğinde elle çevirerek yapılan o olağan  üstü dondurmalar olurdu ki gerçekten bu gün yapılabilse,yapana bir servet kazandırır.Bizim oranın kazan simidini de yabana atamayız.Bu yaşa geldim en  büyük tüketim malzemelerinden  biridir hala. Susamlamadan önce kaynayan kazandaki suya atılır ve sonra susamla kaplanarak fırına verilir,nefis bir doyum malzemesi olurdu.

	Birde mahallemizde kaç göç yoktu.Oyun oynarken tüm evlerin kapıları kilitli olmadığı için dalardık içeriye ve evden eve geçerek çeşitli oyunlar oynardık.Böyle zamanlarda girdiğimiz evlerde nahoş olaylara tanık olur,akşama bir güzel dayak yerdik.Evin erkeği,bir ara fırsat bulur evine gelir ve odasında karısıyla kaçamak yapar sevişirdi.Bizim o sevişmelerden ne haberimiz olsun ki.Dalarız evden içeri,o evin çocuğuyla birlikte,dalarsın odaya,hayda o da ne,Yatakta arkadaşımızın babası, annesini yatırmış,cıs cıbıldak sevişmekteler.Derhal oradan kaçardık amma,akşam olunca ne yapsan kulakların çekilir,bazende dayak yerdik.Adam fırsat bulmuş eve gelmiş,o arada karısıyla sevişecek,sen çocuk  oyununla adamın sevişmesinin içine   edeceksin. Olur mu ya? O nedenle öyle zamanlarda,akşam olmadan önce ben babaanneme gidip  durumu anlatır ve dayak   yemekten kurtulmaya çalışırdım.Çoğu kezde dayak yemez ve babam benim yüzümden babaannemden fırça yerdi.Ne olsundu ki,adamda kapısını kitlesin,bunlar çocuk,ne anlarlar sevişmeden,evde kimse  varmı yokmu  bakarlarmı? utanmadan şikayetmi ediyorlar,vallahi onlara öyle şeyler söylerim ki,insan yüzüne çıkamazlar.Babam dişlerini sıkarak bana bakar,dayak yememenin garantisiyle babaannemin kucağına iyice sokulurdum.

Baba annem gerçekten osmanlı kadınıydı.Ne sözünü esirger,ne hakkı olanı ayırır, nede dostlarını kayırırdı.Hatta bir keresinde teyzem eve gelmiş yüzü alı al,mor bir haldeydi. abaannemin öfke dolu kükremesiyle neler oluyor diye kapı aralığından baktım. Teyzemi karşısına almış “”be hey allahtan korkmaz,kuldan utanmaz,Sen kadın değilmisin,sen olmasan kocanın erkekliği ne işe yarar,Kocan olmasa senin kadınlığın ne işe yarar.Kadın ve erkek bir elmanın iki yarısıdır.Ancak  ikisi bir arada olunca bütün olurlar,sen hala bunu bilmezmisin? ”diye söyleniyordu.Teyzem  ama diye söylenecek oldu.”Bak beni iyi dinle domuz şey,geçen gün oğlunu kızlarla sarmaş dolaş görmüşler,hani o fındık fatma parkta mı ne görmüşte günde sana söylemişti. Sende gubarmış,eh babasının oğlu,çapkın çocuk diye öğünmüştün.Peki senin oğlan ahmet’in konuştuğu kızın ailesi yokmu,o ailenin şerefi yokmu,oğlun olunca gubar, kızın bir erkeğin elinden tutunca orospu muamelesi yap,olacak şeymi bu.Sen kocanla azmı gizli gizli buluşurdun,sen şimdi orospumu oldun.Hayır.Öyleyse kızına neden zulmediyorsun.Alırsın karşına bir güzel anlatırsın.Öyle alemin gözü önünde gezmemesini,el ele,yanak yanağa görünmemesini ve dikkatli olmasını söylersin, Şimdi  anlıyorum,senin kız müyesser kaç gündür yüzünü  göstermeden geçip gidiyor.Sanki topallıyordu da,yoksa kız hınzır,o yüzdenmi dövdün kızını” diye sordu.Teyzem evet dedi  başını öne eğerek.Mualla hanımlarda gün vardı.Orada konuşurken  içeri firdevs girdi,kısırdan tam bir kaşık almıştım ki demesin mi? Kız,semiha,benim adam senin kızı temenyeri parkında bir oğlanla sarmaş dolaş görmüş,nerdeyse öpüşeceklermiş,   senin  kız fingirdek bir şey galiba,onu  biraz dizginle yoksa kucaklarda gezer billahi.Başımdan aşağı kaynar sular döküldü sanki.Nasıl oldum bilemezsin.

	Kız sende çok avalak bir şeysin dedi babaannem.Firdevs’in ağzını tıkayamadın mı? Ayol o zilli,düğününden beş ay sonra doğurdu da ne dedikodular çıktıydı.Dua etsin bana.Herkesin ağzını kapamıştım.Şimdi o zilli kendi yaptıklarını unutuyor,elin kızının gezdiği arkadaşları için dedikodu mu yapıyor? Ben onu bir göreyim bak nasıl benzeteceğim.Hem artık öyle hamamda kız beğenmek,görücü  usulü evlenmek  bitti,şimdi gençler tanışarak evlenmeye bakıyorlar.Eh gezerken de azıcık sevişip koklaşıyorlar da.Ne varmış bunda.Ateşle barut yan  yana ne kadar durabilir ki? 

	Teyzem “eh sen böyle diyorsun,ama babası bir duyarsa dayaktan bir yerlerini kırar,ondan korkuyorum.Sus dedi babaannem,sende erbab ol,duyurma adamına. Birşey söylerse de,sen beni azmı sıkıştırmıştın,zorla azmı öpmüştün falan deyiver,ağzını kapat.Kızına da söyle öyle aleni yerlerde oğlanlarla gezmesin,dikkat etsin.Sonra gizli ilişkiden burunsuz çocuk doğar deyiver.Teyzemin yüzü allanıvermişti.

	Teyzem,Tamam koca anne diyerek evden çıktı.Babaannem homurdanarak mutfağa yöneldi.Birde, bizim gizli saklıyerlerde gördüklerimizi,babaannem bilse kimbilir neler söylerdi.Ama olsun,bilmesi gerekmez.Mahallemizin kızları ve gençlerinden bu yüzden az harçlık almazdık hani,sus payı olarak.Ama bizim amca oğlu vardı ki,hem harçlığı alır,hemde gider herkese söylerdi.O yüzden amca oğlunu kimse sevmezdi.Kimse artık para vermediği için beş parasızdı  ve ne alırsak, elimizdekinden o da isterdi.Müzevirlik ne kötü bir şeymiş.', 'MANGAL KEYFİ (3)   Siz  küçük bir çocuğun neler düşleyebileceğini hiç düşündünüz mü? Hele bir düşünün şöyle.Biz 68 kuşağı gençliğini oluştur...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mangal-keyfi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlan', 'i-lan-oguzkan-bolukbasi-5n5jb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'www.oguzkanbolukbasi.net i tıklayınız, artık bir web sayfam var, ve oraya bir kaç kelime yazıp, bu gezegende yalnız olmadığımı, beni tanıyan ve sevenlerin olduğunu bana bininci kez gösterin lütfen, ve zaman zaman ziyAret ederek beni eleştirin, sevgiyle kalın

oğuzkan bölükbaşı', 'www.oguzkanbolukbasi.net i tıklayınız, artık bir web sayfam var, ve oraya bir kaç kelime yazıp, bu gezegende yalnız olmadığımı, beni tanıyan...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ilan-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönek Dünya', 'donek-dunya-muhammed-salih-tasova-3rrb1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlatsam derdimi kimse anlamaz

Perişan halime gölgem acımaz

Ölsemde arkamdan bir kul ağlamaz

Bıktım, usandım şu Dönek Dünyadan

Dönek Dünyanın, Dönek insanı; 

Bu bir nağmedir belki hiç hatırlanmayacak

Onurum kırılsa bile ummayacak

Görülecek bir hesabım var belkide

Yüreğim sonsuza dek hiç anılmayacak.

Er odurki Dünyaya koya bir eser 

Esersiz kişinin yerinde yeller eser...', 'Anlatsam derdimi kimse anlamaz Perişan halime gölgem acımaz Ölsemde arkamdan bir kul ağlamaz Bıktım, usandım şu Dönek Dünyadan Dönek Dünyanı...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Salih Taşova']::text[], 8.5, '{"poet":"Muhammed Salih Taşova","poet_slug":"muhammed-salih-tasova","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/donek-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anektodlar 8', 'anektodlar-8-cemil-aygen-yapwr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim minik kedim

Seni nasıl uyandırsam

Kafanda oturup saz mı çalsam

Mart ayı yatmak ayı değil 

Sevişmek ayı olduğunu anlatsam', 'Benim minik kedim Seni nasıl uyandırsam Kafanda oturup saz mı çalsam Mart ayı yatmak ayı değil  Sevişmek ayı olduğunu anlatsam...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/anektodlar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anektodlar 9', 'anektodlar-9-cemil-aygen-kup2m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ohh be

Nihayet sabah oluyor

Şu lanet karanlık geceye

Bir türlü alışamadım

1 haftadır elektrikler yanmıyor', 'Ohh be Nihayet sabah oluyor Şu lanet karanlık geceye Bir türlü alışamadım 1 haftadır elektrikler yanmıyor...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/anektodlar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlarmısın', 'hatirlarmisin-sair-gaddar-16-d3fnj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ßir zamanlar seni sayıklayan,

Sevilmesi için herşeyi yapan,

Sevgisinin karşılıksız olduğunu anlayan,

ßi garip şair vardı hatırlarmısın.

...

Seni sevdiğini haykıran

Senin için engeller aşan,

Hayatını sana adayan,

ßi garip şair vardı hatırlarmısın.

...

Yaşlı gözleriyle şiirler yazan,

Her mısrasında ismini yazan,

ßide varki kırık  kalbi olan,

ßi garip şair vardı hatırlarmısın.

...

Sıcak yuvasından ayrılıp,

Senin kollarına koşan,

Ama hep sensizliği yaşayan,

ßi garip şair vardı hatırlarmısın.

...

Sevdiğini bilip sevmediğin,

Yaşlı gözlerini görüp üzülmediğin,

Seni canından çok sevdiğini bildiğin,

ßi garip şair vardı hatırlarmısın.

...

Sensizliğin ölüm olduğunu söyleyen,

Ve hergün binlerce defa ölen,

Son kelimelerinde bile ezgi diyen,

ßi garip şair vardı hatırlarmısın.

...

ßir kelebek kadar masum,

Azrail kadar gaddar,

Ve seni seviyorum ulan Allah''ına kadar diyen,

ßi garip şair vardı hatırlarmısın.

...

Sevildiğini bilipte sevmediğin,

Zaten yaralıydı bide solundan yaraladığın,

Sevdanla kandırıp yaktığın,

ßi garip şair vardı hatırlarmısın.

...

Hasretinle yaşayıp,

ßenim olacaksın diyen,

ßi ömür sevip,karşılığını görmeyen,

ßi garip şair vardı hatırlarmısın.

...

Hasretine dayanamayıp seni görmeye gelmişti,

O kadar mutlu ve sevgi doluydu ki bilemezsin,

Son kelimelerin di ona,

Sevmiyorum demiştin hatırlarmısın.

İşte o an milyonlarca kez canını,

Aldın hayatını yıktın,

Duygularını çaldın,

Öyle bi acıdıki içim,

Topuklarımdan dinamitleseler,

ßu kadar acı duymazdım,

Ve o an seni sevdiğini,

Ve bi ömür boyu seveceğini söyleyen,

ßi garip şair vardı hatırlarmısın.

...

hatırla ezgim unutma...gaddar', 'ßir zamanlar seni sayıklayan, Sevilmesi için herşeyi yapan, Sevgisinin karşılıksız olduğunu anlayan, ßi garip şair vardı hatırlarmısın. ... ...', ARRAY['Türk Edebiyatı','Şiir','Şair Gaddar__16']::text[], 8.5, '{"poet":"Şair Gaddar__16","poet_slug":"sair-gaddar-16","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/hatirlarmisin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle mi! / üşümüyorum /geçmiş zaman şiirleri...', 'oyle-mi-usumuyorum-gecmis-zaman-siirleri-zafer-zengin-etnika-qdp8h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen

den

sonra



sen 

o martıları anlatan kadınsın

boş çığlıklarını gri gökyüzünde

sen 

o sıcaklığı anlatan kadınsın

geceyi süzen boş gözlerle

sen 

o yangınlar anlatan kadınsın

gidişinden sonra dönmeyen

sen

o sevdayı anlayan kadınsın

sevdim mi hüzünlerde bırakmayan

sen şimdi

dönüp geriye 

affet diyorsun öyle mi

sen şimdi

terk et yalnızlığı

sar beni diyorsun öyle mi

sen şimdi

büyü artık 

aşk acısı dokunmasın diyorsun öyle mi

sen şimdi

ellerin küçük

sen üşüdükçe 

ben üşüyorum diyorsun öyle mi

peki 

kim bıraktı içime

bunca acıyı 

kim yaraladı gülen gözlerimi

hepsi senin içindi 

ondan gittim diyorsun öyle mi

gittiğinde beri

içimdeki sen bitmedi

şimdi

bir gül gelip

kendini sevdirdi

öylesine sıcak ki elleri

üşümüyorum...

07 03 2005', 'sen den sonra sen  o martıları anlatan kadınsın boş çığlıklarını gri gökyüzünde sen  o sıcaklığı anlatan kadınsın geceyi süzen boş gözlerle ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/oyle-mi-usumuyorum-gecmis-zaman-siirleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-nihal-gungor-lact3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Peynir verdim kediye,

yemedi.

Bu kalabalık,bu insanlar,

ağlayan yüzümü görmedi.

El salladım yolculara,

kucak açtım koşan çocuğa,

nafile.

Yalnızlık dedim bu halimin adına

Yalnızlık dedim ben de.

Güldüm,gülücükler dondu kaldı,

yüzümde.

Ağladım,gözümden hiç yaş akmadı.

Ne güldüğümü anladılar,

ne ağladığımı.

Yanlışlık dedim bu hallerinin adına

Yanlışlık.

                                26.10.96', 'Peynir verdim kediye, yemedi. Bu kalabalık,bu insanlar, ağlayan yüzümü görmedi. El salladım yolculara, kucak açtım koşan çocuğa, nafile. Yal...', ARRAY['Türk Edebiyatı','Şiir','Nihal Güngör']::text[], 8.5, '{"poet":"Nihal Güngör","poet_slug":"nihal-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizlik-253-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimize Bir Dünya', 'i-kimize-bir-dunya-cemil-aygen-23zb3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel seninle arkadaş olalım

Ben hayatın iyi yanı olayım

Sen eğlenceli yanı

Kötüyü katmayalım aramıza

İyiyle eğlenelim gülelim

Aklımızda hep iyi şeyler olsun

Pişmalık hasretinden çatlasın 

İyinin ne olduğunu 

Bizi gördükçe anlasın

Elele olalım...Hiç ayrılmayalım

Birbirimize anlattıklarımız

Okuduğumuz şiirler gıdamız olsun 

Sevgimiz bizi yaşatsın 

Bahçemizde güzel çiçeklerimiz olsun

Etrafımızda yığınla dostlarımız

Her gördüğünde bize alkış tutan

Bizi anlayan yığınla insan 

Biz gözlerimizi açtığımızda

Bütün bunları görelim

Sadece sevgiye doğruya inanalım

Yanlışı olmayan...Birbirini seven

İki yüce insan olalım 

Sevgimiz hiç azalmasın 

Hadi varmısın 

Bu güzel dünyayı 

İkimiz yaşatalım...Yaşayalım

Varmısın ikimize bir dünya yaratalım...', 'Gel seninle arkadaş olalım Ben hayatın iyi yanı olayım Sen eğlenceli yanı Kötüyü katmayalım aramıza İyiyle eğlenelim gülelim Aklımızda hep i...', ARRAY['Türk Edebiyatı','Şiir','Cemil Aygen']::text[], 8.5, '{"poet":"Cemil Aygen","poet_slug":"cemil-aygen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ikimize-bir-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ke ke me', 'ke-ke-me-zafer-zengin-etnika-m2rlx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kekeme

Bilmezdim sıfatlar nerede saklanır

Fiiller zamirler kimin elinde

İmla mı

Adını duymuştum köyüm yanarken

Derler di bana; kaç

Ateş sevmez insanı

Keşfinden beri

Yakar elini ayağını

Sevmezdi beni de

Gözlerini suyla sildiğimden beri

Kekemeyim

İçimi anlatsam

Bir yüzyılınız varsa

Ve biraz dante kadar ömrün  yarısı

Gençliğimi

Pek erken yaşta

Yaşı kuruttuğumu

Susuzluğu elimde tuttuğumu

Dilimin kuruduğunu

Anlatayım

Var mı ömrünüzden ömrüme

Günleri peşkeş çekmek

Asıldı yüzünüz

Biliriz

Bir şair kadar dinlemez bizi kimse

Kekeme koşmasını alnımıza vurup

Ter diye kelimeler döküp

Beni anlalarda boğulmamız

Siz kaçın

Suyu size dokundurmayız

Kaçarlar tümden

Döner dolaşır

Sokağı boş bırakılmış şehrin insanı

Sevda bulamazsa

Tanrıya sığınır

Emzirir dudağına aşk takanları 

Büyüdükçe asiler

Asileştikçe büyürler

Benlere kapılıp

Bu dünyayı ben yarattımlarda

Peşlerine takarlar karizmayıda

Kırılır elbet

Her yaş büyüdükçe içine

Çöker damarları tenine

Kas erir

Yüz gülmez

Huysuz günler gelir yerine

Kekemeyim

Size kendimi anlatacakken

İnsana kaçtı kelimelerim

Ne olur sizde ateşe gülmeyin

Ateş kekeme yanar demeyin

Dostu yokken

Ne şirin şeysin sen deyin

O zaman görün

Bir lal’ın dilinden

Kutsal metinler

Nasıl dökülür

Hep suyla

Hep suyla sınadık seni

Ey kekeme

Mavinle kudret

Sarı kırmızınla ağır ağır

İsli yanmaların

Kattık içine suyu da

Bulut ettik

Çocuklara gösterdik

İşte tanrı

İşte suydu dedik

Onlar ki; 

İki kapı görseler

Karar veremezler

Hangi göz açık

Hangisi kaçık

Korkarlar biraz

Delilikten

Kekemelikten

Şair kendiyle dalga geçer

İşte bu yüzden

Yüzdeki o gözlerden

Ateş sevmez insanı

Gözlerini suyla sildiğimden beri

İçini yakarda

Suyla silinmeyi sevmezdi

Ateş

Bizim kadar kekemeydi

Şimdi susun

Kekeme nasıl ağlar

Anlatacağım

Ateş gel yanıma canım

Zaman lazım

Anlatmalara ah’la başlayacağım

11 06 2004', 'Kekeme Bilmezdim sıfatlar nerede saklanır Fiiller zamirler kimin elinde İmla mı Adını duymuştum köyüm yanarken Derler di bana; kaç Ateş sevm...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/ke-ke-me-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A - Zalim (vezni aher)', 'a-zalim-vezni-aher-mikdat-bal-z3c5c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatı.................boyunca............zulüm..............etmiştir

Boyunca...............uzanıp................öyle..............gitmiştir

Zulüm................öyle...................kalmaz, işi........bitmiştir

Etmiştir..............gitmiştir.............bitmiştir...........zalim

Gittiği yer...........feci....................artık.................yatmıştır

Feci...................azapları.............kendi................tatmıştır

Artık...................kendi................etmiş kendi.......çatmıştır

Yatmıştır,...........tatmıştır............çatmıştır.............zalim

Amel..................defterini...........soldan................alınca

Defterini.............alıp..................öyle.....................kalınca

Soldan...............öyle.................cehenneme........dalınca

Alınca.................kalınca...........dalınca.................zalim

Mikdat der..........her zalim........bir gün...............yıkılır

Her zalim............ateşte............mutlak................yakılır

Bir gün................mutlak...........zalim, zulüm.......yok olur

Yıkılır,..................yakılır..............yok olur..............zalim.', 'Hayatı.................boyunca............zulüm..............etmiştir Boyunca...............uzanıp................öyle..............gitmişti...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zalim-sematik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimler', 'resimler-nihal-gungor-vodu8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her biri birer birer 

sömürür duygularımı

''''Bitmedimi sürgünün

gel yanıbaşımıza''''derler.

Bulmuşum ben yolumu,

hepiniz gibi.

Çok özlem çeksem bile,

vurmayın yüreğime gelemem.

Resimler beni çağırır.

Resimler savurur duygularımı,

perişan eder.

Resimler bana küser.

Çok özlem çeksem bile,

vurmayım yüreğime gelemem,

geçmişe dönemem.

Biliyorum orada duruşunuz sahte.

Bulmuşum ben yolumu,

hepiniz gibi.

Ben gelsem siz yoksunuz ki.

                     11.12.94', 'Her biri birer birer  sömürür duygularımı ''''Bitmedimi sürgünün gel yanıbaşımıza''''derler. Bulmuşum ben yolumu, hepiniz gibi. Çok özlem çeksem...', ARRAY['Türk Edebiyatı','Şiir','Nihal Güngör']::text[], 8.5, '{"poet":"Nihal Güngör","poet_slug":"nihal-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/resimler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Faruk Beyimiz', 'faruk-beyimiz-abdulhakim-ozturk-771uh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Faruk Bey

Fakiri görünce gözleri yaşlardı

Ya Allah deyip güne başlardı

Lokmasını paylaşıp, yardım düşlerdi

Dar günde halkımıza bel olurdu Faruk Bey

A tandan almıştın vatan sevgini

Özünden görmüştün birlik kavganı

Soyundan kapmıştın güzel övgünü

Huzur dağına bu bahar göç ettin Faruk Bey

Ruhumla duyarım sana saygımı

Dilim kalpten alıp söyler duygumu

Layık olamazsam gör bak kaygımı

Sen gidince göz yaşımız sel oldu Faruk Bey

Uçar kuşlar gider cennet bağına

Yakan ateş olur şerle yatana

İnşallah gidersin Kevser başına

İrem bağı ebedi yerin olur Faruk Bey

Kudretli ellerini öpmek isterdim

Gönlümde yerini yapmak isterdim

Bilgini sevgini kapmak isterdim

Bizimleyken kıymetini bilemedik Faruk Bey

Ne kalem yeter seni yazmaya

Ne kağıt yetişir övgün yazmaya

Abdulhakim alışıyor sensiz kalmaya

Gittiğin yerde mekanın cennet olsun Faruk Bey

		Abdulhakim ÖZTÜRK

		      HAZİRAN 2005', 'Faruk Bey Fakiri görünce gözleri yaşlardı Ya Allah deyip güne başlardı Lokmasını paylaşıp, yardım düşlerdi Dar günde halkımıza bel olurdu Fa...', ARRAY['Türk Edebiyatı','Şiir','Abdulhakim Öztürk']::text[], 8.5, '{"poet":"Abdulhakim Öztürk","poet_slug":"abdulhakim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/faruk-beyimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırgınım', 'kirginim-ali-i-nal-q7mt0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kırgınım hayata

hayata ve insanlara

reva imiş bana

hapsedilmek bu yaşama

nasıl olurdu kimbilir

olmasaydım bu diyarda

hiç çekmemiş olsaydım

herşeyden beni soğutan

olmadık acılara boğan

o hayal kırıklıkları

ihanetler

ve ihanetleri edenler

görmeseydim hiçbir zaman

umut ettiren, 

acı çektiren,

o güzel ama sahte

o gözlerin

içimi delen

o derin bakışlarını

duymasaydım keşke

her daim beynimin içinde

beni benden 

ve beni senden

belkide herkesten

insanlığımdan soğutan

o bildik yalanları

iftiraları

İsyan da neymiş

nesine isyan edeyim senin

ey hayat

layık olan sana

seninde bize layık gördüğün

ancak ve ancak

yalnız ve mutsuz

üstelik umutsuz

bırakıp gitmek seni...', 'kırgınım hayata hayata ve insanlara reva imiş bana hapsedilmek bu yaşama nasıl olurdu kimbilir olmasaydım bu diyarda hiç çekmemiş olsaydım h...', ARRAY['Türk Edebiyatı','Şiir','Ali İnal']::text[], 8.5, '{"poet":"Ali İnal","poet_slug":"ali-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kirginim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlerim ''Gözlerim'' Engel tanımaz!', 'ozlerim-gozlerim-engel-tanimaz-ozan-si-ar-agdasan-zh4lp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GÖZLERİM ENGEL TANIMAZ! 

Gözlerimden engelliyim

ÖZLERİM Engel Tanımaz! 

Umudun türkü teliyim

SAZLARIM Engel Tanımaz! ...

Nakarat:

                 Meşaleyim kar değilim 

                Ufkum geniş, dar değilim

                Gönlüm görür, kör değilim

                GÖZLERİM Engel Tanımaz!

Şafak doğar kucağımdan

Mumlar yanar ocağımdan

Tutulsam da bacağımdan

DİZLERİM Engel Tanımaz! 

Ne dilsizim, ne sağırım

Duyarlıyım vardır ağrım

Çağdan çağa gider çağrım

İZLERİM Engel Tanımaz! 

Karlı dağları aşarım

Özgürce coşar, taşarım

Bir gün toprağa düşerim

TOZLARIM Engel Tanımaz! 

Yürek özürlüsü dolu

Kapatırlar bize yolu

Şah Turna’nın susmaz dili

SÖZLERİM Engel Tanımaz! ...

Meşaleyim kar değilim

Ufkum geniş, dar değilim

Gönlüm görür, kör değilim

GÖZLERİM Engel Tanımaz! ...

Söz ve Müzik: Halk Ozanı Aşık  ŞAHTURNA   www.sahturna.com

Yorum: Ozan ŞİAR Ağdaşan

Vokal: ŞİRİN ŞAFAK Ağdaşan Müzik Grubu

Sevgili şiir, türkü dostları,

Bu yapıtımızı yüreği aydınlık, gönlü gören canlara adıyoruz. En başta da gönül, sanat ve bilinç gözüyle gören değerli Kadın sanatçı ve yazarımız Ozan ŞAH TURNA Aşık VEYSEL üstatlara adıyorum.

Kuşların kanadında sevgiler yolluyoruz bestelerimziden ve şiirlerimizden,. Bakıp ta göremeğen, bakar körlere ibret olurcasına.

Yıllardır karanlıklara ışık saçan Ozan Şah Turna üstad, umut, sevda, dirlik, birlik ve direnç türkülerinin sembolü oldu seçkin kadın ustamız olarak. 

Sevgiyle kalın, umudunuz solmasın...! 

www.siarcan.com', 'GÖZLERİM ENGEL TANIMAZ!  Gözlerimden engelliyim ÖZLERİM Engel Tanımaz!  Umudun türkü teliyim SAZLARIM Engel Tanımaz! ... Nakarat:           ...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ozlerim-gozlerim-engel-tanimaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denklik', 'denklik-ozgur-celik-jdl3n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yağmurların ardı

kızıla çalan çiçekler açar.

bir kızıl saçlı kız,

adı; Adem''e denk

adımlar ıslak kaldırımları.

o yürür...

içimde ezilir sadakat.

yağmur; ölüme denk.

yağmurların ardı

arınır kentin sokakları

çocuklar oynar 

her bakış; masumluğa denk

içimde safra

her damla; kirlenmişliğime denk.', 'yağmurların ardı kızıla çalan çiçekler açar. bir kızıl saçlı kız, adı; Adem''e denk adımlar ıslak kaldırımları. o yürür... içimde ezilir sada...', ARRAY['Türk Edebiyatı','Şiir','Özgür Çelik']::text[], 8.5, '{"poet":"Özgür Çelik","poet_slug":"ozgur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/denklik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir Sevgi', 'nedir-sevgi-ali-i-nal-x2k4s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'düşürmesede kimse dilinde

ne bilir anlamını

insan oğlu sevginin

seven yanlız kendini sever

onun için seviyor sadece

kendisini seveni

Aşk derler bir illet

çorba misali karıştırır

tutku nedir, ya saplantı

ruhun en derin hastalığı

bilip bilmeden belkide

sevgi onun da olur adı

En hafifinden bile

çatışmaya görsün çıkarları

görmek lazım onları

her gün her gece

seni seviyorum diyenleri', 'düşürmesede kimse dilinde ne bilir anlamını insan oğlu sevginin seven yanlız kendini sever onun için seviyor sadece kendisini seveni Aşk der...', ARRAY['Türk Edebiyatı','Şiir','Ali İnal']::text[], 8.5, '{"poet":"Ali İnal","poet_slug":"ali-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nedir-sevgi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıklar', 'asiklar-ali-riza-unal-nt7bc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O koca gönüllü meydane aşıklar

Öyle bir deryada yelken açarki

Onları ne fırtına ne tufan durduramaz

Çünkü nuh-un kazanını kaynatırlar..', 'O koca gönüllü meydane aşıklar Öyle bir deryada yelken açarki Onları ne fırtına ne tufan durduramaz Çünkü nuh-un kazanını kaynatırlar.....', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/asiklar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır-"hakikatın gözyaşları" Kitabından', 'sabir-hakikatin-gozyaslari-kitabindan-omer-ekinci-micingirt-fo88z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kadere rızadır sıdk teslimiyet

İnleyen ney sesi yanıştır sabır

Tahammül tevekkül gayret hamiyet

Hakikati tefsir gardaştır sabır

Sabır dizde derman bahtsızlara kin

Tövbelere keşke kıvamı kalbin

Yüreğimde ataş yârendir lâkin

Secdede aşk sesi beş taştır sabır

Bir nevi yükseliş kalp ehli işi

Musibete çengel ilmeğe teşi

Avama gözyaşı velide huşu

Yusuf’u tasavvur sırdaştır sabır

Teenni yolculuk dizlere takat

Mazluma şefkattir zalime tokat

Yeise galebe, külfetli fakat

Mükâfatı “bir” den pek hoştur sabır

İhlas sadakattir vefadan gani

Masiyeti rettir kulluk beyanı

İman ve itimat ruhun irfanı

Ubudiyet yoldaş yârdaştır sabır

Lütf-u İlâhîdir mükâfat ihsan

Lisanen bedenen duâdır kalben

Sabır ver Allah’ım sığınağım sen

Ömer’e imtihan kor yaştır sabır

Yakıtı sükûttan ataştır sabır', 'Kadere rızadır sıdk teslimiyet İnleyen ney sesi yanıştır sabır Tahammül tevekkül gayret hamiyet Hakikati tefsir gardaştır sabır Sabır dizde ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sabir-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 7', 'guncel-beyitler-7-huseyin-avdic-k1t1c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bizim icin Allah''a cikmak, aya cikmaktan kolaydir.

Allah''a cikmak, aydan da öte, kâinati a$maktir.

******

Âhireti gören gözlerim vardir, gördüm öteyi Rabb''in izniyle.

Rabb''e götüren sözlerim vardir, yazdim onlari Hakk''in vezniyle.

******

Müslümanlari gericilikle suclayanlar, suclananlardan cok daha geridir.

Cünkü ne aya cikmasini bilirler, ne Allah''a; cehennem onlarin yeridir! 

******

Tedavisi $art olan en büyük dert ve hastalik, nefse taparliktir ey insanlar! 

Hakk''a teslim olmadir bu hastaligin ilâci, teslim olan, olur: Kurtulanlar! 

******

$eytani üzmek sevaptir, inanin.

Onu bol bol üzün, sevap kazanin! 

******

Ey insanlar, bosuna yaratilmadiniz.

Rabb''e kulluktur, yaradilis amaciniz.

******

Sevmedigin de olsa bir i$in olsun.

Bununla binlerce dertten kurtulursun.

******

$eytan tuzagidir kumar.

Oynayanlar eder zarar.

Berlin, Haziran 2005.', 'Bizim icin Allah''a cikmak, aya cikmaktan kolaydir. Allah''a cikmak, aydan da öte, kâinati a$maktir. ****** Âhireti gören gözlerim vardir, gör...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guncel-beyitler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özel Beyit(ler) 3', 'ozel-beyit-ler-3-huseyin-avdic-qgs16', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Henüz ''kuram'' olmaktan cikmadi, isbatlanmadi evrim teorisi.

Dünyanin dönüsü gibi sabit degildir, insanin evrim(!) lesmesi.

******

Dünyanin dönmesi gibi isbatli degil evrim kurami.

Isbatliysa, hani delil? Delilsiz ilmin yoktur anlami! 

Berlin, Haziran 2005.', 'Henüz ''kuram'' olmaktan cikmadi, isbatlanmadi evrim teorisi. Dünyanin dönüsü gibi sabit degildir, insanin evrim(!) lesmesi. ****** Dünyanin d...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ozel-beyit-ler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Ağıt', 'kirik-agit-veysel-colak-2k5ei', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazıları yatağında bir mermiyken ölüdür.

Kendini, akşamları unutma.

Ah, bir gülebilsen yıkanır ağzın

benim ömrüm seninle iki nefes arası

bırak, dağılsın çürüten uzaklıklar

bana bir deprem bağışla 

saygılı ol yitirmek korkusuna.

Hiçbir silahı namlusundan öpme

belki yenilirsin, belki ayrılık haklı çıkar

teksin ve yalnızsın üstelik.

kimi nişanlasan kendini vurursun

Artık her kent senin uygunsuzluğunla başlar

çatlak bir yüzle ezberlersin yolları.

Necatigil’den kalma bir yazdı

kalın hüzünlü ve dibine kadar yorgun.

Bırak buluşmalar üşüsün, 

çoğaldıkça insan kıran yasalar

her çocuk masalına çekilir. Sonra aşk

güzel kadınların gövdesinde bıçak yarası.

Anlattığın dünyaya bu çığlık nasıl sığar! 

2005

Dize, Temmuz 2005', 'Bazıları yatağında bir mermiyken ölüdür. Kendini, akşamları unutma. Ah, bir gülebilsen yıkanır ağzın benim ömrüm seninle iki nefes arası bır...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kirik-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Denilen Büyü', 'zaman-denilen-buyu-veysel-colak-c8pfz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman hiç kullanışlı değil. Çoğu kez 

anılar bizi yaşar. Orada çıktım kırılan bir şafağa 

yalandan çatlamış kent; boşluk biriktiriyor 

üstelik pusuları rengarenk. Hep çarpıştım 

beynime dadanan halkın uzak yüzüyle 

bozgun üstüne bozgun, her buluşmanın sonu ıssız uğultu. 

İyi ki yanlışım, yanlış yerdeyim. Hazırım yırtılmaya 

ve meraktasın sen, avucunda zaman denilen kuyu 

çalkalanırsın, ağrıyım sana, bu işin sonuysa 

silinen bir kelime. Biterim, işte budur verilen bana. 

Bir aşk için kıtalar batıran deprem, geceler kuran usta 

eritilen giz, dilimi kopartan köpük: Öldüren kanama. 

Bıktım bozbulanık olmaktan. Ne varsa bir intikam 

ufuklar is biriktiriyor. Sen, her şeyin yazılıp durduğu yara 

bu yüzden an olunur, sorulurum her başlangıçtan. 

Ezberimdedir toprakla su; boşluğa açılan dünya 

nasıl da alışkın parçalanmaya. Ah! o yalnızlıklar 

uzak dağların yankıları. içinizdeki kuşları bırakın 

genişlesin gökyüzü. Buza düşen kor anlamını soğusun 

bir im verilsin ona, zehir yeşili bir sokak olsun. 

işte sonunda koptum sizden, sürtünmenin ısısı oldum 

artık kaybedin beni, bir kıyı gibi orada unutun 

kör bir gökyüzü seçecek sizi, 

ateşe bir deniz gömeceksiniz 

paramparça ve bir karabasandan söküle söküle 

daha bir koyulaşacak korkunuz. 

Ama kaçamam bundan. Siz ağzımdaki şarkıda saklanın 

bir öfke seli içindeki kandan kurtarın beni 

bir eliniz kağıt, bir eliniz kalem olsun 

beni gönderilecek bir haber gibi sarın. 

Bir çocuktan gidilen yolda başlatın kışı, aşk ölsün 

delik deşik bir kar yağdırın içinize 

beni kopartın ama bu yazılsın bir gülün açışına. 

Veysel Çolak

Varlık, Nisan 2001', 'Zaman hiç kullanışlı değil. Çoğu kez  anılar bizi yaşar. Orada çıktım kırılan bir şafağa  yalandan çatlamış kent; boşluk biriktiriyor  üstel...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/zaman-denilen-buyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane', 'efsane-veysel-colak-pax23', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir çiçek, açması yasaklanmış

bir gül ama kokusu yok,

bir ceylan uzak tutulmuş suya

bir soru, yanıtını arayan.

Bir dağ aşınarak yaşadı, o kadın

yırtık bir masaldan doğurdu seni 

yoruldu aşkın atı, kan işe koyuldu

şimdi bir efsane yontuyordur 

yüzünü gömüyordur halkına.

Anılar, mektupların solgun pulu

bir kapı, unutulmuş aralık bırakıldığı

ayaklanmış, yağmur olmuş bozkıra

ateşle korkutulmuş ormanı

orada insan, dünyanın korkuluğu.

Veysel Çolak', 'Bir çiçek, açması yasaklanmış bir gül ama kokusu yok, bir ceylan uzak tutulmuş suya bir soru, yanıtını arayan. Bir dağ aşınarak yaşadı, o ka...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/efsane-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Yudumluk Aşk', 'tek-yudumluk-ask-sahin-karakulunc-g29wl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Avucuna düşmüşse bir sevda,

Yüreğinde varsa yangın,

Gözlerini sarmışsa  umut.

Hadi tut,

Tut elimden,

Avucuna güç,

Yüreğine derman,

Umuduna umut

Bende.

Hadi tut elimden.

Ne aşkın külü kalsın geride,

Ne yaşanmamış arzular.

Hepsi hepsi toplansın bir avuçta

Ya teslim edelim rüzgara,

Uçup gitsin

Ya tek yudumda yutalım

Uyutalım İçimizde

30.06.2005, Devrek', 'Avucuna düşmüşse bir sevda, Yüreğinde varsa yangın, Gözlerini sarmışsa  umut. Hadi tut, Tut elimden, Avucuna güç, Yüreğine derman, Umuduna u...', ARRAY['Türk Edebiyatı','Şiir','Şahin Karakulunç']::text[], 8.5, '{"poet":"Şahin Karakulunç","poet_slug":"sahin-karakulunc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tek-yudumluk-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın İzi', 'sevdanin-i-zi-ufuk-coban-bfx20', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derin bir çizgi yüreğimdeki çizdiğin,

Kolay kolay çıkmayacak, tek sevdiğim,

Çiçekler kadar gizli sensiz yüreğim,

Ellerinde susuz kalan sessiz gözlerim.

Öyle çiz ki beni bir daha unutmasın gözlerin,

Öyle karala ki sevdayı eksiği kalmasın,

Kaleminde bazen dombili olsun, bazen koca göbüş,

Hep yanında olsun, hiç ayrılmasın.

Senede bir de olsa bizi çiz yüreğindeki gibi,

Bazen siyah, bazen beyaz, bazen renkli,

Çiz bir yapraktan düşen damladaki çaresizliği,

Ve yere düşmeden hayat ver anlatırken bizi...

Bir yaşam olabildiğine hapsedilmiş ve yalnız,

Düz duvarlar arasına bir sevda masalı sıkışmış,

Görebilen bir göz olsa, bir de yürek,

Bulsa gerçeği, hissetse benimle aynı şeyi...

25/01/2005', 'Derin bir çizgi yüreğimdeki çizdiğin, Kolay kolay çıkmayacak, tek sevdiğim, Çiçekler kadar gizli sensiz yüreğim, Ellerinde susuz kalan sessi...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdanin-izi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beynimdeki su kırıntıları 1', 'beynimdeki-su-kirintilari-1-sair-rozamona-ugrr6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sehpa üzerinde bıraktığım

kitaplar,anahtar,jöle

sesizlik isyanına ağıt yakıyordu rüzgar

kapı titriyordu git-geller yapıyordu

yatak beni çıplaklığımla esir almıştı

dolaş-sarmaştım şiirle

doguruyordum hemen

hemen ve öldürtüyordum

kalemimin rengiydi şiirin köşesine kazdırılan

duvara güç veren üzerindeki resimdi

resim dalgın,bakış,koyu

geceye kalan uçurtmanın boynu bükük gölgesiydi

o gölge bu gölge değildi

asıl o gölge gündüzün saklambaçıydı

-resim gölgeli

bakış,dalgın,koyu-

bahanesi yoktu volta atışlarımın

duvardan duvara yüzlerimin

hatırı kalmıştı odanın köşesinde

grafikteki kalp atışlarımın göreceli

ispatımıydı yaşamamın

-makina yanılıyordu

sanılmaz yanıldığından-

imgesel düşüncelere dayalı

bazı fısıldılar yükseliyor sesiz

zehirlerken 24 defa akrep yelkovanı

yirmidörtler yirmidörtleri doğuruyor

simgesel işaretlere karşı

sesizlik senfonisi sürüyor

-mazi-

amcamın ardında 1 sene ağıtlar yaktı nenem

-vahhh kelee-çıktı anamın ağzında

anlamsız kelimelere anlam yükledi anam

ben yatağın içinde gözyaşımdan habersiz

babamın ağzından çıkan titrek bir ayetti

-inna lillahi ve inna ileyhi raciun-', 'Sehpa üzerinde bıraktığım kitaplar,anahtar,jöle sesizlik isyanına ağıt yakıyordu rüzgar kapı titriyordu git-geller yapıyordu yatak beni çıpl...', ARRAY['Türk Edebiyatı','Şiir','Şair Rozamona']::text[], 8.5, '{"poet":"Şair Rozamona","poet_slug":"sair-rozamona","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/beynimdeki-su-kirintilari-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolum Yar', 'yolum-yar-yasar-donmez-rtn46', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yolum sonum, yolum ölüm, yolum nar

Varın alaz, varın ateş, varın har

Senin gözün, senin kaşın, senin yar

Bana ölüm, bana gülüm, bana zar

Ah-u zarım, hasbihalim var benim

Benim bitik, perperişan hallerim

Akl-i mecnun, pir-i mazlum ben benim

Dar-ı köhne, dar-ı memat yer benim

Kalki acan, kalki sen de yanasın

Kalki azabana çarptırılasın

Kalki viran, kalki ma-zub olasın

Kalki biçarei ana varasın', 'Yolum sonum, yolum ölüm, yolum nar Varın alaz, varın ateş, varın har Senin gözün, senin kaşın, senin yar Bana ölüm, bana gülüm, bana zar Ah-...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Dönmez']::text[], 8.5, '{"poet":"Yaşar Dönmez","poet_slug":"yasar-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yolum-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beta fizik fırtna **', 'beta-fizik-firtna-ali-riza-unal-nidvx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir nazar eyledim şu köhne dünyaya

Bezm-i belâ  ezeli ervahı alemden

Bir solukta seyredip gelip geçercesine

Bir kelâm söyledim bin kelâm ötürü

O ismi kelâm halk içinde haktan ötürü

Hakikât zatına marifet esmayı seçercesine

Ey evlat çekme hevanın ah-ı zarını

Vardan ayrı kalma varada tamah eyleme

Bir mezar derledim ölmeden ölümü seçercesine..', 'Bir nazar eyledim şu köhne dünyaya Bezm-i belâ  ezeli ervahı alemden Bir solukta seyredip gelip geçercesine Bir kelâm söyledim bin kelâm ötü...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beta-fizik-firtna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Benzemez', 'sana-benzemez-salih-celik-ybedj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönüllerde bahar kışa benzemez

Gerçekler acıdır düşe benzemez

Kalbinde katısı bulunur amma

Sevgiyle doludur taşa benzemez

Dostlar sıcacıktır ele benzemez

Gözyaşı bulanık sele benzemez

Yaban elden belki korurlar amma

Dikenler kokulu güle benzemez

Rüzgarlar sert eser yele benzemez

Yıllar çok uzundur güne benzemez

İplikten de belki ses çıkar amma

Mızrap vurduğumuz tele benzemez

Kalpler hayat dolu cana benzemez

Dünya konaklanan hana benzemez

Elde güzel çoktur diyorlar amma

Bence hiç birisi sana benzemez

                                Ümraniye', 'Gönüllerde bahar kışa benzemez Gerçekler acıdır düşe benzemez Kalbinde katısı bulunur amma Sevgiyle doludur taşa benzemez Dostlar sıcacıktır...', ARRAY['Türk Edebiyatı','Şiir','Salih Çelik']::text[], 8.5, '{"poet":"Salih Çelik","poet_slug":"salih-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sana-benzemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle Git', 'gule-gule-git-esin-ege-yv956', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün aşılmaz bilinen  yollar aşılır 

Heybetli dağlar sıra sıra  önünde eğilir yol gösterirler 

Gecenin karanlığında ay kandil yıldızlar meşale olur 

Zaman o zamandır işte gitmek sesi düşer yüreğine 

Vakit çok geçtir ama bir güç vardır yorgun dizlerinde

Koşar adım gelirsin de uzaklardan

Yaşanmamışlıkların zincirini kırmaya 

Hadi demeye, geldim demeye,ver elini demeye 

Zaman o zamandır işte ki vermesin kimsenin başına yaradan 

Aradığını bulamazsın

Bulsan da alamazsın 

Hadi diyemezsin,ver elini diyemezsin

Eli boş dönersin geldiğin yerlere

Yüreğindeki ateş yakar içini

Bu ne büyük bir acıdır

Ancak yaşayınca anlarsın…

Sen bana gelemezsin biliyorum ama anlamıyorum

Ben senin mecburiyetin değilim 

Oysa insan gönlüne mecburdur gerisi boştur

Şimdi git dilediğin yerlere

Yolun  açık olsun', 'Bir gün aşılmaz bilinen  yollar aşılır  Heybetli dağlar sıra sıra  önünde eğilir yol gösterirler  Gecenin karanlığında ay kandil yıldızlar m...', ARRAY['Türk Edebiyatı','Şiir','Esin Ege']::text[], 8.5, '{"poet":"Esin Ege","poet_slug":"esin-ege","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gule-gule-git-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utandırıyor.', 'utandiriyor-suleyman-saylan-rwykq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'UTANDIRIYOR.

Yüzünü görmedim, bak aylar oldu; 

Öksüzüm sen yokken, kalbim ağrıyor.

Gözünün mavisi silindi, soldu; 

Denizlerim artık yosun bağlıyor.

Hasreti içimde kora döndürdün,

Aşkımı harcayıp pula döndürdün,

Daha ben yaşarken, sensiz öldürdün...

Yüreğim yas tutup kara bağlıyor.

“Gözden ırak olan, gönülden ırak”

Derlerse inanma, gel halime bak...

Bırak artık inadı, bu nazı bırak; 

Fazla naz gönlümü dara bağlıyor.

Sevgimiz nikahlı, ikimiz ayrı; 

Ne sana, ne bana olmuyor hayrı.

Aşkımız mahşere kalmasın gayrı...

Sensiz geçen günü gönlüm saymıyor.

Sevda çiçeğimi soldurma sakın,

Kalbimi hüzünle doldurma sakın,

Var mısın, yok musun? Tavrını takın...

Seni böyle sevmek utandırıyor.

    Süleyman SAYLAN

    Ankara, 31.07.1997  Saat: 15.12   (Şarkı sözü olabilir.)', 'UTANDIRIYOR. Yüzünü görmedim, bak aylar oldu;  Öksüzüm sen yokken, kalbim ağrıyor. Gözünün mavisi silindi, soldu;  Denizlerim artık yosun ba...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/utandiriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Hep Seni Sevmiştim', 'ben-hep-seni-sevmistim-salih-celik-sb3mn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılmamış gibiyiz,sanki benlesin yine

Hala sıcaklığı var ellerinin elimde

Varsın zaman ne kadar zalim olursa olsun

Ben hep seni sevmiştim kalbim yine seninle.

Elem rüzğarlarıyla barışsa gözyaşlarım

Kavga etse umutla,mutlulukla sevinçle

Sanma gözden uzaksan,gönüldende uzaksın

Ben hep seni sevmiştim kalbim yine seninle.

                                      Ümraniye', 'Ayrılmamış gibiyiz,sanki benlesin yine Hala sıcaklığı var ellerinin elimde Varsın zaman ne kadar zalim olursa olsun Ben hep seni sevmiştim k...', ARRAY['Türk Edebiyatı','Şiir','Salih Çelik']::text[], 8.5, '{"poet":"Salih Çelik","poet_slug":"salih-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ben-hep-seni-sevmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Bana.', 'soyle-bana-suleyman-saylan-dnnry', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SÖYLE  BANA.

Yığın yığın malın olsa,

Sayılmayan paran olsa,

Otuz tane karın olsa,

Ne yaparsın söyle bana? 

Sağlığına nazar değse,

Doktor doktor geze geze,

Sahip olsan sen her şeye...

Ne yaparsın söyle bana? 

Önce sağlık, sonra para,

Sevgisizlik büyük yara,

Düşersen bir gün dara,

Ne yaparsın söyle bana? 

Açgözlülük etme sakın,

Bulduğunla şükret, yetin.

En sonunda öleceksin...

Ne yaparsın söyle bana? 

Süleyman SAYLAN

İzmir (Kilim Otel) , 06.04.1997, Saat: 00.55   (Türkü sözü olabilir.)', 'SÖYLE  BANA. Yığın yığın malın olsa, Sayılmayan paran olsa, Otuz tane karın olsa, Ne yaparsın söyle bana?  Sağlığına nazar değse, Doktor dok...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/soyle-bana-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Tatili', 'yaz-tatili-cem-han-0vo61', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman durmuş,sanki saatler çalışmıyor,

Bu yaz gününde tembellik sardı beni elim,kolum kalkmıyor.

İş,güç umurumda değil kafamda çalışmıyor,

Mavi gökyüzü,mavi deniz ve de kumsal bağladı beni bırakmıyor.

İstemiyorum kurtulmak beni bağlayan bu bağlardan,

Keşke kalan ömrüm böyle geçse,

Deniz mutluluk taşısa bana dalgalarından

Yüzelim,eğlenelim düşünmeyelim kara,kara

Yaz günleri kısadır dostlarım geçer koşa,koşa.', 'Zaman durmuş,sanki saatler çalışmıyor, Bu yaz gününde tembellik sardı beni elim,kolum kalkmıyor. İş,güç umurumda değil kafamda çalışmıyor, M...', ARRAY['Türk Edebiyatı','Şiir','Cem Han']::text[], 8.5, '{"poet":"Cem Han","poet_slug":"cem-han","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yaz-tatili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medeniyet', 'medeniyet-ali-i-nal-ryort', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kaldırıp baksa birisi

saklandığı taşın altına süslerin, 

ne kılıflar götürdü

binbir yalanın ardına girenlerin

varsın süslesin

insan oğlu kendisini

ve kendine ait

her bir erdemi ve yargıyı

ardındaki o ilkel dürtülerinin

kurcalasan biraz daha

görürsün adi yüzünü

hemde en kutsal bilinen

sığındığı değerlere gizlenen

Medeniyet dediğin zaten

başka bir şey değil süsten

insan yine aynı insan

çıkmış da olsa mağarasından

düzen aynı düzen', 'kaldırıp baksa birisi saklandığı taşın altına süslerin,  ne kılıflar götürdü binbir yalanın ardına girenlerin varsın süslesin insan oğlu ken...', ARRAY['Türk Edebiyatı','Şiir','Ali İnal']::text[], 8.5, '{"poet":"Ali İnal","poet_slug":"ali-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/medeniyet-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sezen...', 'sezen-suleyman-saylan-qvhkp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SEZEN...

Herkes sana hayran olsun,

Müzik senle anlam buldu,

Sensiz açan güller solsun...

Sezen, sezen, sezen aksu.

Ellisinde bülbül oldum,

Söz bilmezken şair oldum,

Sen içimi yakan korsun...

Sezen, sezen, sezen aksu.

Bastı bacak, kısa boylu,

Dizginlenmez bir tay huylu,

Namı büyük müzik dostu...

Sezen, sezen, sezen aksu.

“Huysuz” derler, sen uslusun,

Yaşanmamış bir duygusun,

Her yürekte ilk/son tutkusun...

Sezen, sezen, sezen aksu.

Saçın kısa, aklın uzun,

Duygu dolu, duygusuzsun.

Herkes hayran namussuzum...

Sezen, sezen, sezen aksu.

Güfte yazma güfte sensin,

Beste yapma beste sensin,

Müzik kokar senin terin...

Sezen, sezen, sezen aksu.

Süleyman SAYLAN

Ankara, 15.07.1997, Saat: 01.33', 'SEZEN... Herkes sana hayran olsun, Müzik senle anlam buldu, Sensiz açan güller solsun... Sezen, sezen, sezen aksu. Ellisinde bülbül oldum, S...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sezen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Hastayım', 'sana-hastayim-suleyman-saylan-thmcj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SANA  HASTAYIM

Sevginin ağına düşüp çırpındım,

Çakır gözlerinde aşkla ısındım,

Kanatsız bir kuşum sana sığındım.

       Her gün görsem bile yine yastayım,

       Çılgın gibi sevdim, sana hastayım.

İçimde çağlayan sonsuz pınarsın,

Kalbime kök salan ulu çınarsın,

Sen benim ömrümde her dem yanarsın.

       Her gün görsem bile yine yastayım,

       Çılgın gibi sevdim, sana hastayım.

Beynime işledin, söküp atamam,

Beni esir aldın, hiçe sayamam,

Ölsem de dönemem, sensiz yapamam.

       Her gün görsem bile yine yastayım,

       Çılgın gibi sevdim, sana hastayım.

Süleyman SAYLAN

Ankara,03.12.1990, Saat:00.45     (Şarkı sözü olabilir.)', 'SANA  HASTAYIM Sevginin ağına düşüp çırpındım, Çakır gözlerinde aşkla ısındım, Kanatsız bir kuşum sana sığındım.        Her gün görsem bile ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sana-hastayim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Gidebilen Sensin', 'niye-gidebilen-sensin-abdulkadir-karaca-bmdke', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En sonunda gözlerime hükmettim

Her gece resminleyken ağlamamak

Niye ben çektim sadece bu acıyı

Niye gidebilen sensin

Kapıları kapatabilen hem hepsini

Mutlumusun şimdi gittiğin günkü gibi

Düşlerimde bir saate tüm istediklerini satmaya hazırım

Ama satın alamazsın sevgimi,

Sen kapıyı kapattın benim hayatım bitti

Hiç öylesi ağlamamıştım gittiğin günkü gibi

Hayır hiç istemiyordum ben gitmeni kapıları kapatıp

En sonunda ağlamışsın öylemi giderken olduğu gibi

Dur demeyi isterdim aşk bu kadar basit mi? 

Kapıları kapatıp gittiğin günkü gibi

Benim hayatım bitti

                                                      12-12-2004', 'En sonunda gözlerime hükmettim Her gece resminleyken ağlamamak Niye ben çektim sadece bu acıyı Niye gidebilen sensin Kapıları kapatabilen he...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/niye-gidebilen-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün sırrı', 'olumun-sirri-ali-riza-unal-dt8zf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölümden korkmayın,sakın ha sakın yarenler

Yeterki onu kabul,ona hazır olun yarenler

Sen Hakkın Ruhundan,Ruh ile var oldun

Hakkın nuru bakidir,sende bakisin yarenler.

Sev kâinatın züptesi, hazreti insanı yarenler

Kalbi rûkun eksik olmasın, hayvanata cemadata

Birde erdem-i kemâlatı, şiar eyle kendine yarenler

Hakkın nuru ölürmü,sende ölmezsin yarenler

Kendine arif ol horlama hayvanı, sakın ha sakın

Ona da özenip varlığın sırrını, zorlama sakın

Ey Hakkın halifesi,uyan ha uyan, nurunu takın

Sen secdeyi Rahmansın, bir kâmile sor yarenler..', 'Ölümden korkmayın,sakın ha sakın yarenler Yeterki onu kabul,ona hazır olun yarenler Sen Hakkın Ruhundan,Ruh ile var oldun Hakkın nuru bakidi...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olumun-sirri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelen Bendirim', 'gelen-bendirim-abdulkadir-karaca-eudze', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bekle beni sevgilim

Bir sabah güneş daha çalmadan kapını

Şehir uyanmadan 

Yıllarca taşıdım  sevgini

Gelen bendirim

Nice zamandır cevapsız taşıdığım sorularımla

Yüzleşmekten korktuğum korkularımla

Vurdum kendimi sevda yokuşlarına

Umut ektiğim bahçeden gül beklerken dikenler kanattı ellerimi

Yaralı kalbimle geldim kapına

Çaresiz gözü yaşlı kalbine muhtaç gelen bendirim

Yeter sana bu utanç

Böyle bir köşede acı çekmek ne demek

Böyle ölürcesine seni beklemek

Bir ölüm yetecekken bu bedene

Öldüm ardın sıra binlerce kere

Yorgun,hasta,çıplak

Gelen bendirim,inadı bırak

Aç kapıyı yetmez mi bu kadar azap? 

                                  2004-11-25', 'Bekle beni sevgilim Bir sabah güneş daha çalmadan kapını Şehir uyanmadan  Yıllarca taşıdım  sevgini Gelen bendirim Nice zamandır cevapsız ta...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelen-bendirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairler Erken Ölür', 'sairler-erken-olur-ali-aydin-1w5im', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben doğmadan, 

Benden önce 

Önüm sıra, 

Çok şairler, 

Göçmen kuşlar göçtü sıcak diyarlara.

Kiminin adı, 

Kiminin mısraları, 

Kiminin dörtlükleri kaldı geride.

Gençtiler, 

Delifişek, 

Hepsinin kavak yelleri başında, 

Az yürümediler yağmurda kol kola.

Sel olup aktılar kaldırımlardan,

Oluk oluk, 

Satır satır, 

Sayfalar dolusu.

Kadehler kalktı boş şişelere,

Sigaralar gömüldü kül tablalarına.

Sahi, 

En son kim yazdı gülün şiirini? 

Kim karaladı gül desenli peçeteyi? 

Şairin sessizce öldüğünü bilen var mı? 

Ya başında kavak yelleri esen mezarını? 

Ben doğmadan, 

Benden önce,

Önüm sıra,

Çok şairler, 

Göçmen kuşlar göçtü sıcak diyarlara, 

Hep, ama hep şairler öldü,

Bir de, 

Şiir yazılan sevgililer. 

İstanbul/1994', 'Ben doğmadan,  Benden önce  Önüm sıra,  Çok şairler,  Göçmen kuşlar göçtü sıcak diyarlara. Kiminin adı,  Kiminin mısraları,  Kiminin dörtlük...', ARRAY['Türk Edebiyatı','Şiir','Ali Aydın']::text[], 8.5, '{"poet":"Ali Aydın","poet_slug":"ali-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sairler-erken-olur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atmaya Görsün Şafak', 'atmaya-gorsun-safak-abdulkadir-karaca-0eyqy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Atmaya görsün şafak 

Kaç acı çıkarır bu şehir bağrından

Kaç giden vardır yaralı gönüller bırakıp peşisıra

Güneş doğmayı versin kaç pislik çıkar aydınlığa

Kaç gelen olur umuttur tek varlığı

Kim bilir ne düşlerken kaybeder onu

Kaç gece sürer mazinin yorganında yaşam

Bu şehirden sılaya kaç mektup düşer

Kaç acıyı kapatır kaç selam

Hele bir şafak atmaya görsün

Bu buhranlı geceden kaç yastık kuru çıkar

Bu şehirde de vardır seher yeline ağıt yakan

Kaç ağıt kaç heceden sonra düğümlenir gözlere

Kaç renge esir bu şehir; mavidir,yeşildir,gridir

Kaç rengin anlamı sevgidir

Mutluluktur bazen elleri kaldıran semaya

Kaç dua şehrin günahında kirlenmeden ulaşır mevlaya

Kaç zaman sonra kabul edilir,kaç ömür yeter mutluluğa

Şehri ateşe vermiştir haramiler

Bir yüreğin payına kaç yangın düşer

Huzurun tarifi ne,kaç bakışı,kaç öpüşü sevgilinin

Kaç yürek yakan söz pes dedirtir sana

Kaç vurgun başına cellat eder şehrin kaldırımlarını

Kaç sevgiye inanırsın bundan sonra bu şehirde

Hangi sevda sözcüğü kandırabilir seni

Kaç yılanın gözlerini kapatır perde,kaçını görmezsin

Kalamazsın bu şehirde gitmek istersin

Kaç bela çöker karanlıkla birlikte,kaç acın diner

Lanetlenmiş kehanettir bu şehirde doğmak

Kaç kere kaçsan çözülür büyü

Hele bir şafak atmaya görsün

Kaç kişi anlar kutlu şehrin öldüğünü

                             2004-12-12', 'Atmaya görsün şafak  Kaç acı çıkarır bu şehir bağrından Kaç giden vardır yaralı gönüller bırakıp peşisıra Güneş doğmayı versin kaç pislik çı...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/atmaya-gorsun-safak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hırsız', 'hirsiz-abdulkadir-karaca-ynsh4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elimde resmin,aklımda sen

Öleceğim bak eğer gelmezsen

Taştan mı yapıldı acaba kalbin

Zavallı mahlukat bu mudur sevgin? 

Böyle sevgi olmaz gözlerimde kan

En acı azaptan kurtulmaz yakan

Ahım ömrünsıra dolanıp dursun

Beni arama hiç,kefen bulursun

Unutma sevgilim sen öldüğün gün

Toprak diyecektir denize gömün

Kabul etmez yer gök günahkarsın sen

Ölürmüydün zalim gerçekten sevsen

Bu şiir sanadır yeşil gözlü kız

Kalbimi geri ver geri ver hırsız

2004-09-23', 'Elimde resmin,aklımda sen Öleceğim bak eğer gelmezsen Taştan mı yapıldı acaba kalbin Zavallı mahlukat bu mudur sevgin?  Böyle sevgi olmaz gö...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hirsiz-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kız', 'kucuk-kiz-abdulkadir-karaca-rejjo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben seni sevmiştim hem de çok sevmiştim küçük kız

Sevgini kalbime sığdıramadığım için haykırdım dağlara taşlara

Ben sana hiç yalan söylemedim küçük kız

Evet bedenim esirdi yıllarca yalanlara

Ama yanında prangaları kırıyordum inan 

Sana yalan söyleyemiyordum bak ilk defa doğru söylediğim için ağlıyorum

Her insan hata yapar küçük kız

Bazen istemediklerimiz çıkar ağızdan

Ne kadar çok sevsek de gurura yenik düşeriz bazen

Bazen özür dilemeyi bile beceremeyiz sevdalımızdan

Affet beni küçük kız

Bir daha olmamak üzere son defa affet

Kalbim sensizken tarumar olmuş bir bağ

Helak olmuş bahçe,

Viran olmuş yapı,

Bak yara sarmış her tarafımı

Beni affettin mi küçük kız

At bir köşeye gururunu benimle dalga geçenlere aldırma

Ben alıştım yüzüme gülüp arkamdan vuranlara

Birde sen vurma küçük kız 

Tüfeğini doğrultma yüreğime

Benim yüreğim yeminli senin kurşununla ölmemeye

Mutlu biten masallarda biri değilmiş kaderim

İftiralara inanıp terkeden sevgililerde varmış

İnanmasan da bil küçük kız

Bir yerlerde mevsim baharmış

Hep seni sevdim küçük kız 

İnan hep seni seveceğim hep seni seveceğim

Hiç gelmeyeceksin belkide

Bu şiir dilimde öleceğim 

                                   (Eylül 2004)', 'Ben seni sevmiştim hem de çok sevmiştim küçük kız Sevgini kalbime sığdıramadığım için haykırdım dağlara taşlara Ben sana hiç yalan söylemedi...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kucuk-kiz-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebep', 'sebep-abdulkadir-karaca-ky7yn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arkamda bir avuç rüya

Önümde bir çuval gerçek

Hangi hatanı kapattırsın güzel yüzün

Hangi küfrünü unuttursun

Beni ağlattın ya hep

Allahından bulursun

Barışmaya geldim güya

Elimde bir demet çiçek

Ruhumu kaplayan hüzün

Mutluluğun bir köşede dursun

Çilelerini özledim,sebep

Belki benim olursun

2004-09-24', 'Arkamda bir avuç rüya Önümde bir çuval gerçek Hangi hatanı kapattırsın güzel yüzün Hangi küfrünü unuttursun Beni ağlattın ya hep Allahından ...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sebep-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu sene gelincik çok', 'bu-sene-gelincik-cok-abdullah-ozcan-gokcen-5dvbo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sene gelincik çok,

Kış çok olacak.

Kırmızıyla beyaz birleşmiş,

Senin yılın olacak.

Bu sene gelincik çok,

Bereket çok olacak.

Yeşille kahverengi birleşmiş,

Senin yılın olacak.

Bu sene gelincik çok,

Dostluklar çok olacak.

Siyah ve beyaz el sıkışmış

Senin yılın olacak.

,', 'Bu sene gelincik çok, Kış çok olacak. Kırmızıyla beyaz birleşmiş, Senin yılın olacak. Bu sene gelincik çok, Bereket çok olacak. Yeşille kahv...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Özcan Gökçen']::text[], 8.5, '{"poet":"Abdullah Özcan Gökçen","poet_slug":"abdullah-ozcan-gokcen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-sene-gelincik-cok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leylânın sırrı', 'leyl-nin-sirri-ali-riza-unal-5kdm7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dala budağa bürünür ağaç diye görünür

Bin bir kelâm eder turda,Musa ile öğünür

Ete kemiğe bürünür Leylâ diye görünür

O cilveyi Rabbanidir,mecnun ile övünür

Her zuhuratı sonsuzdan o suphan görünür

Gâh kulu ile övünür gâh kulundan dövünür

Faili hakiki kendidir esması hicap olmuş

Sanmaki aslıda şirinde, her daim o görünür..', 'Dala budağa bürünür ağaç diye görünür Bin bir kelâm eder turda,Musa ile öğünür Ete kemiğe bürünür Leylâ diye görünür O cilveyi Rabbanidir,me...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/leylanin-sirri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nuh-un kazanı', 'nuh-un-kazani-ali-riza-unal-w304v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaynadı tufanı Nuh un kazanı

Aşktır o geminin pusulası ozanı

Sakın olma aktin ihanetin bozanı

Öyle bir kâtibi varki tükenmez yazanı

Bozdukça azdırır küfre ateşe azanı

Kim duymuş selâmette kuyu kazanı

Gördünmü ölüpte mezarlıkta tozanı

Zerre miskal silinmez bir tuhaftır yazanı

Sen talip ol ihlas ile o rahmeti ganiye

Aldanma üçbeş nefeslik rahmetli faniye

Takatince hakim ol fırsat veme caniye

Haydi kaynasın gayrı Nuh un kazanı ..', 'Kaynadı tufanı Nuh un kazanı Aşktır o geminin pusulası ozanı Sakın olma aktin ihanetin bozanı Öyle bir kâtibi varki tükenmez yazanı Bozdukça...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nuh-un-kazani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir ve Ben.', 'bu-sehir-ve-ben-veysel-alkan-hsl5w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu şehir üstüme çöken bir yığın,

Elinden kurtuluş yok yalnızlığın,

Yığın ki adresi hep haksızlığın,

Bu şehir sebebi vefasızlığın.

Bu şehir bin anı bütün aşklarda,

Hüzünle donanmış tüm bakışlarda,

Hüzün ki sedasız yalvarışlarda,

Bu şehir sabahsız, hep akşamlarda.

Bu şehir benim gibi hep beklemekte,

Çılgınca sevip sevip terkedilmekte,

Sevme ki herkesi kıskandırmakta,

Bu şehir dertlere dert eklemekte.

Bu şehir aynı ben her an isyanda,

Derdini anlayan yok bu cihanda,

Dert ki sarmış ruhları,diller figanda,

Bu şehir kaybetmiş, aşk kumarında.

05/03/2002-İstanbul', 'Bu şehir üstüme çöken bir yığın, Elinden kurtuluş yok yalnızlığın, Yığın ki adresi hep haksızlığın, Bu şehir sebebi vefasızlığın. Bu şehir b...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-sehir-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Go away from IRAQ! !', 'go-away-from-iraq-mikdat-bal-x9ude', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I have a say

To U.S.A.

Just, go away,

Go away! 

You kill people

What horrible! 

It’s so simpel

Go away! 

Don’t stay no more

Don’t be a sore

Just beat it, or

Go away! 

Today sorrow

What tomorrow? 

Shit eating crow

Go away! 

We don’t let it

Don’t forget it

If you get it

Go away! 

BAL wrote to much

We’re on the watch

Starsky and Huch

Go away!', 'I have a say To U.S.A. Just, go away, Go away!  You kill people What horrible!  It’s so simpel Go away!  Don’t stay no more Don’t be a sore ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/go-away-from-iraq-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giresun''da', 'giresun-da-mehmet-bicik-k6t80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidelim gidelim de

Eğribel’e çıkalım…

Sevelim sevilelim,

Kavgayı bırakalım…

Yollar hep kapanmış,

Duman inmiş Kümbet’e…

Gel beraber gidelim,

Yârim senle cennete…

Gareysar yolları,

Kıvrım kıvrım kıvrılır…

Kader diyelim gitsin,

Sevenler hep ayrılır…

Gareysar’da gezmesi,

Yârim senle ne hoştur…

Sen hayatımdan çıkalı,

Kâlbimin köşkü boştur…

Giresun’da, sâhilde,

Gezerdik hep el ele…

Diz dize otururken,

Şimdi benzedik ele…

Giresun’da, Kale’de,

Sevişirdik günbatımı…

Kaçıracağım yâr seni,

Alıp tabancamı, atımı…

6 Aralık, 2004 Pazartesi

Burhaniye 16:40', 'Gidelim gidelim de Eğribel’e çıkalım… Sevelim sevilelim, Kavgayı bırakalım… Yollar hep kapanmış, Duman inmiş Kümbet’e… Gel beraber gidelim, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/giresun-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Kent', 'sakli-kent-hasan-can-v7235', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizim kentimiz uzaktı, çok uzak...

Nehirler geçerdi sokak aralarından,

Kaçınılmaz bir yağmuru vardı, tutardı aniden,

Sırılsıklam bir yazı vardı, üşütmeden yağardı,

Nehirlere karışıp giderdi öylece...

Saklı bir kent, içinde yolcusu yok...

Gecesine yıldızlardan başkası uğramazdı,

Sabah güneşine tutsak bir kağıt parçası,

Kendi çapında bir alev yakar, bütün kenti yaktığını zannederek.

Hesap sorulacak bir insan bedeni yok,

Çalacak bir mal, öldürecek bir tabanca...

Saklı kent...içinde yalnızlıktan başka birşey yok.

Küçük bir ev yamacında kentin,

İçinde bomboş bir sandık, hatıralar birikiyor...

Birikenler de bizden uzak, sen nerde ben nerde,

Saklı kent çok uzaklarda, sen yoksun saklı kent yalnızlarda...

Çok uzak, bizden çok uzaktasın,

Saklı kent ve yamacında bir ev,

Sandıkta birikenler içimdekiler,

Sen olmayınca herşey birer birer dağıldı,

Hepsi biryerlerde saklı kaldı...

Saklı kent... bizim kenditimiz,

Senden sonra içimdekilerde saklı kaldı,

Sana saklıyorum, kalanlarla beraber gidişinden sonra gelenleride.

Saklı kaldım, gidişinden sonra gelişine saklıyım...', 'Bizim kentimiz uzaktı, çok uzak... Nehirler geçerdi sokak aralarından, Kaçınılmaz bir yağmuru vardı, tutardı aniden, Sırılsıklam bir yazı va...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sakli-kent-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendini de Yaktın', 'kendini-de-yaktin-mehmet-bicik-i89v9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bigadiç’te parkta, garip garip gezerken,

Göründün de gözüme, kâlbimi yaktın…

Kararan dünyama bir ışık beklerken,

Kafamda cevapsız sorular bıraktın…

Söz vermiştin hani, ölümüne sevecektin.

Sevgimiz için her şeyini, hayatını verecektin.

Mutluluk bahçemize ayrılık tohumları ektin.

Hemen beni değil, kendini de yaktın…

7 Aralık, 2004 Salı

Burhaniye  17:10', 'Bigadiç’te parkta, garip garip gezerken, Göründün de gözüme, kâlbimi yaktın… Kararan dünyama bir ışık beklerken, Kafamda cevapsız sorular bı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kendini-de-yaktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmadım', 'unutmadim-mehmet-bicik-pv1ib', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gurbeti vatan eyledim.

Yüreğime taş bağladım.

Gece gündüz hep ağladım.

Unutmadım, unutamadım…

Acı çektim, hep inledim.

Özleminle türkü dinledim.

Bir olan derdim binledim.

Unutmadım, unutamadım…

Sordum seni çiçeklere,

Parkta oynayan çocuklara,

Baktıkça vitrinde oyuncaklara,

Unutmadım, unutamadım…

Yıllar geçti, ömür bitti.

Dertler çoğaldı, huzur bitti.

Nefret arttı, özür bitti.

Unutmadım, unutamadım…

Kavuşmak için hayal kurdum.

Her gördüğüme seni sordum.

Beklemekten artık yoruldum.

Unutmadım, unutamadım…

3 Kasım, 2004 Çarşamba

Burhaniye  22:54', 'Gurbeti vatan eyledim. Yüreğime taş bağladım. Gece gündüz hep ağladım. Unutmadım, unutamadım… Acı çektim, hep inledim. Özleminle türkü dinle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/unutmadim-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yevmi mahşer', 'yevmi-mahser-ali-riza-unal-ogt48', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Koptu kıyamet fani oldu nefsin kulu

Orada katip mübaşir hep Hakkın kulu

O Hakkın uluhuyeti ululuğundan ulu

Bin akçeden efdâl orada iyilerin pulu

Öyle bir alemki ne firavun ne peygamber ulu

Ayan olur mahşerde maliki yevmiddin nuru

Sen varlığından şüphede bir tek bir o ulu

Her cevherden efdal orada iyilerin pulu..', 'Koptu kıyamet fani oldu nefsin kulu Orada katip mübaşir hep Hakkın kulu O Hakkın uluhuyeti ululuğundan ulu Bin akçeden efdâl orada iyilerin ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yevmi-mahser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanmı talanmı', 'yalanmi-talanmi-ali-riza-unal-10w6j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mal mülk yar evlat hepsi talan oldu

Gördünki her şey o şanı yücenin nuru

Onca ömür lak,lak ile bir fısıltı yalan oldu

Bilirsinki konuşan dil gören göz onun nuru..', 'Mal mülk yar evlat hepsi talan oldu Gördünki her şey o şanı yücenin nuru Onca ömür lak,lak ile bir fısıltı yalan oldu Bilirsinki konuşan dil...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalanmi-talanmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yargıla', 'yargila-omer-temel-xgskj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni en son yüreğinle yargıla.

Ve, ver kararını iki gözüm.

İster giyotine ver başım,ister as.

İstersen tapınak yap,

Veya gökyüzüne posterimi as.

Kahvehane dedikodularıyla değil,

Mahalle kadınlarının,merdiven boşluğu lakırdısı,

İşyeri odalarında, adam satışlarında asla...

Beni felsefenin derinliğinde,

Bilimin aydınlığında,

Tarihin yüzleşmesinde araştır.

Bütün coğrafyaların kriterlerine vur.

Bütün savaşlara sok ruhumu,

Ve bütün barışların baş koltuğuna oturt.

Ama en son yüreğine sok..! 

Bütün damarlarında süz.

Ve etimi kemiğimden ayır,

Sonra nihai kararını ver göznurum.

O sana, doğruyu söyler.

Sonra dön, kendine sor...? 

O olmazsa ben. Ben olmazsam O...

Ne olur? 

                                                                           27.06.2005', 'Beni en son yüreğinle yargıla. Ve, ver kararını iki gözüm. İster giyotine ver başım,ister as. İstersen tapınak yap, Veya gökyüzüne posterimi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Temel']::text[], 8.5, '{"poet":"Ömer Temel","poet_slug":"omer-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yargila-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Engel Tanımaz!', 'gozlerim-engel-tanimaz-ozan-sah-turna-agdasan-fuf1p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GÖZLERİM ENGEL TANIMAZ! 

Gözlerimden engelliyim

ÖZLERİM Engel Tanımaz! 

Umudun türkü teliyim

SAZLARIM Engel Tanımaz! ...

Nakarat:

                 Meşaleyim kar değilim 

                Ufkum geniş, dar değilim

                Gönlüm görür, kör değilim

                GÖZLERİM Engel Tanımaz!

Şafak doğar kucağımdan

Mumlar yanar ocağımdan

Tutulsam da bacağımdan

DİZLERİM Engel Tanımaz! 

Ne dilsizim, ne sağırım

Duyarlıyım vardır ağrım

Çağdan çağa gider çağrım

İZLERİM Engel Tanımaz! 

Karlı dağları aşarım

Özgürce coşar, taşarım

Bir gün toprağa düşerim

TOZLARIM Engel Tanımaz! 

Yürek özürlüsü dolu

Kapatırlar bize yolu

Şah Turna nın susmaz dili

SÖZLERİM Engel Tanımaz! ...

Meşaleyim kar değilim

Ufkum geniş, dar değilim

Gönlüm görür, kör değilim

GÖZLERİM Engel Tanımaz! ...

Söz ve Müzik: Halk Ozanı Aşık  Öahturna (Ozan Şah Turna)    www.sahturna.com

Yorum: Ozan ŞİAR Ağdaşan 

Vokal: ŞİRİN ŞAFAK Ağdaşan Müzik Grubu

Sevgili şiir, türkü dostları,

Bu yapıtımızı yüreği aydınlık, gönlü gören canlara adıyoruz. 

Kuşların kanadında sevgiler yolluyoruz bestelerimizden ve şiirlerimizden, Bakıp ta göremeğen, bakar körlere ibret olurcasına. Karanlıklara ışık saçarak, umuda, sevgiye kucak açarak! ...

www.sahturna.com', 'GÖZLERİM ENGEL TANIMAZ!  Gözlerimden engelliyim ÖZLERİM Engel Tanımaz!  Umudun türkü teliyim SAZLARIM Engel Tanımaz! ... Nakarat:           ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Şah Turna Ağdaşan']::text[], 8.5, '{"poet":"Ozan Şah Turna Ağdaşan","poet_slug":"ozan-sah-turna-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gozlerim-engel-tanimaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Kırıntıları', 'yalnizlik-kirintilari-humeyra-yilmaz-tqacq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir esintiyi paylaşırım hayatla

Rüzgarın sesine katarım ömrümün en inatçı en yaramaz düşlerimi 

Kayıp nehirler saplanır göz bebeklerime

Buğulu karanlıklara soyunur ahlaksız gece hiç utanmadan

Kızıl sabahı bekler 

-bekler 

-bekler

Sevişir ve gider...! 

Her sevişme sonrası yeni bir oğul...! 

Şafak gülümser

Beyaz yağmurların toprağa her vuruşunda

Yeni mevsimler ekerim avuçlarıma

Çiçekler kuruturum günlerin arasında rengarenk

Yetim kalır hazan 

Sarı yaprakları koyar cebine

Tütün rengi acılarını bağrına basacak anne arar / bulur! 

Bir tebessümlük yokluğun şahlanır dudaklarımda 

Kirli mendillerde yeşerdikçe küf kokan geçmiş

Aynalar tutarım kırılganlıklarıma 

Merdiven altındaki korkuları tırmalarken nankör kedi

Süt beyazı umutlar pişiririm kendime

Kendimce çizgiler çizerim alnıma / alt alta

Sol yanıma değdikçe bir boşluk

Hücre sayım kadar ağırlık çöker yüreğime

Derin geceler kazarım ellerimle göğün sırtına

Gömerim yüklendiğim yükü / hesap sormaz bana

Sorgularıma yenilen sevdalara yanmaz içim

Bir tutam kusur katarım hüzünlerime olur biter 

Hayatı kuşanırım / ölüm uğramaz yanıma

Zafer bilirim yalnızlığımı

Çok zor olsa da...!', 'Bir esintiyi paylaşırım hayatla Rüzgarın sesine katarım ömrümün en inatçı en yaramaz düşlerimi  Kayıp nehirler saplanır göz bebeklerime Buğu...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yalnizlik-kirintilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Gönlüm', 'gul-gonlum-gunduzalp-kayihan-ydxgz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doğması beklenen güne karanlık çöküyor

Gül, gönlüm; gönlüm gül de sevgiyi gözlüyor

İnmekte nur sağnak sağnak gökten

Gönlüm, gül gönüllü Gülünü bekliyor

Sükut dahi isyankar bu ahvale

Kelimeler yetmiyor ifade için bu hale

Fışkırmakta aşk filiz filiz yerden

Gönlüm, gül gönüllü Gülünü bekliyor

Sabır, sabretmeyi unutuyor beklemekten

Gül, güllerini gönderiyor kendisi gelmeden

Arz,arş tepe taklak olunca sevmekten

Gül, gülüşünü göstermekte uzaklardan

Gönlüm, gül gönüllü Gülünü bekliyor', 'Doğması beklenen güne karanlık çöküyor Gül, gönlüm; gönlüm gül de sevgiyi gözlüyor İnmekte nur sağnak sağnak gökten Gönlüm, gül gönüllü Gülü...', ARRAY['Türk Edebiyatı','Şiir','Gündüzalp Kayıhan']::text[], 8.5, '{"poet":"Gündüzalp Kayıhan","poet_slug":"gunduzalp-kayihan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gul-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O an ve şair', 'o-an-ve-sair-omer-temel-fu0z3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'An gelir şair; 

Kalemde erir, Kağıtta biter.

An gelir, Sözcükler heykel olur,

Vinçlerle bile kalkmaz.

Ve an gelir, kainat dönüp yüzüne  bakmaz.

Bahar gelir geçer,

Özlenen o yaz gelmez.

Her yer çiçek bezenir,

Hiç biri koku vermez.

Caddeler mahşerleşir,

Kalabalıklar coşar.

Rıhtım rıhtım insanlar,

Kahkahalarla patlar.

Heyhat ki bu panayır,

Birini hiç avutmaz.

Bu mahşerde o biri,

Yapayalnız yalpalar.

Ne gönlünde bir hitap,

Ne gözünde dünya var.

Ruhsuz gömlekler o''na,

Çelik çomaktır ancak.

O ötelerden öte,

Dolu bir dünya arar.

                                      27.06.2005', 'An gelir şair;  Kalemde erir, Kağıtta biter. An gelir, Sözcükler heykel olur, Vinçlerle bile kalkmaz. Ve an gelir, kainat dönüp yüzüne  bakm...', ARRAY['Türk Edebiyatı','Şiir','Ömer Temel']::text[], 8.5, '{"poet":"Ömer Temel","poet_slug":"omer-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-an-ve-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Sevdan', 'yuregimde-sevdan-ufuk-coban-03n4t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni görmeden yaşamıyor yüreğim, hep seni arıyor,

Ellerinde olmadan bedenim nefes almıyor

Ne yapsam senden uzak kalınmıyor

İlk gün gibi çarpıyor yüreğim, seni özlüyor gözlerim.

Çok ama çok sevdim seni ilk günden beri

O zaman belki bilmiyordum nedenini

Karşıma çıktın kader gibi, alınyazısı gibi.

Sevdanı saklıyorum yüreğimde hiç eksilmesin diye,

Ellerimi saklıyorum sıcaklığın hiç kaybolmasın diye

Varlığın mutluluk, dua ediyorum hiç bitmesin diye

İlk gün gibi düşlüyor kalbim seni görecek diye.

Yalnızlıkta bir düş çıkarttın benden belki istemeden

Olsun istediğim şeyleri gösterdin yüreğinde saklamadan

Razı olsan bu yüreği korumasız adama düşünmeden

Uzaklara kaçırmasan yüreğini bir an bile beni sarmadan

Mavi ötesi bir sevda olsam yüreğinde sen anlamadan.

20/07/2004', 'Seni görmeden yaşamıyor yüreğim, hep seni arıyor, Ellerinde olmadan bedenim nefes almıyor Ne yapsam senden uzak kalınmıyor İlk gün gibi çarp...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yuregimde-sevdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Gözlüm', 'bahar-gozlum-husnu-avci-d4026', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen olmalıydın şimdi yanımda.

Beraber ıslanmalıydık bu yağan haziran yağmurunda,

Sen, sen benim isteyipte elde edemediğim,

Sen, sen benim yürek yangınım, içimde dinmeyen fırtınam,

Sen hayatımdaki tek anlamsın,

Sen benden öte benim sol yanımsın.

Kalbim durduğunda ona hayat verecek,

Ben her çöktüğümde elimden tutup kaldıracak,

Beni tekrar hayata bağlayacak,

Sen vardın, bir sen vardın, nerdesin be, nerdesin bahar gözlüm. 

Seni anlatmaya yada adlandırmaya yetmiyor dağarcığım 

Ben seni anlatamadığım kadar seviyorum. 

Nerdesin, nerdesin be bahar gözlüm, bir bilsen sensiz ne haldeyim,

Bir görsen şimdiki ahvalimi, belki tanımaz yanımdan geçersin.

Ayrılığın beni göçertti, çökertti be bahar gözlüm,

Şimdi görsen beni tanımaz, yanımdan gelir geçersin.

Ama bilmezsin ki aslın da yanımdan değil, 

Bahar yağmuru gibi bahar gözlerinle sen benim üstümden geçersin.

Bahar gözlüme hitaben.', 'Sen olmalıydın şimdi yanımda. Beraber ıslanmalıydık bu yağan haziran yağmurunda, Sen, sen benim isteyipte elde edemediğim, Sen, sen benim yü...', ARRAY['Türk Edebiyatı','Şiir','Hüsnü Avcı']::text[], 8.5, '{"poet":"Hüsnü Avcı","poet_slug":"husnu-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bahar-gozlum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koçum Benim', 'kocum-benim-zafer-mutlu-0mhg4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hadi diyelim deneyimlisin..

İyi iş görürsün.

Ya da görmüşsün..

Çık bakalım sokağına.

Bak bakalım o  gergin suratlara..

Farketmez aslında 

Anan,baban..

Amcan,dayın,halan

Deneyimlerini anlat bakalım onlara..

Yıkarlar  adamım,yakarlar...

tebessüm demek, acıdır ve

acıtır bazen hüznü akıtır...

Koçum benim..

Senin aklın hala öğrenci akşamlarından 

kalan dört kişilik masada..

Oldu da hani o kağıt diploman

kesmeşeker  köşeli..

Odanın bir ucunda..

Koçum benim 

Hayat ise sevdiklerinin gergin

Suratlarında....', 'Hadi diyelim deneyimlisin.. İyi iş görürsün. Ya da görmüşsün.. Çık bakalım sokağına. Bak bakalım o  gergin suratlara.. Farketmez aslında  An...', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kocum-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-ufuk-coban-tac19', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gitme yalnızlıklara Pamuşum beni bırakıp buralarda,

Uzatma ellerini yalnız gecelere, yıldızların sıcaklığına,

Gitme kokunu bırakıp ıssız karanlık köşelere,

Yalnız bırakma bu sensiz yaşayamayan yüreği.

Dayanılmaz olur ayrılık acısı gerçekten seviyorsan eğer,

Yüreğin dayanmaz bedeninde yalnız kalmaya,

Nefesin bile ihanet eder sana durmaz yanında,

Bir karanlık çöker gecene güneşin yoksa yanında eğer.

Sessizce ağlar bu beden bulamazsa diğer yarısını,

Gözler kapanır yere, göremezse birtanesini,

Ellerim çıkmaz cebinden uzaktaysa sıcaklığı

Ne kaldırır ki seven gönül, nasıl en ufak ayrılığı? 

Yüreğim uyanmaz sabahlara seni göremediği,

Her geçen gün alır beni sensiz karanlıklara,

Yüreğimde tek ses susmak bilmediği

Gitme Pamuşum bensiz dünyalara...:*-(

21/05/2004', 'Gitme yalnızlıklara Pamuşum beni bırakıp buralarda, Uzatma ellerini yalnız gecelere, yıldızların sıcaklığına, Gitme kokunu bırakıp ıssız kar...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gitme-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gece....', 'bu-gece-soner-demir-5yde5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu gece; 

her hangi bir şehrin

otogarında

veya garında 

belkide havalimanında,

yada nebileyim; 

bir kıyı kasabasının küçük limanında,

gelişini beklemek için inan

canımı verirdim gözümü kırpmadan...

bu masa,

bu kadeh ve bu boş şişe

şahidim olsun.....', 'bu gece;  her hangi bir şehrin otogarında veya garında  belkide havalimanında, yada nebileyim;  bir kıyı kasabasının küçük limanında, gelişi...', ARRAY['Türk Edebiyatı','Şiir','Soner Demir']::text[], 8.5, '{"poet":"Soner Demir","poet_slug":"soner-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-gece-133-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Güneş Geçti', 'kac-gunes-gecti-salim-erben-un7rt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç kere yanıp söndü

Kaç gün batımı ağladım

Ne kadar gözyaşı döktüm

Hangisi ulaştı sana

Kaç kere yandı canım

Sen yokken 

Ben de bir şey yapamadım

Hayatımın anlamı

Ne aşka sığınabildim

Ne de bitmeyen hasrete

Mahkum ettin beni de kendini de

Bir sevenim var diyemedin

İçindeki gururu yenemedin

Bu kadar mı ağır bastı 

Hadi ne olur söyle

Bu kadar mı yordu seni

Yoksa yanlış mı tanıdım

Ceylan gözlerini

Bir alo bir merhaba de

Çıplak dağlar benim

Demir parmaklık senin 

Arkasında sen önünde ben 

Hani nerde şimdi o

Zalım diyenler 

Onlar bile vefasızmış 

Çıkıp gittiler...', 'Kaç kere yanıp söndü Kaç gün batımı ağladım Ne kadar gözyaşı döktüm Hangisi ulaştı sana Kaç kere yandı canım Sen yokken  Ben de bir şey yapa...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kac-gunes-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahpe Dünya', 'kahpe-dunya-salim-erben-o9jr5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllardır yaşarım güldürmezsin

Süründürür yerlerde öldürmezsin

Akıtır gözlerimi dindirmezsin

Sen neymişsin kahpe dünya

Yarıyı geçecek ömür bitiyor

Saçlar ağarıp gül benzim yitiyor

Tutmuyor kalemi elim titriyor

Gülmeyi unutturan kahpe dünya

Dolmuyor çilem gelsin ecel

Can alan azrail bu gece gel

Al ruhumu sürülmeden el

Çok acımasız kahpe dünya

Sana sesleniyorum ey yüce Allah''ım

Ölmek istiyorum bu gece ölmek

Hoşuna gidiyorsa Zalımı süründürmek

Kahpe dünyadan göç ederken

İstiyorum yazdığın kadere gülmek', 'Yıllardır yaşarım güldürmezsin Süründürür yerlerde öldürmezsin Akıtır gözlerimi dindirmezsin Sen neymişsin kahpe dünya Yarıyı geçecek ömür b...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kahpe-dunya-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşsam Sana', 'kavussam-sana-salim-erben-phi53', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bitmiyor günlerim sanki sır			

Saatler yıl oldu aylar asır          			

Yatağım çul  yorganım hasır 			

Hiç ayrılmam kavuşsam sana 

						

Dudağımda şarkı dilimde destan 			

Oldum çölde hasretinden hastan 			

Sormazdım bir daha eşten dostan 			

Hiç ayrılmazdım kavuşsam sana				

İstiyor gönlüm sendeki yerini

Uzanıp tutasım geldi ellerini 		

Bahçende açılan gonca güllerini

Koklarım kıyamam kavuşsam sana

              

Görme kalbi yansın tutuşsun

Duyma ahımı sende buluşsun

Bu zalım sana nasıl kavuşsun

Hiç ayrılmazdım kavuşsam sana.', 'Bitmiyor günlerim sanki sır			 Saatler yıl oldu aylar asır          			 Yatağım çul  yorganım hasır 			 Hiç ayrılmam kavuşsam sana  						 D...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kavussam-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Derdi ki', 'kim-derdi-ki-salim-erben-wyfl1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boynu bükük gözü yaşlı

Arkasından ağladı sevdam

Tuşlara basan parmaklar

Ahizeyi tutan eller

Konuşmak isteyen diller

Sustu konuşamadı

Sevinç hüzüne karıştı

Cesaret korkuya ulaştı 

Neşe acıyla tanıştı

Ve her sabah uyandığında

O korkunç yer aklındaydı

Demir parmaklıklar

Demir kapılar

Bir de gardiyan vardı

Müdürü..gözlüklü ihtiyar

Ve de her gün batımı; ahı.

Kader ortağı acılardı.

Hücresi ise ona göre

Huzur buldugu tek yuvaydı

Sevdası müzik aşkı 

Şiirlerde ki yarım kalandı

Ya öldürdüğü insan,

Kaba saba ama

Tam bir babaydı

Zalım tam bir baba', 'Boynu bükük gözü yaşlı Arkasından ağladı sevdam Tuşlara basan parmaklar Ahizeyi tutan eller Konuşmak isteyen diller Sustu konuşamadı Sevinç ...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kim-derdi-ki-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-ufuk-coban-83sx0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat bu herkese gülmüyor,

Herkesin eline bir kırmızı gül vermiyor,

Bazen elindekini alıyor insandan,

Sürüklüyor ilk rüzgarla uzaklara bir daha getirmemek üzere.

Bir masal yapıyor hayatı insanlara,

Mutlulukları uyku öncesine taşıyor başkasının dilinden,

Ve rüyalar başlıyor çocukluk dünyamızdan,

Hiç bir kötülüğü bilmediğimiz diyarlardan.

Büyümek zor geliyor sevdalarda kayboldukça,

Gerçekler rüya oluyor aşklar yoruldukça,

Bir bir sırtını dönüp gidenlere baktıkça,

Hayat gülmüyor bize yıllar eskidikçe.

Biz de bir fırtınadayız aşkım,

Ayrı yönlere esen rüzgarlardayız,

Gittikçe uzaklaşan bir yoldayız,

Ne dostuz, ne canız, ne de sevdayız.

Bizimkisi bir inat içimizdeki hırs uğruna,

Sonu belli herkes gidecek kendi yoluna,

Gözler görmedi gerçekleri bir alışkanlık acısına,

Artık ne bakış, ne de bir selam bu sevda uğruna...

19/09/2004', 'Hayat bu herkese gülmüyor, Herkesin eline bir kırmızı gül vermiyor, Bazen elindekini alıyor insandan, Sürüklüyor ilk rüzgarla uzaklara bir d...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/veda-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahmaranlar(20)', 'sahmaranlar-20-i-smet-barlioglu-8ftz3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İkinci Bölüm

1

‘Lerdüvan dayadım alma dalına,

Almaları yumruk yumruk daş gibi.’

Tren keskin bir düdük çalarak küçük bir istasyona giriyordu.

Koridorun penceresinde yıldız yıldız parlayan ışıklara gözlerini dikmiş olan köylü:

- Aha o yıldız yıldız kimi ışşıhlar Çimento Pavlukası, bu istasyon da Yapı, mettiş bey. Benim bacanah bur ‘da ve yolum da bitti. Artıh sana uğurlar ola. Şuracıhdan Sivas ‘a ya on dakga çeker, ya onbeş. Arada başga istasyon yoh. Haydi gal sağlıcahla.

Dedi ve yavaşlayan trenin durmasını beklemeden az ilerdeki kapıyı açıp atladı.

Delikanlı onu istasyon binası arkasında kayboluncaya kadar izledi, sonra, koridorun soluk ampulü altında parıltısız bir ayna gibi sırtı karanlıklara dayalı duran pencere camında kendine döndü.

Tren tekrar yola çıkmıştı. Gecenin karanlık ufkundaki tek tük yıldızlar camdaki elbisesinde parlar üniforma düğmeleri gibi bir görünüyor, bir kayboluyorlardı. Elbisesi yeniydi. İlk elli lirasını peşin verip bir tüccar terziye dörtyüz liraya yaptırmışlardı. Parasını taksit taksit ödeyeceklerdi. Ayakkabılarını, resmi daireleri dolaşıp veresiye satış yapan PTT ‘ye de uğramış olan bir aracıdan almışlardı. Adam senedini-sepetini yazıp ‘Ayda da ne verirseniz verin, biz size borcunuz bitince duyururuz.’ Diyerek girmişti. Gömleğini, peşinsiz olarak taksitle, eve perde aldıkları manifaturacı satıp parasını perde borcu üzerine eklemiş, ‘Ömürlüktür; yıka yıka giy.’ lerle övmüştü.

‘Veresiye oldumu çek sırtına. Başka bir şeyim yok. Bir plastik yol çantası topu-tomarı. Nasıl olsa ilk aylığımdan Sivas ‘ta tümünü alırım. Üüüüh, neler neler alırım.’ dı.

Mutluydu. Yorgunluğu, solgunluğu, üzülmüşlüğü, tükenmişliği yoktu. Tazelenmişliği, bir iyi, bir çok iyi tazelenmişliği, bir kendine çok yaman güvenmişliği vardı. Yeni ufuklara, yeni umutlara gidiyordu. Aydınlıklara doğru karanlıkları yırta yırta. Güneşin battığı illerden, doğduğu illere. Toprak kokan, yağmur kokan, buruk umutlar kokan illere.

Atandığını öğrendiklerinin ertesi günü, eşinin de ayni yere ivedilikle atanması için dilekçe vermişlerdi. ‘Zaten yasalar bunu öngörüyor.’ du. ‘Bir hafta ya sürer, ya sürmez.’ di. ‘Yasalar… Bireylerin mutluluğunu öngören, çoğunlukla bu mutluluğu sağlamak için yapılan yasalar böyle istiyor.’ du. ‘Bu doğru.’ ydu.

‘Eşim gelinceye kadar cana-başa düşer ev tutarım. O gelmeden ben döşer dayarım bile. Sivas için, ‘Soğuk Erzurum ‘ludur ama Sivas ‘ta oturur.’ derler. Tezelden bir soba alırım. Şu kalın kalın, şu dışı emaye emaye, vay babam, gülle gibi ağır ağır Auer sobalardan. Kömürü, odunu, linyiti, tezeği, çalıyı-çırpıyı bile ayni kolaylıkla yakan o pahalı Auer sobalardan. Atarım kömürlüğe de üç ton kok kömürüyle iki-üç ton odun falan, kışın vareder yakarız Minicik ‘le.’ ydi.

‘Sonra Miniciğe kalın kalın mantolar yaptırırım kış için. Yakaları kürklü kürklü, şık şık, pahalı pahalı mantolar. Çeyizinden satılan kumaşının da aynısını bulur, onu da gene armağan ederim. Dişlerini, Miniciğin dişlerini, dişlerini yeniden yaptırırım. Aynini. Ayninden güzelini. Yoksulluk yüzünden lokmaları bile haram oldu. Yoksulluk yüzünden… Benim yüzümden…’ di.

Trenin kesin ıslığı ve karanlık koridor penceresinin bol bir ışıkla aydınlanmasıyla düşünceleri uzaklaştı, sağıldı, eridi.

İstasyon binası üzerindeki büyükçe yazılmış SİVAS kelimesini, içinde biryerleri kaynaya kaynaya okudu. Plastik çantasını kapıp indi.

Yaz aylarında bulundukları halde hava soğuktu. Ciğerleri taze havanın soğukluğuna çabucak alıştı. Birinci perondaki içkili lokantanın pikabı bir sarhoş havası çalıyordu. Buradan daha da ileriye, doğuya gidecek olan yolcular trenden koşuşarak inmiş, büfenin önünde bir bardaklarına, bir de başlarını çevirip korkuyla trenlerine bakarak üfleye üfleye çay içiyorlardı. Etli ekmek satan bir çocuk vagonlara bağıra bağıra furgona doğru gitti. Yolculardan birileri, ortadaki üstü altıgen beton çatılı, altıgen gövdeli bir çeşmenin altı musluğuna ağızlarını dayamış, su içiyor, su dolduruyorlardı. İstasyon binası dibinde, kalıcılardan olduğu rahatlıkla anlaşılan bir demiryolcu ayakkabılarının ikinci tekini boyatmaktaydı. Bir hamal, yaşlı bir kadının ağzı kapaklı, yüksek, yuvarlak ve ağır sepetlerini taşıyordu. Tulumlu birkaç işçi, ellerindeki hortumların suyunu vagonların kapalı pencerelerine sıkarak sapları uzun fırçalarla ıslak camları silmekteydiler. Açık pencerelerden birinden başını ve ellerini çıkarmış heyecanlı bir çocuk, kalabalığın biryerlerine doğru ‘Lan Apooooo… Goş… Gahdıracah şindi trenci treni…’ diye bağırıyordu. Vagon camlarını yıkayıp silen tulumlu işçiler ‘Lan bavem bu da bizden. Ahha…’ diyerek hortumla çocuğun yüzüne su püskürttüler, güldüler. Dinç davranışla yaşlıca bir demiryolcu aşağıya, vagonların arasına inmiş, bir şeylerle uğraşıyordu. Peronu rahat adımlarıyla geçerken elindeki saplı işaret çubuğunun bir yüzündeki yeşil, obir yüzündeki kırmızı ışığını düzenle salındıran, başı kırmızı şapkalı hareket memuru lokomotife doğru gitmekteydi.

İstasyonun yüz metre ötesi karanlıktı. Karanlık sınırın az önündeki yola cansız ışıklar vurmuştu. Beri yanda sıraya dizilmiş faytonlar, biryerlere gidecek yolcu bekliyorlardı.

Delikanlı elindeki plastik çantasıyla faytonlara doğru yürürken sesi uzaklarda yankılanan tren hareket etti.

Faytonlardan ikisinin sürücüleri yoktu. Üçüncü faytonun sürücüsü,.çeriye, yolcu yerine geçmiş, başını yan tenteye gömerek uyumuştu. Bir başkasının sürücü yerinde, elindeki kamçıyla oturan oniki yaşlarında kadar bir çocuk vardı. Kendisini görünce:

- Götürelim mi, abi? 

Diye seslendi.

- Götür.

İki faytonun arasından geçip arabaya bindi. Oturduğu zaman minderlerin altında yaylanacağını sanıyordu. Esnemeyen, üzeri muşamba kaplı koltuğa oturunca şaşırdı. Gerçekte, faytonun yabancısı değildi. Kendi doğduğu yerlere de motörlü araç pek girmemişti. Bayram törenlerinde geçit yapan dalgalı dalgalı boyanmış askeri kamyonlara, bir de varlıklı bir acentacının kaplumbağa tipi, kırmızı, güzel arabasına büyüyünceye kadar bakmıştı.

Faytoncu çocuk:

- Nereye gidelim abi? 

Diye soruyordu. Delikanlı mutlu bir sesle:

- Çocuğum, ben Sivas ‘ın yabancısıyım. Dedi. Eskiden gelmiştim ya, çok çok uzun yıllar önceydi. Senden de küçükken. Onun için sen beni bir otele götüreceksin. Kendi bildiğin bir otele. Ama bu otel hem pahalı olmayacak, hem de devlet dairelerine yakın bir yer olacak.

Sonra, ‘Belki çocuğun başı henüz devlet daireleriyle derde girmemiştir.’ Diye düşünerek ekledi:

- İsyersen sen beni ana caddeye götür. O da olur.

- Devlet dairelerine yakın bir yere götüreyim, abi.

Delikanlı kendi kendine,’Girmişmiş.’ dedi.

Atlar yürüdüler. Araba istasyonun arkasındaki alanımsı yerden çıktı. Büyükçe bahçenin yanından dönerek parke taş döşeli, kenarları ağaçlıklı, iki ayrı fakat dar gidiş gelişli, yokuşlu bir yola girdi. Cadde boydan boya aydınlatılmıştı. Yukardan aşağı vuran mavimtrak ışık sadece yolu aydınlatıyor, yol kenarlarında tek tük karşılaşılan kara kara binaların, arsaların, boşlukların, tek kat eski tip evlerin detayları belli olmuyordu. Bir araba, farlarıyla sol atın sol yarısını aydınlatarak yanlarından geçti. Mavi fluoressant ışıklar fayton körüğünün gölgesini arabanın içine düşürüyor, sonra oynaşarak gölgeyi daraltıp genişletiyor, bir ara arabanın içini karanlıkta bırakarak ayrılıyor, az sonra yeniden geliyordu.

Delikanlı, altındaki muşamba kaplı tahta sıranın sarsıntılarını ayniyle kendi vücudunda duyarak bir sigara yaktı. Dumanı ciğerlerine çekti. Atları boyuna haylayıp hayvanlara aralıksız kamçı vuran çocuğa seslendi:

- Çok vurma hayvanlara. Hiç vurma. Bırak gönüllerince gitsinler. Acımak iyi şeydir.

Sürücü çocuk, içinden ‘Bu yabancılar da adama hep araba sürmek öğretirler’ diye söylendiyse de, bir daha da atlara kamçı vurmak atılımını gösteremedi. Sadece, arada bir, kamçısının sırımını, acıtmayan bir ince püskül gibi her iki atın sırtında gezdiriyor, kamçı noksanlığını belli etmemek için tüm kuvvetini sesine vererek hayvanları daha hırslı haylıyordu.

Ortası havuzlu, büyükçe bir alana çıktılar. Sürücü çocuk, ilerdeki taştan yapılı, eski tip bir binayı kamçısıyla göstererek:

- Bu bina hükümet konağı.

Dedi. Sonra, yapılmış uyarıyı unutmuş görünerek atlara birer kırbaç yapıştırdı. Araba, sağlı sollu mağaza ve dükkanlarla çevrili caddeye aşağı gitmeye başladı. Çevre, aydınlık ve epeyce canlı olmakla birlikte dükkanlar ve mağazalar kapalıydı. İleride bir dört yol ağzından sağa döndüler. Araba, açık birkaç bakkalın ve daha canlı ışıkların bulunduğu bir caddede durdu.

- Borcumuz ne? 

- Borcun iki lira olmasına iki lira ya, sen yüzeli de versen olur, abi.

Delikanlı parayı uzattı.

‘İstanbul ‘daki bir fincan süt parası. Üstelik, sütçünün bakacak beslenecek atları, eskiyecek bir yaysız, oturaksız arabası da yok.’

Atları kamçılamadan, sadece haylayarak uzaklaşan arabacı çocuğun arkasından bir süre baktı, sonra otele girip yazıcıyla görüştü. Yazıcı, beş yataklı bir odada yer ayırıp defterine işaretlerken ne işte çalıştığını da sordu. Delikanlı tüm yaşantısında ilk defa olarak bir unvan söylüyor, müfettiş olduğunu söylerken de söylediğine kendisinin de inanacağı gelmiyordu. Sahte para sürerken yakalanmasını bekleyen kalpazanlara özgü bir korku içindeydi. Yazıcının birden yerinden fırlayacağını, biryerlerden birilerine telefonlar edeceğini, içeriye ansızın polislerin ve daha birkimselerin gireceğini, kendisini yaka-paça sürükleyeceklerini, tekme-yumruk, sille-tokat biryerlere götüreceklerini sanıyordu. Böyle bir şey olmadı. Delikanlı içinde tatlı, çok tatlı bir sevinç duydu.

‘Sahte parayı yutturmuş insanların sevinci.’

Merdivenleri çıkarken yazıcı kendisine yol veriyordu. Davranışları saygılıydı. Her günkü müşterilere gösterilebilenden daha büyük bir saygı taşımaktaydı. Ama delikanlı bir türlü öne geçmeyi bilemiyor, beceremiyor, gülünç bir kibarlıkla hep geride kalıyordu.

‘Yolu bilmediğimden değil, saygıya alışamadığımdan.’ dı.

Yazıcı, odasını gösterip iyi geceler diledikten sonra ayrılırken ‘İlk defadır ki; bizim otele de bir büyük müşteri geldi. Hem de bir müfettiş. Sabahleyin kendisini kaçta kaldırmam gerektiğini de söylemedi. Belli ki; kendine güveni var, çağrılmadan uyanacak.’ diye düşünüyordu.

Beş yataklı odada üç müşteri yatmaktaydı. Yatağın biri boştu. Pencerelerden birinden, cadde direğindeki fluoressantın mavi ışığı, kendisine ayrılan yatağa vurmuş, dikdörtgen yatağı bir köşegen gibi ikiye bölmüştü. Yatağın yarısı maviye boyanmış, yarısı siyah kalmakta direnmişti. Yatanlardan biri horluyordu. Elektriği yakmadan sessizce soyunup yatağına uzandı.

‘Şaşılacak şey: Hiç yorulmamışım. Haydarpaşa nire, Sivas Garı nire? Yorulmamışım. İnsan mutlu olunca yorulmak nedir bilmiyor. Mutlu muyum? Mutlu muyum acaba? Gerçekten, mutluluk mu bu? Öğrenci yurdunda yattığım gecelerin ayni. Gene beş kişilik bir oda ve gene dört kişi. Orada ranzalıydık, burada yataklıyız. Gene her gece böyle biri horluyordu. Tıpkı bu horlayan adam gibi. Kimdi? .. Koca Kelle A ‘met? .. Evet, O ‘ydu. Koca Kelle A ‘met ‘ti. Gündüz anlatılan fıkraya, gündüz yapılan espriye, ancak geceyarısı anlayıp gülen A ‘met ‘ti. Nasıl buldum ben bu adı, çabucak? ‘Kimdi? ’ sorusuna kim cevap verdi bende? Benim içimde bana bu cevabı kim verdi? Ben kimim? Ben soruyu soran mıyım? Ben soruyu soransam, soruma cevabını bulan kim? Cevabı veren bensem; soruyu soran kim? ‘Bu kediyse et ner ‘de? Bu etse kedi nic ‘oldu? ’ Pis iş… Kendi kendine soru sormak pis iş… Olanaksız iş… Ama oluyor… Ama acaba olduğu oluyor mu? Soruyu biri sorar, karşılığını bir başkası verir. Bu doğru. Ben bende iki kişi miyim? Kimlerim ben? Koca Kelle A ‘met ‘i kim buldu bende? Beyin mi? Beyin benden başkası mı? Başkaları mı? Beyin korkunç bir arşiv… Uzun, çok uzun yılların her saniyesinin kokularını, biçimlerini, tadlarını, seslerini, esnekliklerini saklayan bir arşiv… Kayıtlarını maddeleştirsen saraylara sığmaz… Pis iş… Çok pis iş… Atla bir kalem sen bunu… Es geç… Sittiret. Kavraması zor iş… Evreni bir çadır bezi gibi bir ucundan tutarak kendi üzerine katlamaktan daha zor iş… Sittiret… Bunlar yalan… Bunlar gerçek değil… Gerçek olan şu; Bu adam horluyor. Ben de horlarım. Koca Kelle A ‘met de horlardı. Yataklara birbirimizden önce dalıp birbirimizden önce uyumakta yarış ederdik. Sona kalıp dona kalmayalım diye: Horlayan horultuda uyuyamaz. Uyuyamaz. Ama adı Osman olursa o başka. Yatağa bir yapıştımı, iki gece bir gündüz horlayan Osman… Mitil Osman… Tren Haydarpaşa ‘dan çıkıp rötarlar yapa yapa, yolculara lanet ettire ettire Kars ‘a ulaşıncaya kadar uyuyabilen Osman… Ve ona uykuda avans veren Yıldır… Osman ‘dan önce yatıp Osman ‘dan sonra kalkan Yıldır… Yatakları korkutan, uykuları ürküten, geceleri yıldıran Yıldır… Siz buralardasınız şimdi… Buralarda biryerlerde… Uykuya doymayan gözlerinizle kimbilir hangi ivedi iş bekleyen masalarda… Uyuyorsunuz… Birbirinize avanslar vere vere uyuyorsunuz… Uyuyun oğlum; uyuyup büyürsünüz… Yatın oğlum; kavun-karpuz yata yata büyür…

Bizim masamız ucuzdu, bizim masamız kontrplaktı. Minicik onarmıştı eski, portatif masamızı. Sevgili Minicik… Kutsal Minicik… Yaşantı arkadaşım, fikir arkadaşım, yoksulluk arkadaşım, sevgilim, eşim, karım, açmazlarımı açan anahtarım. İngiliz anahtarım, İngiliz akıllım. Uzaklaşan trenime çığlığından ses, gözlerinin yaşından süs veren Miniciğim. İşte, sen duruyorsun yine kompartman penceremin önünde. Ağlıyorsun peronda durmuş, bir mutlu. Ben seni yeniden görünceye kadar, sen hep öyle ağlar duracaksın peronda. Duracaksın ama gerçek olmadan. Senin gerçeğin o saniyeden sonra değişti. Tüm gerçeklerin bir sonraki saniyelerde değiştikleri gibi. Hiçbir gerçeğin bir önceki saniyedekine uymadığı gibi. Seni en son gördüğümle en ilk göremediğim saniye arasında değişti gerçeğin. Değişecek günlerimizle değiştin. Şu anda da ağlıyorsun, biliyorum. Ama başka gerçekler içinde. Çok kaypak, çok değişken, çok sümük gibi yapışkan, çok cıva gibi tutulamayan gerçekler içinde.’

Delikanlı ancak sabaha doğru, benzerlikleriyle birbirlerine bağlanan düşünceler zincirini biryerlerdeki halkalarından koparıp uykuya dalabildi.

Gözlerini açtığı zaman, kapalı pencereleri, duvarları, kapıları aşan bir satıcının kuvvetli sesi, kelimelerde aralıklar bırakarak:

- Süüüt… Süüüt… Süüüt…

Diye yankılanıyordu.

Kolundaki ‘Enfiye Kutusu’ na baktı: Yediye çeyrek vardı. Müşterilerinden birinin henüz yatmakta olduğu beş yataklı odada ‘Bereketli geçecek, bize yeni kapılar açacak bir sabah’ buyruk sürdürüyordu.

Hazırlanıp çıktı. Uykusuzluğuna rağmen vücudu dinçti. Otelin az ilerisindeki cadde, önleri süpürülüp sulanmış bakkal dükkanları, manavlar ve mağazalarla bezenmişti. Cadde, bu temizliğiyle bayram sabahlarının sokaklarını andırıyordu.

Kapısının üstüne traş leğeni asmış bir berbere girdi.

Kafası usturayla kazınmış, pehlivan yapılı berber, saçlarını kırparken gözleri, aynaların yan kenarlarına asılı duran camlı, çerçeveli bir duyuruya ilişti. Bu; dükkanın çalışma saatlerini gösteren bir çizelgeydi. Altında resmi mühürle mühürlenmiş bir ‘Bölge Çalışma Müdürü’ ibaresi, bir imza ve imza sahibinin adıyla soyadı vardı. Kendisiyle çalışacağı müdürün adını oracıkta öğrenmiş olmak hoşuna gitti.

Bu çevredeki caddeler, kentin ana caddeleri olduğu halde, bakınca tükeniveren, göz atınca sonu geliveren çok kısa yollardan ibaretti. Ortada asfalt diye bir şey yoktu. Tüm caddeler parke döşeliydi. Yirmibeş uzun yıl önce, babasının başka bir yere atanışı dolayısıyla transit geçtikleri kentin bu bölümünü kolayca tanıdı. Üzüldü. Boğazına yumruk yumruk birşeyler tıkandı. Kişilerinin kolayca ve hemen değişiverdiği bir ülkenin yirmibeş uzun yılında kentler hiç değişmiyordu. Bugünleri, yirmibeş uzun yıllar öncesinin ayniydi.

Kavşaktan dört kola ayrılan caddelerde, erken uyanmış bir canlılığın ve çalışkanlığın sevimliliği vardı. Açılmakta komşusundan geç kalmış tek dükkan, tek mağaza yoktu. Sabahın adamı dinlendiren, yenileyen serinliğinde, bir vitrin önünde kızaran döner kebabı görünce; görmezliğe gelmek için adımlarını sıklaştırdı.

İşe başlayacağı dairenin yerini bilmemekle birlikte, bundan rahatsızlık duymuyor, nasıl olsa kolay bulunur düşüncesiyle geçtiği caddelerdeki en modern, en görkemli binalara bakıyordu.

Bir ucu istasyona, obir ucu odunculara ve mezarlıklara kadar uzanan ana caddeyi ilgiyle araştırıp inceledi. Bulamayınca ivedileşti: Tam dairenin açılış saatinde işinin başında olmak istiyordu.

Karşılaştığı adamlardan sordu. Bilemediler. Bilebilecek kimselere başvurdu, öğrenemedi. Polisler böyle bir daire duyduklarını, ama nerede olduğunu çıkaramadıklarını söylediler. Başvurduğu bir gazete satıcısı, yoldan geçen, orta boylu, iyi traşlı, gayet sempatik, yaşlıca bir adamı gösterdi:

- Sivas ‘ımızın eskilerinden, görmüş geçirmişlerinden, başına çok iş gelmişlerindendir. O bilir.

Dedi. Sonra adamın arkasından seslendi:

- Baba… Baba… Koyuncu Baba… Bak hele canım…

Adam döndü, yanlarına geldi. Yaşına göre çok dinç, çok anlayışlı, çok sıcakkanlı ve çok girişkendi. Siyah gözlerinin parıltılarında zeka izleri vardı. Onların bir şey demesine kalmadan:

- Efendi yabancı mı, gardaş? 

Dedi. Delikanlı başıyla onayladı. Açmazını anlattı. Adam arkadaşına:

- Sen işinden olma… Ben efendiye yardım erim…

Deyip büyük bir sıcakkanlılıkla delikanlının koluna girdi:

- Adını bağışla? 

- Kubilay.

- Kubilay… Uzun ad. Ben sana Kubi derim. Bizim bu Sivas ‘ta öyledir. Muzaffer ‘e Muzo, Abdullah ‘a Abo ve tabii Kubilay ‘a da Kubi.

Delikanlı büyük bir şaşkınlıkla; ‘Tanıdıklarımın yıllardan buyana çağırdıkları gibi çağırdı beni. Ayni sesle, ayni biçimde. Çok zeki, çok sıcakkanlı.’ diye düşündü.

Adam konuşmasını sürdürüyordu:

- Bakma gardaş, Sivas ‘ımız soğuktur ama adamları sıcaktır. Beni ‘Koyuncu Baba’ diye seslerler. Ana cadde üzerinde çayevi işletiyorum. Cami ile karşı karşıya. Kahveci olduğum seni aldatmasın. İngiliz kumaşından takım elbisenin dikiş parasıyla beş lira olduğu çağlarda, beş lira da terzisine bahşiş verirdim. Varlığım çoktu. En çok destek olduğum tanıdıklarımın oyunlarına geldim. Battım, çıktım, gene battım. Manifaturacılık yaptım, alıcıyı kazıklayamadım, kazıklamayı sevemedim. Doğru çalışınca da yıkıldım. Şimdi kahveciyim. Gene doğru çalışıyorum ve elimde mum, adam arıyorum. Neyzen merhum Beyoğlu ‘nun ortasında küçük su dökecek olmuş. ‘Aman üstad, ne yapıyorsunuz? ’ diyerek engel olmuşlar. Nedenini sormuş. ‘Görmüyor musun, çevre adam dolu.’ Demişler. Üstad merhum, küçük suyunu iyice yana-yöreye attıra attıra ‘Hani ya buralarda adam? Ben bir tek adam göremiyorum ki.’ Karşılığını vermiş.

Sekiz yaşlarında kadar bir çocuk, elindeki benzin dolu şişeyle yanlarına yanaştı. Sevimli bir yakınlıkla:

- Nasılsın Baba? Dedi. Sen de iyi misin abi? 

Yaşlı adam, küçük çocuğun saçlarını okşadı:

- Varol gaardaş. İkimiz de iyiyiz. Sen nasılsın? Epey çakmak doldurabildin mi? Çok benzin satabildin mi? Baban nasıl? Gene her gece çekiyor mu kafayı? 

Sonra delikanlıya döndü. Çocuğun saçlarını bırakmadan:

- Oğlum, yakınım değil. Dedi. Müşterim. Hem iyi müşterim. Merttir-cömerttir. Gönlünün sevdiğini çay içirmeden kaldırmaz. Cin gibi akıllı. Bunun bir babalığı var. Yani ki; Allah ‘tan başka kimsesi yok. Çünkü; herif ayyaş. Bu çocuk gecenin geç saatlerine kadar ayakları altına gelmeden onun-bunun çakmağına benzin doldurur, beriki de onun bu paralarıyla dem tutar. Dinle gardaş, nükte, fıkra yavan sözün katığıdır. Kerata bir kış gecesi hiç benzin satamamış. Eve gitmiş. Gitmiş ama kolay mı? Ayyaş para bekliyor. Yakalamış oğlanı, serçe gibi boğazından, hemen şimdi git bana içki al, hiç olmazsa bira, diye. Oğlanda para yok ama akıl var. Sen buna öyle bakma. Bir köşenin dibinde işemiş bira şişesinin içine, doldurmuş ki, ağzına kadar, köpüğü bile eksik değil. Bilirsin; küçük çocuklar çok işerler. Hele de bunun gibi çok çay içeni olursa. Bu öyledir; baba ayyaş olursa çocuk da çay içer, bira içer. Derken götürmüş bir şişe bira(!)  yı sarhoşa. Herif zaten kafayı bulmuş. Bu şişe birayı da kapıp diplemiş. Diklemesiyle puuuurt diye ağzından püskürtmesi bir olmuş. Şimdi sen, herif anladı da çocuğu dövecek sanırsın, değil mi? Hayır. Sarhoş, biranın tadına bakınca demiş ki; ‘Devlet devlet değil ki; yaptığı biralar bile at sidiği gibi.’ Demesine bakma. At sidiği, mat sidiği, diklemiş devirmiş. E, o kadar kızgınlık da olur: Sarhoş bu. Yaaa gardaş, işte bu velet öyle velettir.

(Devam edecek…)  20', 'İkinci Bölüm 1 ‘Lerdüvan dayadım alma dalına, Almaları yumruk yumruk daş gibi.’ Tren keskin bir düdük çalarak küçük bir istasyona giriyordu....', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/sahmaranlar-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Buna Yaşamak mı Diyorsun?', 'sen-buna-yasamak-mi-diyorsun-abdulkadir-karaca-zzgjt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni istiyor bu adam 

Ellerini ellerine istiyor,gözlerini gözlerine

İstemekten öte nedir ki hayat

Mevsimler umutlarla atlatılıyor

İki sinema bileti biri sana alınmış

Bilmiyor musun? 

Ne çıkar

Yarınlarım yavaş yavaş kararıyor

Martılar öyle çığlık atıyorlar ki sorma gitsin

Gök parçalanacak sanıyorum

Bazen şarkılar adını söylüyor

Çaresiz ve üzgün dinliyorum

Hem seni sevmediğimi söylüyor,hem de

(Bilmiyorum seni mutlumu eder yoksa kanatır mı?) 

Ağlıyorum

Yenilmek çok eziyor beni,bu kadar zaferden sonra

Bu şehir bildiğimden daha soğukmuş

Senin açtığın yaralar sızlıyor

Ne geçmişim avutuyor beni ne geleceği düşünüyorum

Bu kadar aptalım demek ki çünkü hala seni seviyorum

Hep aynı duygularla harmanlanıyor gönlüm

Tıpkı çaresiz bir illete benziyor

Ne etsem de bırakmıyor yakamı

Bir kaza kurşunu mutluluğum olacak

Belki bu kadar uzak olmayacağım sana

Aslında sevebilmek en güzeli,hakkını verebilmek,başarabilmek

Mevsim kış,hava soğuk,bir çayın özlemi gibisin

Ben tanıdık,ben bildik,ne kadar uzak olsanda

Hep yakındı bana sensizlik

Tebessümü şekere ağlayan çocukta kaybetmiştim

Ya seni? 

Belki bir gün bu şiiri okursun

Cevapsız sorularım var

Gel ve dinle bir kere

Yıllar önce harcadığın bu aşk

Acılar hediye edecek sana

Umut,özlem,sevgi,korku ve gidişin

İşte hayatımın özeti

Bu günlerim neden mi yok? 

Sen nefes almayı yaşamak mı sayıyorsun

Elin nerde bomboş ellerim

Ne sesin var,ne kokun 

Sen buna yaşamak mı diyorsun

                                2004-12-13', 'Seni istiyor bu adam  Ellerini ellerine istiyor,gözlerini gözlerine İstemekten öte nedir ki hayat Mevsimler umutlarla atlatılıyor İki sinema...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sen-buna-yasamak-mi-diyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittin Ya', 'sen-gittin-ya-abdulkadir-karaca-xl3l0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen gittin ya dostum

Ardından bir bir kopmaya başladı takvimler

Her yaprakta biraz daha yokluğun

Tam beş ay oldu dostum

Ne sesin ne de kokun

Tarifsiz bir keder oturmuş yüreğime

Sen yoksun

Neden hala bana kin duymuyorsun diyorsundur

Denedim ama ellerin geldi aklıma

Hani bana o ellerle kırmızı çiçekler vermiştin

Denedim gözlerin geldi aklıma

Buz gibi baksa bile beni deli etmiştin

Denedim kalbin geldi aklım ne kadar nankör olsa da 

Bir zamanlar beni sevmiştin

Yani  dostum kement attı boynuma yokluğun

Yani dostum sen yokken  aslında bende yoktum

Ne çok isterdim bir serçenin masumluğunu

Taşırdım bu alemin tüm sarhoşluğunu

Ama umarsızca üzerime attığın yokluğunu

Bir dağa vermeyi denedin mi hiç

Bir bana vermeyi bildiğin gibi

Acaba dünyada varmıdır bilmem 

Vefasız kalbini sevdiğim gibi

Dostum sen yoktun buralarda mevsimler eskidi

Umut öksüz kaldı acı serpildi ve baş kaldırdı tüm şiirlerime

Esir aldı beni koş kurtar dostum

Yoksa paramparça edecek sevgimi

Buralar böyle dostum

Aylar oldu sen yoksun

Gelme artık hiç ummadığım bir anda gidersin yine

Gelme artık uğurlar olsun

(İstanbul 2004)', 'Sen gittin ya dostum Ardından bir bir kopmaya başladı takvimler Her yaprakta biraz daha yokluğun Tam beş ay oldu dostum Ne sesin ne de kokun...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sen-gittin-ya-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden ötesi Var mı ki', 'senden-otesi-var-mi-ki-abdulkadir-karaca-x34rp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen ne merhametliydin ey nebi! 

Gafletin son raddesine kadar hükümran olduğu topraklarda

İnsanlar yüceltiyorlardı inkarı,kalplerini karartmıştı asilik

İnsanlar ilahlaştırıyorlardı taşları

Sense hakka imana çağırdığın için onları,taşladı seni nasipsizler

Gazap için kainat tek sözünü bekliyordu

Uğruna alemler yaratılan sevgili taşlanıyordu

Kan sızıyordu toprağa ayaklarından,toprak bile yutmak istedi beni sakifi

Ve sen ellerini kaldırdın semaya,güneş o an secde etti avuçlarına

Arş titriyordu felaketin ağırlığından

Ellerin hala açık gökyüzüne

Affet Allahım dedin,bilmiyorlar,bilmiyorlar bilselerdi

Yapmazlardı...

Senin canına düşman olmuşlardı ey resul! 

Senin rabbine imandan acizler bilmiyorlardı ki

O isterse bir güvercinle korurdu habibini

Örümcekle saklardı perde inmiş gözlerden

Kum taneleri alaşağı ederdi düşmanı

Çünkü o isterdi

Senin yiğitlerin vardı ya Muhammet! 

Hamza''n,Alin,Ömer''in,Sümeyye gibi şehitlerin

Onlar ki dinleri için ölüme tebessümle geçti ömürleri

Onlar ki canlarından öte can bildiler seni

İslam uğruna herşeyi terkettiler

Vazgeçtiler,dünya malı neydi ki

Sen en muzaffer komutansın ey elçi! 

Bedirde dinin için kapandın secdeye

Allahım dedin,eğer bu bir avuç müslüman kaybederse savaşı

Yeryüzünde sana ibadet eden kimse kalmayacak,yardım et yarabbi! 

Sen dilersinde,olmazlara sınır vermek mümkün olur mu

Sen istersinde,boş mu döner ellerin

Dönmeyecekti tabii,küfre mezardı bedir

İsteyen sen olmuştun,rabbin çokça verendi

Sen en büyük öğretmendin ey Ebu Kasım! 

Bize islamı öğrettin,insanlığı,doğruyu

Kapıya geleni boş çevirmemeyi,bedel istemeden vermeyi

Birbirimizi sevmeyi,kardeşliği,cömertliği

Oku diyordu kuran,okuyunuz buyurdun

Esirliğin bile diyeti insanlara okuma yazma öğretmekti

Sen öğreten oldun hep

Sen hasanı,hüseyini severdin,bedeviler şaşakalırdı

Ancak kalbi kararmış olan sevmeyi bilmez derdin onlara

Değişmedi hiç bir şey,sen öğrettin

Kalbi karalar sevemediler bizi

Sen alemlere rahmet için gönderilen peygamber! 

Biz mahrumiyetimizi kader diyerek avutmaya çalışırken

Aslında seni görememenin ızdırabından doluyor gözlerimiz

Devende bir tüy olmaya bile razıyken

Bu asırda hangi saltanat oyalayabilir bizi

Senin asrında olsaydık eğer

Belki bir kere görebilirdik gül yüzünü

Yahut senin kokun sinerdi üzerimize

Şimdi asrımdaki insanların yüzlerinde ki acımasızlık beni korkutuyor

İnsanlar senin kazandırdıklarını kaybetme yarışındalar sanki

Örnek sen olmayınca viran oluyor bilinen her şey

Artık asri bahaneler türetiliyor bizi yolundan ayırmak için

Bizse tüketene kadar son nefesimizi

Seni örnek alacağız peygamberim

Zaten senden ötesi varmı ki? 

                                2005-03-17', 'Sen ne merhametliydin ey nebi!  Gafletin son raddesine kadar hükümran olduğu topraklarda İnsanlar yüceltiyorlardı inkarı,kalplerini karartmı...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/senden-otesi-var-mi-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selma''ya', 'selma-ya-abdulkadir-karaca-c46du', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daha çok mu ezilecek kalbim

Daha çok mu taşınmaz olacak bedenimde

Sevmenin bedelinin bu kadar ağır olduğunu bilseydim

Biz koza örerdim kendime ve görmezdim seni

Bilseydim eğer,tüm zaferlerimin yenilgi olduğunu bile anlamadan

Yeni bir zafer aramayacaktım kendime

Daha çok mu yanacak yüreğim

Ya da sen bu acıyı kovabilecek misin yüreğimden

Silinmez bildiğim düş kırıklıklarımla birlikte

Kapı dışarı eder misin onları...yoksa

Bir yok oluşta sen atıp varlığımın bütün çaresizliğini alabilirmisin

Kalbimden

Gözlerimi gözlerinde kaybettiğimden beridir,ızdırap esir almışsa ruhumu

Bütün insanlık şahit olmuşsa,güya bensem isyankar zamana

Evet kabul ediyorum suçumu

Zaman seni benden	çalacak kadar alçaldıysa beni mahrum edecek kadar senden

Kabul ediyorum suçumu cezama razıyım

Ben sadece sevdim Selma 

Üstelik böyle bir aşkın tüm olunmazlığını kabullenerek

Senin bilmeni istedim ve birazcık sevebilmeni beni

Çok şey mi istiyorum yada bu senin için çok şeyi feda etmek midir

Senin için bu aşk sevmek midir en sevilmezi...bilmiyorum

Bu yükü tek başıma taşıyabilseydim eğer ne seni yardıma çağırırdım

Nede sana açardım derdimi

Ama yapamadım Selma bağışla

Bir ömür boyu kabullenemedim sensizliği

Öyle korkutucu bir his ki bu,düşündükçe kesiliyor nefesim

Öyle kanayan,öyle ağır bir yara ki ölümü özlüyorsun

Bir kaybolmuşluk,bir başıboşluk baştan sona 

Son nefesin şah damara kadar yaklaşması

Cümlelerin anlatamadan tüketildiği bu dert bana paryamsın diyor

Selma asiliğimde bir yere kadar 

Sonra sen olmazsan yanımda bu isyan neye yarar

Ama ne olursa olsun seni seviyorum Selma

Ve her şeye razıyım,eğer ki sevmek buysa

(27,03,2005)', 'Daha çok mu ezilecek kalbim Daha çok mu taşınmaz olacak bedenimde Sevmenin bedelinin bu kadar ağır olduğunu bilseydim Biz koza örerdim kendi...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/selma-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devrin Bedevileri', 'devrin-bedevileri-abdulkadir-karaca-70b5i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başımızı senin okşamanı isterdik ve bizi korumanı

Yalanın nefes kadar tabii solunduğu bu düzende

Biz Enes misali dalsak bile oyuna 

Senin gibi okşayan eller olmayacak biliyorum

Senin öğrettiğin gibi öğretilmiyor hiçbir doğru

Ve senin hoşgöründen eser yok insanların bildiklerinde

Demek ki onlara da senin öğrettiğin gibi öğretilmemiş

Yoksa ne mümkündü bir çocuk sevilirken tüm cehaletiyle şaşırmak

Bilmiyorlar ki namazda bile Hasan''ın sırtına çıkmasına müsaade ettin sen 

Hüseyin''le oyunlar oynardın ve devrin bedevileri şaşırırdı

Çünkü onlar çocuk sevgisini bilmezlerdi

Tükenmiyor

Devirler değişse de devrin bedevileri

Bir bayram günüydü Medine de 

Medine çocukları en güzel giysileriyle cıvıldaşırken sokaklarda

Bir çocuk çökmüş duvarın dibine ağlıyordu

Neden ağladığını sordun

Babasının şehit olduğunu anlattı çocuk ardından yakasına yapışan kimsesizliğini

Gözlerin doldu ya Resulallah

Ben Ebu Kasımım dedin çocuğa,ben baban olsam Ayşe de annen ne dersin

Ne denilirdi ki,sözden öte söz lazımdı anlatmaya

Fikirler çocuğun gözyaşlarına düğümlenmişti

Titrek bir nağmenin tüm boğukluğuyla koptu küçücük dudaklardan evet

Artık o da bayram çocuğuydu hem de bayram çocuklarının en mutlusu

Baba peygamberdi artık,uğruna alemler yaratılan resul-u  ekberdi

Bu sevgiye şahitti Medine,bir köşede anlamaktan aciz devrin bedevileri

Şimdi şahidin sen olduğunu bilenlerin sevgisine muhtaç çocuklar

Bazılarının silah oluyor oyuncakları 

Bazılarıysa kurşunlar altında doğup yaşamaya çalışıyorlar

Kısacası biz sevgiden aciz tutunmuşuz bir köşesine dünyanın

Senin sevdiğin gibi sevmiyor kimse

Ve sevmeyi öğrenemiyor bu devrin bedevileri

Sen severdin bizleri ey nebi

                                             2005-03-24', 'Başımızı senin okşamanı isterdik ve bizi korumanı Yalanın nefes kadar tabii solunduğu bu düzende Biz Enes misali dalsak bile oyuna  Senin gi...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/devrin-bedevileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu da Geçer', 'bu-da-gecer-zumrut-demirtas-2h8xj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey, 

Çukur gözleri kömür karası, 

Acı sözleri ömür belası,

Yar! 

Parmağının ucu kopmuş

Üzülme, üzülenin var,

Tırnağına zarar gelse,

Yüreğimde, fırtınalar 

Kopar! 

Ey,

Ruhumun öbür yarısı,

Alev gönlümün çırası,

Yar! 

Bu da gelir, bu da geçer,

Zaman her acıyı siler,

Sevdan yüreğimi ezer,

Giden parmak olsun,

Kim takar! 

(17.06.2005)

(Yorumlar Üzerine Dipnot:

Parmağını Makineye Kaptıran

Yarime Geçmişler Olsun...)', 'Ey,  Çukur gözleri kömür karası,  Acı sözleri ömür belası, Yar!  Parmağının ucu kopmuş Üzülme, üzülenin var, Tırnağına zarar gelse, Yüreğimd...', ARRAY['Türk Edebiyatı','Şiir','Zümrüt Demirtaş']::text[], 8.5, '{"poet":"Zümrüt Demirtaş","poet_slug":"zumrut-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bu-da-gecer-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Ağlar', 'kan-aglar-i-smail-dogan-s2s1v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göz yaşlarım dökülüyor toprağa, 

Yaz ayında kururmuş,GÖL kan ağlar. 

Çoşar sular azgın varır ırmağa, 

Yatağını yıkıyor, SEL kan ağlar. 

Kurumadı gitti gözüm yaşları, 

Yok başağım pişmez evin aşları, 

Seyreyledim gökte uçan kuşları, 

Ötmez oldu bülbülüm,GÜL kan ağlar. 

Sıra sıra gelen kuşlar darılmış, 

Susuzluktan bataklıktar kasılmış, 

Ayrık otu birbirine sarılmış, 

İşlemiyor toprağı, BEL kan ağlar. 

Yaz baharım döndü kara kışına, 

Su gelmiyor bağ bahçenin başına, 

Milyon arı emek harcar boşuna, 

Kır çiçeği kurudu, BAL kan ağlar. 

Alamadım kışlığımı evime, 

Kulak verin, kulak verin ezğime, 

Nazar değdi O güzelim eriğme, 

Yaprakları kurumuş, DAL kan ağlar. 

Kuraklığa karşı verek savaşı, 

Elim yüzde yapıyorum bağdaşı, 

Neyleyeyim atlas libas kumaşı, 

Sarmıyor ki göğsümü,ŞAL kan ağlar. 

Yağmadıkca yağmur tarla sızlanır, 

Çatlar toprak çorak çorak tuzlanır, 

DOĞANİ''yem yanar yürek közlenir 

Kıtlık da can alırsa, KUL kan ağlar. 

Şiir Perisi Grub''unun ''Bir Dörtlük de Sen Yaz'' aktivitesininden esinlenilerek yazılmıştır', 'Göz yaşlarım dökülüyor toprağa,  Yaz ayında kururmuş,GÖL kan ağlar.  Çoşar sular azgın varır ırmağa,  Yatağını yıkıyor, SEL kan ağlar.  Kuru...', ARRAY['Türk Edebiyatı','Şiir','İsmail Doğan']::text[], 8.5, '{"poet":"İsmail Doğan","poet_slug":"i-smail-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kan-aglar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pes Etme Gönül', 'pes-etme-gonul-muammer-baydere-ypryn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamanla huzura varılır elbet

Hele dur bakalım ses etme Gönül

Gün gelir yaralar sarılır elbet

Yeter ki yenilip pes etme Gönül

Yaratan kulunu sabrını ölçer

Köprünün altından çok sular geçer

Sonunda mutluluk seni de seçer

Yeter ki yenilip pes etme Gönül

Sevenin sevgisi hor olur mu hiç

Sönen bir ateşten kor olur mu hiç

Umutla yaşamak zor olur mu hiç

Yeter ki yenilip pes etme Gönül

Hem iner hem çıkar hayat merdiven

Bitmesin kendine duyduğun güven

Yok sanma dünyada gerçekten seven

Yeter ki yenilip pes etme Gönül

Madem ki bir zalim aldı ahtını

Kendini ezdirip yıkma tahtını

Kısmetse sileriz kara bahtını

Yeter ki yenilip pes etme Gönül', 'Zamanla huzura varılır elbet Hele dur bakalım ses etme Gönül Gün gelir yaralar sarılır elbet Yeter ki yenilip pes etme Gönül Yaratan kulunu ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/pes-etme-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemek', 'ozlemek-ozgur-kokturk-x5et7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşmek düşlerden bir gece vakti 

Bir gece vakti seni özlemek 

Günlere geceleri ekleyip 

Tüm sevdaları sana üleştirmek... 

Özlemek, özlemlerin soluğu ensemdeyken 

En sonunda hep seni bilmek yine 

Yarınları, dünlerle birleştirirken 

Hep bir yol olmak umuda, sevgiye...', 'Düşmek düşlerden bir gece vakti  Bir gece vakti seni özlemek  Günlere geceleri ekleyip  Tüm sevdaları sana üleştirmek...  Özlemek, özlemleri...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlemek-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evli Ve Çocuklu', 'evli-ve-cocuklu-muammer-baydere-uv5i5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostlarım hep onu suçluyor ama

Masum ve çocuktu belki sevdiğim

Kulların yüzünden büründük gama

Evli ve çocuklu şimdi sevdiğim

Uzaktan bakarım yüz yüze gelmem

Kötü söz söylemem intizar bilmem

“Perişan” diyorlar haline gülmem

Evli ve çocuklu şimdi sevdiğim

Kahrımı ezerken sabır taşında

Şimdiden pes ettim yolun başında

Kadere yenildi bu genç yaşında

Evli ve çocuklu şimdi sevdiğim', 'Dostlarım hep onu suçluyor ama Masum ve çocuktu belki sevdiğim Kulların yüzünden büründük gama Evli ve çocuklu şimdi sevdiğim Uzaktan bakarı...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/evli-ve-cocuklu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayende', 'sayende-salih-ozalasan-h5bfl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşığın yoksa sazın ses vermez olsan da sazende

Başı dumanlı bir çınar olsan uzanan olmaz gölgende

Sevenler yanından geçmez, ilk harfler olmaz gövdende

Sazın sözü sevdadır, sevdayı öğrendim senin sayende

Dil ile zikir yansıtır mı yürekten geçeni? 

Hangi şarap sarhoş eder yüreği sevda çekeni? 

Dil ile söylersinde nasıl saklarsın o hayır diyen gözleri

Gözleri okumak fal mıdır? falcı oldum senin sayende

Sazın ağlar sözün ağlar yalancı bahardaymışçasına gülsen de

İki gözün açık kalır hayatı dolu dolu yaşadım öldüm desende

Cenaze namazın kılan olmaz libastan kefene bürünsen de

Gözü ardında olanın ruhu çıkmaz, gözüm ardımda kaldı sayende

Yazım tarihi 30-06-05 Saat 23,50

Salih Özalaşan', 'Aşığın yoksa sazın ses vermez olsan da sazende Başı dumanlı bir çınar olsan uzanan olmaz gölgende Sevenler yanından geçmez, ilk harfler olma...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sayende-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Bir Şeyim Kalmadı', 'hic-bir-seyim-kalmadi-muammer-baydere-0g9h3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyada bizim gibi ne insanlar yaşıyor

Sana kaç kez anlattım fakat aklın almadı

Çok üzgünüm güzelim konu beni aşıyor

Senin için yapacak hiçbir şeyim kalmadı

Yolları uzatıyor yokuşa sürüyorsun

Gerçekleri unutup hayaller görüyorsun

Günden güne başına bir çorap örüyorsun

Senin için yapacak hiçbir şeyim kalmadı

Sana aşkı öğretmek düşmezse de haddime

Sonu olmayan sevgi çare olmaz derdine

Bana pek zararın yok ihanetin kendine

Senin için yapacak hiçbir şeyim kalmadı

Gülmek isteyen gözler ağlamayı dener mi

Taşıdığın sularla değirmen hiç döner mi

Bir başkası yüzünden koca hayat söner mi

Senin için yapacak hiçbir şeyim kalmadı', 'Dünyada bizim gibi ne insanlar yaşıyor Sana kaç kez anlattım fakat aklın almadı Çok üzgünüm güzelim konu beni aşıyor Senin için yapacak hiçb...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hic-bir-seyim-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı''dan Dileğim', 'tanri-dan-dilegim-muammer-baydere-tkmk4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilirsin yaşamak ebedi değil

Nasılsa gün gelip sürem dolacak

Tanrı’dan dileğim cennete değil

Her gece rüyana girmek olacak

Tasasız yatarken onun koynunda

Çektiğim acılar vebal boynunda

Tanrı’dan dileğim bil ki sonunda

Her gece rüyana girmek olacak

Bende mutluluğun yalnız adı var

Neden ağlıyorsun yatağın mı dar

Tanrı’dan dileğim mahşere kadar

Her gece rüyana girmek olacak

Seni son bir defa gördüğüm zaman

İlk işim halini sormak olacak

Tanrı’dan dileğim öldüğüm zaman

Her gece rüyana girmek olacak', 'Bilirsin yaşamak ebedi değil Nasılsa gün gelip sürem dolacak Tanrı’dan dileğim cennete değil Her gece rüyana girmek olacak Tasasız yatarken ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tanri-dan-dilegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İrfanı Bilmeyen Biri', 'i-rfani-bilmeyen-biri-zulfikar-yapar-kaleli-3r7re', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İzzeti irfanı bilmeyen herif 

Yirminci yüzyılda yamana benzer 

Gören zaten tanır, gereksiz tarif 

Fırsat tanımayan amana benzer 

İman gönüldedir zekâda ilim 

İlmi olmayan hiç olur mu âlim? 

Herkes anlamalı, her aklı selim 

Anlamayan varsa, samana benzer 

Peygamber emridir yürü ileri 

Müslüman olan hiç kalır mı geri? 

İslâmlık ilimdir ezelden beri 

Aksini söyleyen lâmana benzer 

Yeniye aşığız tutarız onu 

Nizam-ı âleme uygunsa yeni 

Gelen yok sayarsa geçmişi dünü 

Onu tasvip eden dumana benzer 

1990', 'İzzeti irfanı bilmeyen herif  Yirminci yüzyılda yamana benzer  Gören zaten tanır, gereksiz tarif  Fırsat tanımayan amana benzer  İman gönüld...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/irfani-bilmeyen-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaka Bir Yana', 'saka-bir-yana-muammer-baydere-44nm2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“Gönlünde bana yer var mı” diyerek

Şakayla karışık takıldım sana

Kaptırdım kendimi aşka giderek

Tutuldum güzelim şaka bir yana

“Aşkından deliye dönerim” derken

“Ateşim buz olur sönerim” derken

“Aklında bulunsun önerim” derken

Tutuldum güzelim şaka bir yana

Günümü gün ettim hiç ağlamadan

Yar diye kimseye bel bağlamadan

Farkına varmadan hiç anlamadan

Tutuldum güzelim şaka bir yana

Yıllarca isterken aşktan affımı

Sevginle süsledim her tarafımı

Bir oyun zannetme itirafımı

Tutuldum güzelim şaka bir yana', '“Gönlünde bana yer var mı” diyerek Şakayla karışık takıldım sana Kaptırdım kendimi aşka giderek Tutuldum güzelim şaka bir yana “Aşkından del...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saka-bir-yana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılbaşı', 'yilbasi-zulfikar-yapar-kaleli-fcr72', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu kanlı yıla da zevkli başladık

Eğlenmek zulümdür gülmek zulümdür

Şu can Karabağ’ı çoktan boşladık

Eğlenmek zulümdür gülmek zulümdür

Analar babalar yakarken ağıt

Gözyaşı mürekkep leçeği kâğıt

Doğuda Mehmetçik olurken şehit

Eğlenmek zulümdür gülmek zulümdür

Soğukta aç susuz kıvranan Gazze

Evladı fatihan doğranan Gazze

Kardeşler bacılar şu yanan Gazze

Eğlenmek zulümdür gülmek zulümdür

Bir yanda İsrail beni boğazlar

Bir yanda Ermeni yüreğim sızlar

Eğlenmek size mi düştü kansızlar

Eğlenmek zulümdür gülmek zulümdür

Kaleli bu yılda kanla gözyaşı

Medeni Avrupa çıbanın başı

Eğlen bire kansız bugün yılbaşı

Eğlenmek zulümdür gülmek zulümdür

01.01.1994', 'Bu kanlı yıla da zevkli başladık Eğlenmek zulümdür gülmek zulümdür Şu can Karabağ’ı çoktan boşladık Eğlenmek zulümdür gülmek zulümdür Analar...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yilbasi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mucize...', 'bir-mucize-muammer-baydere-oi1fh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dilim feryat etmekte bana göre haklıdır

Fakat isyan sayılmaz bir sitemdir sözlerim

Seni seven kalbimde ne acılar saklıdır

Bir mucize bekliyor gülmek için gözlerim

Sevincimle kederim paylaşırken kozunu

Sen keyifle verirsin mutluluğun pozunu

Bana da almak düştü umutların pozunu

Bir mucize bekliyor gülmek için gözlerim

Bende neşe kısıtlı hüzün dersen limitsiz

Ziyafetten vazgeçtim gönlüm sensiz simitsiz

Çaresi yok derdimin korkarım ki ümitsiz

Bir mucize bekliyor gülmek için gözlerim

Bu gidişle huzura mümkün değil ulaşmak

Senden sonra bir aşka ne haddime bulaşmak

Kısmet olmadı bir gün tebessümle dolaşmak

Bir mucize bekliyor gülmek için gözlerim', 'Dilim feryat etmekte bana göre haklıdır Fakat isyan sayılmaz bir sitemdir sözlerim Seni seven kalbimde ne acılar saklıdır Bir mucize bekliyo...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-mucize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayıkla Pirincin Taşını', 'ayikla-pirincin-tasini-muammer-baydere-07gs2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her önüme çıkan seni seviyor

Kime sorsam seni “sevgilim” diyor

Benim bu işlere aklım ermiyor

Ayıkla pirincin taşını şimdi

Sen aşkı sevdayı oyun mu sandın

Gölgeni gördün de boyun mu sandın

Çok canları yaktın sonunda yandın

Ayıkla pirincin taşını şimdi

Kimine bir ümit verip geçersin

Kimine gizlice gülüp geçersin

Aşkı her gönülden nasıl içersin

Ayıkla pirincin taşını şimdi', 'Her önüme çıkan seni seviyor Kime sorsam seni “sevgilim” diyor Benim bu işlere aklım ermiyor Ayıkla pirincin taşını şimdi Sen aşkı sevdayı o...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayikla-pirincin-tasini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Bilir! ! !', 'baba-bilir-zulfikar-yapar-kaleli-8kcdf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalaklardan makamlara inmeyi 

Hebalar mı bilsin baba dururken? 

Devlet kasasından köşe dönmeyi 

Tebalar mı bilsin baba dururken? 

Şu semer, şu eyer, şu yular, tanı 

Bunlar için dara koyar vatanı 

Yüzsüz mekanlarda, üssüz yatanı 

Dubalar mı bilsin baba dururken? 

Yalpa eşek, sırlı dönek, gütmeyi 

Blucinli, kotlu, inek gütmeyi 

Gene, pire, sivrisinek, gütmeyi 

Obalar mı bilsin baba dururken? 

Çamurlu zemini, hovarda damı 

Suni tebessümü, arsız adamı 

Zamansız, mekânsız, devrilen çamı 

Sobalar mı bilsin baba dururken? 

Sahipsiz meydanın asri yamanı 

Toz bulutlu koca dağın dumanı 

Rüzgarda savrulan sapı, samanı 

Yabalar mı bilsin baba dururken? 

Dörde nikahlıyı, beşe sözlüyü 

Karabasan, hokkop, kedi gözlüyü 

Yer altı, kanunsuz, saklı gizliyi 

Çabalar mı bilsin baba dururken?', 'Yalaklardan makamlara inmeyi  Hebalar mı bilsin baba dururken?  Devlet kasasından köşe dönmeyi  Tebalar mı bilsin baba dururken?  Şu semer, ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/baba-bilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayağıma Geleceksin', 'ayagima-geleceksin-muammer-baydere-t6zaf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her zaman dilimde hep aynı cümle

Dertleştim masamda solan gülümle

Bir bahse tutuştum kendi kendimle

Bir gün ayağıma geleceksin sen

Kendine getirir seni bu beste

Elinde olacak güzel bir deste

Gözlerim yollarda kulağım seste

Bir gün ayağıma geleceksin sen

Bir karış havada olsa da aklı

Sevenin kalbinde bir ümit saklı

Zaman gösterecek hangimiz haklı

Bir gün ayağıma geleceksin sen', 'Her zaman dilimde hep aynı cümle Dertleştim masamda solan gülümle Bir bahse tutuştum kendi kendimle Bir gün ayağıma geleceksin sen Kendine g...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayagima-geleceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımdan Teğet Geçiyorsun', 'hayatimdan-teget-geciyorsun-arif-baltaci-41d99', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeni dağılmıştı gönlümün

Hüzün yağdıran bulutları

Ve ben küçüktüm daha 

Katlanmak için büyük acılara.

Zamanla parmaklarım sigara, 

Yüreğim sen kokmaya başlamıştı.

Asi bir kısraktı sevgi. 

Ben onunla çok diyarlar gezdim.

Konya’nın bozkırında kurudum,

Ankara’nın soğuğunda titredim.

Ama bir an olsun sevginden vazgeçmedim.

Heyhat, zaman su misali akıyordu

Çocukluktan gençliğe...

Her şey değişiyordu da 

Bir seni seven çocuk yanım aynı kalıyordu.

Şiirler yazıyordum, utanıyor sana okuyamıyordum.

Seviyordum ölesiye ama sana söyleyemiyordum.

Dedim ya çocuktum işte.

Ve çocuklar bilmezdi iki yalanın arası kaç saatti.

A kalbinden B kalbine gidecek bir seyahatin 

Kaç saat süreceğini hesaplayamamıştım 

Çünkü ben senin kalbinde esir kalmıştım.

Neden sevilmezdi mahpusluk bu yüzden anlayamadım.

Kaldırıp kafamı gökyüzüne

Derin siyahı ve yıldızları seyrederdim her gece,

Üşürdüm yokluğunu hissedince 

Ben her nefeste seni düşünürdüm...

Bir tarafı yamalı yorgan ısıtmıyor ki yüreğimi,

Mısır tarlalarında garip uğultular çıkaran rüzgar da anlamıyor beni,

Bahçemizdeki havuza su içmeye gelen güvercinlerde.

Ne bilsin yağmur sana olan sevgimi

Avutmaz, avutamaz beni hiç kimse

Ağır aksak yürüyorum sokaklarda 

Sırtımda her daim artan aşkımın yükü 

Eziyor beni nefes alamıyorum

Oysa sen buna sebep olarak sigarayı gösterip

Bırak artık şunu diyorsun

Bir bağımlılıktan kurtulmak için

Yenisi gerek bunu biliyorsun

Biliyorsun da hayatıma girmiyorsun. 

Hep hayatımdan teğet geçiyorsun....', 'Yeni dağılmıştı gönlümün Hüzün yağdıran bulutları Ve ben küçüktüm daha  Katlanmak için büyük acılara. Zamanla parmaklarım sigara,  Yüreğim s...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/hayatimdan-teget-geciyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-yucel-karakilic-knhlm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine akşam oldu. Aciz ruhuma,

Aldığım nefesle girdi, yalnızlık.

Güneşle beraber batan bahtıma,

Hüznün gölgesini serdi, yalnızlık.

Gecenin kucağı karanlık, cansız,

Esrarlı sırırına ermek imkansız,

Zayıf benliğimde, sessiz sedasız,

Ömür boyu hüküm sürdü, yalnızlık.

Ayın şavkı puslu, romantizmi yok,

Rüzgar durgun, deniz coşkusuz donuk,

Sezgilerim nemli, içerim buruk,

Beni hep bu halde gördü, yalnızlık.

Hayaller beynimin can sıkıntısı, 

Aklımı zorluyor her takıntısı,

Duygular gönlümün son yıkıntısı,

Ne huzur, ne umut verdi, yalnızlık.

Titreşen mum gibi, hevesle yanan,

Kıvranan arzumun şehveti ziyan,

Sonsuz ihtirasla, kimbilir, şu an,

Kaç bedende sona erdi, yalnızlık.

Hicranla avuttum, meçhul hasreti,

Murad göstermedi, vuslat nöbeti,

Gizli paylaşılan bir günah gibi,

Her güzel insanın derdi, YALNIZLIK...', 'Yine akşam oldu. Aciz ruhuma, Aldığım nefesle girdi, yalnızlık. Güneşle beraber batan bahtıma, Hüznün gölgesini serdi, yalnızlık. Gecenin ku...', ARRAY['Türk Edebiyatı','Şiir','Yücel Karakılıç']::text[], 8.5, '{"poet":"Yücel Karakılıç","poet_slug":"yucel-karakilic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalnizlik-254-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmiyor', 'bitmiyor-arif-baltaci-0qdth', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Resimlerdeki her çizgide bir anlam varmış

Söyleyebilir misin alnımdaki çizgilerin anlamını.

Özellik şu derin olan neyi anlatıyor

Herkes anlıyor seni sevdiğimi

O derin çizgi bile anlıyor 

Senin ruhun feryadımı duymuyor.

Orhan baba söylüyor bir taraftan

Bir taraftan Doğukan söylüyor

Gitmiyor sevdiğim gitmiyor 

Sevdan ruhuma işlemiş 

Git desem de gitmiyor.

Umut bende bitmiyor...', 'Resimlerdeki her çizgide bir anlam varmış Söyleyebilir misin alnımdaki çizgilerin anlamını. Özellik şu derin olan neyi anlatıyor Herkes anlı...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bitmiyor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiiri Sana Yazdım', 'bu-siiri-sana-yazdim-arif-baltaci-dngvd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Merhaba; ömrüme doğan güneş

Şiirlerim sana yazıldı bu defa 

Gönlüme yağdırdığın yağmurlar

Aşk oldu, çoştu bu defa...

İlk bahar de bu mevsimin adına 

İstersen sevda de benim duygularıma 

Varmış gözüm bir kere sana bakmanın tadına 

Umrumda mı yağan kar, umrumda mı sonbahar....

Nedeni olmaz sevmenin, mantığı olmaz.

Bırak sorgulamayı tut ellerimden

Sonsuz bir meçhulde kaybolurken anılar 

Bana gel vakit kaybetmeden...

Eskiden kalma alışkanlıklarını bırak

Seni seven bu oğlana umut ver

Ellerimi tutmasan da olur 

Gözlerime bakıp gül yeter...

Yazılmış kaderime sevdan

Yüreğime kazınmış adın gizlice 

Gel sevdiğim kimseler görmeden gel

Bari rüyalarıma gir bu gece....

Adını koyamamıştım ya yalnızlığımın

Artık adını çok iyi biliyorum

Senin olmadığın her yerde 

Ben yalnızım diyorum...

Lal olurdu dilim seni görünce 

Sensiz geçen anlarıma lanet ederdim

Ahh dört mevsim öteden gelsen bana 

Seni sen gibi değil, kendim gibi severdim...

Dertlerimizi paylaştık da seninle

Bir tek seni sevdiğimi söyleyemedim.

Hayalin gitmedi gözümün önünden

Her duada tanrımdan seni diledim...

Issız sokaklarda dolandım durdum.

Dinmedi içimdeki asi rüzgarlar 

Gel sevdiğim, doğ kalbime güneş gibi 

Gel ki yaşansın gönlümde bahar...

Zindan olur geceler sen gelince aklıma

Gün ışığı kapıma boş yere gelir.

Bilmez ki sen gelmeden dinmez karanlık 

Sensiz her yer benim hücremdir.

Leyla’yı ararken ben seni buldum.

Mecnun oldum çöllerde bırakma beni

Beni çölün sıcağı etkilemezde 

Aşkının ateşi yakar sinemi...

Ilgıt ılgıt esen rüzgarlarla gel 

Gir gönlüme sevdiğim, sonum ol benim.

Tut ellerimi meydan okuyalım ölüme

Anla artık beni, canım ol benim

Senliğini at bir yana, benim ol benim...', 'Merhaba; ömrüme doğan güneş Şiirlerim sana yazıldı bu defa  Gönlüme yağdırdığın yağmurlar Aşk oldu, çoştu bu defa... İlk bahar de bu mevsimi...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/bu-siiri-sana-yazdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Adaletsiz ki Şu Hayat Dedikleri', 'oyle-adaletsiz-ki-su-hayat-dedikleri-melih-coskun-mpk5l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle adaletsiz ki 

Şu hayat dedikleri oyun

Dönüp duruyor başımız acıların ekseninde 

İnsanlar unutturdular bana 

Kendilerine güvenebilmeyi

O gün bu gündür 

Aşka sığınıyorum. 

Yağmurdan kaçan bir kedi yavrusu gibi.

Zor yolların yolcusuyduk 

Kirlenmemiş yüzlerimizle 

Kovulduk girdiğimiz bütün kapılardan. 

Fazla geldi dürüstlüğümüz 

Yaşamak için yalancıların dünyasında 

Yüreğimiz büyük geldi 

Yüreksizliğinin ardına sığınanlara 

Öyle adaletsiz ki şu hayat denilen 

Hainleri kahraman yapar 

Gerçek kahramanlarını hain.

Sevmek terk etmeyi gerektirir

Nefretse ilk sayfa haberi gazetelerde. 

Gür çıktıkça sesim 

Kalın duvarlar örerler etrafıma

En büyük hatadır bahsetmek 

Haktan 

Alın terinden 

Hürriyetten.

Meze yapılır alın teri sarhoş masalarında 

Haysiyet kapı dışarı çıkmaya utanır ay başlarında 

Ve dünya dönmektedir hala 

Acıların ekseninde…', 'Öyle adaletsiz ki  Şu hayat dedikleri oyun Dönüp duruyor başımız acıların ekseninde  İnsanlar unutturdular bana  Kendilerine güvenebilmeyi O...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/oyle-adaletsiz-ki-su-hayat-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün İstanbul’dan Ayrılacağım...', 'bugun-i-stanbul-dan-ayrilacagim-arif-baltaci-c64ec', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boğazıma düğümlendi yalnızlık

Gönlüm bir namlu şimdi

Tam şakağından vuracağım sensizliği 

Asi ezgilere aldırmayacağım.

Küçük bir yavru ceylana verip umutlarımı,

Bugün İstanbul’dan ayrılacağım.

Anadolu’nun tezek kokan yollarına vuracağım kendimi

Artık biraz da kendime yaşayacağım.

Seni hatırlatan her şeyi dağıtıp sokak çocuklarına 

Artık adını unutacağım.

Seni doğduğun yere bırakıp 

Bugün İstanbul’dan yani senden 

Yani sevdiğimden ayrılacağım.

Yazdığım şiirleri duymayacaksın artık 

Ve sana yük olan sevgimi 

Vapurdan martılara atacağım.

Sileceğim adını gönlümden 

Biraz da kendime yaşayacağım.

Bugün İstanbul’dan ayrılacağım...', 'Boğazıma düğümlendi yalnızlık Gönlüm bir namlu şimdi Tam şakağından vuracağım sensizliği  Asi ezgilere aldırmayacağım. Küçük bir yavru ceyla...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bugun-istanbul-dan-ayrilacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Gel', 'bana-gel-arif-baltaci-vit70', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızsan, korkuyorsan karanlıktan

Kaybettiysen bütün umudunu

Ve gönlündeki asi ezgiler azıyorsa yine 

Hiç düşünme, bana gel...

Bir acı kahve çektiyse canın,

Sıkıldıysan etrafındaki uzun burunlu pinokyolardan

Uykun kaçtıysa gecenin kuytusunda

Hiç düşünme, bana gel...

Ağır geliyorsa yaşamak 

Acıktıysan kara sevdaya

Papatyalardan medet ummayı bırak

Hiç düşünme, bana gel...

Üşüyorsun sahte baharlarda 

Sıcak bir yüreğe muhtaç kalmışsan 

Her şeyi geride bırak 

Hiç düşünme, bana gel...

Görmek istiyorsun bendeki seni

Bulmak istiyorsun hayallerini 

Artık sebep aramayı bırak

Hiç düşünme, bana gel...', 'Yalnızsan, korkuyorsan karanlıktan Kaybettiysen bütün umudunu Ve gönlündeki asi ezgiler azıyorsa yine  Hiç düşünme, bana gel... Bir acı kahv...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bana-gel-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende ki Sevdan', 'bende-ki-sevdan-sevgili-ozbek-ssnum', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen

Güneş kadar yakın

Bir o kadar uzaksın.

Yıldızlar kadar parlak

Bir o kadar çıplaksın.

Söyle bana güneşin oğlu

Nedir beni cezbeden sende ki

İçmeye susadığım dudakların mı 

Yoksa

Umutla

Pırıltılarını görmek istediğim

Karagözlerin mi

Sevinçle duymak istediğim

Melodik vuruşlarımı kalbinin

Yoksa

Özlemle yüzmek mi

Yüreğinin engin denizinde

Ya da

Hasretle yalnızlığımda ki bana

Bende ki yalnızlığa

Gömülen sevdan mı', 'Sen Güneş kadar yakın Bir o kadar uzaksın. Yıldızlar kadar parlak Bir o kadar çıplaksın. Söyle bana güneşin oğlu Nedir beni cezbeden sende k...', ARRAY['Türk Edebiyatı','Şiir','Sevgili Özbek']::text[], 8.5, '{"poet":"Sevgili Özbek","poet_slug":"sevgili-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bende-ki-sevdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla İstanbul', 'agla-i-stanbul-arif-baltaci-tw32q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey be İstanbul, ey taşı toprağı altın

Sevdaları yalan, sevenleri hain şehir.

O boğazının mavileri yetmedi mi sana 

Gözyaşımı da istedin benden.

Aksın sevdiğimin uğrunda gözyaşlarım  ne çıkar ki 

Varsın durmasın sonsuza kadar

Senin mavilerin yetmiyorsa sana

Ağlarım yetene kadar aklımda sevdiğim var.

Ağıt yaksın yaşlı teyzeler ardımdan

Yalnızım ey gökteki yıldızlar.

Ağla be kahpe İstanbul

Sende ağla biraz benim ardımdan.

Bahara soyunan taze çiçek kokan ormanlarını

Bindiğim vapurun ardından uçan martılarını

Ve beni sevmeyen o kadını

Çıkarıp anılarımdan gideceğim şehrinden 

Çantama biraz umut, çok az dostluk ve biraz da vefa aldım

Bütün kötü anlarımı sana miras bıraktım.

Dedim ya İstanbul biraz da sen ağla.

Benim acım zaten yeter bana.', 'Ey be İstanbul, ey taşı toprağı altın Sevdaları yalan, sevenleri hain şehir. O boğazının mavileri yetmedi mi sana  Gözyaşımı da istedin bend...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/agla-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zannetik ki oldu / kınama/protesto', 'zannetik-ki-oldu-kinama-protesto-zafer-zengin-etnika-zf8e0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'öyle bir umut bekledik şiiri

yanımıza damlardı kan

küçük elimizden

kıymık batar dizelerden

dolama olurdu

biz oynardık

şehir uyurdu

hayatın omuzun da

biz korkardık

zannettik ki

ikisi de bizi unutacak

oyunlar çocuksuz kalacak

gün bizimle yorulacak

biz büyüdük

umut oldu

şiir geldi

gün yoruldu

zannettik ki oldu

21 06 2005

Şair ve insan olarak görevim ve insalığım gereği: 

2 Temmuz 1993’de sivasta yakılarak

Katledilen sanatçı ve aydınlarımızı saygıyla anıyorum.

2 Temmuz 2005 günü Ankara’da   Hakan Peker ve Alişa’nın katılacağı

ve havii fişek gösterilerinin yapılıp vatandaşın bu acı günde eğlenip

kendinden geçmesini isteyen Ankara Büyükşehir Belediye Başkanı

Melih Gökçek''i de kınıyorum. Tüm demokrat aydınları,İnsani tavırdan ödün vermeyenleri,site yönetimini ve değerli şair arkadaşları da bu ayıp için tepki

vermeye davet ediyorum.

Aynı Hakan Peker sanırım bu olayı bilmiyor ki; 

http://www.hurriyetim.com.tr/haber/0,,sid~456@nvid~486593,00.asp

bu linkte cumhuriyet bayramında konser vermiş.

ANKARA BÜYÜKŞEHİR BELEDİYESİ  Eğitim Kültür Daire Başkanlığı 

Kültür Etkinlikleri

Eğitim ve Kültür Daire Başkanlığı, Hizmet İçi Eğitim Şube Müdürlüğü, Halk Eğitim Şube Müdürlüğü, Eğitim Merkezi Şube Müdürlüğü, Planlama ve Koordinasyon Şube Müdürlüğü, Turizm ve Tanıtma Şube Müdürlüğü, Kültür Etkinlikleri Şube Müdürlüğü, Yayınlar ve Kütüphaneler Şube Müdürlüğü, Kent Orkestrası ve diğer alt birimlerden oluşmaktadır. Daire Başkanlığının görev ve sorumluluklarını aşağıdaki şekilde özetlemek mümkündür: 

* Belediye Başkanlığı tarafından belirlenen amaç, ilke ve talimatlar ile ilgili mevzuata uygun olarak belediyenin eğitim ve kültür etkinliklerini değişen koşullara uygun bir şekilde, seçenekli olarak belirleyip başkanlık onayına sunmak, onaylanmış eğitim ve kültür seçeneklerini bağlı birimleri koordine ederek uygulamak, veri tabanı ve ihtiyaç tablosunu düzenlemek.

* Belediye personelinin hizmet içi eğitim ihtiyacını tespit etmek, eğitim plan ve programlarını hazırlamak, uygulamak ve değerlendirmek.

* Eğitim ve kültür faaliyetleri için gerekli olabilecek ortamı, araç gereç ve teknolojiyi belirlemek, diğer birimlerin eğitim merkezindeki faaliyetlerini zamanlamak ve koordine etmek.

* Daire Başkanlığına bağlı birimlerin yıllık plan ve programlarım birleştirmek,bunları belediyenin temel stratejisi ve bütçe imkanlarına uyarlamak.

* Belediyenin amaç, ilke ve hedeflerine uygun olarak her türlü kültür etkinliğini planlamak, uygulamak, değerlendirmek ve raporlaştırmak.

* Belediye kitaplıkları için gerekli yayınların tespiti, temini, korunması ve servis hizmetlerini yürütmek.

* Belediye sorumluluğunda bulunan tarihsel ve kültürel kalıtların korunup geliştirilmesi ve tanıtılması, iç ve dış turizm için özendirici önlemlerin tespiti ve bunlarla ilgili yayın faaliyetlerini yürütmek.

* Kent halkının bilgi ve beceri düzeyinin yükseltilmesi için kültürel, mesleki ve teknik eğitim programlarını üretip uygulamak ve değerlendirmek.

* Kent halkına geleneksel ve evrensel müziğin çeşitli türlerini açık ve kapalı mekanlarda sunarak kent halkının kaynaşmasını, toplumsal moralin yükseltilmesini ve ortak bir kent kültürünün oluşmasını sağlamak.

Özellikle son madde çok ilginç..ne demek lazım bunlara bilmem ki..Toplumsal moral böyle yükseltiliyor herhalde..maşallah..maşallah..nazar değmesin..2 Temmuz da böylesi bir  Konserle herhalde moral olsun bazı şeyler unutulsun yaşanmamış gibi varsayılsın diyorlar..

Bu ne insanlığa ne kamu görevi yapan bir kuruluşa ne de o konsere katılan Sanatçılara yakışır.. Halkımızı duyarlı olmaya davet ediyorum...

Kaynak; http://www.ankara-bld.gov.tr/Birimalt.asp? birimkategori=018', 'öyle bir umut bekledik şiiri yanımıza damlardı kan küçük elimizden kıymık batar dizelerden dolama olurdu biz oynardık şehir uyurdu hayatın o...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/zannetik-ki-oldu-kinama-protesto-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Seni Düşündüm', 'hep-seni-dusundum-cemal-yasar-2z11h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep Seni Düşündüm

Yapayalnızlığın hasretliğinde

Akan suyun şırıltısında,

Sallanan kavakların hışırtısında,

Ve yağan yağmurun çiseliğinde,

Hep seni düşündüm.

Gökyüzünün ufkunda,

Derin vadinin yankılanışında,

Yolların sonsuzluğunda,

Ve on iki burcun kuşağında

Hep seni düşündüm.

Ferhat’ın dağ delişinde,

Yanan Kerem’in alevinde,

Mem’in Zine olan hasretinde,

Ve kelebeğin ışığa atışında,

Hep seni düşündüm.

Işığın karanlığında,

Zindanların duvarlarında,

Sarp dağların doruklarında,

Ve dönen dünyanın yuvarlaklğında,

Hep seni düşündüm.', 'Hep Seni Düşündüm Yapayalnızlığın hasretliğinde Akan suyun şırıltısında, Sallanan kavakların hışırtısında, Ve yağan yağmurun çiseliğinde, He...', ARRAY['Türk Edebiyatı','Şiir','Cemal Yaşar']::text[], 8.5, '{"poet":"Cemal Yaşar","poet_slug":"cemal-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hep-seni-dusundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Koyamadım Yalnızlığımın -2-', 'adini-koyamadim-yalnizligimin-2-arif-baltaci-ej7q3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her yeni doğan günden seni diledim.

Beklemenin sabırsızlığı yaşadım 

Tenha ve sen kokan sokaklarda.

Oysa biliyordum yine gelecektin bana

Yüzünde masum gülümseyişin

Elinde ufak kırmızı çanta 

Ya çok yoruldum taşısana diyecektin.

Yorulana kadar umarsızca dolaşacaktık yollarda

Çamlıca’nın ardından güneş tepeye doğru yol alıyor

Saat ayrılığı çoktan geçmiş

Ve ben hala seni bekliyorum

Biliyorum her gün daha da ağaracak saçlarım

Biliyorum her gün daha da ağır gelecek yaşamak

Oysa bana söz vermiştin, sana söz vermiştim

Bir Perşembe gecesi gittiğin gibi gelecektin

Bende vuslat gününe kadar seni bekleyecektim.

Ne çok dualar ettim tanrıya 

Bir kez daha göreyim diye rüyamda seni.

Sevdiğim, günüme doğan güneşim benim.

İstanbul artık bana dar geliyor.

Sigaraya da başladım yeniden.

Her nefeste seni çektim içime 

Her nefeste seni düşündüm.

Bu yüzdendi sigaraya düşkünlüğüm.

Tam da mutluluğun şifresini çözmüşken 

Anlayamadın bu acele gidişin neden....

Toplamadan valizini, düşünmeden sensiz beni

Henüz çizmemiştik ki mutluluğun resmini

Oysa biraz umudun mavisinden katacaktık 

Birazda gözlerindeki kahverenginden 

İçine kalbinin beyazından koyacaktık

Ve birazda ilk bahar yeşilinden...

Daha bitmemişti ki resmimiz 

Bu acele gidişin anlamadım neden...

Yine sensiz uyandım 

Kaç gün oldu sevdiğim alışamadım

Ben senin yokluğuna dayanamadım

Geçen zamanın inadına daha bir arttı acım

Yalnızım sevdiğim yalnızım

Kimse anlamıyor beni

Kimse dindiremiyor içimdeki sensizliği,

Oysa “hiç adı koyulur mu yalnızlığın derdi” Sevil hanım

Ama ben hala adını koyamadım yalnızlığım

Annem “Onlarca dostun var ya etrafında oğlum” diyor 

Oysa ben sensiz yapayalnızım annem bunu bilmiyor.

Ne çıkar ki etrafımda binlerce insan olsa 

Sensiz olmak, yalnızlık demektir benim lügatımda...

Kaç zaman geçti sevdiğim sen yoksun

Biliyorum dönemezsin gittiğin yerden

Biliyorum sen daim beni beklersin

Gece uyurken rüyama gelir 

Gündüzleri her an beni izlersin.

Ben sensiz doğan her güne lanet ettim.

Her gece tanrıdan seni istedim.

Mezarının başında ne dualar ettim.

Sana gelmeyi de beceremedim sevdiğim..

Sana gelmeyi de beceremedim.', 'Her yeni doğan günden seni diledim. Beklemenin sabırsızlığı yaşadım  Tenha ve sen kokan sokaklarda. Oysa biliyordum yine gelecektin bana Yüz...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/adini-koyamadim-yalnizligimin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem 1', 'deprem-1-cemal-yasar-laqmj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'DEPREM I

Ay perde olup 

Güneş''i örtmüştü.

Karanlık kabus olup

Dünya''nın üzerine çökmüştü.

Deniz duygulanmış

Isınıp ağlıyordu,

Öfkelenip kabarıyordu.

Hiç kimse; 

Ey deniz! 

Neden ağlıyorsun,

Neden kabarıyorsun? 

Diye sormuyordu.

hiç kimse; 

Ey Güneş! 

Neden görünmüyorsun,

Niçin karartıyorsun? 

Diye sormuyordu.

Onbir Ağustos

Belki de yas tutuyordu

On yedi Ağustos için.

Bulutlar kafile kafile

Vermek için kara haberi

Toplanmıştı Marmara semasına.

Yılanlar deliklerden,

Fareler köşelerden

Ayrılmıştı.

Her taraf sessiz,

Karanlık ve mahzundu.

Bedenler suskun,

Derin bir uykuda

Olup bitenden habersiz

Yarın için 

Hayal kuranlar vardı.

Tatlı rüyada

Umudu peşinde koşanlar için

Uyku daha da ağırdı.

Ve 17 Ağustos

2000''e dört ay kala

Gece 3.02

Yer,gök,deniz,gece ve insan

Birleşip bağırmaya, çağırmaya

Ulumaya saniye tuttular.

Yer yarılmıştı,

Deniz yükselmişti,

Marmara beşik gibi sallanıyordu.

Evet! 

Dünya o an beşik,

Tabiat, ana,

Uyuyanlar da bebek olmuştu.

Ama tabiat ana,

Uyutmak için değil,

Adeta öldürmek için

Sallıyordu evlatlarını.

Çok katlı binalar

Yerle bir olmuş

Beton yığınları altında

Kimi ölü kimi sakat

Kimi de nefessiz kalmıştı.

Bir ana bağırıyordu:

Uyy oğlum Ahmet! 

Vay kızım Emine! 

Muratsız gittiniz.

Yok mu sizi kurtaracak,

Şu taşın altında olacak

Yok mu bu taşı kaldıracak,

Oğlum aha burda

Kızım aha şuracıkta oturuyordu.

Hani nerede,

Kimse yok mu,

Nasıl oldu,

Ne oldu? 

Canlarım! 

Yeni kazanmıştı üniversiteyi

Oğlum Ahmet.

Uyy sana kurban olaydı

Anan Ahmet! 

Canım kızım! 

Doktor olacağını söylüyordu.

Bana bakacağını söylüyordu.

Hayatı ne kadar sevdiğini 

Haykırıyordu.

Uyy canım kızım! 

Seni gelin edeydim,

Muradına erdireydim,

Seni böyle görmeyeydim,

Yıkamadan gömmeyeydim.

Yandım anam,yandım babam

Dünya yıkıldı başıma

Nerede hani,

El uzatan yok mu? 

Oğlum da kızım da 

Burada.

Ölemezler,ölmemişler,ölmesinler.

Kahrolası betonlar,

Kahrolası duvarlar

Üzerimize yıkıldınız,

Ocağımızı söndürdünüz.

Keşke yerinizde ben olaydım.

Çaresizim,yalnızım, kimsesizim.

Betonların altında cesetler,

Kurtarmaya daha gelecekler

Can çekişiyor bedenler,

1,2,3,4 diye geçiyor günler.

Haykırıyordu Davut Amca:

Ey toprak ana! 

Ne istedin bizden,

Ne yaptık sana,

Neden öfkelendin,

Neden bizi öldürdün? 

Konuşsana,anlatsana

Dile gelsene.

Evsiz kaldım,

Duygularım sönük,

Elim ayağım tutmuyor.

Bir aylık torunumdan 

Ne istedin? 

Ailemi aldın,

Çocuklarımı aldın,

Ne yaparım şimdi,

Nereye giderim,

Nasıl yaşarım? 

Benimle konuşsana

Başını kaldırsana

Senin de benim gibi

Derdin var mı ki

Yalnızım, çaresizim,kimsesizim.', 'DEPREM I Ay perde olup  Güneş''i örtmüştü. Karanlık kabus olup Dünya''nın üzerine çökmüştü. Deniz duygulanmış Isınıp ağlıyordu, Öfkelenip kaba...', ARRAY['Türk Edebiyatı','Şiir','Cemal Yaşar']::text[], 8.5, '{"poet":"Cemal Yaşar","poet_slug":"cemal-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":127,"source_url":"https://www.antoloji.com/deprem-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söndüremedim.', 'sonduremedim-veysel-alkan-hmw0q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aslında maziye gömerdim seni,

Unutmayı gözüme kestiremedim.

Ağlattın,inlettin yıllarca beni,

Sözümü gönlüme geçirtemedim.

Kaç kere başladı bu aşk biterken,

Ayrılık rüzgarını estiremedim.

Vazgeçmeyi düşündüm acı çekerken,

Ne varki sabrımı bezdiremedim.

Mutluluk aradım huzur istedim,

Doğruyu kendime seçtiremedim.

İsyanım mı olmadı,ah mı etmedim,

Bağıma güllerini ektiremedim.

Aklımın ucuna geldi figanlar,

Dilime kötü söz ettiremedim.

Dalgalandı duygular,taştı arzular,

Önünde bent oldum bitiremedim.

Yıkılmış perişan kaldım aşkından,

Ben sana kalbimi küstüremedim.

Canımı yakıyor kor gibi sevdan,

Uğraştım uğraştım söndüremedim.

16/02/2002-İsatanbul', 'Aslında maziye gömerdim seni, Unutmayı gözüme kestiremedim. Ağlattın,inlettin yıllarca beni, Sözümü gönlüme geçirtemedim. Kaç kere başladı b...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sonduremedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem II', 'deprem-ii-cemal-yasar-fphih', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'DEPREM II

Dipten gelen dalga

Ağıtlarla feryatlarla

Bir haykırış

Bin yıkılış

Binlerce ses

Bir bu yana

Bir o yana

Şefini kaybetmiş 

Bir orkestra adeta

17 Ağustos

03:02

Mahşerin diğer adı

Yankılanıyor

İnsanlığın feryadı

Darmadağınık düşünceler

Tar u mar olmuş her yer

Enkaz altında cesetler

Yok edilmiş yürekler

Dipten gelen dalga

Kökü Afrika’da

Gövdesi Arabistan’da

Başı Yunanistan’da

Feryadı Türkistan’da

Karalar karalara bürünmüş

Feryatlar içinde kaynıyor deniz

Gökyüzü göz yaşı döküyor

Dipten gelen faylar

Üç kıtayı sallar

Bebek,genç,ihtiyar demez

Vurur

Düşer bütün insanlar

Feryat,imdat,haykırış

İnfial,ah u vah,inleyiş

Yankılanan sesler

Buğulanan gözler

Yanan yürekler

Allah’a açılmış eller

Aciz

Ve de

Çaresiz kalan medeniyetler

Sonucu değiştirmeyen vaatler

Yetersiz kalan teknoloji

Çare olmayan yırtık çadırlar

Kulağı olmayan rasathaneler

Dipten gelen faylar

Ve ölen ölür

Nerede kalan sağlar

Bunlar mı dediniz

Belki de hiç biri

Dipten gelen faylar

Ve sallanan kıtalar

Vurulur bütün insanlar

Yardıma koşanlar

Değil yakınlar

Yine uzaklar

Kurtaranlar

Yine halklar

Yardımı almayanlar

Düşünüp bir daha taşınsınlar

Kardeşlik insanlık ölmedi

Ey insanlar! 

Irkçılık enkaz altında

Çıkmaz bir daha bu dünyada

En güzeli halkların kardeşliği

Devletlerin savaşları

Olur

Zenginlerin karları

Onlar da olur 

Halkların düşmanları

Her şey

Kar için değil

Yaşamak için

Vurmak için değil

Kardeşlik için

Yıkmak için değil

İnşa etmek için

Bütün insanlar kardeştir

Düşman olan kardeştir

Beyaz ırk siyah ırk sarı ırk

Bizim için zenginliktir

Herkes koştu yardıma

Yaptı düşeni payına

Düşmanlık düştü fay hattına

Filizlendi insanlık

Kardeşlik adına

Deprem kardeşliği derler

Tek bir oluyor yürekler

Yardıma koşuyor ülkeler

Gömülüyor kan emici böcekler.', 'DEPREM II Dipten gelen dalga Ağıtlarla feryatlarla Bir haykırış Bin yıkılış Binlerce ses Bir bu yana Bir o yana Şefini kaybetmiş  Bir orkest...', ARRAY['Türk Edebiyatı','Şiir','Cemal Yaşar']::text[], 8.5, '{"poet":"Cemal Yaşar","poet_slug":"cemal-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/deprem-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oynama Benimle Oyuncakçı', 'oynama-benimle-oyuncakci-suheyl-turkoglu-5ybbt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hadi oyuncakçı,

Sat bana hayallerimi.

Her rafında,

Ayrı bir dünya gizli.

Bırak alayım dilediğimi.

Sen öbürlerini gösterip,

Önüme Betmen''i koyuyorsun,

Şiddeti övüyorsun,

Çocuğum ya,

Kandırıyorsun.

Dükkanın çalışıyor,

Keyfin yerinde,

Kim bilir,

Daha ne kadar,

Oynarsın hayallerimle.', 'Hadi oyuncakçı, Sat bana hayallerimi. Her rafında, Ayrı bir dünya gizli. Bırak alayım dilediğimi. Sen öbürlerini gösterip, Önüme Betmen''i ko...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oynama-benimle-oyuncakci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-meyus-cetin-zf1q8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dört duvarda yalnızlık kazınmış...

Özgürlük dediğim; 

Devamlı tercih ettiğim; 

Nedir yalnızlık? 

Birkaç damla gözden,

Irmaklar gönülden,

Çağlayan en derinden,

Nedir yalnızlık? 

Geçmeli illa zaman; 

Düzinelerce insan,

Belki bilmem kaç mekan,

Nedir yalnızlık?', 'Dört duvarda yalnızlık kazınmış... Özgürlük dediğim;  Devamlı tercih ettiğim;  Nedir yalnızlık?  Birkaç damla gözden, Irmaklar gönülden, Çağ...', ARRAY['Türk Edebiyatı','Şiir','Meyus Çetin']::text[], 8.5, '{"poet":"Meyus Çetin","poet_slug":"meyus-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizlik-255-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-meyus-cetin-vewc2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Damarlarda kan yerine

Alkol akınca belki

Mantık yerine dudaktan

Duygular akar belki', 'Damarlarda kan yerine Alkol akınca belki Mantık yerine dudaktan Duygular akar belki...', ARRAY['Türk Edebiyatı','Şiir','Meyus Çetin']::text[], 8.5, '{"poet":"Meyus Çetin","poet_slug":"meyus-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/belki-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebep-i Hayat', 'sebep-i-hayat-meyus-cetin-37d3g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dökülen mısralarda gözyaşım; 

Akmıyor başka.

Düşlerde kalan hayatım; 

Yaşanmıyor başka.

Sen olsan burada,

Şurada yanı başımda.

Ellerin avuçlarımda,

Gözlerin bakışlarımda.

Umutlar var ya,

Olmasa hayatta.

Ne para, ne mal.

Sebep bulunmuyor asla...', 'Dökülen mısralarda gözyaşım;  Akmıyor başka. Düşlerde kalan hayatım;  Yaşanmıyor başka. Sen olsan burada, Şurada yanı başımda. Ellerin avuçl...', ARRAY['Türk Edebiyatı','Şiir','Meyus Çetin']::text[], 8.5, '{"poet":"Meyus Çetin","poet_slug":"meyus-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sebep-i-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-meyus-cetin-breum', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatım, sözlerim yalan

İşim, görevim hepsi yalan

Geçen günler geceler

Ben, sen, o, hepsi yalan

Sevdim, sevildim

Dostluk, arkadaşlık, aşk

Yalan hepsi yalan', 'Hayatım, sözlerim yalan İşim, görevim hepsi yalan Geçen günler geceler Ben, sen, o, hepsi yalan Sevdim, sevildim Dostluk, arkadaşlık, aşk Ya...', ARRAY['Türk Edebiyatı','Şiir','Meyus Çetin']::text[], 8.5, '{"poet":"Meyus Çetin","poet_slug":"meyus-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalan-149-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu türküsü', 'anadolu-turkusu-halil-colak-9zwh2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeşildir dağları Erzurum, Kars’ın

Sıcaklık denince Adana, Mersin

Türkülerin dilinde Edirne, Van’sın

Her yerde türkü, Anadolu türküsü

Gitmedim öteye Sivas’tan gayrı

Her yerin güzelliği hep ayrı, ayrı 

Divriği dersen benimde doğumda yeri

Her yerde türkü, Anadolu Türküsü

Elazığ söylersen gakgoş yuvası

Malatya''ya varırsan kaysı ovası

Aydın, Manisa  incir cilesi

Her yerde türkü, Anadolu türküsü

Antalya ki yurdun cennet diyarı

Boluda soylenir koroğlu destanı

İstanbul ki dünyada bulunmaz eşi

Her yerde türkü, Anadolu Türküsü

Trabzon  Karadenizin kültür merkezi

Rize’nin vardır Çamlı Hemşin’i

Samsun kurtuluşun başlangıç yeri

Her yerde türkü, Anadolu Türküsü

Artvin den gelirsin göleğe doğru

Ardahan''kı doğun sınır kapısı

Iğdır ki her türlü meyvenin yeri

Her yerde türkü, Anadolu türküsü

Urfa  şehri ki Halil rahman otağı

Diyarbakır''ki Ziya Gökalp’ın yeri

Gaziantep kebabı, Maraş''ın dondurması

Her yerde türkü, Anadolu türküsü

Çanakkale  Türkün yenilmez destanı

Bursa ki osmanlı''nın kültür merkezi

Balıkesir,,Bilecik Yörük ovası

Her yerde türkü, Anadolu Türküsü

Sakarya’m, Erzincan yaralı gelin

Zonguldak, Bartın’ını gidinde görün

Ordudan çıkıp, Giresun’una varın

Her yerde türkü,Anadolu türküsü

Hangi il kaldı dadaşım ben bilemedim

Konya’yada mevlanaya yüz sürüp geldim.

Niğde’den, Aksaraya  geç vakit vardım

Her yerde türkü, Anadolu Türküsü

Nevşehir’in Allah''tan peri bacası 

Isparta’nın mis kokan gül bahçesi

İzmir’in unutulmaz konak meydanı

Her yerde türkü, Anadolu türküsü

Sinop bu unutma, dağıtma sakın

Çorumda leblebi yiyip tadına bakın

Tokat’ı bekmezi yiyip,, Yozgat’ta kalın

Her yerde türkü, Anadolu türküsü

Batman Siirt petrol yatağı

Hakkâri’nin erişilmez yüksek ovası

Ağrı ise eskinin kara kösesi

Her yerde türkü, Anadolu türküsü

Kırklareli batıda en uçyeri

Tekirdağ hatırlatır Mehmet Akif’i

Karaman,Aksaray vilayet oldu

Her yerde türkü, Anadolu türküsü

Amasya’nın elması kaldı

Bayburt  en sonunda il oldu

Gümüşhane tekbir Kelkitle kaldı

Her yerde türkü, Anadolu türküsü

Hatayı ben nasıl unuturum

Kerkük, Musul, telef er bir başka ilim

Dişsiz kalırsam, Kırıkhan’a uğrarda yolum

Her yerde türkü, Anadolu türküsü

Lefkoşa, magosa dededen kalma

Larnaka, Lima sol senin unutma

Ciddi ol  sırıtma hilebaz ruma

Her yerde türkü Anadolu türküsü

Artvinli kardeş oynar ata barını

Karabağ’ki türkün özdiyarını

Almasın ermeni Türkün vebalını

Her yerde türkü, Anadolu türküsü

Horasan ereniyim Erzurum ilim

Ağzımı bağla salarda, durmazda dilim

Mangal gibi yüreğim, çelikten kolum

Her yerde türkü, Anadolu türküsü

Halil Çolak 01.07.2005 saat 02.13

Yenimahalle /Ankara', 'Yeşildir dağları Erzurum, Kars’ın Sıcaklık denince Adana, Mersin Türkülerin dilinde Edirne, Van’sın Her yerde türkü, Anadolu türküsü Gitmedi...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/anadolu-turkusu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muştu mu?', 'mustu-mu-ahmet-turan-altunsu-4ctc8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne yalan var, ne dolan var dilinde,

Melek desem; kanatların düştü mü? ..

Düşündüren bir halın var dilinde; 

Kor bir efkâr yüreğine düştü mü? ..

Onca kahır omuzuna yüklenmiş,

Yüklendikçe binbir sızı eklenmiş.

Yığın olmuş, yüreğinde saklanmış,

Serçe yürek yelyepelek koştu mu? 

Kaç yıl oldu ayrı düştün erinden,

Emanet can düştüğü gün erinden,

Dayandıysan, bu senin hünerinden; 

Lâkin, yürek isyân isyân coştu mu? ...

Dönüverdin, gördün: iki can bekler,

Ufka baktın, gördün: iki han bekler,

Düşe daldın; gördün ki sultan bekler; 

Gözlerinin telvesine şaştı mı? ..

Turan der ki melek yüzlü şu güzel,

Gökten inmiş; nasıl nazlı şu güzel,

Yazgım mıdır lâtif sözlü şu güzel; 

Giderayak verilmiş bir muştu mu? ..

-01.07.2005 / Ankara

-Ahmet Turan Altunsu', 'Ne yalan var, ne dolan var dilinde, Melek desem; kanatların düştü mü? .. Düşündüren bir halın var dilinde;  Kor bir efkâr yüreğine düştü mü?...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mustu-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharlar', 'baharlar-suheyl-turkoglu-ld588', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kış gelir,

Acımasız,

Soğuğuyla,

Dondurur dünyayı,

Binlerce,

Can alır,

Gaddarca.

Sonra da yumuşar,

İlk baharda,

Yaltaklanır yaza.

Yaz kavurur,

Cehennem eder,

Dünyayı,

Sıcak,

Çok sıcak,

Öyle sıcak ki,

Ölür,

Yaşlılarla çocuklar.

Özlediğimiz,

İçimizi okşayan,

Baharlar şimdi,

Sular, seller getirip,

Boğuyorlar.

Can alıyorlar.

Mayıştığımız,

Duygusallaştığımız,

İçimizin,

Bir hoş olduğu,

Baharlar,

Düşürdü maskelerini,

Romantik değiller,

Şimdi onlar,

En fazla,

Can alıyorlar.', 'Kış gelir, Acımasız, Soğuğuyla, Dondurur dünyayı, Binlerce, Can alır, Gaddarca. Sonra da yumuşar, İlk baharda, Yaltaklanır yaza. Yaz kavurur...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/baharlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimizden vatan çıktı, çıkacak', 'elimizden-vatan-cikti-cikacak-mikdat-bal-8rsij', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl oldu, uzun zaman sabrettik

Elimizden vatan çıktı, çıkacak

Acep niye biz geçmişte harbettik

Her değeri biri yıktı, yıkacak

Çok hazindir milletimin dıramı

Baş kendimiz, Brüksel mi Ankara mı? 

Sorup gardaş deşme benim yaramı

Çanımızı biri yaktı, yakacak

Deşme gardaş zaten yaram ağrıyor

Kıbrısımın derdi beni doğruyor

Biri halkı meydanlara çağrıyor

Korkum, kardeş kanı aktı, akacak

Yoğun bir çalışma var Ankarada

Yutturmuşlar bir çok şey bu arada

Ege sahanlığı, şimdi sırada

Ortak Pazar bize taktı, takacak

Der ki AB bulursa bahaneler

Ankara kriteriymiş, daha neler

Katledildi, töreler,ananeler

Millet aval aval baktı, bakacak

Sanki yeni bir manda kuruluyor

Çok acele karara varılıyor

Her mes’ele AB’ye soruluyor

Türk milleti bundan bıktı, bıkacak

Mikdat derki yazarım, gönlüm yara

Çok dertliyim efkarlıyım bu ara

Neden yazmaz, nerde şair şüara

Suskunlar canımı sıktı, sıkacak', 'Nasıl oldu, uzun zaman sabrettik Elimizden vatan çıktı, çıkacak Acep niye biz geçmişte harbettik Her değeri biri yıktı, yıkacak Çok hazindir...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/elimizden-vatan-cikti-cikacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalabalıklardayım', 'kalabaliklardayim-selman-faris-karakose-hh2lp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sevmeyi unutalı yıllar oldu desem inanırmısın... 

Çok zaman geçmişti ki 

Hiç bilmediğim bir zamanda, hazırlıksızken çıkmıştın karşıma

Hani sınavlarımız kötü geçince her zaman deriz

“Sorular Çalışmadığımız Yerden Çıktı”... 

Sen sınav kağıdına sadece adımı ve numaramı yazıp çıkacağım

Yani sevgilerden, aşklardan jübilemi yapacağım zaman girdin bu sınıfa.. 

O an bir soru var dedim çözebileceğim. 

Sen hiç hazırlığım yokken dokundun yüreğime 

Ben korkuyordum yüreğime dokunulmasından 

Sen masumane gülümsediğin zaman yüreğimin parçaları birleşiyordu... 

Legolar gibi dağınıkdı ki... 

Sen dokununca toplandı bir araya hepsi 

Seni seviyorum yazıldı o parçalanmış objeler 

Sen sadece seni sevdiğimi sanıyordun, 

Ama ben sadece seni sevmemiştim seni tanıyınca 

Tozlu raflara kaldırdığım bir kitabın ilk sayfasını açıp 

Yeniden aşkı okumayı da sevmiştim. 

Her şey güzel, her şey toz pembe.... 

Halbuki arkası kapkaranlıktı

21 yıla 21 ömür biçmiştim

Ben sana sadece önsözü anlatmıştım.

Anlamsızlaşan sadece benim yalansızlaştığımdı... 

Ne zaman sevgi aşk denilirse, kahrolası doğruculuk kaplar beni... 

Sana hiç anlatmadım ama ben hiç ağlayamam

Ki ağladığımda çok nadirdir

Gözlerimin içi kıpkırmızı bir gül gibi olur

Ben ona ağlamak derim....

Ben isterdim ki uzattığım bu elimi tutarsın 

Ve beni çekip alırsın bu kalabalığın içinden

Ben seni nasıl çekip aldıysam... 

Ben bu kalabalığın içine seni çıkarmak için girdim

Seni çıkardım ama ben hala buradayım.... 

Burada yaşamaya alıştım....

Sen o güzel gözlerin nerede gülüyorsa oraya git... 

Ben sadece bunu istiyorum

Benim adımı unut istersen, sanımı, yüzümü, gülümseyen yanaklarımı unut 

Sadece mutlu olabileceğin yerlere git. 

Ama ola ki dönüp bakmak istersen bu tarafa

Ben hala kalabalığın içinde yalandan gülümsüyor olacağım.... 

Gerçekten mutlu olduğumda hiç gülümsemediğim kadar.

Seni sevdiğime hiç pişman olmadım

Olmayacağımda

Hani ilk konuştuğumuz gün demiştin ya

 “Beni seven biri bulsam, onu sevmesem de 

hiç yanından ayrılmam hayatım boyunca”

Büyük konuşma demiştim

..........yanılmamışım

Kutluyorum seni

Öyle birini buldun, ama o bulduğun kişi en son yıldızını da kaybetti

Yani çırılçıplak

Yani susuz

Yani sensiz

Ben şimdiden alıştım.... ...ki zaten sen hiç alışmamıştın.....

Seni Seviyorum

Selman Faris KARAKÖSE (22.06.2005)', 'Ben sevmeyi unutalı yıllar oldu desem inanırmısın...  Çok zaman geçmişti ki  Hiç bilmediğim bir zamanda, hazırlıksızken çıkmıştın karşıma Ha...', ARRAY['Türk Edebiyatı','Şiir','Selman Faris Karaköse']::text[], 8.5, '{"poet":"Selman Faris Karaköse","poet_slug":"selman-faris-karakose","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/kalabaliklardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzerimizde Gök Yüklü Acılar Sağanağı', 'uzerimizde-gok-yuklu-acilar-saganagi-vedat-koparan-zp539', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hüznümü tetikleyen hangi zaman kanamada

kayıp giden o çokça sayamadığım  yıldızlarda

bunca acılar sağanağında kalmışken bir başına 

bu günde gözler ateş alımı madımak yangını 

seyircisi olunan yaşamın kahpe bir saldırısı

çıkardım bir bir derin kör kuyulardan suskuları

uzanır kara ses buluta tükürürsün yapışmış gırtlağa

üzüntümüzde saldırgan bir talan dolanır ortalıkta 

bastım tuz basımı acıları ses olsun dağ yangınlarına

gördüm o yangını ve nicelerini 

tarih geçti önümden gözlerim yandı 

tepeden tırnağa acı acıyı kesti

hey hüznü arş’a eren dost kaldır başını

bir baş  ki

yetim öksüz  kırgın ama dik olsun bizimkisi

Vedat Koparan 01.07.2005 (02.40)', 'hüznümü tetikleyen hangi zaman kanamada kayıp giden o çokça sayamadığım  yıldızlarda bunca acılar sağanağında kalmışken bir başına  bu günde...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzerimizde-gok-yuklu-acilar-saganagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Devrin Düşozorları', 'bir-devrin-dusozorlari-ozan-turk-kp6b2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oysa ne çok şey var sana anlatılacak

Yorgunluğumdan yakınıyorum hep işte bu zamanlarda

Oysa ne kadar anlatmak isterdim sana 

Beni nasıl incittiklerini

Nasıl böyle duvar

Böyle zincir

Böyle ezansız ettiklerini…

Aslında senin de 

Benimkilere benzer acıların 

Taşlaşmışlığın var

İşte o yüzden sen ve ben 

Birbirimizi görmediğimiz vakitler bu kadar gevezeyiz

Bu yüzden 

Birbirimize zamanlarımızın dışında bu kadar yakın

Zamanlarımızda bu kadar uzak kalmalıyız

İhtimal doğar çünkü,

Senden benim dinozor düşüncelerime

Ve bu benim dinozorlarımdır ki

Çağıracaklardır

Senin taş devrini

En yalnız gecelerine…', 'Oysa ne çok şey var sana anlatılacak Yorgunluğumdan yakınıyorum hep işte bu zamanlarda Oysa ne kadar anlatmak isterdim sana  Beni nasıl inci...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-devrin-dusozorlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğe Dokundum', 'sensizlige-dokundum-ufuk-coban-ffqjx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerini özledi saçlarım, rüzgar yetmiyor artık, 

Uzanmak sensizliğe, dizlerinin yerine, 

Yetmiyor birtanem hiçbir şekilde, 

Sen olmayınca hiçbirşey yok gözlerimde. 

Sabır bana işkence yokluğunda, 

Bilsen ne kadar özledim seni izlemeyi, 

Susmayı, gülen yüz olmayı, bazen somurtmayı, 

Sen olmayınca hiçbirşey yok ellerimde. 

Artık bakamaz oldum resimlerine, 

Dayanmak çok zor oldu sensizliğe, 

Bir umut yükleyebilsem sesime, 

Belki söylerdim uzaktayken bile birşeyler sevgime. 

Gündüzüm artık beyaz bir rüya, 

Kime baksam seni görüyorum, 

Neye dokunsam korkup kaçıyorum, 

Çünkü dokunabildiğim yalnızca sensizlik. 

30/11/2000', 'Ellerini özledi saçlarım, rüzgar yetmiyor artık,  Uzanmak sensizliğe, dizlerinin yerine,  Yetmiyor birtanem hiçbir şekilde,  Sen olmayınca h...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sensizlige-dokundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alemci', 'alemci-necmi-saglik-wpv6j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bildiğim tek şey vardır meyhanede oturmak kadehler arasında masalara yığılmak ben alemciyim yani keş bir varım bir yokumdur anla beni bir tanem ben seninle olamam çünkü ben ayaşım ayaş...', 'Bildiğim tek şey vardır meyhanede oturmak kadehler arasında masalara yığılmak ben alemciyim yani keş bir varım bir yokumdur anla beni bir ta...', ARRAY['Türk Edebiyatı','Şiir','Necmi Sağlık']::text[], 8.5, '{"poet":"Necmi Sağlık","poet_slug":"necmi-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/alemci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmalı', 'yanmali-huseyin-sigirtmac-8ingz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Efkar çekip yanma gönül boşuna.

Duygu düşünceni çalan yanmalı.

Ferhat’a çevirip dağlar başına.

Aşkın ateşiyle salan yanmalı.

Ben razıyım hasretliği çekmeye.

Ayrılık gamıyla figan etmeye.

Viranede alışırım ötmeye.

Beni gül dalından alan yanmalı.

Ne Leyla şan buldu, ne Mecnun bir ün.

Yürekte sevdamla olurum sürgün.

Batmaya yüz tuttu, doğmaz artık gün.

Ben geçer giderim kalan yanmalı.

Arınır mı arzu teselli ile? 

Bunca gamı veren çekmez mi çile? 

Sığırtmaç’la cismi olmasa bile

Gönülde yaşayan yalan yanmalı.', 'Efkar çekip yanma gönül boşuna. Duygu düşünceni çalan yanmalı. Ferhat’a çevirip dağlar başına. Aşkın ateşiyle salan yanmalı. Ben razıyım has...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanmali-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ali'' nin yalancısıyım', 'ben-ali-nin-yalancisiyim-nilgun-aras-cqm2h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen yine Kumkapı'' ya takılmışsın

Ali'' nin yerine

Oraya gitmek istememişsin aslında

Çek kardeşim, demişsin şoföre

Çek cehennemin dibine

Şoför cehennemin dibini ne bilsin 

Belki de bilir, belki de bilir

Kim bilir

Kimin ne bildiğini

Kim bilebilir 

Her neyse

Cehennemin dibi deyince

Ali'' yi kast ettiğini sanmış

Hiç olur mu, hiç olur mu

Ali'' nin yeri cehennem olur mu

Bu kapıdan geçene 

Tek soru sorulur mu

Gittin gördün

Ali'' yi Ali yapan

Duvardaki 

Guguk kuşudur

Ve kavanozda büzülen su yılanı

Su yılanı dediğim

Ali'' nin eski karısıymış

Olur mu olur

Kim diyebilir ki şu dünyada

Ne yalandır ne doğrudur

Zaten ben Ali'' nin yalancısıyım

Ali der ki,

Ne zaman kadeh kalksa

Bir şeylerin şerefine

İliklerine kadar titrermiş

Kuş gözlerini ona dikip

Sanki cevabı önceden

Ve sadece kendisi bilir gibi

Sinsi sinsi ötermiş

''Suç nerde

Suçluluk nerde

Aşk nerde''

Bunu bilmeyecek ne var 

Suç

Gelsem de gelmesem de 

Suçluluk

İlk yudumdan sonra dudağımda, dilimde 

Aşk

Ağır ağır çözülen buzların

Gözüme bata bata

-İçime çarpa çarpa- 

Yok olup gidişinde

Geçirdiniz, geçirdiniz

Aklınızdan geçirdiniz

Yani biz şimdi... Ali'' yle ikimiz? 

İyi ama hanginiz, hanginiz

Bir rakı bardağının içinde

Sabahlara dek seviştiniz

Ve dönüş yolunda şoföre

Söyleme yürekliliği gösterdiniz? 

Diyeceksiniz ki şoför 

Rakı bardağında sevişmeyi ne bilsin

Belki de bilir, belki de bilir

Kim bilir

Kimin ne bildiğini

Kim bilebilir', 'Sen yine Kumkapı'' ya takılmışsın Ali'' nin yerine Oraya gitmek istememişsin aslında Çek kardeşim, demişsin şoföre Çek cehennemin dibine Şoför...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Aras']::text[], 8.5, '{"poet":"Nilgün Aras","poet_slug":"nilgun-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/ben-ali-nin-yalancisiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayıplı İnsan Modeli', 'ayipli-i-nsan-modeli-ozan-ozel-tf4ma', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'utanmaz ruhun

sıkılmaz sahibi

aldatma kıvamında

boy verir 

kan yığınları üzerinde

bir kabus gibi

büyür de büyür

ayıplı insan modeli', 'utanmaz ruhun sıkılmaz sahibi aldatma kıvamında boy verir  kan yığınları üzerinde bir kabus gibi büyür de büyür ayıplı insan modeli...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayipli-insan-modeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taparcasına Sevdiğimsin', 'taparcasina-sevdigimsin-huseyin-erdogan-xyffc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ay gibisin gök yüzümde

bana öylesine yakınsın ki

ben dalım

sen de yaprağımsın sanki

uzattım elimi

tutacak gibiyim seni

bir mum gibi

sönme sakın

ömrüm boyunca

pırıl pırıl

dünyamı aydınlatsın

ışığın

sen benim

alıp da vermediğim

nefesimsin

yemyeşil 

rengarenk açan

hiç solmayan

bahar mevsimimsin

baktığım gözlerimsin

bitmeyen hayallerim

uyanmak istemediğim

düşlerimsin

yüreğime

resmini çizdiğim

taparcasına sevdiğimsin

                     01.07.2005', 'ay gibisin gök yüzümde bana öylesine yakınsın ki ben dalım sen de yaprağımsın sanki uzattım elimi tutacak gibiyim seni bir mum gibi sönme sa...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/taparcasina-sevdigimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Nasıl Anlatılır Ya Rab? ♥ ? & ∞ ♥', 'askin-nasil-anlatilir-ya-rab-caglar-asik-r0wop', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şükürler olsun sana Ya Rab.

Bizlere de nasip et Ya Rab.

Dil, arından söyleyemez Ya Rab.

Aşkın nasıl anlatılır Ya Rab? 

♥ ? & ∞ ♥ 

Yunus bülbül olmuş Ya Rab.

Mevlana döner olmuş Ya Rab.

Aşıklar delice olmuş Ya Rab.

Aşkın nasıl anlatılır Ya Rab? 

♥ ? & ∞ ♥ 

Geldik gönüllere Ya Rab.

Mahcup etme bizi Ya Rab.

Niceleri bekler Ya Rab.

Aşkın nasıl anlatılır Ya Rab? 

♥ ? & ∞ ♥ 

Gönüller dinler Ya Rab.

Özler hisseder Ya Rab.

Sözler yetmez Ya Rab? 

Aşkın nasıl anlatılır Ya Rab? 

♥ ? & ∞ ♥ 

Yardım senden Ya Rab.

Derman senden Ya Rab.

Ferman senden Ya Rab.

Aşkın nasıl anlatılır Ya Rab? 

♥ ? & ∞ ♥ 

Dilediğin olur Ya Rab.

Sensin sevdiğim Ya Rab.

Sensin aşkım Ya Rab.

Aşkın nasıl anlatılır Ya Rab? 

♥ ? & ∞ ♥ 

Lütfu kereminle Ya Rab.

Paylaşacağım Ya Rab.

Yaşayacağım Ya Rab.

Aşkın nasıl anlatılır Ya Rab? 

♥ ? & ∞ ♥ 

Tövbem sana Ya Rab.

Şükrüm sana Ya Rab.

Muradım sana Ya Rab.

Aşkın nasıl anlatılır Ya Rab? 

♥ ? & ∞ ♥ 

Anlatılmazı anlattır Ya Rab.

Söylenmezi söylettir Ya Rab.

Bilinmezi bildittir Ya Rab.

Aşkın nasıl anlatılır Ya Rab? 

♥ ? & ∞ ♥ 

Anlatamazsam göstert Ya Rab.

Gösteremezsem duyurt Ya Rab.

Duyuramazsam hissettirt Ya Rab.

Şükürler olsun aşkına Ya Rab? 

♥ ? & ∞ ♥ 

İstanbul – 30.06.2005

♥ ? & ∞ ♥', 'Şükürler olsun sana Ya Rab. Bizlere de nasip et Ya Rab. Dil, arından söyleyemez Ya Rab. Aşkın nasıl anlatılır Ya Rab?  ♥ ? & ∞ ♥  Yunus bülb...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/askin-nasil-anlatilir-ya-rab-9829-8734-9829-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey özgürlüğün çocugu', 'ey-ozgurlugun-cocugu-ayten-ozlem-yesilcali-vng2b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Git gidebildiginkadar uzaklara.

Unutabilecek misin kendini geçmişini; 

Nereden geldiğini,sanmam.

Kader almış seni çemberine.

Unutma geçmişini,unut ma nerede oldugunu.

Ey özgürlüğün çocuğu..

Senki özgürlük için canını verdin.

Bir lokma ekmek uğruna hayat feda ettin.

Kana kan cana can oldun.

Unutma geçmişini,unutma geldiğin yeri.

Kanma süslü laflara,luğatlara

İnan seni seviyorum diyene.

Sevgi emeğimizdir,sevgi vatanımızdır.

Sevmek özgürlüğümüzdür.

Unutma geçmişini,unutma geldiğin yeri.

Seni senden almalarına izin verme.

Unutma şehit verdiğimiz canları.

Ey özgürlüğün çocugu...', 'Git gidebildiginkadar uzaklara. Unutabilecek misin kendini geçmişini;  Nereden geldiğini,sanmam. Kader almış seni çemberine. Unutma geçmişin...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ey-ozgurlugun-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çingene seyyah', 'cingene-seyyah-serkan-dogan-yqsla', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çerçevelenmiş sarhoş sokak

çevresinde deverân eden çingene seyyah

dinlermiş gibi çivi seslerini ve gitar nâmelerini 

	sokak köşesinde bedrin raksı

	kenarlarda lambalar âyini

	orta yerinde selvinin valsine tutulmuş fıskiye

	serinliğiyle hiç dinlenmeden anlatılan hikâye

	çingenelerin seyahat edenlerin hikâyesi

sendeleyen sisten geceliğini çekip çıkarır

ak eteğine eğilmişken eğlence kararır

her değişen fânidir, der, eskiler

elbet birgün değişmez bir yel eser...

ve sersemlemiş seyyahın avucunda o saydam karaltı

belki de seyirdedir bir masal saflığındaki sokağı.', 'çerçevelenmiş sarhoş sokak çevresinde deverân eden çingene seyyah dinlermiş gibi çivi seslerini ve gitar nâmelerini  	sokak köşesinde bedrin...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cingene-seyyah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alaca', 'alaca-serkan-dogan-kkykd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaklaşan akşam alacaları

daha Narsis efsanesinde sürüklenirken

Afrodit’in billur parmaklarında boğulan

ve sevda semtinde yenik düşen

ak bir manolya tazeliğinde

kınası uçmuş kır saçlı çelebileri

kovaladı toprağın tâ dibine dek

fermanı yazdı, alacalar, ışıksız manastırlarda

tutulan kamer ve unutulan beyaz gül

uçucu bir öpücüğü değişir

kesişimin suskunluğuna', 'yaklaşan akşam alacaları daha Narsis efsanesinde sürüklenirken Afrodit’in billur parmaklarında boğulan ve sevda semtinde yenik düşen ak bir ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/alaca-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyüş', 'yuruyus-serkan-dogan-xjifk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ankaa, yâr-ı gâr veya çöl cini

konak yeri, yoksullar yurdu

yollarımı aydınlat güneşşemsim benim

incecik puşu giymiş hercâyiyim

zünnarım koptu / azâd edildim

bir yürümesini bilirim

biricik nokta idim, döndüm, âlem oldum

sûrun yasını yuttum

Mesih’in heyecanını tuttum

üfürüklü bir mağara ehli idim

bir ömür boyu yattım

muştuyu duydum ve uyudum

ne Hızır’ı, ne de İlyas’ı tanıdım

ama zincir halkalar, dalgalar

ne diye hep peşimden koştular

ben yürüdüm

sular alçağa akarken

bir kafes bir kuş aramaya çıktı

gûya, tûfan kopacaktı

ben yürüdüm

ol peşrevin pîri oldum

ben yürüdüm

tûr, bekle dinlen görünme

ben koşmasını bilmem', 'ankaa, yâr-ı gâr veya çöl cini konak yeri, yoksullar yurdu yollarımı aydınlat güneşşemsim benim incecik puşu giymiş hercâyiyim zünnarım kopt...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yuruyus-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nükte', 'nukte-serkan-dogan-9vw72', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ayını yitirmiş saadetlerde âsâ

semâ sekteye mi uğradı, hâşâ

sedef yılan damağında

zehir incisi damıtan

zuhale aldanma

selsebiller akıtan

	çadırıma gir

		tûba orada

zahmeler vuruluyor

işittin mi hû', 'ayını yitirmiş saadetlerde âsâ semâ sekteye mi uğradı, hâşâ sedef yılan damağında zehir incisi damıtan zuhale aldanma selsebiller akıtan 	ça...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nukte-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanı', 'sani-serkan-dogan-3rnsm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'geçenlerde, tekrar, ama son defa

çığlığımın mahrem duvarına dayalı

gözbebeklerime uzandım

bembeyaz sayfanın üzerine bembeyaz bulut

resimleri çizerek

üvey dumanlı notalar karaladım

efsaneler hatırladım

kehanetleri unuttum

sıra bana gelince

ben sustum

tesbihle yükselen nefesleri

engebeli sırılsıklam vicdanıma

ve saydam orkideme adadım

bilemem ben neyi ne sandım', 'geçenlerde, tekrar, ama son defa çığlığımın mahrem duvarına dayalı gözbebeklerime uzandım bembeyaz sayfanın üzerine bembeyaz bulut resimleri...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sani-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek', 'bebek-serkan-dogan-cshu4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kıyâmetin kundağında uyuyan bebek

elini açmış kendi gülümseyen gönlüne

güvertede göğümün göğeren güvercinleri

yakalar ve salıverir, sakınır

varoşlarıma küskün yağmurlar

hıçkırık hıçkırık takılıra topuğuna bebeğin

kırık kanatlı kuş misâli

kaderin kum saatinden akan zerreleri

ve o doğarken dul kalan isyânımı bölüşür

elem dergâhından haz emzirip de

cânı tenden sıyırınca 

bebeğimle diz dize

lyre çalar ney üfleriz

‘elverir bir şaire bir nev-nihâlin gölgesi’

biz bebekte biz bebekte biz bebeğiz', 'kıyâmetin kundağında uyuyan bebek elini açmış kendi gülümseyen gönlüne güvertede göğümün göğeren güvercinleri yakalar ve salıverir, sakınır ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bebek-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Patika', 'patika-serkan-dogan-nuknl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Patikasından giderim yaşamın,

Bir zaman kıyısı yerim belirsiz

Kıyamaz bana Tanrım atmaz

Derin yalnızlıklara, makarna

Yemekten hiç çekinmesem

De bir sonu vardır iştahın

Tahtına kurulmuşum bir

Kere bencil uzaylıların

Geriye asla dönmem

Desem de inanma

Ona hiç aldanma

Deli dolu dünya

Girer kanına 

İnsanların.', 'Patikasından giderim yaşamın, Bir zaman kıyısı yerim belirsiz Kıyamaz bana Tanrım atmaz Derin yalnızlıklara, makarna Yemekten hiç çekinmesem...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/patika-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevi sömürgen', 'sevi-somurgen-serkan-dogan-53bei', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hareli kaderim karılırken kulaçlarla

üşürüm şaşkınlıkla ve açık avuçlarla

hormonlu somurtkan öpüşlerini aldın 

geriye sevi sömürgeni bıraktın gittin

hançerleyerek baktın terk ederken

benim halim şimdi inan çok fena

kuzey rüzgarlarına döndüm

kıblem belki tersyüz oldu

melekler acıdı halime

kuşku dolandı belime

keşkelerin sırtından

elde edemem hiç

bir kazanç', 'hareli kaderim karılırken kulaçlarla üşürüm şaşkınlıkla ve açık avuçlarla hormonlu somurtkan öpüşlerini aldın  geriye sevi sömürgeni bıraktı...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevi-somurgen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla', 'anla-serkan-dogan-5pmk3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kınım dolu kanla

süzülür gözbebeklerimden 

katledilebilmiş değilim henüz anla

zarflar tutuşmakta posta kutularında

ah, söyleyemez ki zavallı kalbim 

lacivert kraterin ayaklarında

fikirlerim bir çift kelepçe

birtakım kara parçalarında 

yeterince sahtedir yaralarım

mermer lahitlerin yanı başında', 'kınım dolu kanla süzülür gözbebeklerimden  katledilebilmiş değilim henüz anla zarflar tutuşmakta posta kutularında ah, söyleyemez ki zavallı...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anla-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-serkan-dogan-j35py', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'beklerdim

sen bende kalmıştın

ben sende arardım

güzelliğinin yarınını

gelmezdin 

asırlar geçti kabuslar

bile korkutmaz oldu

hayallerim değişti

sabrım tükendi

pas bağladım

karalar

yollarına demirledi

uzaktaydın

diye söylendim

sebebini bilemeden

benliğimde depremler

salladı seni sana dair

isimler getirdi

bir başka şehirden

seneler sonra

işitemedim sesini

gelişinin', 'beklerdim sen bende kalmıştın ben sende arardım güzelliğinin yarınını gelmezdin  asırlar geçti kabuslar bile korkutmaz oldu hayallerim değiş...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bekleyis-123-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur', 'dur-serkan-dogan-3fwtv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'akışına bırak

yaslan arkana

durdurma yaşamı

ve ardından

sök kalbini

tırman gönlüme

sar ruhumu

yaslı kucağına

sars ve parçala 

beni sonra

ve hele bir dur

kelimeler mağarasında

ben yokum sende ama

yokluğun vardır bende

unutma ki 

ışıklar arar alkışı 

düşüncemdeki fırtına

bilincin tuzağında

noktalandıysa

sen oradasın.', 'akışına bırak yaslan arkana durdurma yaşamı ve ardından sök kalbini tırman gönlüme sar ruhumu yaslı kucağına sars ve parçala  beni sonra ve ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dur-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisyan incileri', 'nisyan-incileri-serkan-dogan-81ftm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne güzeldi o eski günler kalkardık sabah erken

öpüşürdük itişirdik küsüşürdük bizler de küçükken

sana yaptığın zulmün hüzünlerini getirdim

tenha anlarını bilirim, ve ben inan beterdim

bindim atıma sürdüm rahvan söndü alevi 

seyretti göçebe beni sanki sandılar bedevi

çektin çıkardın beni uzattın ta kafatasıma

sayfası açıktı zaten belli döndü ilk hatasına

hiç gönderilmemiş mektupları açtım

yine kaybedeceğim savaşa başladım

derin bir derdin vardı, unutmuştum

acılarımı yanaklarında kurutmuştum', 'ne güzeldi o eski günler kalkardık sabah erken öpüşürdük itişirdik küsüşürdük bizler de küçükken sana yaptığın zulmün hüzünlerini getirdim t...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nisyan-incileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanla', 'zamanla-serkan-dogan-4qlwd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zaman aşımına uğradı

dimağımın kara incileri

ne kadar anlatsam boş

bildiğini okuyacak belli

kentin taşkın nehirleri

daraldıkça içime akar

arkasındadır bu dünyada

gökyüzü bile parmaklıkların

ölmek için üç sebepten birisi

kıyamet döşeğimin sacayağı 

elma yersem de mutlaka irisi

bu bana kör talihin bir kıyağı.', 'zaman aşımına uğradı dimağımın kara incileri ne kadar anlatsam boş bildiğini okuyacak belli kentin taşkın nehirleri daraldıkça içime akar ar...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zamanla-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksi beş', 'eksi-bes-serkan-dogan-5t02x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'paskalya yortusu değil bu

pandora kutusu, ardına kadar açık

kanımın iliğimden çekildiğine

şahittir dehşetli denizler

pusulanın şaştığı anda

fazladan bir dakika, soğuk

yıldızlar ve bir ağaç kovuğunda

sarkmayı bekleyen yıllar

başka bir cana adanmış.

palazlanan ozanlar mezarlığı

perişanlığımızın şanındandır

pelerinli süvari kahramanım

gelmez ama zaman doluyor

bari bir ara beni beklese

bir an için yaşamaya değse.

10/04', 'paskalya yortusu değil bu pandora kutusu, ardına kadar açık kanımın iliğimden çekildiğine şahittir dehşetli denizler pusulanın şaştığı anda ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Doğan']::text[], 8.5, '{"poet":"Serkan Doğan","poet_slug":"serkan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eksi-bes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzakta Bir Köy Vardı', 'uzakta-bir-koy-vardi-ekrem-sama-od3il', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eskiden orada bir köy vardı uzakta,

Çırpınıp dururdu, takıldığı tuzakta...

Tüm serveti, birkaç inek birkaç buzağı,

İmefe denilen avcı kurdu tuzağı.

Ürün ekse para etmez, elinde patlar,

Ekilmeyen tarlalar, boş kalmış anbarlar.

Her ürün dışardan getirilir, dövizle,

Üretici ezik ezik olmuş faizle.

Tüm delikanlılar düşürülmüş gurbete,

Çalış didin, dolan bir şey yok ki sepete.

Pancar, fındık, buğday, pamuk, fıstık, çay, tütün..

Maliyete razı, lakin zarar büsbütün..

Orda bir köy vardı, hiç gidemem gelemem,

Hala yerinde mi? İnan ki ben bilemem...

(İstanbul:29.06.2005)', 'Eskiden orada bir köy vardı uzakta, Çırpınıp dururdu, takıldığı tuzakta... Tüm serveti, birkaç inek birkaç buzağı, İmefe denilen avcı kurdu ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uzakta-bir-koy-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Analar ağlar', 'analar-aglar-gulseren-onay-8qukk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Havada kan ve barut kokusu,

Bir ana ağlıyor...

Bilmem kaçıncı sortide 

Vurulmuş,

Üzerine titrediği yavrusu,

Gözlerinde ölüm korkusu

Uzanmış boylu boyunca yatıyor...

Millerce uzakta 

Bir başka ana,

Korkusu yok ölümden yana...

Yüreği zaferden pır pır,

Hazırlık yapıyor mutfağında

Dilinde zafer türküleriyle 

Savaştan galip dönecek oğluna..

Televizyonda bir resim,

Altından hızla geçiyor 

Alt yazılar...

Ansızın

Yüreğindeki sevinç

Dönüşüyor acıya.

Çaresizliğin yükü

Binince dizlerine

Gözlerine yaşlar doluyor,

Yığılıyor olduğu yere,

Başlıyor ağıt yakmaya...

Şimdi 

İki ana ağlıyor

birbirinden uzak,

İsyan ediyor iki ana 

Aynı acımasızlığa...

Kaybetsede,

Kazansada,

Sadece anası ağlar adamın

Sadece ağıtlar yakılır 

Savaşta.....

GÜLSEREN ONAY', 'Havada kan ve barut kokusu, Bir ana ağlıyor... Bilmem kaçıncı sortide  Vurulmuş, Üzerine titrediği yavrusu, Gözlerinde ölüm korkusu Uzanmış ...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/analar-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahramanlık', 'kahramanlik-ulvi-ziya-yzjql', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vatan kurtaran aslan; cesurdur,kahramandır...

Dostuna karşı yahşi,düşmanına yamandır...

''''Benden sonrası tûfan '''' diyenlere rağmen; 

Her işi doğru yapan,hakÎkî kahramandır...', 'Vatan kurtaran aslan; cesurdur,kahramandır... Dostuna karşı yahşi,düşmanına yamandır... ''''Benden sonrası tûfan '''' diyenlere rağmen;  Her işi...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kahramanlik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur Gülleri', 'huzur-gulleri-l-tif-karagoz-714j6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Herkesler kol, kola bülbüller gibi

Neden nadas kalır gönüllerimiz? 

Aşk bahçesinde açsın güllerimiz

Yanlarında coşan sümbüller gibi! 

Sevmek ve sevilmek için yaşarız

Aşkın girdabında sular coşarken,

Ömrümüzün son yolunda koşarken

Sevgi yatağından niye taşarız? 

Dirlik tarlasında hasadımız yok

Paramız pulumuz kaç para eder? 

İçimizde sönmez kor gibi keder

Hep kalplerimizde saplı durur ok! 

Yüzümüzde huzur gülleri açsın

                                  Sevgi atlarımız yine yarışsın  

 Birbirine darılanlar barışsın

                                  Mutluluk güneşi,gülücük saçsın! 

Kasım – 2004', 'Herkesler kol, kola bülbüller gibi Neden nadas kalır gönüllerimiz?  Aşk bahçesinde açsın güllerimiz Yanlarında coşan sümbüller gibi!  Sevmek...', ARRAY['Türk Edebiyatı','Şiir','Lâtif Karagöz']::text[], 8.5, '{"poet":"Lâtif Karagöz","poet_slug":"l-tif-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzur-gulleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai - X', 'rubai-x-kenan-mim-eryigit-z29vj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül soldu..kalbimse ezik ve kırık.! 

Git ve beni yalnız başıma bırak.! 

O renkli hülyalar bana çok ırak.! 

Yeni dünyamda yer yok sana artık.!', 'Gül soldu..kalbimse ezik ve kırık.!  Git ve beni yalnız başıma bırak.!  O renkli hülyalar bana çok ırak.!  Yeni dünyamda yer yok sana artık....', ARRAY['Türk Edebiyatı','Şiir','Kenan Mim Eryiğit']::text[], 8.5, '{"poet":"Kenan Mim Eryiğit","poet_slug":"kenan-mim-eryigit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-x-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağam', 'agam-hayri-arikan-serdaroglu-4me80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '* * * * * * * Ağam * * * * * * * * 

  



-Hayri Arıkan ağama- 

Bağrım açtım yol ağam 

Sinem içre dol ağam 

Harsımdan er saçtığım 

Mısra mısra çul ağam. 

De hele de balada 

Ser verilmiş kal`ada 

Beni kurban sala da 

Söz hakkına bul ağam 

Yamandır hey yamandır 

Bu ne garip zamandır 

Göz buğulu amandır 

Tut derdimi yol ağam. 

`Hayri ağam hey ağam 

Asil kandan pey ağam 

Ver elini öpeyim 

Pak alnımda bey ağam! ` 

Visâl olsun eşine 

Dosta il il deşine 

Düşüp eren peşine 

Oba oba kol ağam 

Kurtbala od ad olmaz 

Gül dalında tad olmaz 

Kim demiş ki yad olmaz 

`Şair` denen kul ağam 

`Hayri ağam hey ağam 

Asil kandan pey ağam 

Ver elini öpeyim 

Pak alnımda bey ağam! ` 

26 Haziran 2005 // T A R S U S 

Hakan İlhan Kurt

 Hayri Arıkan (Serdaroğlu)', '* * * * * * * Ağam * * * * * * * *     -Hayri Arıkan ağama-  Bağrım açtım yol ağam  Sinem içre dol ağam  Harsımdan er saçtığım  Mısra mısra ...', ARRAY['Türk Edebiyatı','Şiir','Hayri Arıkan (Serdaroğlu)']::text[], 8.5, '{"poet":"Hayri Arıkan (Serdaroğlu)","poet_slug":"hayri-arikan-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/agam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-emin-eren-x3yhr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey ölüm. zamanın yok senin

En istediğimiz anda 

Hep başkalarıyla uğraşırsında

Uzak dur dediğimizde

Bize uzakmış gibi 

Bir anda en yakınımızda

Bize dokunmuyor edasıyla

Bizi üzmek yakışmıyor ki sana

Ey ölüm dokun bana,al beni

Hazırım sana  kat kervanına

Üzemeyeceğin için kimseyi

İlk kez ben güleceğim sana

Haah..hah...hah...hah....haaa', 'Ey ölüm. zamanın yok senin En istediğimiz anda  Hep başkalarıyla uğraşırsında Uzak dur dediğimizde Bize uzakmış gibi  Bir anda en yakınımızd...', ARRAY['Türk Edebiyatı','Şiir','Emin Eren']::text[], 8.5, '{"poet":"Emin Eren","poet_slug":"emin-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olum-185-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim', 'memleketim-yusuf-ter-elmk2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl met edeyim güzel yurdumu

Memleketim atlas halıya benzer

Dört mevsim yaşanır bir yıl içinde

Altından bezenmiş yalıya benzer

Her yerinde cevher her yer mücevher

Doğduğum doyduğum savurduğum yer

Her zaman bizlere kültür rehber

Yiğidi yiğittir veliye benzer

Doğuda kar olur  eğede güneş

Varmı yurdumuza benzeri bir eş

Karadeniz yeşil yurduma düşeş

Yağmurlar bol yağar suluya benzer

Anadolu türkülerin sılası

İlelebet çıkmaz altın cilası

Dilinde düşürmez yaşlı babası

Kadehte şerbette doluya benzer

Altını bakırı krom demiri

Bor madeni şimdi hepsinin piri

Çıkarsalar petrol toplar geliri

Yusuf’um yurdunda deliye benzer



29.06.05

Saat 23:32 İsviçre', 'Nasıl met edeyim güzel yurdumu Memleketim atlas halıya benzer Dört mevsim yaşanır bir yıl içinde Altından bezenmiş yalıya benzer Her yerinde...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/memleketim-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağrı...', 'cagri-dursun-elmas-wj7eo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Milletin bahtını kurtarmak için,

Zalim karşısında dik durmak için,

''Ben''liği terkedip, ''biz'' olmak için

Alp Eren ruhsatlı, bilekler gelsin...

Sağlanmalı yine Türk''ün hürlüğü

Atmalıyız zihinlerden körlüğü

Avrupa değil de; Dünya Türklüğü

Kurulmalı diyen, erkekler gelsin...

Bozkurt gibi hürriyeti yeğleyen

Sefere çıkmaya hazır bekleyen

Turan birliğini hedef eyleyen

Türk gibi düşünen, dölekler gelsin...

Türk-İslâm aşkıyla tutuşup yanan

Millet gerçeğine,kafayı yoran

Hep hakkı koruyan,Hak''ka dayanan

Sevdalı cevvaller, dilekler gelsin...

Beş bin gencimizi verdik toprağa

Kurban ettik ay-yıldızlı bayrağa.

Türklük davasıyla baştan ayağa

Tutuşan bedenler, yürekler gelsin...

01.07.2005', 'Milletin bahtını kurtarmak için, Zalim karşısında dik durmak için, ''Ben''liği terkedip, ''biz'' olmak için Alp Eren ruhsatlı, bilekler gelsin.....', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cagri-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlık Gazeli', 'varlik-gazeli-mehmet-sakir-karatas-y2vxg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgiyle boy veren edamız vardır

Bizimde güzel bir sedamız vardır

Daha çok söyleriz biz bu ilhamla

Hiç eksik etmeyen hüdamız vardır

Doğrunun güzelin safındayız hep

Yalana çirkine cüdamız vardır

Şiiri en kutsal sanat sayarak

Bu yola baş koyan fedamız vardır

Gelince sukutun demi ey Şakir

Anlı şanlı olan vedamız vardır', 'Sevgiyle boy veren edamız vardır Bizimde güzel bir sedamız vardır Daha çok söyleriz biz bu ilhamla Hiç eksik etmeyen hüdamız vardır Doğrunun...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şakir Karataş']::text[], 8.5, '{"poet":"Mehmet Şakir Karataş","poet_slug":"mehmet-sakir-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/varlik-gazeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayri Arıkan (Akrostiş)', 'hayri-arikan-akrostis-hayri-arikan-serdaroglu-cjuhq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-******HAYRİ ARIKAN (Akrostiş)  ******- 

  



''H''oş geldin dünyama, gönül bağıma 

...Ruhuma gül oldun Hayri ağabey... 

...Baharlar getirdin huzur dağıma 

...Köyüme yel oldun Hayri ağabey... 

''A''tandan almışsın vatan sevgini 

...Soyundan kapmışsın bayrak övgünü 

...Özünden görmüşsün birlik kavganı 

...Davama yol oldun Hayri ağabey... 

''''Y''a Allah'''' deyip de güne başlarsın 

...Fakiri görünce gözün yaşlarsın 

...Lokmanı paylaşıp, yardım düşlersin 

...Halkıma bel oldun Hayri ağabey... 

''R''abbine inancın kalbinde tamdır 

...Dindaşın zordaysa gönlünde gamdır 

...Duan ile dileğin onlara demdir 

...Dinime sal oldun Hayri ağabey... 

''İ''nsanlık adına önde yürürsün 

...Seni tanıyanı kolda görürsün 

...Art niyetlilere cephe durursun 

...Soyuma kol oldun Hayri ağabey... 

''A''lper gibi canlar sundun vatana 

...Zıpkın gibi fırlar yurda çatana 

...Yakan ateş olur şerle yatana 

...Ülkeme şol oldun Hayri ağabey... 

''R''uhumla duyarım sana saygımı 

...Dilim kalpten alıp söyler duygumu 

...Layık olamazsam gör bak kaygımı 

...Gönlüme göl oldun Hayri ağabey... 

''I''şıldayan nursun benim gözümde 

...Dostluğun taşıyor çağlar özümde 

...Dize dize şiirleştin sözümde 

...Kalbime dil oldun Hayri ağabey... 

''K''udretli ellerin öpmek isterim 

...Gönlümde yerini yapmak isterim 

...Bilgini, sevgini kapmak isterim 

...Canıma dal oldun Hayri ağabey... 

''A''stını hor görmez sevgi sunarsın 

...Düşkünü görünce içten yanarsın 

...Gözü doymazları hepte yenersin 

...Özüme bel oldun Hayri ağabey... 

''N''e kalem yeterli seni yazmaya 

...Ne kâğıt yetişir övgüm dizmeye 

...Yemin ettim adın kalbe kazmaya 

...Dilime bal oldun Hayri ağabey... 

(Sayın Hayri ARIKAN ağabeyime ithamımdır...)

(12 HAZİRAN 2005 - BATMAN)

Turan Orak

 Hayri Arıkan (Serdaroğlu)', '-******HAYRİ ARIKAN (Akrostiş)  ******-     ''H''oş geldin dünyama, gönül bağıma  ...Ruhuma gül oldun Hayri ağabey...  ...Baharlar getirdin hu...', ARRAY['Türk Edebiyatı','Şiir','Hayri Arıkan (Serdaroğlu)']::text[], 8.5, '{"poet":"Hayri Arıkan (Serdaroğlu)","poet_slug":"hayri-arikan-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/hayri-arikan-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem Ateşi', 'cehennem-atesi-hifzi-ozbekmez-e3e31', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'CEHENNEM ATEŞİ

Bende seviyorum demek yerine 

Hançeri daldırdın sende derine

Dilerim allahtan çıkma serine

Cehennem ateşi kavursun seni

Hatam hiç olmadı benim bu işte

Payın çok büyüktü kötü gidişte

Sırat köprüsünden aşağı düşte

Cehennem ateşi kavursun seni

Beddua etmesi elbet zor ama

Zehiri doldurdun sende yarama

Öbür dünyadada rahat durama 

Cehennem ateşi kavursun seni

Hayali rüyamı yıktığın gibi 

Ölmeden boğazım sıktığın gibi

Ozan latifiyi yaktığın gibi

Cehennem ateşi kavursun seni

HIFZI ÖZBEKMEZ', 'CEHENNEM ATEŞİ Bende seviyorum demek yerine  Hançeri daldırdın sende derine Dilerim allahtan çıkma serine Cehennem ateşi kavursun seni Hatam...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cehennem-atesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ülke - I (Boyayalım Abi! ....)', 'bu-ulke-i-boyayalim-abi-ugur-deniz-ulkegul-xlnly', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim ülkemde

Beyaz saçlı ihtiyar çocuklar

Henüz ilkokul çağında başlar

İşçilikleri…

Biri karton toplar sokaktan

Siyaha boyalıdır diğerinin elleri

Umut dolu gözleriyle sorar

Boyayalım abi? 

……………

Hani aristokrat durur bir yanınız

Ve diğer yanınız genlerinden utanır

Bardağınızda viski, sofranızda havyar …

Geçer gidersiniz çoğu zaman yanından

Duymaz bir türlü kulaklarınız

Boyayalım abi? 

……………

Ayakkabınızın cinsi değildir düşündüğü

Kulak bile asmaz terslemenize, güler

Acımanın ve acımasızlığın rengini tanır

Kaçamak çalışır ders sonrası

Şimdi öğretmeni görse O’na ne der? 

Kim bilir nasıl utanır…

Hani siz eylem hazırlığı yaparken

Lastik yakarken sokakta

Barikat kurarken…

Bir de çiçekleri sopalarla dövüp yolarken

Camını kırdığınız marketin önünden bakar

Bir omzunda okul çantası üstünde önlük…

“Akademik protesto”  nun “ilk çağ seyircisi”

Kırıp dökerken duymaz sokak eylemcisi

Boyayalım abi? 

……………

Benim ülkemde

Çocuk diyemezsiniz bazılarına

Yürek ister…

En azından yağmuru bilmelisiniz

Sonra sıtmaya tutulmayı

Bütün gece ateşler içinde yanmayı

İlaçsız kalmayı ve bazen

Yevmiyesiz döndü diye azarlanmayı…

Zordur çocuk olmak bu ülkede

Bu şehrinde yaşamak

Altı delik ayakkabılar

Ve soğuktan buz tutan parmaklar…

Çocuk işte

Yine de yeter içini ısıtmaya

Vitrinde 

Düş’ünü kurduğu oyuncaklar…

……………

Hani siz Aşk’tan falan bahsedersiniz

Bir de Kadının ruhundan

Kimi zaman

Sosyal bir “ – izm” hikayesidir anlattığınız

Bar sohbetlerinde kapanırken gözleriniz

Nasıl da çok satar kitaplarınız…

Bir de siz

Diaspora bilgesi

Pamuk tarlasında terleyen

Kadının sesi…

Çözümcü medeni uysal

Toplumsal bir yaranın

Düşünsel tedavisi…

Boş “ –Bakan” gözler

Şen şakrak ekranlar

Bir bulvar gazetesi

Kahvede oturanlar, sessizlik…

Radyoda “Amerikanın sesi…”

“Sevgili Vatandaşlarım…vs..vs..vs..”

Dar gelirken vücuduma giydiğim

Söyle bakalım “Vekaleten seçtiğim ”

O giydiğin…Kimin elbisesi? 

……………

Çabuk eskir Ankara’da ayakkabılar

Boyayalım abi? ..........................', 'Benim ülkemde Beyaz saçlı ihtiyar çocuklar Henüz ilkokul çağında başlar İşçilikleri… Biri karton toplar sokaktan Siyaha boyalıdır diğerinin ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/bu-ulke-i-boyayalim-abi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemedim', 'sevemedim-mehmet-bicik-riq0f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben,

Tek seni sevdim.

Bir de 

Kızımı…

Kışa dönen yazımı,

Dinmek bilmez sızımı,

Bitmek bilmez hızımı,

Sevemedim…

Kötü yazılmış yazımı,

Tutamadığım ağzımı,

Çıktığınca bağıran avazımı,

Sevemedim…

Havada kavrulan közümü,

İyilik isteyen özümü,

Gurur yaptım, çözümü,

Sevemedim…

12 Ekim, 2004 Salı

Burhaniye 04:45', 'Ben, Tek seni sevdim. Bir de  Kızımı… Kışa dönen yazımı, Dinmek bilmez sızımı, Bitmek bilmez hızımı, Sevemedim… Kötü yazılmış yazımı, Tutama...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevemedim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-mehmet-bicik-qr71n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrı düşmüş sevdiğinden,

Erememiş murâdına…

Ferhat olup düşmüş çöle,

Kader dermiş bunun adına…

Beyninde esen fırtınalar,

Döndürememiş onu yolundan…

Gözü yaşlı kalan analar,

Tutup götürmemiş onu kolundan…

29 Mart 2003, Burhaniye', 'Ayrı düşmüş sevdiğinden, Erememiş murâdına… Ferhat olup düşmüş çöle, Kader dermiş bunun adına… Beyninde esen fırtınalar, Döndürememiş onu yo...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/firtina-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonumuz Bağlı', 'sonumuz-bagli-mehmet-bicik-jj5lt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben garip, sen çaresiz.

Elimiz, kolumuz bağlı..

Doğuştan ikimiz de kadersiz,

Mutluluk yolumuz bağlı..

Gökyüzü değil, bahtımız kara.

İkimiz de yürekten almışız yara.

Ne yapsak derdimize bulunmaz çâre.

Geçmişimiz değil, sonumuz da bağlı..

13 Nisan 2003, Burhaniye', 'Ben garip, sen çaresiz. Elimiz, kolumuz bağlı.. Doğuştan ikimiz de kadersiz, Mutluluk yolumuz bağlı.. Gökyüzü değil, bahtımız kara. İkimiz d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sonumuz-bagli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Ziller ve Somon...', 'ziller-ve-somon-naime-erlacin-zxp1e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hep ayrılık

hep acı

ölümü susmak yaşarken 

kabadayı hüzünlerle hep 

besili gamları mı yazar şair

bu denli sorumlu muyduk 

tüm zamanlarda yeşeren 

sancılı duygulardan? 

gidelim! 

teneffüse çıkmak istiyorum artık

zil sesi duymak 

sıfırlamak kümülatif bilinci bir an olsun

ikili bireyselliğini kutsamak aşkın

uzağı yok saydırıyor 

şafak vakitlerinin hüzünlü güneşi 

delişmen bir haziran gecesinde

suyun işveli kucağına bırakmak istiyorum gövdemi

bilmeyecekler yoksa hiç 

ölü mü 

diri miyiz

“Schrödinger’in Kedisi” misali

günün acılı tebessümünde hıçkıran ufuk kayıp

gül bir özleyişe düşüyor yüzümün göçleri

çalsın diyorum artık ziller

suyun sesinde tütsülensin yaşam

trampetler vursun kalbimde haziran gülleriyle 

bir somon gibi koşarım çağrına

bulurum yönümü 

senden gelen imleri

doğuştan sen mahkûmu 

bir doğa sevdalısı gibi

çalsın ziller

gidelim haydi 

(20 Haziran – 1 Temmuz 2005)', 'hep ayrılık hep acı ölümü susmak yaşarken  kabadayı hüzünlerle hep  besili gamları mı yazar şair bu denli sorumlu muyduk  tüm zamanlarda yeş...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ziller-ve-somon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşe Hasret', 'gunese-hasret-mehmet-bicik-p2ax2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabah güneşiydin sen

Hayâtıma doğan…

Umut verdin,

Hayat verdin

Kararan benliğime…

Kolu-kanadı kırılmış

Bir şahindim ben…

Senle uçmaya başladım

Hayaller ülkesinde…

Sende buldum mutlulugu,

Senle sevdim hayatı sevmeyi…

Akşam güneşi olup

Uzaklaştıkça uzaklaştın benden…

Her şeyi alıp götürdün,

Göz yaşlarımı silmeden.

Acı verdin,

Gözyaşı döktürdün hep…

Kararttın bahtımı,

Kök  söktürdün hep…

Bense; 

Umutsuzca yaşıyorum,

Güneşe hasret…

29 Haziran 2003, Burhaniye', 'Sabah güneşiydin sen Hayâtıma doğan… Umut verdin, Hayat verdin Kararan benliğime… Kolu-kanadı kırılmış Bir şahindim ben… Senle uçmaya başlad...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gunese-hasret-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayfa Değil Satırını Okumam', 'sayfa-degil-satirini-okumam-murat-demir-s4ml3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu sevdamın kenarına, ucuna

Hint ipliği olsan seni dokumam

Tek bir dilden kitap olsan acuna

Sayfa değil satırını okumam

Pınar olup kervan geçmez çöllerde

Çağlasanda yudumuna takılmam

Dünyada  tek deniz olsan dillerde

Ölürümde sahiline sokulmam

Canım diye gelip beni seçsende

Güzel sayıp varlığına aldırmam

Her saniye yüreğimden geçsende

Dik başımı eyerimde kaldırmam

Hasretinden ağlasamda, gülsemde

Senin için gönlüme saz çaldırmam

Yokluğunda derde düşüp ölsemde

Sana asla namazımı kıldırmam

Benim için benden önce öldün sen

Geçti artık bana seni sevdirmem

Sen yinede hala beni var bilsen

Sana uyup bana beni güldürmem

Ne yazık ki sen mazimde kayboldun

Boranında kalsa bile sıcağım

İçimde ki bu sevgi de son buldun

Günden güne buz olsada ocağım!', 'Şu sevdamın kenarına, ucuna Hint ipliği olsan seni dokumam Tek bir dilden kitap olsan acuna Sayfa değil satırını okumam Pınar olup kervan ge...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sayfa-degil-satirini-okumam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melâmi sırrı', 'mel-mi-sirri-ali-riza-unal-ucrv9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz bu vücut illetinden azadeyiz 

Seyyarı sefer seyran olduk.

Varlık benlik zilletinden aczadeyiz

Sultana nefer hayran olduk ..', 'Biz bu vücut illetinden azadeyiz  Seyyarı sefer seyran olduk. Varlık benlik zilletinden aczadeyiz Sultana nefer hayran olduk .....', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/melami-sirri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazgı', 'yazgi-serkan-karabulut-m1o11', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bilirim 

Her gülücük ardındaki hüznü

Saklama boşuna

Ağlamak yok demiştim tanrıya

Üzülmek yok demiştim

Yazgı böyleymiş

Boyun eğdim kadere', 'Ben bilirim  Her gülücük ardındaki hüznü Saklama boşuna Ağlamak yok demiştim tanrıya Üzülmek yok demiştim Yazgı böyleymiş Boyun eğdim kadere...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yazgi-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızım', 'yildizim-asya-yildiz-kdlup', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başımın üstünde keder kara bulut, musallat

Yıldızım, bir anda söndü gözümün feri...

Özlemin ciğnedi her hücremi, beterim

Çırpınışlarım can yüreğine aksetmez mi? 

Ardı arkası kesilmeyen sonsuz bir sitem,

Katlayıp yolları ulaştı dökülen harabeme.

Anılardaki bakışları, kahkahaları özledim! 

Yıldızım, huzur tutuşur mu benimle yine? 

Bir demet hüzün verdim gönlüne, istemeden,

Kestim biletimi, saldım üzerime köpekleri.

İçin için kanar ruhum, derman istemeden...

Yıldızım, sevdamın özü bizi beslemez mi?', 'Başımın üstünde keder kara bulut, musallat Yıldızım, bir anda söndü gözümün feri... Özlemin ciğnedi her hücremi, beterim Çırpınışlarım can y...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yildizim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslata umut', 'vuslata-umut-ali-riza-unal-0gpwn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdan bin pare eyler ömrümü benim

Hicranın  zar eyler gönlümü benim

Hekimler değmesin azdırır derdimi

Busene umudum avudur beni

Ne çare sensizlik kavurur beni

Bi çare densizlik savurur beni

Tabibler bi haber derdime benim

Vulata umudum avudur beni..', 'Sevdan bin pare eyler ömrümü benim Hicranın  zar eyler gönlümü benim Hekimler değmesin azdırır derdimi Busene umudum avudur beni Ne çare sen...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vuslata-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel', 'bedel-serkan-karabulut-0hw7o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gidişin bir gelişi var

Kimi hüzün kimi sevinç

Her acının bir faturası var

Bazısı mükafat bazısı bedel', 'Her gidişin bir gelişi var Kimi hüzün kimi sevinç Her acının bir faturası var Bazısı mükafat bazısı bedel...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bedel-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alper ARIKAN', 'alper-arikan-hayri-arikan-serdaroglu-nsicp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alper ARIKAN*** 

  



''A''lmış huyu babadan, kalemi şiir yazar 

...hep mazlumun yanında, yiğit Alper ARIKAN 

...salmış nuru yaradan, sevgiyi kalbe kazar 

...saygı hürmet kanında, yiğit Alper ARIKAN 

''l''akin hiç göremeden, şavkı nurdan yüzünü 

...sarılıp öpemeden, parıldayan gözünü 

...bu dosta eremeden, benimsedim özünü 

...vefa buhur canında, yiğit Alper ARIKAN 

''P''apatya fallarında, aramamki ben onu 

...dostluğun yollarında, gezip sormuşum yönü 

...bir gülün dallarında, ötüp bulmuşum konu 

...serdarların hanında, yiğit Alper ARIKAN 

''E''n güzel duygularla, büyüttü seni baban 

...soğukta o titrerken, attı üstüne kaban 

...insanlığı öğretti, seninde oldu çaban 

...bir Hayri''nin yönünde, yiğit Alper ARIKAN 

''R''iyakarlığı bilmez, yalan dolanı sevmez 

...dostlukları hiç silmez, kini nefreti övmez 

...sevgi çiçeği solmaz,muhabeti hiç kovmaz 

...birliktelik gününde, yiğit Alper ARIKAN 

''A''rkadaşlık yönünden, sensin kusursuz olan 

...bir doğruluk yanında, sensin gönüle dolan 

...şefkatli el önünde, sensin iyiyi bulan 

...bir şairin ününde, yiğit Alper ARIKAN 

''R''astlamadım sen gibi, sadakatli bir kişi 

...doğruluktur uğraşı,iyiliktir tek işi 

...güzelliği ruhunda, bulunamazki eşi 

...gül Muhammed teninde, yiğit Alper ARIKAN 

''I''slanmasın gözlerin, hep gülüversin yüzün 

...sanki yemin sözlerin, doğruluktandır özün 

...titremesin dizlerin, olmasın canda sızın 

...bir adalet şanında, yiğit Alper ARIKAN 

''K''üs olan yüreklere, uzanıp barıştırır 

...dostluk maratonunda, yürekler yarıştırır 

...kindarlık iksirine, sevgiyi karıştırır 

...pak yürekler önünde, yiğit Alper ARIKAN 

''A''lnından öpeceğim, kısmetse göreceğim 

...yüreğe ilmik ilmik, bir sevda öreceğim 

...sevgimi kabul etse, bir sefa süreceğim 

...günümün her anında, yiğit Alper ARIKAN 

''N''e güzel de dalmışım, geldim şiir sonuna 

...isterim bu şiirle, varıp gelsem yanına 

...kucak dolusu sevgi,derip versem önüne 

...kardeşim ol sonunda, yiğit Alper ARIKAN 

(Değerli Dost/Üstad/Ağabeyim Hayri ARIKAN''nın oğlu Sevgili Alper ARIKAN''a ithaf edilmiştir.)

Şeyhmus Sevilmez

 Hayri Arıkan (Serdaroğlu)', 'Alper ARIKAN***     ''A''lmış huyu babadan, kalemi şiir yazar  ...hep mazlumun yanında, yiğit Alper ARIKAN  ...salmış nuru yaradan, sevgiyi ka...', ARRAY['Türk Edebiyatı','Şiir','Hayri Arıkan (Serdaroğlu)']::text[], 8.5, '{"poet":"Hayri Arıkan (Serdaroğlu)","poet_slug":"hayri-arikan-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/alper-arikan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım yolunda', 'canim-yolunda-serkan-karabulut-qm6if', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kabul, tamam desen geleyim

Canım yolunda.

Tutsan elimi çeksen sürsen yokuşa

Tutsağım demem eylesen köle

Seninle bir yastığa baş koysam', 'Kabul, tamam desen geleyim Canım yolunda. Tutsan elimi çeksen sürsen yokuşa Tutsağım demem eylesen köle Seninle bir yastığa baş koysam...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/canim-yolunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Dalı Gibisin', 'bahar-dali-gibisin-mustafa-dilki-tzjqk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gezersin hep gülerek

Cıvıl cıvıl civelek

Kolun kanadın çiçek

Bahar dalı gibisin

Güzelsin ince hatlı

Güzelliğin bin katlı

Çok şekersin çok tatlı

Anzer balı gibisin

Güzelsin karmaşıksın 

Bilmem kime aşıksın 

Sararsın sarmaşıksın

Hanımeli gibisin

Bulunmaz bir esersin 

Neden böyle susarsın

Ilgıt ılgıt esersin

Seher yeli gibisin

Bir namedir sözlerin

Mehtap gibi yüzlerin

Yıldız yıldız gözlerin

Samanyolu gibisin

Bazen sessiz durgunsun

Bazen küssün kırgınsın

Bazen hayli çılgınsın

Deli-dolu gibisin

Nazlı nazlı bakarsın

Elvan elvan kokarsın

Şu sinemi yakarsın 

Yemen çölü gibisin

Başka gelmez aleme 

Alsam bitmez kaleme

Dilimde name name 

Tambur teli gibisin

Ey yiğitlerin yari

Adını söyle bari

Güzellikler diyarı

Anadolu gibisin

Esirin oldum senin 

Sana binlerce yemin

Şu güzel Türkiye’min

İstanbul’u gibisin', 'Gezersin hep gülerek Cıvıl cıvıl civelek Kolun kanadın çiçek Bahar dalı gibisin Güzelsin ince hatlı Güzelliğin bin katlı Çok şekersin çok ta...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bahar-dali-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağır Sultan Duydu', 'sagir-sultan-duydu-mustafa-dilki-70tj8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu gölümün sana olan aşkını 

Sağır sultan duydu sen duymadın mı

Sevda mimarının sırça köşkünü 

Sağır sultan duydu sen duymadın mı

Ateşlere attın yanan bağrımı 

Katmer katmer ettin gönül ağrımı 

Geceler boyunca aşka çağrımı 

Sağır sultan duydu sen duymadın mı 

Aşkınla inleyen gönül sazımı 

Ellerim göklerde aşk niyazımı

Çığlıklar içinde son avazımı 

Sağır sultan duydu sen duymadın mı 

Hasret tarlasına dert ektiğimi

Acılar içinde ter döktüğümü

Sensiz buralarda ne çektiğimi

Sağır sultan duydu sen duymadın mı', 'Şu gölümün sana olan aşkını  Sağır sultan duydu sen duymadın mı Sevda mimarının sırça köşkünü  Sağır sultan duydu sen duymadın mı Ateşlere a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sagir-sultan-duydu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklediğim Sen Misin', 'bekledigim-sen-misin-mustafa-dilki-ezqog', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kerem misali yanıp 

Papatyalara kanıp 

Uykularda uyanıp 

Beklediğim sen misin 

Sen misin kaşı karam

Sen misin gönül yaram

Sen misin ey manolyam

Kokladığım sen misin

Boşa geçen yıllarda 

Ümit dolu fallarda 

Akşam üstü yollarda 

Beklediğim sen misin

Gözlerimdeki nemde 

Seni andım her demde 

Bir sır gibi sinemde 

Sakladığım sen misin

Sen misin tatlı dillim 

Sen misin esmer tellim

Sen misin ince bellim

Beklediğim sen misin

Güldürdünya bahtımı

Geri aldım ahtımı 

Saat başı rıhtımı 

Yokladığım sen misin

Aradım durdum seni 

Galiba buldum seni

Şarap gibi buseni

Diklediğim sen misin 

Sen misin beyaz incim

Sen misin ey sevincim

Sen misin canım cicim

Beklediğim sen misin', 'Kerem misali yanıp  Papatyalara kanıp  Uykularda uyanıp  Beklediğim sen misin  Sen misin kaşı karam Sen misin gönül yaram Sen misin ey manol...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bekledigim-sen-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen kiminsin', 'sen-kiminsin-mustafa-dilki-p8sbz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey gönüller sultanı 

Sen kiminsin kiminsin

Kim canının cananı 

Sen kiminsin kiminsin

Ben başında çilenim 

Ben uğrunda ölenim

Ben sadık bir kölenim 

Sen kiminsin kiminsin 

Bu güzel sözler kime 

Bu güler yüzler kime 

Söyle bu nazlar kime 

Sen kiminsin kiminsin

Hislerimden eminim 

Sana sözüm yeminim

Ebediyen seninim 

Sen kiminsin kiminsin

Düşlerime girensin 

Bana hayat verensin 

Hani senin prensin

Sen kiminsin kiminsin', 'Ey gönüller sultanı  Sen kiminsin kiminsin Kim canının cananı  Sen kiminsin kiminsin Ben başında çilenim  Ben uğrunda ölenim Ben sadık bir k...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-kiminsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Gül', 'mavi-gul-emin-akduman-cvh6q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni üzmek için sevmemiştim..

Anladım ki yanılmışım 

Aramıza her gün yeni duvarlar dikip 

Beyaz mıyız,yoksa karamı diye düşünmek yerine

Dönüp sırtımızı birbirimize 

Başka ufuklara bakalım.

Sen ay’ın doğuşunu seyret 

Ben batışında kalayım..

Yeni zamanlar yaratalım kendimize 

BİZ olmadan önceki Biz’sizliğe dönelim..

Neden mi bitanem..

Çünkü hep dilinde dolanıp duran 

“-Nasıl olsa bir gün bitmeyecek mi? ”

“-Bittiğinde daha kötü olmak istemiyorum.”

“-Bu son görüşmemiz belki bir daha olmaz,olmamalı”

“-Yanlış yapıyoruz”

Cümlelerinde ölüp ölüp,

Ardından yine 

''Seni özledim'' diyen gözyaşlarınla

Hayat Bulmak Yoruyor Beni.

EVET haklısın,

Yanlışlarımla gelmişim sana

Şimdi senden öğrendiğim doğrularla gidiyorum..

İmkansız AŞK’mış bizimkisi.. 

Biliyordum ama dinlemediki yüreğim..

Hala da öyle ya.

Neyse bitanem..

O iki MAVİ GÜL’ün 

Asla yeni umutları olmayacak

Aynı gecelerde çiğ düşse de gözlerine

Aynı güneşi paylaşmayacaklar bir daha..

Sesini özlesem de,

Gözlerini hayal etsem de

Hilaline takılıp kalsam da 

O güzelim kaşlarının

Senin olsun artık başımda estirdiğin rüzgar..

Olmuyor işte biliyorsun..

Sevsem bir türlü... 

Sevmesem bir türlü...

Hep doğruya aykırıydı yaşadıklarımız..

Kaç şarkı duydumsa aşktan yana..

O kadar birikti içimdeki SEN. 

O kadar çoğaldı içimde özlemin 

Bir bilsen ah bir bilsen

Hiç yalanım yoktu benim..

Ama artık 

En büyük yalanı öğrendim.

Yokmuş AŞK dedikleri 

Yalanmış işte yalan.

Ama biliyorsun! 

Kimseye ihanet etmedik biz.

Kendimize bile.

Sevgiyle kal

Ve kendine iyi bak

Benim güzel Mavim', 'Ben seni üzmek için sevmemiştim.. Anladım ki yanılmışım  Aramıza her gün yeni duvarlar dikip  Beyaz mıyız,yoksa karamı diye düşünmek yerine ...', ARRAY['Türk Edebiyatı','Şiir','Emin Akduman']::text[], 8.5, '{"poet":"Emin Akduman","poet_slug":"emin-akduman","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/mavi-gul-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-mustafa-dilki-9lglx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar benim sırdaşımdınız

Bende hatıranız derin aynalar 

Aşıktım yolumda yoldaşımdınız

Gençliğimi geri verin aynalar 

Yemyeşil gösterin kuru dalları

Kısacık gösterin uzun yolları

Unutturun bana zalim yılları

Gençliğimi geri verin aynalar

Duvarda nispetle durmayın öyle

Efkarlıyım soru sormayın öyle

Yılları yüzüme vurmayın öyle

Gençliğimi geri verin aynalar', 'Bir zamanlar benim sırdaşımdınız Bende hatıranız derin aynalar  Aşıktım yolumda yoldaşımdınız Gençliğimi geri verin aynalar  Yemyeşil göster...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aynalar-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağlarım Gönülden Çağıran Sese ♥ & ♥ !', 'caglarim-gonulden-cagiran-sese-caglar-asik-y31gd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey gönüllerin sevgilisine çağıran ses! 

Ah! Gönüllerde, nede güzel bir nefes.

Sözüne gönülden nelerim var diyecek. 

O gönül, sözlerini tanıyınca söyleyecek.

♥ & ♥ ! 

Kolay değil öyle, hemen kabul edilebilecek.

Çağıran bülbül olsada, tanımadan kim gelecek.

Bir gün inanıyorum, o da, bir çağrıya gelecek.

Henüz o kokluyor, duyunca kokuyu koşup gelecek.

♥ & ♥ ! 

Yürek dağlamak istemesemde dağlarım.

O ses çok kıymetli, sakın ha yaralamayın.

Bir gün sizde gönülden geleni karalayın.

Sizi duyup anlayanlara selam yollayın.

♥ & ♥ ! 

Ben ağlarım, sizler hep gülün oynayın! 

İsterseniz yüreğimi, hep böyle dağlayın! 

Bu aşk çok kıymetli, sakın ha ahlanmayın! 

Bir gün yüzleşirseniz, yanıpta kavrulmayın! ...

♥ & ♥ ! 

İstanbul – 01.07.2005

♥ & ♥ !', 'Ey gönüllerin sevgilisine çağıran ses!  Ah! Gönüllerde, nede güzel bir nefes. Sözüne gönülden nelerim var diyecek.  O gönül, sözlerini tanıy...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Aşık']::text[], 8.5, '{"poet":"Çağlar Aşık","poet_slug":"caglar-asik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/caglarim-gonulden-cagiran-sese-9829-9829-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve', 've-serkan-karabulut-wsw30', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hani kaçarsın ya olur olmaz

Bir şey takılır birden düşüne

Canını yakar küsemezsin de

Ve

Bir daha katılaşır kalbin

Dolar nice acılar içine

Nefes alamazsın 

Kızarsın kendine

Yumruklarını sıkarsın

Avuç içlerini parçalarcasına

Gözün dolar utana sıkıla burun çekersin

Gitmek geçer düşüncelerinde

Ve

Kaçamazsın zoruna gider

Hiçbir yerde barınamazsın

Bulanma iyi düşün

Gitmen gereken yer aslında

O ortamdan biraz uzaklaşmak olacaktır

Aksi alır seni götürür 

Ve

Bir daha da dönemezsin', 'Hani kaçarsın ya olur olmaz Bir şey takılır birden düşüne Canını yakar küsemezsin de Ve Bir daha katılaşır kalbin Dolar nice acılar içine Ne...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ve-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harammı oldu helâlin', 'harammi-oldu-hel-lin-ali-riza-unal-uw560', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sürçü lisanmı eyledik ey canânı Nigârım

Nedir bu sesizlik hayırmı sükûtu firarın

Bilirsin nigâhı zülfüne seyran bu hayranın

Kahretma buseyi nihanını çatmasın didârın

Leb-binin nuş-udur bu divane figânın

Her perdene visalim  harammı oldu helâlin..', 'Bir sürçü lisanmı eyledik ey canânı Nigârım Nedir bu sesizlik hayırmı sükûtu firarın Bilirsin nigâhı zülfüne seyran bu hayranın Kahretma bus...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/harammi-oldu-helalin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
