INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskimez Beyitler 28', 'eskimez-beyitler-28-huseyin-avdic-086h9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Flora, yeşil şifa.

İnsandan silker yaka.

******

Varsa yoksa var sadece ''şu an''.

İşte benim herşeyim bir bu an.

******

Gelmiş, gecmiş, gelecek: Hepsi bir yudum içecek.

Kur''an çeşmesinden herkes, bu yudumu içecek.

******

Dikkat geliyor dikkat! Gelmiş, geçmiş, gelecek.

Geçmem diyen geçecek, gelmem diyen gelecek.

******

Geçmiş geçmiş, gelecek gelecek.

Benim için bir ''gelmiş'' gelecek.

******

Varsa, ''bugun'' var, ''yarın'' yok.

''Bugun''u ''yarın'' yapan çok! 

Batı Berlin, 1980-85.', 'Flora, yeşil şifa. İnsandan silker yaka. ****** Varsa yoksa var sadece ''şu an''. İşte benim herşeyim bir bu an. ****** Gelmiş, gecmiş, gelece...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eskimez-beyitler-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebessüm', 'tebessum-i-lhan-koruyucu-1gfv2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsanın içinden gelmeli, coşmalı ki

Gülümsemeler akışı coşkun bir sele dönmeli,

Hayattan zevk alabilmeli bile, bile doyarak ki! 

Tebessümü dönüşmeli birden gülmeye

Hep mutluluk karşısında değil de

Dağ dağ büyük görünen sorunlarda,

Kaybetmemeli ümidini içinden

Tebessüm edebilmeli hayata gülümseyerek.', 'İnsanın içinden gelmeli, coşmalı ki Gülümsemeler akışı coşkun bir sele dönmeli, Hayattan zevk alabilmeli bile, bile doyarak ki!  Tebessümü d...', ARRAY['Türk Edebiyatı','Şiir','İlhan Koruyucu']::text[], 8.5, '{"poet":"İlhan Koruyucu","poet_slug":"i-lhan-koruyucu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tebessum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyarı 2', 'uyari-2-rahim-recep-akdora-59dqv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir değnek al eline

Kır ikiye 

Parçalarını ister elinde tut

İstersen fırlat gitsin.

Ama düşün 

Bu kırdığın değnek bir bütündü az önce

Sen kırdın onu 

Tekrar onarabilir misin.

İnsanda öyledir kardeşim

O değnekten daha kırılgandır.

Dilin kemiksizliği

İstediğini söyleme hakkını vermez insana

Nice bilgisayarlar yerleştirmiş beynine yaradan

Ölçeceksin

Biçeceksin

Kusurlarını karşındakine incitmeden ileteceksin

Anlamasını sağlayacaksın en uygun kelimelerle

Karşısında hoşgörü gülümseyeceksin

Gülün nazikliği nasırdır insan önünde

Taşın sertliği de hamur.

İtilmiş kakılmış bir insan mı gördün 

Üstü başı çamur

Tut elinden

Tek onlar anlar 

uzanan elin dilinden.', 'Bir değnek al eline Kır ikiye  Parçalarını ister elinde tut İstersen fırlat gitsin. Ama düşün  Bu kırdığın değnek bir bütündü az önce Sen kı...', ARRAY['Türk Edebiyatı','Şiir','Rahim Recep Akdora']::text[], 8.5, '{"poet":"Rahim Recep Akdora","poet_slug":"rahim-recep-akdora","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/uyari-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erciyesim ağlamasın ne yapsın', 'erciyesim-aglamasin-ne-yapsin-umut-gungor-01giy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinden akıtıyor yaşları,

Koparacak olsa inan saçları,

Çoğalıyor yine şehit taşları,

Erciyesim ağlamasın ne yapsın.

Vatan için koşup gitti askere,

Kısmet değil imiş ona teskere,

Selam durdu dağlar şehit askere,

Erciyesim ağlamasın ne yapsın.

Ana baba evlat yürek dağlıyor,

Erciyeste kardelenim ağlıyor,

Karadeniz isyan edip çağlıyor,

Erciyesim ağlamasın ne yapsın.

Serdengeçtim fırsat verme haine,

Mehmetçikle benze kartal şahine,

Akbabalar konsun itin leşine,

Erciyesim ağlamasın ne yapsın.', 'Gözlerinden akıtıyor yaşları, Koparacak olsa inan saçları, Çoğalıyor yine şehit taşları, Erciyesim ağlamasın ne yapsın. Vatan için koşup git...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/erciyesim-aglamasin-ne-yapsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıma', 'askima-mehmet-mutluay-vocyn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülmek için mutlu olmayı bekleme.belki mutlulukğülüşünde saklıdır.sakın ağlama,seninbir gülüşün için yaşayan biri vardır.insanlıgı kaybettim sevgiye çizik çektiminsanlıktan korkmayan ölüme meydan okuyan.namlunun ucunda canımızı verene kadar sevdik,tetik çekecek kadar sevilmedik.her kalleş için yüreğine bir çarpı koy koyki ğeriye döndüğünde kaç kalleşten darbe yedigini bende sayayım.insanı ayakta tutan kinler öfkeler inatlar vardır.işte biz o duyğularla beslendik buralarda.o duygular kan oldu damarlarımızda kan.onun için sevda köleliktir', 'Gülmek için mutlu olmayı bekleme.belki mutlulukğülüşünde saklıdır.sakın ağlama,seninbir gülüşün için yaşayan biri vardır.insanlıgı kaybettim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Mutluay']::text[], 8.5, '{"poet":"Mehmet Mutluay","poet_slug":"mehmet-mutluay","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/askima-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirli savaşın yarınsız çocukları', 'kirli-savasin-yarinsiz-cocuklari-i-lhami-arslantas-n4jy8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Onlar 

Kirli bir savaşın 

yarınsız çocukları 

Onlar 

Ne nötron yapıyorlar 

Ne de kitle imha silahları 

O umutsuz gözlerindeki yaşlarıdır 

Tek savunma silahları 

Ama ne yazık ki 

Vicdanları onları vurur 

Vicdanı olanlarsa 

Savaş istemez zaten 

Onlar 

Kardeşliğe aç 

Temiz ve berrak yürekleriyle 

Bir damla şefkat 

Bir yudum sevgiye muhtaç

Kirli savaşın yarınsız çocukları', 'Onlar  Kirli bir savaşın  yarınsız çocukları  Onlar  Ne nötron yapıyorlar  Ne de kitle imha silahları  O umutsuz gözlerindeki yaşlarıdır  Te...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kirli-savasin-yarinsiz-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-yildiray-kurban-mhm4t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerin bir başkasına dokunursa; 

Bil ki; yüreğim bin parça.

Aklından benden başkası geçerse; 

Bil ki; zindan bana her gece.

Dudaklarından benden başkası öperse; 

Durur zamandaki her saniye.

Yüreğin benden başkasını severse; 

söz bulamam ihanetine.

Acırım ozaman haline,

Mezarıma gelirsin elinde bir demet gül ile! ! ! 

İşte ozaman girerim bedenine.

Otururum yüreğinin en derin yerine. 

İşlerim bütün hücrelerine,

Beni düşünüp kahrolmaktan alamazsın kendini.

Gülerim o vakit haline.

İnan yazık olur SEVGİMİZ ''e

Ona göre HAAAA

Sakın ola bana ihanet etme! ! ! 

2000   Ankara', 'Ellerin bir başkasına dokunursa;  Bil ki; yüreğim bin parça. Aklından benden başkası geçerse;  Bil ki; zindan bana her gece. Dudaklarından b...', ARRAY['Türk Edebiyatı','Şiir','Yıldıray Kurban']::text[], 8.5, '{"poet":"Yıldıray Kurban","poet_slug":"yildiray-kurban","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ihanet-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serdengeçtim 5', 'serdengectim-5-umut-gungor-fmw12', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Görmezmisin ok yayını biçecek,

Zalimler keyif çayını içecek,

Atı alan viyanayı geçecek,

Durma sende hazır eyle tayını.

Kürşatların hazır kıta beklesin,

Tarihlere zaferleri eklesin,

Çapulcular korkusundan teklesin,

Durma sende hazır eyle tayını.

Dindir artık bacı gardaş yasını,

Dünya görsün yiğitlerin hasını,

Pak eyle tüfeğinden pasını,

Durma sende hazır eyle tayını.

Serdengeçtim aral gölü buz olsa,

Ayağında çalı diken tuz olsa,

Koşacağın yollar sana uz olsa,

Durma sende hazır eyle tayını.', 'Görmezmisin ok yayını biçecek, Zalimler keyif çayını içecek, Atı alan viyanayı geçecek, Durma sende hazır eyle tayını. Kürşatların hazır kıt...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/serdengectim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serdengeçtim 6', 'serdengectim-6-umut-gungor-874ly', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilesinki ok yayında sıkıldı,

Kerkük Türkü zindanlara tıkıldı,

Nüfus tapu bilgileri yakıldı,

Çapulcuya paşa dendi ne deyim.

Davran artık ok yayından kaçıyor,

Çapulcular orada zulüm saçıyor,

Paçavrayı bayrak diye açıyor,

Çapulcuya paşa dendi ne deyim.

Sinirinden Tuna bile köpürdü,

Yüzlerine Karadeniz tükürdü,

Aral kızdı rüzgarını götürdü,

Çapulcuya paşa dendi ne deyim.

Serdengeçtim taş yerinde ağırdır,

Kerküklümü duymayanlar sağırdır,

Derdi çeken kırk yaralı bağırdır,

Çapulcuya paşa dendi ne deyim.', 'Bilesinki ok yayında sıkıldı, Kerkük Türkü zindanlara tıkıldı, Nüfus tapu bilgileri yakıldı, Çapulcuya paşa dendi ne deyim. Davran artık ok ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/serdengectim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir''e Aşk', 'i-zmir-e-ask-sait-muharrem-say-c3wkz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Varoşlarında dolaşan

Bir sokak iti bile şanslı benden

Tam yaşamı emecekken,

Karmaşandan, varyantından

Karşıyaka’ndan

Dağlarından

Tam da gerçekten büyüyecekken

Buna hazırken

Kollarım kendi meşrebince açık

Otoyol sıradanlığı

Tren rayı soğukluğu üzerimde

Üşüyerek,

Yokluğun üzerime üşüşerek

Gitgide uzaklaşıyorum senden

Aşkım İzmir

(Mayıs 2005)', 'Varoşlarında dolaşan Bir sokak iti bile şanslı benden Tam yaşamı emecekken, Karmaşandan, varyantından Karşıyaka’ndan Dağlarından Tam da gerç...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/izmir-e-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahsen''e Mektup', 'ahsen-e-mektup-mehmet-bicik-9h22r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aylar oldu 

    ayrılalı senden..

       Haberin alamıyorum 

           gelenden, gidenden..

               Ve…

                    Kahroluyorum hasretinden…

Sana olan sevgimi, özlemimi; 

Sana duyduğum hasreti

                    Anlatmak istiyorum bu gece..

Seni benden alan,

   beni acılara salan ellere; 

      seni yetim bırakan kadere,

         geçmiş, gelecek yıllara

                           lânet okuyorum…

Yazdığım şarkılara, şiirlere; 

   kitaplara, defterlere; 

     içinde sıkışıp kaldığım,

       derdimi anlattığım duvarlara,

         ilmik ilmik, desen desen

           adını, sevgini dokuyorum…

Yokluğun yıkıyor,

   yüreğimi yakıyor,

      ataşlara atıyor beni..

         gün geçtikçe çöküyorum…

Ve…

Doldum, taştım..

Diyâr diyâr dolaştım..

Çok engeller aştım..

Sonunda şaştım! ...

Seni ellere bıraktım,

   koştum uzaklara; 

     aldırmadım hiç

          kurulan tuzaklara; 

             nefretim, kinim

                 sütü bozuklara..

                    aldım defterimi, kalemimi

                        içimi sana döküyorum…

Bilsen,

   ne acı kızım! 

          dün kucağımdaydın,

               şimdi karşıdan bakıyorum…

Seni düşündükçe

    Kahroluyorum,

         Bir cigara, bir cigara, bir cigara

             Daha yakıyorum…

7 Aralık 2001, Burhaniye', 'Aylar oldu      ayrılalı senden..        Haberin alamıyorum             gelenden, gidenden..                Ve…                     Kahroluy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ahsen-e-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Para Eldeki Kirdir', 'para-eldeki-kirdir-sait-muharrem-say-8l64j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En büyük zenginliğin

Yaşamın,

Bak nasılda sürekli nefes alabiliyorsun

Nasilda görebiliyorsun önüne gelen herşeyi,

Köşedeki şu güzelim hatunu mesela

Nasılda süzebiliyorsun 

Güzelliğine nasılda ortak oluveriyorsun

bedava...

Paran yoksa,

cebinde mi yok,

Sok iki elini birden ceplerine,

Birde fiyakalı bir bakış fırlat 

Göğsün ilerde,

Var mı senden zengini şimdi.

En büyük zenginliğin yaşamın

Para eldeki kirden başka nedir ki?', 'En büyük zenginliğin Yaşamın, Bak nasılda sürekli nefes alabiliyorsun Nasilda görebiliyorsun önüne gelen herşeyi, Köşedeki şu güzelim hatunu...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/para-eldeki-kirdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salınada Sunam Gölde Salına', 'salinada-sunam-golde-salina-umut-gungor-uifcb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Salınada sunam gölde salına,

Kurban olam al bayrağım alına,

Bırakamam onu selvi dalına,

Yüreksize bırakamam taşısın.

Dalgasına derya deniz eremez,

Heybetini sıradağlar geremez,

Yüreksizler yüreğinde derdemez,

Yüreksize bırakamam taşısın.

Azameti düşmanını titretir,

Eşkiyayı inlerinde inletir,

Türküsünü dünyalara dinletir,

Yüreksize bırakamam taşısın.

Serdengeçtim bayrağıyla var olur,

Onsuz ona yedi kıta dar olur,

Yaşamak bile o anda ar olur,

Yüreksize bırakamam taşısın.', 'Salınada sunam gölde salına, Kurban olam al bayrağım alına, Bırakamam onu selvi dalına, Yüreksize bırakamam taşısın. Dalgasına derya deniz e...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/salinada-sunam-golde-salina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlanma gönül nazlanma', 'nazlanma-gonul-nazlanma-tuncay-akdeniz-4cnzs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seven gönüller üşütmez

Buzlanma gönül buzlanma

Sanma ki kimse işitmez

Gizlenme gönül gizlenme

Ne yazdın oku satıra

Dokunma gönül hatıra

Ağır gelirse fatura

Sızlanma gönül sızlanma

Dikkat etmesen sözüne

Kurt dalar koyun kuzuna

Güvenme yolun düzüne

Hızlanma gönül hızlanma

Bu devrandır böyle döner

Mazlumları herkes döver

Ah amanı üsten siner

Tozlanma gönül tozlanma

İhanet eder vefasız

Dünya varlıklı sefasız

Malı var evlat hayırsız

Nazlanma gönül nazlanma

Canlılar olsa kalıcı

Hiç olmazdı can alıcı

Dara kalanda duacı

Vızlanma gönül vızlanma

Herkese eşit kanunu

Kandıramaz kimse onu

Bu hayatın vardır sonu

Sazlanma  gönül sazlanma

Tuncay’ın kendine sözü

Arsızın utanmaz yüzü

Kamerası çeker bizi

Pozlanma gönül pozlanma', 'Seven gönüller üşütmez Buzlanma gönül buzlanma Sanma ki kimse işitmez Gizlenme gönül gizlenme Ne yazdın oku satıra Dokunma gönül hatıra Ağır...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/nazlanma-gonul-nazlanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşalım', 'konusalim-asik-meric-o1u9p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlar konuşa, konuşa anlaşır,

Beri gel can sevdiğim, sizden konuşak.

Konuşarak güzellikleri paylaşır,

Hakikate yönelen, sözden konuşak.

Ne güzeldir, sözde sevgiyi aramak,

Kötüdür sözüyle namerde yaranmak,

Sıkışınca, her an yalana sığınmak,

Kerpiç evi ısıtan, közden konuşak.

Varlığın hedefi, imana sarılmak,

Menzilde olmamalı asla yorulmak,

Hak vaki olduğunda sararıp solmak,

Diriliğin son ucu, güzden konuşak.

Söz gümüş olunca, sükut altın olur,

Doğrular ancak gümüş sözle sunulur,

Sora, sorula Bağdat bile bulunur,

Görmek için de bakan, gözden konuşak.

Bağırmayıp, biraz yavaştan alalım,

Hep bağışlayan, af eden biz olalım,

Kendimiz, mağdurun yerine koyalım,

Bariton, bas değil de, tizden konuşak.

Ahlakı, ibadeti Rabbim emretmiş,

İşin bitiş tarihi, belli ki yetmiş,

Hak’ın emrini yalnız İblis ret etmiş,

Kurandaki ayet, nas, cüzden konuşak.

Sözlerimiz zehir, zemberek olmasın,

Fikrimiz, enayi yerine konmasın,

Altta kalarak saçın, başın yolmasın,

Lafazan torba ağzı, büzden konuşak.

Ne güzel yaratış, insanı yaradan

Sakın düşünmeden, laf etme sıradan

Söz güzel olur, delikteki yılandan,

İnsan fıtratındaki, özden konuşak.

Tüm alemler, Cenabı Rab’i zikreder,	

Yunus, yaradan dan ötürü çok sever,

Veysel Şah’ı Muhammed’i görmek diler,

Lal olmuş dilleri de çözden, konuşak.

Boş durmayıp, gayret içinde olalım,

Evire, çevire doğruyu bulalım,

Yanlış yapmaktansa, bilene soralım,

Revan olup ta giden, dizden konuşak.

İstikametimizi, orta yolla bulalım,

Aşırılıklara ırakta duralım,

Mutluluğu hep beraberce kuralım,

Var oluşumuzda ki, gizden konuşak.

Sözümüz İzm’le karıştırılmasın,

Kulak ardı edip, savuşturulmasın,

Doğru ile yanlış yarıştırılmasın,

Geride bırakılan, izden konuşak.

Öğrenmek altın sükutla olur mu? hiç,

Bilenle, bilmeyen bir tutulur mu? hiç,

Daima sevip, sevilir AŞIK MERİÇ,

Somurtup susmaktansa, bizden konuşak.

(15.12.2002/İstanbul)', 'İnsanlar konuşa, konuşa anlaşır, Beri gel can sevdiğim, sizden konuşak. Konuşarak güzellikleri paylaşır, Hakikate yönelen, sözden konuşak. N...', ARRAY['Türk Edebiyatı','Şiir','Aşık Meriç']::text[], 8.5, '{"poet":"Aşık Meriç","poet_slug":"asik-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/konusalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytanlık', 'seytanlik-ulvi-ziya-dzzpo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birçok şeytan kuşatarak akıl verdi bir nobrana

Yürü ey yiğit dediler; tüm imkânlar senden yana

Çok cesursun ve güçlüsün,yerleri ez,göklerde gez

Yık karşına çıkan yeri,hiç kimse engelleyemez...

Vız gelir senin hızına  binlerce mil mesafeler

Çeşit çeşit silahların dağı yıkar,göğü deler...

Denizler aş,çöle ulaş; kanlar akıt,ezip sömür

Petrol,altın,demir için harca yüzbinlerce ömür...

Bil ki ne varsa senindir yeryüzünde ve uzayda

İster dünyada olsun rant,ister Mars''ta veya ayda...

Dâima git uzaklara ; başında bir kavak yeli

Her ne varsa senin hakkın,her servet senin ey deli...

İşte kitap; bak yazıyor:sana vaat edilmişler...

Bu ülkeler; insan,hayvan hepsi sana verilmişler...

Kitaba bak,tersten oku,git cesurca hakkını al

Senin düşüncen doğrudur,diğer fikirler hep maval...

Şeytanlar yol gösterdi de cenge gitti bu dîvâne

Yaktı,yıktı birçok yeri; vîran oldu pekçok hâne

Güyâ azgın insanlara hak,adâlet sunacaktı; 

Vahşî genlerine uydu; nizam,intizam bahâne...

Boş beynine fikir doldu şeytanlıklar serîsinden

İnsanlığa gömlek biçti kurtlu domuz derisinden

Bilmedi ki; azâde ruh,kirli,dar giysiye sığmaz

Er geç patlatır çıkar cenderenin içerisinden...

Aklın varsa ey yoz yiğit mahvolmadan yurduna dön! ...

Denizden git hep batıya,budur sana en doğru yön...

Binlerce mil uzaklarda,çöllerde ne arıyorsun? 

Şeytanlardan ilham alan; ey en barbar, bön  oğlu  bön! ...', 'Birçok şeytan kuşatarak akıl verdi bir nobrana Yürü ey yiğit dediler; tüm imkânlar senden yana Çok cesursun ve güçlüsün,yerleri ez,göklerde ...', ARRAY['Türk Edebiyatı','Şiir','Ulvi Ziya']::text[], 8.5, '{"poet":"Ulvi Ziya","poet_slug":"ulvi-ziya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seytanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmazsa olmazımız sevgimiz', 'olmazsa-olmazimiz-sevgimiz-i-lhami-arslantas-pvxtb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '......Siz bensiz, 

Siz bensiz, 

Ben sizsiz, 

Olmasın Sevgim izsiz, 

Çavlan olayım, 

Sizi çağlayım, 

Sizi duyayım, 

Sizi koklayım, 

Lalede, sümbülde, gülde. 

.......Olmasın, 

İnsan sevgisiz, 

Sevgim izsiz sevimsiz…

Olmazsa olmazımız sevgimiz', '......Siz bensiz,  Siz bensiz,  Ben sizsiz,  Olmasın Sevgim izsiz,  Çavlan olayım,  Sizi çağlayım,  Sizi duyayım,  Sizi koklayım,  Lalede, s...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olmazsa-olmazimiz-sevgimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma Ya Rab', 'sorma-ya-rab-asik-meric-xltxo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hatalarım çoktur benim,

Günahlarım vardır benim,

Af etmen sonsuzdur senin,

Kendi hakkın sorma Ya Rab.

Kusurumla gelsem bile,

Sana aşkım döndü sele,

Rehberim habibin ile,

Resul hakkın sorma Ya Rab.

Varlığın bize bildiren,

Hakkı özümde sevdiren,

Okudukça yüz güldüren,

Kur’an hakkın sorma Ya Rab.

Beni dünyaya getiren,

Şükretmeye ilk götüren,

Genç yaşta ömrün bitiren,

Ana hakkın sorma Ya Rab.

Gelişime vesiledir,

Razılığı sevgindedir,

Hak yolunda benimledir,

Baba hakkın sorma Ya Rab.

Aşkında bana eş olur,

Huzuru imanda bulur,

Olmazsa sararıp solur,

Zevce hakkın sorma Ya Rab.

Her biri birer çiçektir,

Hak mutlak sevilecektir,

Bunu neslim görecektir,

Evlat hakkın sorma Ya Rab.

Sılada akrabam atam,

Şad olsun duayla yatan,

Var olsun bu cennet vatan,

Sıla hakkın sorma Ya Rab.

Komşularım gönlümdedir,

Onlar her an benimledir,

Gurbetteki ailemdir,

Komşu hakkın sorma Ya Rab.

Kul hakkı yeme, bilmem hiç,

Ondan kalbe gelir sevinç,

Dua eder AŞIK MERİÇ,

Kul hakkın sorma Ya Rab.

(05.03.2005/İstanbul)', 'Hatalarım çoktur benim, Günahlarım vardır benim, Af etmen sonsuzdur senin, Kendi hakkın sorma Ya Rab. Kusurumla gelsem bile, Sana aşkım dönd...', ARRAY['Türk Edebiyatı','Şiir','Aşık Meriç']::text[], 8.5, '{"poet":"Aşık Meriç","poet_slug":"asik-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sorma-ya-rab-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-necmiye-sarpkaya-prp3f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi sihirli sözcük yeryüzündeki en anlamlı en gizemli 

İlgi çekici ve geniş kapsamlı sözcük. 

İnce bir sızı ile bir çarpıntı bir kıpırtı ile başlar sakin dingin yürekte.

Ansızın bir damla,bir kadre bir zerre gibi başlayan sevgi gönül 

Toprağında süratle büyür. Adı sevgi olan ince sızı havasını,suyunu

Gübresini gönül derya denizinde bulur. Geriye sevgiliyi haberdar etmek 

Kalmıştır,sevgi büyümüş serpilmiş o geniş topraklar dar gelmeye dışa sızmaya 

Dışarıya açılmaya hazırlanmıştır artık. Üstünü örten gizemli tül yavaşça aralanmış

Gözle görülmeye elle tutulmamaya başlanmış tam kıvama gelmiştir.İşte o an 

Haberdar etme zamanıdır. Özlemler,elem ve kederler acılar başlamıştır. 

Sevgiliyi görmeden sesini duymadan yaşamak acı ve hüzün verir olmuştur. 

Onun her sözü her davranışı güzel ve özeldir. O muhteşemdir 

O kusursuz hatasız her şeydir.Candır damarlar da dolaşan kandır. 

Yaşam ağacının kökü tek sebep ve yegane gayedir.  Manadır özdür biçimdir 

Seven için sevgili her şeydir. 

Yavaş yavaş gönülden gönle sızacak akacak bir yol bulur 

Zaman içinde kabul görür.Canan canın sunmuş olduğu 

En güzel en özel armağanı nasıl reddedebilir ki? edemez 

Alır kabul eder. Gönül diğer gönülle buluşmuş koklaşmış anlaşmıştır. 

Zaman ve mekan önemli değildir samanlık seyran olacaktır. 

Öyle olur gün gelir sevinir gün gelir ağlaşırlar ama beraberlerdir 

Her şey paylaşılır,acılar sevinçler hüzünler her şey paylaşılır.

Sevgilinin eline batan bir diken sevenin gönlüne batar kanatır yaralar 

Izdırabı İfade edilemez. 

Ne olursa işte ondan sonra olur.Olaylar başlar seven 

Yetinmez,kanmaz  doymaz sevgili tamamen onun olmalıdır 

Bu ona verilmiş temel bir haktır. 

Sevgili aldığı her nefesi,söylediği 

Her sözü onun için söylemeli,ona göre konuşmalı,

ona göre davranmalı ona göre biçimlenmeli

Kılık kıyafetini ona göre düzenlemeli onun gönlünü 

Hoş tutmak boynunun borcu olmalıdır.Halka takılmış

Kement atılmış,bütün varlığı kelepçelenmiştir.

Kalp parsellenmiş imarı yapılmış içerisine girip yerleşilmiştir

Gönle daha önce kendisine sevgisine hayat veren yetiştiren geliştiren

Gönle ipotek konmuştur 

Sevgi sihirli sözcük, 

Sevgi nerede gizemli örtün? 

Sevgi yaşamın temeli, 

Sevgi en manalı sözcük, 

Sevgi nasıl olmalıydın? 

Nasıl yola çıkmıştık nerelere ulaştık? 

Büyümeli,şartsız kuralsız ve beklentisiz olabilir miydin 

Yorumu sizlere bırakıyorum...... 

Şartsız ve kuralsız gerçek sevgilere gerçek sevgililere 

seven sevecek olan gönüllere selam olsun selam olsun..... 

Necmiye Sarpkaya', 'Sevgi sihirli sözcük yeryüzündeki en anlamlı en gizemli  İlgi çekici ve geniş kapsamlı sözcük.  İnce bir sızı ile bir çarpıntı bir kıpırtı i...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/sevgi-186-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Sitemiz', 'bizim-sitemiz-asik-meric-bcqi9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Temiz havası, akan suyuyla,

Parkları, bahçeleri, yoluyla,

Yönetimi, sporu, toyuyla,

Başka güzeldir bizim sitemiz.

Sakinleri, konu komşusuyla,

Yeşile olan tutkusuyla,

Kalplerdeki güzel muştusuyla,

Başka güzeldir bizim sitemiz.

Konutlar, okullar, çevresiyle,

Kartpostala benzer çehresiyle,

Her yöreden türlü şivesiyle,

Başka güzeldir bizim sitemiz.

Hakka yönelen ramazanıyla,

Beş vakit ezanda niyazıyla,

Havuzdaki ördeği, kazıyla,

Başka güzeldir bizim sitemiz.

Ara sıra kusurları göreniyle,

Eleştiriye hoş güleniyle,

Allah razı olsun Ören’iyle,

Başka güzeldir bizim sitemiz.

Müezzini, imam hatibiyle,

Beyaz masadaki katibiyle,

Güvenliği, teknik hizmetiyle,

Başka güzeldir bizim sitemiz.

Seher vaktinde öten kuşuyla,

Namaz eda edilir huşuyla,

Al bayrağı elde tutuşuyla,

Başka güzeldir bizim sitemiz.

Marmara Evleri kulvarıyla,

İMES içindeki bulvarıyla,

Niyetleri iyi muhtarıyla,

Başka güzeldir bizim sitemiz.

Kederi, tasası, sevinçiyle,

Çocuğu, ihtiyarı, gençiyle,

Sitesine AŞIK MERİÇ’iyle,

Başka güzeldir bizim sitemiz.

(15.03.2002/İstanbul)  

Not: Bu şiir İMES. Sitesi Yönetimi tarafından yapılan, site hakkında şiir 

        ve kompozisyon yarışmasında birinci seçilmiş ve ödül kazanmıştır.', 'Temiz havası, akan suyuyla, Parkları, bahçeleri, yoluyla, Yönetimi, sporu, toyuyla, Başka güzeldir bizim sitemiz. Sakinleri, konu komşusuyla...', ARRAY['Türk Edebiyatı','Şiir','Aşık Meriç']::text[], 8.5, '{"poet":"Aşık Meriç","poet_slug":"asik-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bizim-sitemiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Babam', 'sevgili-babam-asik-meric-r0gob', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sene bin dokuz yüz elli altı,

Dört çocuk senin eline kaldı,

Anladık ki dünya bize dardı,

Sadık minettardır sevgili babam.

Çocuklar okur mu? acep derdin,

Okumamız için çaba verdin,

Öksüzler diye, acır severdin,

Kazım hürmetkardır sevgili babam.

Garibanlık seni dara soktu,

Çaresizce iki canın koptu,

Çevrenden sana hiç derman yoktu,

Orhan şükürdardır sevgili babam.

Rabbim sana uzun ömür versin,

Her ne yapsakta yine seversin,

Ömründe her an iman edensin,

Ümmügül vefakardır sevgili babam.

Çile çektin ama verdin sevinç,

Dilerim kırılmazsın bize hiç,

Sever seni oğlun AŞIK MERİÇ,

Mutluyuz seninle sevgili babam.

(16.06.2005/İstanbul

Not::Sevgili babama ithafen, babalar günü için yazılmıştır.', 'Sene bin dokuz yüz elli altı, Dört çocuk senin eline kaldı, Anladık ki dünya bize dardı, Sadık minettardır sevgili babam. Çocuklar okur mu? ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Meriç']::text[], 8.5, '{"poet":"Aşık Meriç","poet_slug":"asik-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevgili-babam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senaryodaki Yüzler', 'senaryodaki-yuzler-hasan-can-tfu8g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yandım sevgilim, gözlerine kandım,

Bir bir gülüşünü, bir bakışını aşk sandım.

Aşk sandığım gülüşünde, bakışında kayboldum,

Yalanlar içinde, kaderime bağlanmış gözyaşlarıyla boğuldum.

Yalandı sevgin, kocaman bir yalandı,

Bu gönül ne umutlarla etrafında dolandı,

Bir gece kapına geldiğimde yağmur çisiltisinde,

Beni terkettiğini anlamıştım, gidişin sevgine benzedi sessizce.

Bıraktım kendimi bir kenara ne olacaksa olsun,

Yüzüm bir kuytuda isterse bir çiçek gibi solsun,

Çıkmayacağım sokağa, vurup gitmeyeceğim kendimi yollara,

Ne olacaksa olsun bıraktım kendimi, isterse hayat dursun.

Yürüsem ne olacak acım mı azalacak,

Gözlerim ağlamasa kederli sözler mi susacak,

Kendimi kuytudan alsam hayat güzel mi olacak,

Gece gündüze dönse sevgilere umut mu doğacak? 

Yürüsemde koşsamda hayat aynı entrikalarla dolu,

Her senaryoda aynı kişiler, yüzler hep aynı.

Sorumsuzca ve acımasızca yürüyerek bitirmişler sevda yolunu,

Arta kalanlara acısını derinden çekmek kaldı.', 'Yandım sevgilim, gözlerine kandım, Bir bir gülüşünü, bir bakışını aşk sandım. Aşk sandığım gülüşünde, bakışında kayboldum, Yalanlar içinde, ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senaryodaki-yuzler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İrem Bebek', 'i-rem-bebek-asik-meric-piv3n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İrem bebek, aramıza hoş geldin,

Sefalar getirdin, Torun No Bir.

Hepimize pek çok sevgiler verdin,

Güzellikler getirdin, Torun No Bir.

Beklerken seni, içimiz boştu,

Anne annen, baba annen bir hoştu,

Dedelerin hastaneye koştu,

Sevgiler getirdin, Torun No Bir.

Yaradan bize güzel hazlar verdi,

Mutluluktan uçan baban, annendi,

Duygularla dolan Aşık Dedendi,

Esenlikler getirdin, Torun No Bir.

Doğar doğmaz gözlerini açtın,

Çevrendekilere neşeyle baktın,

Güzelliğinle görenleri yaktın,

Saadetler getirdin, Torun No Bir.

Gülücüklerin mutluluğumuz oldu,

Ağlamaların içimizi burdu,

Gelişini amcan, dayınlar sordu,

Hayırlar getirdin, Torun No Bir.

Dilerim bahtın çok güzel olur,

Yuvarlanan taş gediğini bulur,

Yüreğimiz senin sevginle dolur,

Mutluluklar getirdin, Torun No Bir.

Senin yüzünü gören sevmez mi hiç,

Aldı gönlümüzü şenlikle sevinç,

Çok sever seni deden AŞIK MERİÇ,

Hoş geldin aramıza, Torun No Bir.

(20.11.2004/Çorum)

Not: Sevgili ilk torunum İrem Kani’nin doğumu nedeniyle yazılmıştır.', 'İrem bebek, aramıza hoş geldin, Sefalar getirdin, Torun No Bir. Hepimize pek çok sevgiler verdin, Güzellikler getirdin, Torun No Bir. Bekler...', ARRAY['Türk Edebiyatı','Şiir','Aşık Meriç']::text[], 8.5, '{"poet":"Aşık Meriç","poet_slug":"asik-meric","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/irem-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SU Sesi Olup AKsaydım...', 'su-sesi-olup-aksaydim-ozan-si-ar-agdasan-auqss', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suyun sesi olsaydım da

Sevgi bağına AKSAYDIM

Yar yüzünü bulsaydım da

Ölünceye dek BAKSAYDIM

Bin can verdim, bir anlığa

Yaran oldum yaranlığa

Kar yürekli karanlığa

Geceye mumlar YAKSAYDIM

Su kaynar, gelir eşmeden

Yaram ey olmaz, eşmeden

Turna gözlü ser çeşmeden

Buluta şimşek ÇAKSAYDIM

Yanıp kül olsam toprağa

Renk versem, yeşil yaprağa

Şiar bağban olsam bağa

Aşıklara gül TAKSAYDIM

Su sesi olup AKSAYDIM

Geceye mumlar YAKSAYDIM! ...

Söz ve Müzik: Ozan ŞİAR Ağdaşan Yorum: Aşık Şah TURNA

www.siarcan.com www.sahturna.com', 'Suyun sesi olsaydım da Sevgi bağına AKSAYDIM Yar yüzünü bulsaydım da Ölünceye dek BAKSAYDIM Bin can verdim, bir anlığa Yaran oldum yaranlığa...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/su-sesi-olup-aksaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demekki sende gidiyorsun', 'demekki-sende-gidiyorsun-ramazan-kayak-yqk9z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'güzel kız Demek ki sende gidiyorsun

Bu şehirden

Ve benim ömrümden

Ne bir veda 

Nede selam

Haydi git güle,güle

Bir sevgi sözcüğü olmasa bile

Haydi uğurlar ola 

                                       Ramazan kayak', 'güzel kız Demek ki sende gidiyorsun Bu şehirden Ve benim ömrümden Ne bir veda  Nede selam Haydi git güle,güle Bir sevgi sözcüğü olmasa bile ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/demekki-sende-gidiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-ramazan-kayak-7w42l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç sokak var aramızda

Kaç deniz

Ne kadar gözyaşı

Ne kadar hasretlik

Bilirmısin

Her sensiz geçen dakikada

Kaç ben ölür içimde

Kaç ben atılır

Tel örgülerle çevrili

Mayın tarlalarına

Kaç bahar geçer

Senden uzakta sensiz

Sağanak yağmurlarda

Bilirmisin

Nasıl sevildiğini

Nasıl özlendiğini

Bomboş soğuk odada

Nasıl beklendiğini

El açılıp Allah’a 

Kaç dua’da istenildiğini

Bilirmisin

Benim kara bahtım

Beni deli sevdam

Çıkmazlara atığın yetmedımi

Her şey’e köstürmeyi

Herkesten kaçırtmayı

Kaçak gecelerin sonunda

Tek başına bırakılmayı

Bilirmisin 

                Sevgili 

                        Sen söyle…

                   

                                         Ramazan kayak', 'Kaç sokak var aramızda Kaç deniz Ne kadar gözyaşı Ne kadar hasretlik Bilirmısin Her sensiz geçen dakikada Kaç ben ölür içimde Kaç ben atılır...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sevgili-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşim ol', 'gunesim-ol-ramazan-kayak-7riss', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneşim ol bitanem

Gökyüzüm

Bulutlarım ol

Özlemlerim

Yağmurlarım ol

Aşkım

Uykum ol karanlık gecelerime

Şafak ol doğ alaca sabahlarıma

Aydınlat tüm hücrelerimi bir,bir

Sevdam ol

Sevgim ol yıkık yorgun gönlüme

Tutkum öfkem inadım hırsım ol

Gecekondunun çamurlu sokaklarında

Gençliğime uzanan

Çıplak yalın nasırlı bir el ol

Sana vurgunluğumu düşün

Sana tutsaklığımı

Hayata bıkmışken derinden

Sevinci ol gönül evimin

Haydi gel canım ol

Gel baharım ol

Kışlar gelmeden

Senin ömrüne….

                        Ramazan kayak', 'Güneşim ol bitanem Gökyüzüm Bulutlarım ol Özlemlerim Yağmurlarım ol Aşkım Uykum ol karanlık gecelerime Şafak ol doğ alaca sabahlarıma Aydınl...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gunesim-ol-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-atif-okan-9yq6g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ağaçları tesine çevir

kökleri semaya baksın

ters çevir uçurtmaları

çocuklar kanatlansın', 'ağaçları tesine çevir kökleri semaya baksın ters çevir uçurtmaları çocuklar kanatlansın...', ARRAY['Türk Edebiyatı','Şiir','Atıf Okan']::text[], 8.5, '{"poet":"Atıf Okan","poet_slug":"atif-okan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/umut-183-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Notalar Bitince', 'notalar-bitince-zeki-akcali-7dw9b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir başınayken:

Portelere dökülür,

Notalarda patlar,

Yaptıklarına kızar...

Hüzün basar

Şarkılarını çalarken...

Kelimelerde arayıp

Bulmuştur kendini.

''Hiç hata yapmasaydım'' der.

Ama şarkı biter.

Notalar tükenmiştir artık.

Ve müzisyen gider...

(30/06/2005, Perşembe, B.Çekmece) 

(2. dönem)', 'Bir başınayken: Portelere dökülür, Notalarda patlar, Yaptıklarına kızar... Hüzün basar Şarkılarını çalarken... Kelimelerde arayıp Bulmuştur ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Akçalı']::text[], 8.5, '{"poet":"Zeki Akçalı","poet_slug":"zeki-akcali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/notalar-bitince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liselim', 'liselim-mehmet-bicik-rrp0t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Askerde şafak karalarken,

Yaralı gönlümü çaldı, liselim…

Yalnızlıktan sıkılıp dost ararken,

Sisli dünyama daldı liselim…

Gözleri vardı fal taşı gibi,

Bakışları ceylân bakışı gibi,

Sanki Leylâ''nın bir eşi gibi,

Aklımı başımdan aldı, liselim…

Ayrılık acısı cana tak edince,

Sabır dermânı bitip tükenince,

Herkes sevdiğini alıp çekilince,

Gurbete haber saldı, liselim…

Asker sevgiliden mektup gelince,

Sağlıklı, güzel haberler alınca,

Sevgili: “Seni seviyorum” deyince,

Gözleri parladı güldü, liselim…

15 Mayıs 1998, Malatya', 'Askerde şafak karalarken, Yaralı gönlümü çaldı, liselim… Yalnızlıktan sıkılıp dost ararken, Sisli dünyama daldı liselim… Gözleri vardı fal t...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/liselim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öperim', 'operim-mehmet-bicik-nmqw1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O kadar güzelsin,

Meleğim, perim…

Gamze yanağından, 

Yakalarsam öperim…

Sevgilinin aşkıyla,

Yanan bir erim…

Çok uzak yoldan geldim,

Kurumadı hâlâ terim…

Yârim için terk ettim,

Edep ve ârım…

Sevdiğim elin olursa,

Bütün dünyayı yakarım…

7 Mayıs 1998, Malatya', 'O kadar güzelsin, Meleğim, perim… Gamze yanağından,  Yakalarsam öperim… Sevgilinin aşkıyla, Yanan bir erim… Çok uzak yoldan geldim, Kurumadı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/operim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yağmurun Öyküsü', 'bir-yagmurun-oykusu-nuri-yilmaz-e9bcc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünyanın bir yerinde bir yervardi.

İsmi Anaduluydu.

Kaderi ya,kederliydi.

 *****     *****     *****

Çoraklaşmişti Anadolu.

Suya hasretti Anadolu.

Hırçınla eserdi rüzgar iklminde.

Eksik olmazdı coğrafyasında tozda, dumanda.

 *****     *****     *****

Millet bir yağmura hasretti.

Ne çare ümitler yitikti.

 *****     *****     *****

Bazen yağardı yağmur.

Ama hırçın hırçın...

Sel getirirdi azgın  yağmur.

Başedebilmek ne mümkün.

 *****     *****     *****

Sonunda bir bulut gözüktü.

Küçüktü.

Büyüdü,büyüdü...

Gökyüzünü ak etti.

Millette tebesüm etti.

Miletti ümitlendirdi.

 *****     *****     *****

Birden AK''ın etrafı kapladı karalar.

Çakıştılar AK''la kara bulutlar.

Birden gözüktü emareleri yağmurun.

Görmeliydin; yükseldi,arşa çıktı sururum.

 *****     *****     *****

Kasım''da düştü yağmur. 

Kalblere düştü yağmur.

Kalbleri yumuşadı yağmur.

Ümitleri yeşerdi yağmur.

 *****      *****     *****

Feleğin inadına yağdı yağmur.

Her tarafı sardı surur.

 *****     *****     *****

Hüzün yer verdi sevince notalarda.

Bahar bestesi yazıldı sonbaharda.

Anadolu yeşerdi kışta,

Mahsula durdu evel-ı baharda.

 *****     *****     *****

Güzel yağdı yağmur.

ahenk ahenk...

Güzel yağıyor yağmur.

Yağışı kalbimin  ritimlerine denk

 *****     *****     *****

Güzel oldu Anadolu.

Her taraf gül her taraf çicek.

Güzel kaldı Anadolu.

İnşaallah güzel kalacak.

Temmuz/2005-Ümraniye-İstanbul', 'Dünyanın bir yerinde bir yervardi. İsmi Anaduluydu. Kaderi ya,kederliydi.  *****     *****     ***** Çoraklaşmişti Anadolu. Suya hasretti An...', ARRAY['Türk Edebiyatı','Şiir','Nuri Yılmaz']::text[], 8.5, '{"poet":"Nuri Yılmaz","poet_slug":"nuri-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/bir-yagmurun-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-ufuk-coban-5lt7z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek acı çekmektir görmemek uğruna, 

Sineye çekmek umudunu zaman geçse de, 

Bazen gözlerini kapatmak ve hayali ile yetinmek, 

Ama hep sevmek umut olmasa da gökyüzünde. 

Sevmek zaman zaman yağmurlarla yarışmak 

Rüzgarı yenip fırtınaya meydan okumak, 

Güneşe bakıp kendi sıcaklığınla güneşi kavurmak 

Ama hep ayıklamak gözyaşlarını yere düşen damlalardan. 

Sözleri beklemek saklandıkları köşeden, 

Duymak için asılı kalmak zamanda günlerce, 

Bir kelimeye koşmak için kendini germek, 

Sonra havada süzülen bir ok olmak hedefi olmadan. 

Sevmek son çare, hayalinle yaşamaya. 

Adını söylemeye, gülümserken elindeki güle 

Sevmenin adı yok, kendisi gizler acıları 

Paylaştırdıkça ortaya çıkartır bakışları. 

Günışığına çıkartamazsın o savunmasız, 

Söyleyemezsin senin için kutsal, 

Tek şansın bir umut gizlenmiş gözlerde 

İnan sığmaz sevgiler aciz kelimelere... 

26/06/2000', 'Sevmek acı çekmektir görmemek uğruna,  Sineye çekmek umudunu zaman geçse de,  Bazen gözlerini kapatmak ve hayali ile yetinmek,  Ama hep sevm...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevmek-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmışmı', 'yasanmismi-hasan-akar-9v0hq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşanmışmı geriye  dönde bir bak

Yeter artık maziyi bir kibritle yak

Kader rüzgarına katmış sürüklüyor

Sürüklenen hayatına varmı yapacak', 'Yaşanmışmı geriye  dönde bir bak Yeter artık maziyi bir kibritle yak Kader rüzgarına katmış sürüklüyor Sürüklenen hayatına varmı yapacak...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akar']::text[], 8.5, '{"poet":"Hasan Akar","poet_slug":"hasan-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yasanmismi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışkanlık', 'aliskanlik-hilmi-tanrikulu-ysgd2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birşeye alışmak gibiydin,

Önce heyecanlı,

Sonra alaycı...

Zamanı gelince eskimedin...

dikkatli alıştım sana,sindire sindire,

dikkatsiz ayırdılar senden,öldüre öldüre....

alışkanlık gibiydin,

sana acizdi başım sonum....

yokluğunda kudurdum....

bir şeye alışmak gibiydin.... 

önce yabancı,

ardından alaycı...

küçük çocukların oyuncakları kadar,

pastel boyaların kağıtları kadar,

vardın kalemlerimde...

saklamadım alıştığımı...

bir tek sen vardın,

bilmeyen...

bir şeye alışmak gibiydin....

uzaktan uzağa...

kokusu çalınıp, ağlatılmış fesleğen,

kendini kurutmuş dalgalar,denizden gelen,

uğruna can alınacak bir söz, daha söylenilmeyen,

ve daha niceleri,

benim kadar alışmadı sana,

uzaktan uzağa....

bir şeye alışmak gibiydin...

önce yabancı,

sonra alaycı...', 'Birşeye alışmak gibiydin, Önce heyecanlı, Sonra alaycı... Zamanı gelince eskimedin... dikkatli alıştım sana,sindire sindire, dikkatsiz ayırd...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aliskanlik-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim farkı', 'mevsim-farki-hilmi-tanrikulu-px23v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aramızda mevsim farkı var,

Sen yazsın,

Ben sonbahar....

Hep hüzün; 

Senden bana kalanlar.....

Bu yüzden tevazularım...

Kendimi söndüremeyişlerim....

Sana varamayışlarım....

Ayrılığa kaçışlarım....

Kendine iyi bak diyorsun ya bana,

Ben hiç bakmıyorum kendime ama....

sonra yansıyorum aynaya....

Gözlerim hala uykuda....

Uyansa....

Yollanacak ağlamaya....

Aramızdaki mevsim farkına....', 'Aramızda mevsim farkı var, Sen yazsın, Ben sonbahar.... Hep hüzün;  Senden bana kalanlar..... Bu yüzden tevazularım... Kendimi söndüremeyişl...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mevsim-farki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arasıra uğra', 'arasira-ugra-hilmi-tanrikulu-99tsz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arasıra uğra,

Ki; 

Yaşadığımı kontrol et…

Ama sakın uyandırma,

Belki uykuya yatmışımdır,

Seni görmek adına…', 'Arasıra uğra, Ki;  Yaşadığımı kontrol et… Ama sakın uyandırma, Belki uykuya yatmışımdır, Seni görmek adına…...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/arasira-ugra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-hilmi-tanrikulu-qu6h5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yepyeni bir sayfa…

Yüreği benden küçük, yaşça…

Gel de yaşa…

Kirlet bakalım sokaklarda,

Ellerinle,

Kanınla…

Kusura bakma,

Benim yüreğim kaldırmaz,

Bembeyaz sayfaları kullanmaya.

Bana kirlileri ver,

Benden daha kirlileri.

Bulabilirsen eğer…

O zaman söyleyeceğim,

Söyleyemediklerimi.

Yüreğimin gediklilerini…

Belki….', 'Yepyeni bir sayfa… Yüreği benden küçük, yaşça… Gel de yaşa… Kirlet bakalım sokaklarda, Ellerinle, Kanınla… Kusura bakma, Benim yüreğim kaldı...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/belki-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haftaiçi Beyoğlumsun', 'haftaici-beyoglumsun-hilmi-tanrikulu-0eriz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen benim hafta içi Beyoğlumsun,

Öyle hazırsın her şeye

Ve öyle uzaksın…

Başlayınca bitmezsin,

Masum ve mavisin.

Aklıma İstanbul’u getiren şarkılar gibisin

Ve ben sefil.

Öyle hazırsın her şeye

Ve başlayınca bitmezsin…

Lakin sen başlayınca,

Ben sefil…

Git….', 'Sen benim hafta içi Beyoğlumsun, Öyle hazırsın her şeye Ve öyle uzaksın… Başlayınca bitmezsin, Masum ve mavisin. Aklıma İstanbul’u getiren ş...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/haftaici-beyoglumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaydederim Ömrüme', 'kaydederim-omrume-hilmi-tanrikulu-2jyjr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arkadaşlarım çıkardı karşıma,

Gece ansızın…

Korkar sayıklardım geçmişi,

Onlara layık olsun diye..

Sonra kaçardım onlardan….

eflatun şarkılara kaydedemediklerimi bırakırdım

Ve öyle kaçardım….

Keşke şimdi birisi gelse de,

Yüzüme tükürse….

Hemen kaydederim ömrüme…..', 'Arkadaşlarım çıkardı karşıma, Gece ansızın… Korkar sayıklardım geçmişi, Onlara layık olsun diye.. Sonra kaçardım onlardan…. eflatun şarkılar...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kaydederim-omrume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kokum', 'kokum-hilmi-tanrikulu-7y6fy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırak kokumu gitsin,

Bütün şehri dolaşsın…

Herkes koklasın…

Nasıl olsa,

Hiç kimse senin gibi koklayamayacak…

O yine seni bulacak….', 'Bırak kokumu gitsin, Bütün şehri dolaşsın… Herkes koklasın… Nasıl olsa, Hiç kimse senin gibi koklayamayacak… O yine seni bulacak…....', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kokum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müsadenle', 'musadenle-hilmi-tanrikulu-bl6pi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Giriyorum,

Girdim… müsadenle….

Kendi evime,

Sonra ağıtlara baktım,

Aramadım…

en orospu halleriyle,

bıraktığım yerde….

Toparlanacağım biraz,

Sesimi de almam gerek…

Hayat zor,

Keder var daha zor.

Nasıl  ağlarım? 

Sesim olmadan…

Yine müsadenle,

Az kalacağım evimde…

Zaten sözüm var,

Geçen yıl yanan söğütlere,

Gitmem gerek müsadenle…

Birkaç nota alsam yeter,

Sabahları kolay etmeye,

Nota ve hüzün gerek,

Söylemlere katık etmeye…

Hüzün zaten var envanterimde,

Birkaç nota alacağım,

Lazım değilse…

Dahili acılara dokunmayacağım,

Zaten sana almıştım onları…

Bitiremedim daha,

Arka cebime soktuklarını….

Bu gidiş son değil…

Uğrarım yine.

Sıcak serzenişler çıkarsa,

Fırında sıraya girerim, seve seve.

Alır, koşarım tembelliğine

Ve bırakırım,

Kapının önüne.

Sen aldanma bu gidişe….

Dönerim belki yine….

Ve sakın üzülme,

Komaya girersem yine.

Uğrarım,

Sırat köprüsünün önündeki 

Büfeye.

Bir şeyler kapar,

Dönerim sessizliğin izmaritlerine…

Eğer dumanları griyse,

Elbet gözükür,

Zifiri karanlık gecede….

Böyle sanma cinneti…

Ben nelerini geçirdim…

Gelir öğretirim yine….

Sen kal burada…

Rahatsız eden olursa,

Bekçi var kapıda…

Şarapçıların evidir burası….

Korkmazlar senden…

Sende korkma onlardan….

Belki çiçek getiriler,

Benim bayramlarda getirdiğimden…

Ama dua etmez onlar…

Belki küfür çıkar bedenlerinden…

Ben uğrarım yine….

sen korkma yılanlardan çıyanlardan….

Onlar her yerde,

Yaşamda da var…

Sen huzurlu ol….

Ben yanındayım…gidip geliyorum…

Biliyorsun….bazen yaşıyorum,

Bazen ölüyorum…', 'Giriyorum, Girdim… müsadenle…. Kendi evime, Sonra ağıtlara baktım, Aramadım… en orospu halleriyle, bıraktığım yerde…. Toparlanacağım biraz, ...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/musadenle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misafirlerim', 'misafirlerim-hilmi-tanrikulu-3tv9t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir düş kurmuşum,

Uyuyormuşum...

Hatta rüyalarım varmış...

Hatta rüyamda komşularım yaşıyormuş...

Yaşları yeni geçmiş yasakları,

Sevmişler, evlenmişler...

Ve onlarda uyuyormuş...

Çocuklarını görmüşler rüyalarında...

Sevinmişler...

Bana misafir gelmişler,

Daha konuşamadan,

Uyanmışım...

Düşüm bitmiş...

Üzülmüşüm, garipsemişim,

Son on dakikamı,

Böyle geçirmişim...', 'Bir düş kurmuşum, Uyuyormuşum... Hatta rüyalarım varmış... Hatta rüyamda komşularım yaşıyormuş... Yaşları yeni geçmiş yasakları, Sevmişler, ...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/misafirlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl ulaştık sabaha', 'nasil-ulastik-sabaha-hilmi-tanrikulu-uzz5d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl bir sabaha ulaştık böyle….

Uykusuz ve susuz,

Ama Susuzluğum kuraklıktan değil,

Rakıdan….

Sen hatırlıyor musun? 

En son beni öpüyordun,

ben sana bırakmıştım tüm şimdilerimi…

Sana yetmedi ve geçmişimi istedin,

verdim küfrederek….

Sonrası bende yok….

Zaten öncelerimi sen almıştın….şimdi onlarda yok…

Nasıl bir sabaha ulaştık….

Ömrümden kalan,bir tek bu sabah var elimde….

Öncesi ve sonrası senin bahçelerinde gömülü,

Sana ektim yani tüm ömrümü….

Bakalım ne çıkacak…o kadar rakı serptim üstüne….

Bakalım ne çıkacak senden bana…

Ama önce anlat….

Nasıl ulaştık sabaha?', 'Nasıl bir sabaha ulaştık böyle…. Uykusuz ve susuz, Ama Susuzluğum kuraklıktan değil, Rakıdan…. Sen hatırlıyor musun?  En son beni öpüyordun,...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/nasil-ulastik-sabaha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anlamı Var', 'bir-anlami-var-ali-i-hsan-ozturk-jc4l7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sesin okşuyorsa ruhumu

Titretiyorsa bedenimi nefesin

Hevesin amacım oluyorsa

Elbette bunların bir anlamı var.

Uyuyamıyorsam seni düşünmekten

Tüm rüyalarımda seni görüyorsam

İsmini sayıklıyorsam uykularımda

Elbette bunların bir anlamı var.

Seviştiğimiz yatağa yatmıyorsam

Giydiğin mavi gömleğimi yıkatmıyorsam

Teninin kokusu hala üzerimdeyse

Elbette bunların bir anlamı var.

Doğa seninle güzel, gökyüzü seninle mavi

Dünya senin etrafında dönüyorsa gözümde

Ben sırf senin için yaşıyorsam

Elbette bunların bir anlamı var.

Üzüntün kederin yıkılışım oluyorsa

Can pınarımdan akıyorsa gözyaşın

Tüm benliğimi sana adamışsam

Elbette bunların bir anlamı var.

Varlığımı seninle eşdeğer tutuyorsam

Tüm insanlar seni hatırlatıyorsa bana

Yokluğunda yaşamıyorsam eğer

Elbette bunların bir anlamı var.

İhanetin kana boğuyorsa yüreğimi

Sensiz kalmak kıyametim oluyorsa

Yinede bu cana hala kıymadıysam

Elbette bununda bir anlamı var.', 'Sesin okşuyorsa ruhumu Titretiyorsa bedenimi nefesin Hevesin amacım oluyorsa Elbette bunların bir anlamı var. Uyuyamıyorsam seni düşünmekten...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Öztürk']::text[], 8.5, '{"poet":"Ali İhsan Öztürk","poet_slug":"ali-i-hsan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-anlami-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne yapacaksak yapalım', 'ne-yapacaksak-yapalim-hilmi-tanrikulu-n5jne', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşün şimdi,

Vakit geldi...

Akşam oldu ikimize...

Ya vazgeçeceğiz seninle,

Ya sevişeceksin benimle...

Çabuk! 

Olmaya engel bundan sonra,

Geçmesin zaman boşa...

Hadi karar ver,

Ayrılıkla hüzün düşecekler....

Sonra ne yaparız? 

Bizi beraber görecekler...

Acele et,

Kaç an etti beklediğimiz...

Kalmadı sabrım,

Hadi yalnızlığım,

Ne yapacaksak yapalım...', 'Düşün şimdi, Vakit geldi... Akşam oldu ikimize... Ya vazgeçeceğiz seninle, Ya sevişeceksin benimle... Çabuk!  Olmaya engel bundan sonra, Geç...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-yapacaksak-yapalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne yaptım....', 'ne-yaptim-hilmi-tanrikulu-s3141', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne yaptım? 

Bir konser izledim,

Çok beğendim.

Azıcık eğlendim…

Ne yaptım? 

Bir şeyler içtim.

Başım döndü,sendeledim.

Kocaman şehirde,

Tektim…

Ne yaptım? 

Kısa hikayeler yazdım.

Sonra kendimden sakladım.

Hikayeler yaşattılar beni,

İçimdekileri rahatlattım..

Ne yaptım? 

Kendim sordum,

Kendim cevapladım…', 'Ne yaptım?  Bir konser izledim, Çok beğendim. Azıcık eğlendim… Ne yaptım?  Bir şeyler içtim. Başım döndü,sendeledim. Kocaman şehirde, Tektim...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ne-yaptim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrüm gibi kısacık saçlarım', 'omrum-gibi-kisacik-saclarim-hilmi-tanrikulu-a53tb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kısacık saçlarım…

Ömrüm gibi…

Ben hiç yaşamadım,

Saymazsam seni….

Yokluk vurmuşken dibe….

Saygısız varlığın ne kelime yüreğime….

Ancak acı….

Bedenime….

Ömrüm gibi kısa saçlarımı doladım,

Gözlerime…

Ve o halimle öyle bir dokundum ki sonsuza,

Öldüm….

Oysa sarhoştum, 

Kanındaki alyuvarlarla içip içip 

Seni konuşmuştuk….

Ölmeyecektik….

Öldüm….

Ömrümü gözlerim bitirdi…

Gözlerimi saçlarım…

Sayende sonsuz oldum….

Ve geçen dünyada hiç bir şey yaşamdım…

Saymazsam seni….', 'Kısacık saçlarım… Ömrüm gibi… Ben hiç yaşamadım, Saymazsam seni…. Yokluk vurmuşken dibe…. Saygısız varlığın ne kelime yüreğime…. Ancak acı…....', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/omrum-gibi-kisacik-saclarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Sevda, İşte Ben', 'i-ste-sevda-i-ste-ben-ali-i-hsan-ozturk-ma5tr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlatamam ki duygularımı

Ne kalem anlatabilir beni, ne kağıt

Ne de kelimeler anlatabilir duygularımı.

Anlamak çözmek istersen beni

Bana tüm çıplaklığınla gel

Kaybetmek korkusunu atarak yüreğinden

Saf ve temiz duygularla gel.

Soyut olan ne varsa bende

Bir kaşif edasıyla ufak ufak keşfet beni

Gönlümün içine ta derinliklerine in ki! 

Gizemlere ulaş bir bir.

Kimi sırlarda çöl sıcağıyla kavrulacak

Kimi sırlarda kutup soğuğunda donacaksın

Uçsuz bucaksız kır çiçeklerine vardığında,

Soyun ki bedenini okşasın onlar.

Her çiçek ılık bir nefes,

Her çiçek ateşli bir öpücük,

Ve her çiçek benden bir parça anımsatıyorsa sana

Bil ki! Ruhum orada gizlidir.

Ulaştığın değeri bil ve tanı.

İçeride kalmak senin elinde

Lakin yaşayabileceğine kanaatin varsa orada

Tüm tabuları yıkmalı, benliğine hoşça kal demelisin

Ve gönlüme merhaba…

Kuralları mantığımız değil, aşkımız koyacak

Bütün çılgınlıkları sınırsız yaşayacağız

İrem’in güzelliklerini paylaşacağız birlikte

Ben-Sen değil, biz olacağız iki ayrı bedende

Ama; her şeyi başarmak senin elinde,

Evet diyecek cesaretin varsa

İşte Gönül, İşte sevda, İşte ben…', 'Anlatamam ki duygularımı Ne kalem anlatabilir beni, ne kağıt Ne de kelimeler anlatabilir duygularımı. Anlamak çözmek istersen beni Bana tüm ...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Öztürk']::text[], 8.5, '{"poet":"Ali İhsan Öztürk","poet_slug":"ali-i-hsan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/iste-sevda-iste-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rutin', 'rutin-hilmi-tanrikulu-erp85', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kış kendini sakladı,

Ağaçlar çiçek açtı.

Matematiğe vurdu güneş, şehri

Sayım günü sessizliği çıktı...

Ve dünya utandı kendinden....

Toprak bedenim istemediğinden,

Üzüldüm halime,

Oturup yazdım...

Bilindik kelimelerle,

Yollandım bilinmedik cümlelere...

Bitmedi hiç sayfam ve yazmam,

İlham perilerinin sekizi bende bu akşam,

Birini izne yolladım,

Belki de eksikliğim ondan...

Hep rutinim.

Kış kendini sakladığında,

Huylarımı dağıtıyorum odama...

Ağaçlar çiçek açtığında,

Kızıyorum kışın yalanına...

Ve kendinde utanıyor dünya....

Bedenimi kabul ettiremediğimde toprağına,

Aslında hiç kimseyim...

Yazdıklarımı yaşadığımdan,

Ve alıştığımdan kışın yalanına,

Aslında rutinim...', 'Kış kendini sakladı, Ağaçlar çiçek açtı. Matematiğe vurdu güneş, şehri Sayım günü sessizliği çıktı... Ve dünya utandı kendinden.... Toprak b...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/rutin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süt', 'sut-hilmi-tanrikulu-u4ijh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman; 

Kendini kandıramadığından,

Eskiyorum...

Ve her geçen gün,

Küfleniyorum...

Daha dün gibi,

Annemden içtiğim süt....', 'Zaman;  Kendini kandıramadığından, Eskiyorum... Ve her geçen gün, Küfleniyorum... Daha dün gibi, Annemden içtiğim süt.......', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı', 'sarki-hilmi-tanrikulu-1imol', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Radyoyu açıp,

Bir şarkıyı beklemek gibisin…

Heyecanlı ve kısıtlı.

Hele sen gelince bir sevincim var ki; 

Yüreğim cinnet,

Gözlerim kan çanağı…', 'Radyoyu açıp, Bir şarkıyı beklemek gibisin… Heyecanlı ve kısıtlı. Hele sen gelince bir sevincim var ki;  Yüreğim cinnet, Gözlerim kan çanağı...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sarki-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkedilmiş şehir', 'terkedilmis-sehir-hilmi-tanrikulu-xl981', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep bahsederler aslında,

Sen hiç terkedilmiş şehir gördün mü hayatında? 

Ben gördüm….

Sende,

Okuyorsun şu anda….', 'Hep bahsederler aslında, Sen hiç terkedilmiş şehir gördün mü hayatında?  Ben gördüm…. Sende, Okuyorsun şu anda…....', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/terkedilmis-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya düşersem gözlerine', 'ya-dusersem-gozlerine-hilmi-tanrikulu-6qkjb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aklımda tutamadım hiç gözlerini....

Rasgele uçurulmuş uçurtmaların,

Düşme korkusu var peşimde...

Ya düşersem gözlerine....', 'Aklımda tutamadım hiç gözlerini.... Rasgele uçurulmuş uçurtmaların, Düşme korkusu var peşimde... Ya düşersem gözlerine.......', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ya-dusersem-gozlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-hilmi-tanrikulu-ptsm7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah yalnızlık…….

Sen ne büyüksün…..

Kadın ne ki….

Sen bütün hepsinden güzelsin……..', 'Ah yalnızlık……. Sen ne büyüksün….. Kadın ne ki…. Sen bütün hepsinden güzelsin…….....', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalnizlik-256-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yatağım', 'yatagim-hilmi-tanrikulu-139bb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bembeyaz…

Ve dağınık biraz…

bir yatak…

Uykuya adanmış bir yolda…

İmzamı atarım,

Masumluğunun altına…

Giriyorum içine…

Uyuyorum sadece…

Sonra; 

‘’ boynumda bir öpücükle irkiliyorum…

çeviriyorum yüzümü, sendeliyor ruhum,

öpüyorum kanlı kanlı…

içim akıyor, yüzüyorum yabancı bir tende

yeni kelimeler katıyorum sözlüğüme,

bitiyorum…’’

uyanıyorum sadece,

yatağımdan utanıyorum sessizce.

Yatağım,

Hangi bulut geçebilir ki yerine.

İmzamı atarım,

Sakladıklarının üzerine….', 'Bembeyaz… Ve dağınık biraz… bir yatak… Uykuya adanmış bir yolda… İmzamı atarım, Masumluğunun altına… Giriyorum içine… Uyuyorum sadece… Sonra...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yatagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yola çıkmışım', 'yola-cikmisim-hilmi-tanrikulu-vl1da', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yola çıkıyorum....

... yola çıkmışım

en aydınlık sokaklarda,

gözümü karartmışım.

İçimi süzmüşüm,

Cinnet cinnet ağlamışım.

Sıfırlamışım bildiklerimi,

Kendime baştan inanmışım.

Yola çıkmışım....

...yola devam ediyorum,

yaşlanıyorum...', 'Yola çıkıyorum.... ... yola çıkmışım en aydınlık sokaklarda, gözümü karartmışım. İçimi süzmüşüm, Cinnet cinnet ağlamışım. Sıfırlamışım bildi...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yola-cikmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladılar senden anlattıklarıma', 'agladilar-senden-anlattiklarima-hilmi-tanrikulu-82wk7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayaklarının sureti mahalleni ayaklandırdı.

Meydanda bir ceset yatıyor,

Benden geri kalan.

Gözlerimde ki rüyadan,

Ve hastalığımdan,

Artan…

Cesedi kaldırıp gömdüler,

Yanlış yüreğe,

Filizlendim sessizce.

Teninin kokusuna hasretli,

Çiçekler çıkardım…

Utandılar yaptıklarıma,

Ağladılar senden anlattıklarıma…

İsteyemediler benden,

Toprağın altında kalmamı.

İsteyemediler gülden,

Dikeninden utanmasını…

Mahcup oldu gökyüzü,

Gülüme ve cesedime ağladı.

Adına yağmur dediler,

Kimse gerçeği anlamadı…

Çocuklar cesaret etti,

Gözyaşlarına sordu…

 Bozmadı oyunumu gözyaşları,

Cevapları iki melodi etti…

Yol kenarları ve günbatımı,

Ağlaştı her melodi başlangıcında.

Melodiler ağıtlara benzetti kendini,

Şereflendirdiler cesedimi…

Öylece kaldım…

Sokak çocukları ve sanatçılar bile utandı…

Sevdiklerimin cesedime yaptıklarına…

Sığındım tanrıya…

Anlattım…

Ağladılar senden anlattıklarıma…', 'Ayaklarının sureti mahalleni ayaklandırdı. Meydanda bir ceset yatıyor, Benden geri kalan. Gözlerimde ki rüyadan, Ve hastalığımdan, Artan… Ce...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/agladilar-senden-anlattiklarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen git yemek ye', 'sen-git-yemek-ye-hilmi-tanrikulu-1zyjc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen git yemek ye…

Ben rüya göreceğim.

Göremezsem,

Görene kadar gideceğim.

İlla ki göreceğim bu akşam.

Görmem gerekiyor zaman zaman.

Uzak kaldığımda toprağımdan,

Toprağımı çıkarıyorum rüyamdan…

Oyun oynuyorum yoklarla,

Babamı görüyorum, yorgunca,

Sevişiyorum aşkımla,

Konuşuyorum toprak olanlarla.

Uçuyorum üstüm açıkken,

Üstümden geçen meltemden…

Rüyalarımı arıyorum, unutmuşken,

Puslu hikâyeler arıyorum,

Sen yemek yerken…

Unutuyorum çok sabah,

Kalkarken âşık olduğumdan,

Bereketini kaçıyorum uykularımın,

Sıkılınca rüyalarımdan.

Kâbuslarımdan…

Bazen karışıyor rüyalarım ile hayatlarım,

Ayaklarımın altından deniz geçerken,

Yaşıyor muyum gerçekten,

Uyuyor muyum yaşarken,

Bilmemezlikten geldiğimden, bilmediğimden,

Karışıyor istemeden…

Gözlerim uykuma düşerken,

Ellerimi ayırıyorum bedenimden,

Ayırmam gerekiyor zaman zaman,

Uzak kaldığımda rüyalardan…

Uyuyorum çünkü,

Görüyorum,

Gördüğümü,

Unutuyorum….

Sen git,

Yemek ye…', 'Sen git yemek ye… Ben rüya göreceğim. Göremezsem, Görene kadar gideceğim. İlla ki göreceğim bu akşam. Görmem gerekiyor zaman zaman. Uzak kal...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sen-git-yemek-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen...', 'sen-yasar-bereket-avv1a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir davadayım...

cellat en ağır baltasını hazırlamakta

sehpa kurulu

iplerse dünden hazır 

geçmek için ince boynuma...

biri seviniyor 

diyor ki:

''Ne mutlu! ölüyor bir vatan haini daha.'' 

biri ise aglıyor 

diyor ki:

''yazık bir can daha verdik onurlu kavgada''

bense düşünüyorum

ve diyorum ki:

''eğer ben bir kahramansam

savaştıysam ölümüne 

vazgeçtiysem bir gece vakti 

yıldızlara bakmaktan

ölüyorsam güneşli bir yaz sabahı

sebebi sensin bu kahrmanlığın

ve ölümüm, sevdiğim! 

en büyük ayıbıdır insanlığın...', 'bir davadayım... cellat en ağır baltasını hazırlamakta sehpa kurulu iplerse dünden hazır  geçmek için ince boynuma... biri seviniyor  diyor ...', ARRAY['Türk Edebiyatı','Şiir','Yasar Bereket']::text[], 8.5, '{"poet":"Yasar Bereket","poet_slug":"yasar-bereket","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-576-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbulu Dolaştım', 'i-stanbulu-dolastim-hasan-cam-z6xsn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstanbul''u dolaştım bu gece

Sen gibi yuvarladı kaldırımları beni

Hiçbir sokağın sonu gelmedi

Kapı numaranı aradım sokak sokak

Işıkları sönmüş tüm evlerin

Safaride yaşlı aslan düşündüm kendimi

Tarihin gibi eskimişim, kim ne yapsın beni

Bulan sevinmez kaybeden hiç üzülmez

İçinde kimleri barındırmadınki istanbul

Koçları,Sabancıları, Uzanları

Koskoca denizleri bile havuz yaptın

Yalnız bana bir bana kapını açmadın

Neydi beni sana baglayan istanbul

Sevgimi, ömrümü, sen gurbetimi aldın

Tarihin gibi eskimişim, kim ne yapsın beni

Bulan sevinmez kaybeden hiç üzülmez

18,02,2005,

Ümraniye   İstanbul', 'İstanbul''u dolaştım bu gece Sen gibi yuvarladı kaldırımları beni Hiçbir sokağın sonu gelmedi Kapı numaranı aradım sokak sokak Işıkları sönmü...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/istanbulu-dolastim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir başka', 'bir-baska-ahmet-ayanoglu-gwcqt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çevirme beni yolumdan

yolum çok uzak

önümde binbir tuzak

ben dağlara tutsak

sen ise aşka

zamanım olmasada aşka

benim sevdam bir başka', 'çevirme beni yolumdan yolum çok uzak önümde binbir tuzak ben dağlara tutsak sen ise aşka zamanım olmasada aşka benim sevdam bir başka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ayanoğlu']::text[], 8.5, '{"poet":"Ahmet Ayanoğlu","poet_slug":"ahmet-ayanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-baska-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Bahçesindeki Sevgiliye Ağıt', 'gul-bahcesindeki-sevgiliye-agit-nigar-adak-d7ofv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen ki, mağrur çehrenle, asi bahar gülüsün.

Önünde secde eden, bülbüle gülen gülsün.

Bense sarp kayalarda, yorgun yıldız çiçeği.

Tek bir sözüne vurgun, kanlı sevda çiçeği. 

Sen gül bahçelerinde, ağıtlardan uzaksın.

Beyaz gönül kuşumu, yaralayan tuzaksın.

Gökkuşaklı hayaller, uykunu süsledikce,

Gecelerin tenine, aşkla seni işledim.

Göklerinde yıldızlar, şiirler söyledikce,

Çürüttüğün baharın, hazarını izledim.

Yalnızlığın küf kokan, yitik mahzenlerinde, 

Ciğerin kanamadı, has aşkın közlerinde.

Sen sevda acısını, yaşamadın bilmezsin.

Bıçak sırtı kederi gaye, bal eylemezsin.

Gemilerin poyrazda, yönünü şaşırmadı.

Limansız öksüz gibi, hiç çaresiz kalmadı.

Ateşi üzerine, derman diye örtmedin.

Sevdanın korlarını, şifa diye öpmedin.

Hüzün çıkmazlarından boşluklara düşerken,

Tutunacak ellere, boş yere uzanmadın.

Aşkın uçurumunda yârdan imdat beklerken,

Bin parçaya bölünüp, toprağa dağılmadın.

Ruhumun yamacında, yeşil ovalar vardı.

Güneşle sarmaş dolaş, gözlerine uzardı.

Koşardı ceylanlarım, sen kalbime baktıkca.

Coşardı nehirlerim, sen gönlüme aktıkca.

Ay parçası yüzünde, mehtap şarkı söylerdi.

Saçlarında yakamoz, parlar eşlik ederdi.

Senin bir bakışınla, kainat aydınlanır,

Yüreğimin çölünde, kumlar çiçek olurdu.

Gonca gamzelerinde, tüm tabiat canlanır, 

Filizlenen duygular, aşka buse olurdu.

Sen sevdamın özüne, inemedin maralım.

Deryanı bulandırdın, yüzemedin karalım.

Sen aşkı bir mevsimlik, gönül oyunu sandın.

Ağustos güllerinin, mis kokusuna kandın.

Hazan rüzgarı esip, güz gülüne dönünce, 

Aşkımı öğrenirsin, pişmanlık görününce.

Nigar Adak

03.07.2005

Dikkat: Şiirlerimin hepsi noter tasdiklidir..! Şair adı olmadan alıntı yapılamaz..!', 'Sen ki, mağrur çehrenle, asi bahar gülüsün. Önünde secde eden, bülbüle gülen gülsün. Bense sarp kayalarda, yorgun yıldız çiçeği. Tek bir söz...', ARRAY['Türk Edebiyatı','Şiir','Nigar Adak']::text[], 8.5, '{"poet":"Nigar Adak","poet_slug":"nigar-adak","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gul-bahcesindeki-sevgiliye-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutunmak', 'tutunmak-sanem-deniz-xfvch', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatını erteleme 

Tutun en derinlerden toprağa 

Köklerini sal 

Yeşermeye çalış, çiçek aç 

Yağmurda, doluda, karda 

Dimdik kal eğme başını 

Güneş açtığında kaçırma gözlerini 

Ağlayayım deme acılara, 

Küsme hayata her ne olursa 

Silkelen bir bak etrafına 

Senden kıymetli bir sen daha var mı ki? 

Bu yalancı dünyada!', 'Hayatını erteleme  Tutun en derinlerden toprağa  Köklerini sal  Yeşermeye çalış, çiçek aç  Yağmurda, doluda, karda  Dimdik kal eğme başını  ...', ARRAY['Türk Edebiyatı','Şiir','Sanem Deniz']::text[], 8.5, '{"poet":"Sanem Deniz","poet_slug":"sanem-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tutunmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-oguz-yirmibes-fo00z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şey seninle güzel hayatımda 

Aşk senle var damarlarımda

Ölüm oyuncak sepetimde bir hatıra

Ve bekleyiş, beklemek seni yıllarca 

Özlemek kokusunu teninin 

Lanet olsun sen olmadan geçirdiğim yıllara

Lanet olsun sensizliğe

Doyamam ben bu hayatta sana 

Gerekir yıllar milyonlarca

Koşturup dururken bile yalanlarımın arkasından

Boş boş gezinirken sokaklarımda 

Kaybolurken çaresizliğin getirdiği ezikliğin altında 

Durup düşünsem seni 

Ve hayatım anlam kazansa senle

Bunca kötülüğün içinden çıkarıp götürürsün beni

Senin bile tahmin edemediğin kadar uzaklara', 'Her şey seninle güzel hayatımda  Aşk senle var damarlarımda Ölüm oyuncak sepetimde bir hatıra Ve bekleyiş, beklemek seni yıllarca  Özlemek k...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yirmibeş']::text[], 8.5, '{"poet":"Oğuz Yirmibeş","poet_slug":"oguz-yirmibes","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gercek-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuğum Ben', 'cocugum-ben-dilek-ozdemir-xb5rb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuğum ben

ağlarım hala kanayınca yüreğim

koşma düşersin derler

dinlemem yine koşarım

aşk kelebeğini yakalamacasına

düşer yüreğimi kanatırım

ağlarım

Çocuğum ben

mızıkçılık yapınca sevdiğim

gider şikayet ederim büyük kendime

zamana lanetler yağdırıp

küserim bir daha oynamamacasına

sevgim hep galip gelir

barışırım

Çocuğum ben

koşarım, düşerim, ağlarım

çocuğum ben

severim, küserim, barışırım', 'Çocuğum ben ağlarım hala kanayınca yüreğim koşma düşersin derler dinlemem yine koşarım aşk kelebeğini yakalamacasına düşer yüreğimi kanatırı...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cocugum-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sanem-deniz-kxl5k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Burcu burcu akıttın aşkı içime

Musallat oldun bu garip gönle

Viraneye döndüm aşkın elinde

Taptığım bastığım toprağım oldun

Dilimden düşmez o güzel ismin

Gözlerimden silinmez güzide resmin

Kulaklarımda çınlar hüzünlü sesin

Hayatımı verdiğim bir emel oldun

İnlesem de yoktur derdime çare

Bilirim bakmazsın bu garip hale

Son nefesimi versem senin elinde

Sardığım yattığım kefenim oldun', 'Burcu burcu akıttın aşkı içime Musallat oldun bu garip gönle Viraneye döndüm aşkın elinde Taptığım bastığım toprağım oldun Dilimden düşmez o...', ARRAY['Türk Edebiyatı','Şiir','Sanem Deniz']::text[], 8.5, '{"poet":"Sanem Deniz","poet_slug":"sanem-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-577-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-hasan-cam-qur83', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoksun yok, bu gecede yoksun

Kapıda karşılayışın yok

Tebessümün, gülüşün yok 

Odamda karşılayışın yok

Saat yirmi üç, yoksun sen yok

Ellerimi tutuşun yok 

Gözlerime bakışın yok

Saçlarımı okşayışın yok

Saat yirmi dört, yoksun yok

Boynumda, ılık nefesin yok

Saat sıfır bir, yoksun yok

Bal dudağınla öpüşün yok

Sıcak sarılışın, okşayışın yok

Saat sıfır iki, yoksun yine yok

Ve sıfır dört, üstümü örtüşün yok

Dışarda yağmur, çok soğuk

Zifiri karanlık, yalnızım yoksun

Cama vuran, rüzgardan başka yok

Umutlarım, duygularım kaldı dışarda

Üşümesin, bari ona sahip çık, yoksun yok

02,02,2005,

Ümraniye   İstanbul', 'Yoksun yok, bu gecede yoksun Kapıda karşılayışın yok Tebessümün, gülüşün yok  Odamda karşılayışın yok Saat yirmi üç, yoksun sen yok Ellerimi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yoksun-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sokak Çocuğu', 'ben-sokak-cocugu-dilek-ozdemir-jpjwi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sokak çocuğu

ben hayattan kovulan bir fidan

ben yalnız kendi düşlerinde kahraman

yatağım kuytular

duşum yağmurdur benim

yoktur dişlerimden başka tırnak makasım

nasıldır soğuk kış gecelerinde mısır patlatmak

ütülü giysiler nasıl değer tene

yemek nasıl seçilir bilmem

akşam olup da yanınca evlerin ışıkları

kapattım mı gözlerimi soğuğa ve karanlığa

camların buğusundan dalar girerim içerilere

en sevdiğim yemekleri pişirmiştir annem

tokluk sonrası sokulup sıcağına

uzanırım dizine

uyurum

sahip olduğum tek bolluk

salgısıdır burnumun

bir de, bir de soğuk

ve hepsinden önemlisi

başımı rüzgarlar okşar sadece

ellerimde acılı bir tarih vardır

eksilmeyen bir çığlık gözlerimde

birbiri ardına saklanan sokaklarda

oynarken saklambaç oyunumu polisle

Ben sokak çocuğu

ben hayattan kovulan bir fidan

ben yalnız kendi düşlerinde kahraman', 'Ben sokak çocuğu ben hayattan kovulan bir fidan ben yalnız kendi düşlerinde kahraman yatağım kuytular duşum yağmurdur benim yoktur dişlerimd...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-sokak-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aktın Gözlerimde', 'aktin-gozlerimde-hasan-cam-m9e0q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bulut oldun çöktün üstüme

Yağmur gibi aktın gözümde

Aşkınla yanan şu yüreğime

Tusunami depremleri oldun

Nehir oldun, göller, baraj oldun

Denizler, okyonuslarsın içimde

Sen hep aktın aktın gözlerimde

Sen hep aktın aktın gözlerimde

Hasretimsin yıllarca yüreğime

Yollar filmler gibi aktın gözüme

Biçare medet olmadın gönlüme

Yapraklar gibi döküldün ömrüme

Nehir oldun, göller, baraj oldun

Denizler, okyonuslarsın içimde

Sen hep aktın aktın gözlerimde

Sen hep aktın aktın gözlerimde

10,02,2005

Ümraniye  İstanbul', 'Bulut oldun çöktün üstüme Yağmur gibi aktın gözümde Aşkınla yanan şu yüreğime Tusunami depremleri oldun Nehir oldun, göller, baraj oldun Den...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aktin-gozlerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşif', 'kesif-dilek-ozdemir-bf8o6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sabah şafak rüzgarlarıyla

yeniden keşfedilebilir insan

bütün seslerine yetişilebilir dünyanın

ve bir destan yazılabilir erkenden

sular gibi berrak

kuşlar gibi özgür

aşklar gibi tutkulu

yaşama merhaba denilebilir yeniden

gelecek günlerin umuduyla', 'Bir sabah şafak rüzgarlarıyla yeniden keşfedilebilir insan bütün seslerine yetişilebilir dünyanın ve bir destan yazılabilir erkenden sular g...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kesif-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme', 'anneme-ferhat-eren-88ktp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gün anneler günü…

Şimşekler çakıyor, ağlıyor gökyüzü,

İçime akıttığım göz yaşlarımı saklamak ister gibi.

Kızıl seller yollarımı kesiyor her sokaktan,

Bu gün, gün yerine karanlıklar doğuyor şafaktan.

Güneş gözlerini kapatmış, bakmıyor gözlerime

Ellerimde çiçekler yok bu gün,hürmetimi sunmak için ellerine.

Bütün limanları boğmuş azgın dalgalar,

Ağlıyor gözlerim,ağlıyor yüreğim,

Nerelere tutunacağım bilemiyorum.

Hadi sen gel artık anne,

Hain pusular yollarımı kapatmış, ben sana gelemiyorum.

Ellerim üşüyor anne, avuçlarım yok avuçlarında.

Bedenimi saran zulüm sarmaşıkları zehirliyor kanımı.

Kuluçkadan yeni çıkmış civcivler gibi şaşkınım.

Üşüyorum anne…

Kanatlarını özlüyorum anne.

Nerelerdesin, hani  nerelerde anne? 

Yoksun yanımda,

Şefkatine muhtacım.

Yalnızlık bitiriyor gücümü, 

Üzerime geliyor bütün dünya, gücüm bitiyor anne.

Nerede merhamet kanatların, neden yoksun yanımda? 

Duymuyor musun  gökleri yırtan zulüm çığlıklarını.

Göğsüme bastırdığım çocuklarımı bile ısıtmaya gücüm yok artık.

Kimsem yok başımı okşayacak,

Kimsem yok sırtımı yaslayacak.

Bütün kapılar kapandı sanki,

Bir çardak bile yok altına sığınacak.

İçime yağıyor bütün sağanaklar.

Kara bulutlar esir aldı ruhumu.

Uzat artık ellerini, tut ellerimden.

Sen annemsin,canıma can verensin,

Kurtar beni çıkmaz sokaklardan, 

Hadi gel, tut artık elerimden.

Kurtar beni, mahkum olduğum zindanlardan 

Seni özlüyorum annem.

Hani nerde bahar rüzgarı kokun.

Göğsüne yaslayamıyorum başımı, güneşin battığı vakitlerde.

Kanepenin üzerinde uyuyup kalmışım bak,

Üzerimi kimseler örtmüyor anne.

Yavrularım bile içimi ısıtmıyor anne.

Bu gün anneler günü,

Çiçekler çok uzakta, toplayamıyorum.

Yüreğimi zulme hapsetmek istiyor kara vicdanlar

Bedenimi esir etmek için taş duvarlara.

Kurtuluşum yıldızlarda biliyorum.

Öyle uzaktalar ki, 

Çok yorgunum,

Çaresizim,

Gücüm yok söylemeye

Beni bekliyorlar biliyorum.

Ellerim yetişmiyor annem, 

Uzanamıyorum.', 'Bu gün anneler günü… Şimşekler çakıyor, ağlıyor gökyüzü, İçime akıttığım göz yaşlarımı saklamak ister gibi. Kızıl seller yollarımı kesiyor h...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Eren']::text[], 8.5, '{"poet":"Ferhat Eren","poet_slug":"ferhat-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/anneme-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki', 'celiski-mikdat-bal-7l87n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok kişi aydınım, söylüyor ama

Patavatsız, konuşurlar katiller

Puştların kalpleri kör yani âmâ

Pespayeler kokuşurlar katiller

Entrikadır, başka değil sözleri

Pislik kokar kalıpleri hem özleri

Pervasız kahpedir, kansız yüzleri

Perişanca kakışırlar katiller

Lanet olsun insanları yaktıran

Parçalatıp, kardeş kanı akıtıran

Planlayarak köyler yakıp yıktıran

Pisler, kemik kapışırlar katiller

İşte böyle, bazı aydın nursuzlar

Kalemleri kiralık uğursuzlar

Kalpleri kapalı bu onursuzlar

Kışkırttarak, konuşurlar katiller

Şirretlikte en ileri saftalar

Kandırmakta, konuşmada laftalar

Kendi karındaşlarını aftalar

Karşı savdan kaçışırlar katiller

Kalmadı onlara artık inanan

Kardeşleri bile, ErmeniYunan

Kapılmışlar körü körüne, inan

Karışmışlar, kopuşurlar katiller

İşte böyle bazısı satılmıştır

Mikdat der ki  çoğu aldatılmıştır! 

Fikirleri çöplüğe atılmıştır

O çöplükte kokuşurlar katiller', 'Çok kişi aydınım, söylüyor ama Patavatsız, konuşurlar katiller Puştların kalpleri kör yani âmâ Pespayeler kokuşurlar katiller Entrikadır, ba...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/celiski-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni Seviyorsun Karanfilim', 'sen-beni-seviyorsun-karanfilim-dilek-ozdemir-0preg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen beni seviyorsun kan bakışlı karanfilim

Düşürmesen de yağmurlarını gözlerinin bulutundan

Kupkuru kalmış yüreğim ıslanıyor sen bakınca

Gözlerinde kan gölleri

Titriyorsun

Sen beni seviyorsun ay gülüşlü karanfilim

Hiç sevilmemiş bir çocuğun hüznündeyken gözlerin

Gözlerime değince kır çiçekleri yayılıyor yüzüne

Çıplak kalıyor gülüşlerin

Titriyorsun

Sen beni seviyorsun ateş tenli karanfilim

Ellerin sarsıntılar yaratıyor bedenimde

Parmak uçlarımda aşkı hissediyorum

Çünkü hissettiriyorsun

Titriyorsun

Sen beni seviyorsun deniz sesli karanfilim

Bir gitarın nağmeleri alıp götürüyor beni

Fısıldıyor kulağıma işte aşk bu diye

O gitarı sen çalıyorsun

Titriyorsun

Sen beni seviyorsun kor yürekli karanfilim

Tanrısı aşk olan tapınaktır yüreğin

Her gün buzlara gömüyorsun, her gün buzlar eriyor

Zamanı gelince doyumsuz ibadetin

Titriyorsun

Titriyorsun

Sen beni seviyorsun az sevilmiş karanfilim', 'Sen beni seviyorsun kan bakışlı karanfilim Düşürmesen de yağmurlarını gözlerinin bulutundan Kupkuru kalmış yüreğim ıslanıyor sen bakınca Göz...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-beni-seviyorsun-karanfilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sivas''ın Oğluyum', 'ben-sivas-in-ogluyum-sahin-yilmaz-whb5z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bozkırın ortasında medeniyet beşiği

Buradan arşa çıkar evliyanın ışığı

Saymakla tükenir mi ozanları, aşığı? 

Veysel''le aşka geldim, Ruhsati''yle doluyum

Sivas benim vatanım, ben Sivas''ın oğluyum

Alevi, Sünni kardeş, kardeşliği biliriz

Vatan için yaşarız, vatan için ölürüz

Provake etmeyin bir araya geliriz

Ali benim imamım, Osman''a da bağlıyım

Sivas benim vatanım, ben Sivas''ın oğluyum

Özümde yiğitlik var, haksızlığa gelemem

Zulme suskun kalıp da dilsiz şeytan olamam

Dostlarım ağlar iken kahkahayla gülemem

Yanlışa isyan eden Pir Sultan, Köroğlu''yum

Sivas benim vatanım, ben Sivas''ın oğluyum

Yıldırım''ın geldiği Osmanlı şehiriyim

Kızılırmakla coşan bereket nehiriyim

Her ilmin merkeziyim batınî, zahiriyim

Orta Asya''dan gelen Oğuzların koluyum

Sivas benim vatanım, ben Sivas''ın oğluyum

Çifte Minare''siyle eder dine şehadet

Gökmedrese, şifaiye Selçuklu''dan emanet

Kitabında yer almaz kalleşlik ve ihanet

Talibi''ye meftunum, Ali İzzet''e deliyim

Sivas benim vatanım, ben sivas''ın oğluyum

Cumhuriyet temeli sağlam örüldü burda

Kurtuluş Savaşına karar verildi burda

Bir millet şaha kalktı, tekrar dirildi burda

Özgürlük çinarının yaprağıyım, dalıyım

Sivas benim vatanım, ben Sivas''ın oğluyum.', 'Bozkırın ortasında medeniyet beşiği Buradan arşa çıkar evliyanın ışığı Saymakla tükenir mi ozanları, aşığı?  Veysel''le aşka geldim, Ruhsati''...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ben-sivas-in-ogluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Bu Ayrılık', 'i-ste-bu-ayrilik-dilek-ozdemir-8w8bn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olmaz diyorduk, oldu işte

çaldı ayrılık kapımızı

çaldı ve alıp götürdü

titremeleri ve o anlık ölümleri

kara katran gibi kelimeler

döküldü gül açtıran dudaklardan

döküldü yıldızlı gecelerin koynuna

kül etti esintili sabahların büyüsünü

çarmıha gerildi kutsal dokunuşlar

ve yakıldı, ne uğruna

gece tanıklığından utandı

sıcak bedenlerle kaynayışını hatırladı deniz

ay ağladı sessizce

nerde, hani nerde o sevda

nerde kenetlenen yazgıların kavgası

nerde sürgünden çağrılan o adam

hangi gecenin karanlığında boğuluyor şimdi

güle güle sevgili umutlarım

her biriniz sancılı gecelerde doğdunuz

bir defterin yazılmayan sayfalarıyken

kalem tutmayı bilmeyen eller

kibrit çakıp kül etti hepinizi

elveda emeklerim

siz ki bir sevginin temel taşları

bir ormanın ilk tohumlarıydınız

suya çizilen resim gibi

yalnızca çizenin gözlerinde kaldınız

güle güle sevgilerim

yaşamaya sevdalanmayan bir yüreğin

sevdalanmayacağını bir çiçeğe

öpemeyeceğini bir çocuğu göğsüne bastırıp

öğrendim, koparılarak yeni çiçeklenen dallarım

sakın ağlama gözlerim

düşlerin ağlayacak nasılsa gecelerde

o adam dönmeyecek sürgünden

dağ olup dikildi çirkinlikleri dünyanın

ona geçit vermeyecekler', 'Olmaz diyorduk, oldu işte çaldı ayrılık kapımızı çaldı ve alıp götürdü titremeleri ve o anlık ölümleri kara katran gibi kelimeler döküldü gü...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/iste-bu-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'z-EL-z-ELE', 'z-el-z-ele-turkuaz-marmaris-ih6ue', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sallanıyor yer ve sallıyor bizi

uyandıracak mı acaba hepimizi? 

Gece oturması ve gündüz uykusu

bunlar çare mi; deprem korkusu! 

Yürekler sallanmıyor, gönüller uyanmıyor, aynı sarhoşluk ve aymazlık devam.

Bu kadar didaktik olmak istemezdim ama beynimi sıkıştırıp dökülüyor kelam. 

-Aç bakalım Semra Hanım eski kocasına dönecek miymiş? 

-Sözde güzellik kraliçesi ama bak meğer ne rüküş şeymiş! 

Bahçede zeytin ağacının dibinde otursan ve düşünsen bir,

o zaman diyeceksin, yaşamak gerek, televizyon neymiş! 

Sallanıyor yeryüzü, uyan ey insan

dünya cennet olacak eğer yaşarsan 

Korkuyla büzülürsen durduğun yerde

ve saklanırsan popüler olan şeylerde

görememek var cennet yeryüzünü

ama bil ki O unutmaz sözünü! 

(z)  EL (z)  ELE', 'Sallanıyor yer ve sallıyor bizi uyandıracak mı acaba hepimizi?  Gece oturması ve gündüz uykusu bunlar çare mi; deprem korkusu!  Yürekler sal...', ARRAY['Türk Edebiyatı','Şiir','Turkuaz Marmaris']::text[], 8.5, '{"poet":"Turkuaz Marmaris","poet_slug":"turkuaz-marmaris","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/z-el-z-ele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anneden Oğluna', 'bir-anneden-ogluna-dilek-ozdemir-gpsm0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önünde birbiri ardına yol kavşakları

seçimlerinin toplamı olacak hayatın

olmasa da merdivenin son basamağı

çık ve ara, mutlaka yükseleceksin

Sokaklarda yapayalnız dolaşan

kimliksiz kalabalıklarda kaybolma

kötürümleşir her gün yaşamın

eğer hayallerine sadık kalmazsan

Korkma sorular sormaktan

en çok da sorgula kendini

bil ki sorularınla sileceksin

seni senden ayıran çizgiyi

Ve kaçma hiçbir zaman

yaralansa da şarkıların

yüreğinin dışında

olmasın başka kalkanın

Nerde karanlık varsa

ışığa dön hemen yüzünü

ve içinde taşı her zaman

güneşin ısıtan sıcaklığını

Aşkı yaşamaktır kendini bulmak

aşkı anlamalı, aşkla nefes almalısın

kaçmaya kalkarsan yüreğinden

ruhunu yitirecektir yaşamın

Gözyaşı dökmekten utanma asla

yeter ki her gözyaşı damlasında

çoğalttığın bir şeylerin olsun

yeter ki bilesin direncini gözyaşın

Varacağın son noktada göreceksin

yalnızca kendi benliğinin olduğunu

hayatının bütün savaşları boyunca

yakalayabileceğin en büyük avın', 'Önünde birbiri ardına yol kavşakları seçimlerinin toplamı olacak hayatın olmasa da merdivenin son basamağı çık ve ara, mutlaka yükseleceksin...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-anneden-ogluna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Karanfil', 'beyaz-karanfil-dilek-ozdemir-jmfxx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşı kaçtı, otuz ya da elli

Yaprakları ölümyaralı olsa da

Yüreği inceden serseri

Ve elleri hep yumuşak

Göç sonrası yeni başlangıçlarda

İçinde bir kıpırtı bir coşku

Sanki eski bayramyeri çocuğu

Kirletilmemiş gözleri

O beyaz karanfil

Bir yarıgece anısıdır şimdi', 'Yaşı kaçtı, otuz ya da elli Yaprakları ölümyaralı olsa da Yüreği inceden serseri Ve elleri hep yumuşak Göç sonrası yeni başlangıçlarda İçind...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beyaz-karanfil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğu Yitik Kadının Hikayesi', 'cocuklugu-yitik-kadinin-hikayesi-dilek-ozdemir-p1n9m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hadi git, git anlat içindeki korkuya

Çocukluğu yitik kadının hikayesini

Küçücük bir yürekken öğrendiğini sevgiyi ve acıyı

Doyamadığına ne ana kucağına ne yar sıcağına

O hep kucak kucak dağıtmak isterken dünyayı

Kendisinden çalmak istediklerini insanların

Ve kimselere duyuramadığını çığlığını

Kaçmak için çirkinliklerle daha çok incinmekten

Ve aramak için karışan ipliklerinin uçlarını

Dağlara çıktığını uzunca bir mevsim

Isıtarak yüreğini ince ince, indiğini düze

Ve meydan okuduğunu sevgisiz bütün tanrılara

Dünyayı her gün yıkıp yenibaştan yaratacak görünse de

Savaştan dönen askerler kadar yorgun olduğunu

Sevdiği sularda sakin dingin uyumakken tek düşü

Hiç indirmediği başının yenilgisini bekleyenlere inat

Koştuğunu bütün zamanlarda ölüm gibi doludizgin

Fersah fersah yol gittiğini sevgiyi ararken

Kimsenin çizemeyeceği bir resmini çizdiğini senin

Sevgisinin nasıl idam ettiğini dağ gibi gururunu

Nasıl kürek çektiğini senin fırtınalı okyanusunda

Ve sen hangi sularda boğuyorsun sevgisini

Hadi git, git anlat içindeki korkuya

Çocukluğu yitik kadının hikayesini.', 'Hadi git, git anlat içindeki korkuya Çocukluğu yitik kadının hikayesini Küçücük bir yürekken öğrendiğini sevgiyi ve acıyı Doyamadığına ne an...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cocuklugu-yitik-kadinin-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir misin', 'bilir-misin-dilek-ozdemir-d26qr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilir misin özlemeyi

bir bomba patlarken ötede

bir can düşerken yanıbaşında

düşer ya askerin aklına sıla

nazlı yari, topak bebesi geçiverir ya gözlerinden 

yüreği parçalanıverir ya mermisiz

duyuramaz ya çığlığını kimseye

işte öyle özlemek ne bilir misin

Sen merhabayı bilir misin

üç gün göçük altında kalan bir insanın

yeniden keşfedercesine yaşamı

ölümü yüreğinde taşıyanlara inat

bütün acıları, hüzünleri unutup

rüzgar kadar hür, okyanus kadar coşkulu

gün ışığına merhaba demesini bilir misin

Sevinmek ne bilir misin

günlerce ateşler içinde yatmış çocuğunun

sakin pırıl pırıl sular gibi

açmasını gözlerini, gülümsemesini

anne nasıl seyreder bilir misin

Gel özlediğim yere, merhaba de, sevineyim', 'Bilir misin özlemeyi bir bomba patlarken ötede bir can düşerken yanıbaşında düşer ya askerin aklına sıla nazlı yari, topak bebesi geçiverir ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bilir-misin-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç Öldün mü', 'sen-hic-oldun-mu-dilek-ozdemir-18cfs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen hiç aşık oldun mu

bir oyuncağa çocukken

ve tattın mı

elinden düşürüp kırmanın acısını

Sen hiç gördün mü 

acısıyla ağlayan bir yaralı yunus

nasıl parçalar kendini

bir teknenin pervanesinde

Sen hiç deli gibi sevdalandın mı

ve ayrıldın mı

Sen hiç öldün mü…', 'Sen hiç aşık oldun mu bir oyuncağa çocukken ve tattın mı elinden düşürüp kırmanın acısını Sen hiç gördün mü  acısıyla ağlayan bir yaralı yun...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-hic-oldun-mu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmeyecegini Biliyorum', 'donmeyecegini-biliyorum-hasan-cam-ezzoy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dönmeyeceğini biliyorum, sensizliği de

yalnızlığa vurdum, vehabet deyim

Dönmeyeceğini biliyorum

Ateşin içinde buz ararcasına

Pes etmedim hayattan, küsmedim asla

Devam ediyorum, tek can dost sigaramla

Bekleyeceğim burada seni

Sensizlik delirtti, acizaneyim şuursuz ca

Sesini rüzğarın uğultusunda aradım

Gözlerini yıldızlarda

Koynumda, kollarımda aradım seni

Ama bulamadım, bulamadım gurbetim

Dönmeyeceğini biliyorum, gözlerim yaşlı

Eskisi gibi, çiçek açmıyor baharlarım

Dönmeyeceğini biliyorum

Kuşların sesini duymuyor kulağım..

Kokusu gelmiyor artık, papatya, güllerin

Günleri unuttu, yılları sayar can yüreğim

Bekleyeceğim burada seni

Kullar ayırsada, ecel hak ayırmaz bizi..

Kabrini gördüm amasyada, Ferhat ile şirinin

Delmişler dağları, bedeli var sevmenin

Naftalin kokusu kefenler, sarsada bedeninİ

Sen, içmdeki beyaz gelinciğimsin gurbetim

20,06,2005,

Ümraniye  İstanbul', 'Dönmeyeceğini biliyorum, sensizliği de yalnızlığa vurdum, vehabet deyim Dönmeyeceğini biliyorum Ateşin içinde buz ararcasına Pes etmedim hay...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/donmeyecegini-biliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Gülüm', 'gozlerin-gulum-dilek-ozdemir-umk5s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerin gülüm

gül yaprağına düşmüş çiğ damlası

yağmurlu gecenin ardından

sabah kokusu

öyle dinlendirici

dışarıda cayır cayır yanarken dünya

pınara ev sahipliği yapan mağaranın

serin derinlikleri

öyle rahatlatıcı

dağın arkasını görmeye and içen son yolcunun

tırmanırken dere tepe yokuş bayır

karlı dağın yapayalnız zirvesine

uzatması donmuş ellerini çıtırdayan odun ateşine

öyle yumuşatıcı

gözlerin gülüm

rengine ihtiyacım olan', 'gözlerin gülüm gül yaprağına düşmüş çiğ damlası yağmurlu gecenin ardından sabah kokusu öyle dinlendirici dışarıda cayır cayır yanarken dünya...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-dilek-ozdemir-dwddd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önce hayalin girdi odama

yüzün karanlıktı ve kimliksizdin

hüznün adını sonbahar koyduğumdan mı ne

hep sonbaharlarda aradım seni sokaklarda

yüzünü bile görmemiştim ama amacımdın

inancımdın insanlardaki güzelliğe

değil mi ki kırdılar mahsun bakışlı fidanları

değil mi ki yıktılar sımsıcak dünyaları

at bindim, kılıç kuşandım, şahlandım

savaşlara girdim savunmak için seni

açlara bir kase çorba sundum adına

susamışlara kaynak suyu içirdim

hiç okşanmamış çocuk başlarını okşadım senin elinle

ve muzaffer askerler gibi gülümsedim sonra sana

çatlayan dudaklarım yumuşadı seni düşündükçe

aydınlandı zindanlarda kaldıkça gözlerim

nefes nefese çıktım bütün merdivenleri senle

şair oldum, şiirler yazdım

seyyah oldum, diyarlar gezdim

el emeğim göz nurumla ince ince nakışladım seni

bir el uzatımı yerdeydin, biliyordum

denizle gecenin buluştuğu yerde 

uzanıp aya dokundum

yüzünle, adınla, kanınla, canınla ordaydın

Sen...Sevgiydin', 'Önce hayalin girdi odama yüzün karanlıktı ve kimliksizdin hüznün adını sonbahar koyduğumdan mı ne hep sonbaharlarda aradım seni sokaklarda y...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevgi-187-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yoksulu Çocuklara Dair', 'sevgi-yoksulu-cocuklara-dair-dilek-ozdemir-ly2hh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kasım başları bir Salı

öldürüldüm dün gece

kimsem yoktu haber verecek

adım unutuluştu

bir öncesi var ölümümün

dillenmeyen bir hikayesi

ben çok önceleri öldürülmüştüm

onikim miydi yoksa onüçüm mü

kanatılırken en çocuk yerlerim

anımsadığım bir şiir vardı

“bir daha hangi ana doğurur bizi”

ellerim intihar etmişti ilkin

ardı sıra gözlerim

sözleri şiirlere bıraktım

dinlemediniz

Ben zaten öldürülmüştüm onsekizimde de

mezardaydım ya bilmezdiniz

kuruydu toprağım

basamaktım gelip geçenlere

her basanla az daha gömülürdüm

suskundum

kendi seçimim değildi suskunluğum 

susturulmuştum

iki teli koparılmış tek telli sazdım

göremediniz

Ben öldürülmüştüm otuzumda da

yürüyüp giden babamın ardından bakarken

tamamlanmıştı zamanım

ve bitirmiştim ölüme ayak diremeleri

yüreğim intihar etmişti o yaz 

kansızdı yüreğimin intiharı

hissetmediniz

Vur emri çıkarmıştınız hakkımda

çığlıktım duyulmayan

ve önce çığlığım yuvarlandı uçurumdan

sonra düşlerim ardı sıra

karışıp yağmur sularına

aktım gittim

fark etmediniz

Daha önceydi yolculuk ya

sevda kesmişti önümü

içimdeki arsız kuşlar

bir şiir yazdırmıştı ellerime

gözlerinde menekşe saklı kadın için

geç kalan aşkın ağlayan geliniydi

sevgi yoksulu çocuklar içindi şarkımız

saklamak istemiştim gözlerini dünyadan

ve karanlık girdi aramıza, sessizlik

söylenememiş ne varsa 

söylemek istemiştim sevgiden yana

gitmeden önce

istemediniz

keşke uyanmasaydım dedim çok sabah

ve uyanmadım

terk ettim şehrinizi

kasım başları bir salı', 'Kasım başları bir Salı öldürüldüm dün gece kimsem yoktu haber verecek adım unutuluştu bir öncesi var ölümümün dillenmeyen bir hikayesi ben ç...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sevgi-yoksulu-cocuklara-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Senin Adın', 'yalnizlik-senin-adin-dilek-ozdemir-qv6it', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerin yanıltmasın seni

gördüklerin etrafında

sisten insan siluetleri

birazdan basınca sıcak

hepsi bir bir dağılacak

yalnızlık senin adın

çünkü yüreğinde yalnızlığın', 'gözlerin yanıltmasın seni gördüklerin etrafında sisten insan siluetleri birazdan basınca sıcak hepsi bir bir dağılacak yalnızlık senin adın ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalnizlik-senin-adin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Sensiz Kalmak', 'sende-sensiz-kalmak-ferhat-eren-mqwzx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sende sensiz kalmak

Güle camdan dokunmak

Pencereden bakmak sokaklara

Boynunu bükmeden iç çekmek

Umutlara sarılıp beklemek yarınları

Özlemleri haykıramamak kumsallarda

Cenneti yüreğinde gizlemek

Güneşi hayal etmek geceleri

Uzaktan bakmak uzaktaki ellerine

Kokunu duymak ama dokunamamak saçlarına

Öyle zor ki umutsuz kalmak

Öyle zor ki bulutlara bakıp dudakları kurumak

Öyle zor ki sende sensiz yaşamak

Öyle zor ki…', 'Sende sensiz kalmak Güle camdan dokunmak Pencereden bakmak sokaklara Boynunu bükmeden iç çekmek Umutlara sarılıp beklemek yarınları Özlemler...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Eren']::text[], 8.5, '{"poet":"Ferhat Eren","poet_slug":"ferhat-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sende-sensiz-kalmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Emriyle Aranan Bir Düş', 'vur-emriyle-aranan-bir-dus-dilek-ozdemir-62j42', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vur emriyle aranan bir düştü gördüğüm

Seslerini duymadan itiş kakış kalabalıkların

Kaçıyorduk dünyadan ardımıza bakmadan

Okyanuslara vuruyorduk kendimizi 

Fırçası oluyordun en insan resmimin

Terzisi oluyordun en aydınlık elbisemin

Yıldızlar yorganımız

Ay ışığı fenerimiz oluyordu

Yeryüzüne bulutlardan bakıyorduk

Serin rüzgarlar okşuyordu bedenlerimizi

En büyülü tütsülerini yakıyordu doğa

Ve biz sarhoş oluyorduk kokularıyla

Çırılçıplak oluyordu yüreklerimiz

Yüreğimizin sıcağıyla güneşi yakıyorduk

Sen bir gerdanlık takıyordun boynuma

Yağmur taneciklerinden yaptığın

Ben mavi gökten bir taç giydiriyordum başına

Kulak kesiliyorduk

Kulak kesilip sessizliğin şarkısını dinliyorduk

Her dalgada kayan kum tanecikleri

Billur suyun en derininde taş oluyorduk

Omuz omuza oluyorduk

Koyun koyuna oluyorduk

Aşk oluyordu

Ölümlüyken son sözümüz', 'Vur emriyle aranan bir düştü gördüğüm Seslerini duymadan itiş kakış kalabalıkların Kaçıyorduk dünyadan ardımıza bakmadan Okyanuslara vuruyor...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/vur-emriyle-aranan-bir-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelmeden Önce', 'sen-gelmeden-once-ufuk-coban-l3zlp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneşe sensizliği anlattım, doğarken yeni güne.

Ne yaptıysam sığdıramadım kelimelere.

Biran önce gelmen için gözlerime,

Dizerdim yollarına, acımasam sana benzeyen güllere.

En son sen gör istedim sözlerimi.

Sadece sen bilirsin sana yazıldığını.

Her zaman karşındayım bazen görmesen de gözlerimi,

Tahmin bile edemezsin, seni ne kadar sevdiğimi.

24-05-2000', 'Güneşe sensizliği anlattım, doğarken yeni güne. Ne yaptıysam sığdıramadım kelimelere. Biran önce gelmen için gözlerime, Dizerdim yollarına, ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-gelmeden-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-ferhat-eren-wg299', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çiseleyen yağmur, damlaların soğutmuyor yüreğimi,

Sağanaklarını gönder, ruhumun korlarını serinletsin.

Yanmasın hasret,

Tutuşmasın özlem,

Kara kömürler olmasın bahtım.

Kalbimin vuruşları bastırıyor gök gürültülerini,

Beynimde çakan şimşekler sesin,

Fırtınaların değil geceyi yırtan,

Yüreğimdeki sevdayı kaldırım taşlarına gizledim adım adım.

Özlemlere, sabırlara anlam oldu adım.

Bir yıldız kaydı yine uçtu gitti.

Acelesi vardı kavuşmak için uzaklarına.

Aynı dilekleri tuttum bildiğin,

Kabul olacakmış gibi umutlandım.

Özenle okudum bütün duaları, bildiğim…

Taşlaşmış kalpler gördüm çöl kayaları gibi.

Dibinde çiçekler açmayan,

Menfaatlere kul olmuş.

Sevgiden nasipsiz,.

Ürkek ve sessiz dökülüşünü güçsüzlük  zannedip,

Kendini bentlerden güçlü görmüş vicdanla.r

Yarınlarda sel oluşunu görünce ne de küçük olacaklar…

Bırak gözyaşları bilsinler yüzümde bıraktığın izleri,

Dağa çıkınca dağdan büyük zanneder kendini ahmaklar.

Çiçekleri yenecek ot gibi görür sesleri yüksen çıkan yaratık.

Sen sula ki yeşersin yeniden baharların,

Büyüsün,  yüreklere ekilen sevgi tohumlarımız.

Büyüsün ki umut olsun yarınlarımız…', 'Çiseleyen yağmur, damlaların soğutmuyor yüreğimi, Sağanaklarını gönder, ruhumun korlarını serinletsin. Yanmasın hasret, Tutuşmasın özlem, Ka...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Eren']::text[], 8.5, '{"poet":"Ferhat Eren","poet_slug":"ferhat-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yagmur-192-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölünecek Şehir', 'olunecek-sehir-dilek-ozdemir-42fmy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölmeye geldim bu şehre

dağlarının, dağlarının

deniz kokan sevdasında

dünyayı sevmeye geldim

Çıkarım zirvelerine

kuşların kanadında

bir sen yoksun yanımda gülüm 

bir de son bir sigara

Gökyüzünü serin üstüme

ırmağında yıkayın beni

toprağı taşı mezarım

yeşili kefenim olsun

Dağlarının dağlarının

deniz kokan sevdasında

yanımda bir sen, bir de son bir sigara

ölmeye geldim bu şehre', 'Ölmeye geldim bu şehre dağlarının, dağlarının deniz kokan sevdasında dünyayı sevmeye geldim Çıkarım zirvelerine kuşların kanadında bir sen y...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olunecek-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bir İsim Koy Diyorsun', 'bana-bir-i-sim-koy-diyorsun-dilek-ozdemir-39a8p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana bir isim koy diyorsun

kırılmışlık diyorum

alabildiğine büyük, derin ve geniş

bir kristal küreyken

paramparça olmaksın sen

Bana bir isim koy diyorsun

yalnızlık diyorum

kalabalıkların en ortasında

kendini paylaşacak

bir kendin bile bulamamaksın sen

Bana bir isim koy diyorsun

kaçaklık diyorum

yüreğin dökülüverir ortaya diye

dünyanın bütün güzelliklerinden

diyar diyar kaçmaksın sen

Bana bir isim koy diyorsun

karanfil diyorum

bir yudum suya hasret ölürken bile

tek yaprağını düşürmeyen

beyaz karanfilsin sen

Bana bir isim koy diyorsun

sevdiğimsin diyorum', 'Bana bir isim koy diyorsun kırılmışlık diyorum alabildiğine büyük, derin ve geniş bir kristal küreyken paramparça olmaksın sen Bana bir isim...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bana-bir-isim-koy-diyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgu', 'sorgu-dilek-ozdemir-qaht2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yüzünün çizgilerini yazmıştım duvarlarıma

saçlarının kırını

her telinde bin acı nakışlanmıştı

yağmur değmişti yüzüne

gözlerin paramparça elmastı

boyutlamalıyım bu gece

yanlış fırça darbelerini

ve ahreti sorgulamalıyım

sigaramı önce filtresinden içer oldum

inkar etmeliyim bu gece bütün filtreleri

gözlerimi yakan uykulardan uyandım

Noel babanın avuntu hediyelerini istemiyorum artık

resimlerini de değiştirdim bütün paralarımın

martı çığlıklarıyla coşan denizin kızını 

inkar etmeliyim

bir konçerto besteledim ağız mızıkamla

umursamıyorum artık hekim tavsiyelerini

bütün azizlere mum yakmalıyım

adaklar adamalıyım kopardığım çiçeklerin ruhuna

dört yapraklı yonca aramaları bıraktım

ama razı değilim iki yapraklısına da

düşlerimin duvarlarını yumruklamaktan yoruldum

gözlerimi kapadım

görmek istemiyorum çirkin yüzleri

reklam panolarından birer birer dökülen

albeni anlamı verdirilmiş sahte gülüşleri

görmek istemiyorum

mavisini ve sarısını ayırıyorum

bütün yeşillerimin

denizine düşen karası

ve ak martıları

ve sokaklarının dumanlı ölümüyle

bu kenti akıtıyorum ellerimden bu gece

tüketiyor ve terk ediyorum

yüreğimi de..

ve sevgimi…

ve sevgilimi…', 'yüzünün çizgilerini yazmıştım duvarlarıma saçlarının kırını her telinde bin acı nakışlanmıştı yağmur değmişti yüzüne gözlerin paramparça elm...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sorgu-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ödedim Borcumu Dünyaya', 'odedim-borcumu-dunyaya-dilek-ozdemir-89ja8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ödedim borcumu dünyaya

bundan sonrası yalnızca benim

yenilmez imparatoruyum artık kendi ülkemin

papatya toplayıp şarkı söyleyen

kırmızı şapkalı kız oldum

farketmedim izleyen gizli gözleri

altında zıpladığım ağacın hemen arkasındaki

en sevgili yerlerde kurulan pusuları

göremedim

ve azgın kurdun kulağını ağzını

ayırt edemedim

midesine inene dek

kayıptı kimliğim

özgürlüğün zindana atılmış haliydim

kurtarıcısını bekleyen tuzaktaki ceylan oldum

işlemedikçe pas tutan vicdanlara

yem olup olmamaktı artık bütün mesele

kah aynanın bu yüzünde

kah öteki yüzündeydim

korktum yalnızca bedelini ödemediğim her şeyden

olmamam gerek dedim

boşlukta dönüp duran çıplak maymunlardan

değiştirmem gerek dedim

insanlığa yakışmayan ne varsa

su taşı deler dedim

sırılsıklam suç kesildim gözlerinde

dediler ki güneşi mi özlüyor gece yarısı

yasaktır bu yerde karanlığın sorgusu

yakın gitsin öyleyse

patladı içimde birikmiş öfkem

boyun eğmedi, diz çökmedi, aman dilemedi

içimdeki karşı ayaklanmalar

cehennem ateşleriyle yıkadım da yüzümü

bir tek çoban yıldızına döktüm içimi

tetikçisini arayan namlu oldum

derken

ceylan sekişli bir aşkın fırtınası

gelip oturdu yüreğime

unutuverdim yaşadığım her şeyi

bahar indi yeryüzüne ve çiçekler kelebekler

başladı dağlarımın karlı zirvelerinde

günahkar diyarların sevişmeler iklimi

gördüm ki düşlerimin çamuru sevgidendi

köprüler kurdum yüreğimin kollarıyla

uçurumların iki yakasına

kutsadım birer birer sevdiğimin söylediği şarkıları

dalları çatırdayan meyveli ağaç

yüzünü güneşe dönen çiçek oldum

ödedim borcumu dünyaya

bundan sonrası yalnızca benim

yenilmez imparatoruyum artık kendi ülkemin', 'ödedim borcumu dünyaya bundan sonrası yalnızca benim yenilmez imparatoruyum artık kendi ülkemin papatya toplayıp şarkı söyleyen kırmızı şapk...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/odedim-borcumu-dunyaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağlıcakla', 'saglicakla-dilek-ozdemir-dc8xk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzünlerle eskidik burada, yalanlarla

ekmekle sevgi, gerçekle düş arasında

göz pınarlarımızdan suladık da başakları

deniz bile kara oldu nasıl olduysa

sen neyi kurtaracaksın artık

dağları yol edip kurutacak mısın denizleri

boyayacak mısın yeşile sararan yaprakları

susturacak mısın gürültüsünü dünyanın

tutup silecek misin bir çocuğun beynini

sen ölünecek şehir

sana düşlerimi bırakıyorum

sağlıcakla…', 'Hüzünlerle eskidik burada, yalanlarla ekmekle sevgi, gerçekle düş arasında göz pınarlarımızdan suladık da başakları deniz bile kara oldu nas...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/saglicakla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pervanenin Öyküsü', 'pervanenin-oykusu-dilek-ozdemir-wkta8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'mumun etrafında delice döndü

ve ateşe saldı kendini pervane

ateş buğuya dönüştü

kanadına kan damlamış bir kuş

gökleri delip yıldızlara erişti

didikleyerek dünyanın her bir yerini

sıçradı son noktadan ve bağırdı

sonsuzluk yankılandı sesiyle

hüzünlü bulutları hıçkırdı kentlerin

bulut suya dönüştü

toprak serildi önüne

güze, doğurgan, tavında bir kadın gibi

kumsal uyanacak az sonra

güneş parladıkça kumsal ısınacak

yalnızca çıplak ayaklar hissedecek sıcaklığı

yalnızca çıplak ayaklar

su ateşe dönüşecek

bekliyorum sevgili

hasat edip koklayacağız birlikte 

dünyanın bütün çiçeklerini', 'mumun etrafında delice döndü ve ateşe saldı kendini pervane ateş buğuya dönüştü kanadına kan damlamış bir kuş gökleri delip yıldızlara erişt...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/pervanenin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mülteci', 'multeci-dilek-ozdemir-ysi32', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ülkemin sınırları dışına hapsolmuşum

mülteciyim

görüş günlerinden yoksun

on yıl geçti, görüşüme gel dostum

Çiçekleri getir bana ülkemden

körfezinin kokusunu avuçla kentimin

doldur ceplerine

bir de martı tut kanadı denizime değmiş olsun

daha da eskidi mi eski sokakların kırık taşları

al bir tane yanına

Bir kır kahvesi vardı salaş, bakımsız

o bulanık çayından bir bardak doldurt bana

dikkat et soğumasın yollarda

balıkçı barınaklarından bir tahta kopar

getir benim için

bir vak sesi koy çantana

köylerimin çamurlu yollarında gezinen

türkülerimi getir

sazımın üç tellik kavgasından

imzalar getir dostlarımdan

rakı sofrasını unutma, balıklı

bir de Bafra cıgarası olsun yanında mutlaka

ateşi tırnak yakana dek içtiğimiz yıllardan

yılları taşı bana

hala rötarla mı kalkıyor 8.20 treni

Pasaport kahvesi çalışıyor mu hala

ülkemi getir bana

Yürekler de olmalı valizinde

insan olma kavgasında daha yenilmemiş

bir arkadaşın kurşun yarasını al sol eline

işkenceden kalan bir direnişi koy yanına da

çığlıklar getir savruluşlardan

ihanetler de var değil mi, onlar kalsın

kara leke almamış alınları isterim

Anamdan bir ninni

bacımın saçından bir tel

babamdansa bir öğüt koy, boş kalmasın yerleri

bir de, bir de unutma, kendini

kucaklayayım ülkemi senle', 'Ülkemin sınırları dışına hapsolmuşum mülteciyim görüş günlerinden yoksun on yıl geçti, görüşüme gel dostum Çiçekleri getir bana ülkemden kör...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/multeci-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz Diyorum', 'olmaz-diyorum-dilek-ozdemir-73fql', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeryüzüne dönüyorsun yüzünü

emekçinin alın teri

varoşların tozlu yolu oluyorsun

caddeler utanıyor sen yürüdükçe

kanadı kırık insanların cesareti

çaresizlerin ümidi oluyorsun

nereye gitsen bir yangına düşüyorsun

önce buğulanıyor gözlerin

sonra çakmak çakmak oluyor

ürküyor kurtlar ve solucanlar

bitmeli diyorsun bu rezillik

kader değil beşinci sınıf yaşamak

her sabah güneşle yükselip

yeni bir dünya resmi yapıyorsun

kükrüyorsun parçalarken

üç öğün insanla beslenenleri

olmaz diyorum

olmaz

kavga böyle yakışır mı insana

Gökyüzüne dönüyorsun yüzünü

yorgun şehre inen dumanlı gecede

aydınlığı çiziyorsun gökyüzüne

samanyolunun tutkunu oluyorsun

rakı bardağının yoldaşı oluyorsun

içinin kumrularını salıveriyorsun

bir şarkı tutturuyor serseri yüreğin

nihavent, hicaz ya da mahur

sesinin rengine düşüyor sevdalar ve acılar

ve menekşeler yaseminler

yüreğinin yalnızlığı yoksullaşıyor

ırmak olup çağlıyorsun

çoğalıyorsun

çoğaldıkça çoğaltıyorsun

ateşe veriyorsun buz rengi gönülleri

günahkar yanların canlanıyor

açıyorsun gözlerinin kelepçelerini

bir gül şenliği başlıyor

dalmışken gözlerinin gül bahçelerine

suçüstü yakalanıyorum

utanıyorum

utanç kesiliyorum

susuyorum

suskunluğumla söylüyorum

olmaz diyorum

olmaz

görmedim böylesini

Bana dönüyorsun yüzünü

gülüyorsun

bir başka oluyorsun gülerken

Akdeniz’in zümrütü oluyorsun

dağlarımda kardelen oluyorsun

bir başka oluyorsun 

ve sümbül çiçeği doluyor ansızın

deniz kokusuna

toprak kokusuna

ve senin kokuna hasret burnuma

çok hissedip az düşünüyorum o anda

kapatıp gözlerimi

uzanan ellerine uzanıyorum

nasıl oluyorsa dokunduğun anda

şimşekler çakıyor ve fırtınalar

yükseliyoruz, çok, pek çok

5846 metre kadar

görünmez oluyor insanlar ve kurtlar ve solucanlar

savruluyoruz

adlarımız neydi bilmiyoruz

bildiğimiz iki kelime kalıyor

biri insan, sevgi diğeri

korkuyorsun

korkup titriyorsun

bu kadar az şey bilmekten

aslında bu kadar az şeyin anlatmasından

şimdiye kadar çok bildiğin her şeyin hepsini

ellerini çekip almak istiyorsun ellerimden

olmaz diyorum,

olmaz, yapma

olmaz ki fırtınanın dümeni', 'Yeryüzüne dönüyorsun yüzünü emekçinin alın teri varoşların tozlu yolu oluyorsun caddeler utanıyor sen yürüdükçe kanadı kırık insanların cesa...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/olmaz-diyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bilebilir ki', 'kim-bilebilir-ki-dilek-ozdemir-s4yvh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kim bilebilir ki

yarın gün ışığı ne armağanlar getirecek

hangi kuşlar konacak şu asırlık çınarın dallarına

hangi yıldız kayacak gökyüzünden

kaç aşk başlayacak, kaçı bitecek

ne düşler görecek gözlerim bu gece

ve sabah hangi renklerle açılacaklar

biri özlediğim yerde merhaba diyecek sevincime

imrendiğim dağların yamaçlarına tırmanacağım belki

kim bilebilir ki

Bu akşam sarhoş olmak istiyor canım

hala nefes alabilmenin şerefine

doldurun kadehlerimi ardı ardına

ölümle tanışmadım ya O’ndan önce

ya tek satırım olmasaydı sevgi üstüne

bir şişe daha aç reis

kaldıracağım yaşanabilen her güzelliğe', 'Kim bilebilir ki yarın gün ışığı ne armağanlar getirecek hangi kuşlar konacak şu asırlık çınarın dallarına hangi yıldız kayacak gökyüzünden ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kim-bilebilir-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyümek', 'buyumek-dilek-ozdemir-euf2h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen mi erken gittin

Ben mi geç kaldım anlamakta seni

Yaşamadan öğrenmek

Kaybetmeden anlamakmış büyümek', 'Sen mi erken gittin Ben mi geç kaldım anlamakta seni Yaşamadan öğrenmek Kaybetmeden anlamakmış büyümek...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/buyumek-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heyy Sen! Burjuva Çocuğu', 'heyy-sen-burjuva-cocugu-mustafa-dogan-kuzgun-36ff0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İzmarit taşıyan ellerin, barut kokusunu bilir mi,

Tadına varabildin mi namert mayınların,

Ya da taşımak zorunda kaldın mı kopan bacağını,

Alnından akan kanlara karıştımı terin.

Acıyı bilirmisin sen,

Yüreği yanmış anaların ağıt yaktığı...

Soluğun kesildimi hiç; 

Kaçarken pusu kurmuş, yosma bileklerden...

Davanın uğruna vuruldun mu,

Haykırırken düşüncelerini coplandın mı,

Örümcek kafalıları alt ederken beynin,

Serin bir şafak asıldın mı hiç?', 'İzmarit taşıyan ellerin, barut kokusunu bilir mi, Tadına varabildin mi namert mayınların, Ya da taşımak zorunda kaldın mı kopan bacağını, Al...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/heyy-sen-burjuva-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sabah Vakti', 'bir-sabah-vakti-dilek-ozdemir-lnaiw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sevdalandım bir sabah vakti

laciverde dönerken karanlık

ve karanlığın içinden gülümserken 

bana benziyordu ay

ve karlı zirvelerden koşup gelmiş

soğuk rüzgar ısıtırken yürekleri

bana benziyordu

ay ve rüzgar bana benzerken

sevdalandım bir sabah vakti', 'sevdalandım bir sabah vakti laciverde dönerken karanlık ve karanlığın içinden gülümserken  bana benziyordu ay ve karlı zirvelerden koşup gel...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-sabah-vakti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmezler', 'bilmezler-dilek-ozdemir-f1jn6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sormazlar onlar sevdamızı

ne ellerimizde doğan güneşlere

ne sarı sıcak başak gülüşlerine

ne kır çiçeklerinin türküsüne

sormazlar

Duymazlar onlar

çığıl çığıl akan su seslerini

ince sazın rengarenk notalarını

ağlayan çağlayanın gözyaşlarını

görmezler

Bilmezler onlar

nelere yetmez içimizdeki sevda

nasıl yazılır tek hecesiz destanlar

nasıl yaşanır dünyanın ötesinde

ve nasıl uçulur kuşlar gibi ölüme

bilmezler', 'Sormazlar onlar sevdamızı ne ellerimizde doğan güneşlere ne sarı sıcak başak gülüşlerine ne kır çiçeklerinin türküsüne sormazlar Duymazlar o...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmezler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cayo erguvan dökerdi saçlarına / 1', 'cayo-erguvan-dokerdi-saclarina-1-zafer-zengin-etnika-jcqic', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cayo erguvan dökerdi saçlarına

  Ondan adı cayo hala

  | Uzun bekleyiş |

  Örmüş gün kırmızıyı

  Uzun örtüler içinde

  Rüzgar dönerken

  Ses geldi elim

  Sustum

  Bağrı bilinmez yaralar

  Bilemedim neydi

  Etimi kemiğimden ayıran

  Sana el vermiş demir

 Keser yaradan yaradan

| sırtını dönüp gidişinden teslimiyetimi imzalamış

ve bir erkek kendini bu kırarken ademden

ve havvadan gayrı hiç sızı kalmadı..

herkes göğünü mavi özleyen insandır.

Kafasında değil içinde arzulayandır..

sıyrıl gururundan iç''in kopmadan | 

 Yanık ellere gül sürüp

  Canım içi yangınlar çıkarıp

  Hazan demeden

  Yürek yakan

  Can koparan

  Sen

  O ses

  Kes gülümü gayrı

  Sana büyüttüm

| göz yaşı  hokka ıstalan kanken.. isten kuleler yaptık

sen sızı saydın..  kaçmazdın kaçamazdın 

etini kendine doyuran celep 

nazik yerinden..  memenden kesip oğul tadı vermedi

biz sana çocuklar ısmarladık 

sen kundak dedin biz çaputlara sardık.. 

kefen habercisi ayrılığın.

şu alnımıza sürdüğün elinle gözlerimizi kapayıp.. 

onlara efendilere baktık

biz insandık anlatamadık ve lanetler okuduk çocuklarına..

çocuklarının yollarına 

ve cayo sana gün veremediysek direnmediğimizden değil..

istenmediğindendi

senin gibi binler kaybettik onların yoluna 

kurban ettik.. alınların öpüp isimlerini yazdık kağıda

kağıdın olmadı yerde çaputa.. o da yoksa taş dikip

başlarına toprağa.. 

şimdi gel öğrensin efendiler.. insan kinsiz ne eder |

  Süzülüp kendi kanadına

  Beyaz güvercin yapıştığında

  Sana yolladık canımızı da

  Sahip çık

  Ağlatma

  Her güvercin

  Senden haberci nasılsa

  Kanadı beyaz olmasa da

  Kırmızı gördükçe

  Bizi hatırla

  Ağrım var ya cayo

  Şu ağrım

  Hep sana anlattığım

  Yarım hayat cayo

  Hala yarım 

  Yarımdan da yakın

  Cayo susacağım

  Kalacağım

  Yarın

  Yarıma yakın

10.01.2005', 'Cayo erguvan dökerdi saçlarına   Ondan adı cayo hala   | Uzun bekleyiş |   Örmüş gün kırmızıyı   Uzun örtüler içinde   Rüzgar dönerken   Ses...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/cayo-erguvan-dokerdi-saclarina-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-dilek-ozdemir-kemfp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aklım almıyor hala gidişini

dün müydü bin yıl mı oldu yoksa

anlayamadım gülüm

sınırsız sanırdım yüreğimi

ama sığmıyor acın yüreğime

sığdıramadım gülüm

bir boşluk ki geride kalan

dolmuyor hiçbir şeyle

dolduramadım gülüm

maskemi takıyorum da ara sıra 

uymuyor üzerime dikilen elbiseler

uyduramadım gülüm

biliyor musun pes etmedim hala

ama yine de diyorum ki bazen

acaba gelsem mi yanına', 'aklım almıyor hala gidişini dün müydü bin yıl mı oldu yoksa anlayamadım gülüm sınırsız sanırdım yüreğimi ama sığmıyor acın yüreğime sığdıram...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gulum-138-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bakımlık Konuk geldim Sana', 'bir-bakimlik-konuk-geldim-sana-dilek-ozdemir-fjleo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bakımlık konuk geldim sana

Mühürlesin gözlerimi gözlerin

Bir tutumluk ver elini 

Bir kez kucakla yürekten

Ve sağlıcakla kal ebediyen

Sen iyi ol yeter ki 

Yağmurda kalmasın gözlerim', 'Bir bakımlık konuk geldim sana Mühürlesin gözlerimi gözlerin Bir tutumluk ver elini  Bir kez kucakla yürekten Ve sağlıcakla kal ebediyen Sen...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-bakimlik-konuk-geldim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşgal', 'i-sgal-dilek-ozdemir-5ddhm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gerçeğimiz işgal altında 

silahlandırın dizeleri

bir ekmek parasına düştü bedenler

insan olan alınlarda bir kara leke şimdi

Düşlerimiz işgal altında 

silahlandırın dizeleri

ipe çekiliyor bütün renkler

dünya siyah beyaz film gibi

Gençliğimiz işgal altında 

silahlandırın dizeleri

kol geziyor korkuyla beyin yıkama

adına eğitim dedikleri

Aşklarımız işgal altında 

silahlandırın dizeleri

sıfır noktasında yürek titremeleri

esintisiz mevsimde kuru bozkır sanki

İnsanımız işgal altında 

silahlandırın dizeleri', 'Gerçeğimiz işgal altında  silahlandırın dizeleri bir ekmek parasına düştü bedenler insan olan alınlarda bir kara leke şimdi Düşlerimiz işgal...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/isgal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Yazık', 'cok-yazik-dilek-ozdemir-1142p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öte yüzündesin madalyonun

görünen hiçbir yerde değilsin

dağın öte yamacında

denizin öte yakasında

ne dokunmak mümkün sana

ne içmek pınarından bir yudum

Ebedi yalnızlığına yenildim senin

Yazık…

Çok yazık…', 'Öte yüzündesin madalyonun görünen hiçbir yerde değilsin dağın öte yamacında denizin öte yakasında ne dokunmak mümkün sana ne içmek pınarında...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cok-yazik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Bahar Var', 'kac-bahar-var-dilek-ozdemir-2kcem', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 've oysa ki tanıktı gökteki ay

suyun sesi ışıklıydı

yarıgecenin yumuşacıktı güzelliği

uzakta kentin ışıkları yanarken

dokundu gözler yüreklere

ibadet eder gibiydi bedenler

buram buram yürek koktu da gece

ulaştık da evrenin renk cümbüşüne

söylenemeyen sözler çöktü araya kurşun gibi

suskular ağı sardı birden dilleri

buzullara gömüldü ateşten gözler

eller kelepçelendi

aysızdı artık gece

ve ben silahsızdım

kan kadar kırmızıyken hüzün

muska yapıp taktılar karanlığı sol göğsüme

taktılar ya bilirim

çocuklar da karanlıkta büyür ana rahminde

bir de bilsem kaç bahar daha var yaşanacak', 've oysa ki tanıktı gökteki ay suyun sesi ışıklıydı yarıgecenin yumuşacıktı güzelliği uzakta kentin ışıkları yanarken dokundu gözler yürekler...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kac-bahar-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-dilek-ozdemir-xbntz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sür arabacı atını

ardıma dönüp bakmadan

terk etmeliyim bu anılar tapınağını

ardıma dönüp bir baksam

saçlarımı görürüm, simsiyah

kutsal rüzgarlarla dağıtıp

avuç avuç bir sevdada bıraktığım

insanlar görürüm kaybetmiş

mezarı üzerine oynadığı kumarı

ve bilir misin arabacı bu kentte

ölümlerin en uzunu yaşanır

yorgun martıları görürüm ardımda

tutsaktır martıların en beyazı da

duyarsız bulanık sularda

kırıntı doyumlara mahkum

sevgilimi ve her şeyimi görürüm

sür arabacı hızlı sür

terk edebilmek de cesarettir biraz

günü gelince doğurduğun çocukları', 'Sür arabacı atını ardıma dönüp bakmadan terk etmeliyim bu anılar tapınağını ardıma dönüp bir baksam saçlarımı görürüm, simsiyah kutsal rüzga...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kacis-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanın Kendine Ettiğini', 'i-nsanin-kendine-ettigini-dilek-ozdemir-1941j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yanındaki boşluğu

yüreğindeki sevdayla dolduramayana

ne kötü

tırmanacak bir yamaç

konacak bir dal bulamayana

ne yazık

yaşamaktan vazgeçip

korkularıyla ölümü bekleyene

ne acı

insanın kendine ettiğini…', 'yanındaki boşluğu yüreğindeki sevdayla dolduramayana ne kötü tırmanacak bir yamaç konacak bir dal bulamayana ne yazık yaşamaktan vazgeçip ko...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/insanin-kendine-ettigini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşkiya Çocuk', 'eskiya-cocuk-dilek-ozdemir-nkisk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatını beşikte yitiren

Sen eşkiya çocuk

Biliyorum eksik kalan 

Bir şeyler var hayatında

Yaşamdan yana

Sevgiden  yana

İnsandan yana

Yaralıdır uykuların

Yalnız ve tek başına

Neler yaşadığını sorsalar

Gözlerin acımasız bakar

Ve yırtıcı kuşlar gibi anlatırsın

Yalnızlığın korkunç yüzünü

Düşlerin avuçlarında

Büyüyor içindeki boşluk

Korkma çocuk korkma

Güneş var arkamızda', 'Hayatını beşikte yitiren Sen eşkiya çocuk Biliyorum eksik kalan  Bir şeyler var hayatında Yaşamdan yana Sevgiden  yana İnsandan yana Yaralıd...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/eskiya-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğmanın Mümkünü Yok', 'dogmanin-mumkunu-yok-dilek-ozdemir-vg3ow', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gidiyorsun bebeğim gitmelisin

sevgim yetmiyor seni dünyaya çağırmaya

öyle çok ön şartı var ki yaşamanın

ve öyle zor ki yaşamak

korkuyorum bebeğim

kıran kırana bir koşu yaşam, acımasız

her gün bir can düşüyor, düşürülüyor

insanlar sevgisiz

riya var bu sürüde, yalan ve açlık var

işkence ve haksızlık

ve ihanet var

bir de aşk var

sevmek var bu küfürbaz dünyada

hep soğukları taşıyor rüzgarlar

alışacaksın

araya karışıp süzülüverecek bir küçücük sıcaklık

hissedeceksin

bedeninle, yaşamınla kavrulacaksın

yaşamanın sevmek olduğunu öğreneceksin

çiçeklerin sesini duyabilmeyi

yüreğini bir sevinç türküsü saracak

koyacaksın ortaya

ve türkün susturulacak

ve kaybedeceksin yüreğinde yaşamayı

bir kez daha yaşamak için sevecek

bir kez daha sevmek için acı çekeceksin

bir garip sofra bu dünya

yiyip tüketecekler ve kenara çekilip

“bu yürek senin, kalanları sen topla” diyecekler

kalemler kırılacak tereddütsüz

bin hançer saplayacaklar bir anda sol göğsüne

sevgiyle yaratmışken seni

nasıl mahkum ederim sevgisizliğe

nasıl veririm bunca acıyı 

şekere bulayarak mama niyetine

sana doğmadan ölümü öğütlüyorum bebeğim

doğmanın mümkünü yok

gecenin ışığına çağırabilsem seni

gizlice, sen ve ben elele

koşabilsek dünyanın ötesine

bitimsiz sevgilerle kucaklaşsak

yeleleri taranmamış kanatlı bir kısrağa binip

doludizgin rüzgarla yarışsak

denizlere kafa tutup

fırtınalara meydan okusak

bütün renklerini ve seslerini değiştirsek dünyanın

korkunun dişlerini köreltebilsek

gece sessiz ve yorgun uykusunda

uykular bana tuzak hazırlıyor

bu gözler ne düşler görüyor

anlatabilsem

buğulu aynalarda görüntünü arıyorum

ölümden bir önceki anda

şafağı bekliyorum bebeğim

bağrıma basamadan, doyamadan sevgine

sabahı çınlatan ışıkla gideceksin

dayanamam diye gidişine

uyutacaklar beni

ne sen,

ne ben,

ağlayamayacağız bile ayrılırken

kanlı gözlerin kir diye akacak plastik eldivenlerden

acın yüreğimi buruyor bebeğim

ölümden önceki son ürpertinle sarsılıyorum

çekip aldılar seni benden

ellerim çıplak kaldı

gidiyorsun, elveda bebeğim

korlara basıyorum, ayağım üşüyor

kuşların cıvıltısında gülüşünü duyuyorum

ve her gülüşün bir yanımı acıtıyor

arada bir düşlerime uğra

yüzünü göster bana

seni öpüyorum bebeğim

seni seviyorum….', 'gidiyorsun bebeğim gitmelisin sevgim yetmiyor seni dünyaya çağırmaya öyle çok ön şartı var ki yaşamanın ve öyle zor ki yaşamak korkuyorum be...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/dogmanin-mumkunu-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çift Söz', 'bir-cift-soz-dilek-ozdemir-9hyah', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir çift sözüm var dostlar söylenecek

bölüşecek bir somun ekmeğim

durma orda yapayalnız

soğuktan uyuşmuş düşlerinle

hayat önünde insanoğlu

feda etme bir anını

hadi ilerle

eğilip su içilsin diyedir kaynak

ekilip biçilsin diyedir toprak

ve özgürce yaşansın diyedir hayat

yetsin artık üçüncü mevki yaşamak

bir çaremiz, yaşamaya dadanmak', 'bir çift sözüm var dostlar söylenecek bölüşecek bir somun ekmeğim durma orda yapayalnız soğuktan uyuşmuş düşlerinle hayat önünde insanoğlu f...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-cift-soz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün İş O İlk Yudumda', 'butun-i-s-o-i-lk-yudumda-dilek-ozdemir-mftd7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'istemek ne özgürlüğü

istemek ölesiye

göze alıp her şeyi

inanmak yüreğinle

inanç benimse eğer

benim olur ekmek de

bütün iş o ilk yudumda

bütün iş bir sonraki adımda

ben küçücük bir terzi

dikiyorum hayalimin elbisesini

biliyorum bir gün tadacağım

yudum yudum soğuyan terimi

bütün iş o ilk yudumda

bütün iş bir sonraki adımda', 'istemek ne özgürlüğü istemek ölesiye göze alıp her şeyi inanmak yüreğinle inanç benimse eğer benim olur ekmek de bütün iş o ilk yudumda bütü...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/butun-is-o-ilk-yudumda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Bugün Yarın', 'dun-bugun-yarin-dilek-ozdemir-8e7vq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dün Akdeniz kendi mavisindeydi

dağlar özgürlüğümdü dün

rüzgar tenimi okşuyordu ılıkca

ve düşmanım bile insandı

bütün kızlar güzeldi, oğlanlar mert

dün sığamıyordum dünyaya

dün sen yanımdaydın

bugün deniz kan kırmızı

etrafımda dikenli tel Bey dağları

ve rüzgar hasta ediyor adamı

bugün anam bile bana düşman

bugün bütün kızlar fahişe, oğlanlar namert

bugün dünya öyle bir boşluk

ve ben öyle küçücüğüm 

bugün sen yoksun

yarın…

yarın…

yarın dünleri çoğaltacağım.', 'dün Akdeniz kendi mavisindeydi dağlar özgürlüğümdü dün rüzgar tenimi okşuyordu ılıkca ve düşmanım bile insandı bütün kızlar güzeldi, oğlanla...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dun-bugun-yarin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Yasını Tutanlar', 'kendi-yasini-tutanlar-dilek-ozdemir-48bks', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akşamdır

bir avuç ay ışığı solar

barutla karışmış tezek kokusunda

kızıl bir akşamüstü ölür düşlerde

teslim olurken kalem ucunda sözcükler

kardeş olur yüzkaralarıyla acılar

ve kendi yasını tutar şimdi

kendi olma anısını yaşayanlar

Gecedir

eski bir yaradan kopan, kararmış

kan pıhtılarıdır dudaklardan damlayan sözcükler

lekelemiştir bir aşkı

ve bir hayatı

Siyahın saltanatıdır şimdi

bıçakların yüreklerde paslandığı

Denizin mavi öfkesini doldurup yüreğime

erken uyandırırım sabahları

gecenin en karanlık mevsiminde

Sabahtır şimdi

soğuk ve sevgisiz bütün tanrıları öldürürüm

kış ölür, gece ölür genç kanımda

süslerim rengarenk kurdelalarla hayatı

fenerler dönerler asarım

kutlarım yeni doğumları

çocuklara sevdalanırım, sevdalara

Sabahtır ve mavidir dünya', 'Akşamdır bir avuç ay ışığı solar barutla karışmış tezek kokusunda kızıl bir akşamüstü ölür düşlerde teslim olurken kalem ucunda sözcükler ka...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kendi-yasini-tutanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğluma Vasiyet', 'ogluma-vasiyet-dilek-ozdemir-15yys', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaldırımların ıslak aynasında yakalandım

gözlerim ele verdi beni

sokak lambalarının buğulu uğultusu

direkten direğe ihbar etti

ateş rengi levhalara kazılı yalnızlığımda

yüreğimin buzullarını kırmaktı suçum

gerçek suçlu ben miydim soğuk mu

bunu hiç bilemedim oğlum

Dünyayı ışıldatan ateş böceklerinin 

altuni sıcaklığı değmişti buzullarıma

ağızsızdılar

alçacık bir sesle parçaladılar

ve korkuyla zindanlara kapatıldılar

dikenliydi çağrılara taktığım gurur kelepçesi

günlerimi kanatıyor oğlum

sanık da benim mağdur da

hakim de benim savcı da bu davada

bir de savunabilseydim yüreğimi

cezam müebbet olabilir

hatta her an ölebilirim

bir gün beni sen yargılamalısın oğlum

kendi ellerimle kırdığım kalemimin 

kalemini sen kırmalısın

ve sevgiyi yaşamalısın', 'Kaldırımların ıslak aynasında yakalandım gözlerim ele verdi beni sokak lambalarının buğulu uğultusu direkten direğe ihbar etti ateş rengi le...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ogluma-vasiyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarcı', 'mezarci-dilek-ozdemir-9a6jj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğim gömülüydü

geçen günlerin sıradanlığında

ve geceydi

bir odaya girdim

kalabalıktı

elimi her uzattığımda

bir el buldum tutacak

gülümsedim

hepsi gülümsediler

bana ve birbirlerine

sevincimi bir duydum yüreğinde

gözlerim doldu, hüznümü paylaştılar

çelişkiler yoktu burada, mutluydum

kapı açıldı, çıktım

irkiltici bir susku çarptı yüzüme

dünya çarptı

yok olmuşlardı

anladım ki onlar yalnızca görüntüydüler

onlar yalnızca aynalardaki ben’diler

ve kalabalıkların yalnızlığını gömdüm aynalı odaya

Susadım

denize koştum

kana kana içtim

hiç içmemekten daha çok susamışken

ağaçlar, çayırlar, dağlar yürüdü denizin üstüne

gece yürüdü en zifiri haliyle

içtiğim sular kurudu

ve susuzluğumu gömdüm denizlere

Bin yıl öncesine gittim Rodrigo’yla

spikerlerin ürkütücü seslerine gittim

ağzı kanlı gazete sayfalarındaydım

tutsaklık korkusu ile düşüp yollara

ülkelerin suskun kentlerine dağılan canlara

ve aşklara

ve ayrılıklara

haykırdım, dudaklarım kıpırdamadı

yolun tam ortasındaydım

ve yürüdüm

ve korkularımı gömdüm dikenli gerçeklere

Bir tutuklu daha adım attı özgürlüğe

bir halk daha ayaklandı dünyanın bir yerinde

bir köylünün alın teri damladı toprağa

ve toprak yeşerdi, ekini boy verdi

bir gonca rengini gösterdi çanak yaprakları çatlatarak

okyanusların coşkulu türküsü tüttü

fabrika bacalarından

bir ağlamak yükseldi ilk nefesin bağırtısı

ve yüreğimdeki hıçkırık düğümünü gömdüm

ve hüznümü gömdüm doğumlara

Akrep kaybolduğunda yelkovanın gölgesinde

aşkı tanıdım buçuğa bir kala

doludizgin çiçek kokularıyla

sıcak koynumda ısıtmaktı sırtını

verebilmekti dolu dolu ellerle dünyayı

su olup çeşmelerden akan güzellikti

ağlayan denizin gözyaşlarını görebilmek

ve esintisizlikten 

ve boyutluluktan batmayı göze alarak

boyutsuz sularda fırtınayı aramaktı

bir andı

bir duyumluk insandı

güneşin her bir ışınını yakalayıp

yumak yapıp sarmaktı

inatçı bir kanser hücresiydi

dokundukça büyüyen

büyüdükçe bitiren

coşkuyla çeken gizemli bir girdaptı

ve düşen bir daha çıkamadı

birileri mutlu aşkın olmadığını söylediler

ölümcüldü

ve ölümümü gömdüm parçalanmış bir aşka', 'Yüreğim gömülüydü geçen günlerin sıradanlığında ve geceydi bir odaya girdim kalabalıktı elimi her uzattığımda bir el buldum tutacak gülümsed...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/mezarci-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük Düşleri', 'ozgurluk-dusleri-dilek-ozdemir-z4mna', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kışlardayım nicedir, üşüyorum

geceler bölük pörçük, yoruldum

boşluk yakalıyor yalnızca ellerim

sessizlikler dolduruyorum bardağıma

sessizlik içiyorum yudum yudum

yıldızlar da yok

çocuklarımsa uykularda şimdi

Nicedir kışlardayım

güneşlenmeliyim artık

örebilirim

ve örmeliyim

ışıklardan sımsıcak giysiler

özgürlük düşleri kuruyorum

delicesine özgürlük düşleri

imkansız özgürlük düşleri

bir isyancı çığlığıyla

imkanlı özgürlük düşleri', 'Kışlardayım nicedir, üşüyorum geceler bölük pörçük, yoruldum boşluk yakalıyor yalnızca ellerim sessizlikler dolduruyorum bardağıma sessizlik...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozgurluk-dusleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Adam', 'o-adam-dilek-ozdemir-adzkg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sabitlenmiş bakışları

uzak meçhul bir noktaya

yüzünden okunuyor düş kırıklıkları

ama yine de

değerlerinin bilincinde

mağrur bir Astek reisi gibi

havada biraz bir kaşı', 'sabitlenmiş bakışları uzak meçhul bir noktaya yüzünden okunuyor düş kırıklıkları ama yine de değerlerinin bilincinde mağrur bir Astek reisi ...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/o-adam-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlık', 'pismanlik-dilek-ozdemir-riu9f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dörtnala geçiyor zaman

hep yaşananların pişmanlığıyla

son ne kadar yakın bilinmez

ölümdür bu savaşın tek galibi

bak bir yıldız daha kaydı

belki yarın olmayacak bir daha

yasaktır sorgulaması yatağını ırmağın

yoktur başka adresi

çaresizdir, akacaktır denize

bir şans verip sevgiye

gel, güneşi yakınlaştıralım

her gün eksiliyoruz az daha

acele yaşamak lazım

pişman olmadan yaşanamayanlara', 'dörtnala geçiyor zaman hep yaşananların pişmanlığıyla son ne kadar yakın bilinmez ölümdür bu savaşın tek galibi bak bir yıldız daha kaydı be...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/pismanlik-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-dilek-ozdemir-vv8g8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen; 

rüzgarın özgürlüğünün,

ateşin sıcaklığının,

okyanusun derinliğinin,

çağlayanın akıcılığının,

ekmeğin doyuruculuğunun,

suyun ferahlatıcılığının,

doğanın üretkenliğinin,

boğanın öfkesinin,

kaplanın yırtıcılığının,

kedinin sokulganlığının,

kartalın keskinliğinin,

delinin cesaretinin,

çocukların neşesinin,

volkanın sabrının,

ölümün sessizliğinin,

kışın titretişinin,

yazın bunaltıcılığının,

ilkbaharın umudunun,

sonbaharın hüznünün,

zirvenin yalnızlığının,

müziğin sonsuzluğunun,

yıldızların gizeminin,

ve İNSAN’ın yüreğinin

toplamısın yalnızca.', 'Sen;  rüzgarın özgürlüğünün, ateşin sıcaklığının, okyanusun derinliğinin, çağlayanın akıcılığının, ekmeğin doyuruculuğunun, suyun ferahlatıc...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-578-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yolcu', 'son-yolcu-dilek-ozdemir-o37zy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'olsaydın

dokunsaydın yaralarıma

dokunup kanatsaydın

kanatsaydın da acısaydım

acımla çığlık olsaydım

düşseydim uçurumlara çığlığımla

döne döne savrulup düşseydim

çarpa çarpa duvarlara

sarsıla sarsıla

yıkıla yıkıla dibe vursaydım

kendime gelemeseydim

gözlerim kararsaydı

kara kara olsaydı

başım dönseydi

dönseydi dönseydi

düşünemez olsaydım

öğrenseydim

imkansızın peşindeki 

son yolcu olduğumu', 'olsaydın dokunsaydın yaralarıma dokunup kanatsaydın kanatsaydın da acısaydım acımla çığlık olsaydım düşseydim uçurumlara çığlığımla döne dön...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/son-yolcu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çerçeveli Pencere', 'cerceveli-pencere-ozan-turk-5fund', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Pencerede bir perde

Hep orada 

Kaldırıyorum perdeyi

Bir de ne göreyim gökyüzü yok

Tam yirmi beş çift çerçeve…

Pencerede perde

Açtım baktım ne göreyim

Çerçeve dolu pencere…', 'Pencerede bir perde Hep orada  Kaldırıyorum perdeyi Bir de ne göreyim gökyüzü yok Tam yirmi beş çift çerçeve… Pencerede perde Açtım baktım n...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cerceveli-pencere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz', 'soz-dilek-ozdemir-r16tl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'verilmiş sözüm var doğduğunda

en cesur yerim kırbaçlansa da

sana bırakmak istediğim tek şey

alın teriyle sırılsıklam bir gelecektir oğlum', 'verilmiş sözüm var doğduğunda en cesur yerim kırbaçlansa da sana bırakmak istediğim tek şey alın teriyle sırılsıklam bir gelecektir oğlum...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/soz-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Şehir', 'yeni-bir-sehir-dilek-ozdemir-q11wz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'oynuyor insanlar her yerde

mutlu sanıp kendilerini

sanki hep yürekleriyle sevişirmişler

hep yürekleriyle bakarmışlar denize, dağa

uzanırmışlar ay ışığında kumlara

sevdiği ile boylu boyunca yan yana

bilirmişler insan nedir bu dünyada

mutluymuşlar sanıp kendilerini

köylü güzeli sosyeteye girmiş diye

göbek atıyor insanlar

çevremde gülüyor şehir

bulutun arkasına saklanmış dolunay

kıskanır gibi mehtabı insanlardan

bütün güzelliklerini gizlemiş deniz

sarınmış kara çarşaflara

üstünde gecenin karanlık yorganı

minik ışıklar yakıyor 

kibritçi kız misali

karşımda titriyor şehir

fırtınalı açık denizlere

uzak adaların ıssız sahillerine

gönlüm gibi yol alıyor tekne

her dalgada bir inip bir yükselerek

her saplanışında dalgaya

hep o aynı feryat boğazında

yol alıyor yine de yeni limanlara

deniz kokusu doluyor burnuma

başım dönüyor

ardımda ölüyor şehir

kül tablası medeniyeti geride kaldı

rüzgar savuruyor külümü

ve hızla yakıyor ateşini sigaramın

hızla yol alıyor gece

her gece bir güneşe gebe

sabahta yeni bir şehir', 'oynuyor insanlar her yerde mutlu sanıp kendilerini sanki hep yürekleriyle sevişirmişler hep yürekleriyle bakarmışlar denize, dağa uzanırmışl...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yeni-bir-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Tutsağım Kendi Sevdamda', 'ben-tutsagim-kendi-sevdamda-dilek-ozdemir-8af5v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben tutsağım kendi sevdamda

kirpiklerimin ardında hapsettiğim

gözyaşlarım bir de

öğrenemedim bu sahnede

hangi dildendir çığlık

hangi dildendir isyan, acı ve hıçkırık

tek başıma oynarken oyunumu

hep kaybeden bir yanımla

kendi bildiğini okuyor zaman

karanlığın saltanatında

Herkes yabancı şimdi bana bu şehirde

her şey yabancı

Bir sabah erkenden

güneş öperken alnımdan

çıkıp gitsem bu şehirden

yitip gitsem zaman içinde

bir sen kalırsın ardımda

bir de yüreğimin karlı dağları

bir de gözlerimde

büyük direnişlerin gizli destanı', 'ben tutsağım kendi sevdamda kirpiklerimin ardında hapsettiğim gözyaşlarım bir de öğrenemedim bu sahnede hangi dildendir çığlık hangi dildend...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-tutsagim-kendi-sevdamda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit Geldi', 'vakit-geldi-dilek-ozdemir-9pfuj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vakit geldi

güneş doğacak birazdan

çepeçevre dağlarımın ardından

tam 17 vakit sürdü gece

tam 17 vakit beklendi doğru zaman

karanlıktı yollar, rüzgarlar soğuk

yanımdan geçti insanlar gece boyu

kimi bir kibrit ateşi sundu

kimi bir nefes sıcaklık

iki dudağın arasından

ama geceydi

ve karanlık

ve soğuk

Ezan sesi şahidimdir

gün ışıyacak birazdan

ben sabaha ben olacağım

ve aydınlık

apaydınlık…', 'Vakit geldi güneş doğacak birazdan çepeçevre dağlarımın ardından tam 17 vakit sürdü gece tam 17 vakit beklendi doğru zaman karanlıktı yollar...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/vakit-geldi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-dilek-ozdemir-c31aj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'en eski yanılgısı insanoğlunun

peşindeki ağzı salyalı korkulardan kaçarak

korkusuz yaşayacağını sanmak

oysa nerde korku varsa

orada ölümü vardır ruhun

arkanda bırakırsan korku canavarını

dönmezsen yüzünü yüzüne

bakamazsan taaa gözlerinin içine

ve hesaplaşmazsan

hesaplaşıp gömmezsen tarihine

hapsedersin

kendini içindeki zindanlara

kendi üstüne kendin kapatırsın

aydınlığa açılan bütün kapıları

her gün kurşuna dizilir yüreğin

her kurşunla oyulur içinde bin mağara

ve her mağarada kör bir yarasa

katleder bütün yeni başlangıçlarını

gömülürsün diri diri dibi zifiri bir kör kuyuya

kulu kölesi olursun kendi yarattığın canavarın

ruhunun katlinin fermanı

kendi yüreğinin gardiyanı olursun

bedenin paslanmıştır

ve günlerin artık kayıptır

açmaz nergisler, kokuları saklanır

sanki bir savaştan bahsediyor gibidir

ağzından çıkan sevgi sözcüklerin

ter kokan eski bir otobüsün arka koltuğunda

sürecektir artık hayat seyahatin', 'en eski yanılgısı insanoğlunun peşindeki ağzı salyalı korkulardan kaçarak korkusuz yaşayacağını sanmak oysa nerde korku varsa orada ölümü va...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/korku-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Yanan Kor', 'yuregimde-yanan-kor-hatem-kardesler-1rarj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Terkederken sensizlik beni yalnızlığıma,

Yüreğimde yanan kor dinmesin istiyorum…

Bakma kederliliğime,bakma ağladığıma,

Yüreğimde yanan kor dinmesin istiyorum…

Ayrılığın,hasretin içimi yakar oldu,

Gözümden çıkan yaşlar kalbime akar oldu,

Neş’eler ve sevinçler hep seninle var oldu,

Yüreğimde yanan kor dinmesin istiyorum…

Sevilmeyi,sevmeyi ilk sende tattım inan,

Bir hasret şarkısında sen oldun hatırlanan,

Kalbimdeki seni taa içimde yaşatan,

Yüreğimde yanan kor dinmesin istiyorum…

		         (Hasret İçimde Bir Dağ)  Kitabından', 'Terkederken sensizlik beni yalnızlığıma, Yüreğimde yanan kor dinmesin istiyorum… Bakma kederliliğime,bakma ağladığıma, Yüreğimde yanan kor d...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yuregimde-yanan-kor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kız', 'kucuk-kiz-dilek-ozdemir-u1jx8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözleri güneşle kırpışan küçük kızdım

çalıntıydı hayatlar, sevgiler yalancı

şarkısını arayan çocuk yüreğim

anlatamadı üşüyen düşlerini

özlem, umut ve sabırla

susmalıydım

sustum

kum saatlerinden akarken hayatlar

kolay değildi çocuk kalmak

zaten anam da yoktu benim

elleriyle ağrıma dokunacak

kanadı oyuncaklarım

yaşamalıydım

yaşadım

rüzgar çağırıyordu beni doruklara

yüreğimin karlı dağlarında

küçük cıvıltılardı dinlediğim

o zaman açıldı içimde

bir aşkın tomurcuğu

bir düştü gördüğüm

uyanmalıydım

uyandım', 'gözleri güneşle kırpışan küçük kızdım çalıntıydı hayatlar, sevgiler yalancı şarkısını arayan çocuk yüreğim anlatamadı üşüyen düşlerini özlem...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kucuk-kiz-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kaç Adım Daha', 'bir-kac-adim-daha-mustafa-dogan-kuzgun-pwo0s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sandalyede oturmuş, pencereden bakıyor,

İstemeden gözlerinden bir kaç damla düşüyor

Dışarıdakiler oyun oynarken, gülerken

Dört duvar arasında sıkışmışlığına yanıyor.

O da isterdi, herkes gibi dilediği kadar koşmak,

Sokaklarda yürürken, yağmur altında ıslanmak,

Birkaç saat kar yağınca, kartopu oynamak,

Yorulduğunda anasının dizlerinde uyumak.

Bunlar belki onun için hayaldi,

Belki hiç gerçekleşmeyecek rüya.

Tıkılıp kalmıştı dört duvar arasına

Ne çocukluğunu yaşadı, Ne de eğlendi doya doya.

Bir gün camdan bakarken, canı koşmak istiyor

Dışarıya çıkıp, oyun oynamak istiyor

Ne kadar denesede, istesede olmuyor

Şu tekerlekli sandalye bir kaç adım daha gitmiyor.', 'Sandalyede oturmuş, pencereden bakıyor, İstemeden gözlerinden bir kaç damla düşüyor Dışarıdakiler oyun oynarken, gülerken Dört duvar arasınd...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-kac-adim-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahne', 'sahne-dilek-ozdemir-wks5l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gece rolüydü oynadığım

gerçekçi olmalı diye

korkmalıydım karanlıktan

ve dar sokakların sakladıklarından

kulaklarım azgın köpek havlamalarıyla dolmalıydı

ışıklarsa hep uzaklarda

nereye bakacağımı bilememeliydim

sesimi duyuramamalıydım kimseye

oraya buraya koşturmalıydım umarsız

duvarlara çarpa çarpa

nefes nefese  kalmalıydım

üşümeliydim, tir tir olmalıydım

tek bir ses yoktu

ya seyirciler

sahne arkası nerde

ve bitti sahnem, perde

ışıkları yakın, şimdi

aydınlık ve alkışlar', 'gece rolüydü oynadığım gerçekçi olmalı diye korkmalıydım karanlıktan ve dar sokakların sakladıklarından kulaklarım azgın köpek havlamalarıyl...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sahne-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-sair-engin-8vmgv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Allahım yine kaderim dönmedi

Yine mahsun ve yaşlı gözlerim

Bende mutlu olmak istiyorum

Şu yalancı dünyada

Hep bekleyeceğim Allahım

Belki bu kaderim döner bir gün

Onu kurtarırım, yürütürüm

Ne olur yarabbim yürü ya kulum de

Artık gücüm,dermanım kalmadı

Bu omuzumdaki yükü taşıyamıyorum

Her gün ağlıyorum yalvarıyorum

Gör artık ey YARABBİM!', 'Allahım yine kaderim dönmedi Yine mahsun ve yaşlı gözlerim Bende mutlu olmak istiyorum Şu yalancı dünyada Hep bekleyeceğim Allahım Belki bu ...', ARRAY['Türk Edebiyatı','Şiir','Şair Engin']::text[], 8.5, '{"poet":"Şair Engin","poet_slug":"sair-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kader-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağan Yağmurlar', 'yagan-yagmurlar-sair-engin-3e5c3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu yağan yağmurlar yine seni hatırlatır bana

Yine kalbim hüzünlenir gözlerim dolar

Tut artık beni ey güzelim düşeceğim yoksa

Yine yalnızım  şu yalancı dünyada

Ne olur bırakma beni buralarda yalnız

Ne olur dayan bak yağmurlar senin için yağıyor

O güzelliğin gökkuşağı gibi önümde beliriyor 

Bak yağıyor bereket sil artık gözyaşlarını

Ben gidiyorum  hiç üzülme olurmu gözleri yaşlı

Belki tekrar kavuşuruz şu yalancı dünyada

Giderken yağmurları götürüyorum olurmu

Çünkü ağlarken gözyaşlarıma ortak olsunlar diye', 'Bu yağan yağmurlar yine seni hatırlatır bana Yine kalbim hüzünlenir gözlerim dolar Tut artık beni ey güzelim düşeceğim yoksa Yine yalnızım  ...', ARRAY['Türk Edebiyatı','Şiir','Şair Engin']::text[], 8.5, '{"poet":"Şair Engin","poet_slug":"sair-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagan-yagmurlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Gerçek', 'son-gercek-hatem-kardesler-mp1gl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Severler ve sevilirler dünyada,

Gün olur; bu sevgilerin ahı kalır…

Biri gülmedeyse insanın,yüzbini ağlamada,

Gün olur; gülünen günün bir tek sabahı kalır…

Allah’I,insanı,varlığı sevin,

Zenginliği sevdiğiniz kadar darlığı sevin,

Çekilin bir kenara azraille pazarlığı sevin,

Ki ömrün ahı gider vahı gelir…



Yine de gülün ağlamayın sakın ha,

Bir gönüle binbir ışık yakın ha,

Pınar olup yüreklere akın ha,

Gülünen gün biter,zamanın eyvahı kalır…

Tasa biter,dert biter ve birgün ömür biter,

Ölüm çok kayıtsızdır,ölecekte bin keder,

Ve derlerse bu yol taa kabre gider,

O zaman insanın kendi,birde Allah’ı kalır…

		         (Hasret İçimde Bir Dağ)  Kitabından', 'Severler ve sevilirler dünyada, Gün olur; bu sevgilerin ahı kalır… Biri gülmedeyse insanın,yüzbini ağlamada, Gün olur; gülünen günün bir tek...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/son-gercek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman', 'pisman-atila-gunal-tevg9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle yaşadıklarımdan

Pişman olmak hiç aklıma gelmedi de

Sana yaşamadıklarımın pişmanlığını

Ömür boyu yaşayacağımdan eminim...', 'Seninle yaşadıklarımdan Pişman olmak hiç aklıma gelmedi de Sana yaşamadıklarımın pişmanlığını Ömür boyu yaşayacağımdan eminim......', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pisman-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gerek Bana', 'sen-gerek-bana-yasar-pullu-jqo4s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayşenur Yazıcı   hanımın 

Eğreti Gelin şiirinden sonra yazıldı...

(1)

Yasal Minibüsler keserdi yollarımı

Sesimi telergüler

Dağlı kederler dolardı yüreğime

Sesine saklanırdım geceleri

Ellerin can ellerin

Kınalı ellerinde yetmezdi

Hep  bu yüzden

Dağlara güvenirdim akşam olunca

Ve toprak kokardı anam

Ben kendimle yüzleşirken

Kan sızardı koynumdan

İçim dışım bir

Kana inat

Gökyüzü kusardım

Ülkemin uçurumlarından

2

Aşk ellerinde miydi

Ellerin mi aşk

Bilebilseydim

Vurulmazdım

En azından

Kendi sınırlarımdan çıkmazdım

Şimdi böyle paramparçaysam

Solucan gibi

Yaralıysam

Yokluğundan

Bu uzun yolculuklar

Ve arayıpta zor bulduklarım

Hepsi senin parçaların

Öğretip unuttuklarından

Mesela şu sazım

Dertleşelim diye çağırsam

Bir gecelik ömrü var

Sonrası isyan

Sonrası karabasan

Yani attığım her adım

Senden sonra

Korkak gölgesine

Oysa 

Aşkta da yenilmeyi ağırlamalı insan

Velhasıl can suyum

Ağrıma giden

Vurulsam tenha bir yerde

Ne ağlayan olacak ardımdan

Ne de yas tutan

3

Barışamam kendimle can

Öldürdüm öldürmek isteyenleri beni

Katil ellerim

Yatağını delen ırmak gibiyim

İşkencedeyim

Elektriksiz bir iskemleyim

Öksüzüm  yokluğuna

Boş bir yerdeyim

Hiçbir yerde

Yani bu kökü zehirli bir su

Yılanlar içer

Kelepçeli ve terli

Sen geçersin

Ben boşuna özlerim seni

4

Gece düşer üzerime

Çapraz fişekler

Yıldızlara asılı gülmelerin

Penceremde pusuda

Ben gölgeme küserim

İnce bir sızı düşer sonra

Kırbaçlanmış buğdayından ülkemin

Yerli mali sevdalar anlat 

Şimşekler düşsün şakaklarıma

Yetim kaldı düşlerimde eğreti gelinler

Ve gelinlikleri

Sen gerek bana', 'Ayşenur Yazıcı   hanımın  Eğreti Gelin şiirinden sonra yazıldı... (1) Yasal Minibüsler keserdi yollarımı Sesimi telergüler Dağlı kederler do...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/sen-gerek-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim Bahardı', 'mevsim-bahardi-salim-erben-pjar5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen varken mevsim bahardı

Sen yoksun diye

Ne yağmur yağdı ne de

Hava karardı

Solar sanmıştın ama solmadı

Yüreğimde fidan gönlümde gül

Gece gündüz actıkca actı

Bir unutabilse bunca çekilen

Bunca acıları,

İlk defa kırıp dagıtmak istedim 

Senden kalanları 

Seni seviyorum diye yazdıgın

İki satır yazı 

Dünden bu güne 

Yarını olmayan bir yalandı

Ne sokağı ışık gönlümün 

Ne de köşe başları                                                         

Kim bilir belki de olmayacak 

Umut dolu yarınları

Kim bilir belki unutur gider

Belki de güneşim olur sönmez

Unutur özünde olmayanları

Ve yine baharım olur 

Dört mevsimde

Yine süsler alaca karanlıkta 

Yıldızlar gibi bu zalımı', 'Sen varken mevsim bahardı Sen yoksun diye Ne yağmur yağdı ne de Hava karardı Solar sanmıştın ama solmadı Yüreğimde fidan gönlümde gül Gece g...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mevsim-bahardi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Özledim', 'cok-ozledim-salim-erben-k630o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bahar gelir yaza benzer

Dağlarında ceylan gezer

Allı turnam candan bezer 

Çok özledim turnam seni

Baglarımda baglarımda 

Ceylan oldun daglarımda

Gülün olsam kahve gözlüm

Gelip gittiğin yollarında

Dağı taşı vermez aman

Daralıyor vakit tamam

Ben gurbete dayanamam

Çok özledim turnam seni



Baglarımda baglarımda 

Ceylan oldun daglarımda

Güller açtı kara gözlüm

Gelirsin diye bu baharda

Yollar aman vermez bana

Hasret kaldım bir selama

Dönmek ister gönül sana 

Çok özledim turnam seni 

Baglarımda baglarımda 

Ceylan oldun daglarımda

Güller açtı kahve gözlüm

Bu kaçıncı baharında', 'Bahar gelir yaza benzer Dağlarında ceylan gezer Allı turnam candan bezer  Çok özledim turnam seni Baglarımda baglarımda  Ceylan oldun daglar...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cok-ozledim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğun Zehri', 'mutlulugun-zehri-bisar-ulutas-yxsla', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çeyreğine veda edeli ömrümün çok oldu, 

umutsuzluk çepeçevre… 

Hâlâ işaret edilecek sevgiyi bulamayan parmaklarım 

yumruk vaziyeti almış, 

Sevda ritminden yoksun yaşam ne de güç, 

Gülümseyişine bağlamıştım oysa hayatımı 

Başkalarıyla paylaşacağın 

mutluluğunun zehrini sunuyorsun şimdi 

İçmez isem sen yoksun… 

Oysa bugüne değin sırtımda dinamitlerin 

patlayışına şahit olmuştum 

Gözlerim ne zulümleri görmezden gelmişti 

Kaç okyanus boğmuştu beni bir bilsen 

Ve kış hiç eksilmemişti tenimde 

Hep yakan, kavuran güneş 

bir gün ısıtamaz mıydı bedenimi, 

Her şeye rağmen bir gülümseyişinle 

omuzlayacaktık dünyayı… 

Cihetsiz yollarda terk edip beni 

       kanat çırpıyormuşsun mutluluk ülkesine, 

Kör olurum, lâl olurum, ihtiyar bir topal 

     al beni de götür ülkenin gecekondu mahallesine 

Güneşsiz, susuz, inançsız 

          ve bırakma beni sensiz 

Bir bakışın yeter, ömrümün sonsuzluğuna 

Düğümlenmiş duygularım yanı başımda 

Bundan böyle sevdam biraz ateş, biraz kül 

Yaşam heybem ağırlaşıyor, n’olur gülümse 

Takatsizim, bedenim yorgun 

Biliyorsun 

Mutluluğun-uz zehir bana 

İçersem yok’um, 

İçmez isem, sen yoksun…', 'Çeyreğine veda edeli ömrümün çok oldu,  umutsuzluk çepeçevre…  Hâlâ işaret edilecek sevgiyi bulamayan parmaklarım  yumruk vaziyeti almış,  S...', ARRAY['Türk Edebiyatı','Şiir','Bişar Ulutaş']::text[], 8.5, '{"poet":"Bişar Ulutaş","poet_slug":"bisar-ulutas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/mutlulugun-zehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-bahri-orhan-byqju', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk vadisinin parlayan güneşi

İkliminde kanat çırpsam sonsuzluğa

Leylakları, sümbülleri dökerken ayağına

Aşk nağmeleri fısıldasam kulağına

Yağmur yüklü bulutlar akar mı gözlerine', 'Aşk vadisinin parlayan güneşi İkliminde kanat çırpsam sonsuzluğa Leylakları, sümbülleri dökerken ayağına Aşk nağmeleri fısıldasam kulağına Y...', ARRAY['Türk Edebiyatı','Şiir','Bahri Orhan']::text[], 8.5, '{"poet":"Bahri Orhan","poet_slug":"bahri-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevda-96-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Bir Türlü Bulamıyorum', 'ben-seni-bir-turlu-bulamiyorum-yasin-yamak-v3y75', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzun zaman oldu.

Ne bir haber var senden ne bir ümit bende...

Huzur yeşermiyor artık 

Yüreğimin toprağında.

Kapkaranlık hayallerde

Geceyi içiyorum,

Gündüzün hatırı için...

Yediverenler misali bir anda süzülüyorum

Uzak diyarlara; 

Ama ben seni bir türlü bulamıyorum...

Kıpkırmızı hasretin gözalan haliyle

Seni bir kere daha özlememeye yeminler ediyorum,

Ama elde değil işte,

O yeminleri sana ağlarken

Seni andığım anda bozuyorum...

Zaman geçiyor yine.

Ardıma bakmadan vuslatına koşarken bütün hayallerimle,

Ulaşılmazlığın düşürüyor beni.

Sereserpe yerdeyken,

Serabın damlıyor ağzımdan içeri.

Özlem geçen başımı serabınla canlandırırken

Seni seviyorum diyerek ölüyorum...', 'Uzun zaman oldu. Ne bir haber var senden ne bir ümit bende... Huzur yeşermiyor artık  Yüreğimin toprağında. Kapkaranlık hayallerde Geceyi iç...', ARRAY['Türk Edebiyatı','Şiir','Yasin Yamak']::text[], 8.5, '{"poet":"Yasin Yamak","poet_slug":"yasin-yamak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-seni-bir-turlu-bulamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mart gecesi', 'mart-gecesi-hamdi-oruc-hsozp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mart gecesi 

Mart gecesi ölsem 

Çanakkale şehitleri gibi ay olsam göğe..

Ölümüm gönüllere güneş olası...

Yakışmaz bana her ölüm

Hey gülüm

Ağlanmasın ay ölümüme

Ölümüm gönüllere güneş olası ölüm

Bahar habercisi ölüm öldüm mart gecesi

Ölürüm zindanlarda

Yada savaş meydanlarında...

Zamanda dost sesi şimdi

Ölmeliyim yar senin uğruna

Nisan yağmurları 

Uhut dağının eteklerinde...

Bahar gelmiş

Açıyor papatyalar

Geldi bahar müjdeleri...

Gözüm deniz mavisine dalıyor 

Kutlu izin gül kokusu

Yarışa başlasın yollar.

''Kanlı gömlekle çıksam 

Affım yazılsa 

Aklım kanatlandı başımda değil artık

İnci kimin göz yaşıdır

Boyunlarda akışı yıllarca sürmüş...

Elif görsem vurulsam...

Affım yazılsa

Gömleğim kanlı şimdi...

''Mertçe öldüm  mart gecesi

En mertçe ben öldüm 

Affım yazılsa

Bir mart gecesi öldüm

Ay sözler aksın avuçlarımdan...

Bir yetim yar  uğruna

Kutlu izin gül kokusu döndürdü başımı

Kanlı gömlekle gelsem 

Hamza gibi karanfil olsam

Affeder misin Allahım

Günahlarım dağ gibi

Affeder misin beni Allah''ım', 'Mart gecesi  Mart gecesi ölsem  Çanakkale şehitleri gibi ay olsam göğe.. Ölümüm gönüllere güneş olası... Yakışmaz bana her ölüm Hey gülüm Ağ...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Oruç']::text[], 8.5, '{"poet":"Hamdi Oruç","poet_slug":"hamdi-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/mart-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahmaranlar(24)', 'sahmaranlar-24-i-smet-barlioglu-fuf3d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '3

‘Heykellere potur verdim, don verdim; 

Aman daşşahları ıslanır deyi.

Heykeller silindir şapga geyinmiş; 

Demir gafaları paslanır deyi.’

Odacı Memmeda:

- Müdür Bey çağırıyor.

Dedi ve gitti. Necdet Bey teftişe gitmiş olduğu için onun masasında oturmakta olan delikanlı yerinden kalktı. Odadan çıkıp koridoru geçti.

Kapısı her zaman açık duran Müdür Nami Bey, elindeki kağıt bıçağıyla masasına tepeleme yığılmış olan sabah postasını açmaktaydı. Delikanlının içeriye girdiğini görünce, bu tepeleme zarf yığınının arasından aldığı taahhütlü bir mektubu kendisine uzattı:

- Adına ve hesabına okuduğun bankadan, Kubi. Dedi. Aç bakalım ne buyuracaklar? Okuduğun hangi duaya ip çekecekler? Sanmam ki; kaynanam kız olsun ama inşallah iyi haberdir.

Delikanlı sapsarı bir yüzle, hiçbir yere oturmayıp masa başında öylesine ayakta durarak zarfı ince bir şerit halinde kenarından yırttı. İçindeki, altı imzalarla, mühürlerle, kaşelerle süslenmiş beyaz kağıdı çıkarıp ürkek, titrek gözlerle baktı:

‘Bankamız adına burslu okumak ve üniversiteyi bitirmekle beraber, öğreniminizin tamamlandığı tarihte verilen görevi kabul etmediğiniz için, bankamızca öğreniminize yapılan giderlerin tarafınıza ödettirilmesi karar altına alınmıştır.

Dört yıllık yüksek öğrenim süresince, bu öğrenim için bankamızca yönünüze yapılan harcamalar 4,800 lira olup ödenmesinin biteceği tarihe kadarki bileşik faizleriyle birlikte toplam 12,995 lira ve 98 kuruş olarak hesaplanmış bulunmaktadır.

Söz konusu 12,995 lira ve 98 kuruşluk burs giderlerinizden doğan borcunuzu, bu bildiri tarihinden başlayarak ayda en az 200 liralık taksitler halinde bankamıza ödemeniz gerekmektedir.

Bu karara karşı direnmek veya ödemeleri yaparken gecikmek halinde; hakkınızda yasal koğuşturma yapma ve aylığınıza haciz koydurma yollarına başvuracağımızı bilgilerinize rica ederiz. Saygılarımızla.’

Monoton bir alışkanlıkla önündeki zarf yığınını açarken gözlerini delikanlının yüzünden hiç ayırmayan Nami Bey ansızın zile basıp ani bir sesle:

- Memeda… Bir bardak su getir… Melahat Hanım ‘a söyle içine bir damla kolonya damlatsın…

Dedi. Kapı dibinden alınmış gibi çabucak gelen suyu delikanlıya yarıya kadar içirdi. Koltuğa oturtup bir Bafra sigarasını dudaklarına tutturdu. Çakmağıyla ateşleyip masasına geçti, delikanlıya gelen mektubu kapıp okumaya başladı. İlk defa rastlanan bir garip tutumla sigarasını sık sık nefesleyerek, burnunu sık sık çekerek kağıda çabuk çabuk göz gezdiriyordu.

Delikanlı koltukta yoktu.

Biryerlerde, karanlık karanlık biryerlerdeydi. Ayaklarının altlarında, sellerle yıkanıp kaypaklaşmış, yüksek, sarp, üzerlerinde durulamayan çetin kayalıklar vardı. Ta aşağılardaki karanlık ovalardan her yönü kapatıp kaplayarak, fokur fokur kaynayarak yükselen kirli, bulamaç gibi koyu dumanlar kayalıkları sarıyor, çıplak ayaklarından bacaklarına, paçaları parçalanmış çadır bezi pantalonuna, kemer yerine beline dolalı ipe, göğsünü-bağrını, pazularını, kollarını ortaya koyan bölük-pörçük gömleğine kadar saldırıyordu. Uzak kayalara yıldırımlar düşüren sağnak yağmurlu bir rüzgar saçlarını koparırcasına savurmaktaydı. Çevrelerde, biryerlerde rüzgarın sesi yaralı bir canavarın öfkeli kükremelerini andırıyordu. Üzerine tüm görkemiyle dikildiği kayalıklarda önüne geçilmez yırtılmalar oluyordu. Kayalar diş diş, yırtık yırtık, kabuk kabuk, pul pul ayrılıyor, yarıklardan kara kara, kaynar kaynar dumanlar hortumlar halinde savruluyordu. İçerisinden kızgın lav fokurtuları gelen karanlık bir mağaranın ağzına doğru, sağ elindeki yıldırımları yansıtan kılıcını sallayarak bağırmaktaydı: ‘Ejderhalar… Canavarlar… Ben buradayım… Kayalıklarda… Ortalarda… Buralarda… Buralarda biryerlerde… Şahmaranlar… Şahmaranlar…’ Sesi mağaranın derinliklerinde yankılar yapmaktaydı.

Memeda kapıda görünerek:

- Siz mi bağırdınız? 

Diye sordu. Müdür bakmadan cevap verdi:

- Kubi bağırdı.

- Çay mı söyleyeyim? 

- Çay söyle Memmeda.

Sonra ikiye katladığı kağıdı zarfıyla birlikte koltukta oturan delikanlıya uzattı:

- ‘Deme Mecnun ‘a deli, herkes bir türlü deli.’ Bunlar da ‘Biz işte bu türlü bir deliyiz.’ Diyorlar. Normal, oğlum. İsteseler de başka türlü söyleyemezlerdi: Bak duvardaki resme. Çerçevesinden çıkabiliyor mu? Çıkamıyor. O bir resim de çıkamıyor. Oysa ki çerçevesi daha büyük. Ama çerçeve çerçevedir. İrisi de vardır, ufağı da vardır. Kalını vardır, incesi vardır. Genişi, darı, yaldızlısı, yaldızsızı vardır. Ama çerçeve çerçevedir. Sınırdır. Tükenmişliktir. Benim onlara bir diyeceğim yok. Zira; onlar sınırlarıyla çıkmışlar ortaya. Ben sana diyorum, sana soruyorum. Tükendin mi? Tükendinse burada, tükenmemişlerin arasında ne işin var? Burada, aramızda, Nami ‘lerin, Muzafferler ‘in, Mehmetler ‘in, Necdetler ‘in, Kemaller ‘in, Memmedalar ‘ın arasında. Daha birilerinin arasında. Daha daha birilerinin arasında. Biz tazeleriz, yenileriz, tükenmemişleriz.

Çayı buz gibi olana kadar bardağına bakmadı. Önüne yığılı zarfları açtı. Kağıtları okudu, memurlarına dağıtımlarını yaptı, imza kartonlarındaki yazıları denetledi, imzaladı, mühürledi. Bu arada Memmeda gelip kendisine uzatılanlarla birlikte soğumuş çayları da alarak gitti.

- Kubi… Diyorum ki; otelde kalmaya paran yok ama parklarda da yatamazsın. Otel parası günde beş liradan olsa, ayda yüzeli lira yapar. Yüzeli lira da yüzeli liradır. Burada, dairede, arşivde yat… Geceleri de rahat rahat dosyaları okur, inceler, branşın kompetanı olursun… Daha avantajlı… Orada, otelde, beş kişi bir odada… Olmaz… İpsizi var, sapsızı var… Horlayanı, horlamayanı var… Hakıranı, tüküreni var… Arşivde o yok… Klasörler hakırmaz, tükürmez, gece geç vakit gelip meyhanelerde yediğini odada kusmaz… Horlamaz… Eşya dediğin bir plastik çanta. Ölsen; işte o çantayı kaldırırlar, olur biter. Hiç gelmemiş, hiç gitmemiş olursun. Yatağını yeni Kubi ‘lere kiralarlar. Al çantanı, gel arşive… Bu gece…

Kalem şefi geldi, birşeyler danışıp gitti.

- Yatarsın, sabahları da çok erken kalkıp bokunu-püsürünü toplarsın. Artık her ne bulup üstüne yatarsan işte onları. Memmeda görmesin diye. Memmeda daireyi süpürmeye, silmeye altıda gelir. Ben zorlamam ama o öyle gelir. Sadece küçük düşmeyesin diye. Başka şey için değil. Dairede, akşam iş bitiminden sabahki işbaşına kadar sigara içme, Kubi. Ateş yakma. Zaten senin yok ama olsa da yaramaz; ütü, ocak ve benzeri araçlar tehlikeli. Üstelik dairenin, dolayısıyla devletin elektriğine yük olur. İstemezsin. İkimiz de istemeyiz. Ben de, sen de.

Memmeda çayları yenileyip getirmişti:

- Ayni çaylar. Soğudu diyin değiştirmiştim.

Dedi. Kültablalarını çöp sepetine döktü. Pencere kenarında gezinen örümceği bir kağıt parçasıyla alıp çıktı.

- Kubi… Merkez dışı teftişler var. Tokat ‘ta. İlçelerinde falan. Biraz çokça. Mehmet ‘e verecektim, ivedi işi çıktı. Yasa dışı bir lokavtı soruşturup inceleyecek. Necdet zaten Suşehri ‘nde. Daha gelmedi. Dosyaların senin programına alınmasını Kemal ‘e söyledim. Yarın sabah yola çıkarsın. On günde ancak biter. Yirmi-yirmibeş işyerinin teftişi. Aralarında hem devlet sektörüne, hem de özel sektöre bağlı işyerleri var. Teftişlerin bitince merkeze dön. Orada raporlarını gece yazman için sana verebileceğim bir yazı makinemiz ne yazık ki yok. Raporlarını gelince burada yazarsın. Tokat otobüsleri Belediye Oteli ‘nin karşısındaki sokaktan kalkar. Senin Koyuncu Baba ‘nın çayevi var ya, işte onun az üstünden. Otobüsler eskidir, dökülür ama gider. Tokat buradan otobüsle üç saat. Yollar Çamlıbel ‘de uçurumlu ve tehlikeli ya, artık Tanrı koruyucun olsun.

Kadranda bazı numaralar çevirip ahizeyi kaldırdı:

- Nihat. Dedi. Bana ikiyüz lira borç yolla. Ha ‘di be… Sen benim günahımı haciz korsun aylığıma… Bekletir, bekletir. Tam haciz ettireceğin gün veririm… Tabii oğlum, umudumuz sizde… Çıkarırsın Personel Kanunu ‘nu, aylığımız artar, sen de basar alacağını alırsın.

Formaliteli laflar etmeden telefonu kapatıp zile bastı. İçeri giren odacıya:

- Memmeda. Dedi. Postayı götürürken Nihat ‘a uğra. Tefeci Nihat var ya, onu ben tanımam ha. Bu benim dediğim, milletvekili Nihat, bizim Nihat. Bana ikiyüz lira borç para verecek. Onu al, gel. Özellikle sana da duyuruyorum ki; bilesin. Kazara ölür mölürsem borcum olduğuna tanıklık edip Nihat ‘ın bu alacağının kalan varlığımdan ödenmesine yardımcı olasın.

- Allah göstermesin, Müdür Bey…

- Allah nasıl olsa gösterecek birgün, Memmeda. Hem de hepimize. Sana, bana, herkese. Öyle de bir gösterecek ki.

Odacı ayrıldı. Kalem şefi Kemal Bey ‘in getirdiği dış teftiş program ve dosyaları incelendi, denetlendi, gereken notlar çıkarıldı ve beklenen her türlü açıklamalar yapıldı.

Memmeda zarfı getirince, Müdür Nami Bey, içinden çıkardığı iki ayrı yüzlük banknottan birini kendi aldıi obirini delikanlıya uzattı:

- Müdür yoksul, müfettiş yoksul. Dedi. Ben ne halt edeyim. İşin ucu Mahmıdalar ‘ın elinde. Al şu yüzlüğü Kubi. On gün sürün bununla. Hanya ‘yı-Konya ‘yı daha bir öğren. Geçici görev yollukları gelmiş olsaydı; sana resmen bir beşyüz lira avans yazdırırdım. Ama daha gelmedi. Ne zaman geleceği, de belli olmaz. Yasalarda (Müfettiş, kendisine avans verilmeden yola çıkarılamaz.)  der ya, sen ona aldırma. Ceza Kanunu ‘nda da hayvanlara ağır yük yükleyenin, eza-cefa yapanın cezalandırılacağı yazılı ama herif iki yerine dört çuval yüklemek bir yana, bir de üstelik eşeğini düdüklüyor, gene aldıran yok. Kişilerin haklarının gargaraya getirildiği biryerlerde, eşeklerinki ha ‘di ha ‘di getirilir. Yani sen yasalara pek fazla güvenme. Ama saygını göster. Yasalarımızı yapanlarımız, yasalarımızı uygulayanların görüşlerine metinlerinde yer vermedikleri sürece, böyle sızlanmalar olacaktır. Yani yasa öyle demiş ama iş hiçbir zaman yolluğun gelmesini bekleyemez. Beklediği yerlerde de istenen fayda sağlanamaz, sadece sızlanmaların adı değişir. Dolayısıyla sana avans veremem. Olsa verirdim. Yok. Şimdi, o yüz lira senin bana borcun olsun, bu ikiyüz lira da benim Nihat ‘ a borcum olacak. Söyleyeceklerim bu kadar. Ha ‘di şimdi kalk git, senin yüzünden işlerimi bekletmek istemem. Babamın oğlu değilsin. Olsan da devletin işinden sonra gelirsin. Yallah.

(Devam edecek…) 24', '3 ‘Heykellere potur verdim, don verdim;  Aman daşşahları ıslanır deyi. Heykeller silindir şapga geyinmiş;  Demir gafaları paslanır deyi.’ Od...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/sahmaranlar-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cayo erguvan dökerdi saçlarına / 2', 'cayo-erguvan-dokerdi-saclarina-2-zafer-zengin-etnika-3j6g4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cayo erguvan dökerdi saçlarına

Ondan adı cayo hala

| bir vakti gecenin yağmur yağıyor cayo..

öyle bıkkın..öyle kurnaz elleri.. 

ıslanmayan sokaklar and içiyor

sövüyor cayo insanlara.. 

ben sana ağlarım cayo sakın sen ağlama

yağmurlar getiririm sana

nisanda hele bekle

kesin ilkbaharda

yeşillenir her yan cayo 

yeşil yakışır memlekete dağlarıma |

gözler ölçülen karanlık

kediler saklıyor içinde

kadınlar kar şımaran

ağıt kadar ağır düşen türkülerde

sustum söylemiyorum işte

uyku gelmiş gözüme

mavi değil üstelik

çok şükür cayo

bugünde uyurken ölmedik

ölürken türkü dinlemedik

| ben saydım cayo. kaldırım taşları yaslı..bir kız ayağı takılmış

hesaba tutmuş kendini saatler.. sen bilirsin cayo, ne bekler 

bu kadınlar bu adamlar.. şimdi sevişme vakti desem

göğe çevirip yüzlerini..akşam çöktümü diye bakarlar.. 

sen ceyo hangi vakit kimle hangi saat kimlerle

ezdin kendini  diplerinle.. el sürülmedik kaç gece.. 

beni düşündün cayo..cesursan hadi söyle

Kovduğunda dedim ki; içimden şarap içen akıldı..

mide gelsin geçsin..şarabı umursamazdı.. 

şimdi sarhoş yataklar düşüyor önüme düşünüyorum.. 

cayo uyumuş mudur diye.. sigara yakıyor

lili marlen radyoda diyor usta..dem tutuyormuş ishak kuşu

ben sandalye ve sen cayo..kıvrılmış kaleme yazıyoruz kendimizi 

yine hiç büyümeden..kimseye küsmeden..yağmura bile sövmeden

sokakları dolduruyoruz.. diyeceğim çok şey var cayo

artık başka gün..başka gece |

eti anlatmış bu kavrulma

yerine düşmüş tin

ten biler zorbalığı

bırak bırak cayo

onlar gibi seni anlatma

kehribara düşürdüm hüznümü

ezer toprak gözünde

ezilir yürek

kendi iç''inde

inceden ince

15 01 2005', 'Cayo erguvan dökerdi saçlarına Ondan adı cayo hala | bir vakti gecenin yağmur yağıyor cayo.. öyle bıkkın..öyle kurnaz elleri..  ıslanmayan s...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/cayo-erguvan-dokerdi-saclarina-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
