INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Habersiz Veda', 'habersiz-veda-ali-i-nal-j3x93', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hiç olmasa bir veda

böyle bir gidiş

olmamalı asla

kim olursa olusun

reva görülmemeli

böyle teklifsiz

böyle habersiz

bir ayrılığa

farkında bile olmamak

son kez gördüğünü

hafızaya kazımak için

o gül yüzü

son bir kez dönüp

derin derin bakamamak

ayrılırken

kaçamak bir bakış atamamak

dönüp giderken yokluğuna

artık onsuz olacak

eksik bir hayata', 'hiç olmasa bir veda böyle bir gidiş olmamalı asla kim olursa olusun reva görülmemeli böyle teklifsiz böyle habersiz bir ayrılığa farkında bi...', ARRAY['Türk Edebiyatı','Şiir','Ali İnal']::text[], 8.5, '{"poet":"Ali İnal","poet_slug":"ali-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/habersiz-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-murat-demir-g2r0m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adam gibi adam derler

Çoğu zaman duymuşumdur

Hitaplarda,

Adamlara rağmen,

Adam olmayanlara bile,

Yazmazsa da kitaplar da.

Neyse der güler geçerim

Sakalındandır sayarak

Anlamadan, anlamışım gibi,

Fakat; 

Hiç anlamadığım,

Anlayamadığım bir şey var ki,

O da, kızlara,

Delikanlı kız mış,

Kadınlara, adam gibi kadın mış

Denilmesidir.

Anlayan varsa anlatsın lütfen,

Neden, kıza, kız gibi kız

Kadına, kadın gibi kadın

Denilemiyor, acaba,

Neden?', 'Adam gibi adam derler Çoğu zaman duymuşumdur Hitaplarda, Adamlara rağmen, Adam olmayanlara bile, Yazmazsa da kitaplar da. Neyse der güler ge...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/neden-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Ne', 'bana-ne-kemal-cakir-oeqwk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bahçelerden, bağlardan

Mor çiçekli dağlardan

Bana ne! 

Gönlümde bir çiçek açmayınca.

Çisil -çisil yağan yağmurlardan

Kudurup deliren çağlayanlardan

Bana ne! 

İçinde bir damlam olmayınca.

Güneş her şeyi yaksın bitirsin

Rüzgar savurup götürsün 

Bana ne! 

Bir zerresi benim olmayınca.

Aşk şarkıları çalsın sazlarda

Çobanlar türkü söylesin uzaklarda

Bana ne! 

Bir nağmesi benim olmayınca.

Ferhat ile Şirin'' in

Leyla ile Mecnun'' un aşklarından

Bana ne! 

Bir sevenim olmayınca.

				Ocak 1993', 'Bahçelerden, bağlardan Mor çiçekli dağlardan Bana ne!  Gönlümde bir çiçek açmayınca. Çisil -çisil yağan yağmurlardan Kudurup deliren çağlaya...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bana-ne-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Daglarım', 'sevda-daglarim-hasan-cam-2bgbc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Farkında değilim, zayıfmış hesabım

Olmaz derken bu gecede sabahım..

Aynaya bakınca anladım, beyaz şakağım

Dönüp bakınca ardıma, nasılda geçmiş yıllarım

Toz, pembe bu gece her şey

Saçların sanıp, boş yastığın okşadım

Yine boşa geçti hayalim, rüyalarım

Nerde nerde, hani sevda dağlarım

Uykularım bölüm pörçük, benliğimi aldın

Elimde sigaram, tek tek yıldızları sayarım

Bir farkım var, gündüzü, geceyi ayıramadım

Akşamlarım yok, doğmadıki güneşim batsın

Her nefeste binkez adını andım

Sevdiğini bilmeyip, günahkar sandım

Her adını duydum, lanetlere sarıldım

Nerde nerde, hani sevda dağlarım.

03,07,2005,

Ümraniye   İstanbul', 'Farkında değilim, zayıfmış hesabım Olmaz derken bu gecede sabahım.. Aynaya bakınca anladım, beyaz şakağım Dönüp bakınca ardıma, nasılda geçm...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevda-daglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berceste Mısralar-24', 'berceste-misralar-24-nihat-malkoc-k8jnz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KARŞILIKSIZ MI SANDIN?

Karşılıksız mı sandın çektirdiğin her âh''ı?

Gün yüzü göstermeyen, göremez hiç sabahı

NAMAZI ÖTELEME

Kazalara güvenip namazı öteleme

Secdesizlik insanı gark eyliyor eleme

OSMANLI’YA DAİR

Sükût eyledi zaman, boynu bükük hâneler

Yas tutuyor tarihler, ağlıyor efsaneler

SİNAN

Can üfledi ruhundan, konuşturdu taşları

Süngüdür minareler, arşa değer başları

KANDİLLER

Gönüller nur çeşmesi, Hakk’a niyazda diller

Zamanı çepeçevre kuşatıyor kandiller

ENTEL ER(KEK)LER

Saçlar omuz aşağı, kulakta bir çift küpe

Her gün diskoda, barda; ahlâk vuruyor dibe

SAÇLAR

Zaman tel tel boyuyor saçlarımı beyaza

Bırakıverdim gayri düşlerimi ayaza

EMROLUNDUĞUN GİBİ YAŞAMAK

Hak varlığına delil, ne kadar gelişse fen

Emrolunduğun gibi yaşamaktır vazifen', 'KARŞILIKSIZ MI SANDIN? Karşılıksız mı sandın çektirdiğin her âh''ı? Gün yüzü göstermeyen, göremez hiç sabahı NAMAZI ÖTELEME Kazalara güvenip ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/berceste-misralar-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktır Şiir Sağan Dudaklarıma', 'asktir-siir-sagan-dudaklarima-derin-oger-mm1ic', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bakışını almışım yanıma

bakışımda ıslak bir gölgedir sevda

uykudur uyanıktır gergef işler kirpiğin dokuması

şu koca şehre sokak sokak hüzün bakar yerine

harelerine gün vurduğum

kızıl kıvılcımlarında umutlar söndürdüğüm

kirpiklerimdeki ıslaklığın cümlesini içime sürdüm

geceye bir çift yıldız bakar yerine

gel gözleri şiir verilim

içim titresin gözbebeğimden kalbime akışına

çiçek açsın gözlerimin içi barışsın bütün dünyayla

aşktır,aşkındır şiir sağan dudaklarıma..............', 'bakışını almışım yanıma bakışımda ıslak bir gölgedir sevda uykudur uyanıktır gergef işler kirpiğin dokuması şu koca şehre sokak sokak hüzün ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/asktir-siir-sagan-dudaklarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berceste Mısralar-6', 'berceste-misralar-6-nihat-malkoc-bwz14', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'MUHAYYİLE

Bu kurşundan sıkleti taşımaz muhayyilem

Günahıma kefaret, haysiyetimdir çilem

AKIL

Bil ki mikro âlemde akıl bedene yüktür

Dindir ruh sancısını, de ki “Allah büyüktür.”

EVRİM

Evrim koca bir yalan, gece gündüz “Hak” derim

Hakk’a delil istersen git aynaya bak derim

NEFS

Yürek denizlerinin durulmuyor suları

Kör şeytanın elinde nefs atının yuları

BERAT

Hakikatle savaşmak, bu mudur sanatınız?

Rûz-i mahşerde soldan verilir beratınız

UMMADIĞIN ZAMANDA

Balık sabırla bekler, ömür boyu ummanda

Hayaller gerçek olur, ummadığın zamanda

(PU)SU

Çağlayan korku vermez, sessiz akan sudan kork

Meydan savaşı kolay, haince pusudan kork

NİHAİ DURAK

Şah damarından yakın, kim demiş ölüm ırak

Dünya bir gölgeliktir, ölüm nihai durak', 'MUHAYYİLE Bu kurşundan sıkleti taşımaz muhayyilem Günahıma kefaret, haysiyetimdir çilem AKIL Bil ki mikro âlemde akıl bedene yüktür Dindir r...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/berceste-misralar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Ben', 'gercek-ben-kemal-cakir-w65px', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni kaybettiğimde kayboldum ben

Ne ben varım artık, ne bende  ben.

Benim bu halime içinden gülen

Asla ben değilim, o bendeki ben.

			Mart 2002', 'Beni kaybettiğimde kayboldum ben Ne ben varım artık, ne bende  ben. Benim bu halime içinden gülen Asla ben değilim, o bendeki ben. 			Mart 2...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gercek-ben-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Sevgiler', 'yalan-sevgiler-haydar-okur-w5vzl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey düş gemisinin mavi süvarisi 

yeterince yükünü almışsın 

tonilaton son reddesinde 

ve hayli ağır bir yük altındasın 

Güvertene varıncaya değin dop-dolu...

Sığabileceğim bir minicik yerin bile yok

sıkıp sıkıştırma beni daracık boşluklara 

ne sen taşıyabilirsin 

ne de ben dayanabilirim 

değerli yüklerinin arasında sıkışmaya... 

bırak beni denizlerin bir yerinde 

korkma gömülmem derin sulara 

dalgalar yazgı gibidir 

bata çıka, yalpalaya yalpalaya...

ulaşırım belki de

bir bilinmez kıyıya...', 'Ey düş gemisinin mavi süvarisi  yeterince yükünü almışsın  tonilaton son reddesinde  ve hayli ağır bir yük altındasın  Güvertene varıncaya d...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalan-sevgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Durak', 'son-durak-kemal-cakir-t6168', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçip duruyor hiç durmadan  zaman

Acaba ne zaman dolacak bu zaman

İnsan düşünüyor da zaman zaman

Yine de aldırmıyor hiçbir zaman.

Karanlığa doğru yol alış mı bu

Yoksa tam bir aydınlığa koşuş mu

Yolun neden farklıdır uzunluğu

Acaba bunun bir ortası yok mu? 

Sonunda hep bir yerde olacağız

Kimimiz ağlayacak,kimimiz gülecek

Kimimiz dört nala o yere koşacağız 

Kimimizin ayakları  geri geri gidecek.

İşte son  son durak göründü bile; 

Yolcular sıra sıra iniş kuyruğunda

Ağlamak, yalvarmak, pişmanlık nafile

“Yapsaydın” denecek bunları zamanında.', 'Geçip duruyor hiç durmadan  zaman Acaba ne zaman dolacak bu zaman İnsan düşünüyor da zaman zaman Yine de aldırmıyor hiçbir zaman. Karanlığa ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-durak-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Özleme Değersin', 'bin-ozleme-degersin-haydar-okur-ma18p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yorgun umutlarını dalgaların çıpıntısına bırak 

ko devinip dursunlar köpük köpük 

düşleyedur ışık kuşlarını duygularının 

özgünlüğünü gecelerin soyutluğunda bırak 

daha bahardasın 

goncasın tomurcuksun... 

ilk mervsimin ilk heyecan ve ilk basamak 

açsın çiçeklerin özgürce renk renk... 

uçuşsun kelebekler gönlünde kanat kanat... 

daha sen ilk tomurcuk ilk çiçeksin 

değil ki bir özleme 

bin özleme değersin', 'yorgun umutlarını dalgaların çıpıntısına bırak  ko devinip dursunlar köpük köpük  düşleyedur ışık kuşlarını duygularının  özgünlüğünü gecele...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bin-ozleme-degersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız Kaykayında', 'yildiz-kaykayinda-haydar-okur-2qboz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşlerim seninle güzel 

Seninle sıcak gecelerim 

Sen içimde oldukça 

Masmavidir düşüncelerim... 

Geceler boyu seni yaşarım

Tan basımına değin usanmadan 

Seni görürüm ay ışığında 

Kar tanecikleri gibi pırıl pırıl 

Ve yağmurun okşayan damlalarında 

ıpıslak sırılsıklam... 

Kimileyin 

Karanlıkta bulurum kendimi 

Düşlerime sarılırım 

Seni ararım 

Seni ararım rüzgarın uğultusunda, 

Ay ışığında,

Yıldızların kay kayında...

Kimileyin de

Kumruların gugukları muştular 

Bana geldiğini ığlım ığlım... 

Goncalar açmaya durur 

Sarar benliğimi bir yar kokusu 

Güzelleşir yer ve gök 

Güzelleşir yaşamım

Yıldızlar kay kay oynadığında', 'Düşlerim seninle güzel  Seninle sıcak gecelerim  Sen içimde oldukça  Masmavidir düşüncelerim...  Geceler boyu seni yaşarım Tan basımına deği...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yildiz-kaykayinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitiklik', 'yitiklik-haydar-okur-mnlyf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevi yok sevda yok

ve sen yoksun

ışığın yansımıyor

ışığın yok...

Duydum

yadlarda açar olmuşsun

çiçek çiçek...

mavi derinliğin yok

Duygusuz duyarsız

ve rotasız bir gemi  gibisin

limansız ve sirensiz...', 'Sevi yok sevda yok ve sen yoksun ışığın yansımıyor ışığın yok... Duydum yadlarda açar olmuşsun çiçek çiçek... mavi derinliğin yok Duygusuz d...', ARRAY['Türk Edebiyatı','Şiir','Haydar Okur']::text[], 8.5, '{"poet":"Haydar Okur","poet_slug":"haydar-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yitiklik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-ufuk-coban-nwdh9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu sabah yağmur düşecek İstanbul''a,

Ama damlalar yalnız kalacak yerde,

Hiç uğramayacaklar yüzüme,

Hiç dokunmayacaklar sensizliğime.

Bu sabah yağmur düşecek kalbime.

Hissettirmeden hasret kaldığım kokuna.

Nefes almazken dokunuşuna,

Bakarken sensiz uzanan yollara.

Yakında fırtına düşecek gözlerime,

Önümü göstermeyen kendiliğinden.

Kaçmaya fırsat vermeyen gücünden,

Ve sonunda bir girdap beni yutan.

İstediğim hiç düşmeyecek kaderime,

Bir bütünü korurken kendiliğinden.

Belki suçlu değildir istediğinden,

Biliyorum... Beni çok sevdiğinden.

17/06/2000', 'Bu sabah yağmur düşecek İstanbul''a, Ama damlalar yalnız kalacak yerde, Hiç uğramayacaklar yüzüme, Hiç dokunmayacaklar sensizliğime. Bu sabah...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yagmur-193-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahrolmayası', 'kahrolmayasi-resat-coskun-2f79v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kahrolmayası 

Neden bu kadar iyisin, 

Neden bu kadar iyi? 

Sensiz nice yıllar geçti. 

Acın hala taze 

Hatıraların içimde hep diri. 

Seni unutmak için 

Karıştırırım, 

Bütün bir maziyi. 

Bulamam, kötülük adına 

Sen elinden gelen 

En ufak incinmişliği. 

Kahrolmayası, 

Neden bu kadar iyisin 

Neden bu kadar iyi? 

Kıyamet mi kopardı 

Seni unutmam için. 

Bahane babından 

Bulsaydım iyilik adına 

Elinden tadılmış bir incinmişliği.', 'Kahrolmayası  Neden bu kadar iyisin,  Neden bu kadar iyi?  Sensiz nice yıllar geçti.  Acın hala taze  Hatıraların içimde hep diri.  Seni unu...', ARRAY['Türk Edebiyatı','Şiir','Reşat Coşkun']::text[], 8.5, '{"poet":"Reşat Coşkun","poet_slug":"resat-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kahrolmayasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsteğim', 'i-stegim-abdulkadir-karaca-rcju1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Ne''mi istiyorum

Bir damla aşk sadece

Çok fazla şey değil

Yetecek kadar işte

Seni ne kadar özlediğimi bilemezsin

Telefonun başında kaç vardiya atlattığımı

Ağladığımı,ağladığımı ve son tuşa basamadığımı

Son tuşa basmaya cesaret ettim

Sesini duydum en sonunda

Cesaret edip İstanbul''da yapamadığımı

Yaptım Bursa yolunda

Sesin ne kadarda değişikti

Üzgünmüsün yoksa? 

Beni attığın kuyunun başında uykusuzmusun? 

Bir kanlı gömlek yok mu götürecek aşka

Memnunmusun kaçtığıma

Duyduğuma göre mutsuzmuşsun

Beni özlersen elini kalbine koy

Çünkü buralar orası kadar soğuk

Bir rüyadan uyanırsın ki korkmuşsun

Sesim gelir uzaktan boğuk boğuk

Tıpkı telefondaki sesin gibi...

Artık mutlu ol

Son kurban ben olabilsem aşka

Bıçağının altına koyardım boynumu

Bir kaç damla sıcak kanım aksa toprağa

Toğrağa dayasam koynumu

Canlansa hece hece aşk sözcüklerim

Bırak sesin gelmesin ben böylede severim

Ya sen bu mecnunu sevebilirmisin

Her yenildiğin savaşta kapıma gelmesen

Her mutluluk verdiğimde bırakıp gitmesen

Seni bu kadar sevmezdim bilirsin

Tüm şiirlerimin sırrını bilmesen

Bugün bu sırrı bahar çiçeklerinde arıyorsan

Ve aradığında beni yanında bulamıyorsan

Burdayım işte yalnızım harabım

Bir görsen ah bir bilsen

(5 Nisan 2004)', '''Ne''mi istiyorum Bir damla aşk sadece Çok fazla şey değil Yetecek kadar işte Seni ne kadar özlediğimi bilemezsin Telefonun başında kaç vardi...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/istegim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit Yetersiz', 'vakit-yetersiz-kemal-cakir-0fk3i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çekmekle bitse dünyanın kahrı

İnanın ki çekip bitireceğim.

Ama  Yine hep biliriz  ki

Yetmiyor buna insanın 

Ne vakti, ne dayanma azmi.

			10.06.2001 Kemal ÇAKIR', 'Çekmekle bitse dünyanın kahrı İnanın ki çekip bitireceğim. Ama  Yine hep biliriz  ki Yetmiyor buna insanın  Ne vakti, ne dayanma azmi. 			10...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/vakit-yetersiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağım', 'bayragim-hasan-cam-vhnwj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bayrağım

Masmavi gökyüzünü süsleyen rengin

Bu vatana nice can vermiş

Şehit kurbanlarımızın kanıdır

Al kırmızın gündüzü

Ay yıldızın

Genç neferlerimizin geleceği

Geceyi ve istikbalini temsil eder

Bayrağım

Soğuk. sıcak gece ve gündüz demedin

Ceddimin devamını temsilen dalgalandın

Her cepheye

Kardeşliği ve barışı taşıdın

Kim aksini iddia ederse

Altında dalgalanan gölgene baksın

Bayrağım

Sana kem gözle bakan gözler

Önce çevresine

Bosnaya. kırıma. ırak''a kıprıs''a

Gümülcineye. dönüp yüce ATAYA

Yüce marşımıza baksın

O herşeyi anlatmaya yeter

26,02,2005,

Ümraniye  İstanbul', 'Bayrağım Masmavi gökyüzünü süsleyen rengin Bu vatana nice can vermiş Şehit kurbanlarımızın kanıdır Al kırmızın gündüzü Ay yıldızın Genç nefe...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bayragim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tadilat', 'tadilat-mustafa-celebi-cetinkaya-3955e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Değişti baştan sona; 

adım, ruhum, yaşantım...

Terkedip gitti umutlar,

Bu can''ı öldü sandım.

Hani adını yazmıştı ya birisi 

                  yıldızların üzerine

İşte o bendim...

Değişti de baştan sona her şey,

ben değiştim de 

sanki ne değişti....? 

04 Temmuz 2005 12:20 

S.B. Sıhhiye', 'Değişti baştan sona;  adım, ruhum, yaşantım... Terkedip gitti umutlar, Bu can''ı öldü sandım. Hani adını yazmıştı ya birisi                  ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çelebi Çetinkaya']::text[], 8.5, '{"poet":"Mustafa Çelebi Çetinkaya","poet_slug":"mustafa-celebi-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tadilat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahmaranlar(25)', 'sahmaranlar-25-i-smet-barlioglu-3jw4w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O gece delikanlı arşivde yattı. Örtüsüz, hantal, dört kalın bacaklı, dikdörtgen biçimli bir masanın üzerinde. Başının altına kalın bir klasör koymaya çalışarak. Yatarken hiçbir şey düşünemedi. ‘Çıkarıp başka biryerlere, bir tahta kutuya da koysan, yaşadığı, var olduğu sürece kendi kendine de düşünür.’ Dediği beyniyle hiçbir şey düşünemiyordu. Bu beyin, bir arabanın şarj yapamayan akümülatörü gibi boşalmış, tükenmişti. Dışı güzeldi, kaportası, ambalajı, dahi bir şeyleri güzeldi ama içi koftu. Sadece olduğu yerde duruyor, var olan bir şeylere, değeri olan bir şeylere benzeyerek aldatacağı saf alıcısını bekliyordu.

Başının altındaki klasörün dalda dalga dalgalandığını hisseder gibi oldu. Doğrulup baktı: Klasörün içinde başı insana benzeyen, kalın gövdeli bir yılan vardı. Günde 72 tavuk, 29 tavşan yiyen, 14 varil süt içen bir yılan.

Klasörü korkuyla yere vurdu. Arasından yılanlar döküldü. Büyümeğe hazırlanan, yumurtadan yeni çıkmış, binlerce yılan, onbinlerce yılan, yüzbinlerce yılan. Başları insan başı, yüzleri insan yüzü olan milyonlarca yılanlar.

Delikanlı klasöre ayaklarıyla vurdu, kartonu ezerek parçaladı ve bağırarak dışarıdaki ıssız, karanlık koridorlara fırladı:

- Şahmaranlar… Şahmaranlar… Şahmaranlar…

Kazara girdiği odanın kapısı kapatılınca, kaçmak için korkusundan kendini kapalı camlara camlara, duvarlara duvarlara vuran bir zavallı kuş gibiydi.

(Devam edecek…) 25', 'O gece delikanlı arşivde yattı. Örtüsüz, hantal, dört kalın bacaklı, dikdörtgen biçimli bir masanın üzerinde. Başının altına kalın bir klasö...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sahmaranlar-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyuncak Satan Çocuk', 'oyuncak-satan-cocuk-kemal-cakir-xy1yb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir o yana bir bu yana sallanıyor

Tıpkı bir salıncak gibi.

Ellerinde  tuttuğu oyuncakları satıyor

Oysa onlar hayallerinin sahibi.

Uzatıyor en sevdiği oyuncağı birine

Kısık bir sesle ''Alır mısın amcacığım'' diyor

Uzattığı eli dönüyor  hemen yerine

Gözlerine inanılmaz biraz hüzün çöküyor

Bu mahcupluk  ve sonsuzluğa uzanan hüzün

Alıp götürüyor  kalan yitik sevgisini

Arada bir  çocukluğuna dalıp dalıp gidiyor

Oyuncaklarını sorguluyor, suçlu sanıp her birini.', 'Bir o yana bir bu yana sallanıyor Tıpkı bir salıncak gibi. Ellerinde  tuttuğu oyuncakları satıyor Oysa onlar hayallerinin sahibi. Uzatıyor e...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oyuncak-satan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aş(k) ın Sone', 'as-k-in-sone-atif-okan-pbl05', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bilesin! aç çakallar bir dağın mahremidir

geceler yıldızlara gebedir gün içinde

şelale lal''e düşse kanla yazılır şiir

zahitler huzur desin aşk matemdir bi(r) inde

bir gün bir gül gibi solmayı da bilmeli

ölümsüzler yoluna ölünerek girilir

bir an kalbimi tutsa tanrının sonsuz eli

boşalır parmaklardan günahlar nehir nehir

günahlarım boğacak bir deniz istiyorum

su/satan dizelerim mısralarım üstüne

an(d) olsun! aynaları yutacak bu ruhum

alevler arasından yüzüm değse yüzüne

aş(k) ınsız bir kılıçtır ipek canlar içinde

parıldar yıldız gibi solgun kanlar içinde', 'bilesin! aç çakallar bir dağın mahremidir geceler yıldızlara gebedir gün içinde şelale lal''e düşse kanla yazılır şiir zahitler huzur desin a...', ARRAY['Türk Edebiyatı','Şiir','Atıf Okan']::text[], 8.5, '{"poet":"Atıf Okan","poet_slug":"atif-okan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/as-k-in-sone-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyüm', 'koyum-hasan-cam-c21wh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzel köyüm taç alan, adın yakışır sana

Dünyaya göz açtım, hayat verdin.

Bir başkasın yeşilinle, havanla, suyunla

Keçiler, kuzular,yayılır ormanında, meranda

Bir zaman, umutlarım vardı ufuklarında

Doyumsuz, muhabbetli, misafirper insanları

Bir başkaydı ozaman, kamil, şakir, dedeler

Yigitti kaşif, muntazdayılar, hasan emmiler

Cıvıl cıvıl torunları, ayşe, ünzile gelinler

Nerde o, atlarla saman taşınan nal sesleri

Nerde o, imam hüseyin, öğretmen tuncay

Yazında girilmez suyuna, gölgededir gölleri

Hıdrellezde külhandı, şükrü top gibi gençleri

Hepsi savruldu birer birer, başka diyarlara..

Kimi gurbete, kimi ihtiyarlığa, kimi kara toprağa

Bir aşk doğmıştu bağrından, akan şelalen gibi

Biri gurbet, biri sıla, öylede çektiler adları gibi

Yakışmazxmıydı yeşilin içine, kırmızılı prenses

Yakışmazmıydı yeşiline, mavi gözlü yağız prens

Cennetsin sen taç alan cennet, ucsuuuz bucaksız

> Samsun Salı pazarı  Taç alan köyü', 'Güzel köyüm taç alan, adın yakışır sana Dünyaya göz açtım, hayat verdin. Bir başkasın yeşilinle, havanla, suyunla Keçiler, kuzular,yayılır o...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/koyum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-serhat-sumer-ckkpv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Masmavi bir ölüme çalıyor gözlerin 

Ne zaman karşına çıksam 

Bir sevmek düğümleniyor kursağımda 

Söyleyemiyorum 

Bulutları çağırıyor gözlerin 

Gitmek gibi yapayanlız uzaklara 

Dilimde şarkılarla 

Özlemek çekiyor canım 

Yağmurlu bir nisan sabahı 

Dökülürken avuçlarımdan gözyaşlarım 

Bir kıyamet gecesi feryadı gibi 

Parça parça olurken yaşadığımız herşey

Vurup dibine isyanların 

Karşında dimdik durmak istiyor 

Gülmek istiyor gözlerin 

Döndüğüm zaman uzak yerlerden 

Hüzünlü aşk şarkıları fısıldarken 

Söylemek istiyor dudakların 

Söyleyemiyorsun

Karşılıksız söylenemiyor hiçbir şey

Hiç bir yolculuğun hayali bile yalnız kurulmuyor

Bir özleyen olsun istiyor insan 

Saçma sapan yerlere 

Saçma sapan zamanlarda gittiğinde 

Ve yılları yakıp geri döndüğünde 

Bir bekleyen bulsun istiyor

Söyleyemiyorum 

Oku gözlerimden 

Sımsıcak bir 

''Seni seviyorum''u oynuyor gözlerin 

Gizleyemiyorsun', 'Masmavi bir ölüme çalıyor gözlerin  Ne zaman karşına çıksam  Bir sevmek düğümleniyor kursağımda  Söyleyemiyorum  Bulutları çağırıyor gözleri...', ARRAY['Türk Edebiyatı','Şiir','Serhat Sümer']::text[], 8.5, '{"poet":"Serhat Sümer","poet_slug":"serhat-sumer","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gozlerin-164-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birden Solup Gitti Gençligim', 'birden-solup-gitti-gencligim-hasan-cam-0xplo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aglayan gözlerimi silenmi var

Kanayan bu yaramı saranmı var

Öyle dertliyimki sonsuz isyanım

Senden başka derdimi bilenmi var

Birden solup gitti gitti gençligim 

Hiçmi hiç bitmeyecek benim derdim

Nedir allahım nedir bu çektigim

Birden solup gitti gitti gençligim

Ayrılık öyle zorki bitmez sanki

Sevmedim senden başka hiç kimseyi

Çok denedim bende sensiz ölmeyi

Senden başka canımı alanmı var

Birden solup gitti gitti gençligim 

Hiçmi hiç bitmeyecek benim derdim

Nedir allahım nedir bu çektigim

Birden solup gitti gitti gençligim

15,09,1979

Ümraniye  İstanbul', 'Aglayan gözlerimi silenmi var Kanayan bu yaramı saranmı var Öyle dertliyimki sonsuz isyanım Senden başka derdimi bilenmi var Birden solup gi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/birden-solup-gitti-gencligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Gece', 'bir-gun-gece-hasan-cam-3uzhm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ömre bedel yaşadık, bir gün gece

Şaşırmış bocalamıştım şefkatine

Tanrı kulu dedin misafir ettin, yabancıydım

Unutmuştun nefreti, feryadı, beni görünce

Soğuktu ısıttın, baş köşeni açtın kalbinde

Ekmek, su, aş verdin, hesap sormadın bana

Annem gibi baktın, kusur etmedin sevginde

Sanki yılları sıgdıracaktık, bir gün gece

Allah''ım rüyamı, aşkım önümde, ben ardında

Gözümüz yaşlı, bedenlerimiz kollarda

Sıcaktı yatağın, şefkatliydi sine ve kucağın

Okadar çoook soracağım, sığarmı bir gün gece

Kokunu sunmuş, benligini vermiş, sarmıştın

Buğulu banyonda, ağıtlarla çok aglamıştın

Duygulu yüreğim, benide aglatmış, dağılmıştım

Yirmi sekiz yıl görmeden, kolaymı bir gün gece

Sevgimiz, ayrı düşen aşkımız, sade bildiğimiz

Hangi özlemi nerede, nasıl yaşadık, anlamadık

Toylar gibi tanımıyor, keşfetmedik biz bizi

Doyamadık, saramadık, böyle kalmaz bir gün gece

Kapı ardı kalışın, kez kez sarlışın, kolaymı aşkım

Varla yok arasında bocaladım, yaşammı ölümmü

Farkındaydım ardıma bakışının, dönüp bakamadım

El sallayamadık haklı aşkımıza, vedasız bir gün gece

11 02 2005

Ümraniye   İstanbul', 'Bir ömre bedel yaşadık, bir gün gece Şaşırmış bocalamıştım şefkatine Tanrı kulu dedin misafir ettin, yabancıydım Unutmuştun nefreti, feryadı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-gun-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamam', 'anlatamam-serhat-sumer-kxoy7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Halimi kınama dostum 

Bana çok büyük imtihan düştü

Kırıldı kanatlarım 

Dizlerimden derman düştü

Değişti gönül dünyam 

Hayallerim bir başka oldu

Tamda kurumuşken yeşillerim 

Bulutlardan yağmur düştü

Özlemim arttı geçmişe 

Eski dostlarim geldi aklıma 

Döndüm önüme ah edip hatırama 

Kalbime koca bir volkan düştü

Kınama halimi dostum 

Çok sıkıntılar çektim 

Ne söylemeye sözüm yeter 

Nede söyleyebilirim 

Ve her şeye rağmen, iyiyim...', 'Halimi kınama dostum  Bana çok büyük imtihan düştü Kırıldı kanatlarım  Dizlerimden derman düştü Değişti gönül dünyam  Hayallerim bir başka o...', ARRAY['Türk Edebiyatı','Şiir','Serhat Sümer']::text[], 8.5, '{"poet":"Serhat Sümer","poet_slug":"serhat-sumer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anlatamam-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Yaşıyla Büyüdüm Ben', 'goz-yasiyla-buyudum-ben-hasan-cam-cmsok', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kanadımı tutuşun neden

En zayıf hücremden vuruşun neden

Gülmedimki dünyada

İçime duvarlar örüşün neden 

Göz yaşıyla büyüdüm ben

Bir de denizlerimi sen doldurma

Samsun şehrinde kabem olursun

Ne olur secdemi sana doğrultma

Seven mutlu olmuyor

Bu uğurda yollar bitmiyor

Güneş battımı bir daha doğmuyor

Ne olur, bir ayrılık daha yaşatma

Göz yaşıyla büyüdüm ben 

Bir de denizlerimi sen doldurma

Samsun şehrinde kabem olursun

Ne olur, secdemi sana doğrultma

13,05,1980,        

Ümraniye     İstanbul', 'Kanadımı tutuşun neden En zayıf hücremden vuruşun neden Gülmedimki dünyada İçime duvarlar örüşün neden  Göz yaşıyla büyüdüm ben Bir de deniz...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/goz-yasiyla-buyudum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satranç', 'satranc-serhat-sumer-6fb8o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Piyon piyonu yer 

Ve güler karanlığın içinde gözler 

Eller 

İlk buluşmanın heyecanıyla titrer 

Çiçekler açar yanaklarında 

Geceleri hayaller süsler 

Piyon fili yer 

Sen dolar her yer 

Gözlerim kapanır, aydınlıktır 

Sözler seni söyler 

Seni anlatır şarkılar 

Bir rüyadır, içim yanar 

Kanar takvimlerin buğusunda eski yaralar

Sessiz bir volkan patlar, duymazsın 

Susarsın sonra 

Vezir yıkılır 

Akşam olmuştur 

Kızılca bir kıyamete uçar martılar 

Yapraklarda sonbahar 

Yüreğim buruktur

Katran dolmuştur gözlerime katkat

Ayrılık demişsindir 

Şah mat.', 'Piyon piyonu yer  Ve güler karanlığın içinde gözler  Eller  İlk buluşmanın heyecanıyla titrer  Çiçekler açar yanaklarında  Geceleri hayaller...', ARRAY['Türk Edebiyatı','Şiir','Serhat Sümer']::text[], 8.5, '{"poet":"Serhat Sümer","poet_slug":"serhat-sumer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/satranc-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalım-1', 'sevdalim-1-gonul-ozdemir-eh5e6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdalım-1

Sevda merkezinin acı çektiği nokta,

Nedir o bilirsin bitanem

Kanayan bir yürek,her atışında

İsmini zikrediyor sanki,

Her günün bitiminde

Sensiz koyuyorum başımı yastığıma,

Meçhul yarınlara kapanmadan gözlerim

Her nefesimde bir damla ıslatır yanağımı,

Boğulurum gecenin zifiri karanlığında,

Düğüm düğüm dizilir boğazıma 

İçimdeki aşk nağmeleri,

Kulağına fısıldayamıyorum

Yoksun yanımda

Güzelliklerin doruğunda dolaşmıştık,

Ahhh SEVDALIM 

Bilsen nasıl duygu,seni sensiz yaşamak...

1.7.2005  Gönül Özdemir   -Bergk-

e-mail

goenuel.oezdemirgmx.de', 'Sevdalım-1 Sevda merkezinin acı çektiği nokta, Nedir o bilirsin bitanem Kanayan bir yürek,her atışında İsmini zikrediyor sanki, Her günün bi...', ARRAY['Türk Edebiyatı','Şiir','Gönül Özdemir']::text[], 8.5, '{"poet":"Gönül Özdemir","poet_slug":"gonul-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevdalim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksa Hâtırâlarda Kalmıştı Şimdi Adım', 'yoksa-h-tir-larda-kalmisti-simdi-adim-mehmet-bicik-b8xka', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duygular sel olup her gün çağlamakta,

Rahatlık bulurum tenhâda ağlamakta..

Kızım Ahsen beni hayata bağlamakta,

Yoksa hatıralarda kalmıştı şimdi adım...

Gönlüm kırıldı, tâmir olmaz bu yara,

Bilmiyorum naparım, düşünüyom kara kara,

Ne yapsam derdimi anlatamam yâre,

Çırpınsam dursam da duyulmaz feryâdım...

Mutsuzluk insanın hayatını bitiren ur,

Çıkamam el içine kalmadı onur-gurur.

Bu ayrılık beni tâ canevimden vurur,

Kalmadı şu âlemde tuzum - tadım...

Duygular sel olup her gün çağlamakta,

Rahatlık bulurum tenhâda ağlamakta..

Kızım Ahsen beni hayata bağlamakta,

Yoksa hatıralarda kalmıştı şimdi adım...

4 Temmuz, 2005 Pazartesi

Burhaniye 13:50', 'Duygular sel olup her gün çağlamakta, Rahatlık bulurum tenhâda ağlamakta.. Kızım Ahsen beni hayata bağlamakta, Yoksa hatıralarda kalmıştı şi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yoksa-hatiralarda-kalmisti-simdi-adim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat İşte', 'hayat-i-ste-abdullah-ozcan-gokcen-1w2uj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğarken ağlamayan mı var

Yaşarken ağlamasın? 

Dertlerle çilelerle,

Doğsan bir türlü, doğmasan bir türlü

Çalışmak,büyük adam olmak

Demek değil midir  okumak? 

Nafile,iş bulmak çok zor

Okusan bir türlü,okumasan bir türlü

Bir gün,yaşından utan

Bekarlık sultanlık mıdır derler? 

Çoluk, çocuk geçim derdi

Evlensen bir türlü,evlenmesen bir türlü

Günler,aylar,yıllar geçiyor

Zamanı mı durduralım? 

Çocukluk,gençlik derken

Yaşlansan bir türlü,yaşlanmasan bir türlü

Herkesin gideceği yer

Kara toprak değil mi? 

Geride bıraktıklarınla 

Ölsen bir türlü, ölmesen bir türlü', 'Doğarken ağlamayan mı var Yaşarken ağlamasın?  Dertlerle çilelerle, Doğsan bir türlü, doğmasan bir türlü Çalışmak,büyük adam olmak Demek değ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Özcan Gökçen']::text[], 8.5, '{"poet":"Abdullah Özcan Gökçen","poet_slug":"abdullah-ozcan-gokcen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayat-iste-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalım-2', 'sevdalim-2-gonul-ozdemir-t6zc5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdalım-2

Aksın gözyaşlarım durmasın,

Her damlada bir HASRET boğulsun.

Çağlasın yüreğim,yansın alev alev

Yansın ki,bağrımda gizlenen sevdam kanasın

Unutturmasın  SEVDALIMI...

3.7.2005   Gönül Özdemir   -Bergk', 'Sevdalım-2 Aksın gözyaşlarım durmasın, Her damlada bir HASRET boğulsun. Çağlasın yüreğim,yansın alev alev Yansın ki,bağrımda gizlenen sevdam...', ARRAY['Türk Edebiyatı','Şiir','Gönül Özdemir']::text[], 8.5, '{"poet":"Gönül Özdemir","poet_slug":"gonul-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevdalim-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhasebem Yetmiyor', 'muhasebem-yetmiyor-hasan-cam-ums9e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağlarına çıkılmıyor sevdamın

Ne dalı kalmış ne budağı

Kırılmış gönül duygularım

Tutmuyor ne elim, nede ayağım

Sana değil kadere, yıllara hesabım

Öfkemiz birşey değiştirmiyor

Bu hayat üniversine, ne kadar çalışsam

Muhasebem yetmiyor be sevdalım

Bitiremedim ben sevda okulunu

Girmiyor dersime senden başkası

Ne müfettişini gördüm ne müdürünü

Mezun olamadım sevdan okulundan

Sana değil kadere yıllara hesabım

Öfkemiz birşey değiştirmiyor

Bu hayat üniversitesine, ne kadar çalışsam

Muhasebem yetmiyor be sevdalım

03,03,2005

Ümraniye   İstanbul

[email protected]', 'Dağlarına çıkılmıyor sevdamın Ne dalı kalmış ne budağı Kırılmış gönül duygularım Tutmuyor ne elim, nede ayağım Sana değil kadere, yıllara he...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/muhasebem-yetmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Merhabaya Özlem Duyanlardanım', 'bir-merhabaya-ozlem-duyanlardanim-volkan-yoruc-yskbo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben herşeyin farkındayım

Uçan kuşun kanatlarındaki sesten hüznü anlarım

Ben farkındayım

Susarken de sesini duyarım

Bilirim

Görmeden gittiğim sisli şehirleri

Yürürüm

Lakin sen göremezsin beni

Diken diken olmuş çiçeklerin ardından ben seni görürüm

Ben herşeyin farkındayım

Dalga dalga olurken sevdiğim o hoyrat deniz

Ben o dalgaların arasından boğulurkende seni duyarım

Yüzüm sensizliğinden beridir güneşe hasret

Ellerim sensizliğinden beridir duvara nefret

Sessizliğin artık yakar da kül eyler beni

Bir merhabaya özlem duyanlardanım,  sen beni öyle farzet', 'Ben herşeyin farkındayım Uçan kuşun kanatlarındaki sesten hüznü anlarım Ben farkındayım Susarken de sesini duyarım Bilirim Görmeden gittiğim...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-merhabaya-ozlem-duyanlardanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İllede Sen', 'i-llede-sen-hasan-cam-o394l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar geçse, bitsede ömür

Ben yine beklerim

Sabır taşların anıt gibi

Sen gideli sevdam

Bir abide, bir abide içimde

Fırtınalar oldun ömrüme

Her ezan, duaların dilimde

Neylerin çalsada gönlümde

İllede sen, illede sen

İllede sen, gurbetim

Ecel gelse, ahretimsin

Girmem cennetime

Sen olmadan sorgu meleğim

Korlarda yanayım

Can vermem, can vermem azraile

Fırtınalar oldun ömrüme

Her ezan duaların dilimde

Neylerin çalsada gönlümde

İllede sen, illede sen

İllede sen, gurbetim

10  03 2005

Ümraniye   İstanbul', 'Yıllar geçse, bitsede ömür Ben yine beklerim Sabır taşların anıt gibi Sen gideli sevdam Bir abide, bir abide içimde Fırtınalar oldun ömrüme ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/illede-sen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kemal', 'kemal-cumhur-karaca-4z9vr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Epey zaman oldu; 

Biri tarafından

''- hey delikanlı! '' diye

seslenilmeyeli..

Öyle ya! artık yaş kemale erdi...

- Kemal mi? 

Hıh! elliikisinde can verdi....', 'Epey zaman oldu;  Biri tarafından ''- hey delikanlı! '' diye seslenilmeyeli.. Öyle ya! artık yaş kemale erdi... - Kemal mi?  Hıh! elliikisinde...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Karaca']::text[], 8.5, '{"poet":"Cumhur Karaca","poet_slug":"cumhur-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kemal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Silip Gidemezsin', 'adini-silip-gidemezsin-hasan-cam-vu8hy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adını silip gidemez’sin, bilmediğin boş yarınlara

Dönüpte bir bak, acı tatlı yaşadığın eski anılara

Ömürmü tamamladın, feryatsız, yarınsız hayatlara

Taktığın yüzük neye yarar, buhar olursa sevdama

.

İçimde korkum, solup gideceksin hangi umutlara

Bırak gönül, Açma karanlığı, beyaz kalsın yarınlara

Ben açtımya aşkıma kapımı, cennet gönül sarayımı

Vermesin şifresini, onun sarayında kendi kalsın

Silme gönlüm iclali, menekşeler içinde yatıp kalksın

Tufanlar sarsa etrafın, bırak seni mutlu sansın

Burkma sevgi dolu yüreğim, yanma dünü ararsın

İçim beni yaksın, gözünde gurbete gülücük aksın

Yonca kolyem, boynunda hatıram, sallana kalsın

Sevgisi buysa, koynuna yar, koluna çanta sansın

Duvar ör sılana, gurbet taşından sıra sıra, vize alsın

Sevgi gücü varsa bırak, duvarları kendi çıkıpta aşsın

23,06,2005,

Ümraniye   İstanbul', 'Adını silip gidemez’sin, bilmediğin boş yarınlara Dönüpte bir bak, acı tatlı yaşadığın eski anılara Ömürmü tamamladın, feryatsız, yarınsız h...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/adini-silip-gidemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap günü', 'hesap-gunu-gulseren-onay-htc1l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aylardan haziran....

Herşeyde yenik hissetti çocuk

Ve yenik çıktı ders yılından...

Gençliğin ürkekliği,

Çaresizliğin cesaretiyle

Terketti bedenini 

Mavi derinliğe... 

Oysa yapacak çok şeyi var daha,

Aşık olabilir,

Kırık dökük sevda şiirleri yazabilir,

Yaşadıklarıyla

Yaşlanabilir....

Ama,

O genç olmayı,

Hesapsız yaşamı,

O 17 sinde kalmayı seçti...

Bir türkü söyleyelim dostlar

Birlikte,

''Ham meyvayı kopardılar dalından''

GÜLSEREN ONAY', 'Aylardan haziran.... Herşeyde yenik hissetti çocuk Ve yenik çıktı ders yılından... Gençliğin ürkekliği, Çaresizliğin cesaretiyle Terketti be...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hesap-gunu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle Gönül', 'dinle-gonul-hasan-cam-r9hur', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dinle gönül dinle

Yağız deli kanlını

Yağız deli kanlını dinle

Bak eserini gör, gördün işte

Bıraktığın zaman tüneline

Boşver geç, boşver geç beni

Şakağına aklar düşmüş eserini

Şimdi bir efsane, mazi dersin

O gençliğim, artık yok bende

Geç boşver, geç beni

Sesimse duydun, çöküşümü gördün

Ben taptığın sılan, bulmuşken seni

Yine sevgimi, gurbetlere böldün

Eğleşme gönül, eğleşme benle

Dinle, yağız deli kanlını dinle

Yine meze yap duyguna, sözlerine

Ama sevgimi bölme

Hani ölümüne verdiğin söz

Ayrılık yoktu

Dinle gönül dinle

Ben kemale çoktan erdim

Sular gibi coşma gönlümde

Boş ver geç, geç beni

Eminol gönül

Son sözün, ebediyete götürecek beni

Eminol eminol

12,03,2005

Ümraniye   İstanbul', 'Dinle gönül dinle Yağız deli kanlını Yağız deli kanlını dinle Bak eserini gör, gördün işte Bıraktığın zaman tüneline Boşver geç, boşver geç ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dinle-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Kulesi', 'kiz-kulesi-hasan-cam-lkej4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hangi yandan baksam seyrine, düşünmek lazım

Saraydan, galatadan, boğazdan, Üsküdar salacaktan

Gecen gündüzünden farklı, zevki sefanla abidesin

Bakış noktası insanlara, gemilere, konaksın martılara

Hoş geldin dercesine karşılarsın, gemileri iki yandan

Gülhaneden dürbünler, üsküdar salacak kordon boyu turlar

Kıyıboyu yerlerde, gazete üstü mezeler, akşamcı kafeler

Belgeseller harici bilmez çoğu, geçmişini, tarihini

Hikayen çok anlatılanlara kalırsa, derin bir efsanesin

Herkese tavsiyem çayını içmek, okumak tanımak geçmişini

Aah kız kulesi, simgesisin güzel boğazın, istanbulun

Erzurum çifte minare, denizli horozu urfa balıklı gölü gibi

Yaşamak lazım seni, deniz kokunu çekerek içten içe

Korkularım var senden gelecekte, ne kadar kalırsın ayakta

Kara tankerler yanı başında, bir gün patlayacak diye

Simge oldun yıllarca kibrit kutularına, aldılar seni senden

Odlumu vakfın, bedel ödendimi sana, kazandılarya senden

Farkında olmadan ceplerimizde taşıdık seni, amblemini

Bilmiyorduk ki, ne gönüller, ne sevgiler fethettigini

Dedimya, yaşamak, tanımak lazım, kültürünü, medeniyetini

Kız kulesi,

14  06  2005

Ümraniye   İstanbul

[email protected]', 'Hangi yandan baksam seyrine, düşünmek lazım Saraydan, galatadan, boğazdan, Üsküdar salacaktan Gecen gündüzünden farklı, zevki sefanla abides...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kiz-kulesi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılsın Bergkamen', 'yikilsin-bergkamen-hasan-cam-u06du', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oldumu sılam, gözyaşı döküşün

Ahlara, vahlara, geri dönüşün

Yalnızlığa bürünüp, odalarda üşüyüşün

Titremedimi yüreğin, bunca sene

Yıkılsın bergkamen, yansın sokaklarıı

Güneş vurmasın, buz tutsun yolları

Ulaşmasın başka sevgiye, ben varken

Çiçek açmasın, kurusun gül dalları

Ömürse verdin, kemalede erdin

Olmadı sılam, sen yılları devirdin

Yürek bir ama, başka kolda sevgin

Sevdana değil sen ayrılığa bezdin

Yıkılsın bergkamen, bahar uğramasın

Yaşanmasın aşk, geçmesin yılların

Istırap gör, şehvet görmesin odağın

Varsa başka sevgin, tütmesin ocağın

14,03,2005

Ümraniye     İstanbul', 'Oldumu sılam, gözyaşı döküşün Ahlara, vahlara, geri dönüşün Yalnızlığa bürünüp, odalarda üşüyüşün Titremedimi yüreğin, bunca sene Yıkılsın b...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yikilsin-bergkamen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gibi Sev Beni', 'ben-gibi-sev-beni-hasan-cam-j63ma', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben gibi sev beni

Kaybetsende bedenini, herşeyi

Sev sev, öyle sevki yürekten

Aşk pusulan dönmesin

Taa derinden hisset beni

Ben gibi sev beni

Göz yaşların anlatsın sana beni

Arama başka ufuklarda

İçindeki boşluksa aşk

Sevdalarında bulasın beni

Ben gibi sev beni

Sevda uykularında, haramsa gecelerin

Aydınlık olmasın  sabahın

Yumduğunda gözlerini

Başka beden sarsada kolların

18,08,1982,

Ümraniye   İstanbul

[email protected]', 'Ben gibi sev beni Kaybetsende bedenini, herşeyi Sev sev, öyle sevki yürekten Aşk pusulan dönmesin Taa derinden hisset beni Ben gibi sev beni...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-gibi-sev-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-nurdan-elver-s2367', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir aşktır yaşamak; 

-siz’li ama’larda dahi...

Bir aşktır yaşamak; 

Fonda çalan müziğin ritmini,

Dalga dalga kokan nergislerle hissederek.

Bir aşktır yaşamak; 

Yüreğimin inceden inceye kanat çırpınışlarında,

Tüm dualitelerle görünen.

Bir aşkı yaşamaktır yaşamak; 

Yokluğunda bile dokunabilmektir O’na.

Sıcaklığını, kelimelerini, varlığını yanında hissedebilmektir.

Tadı damağında kalırcasına içtiğin şarabı hep

Hafızalarda capcanlı tutabilmektir.

Yaşamak aşkıyla yanıp tutuşurken; 

Hayata tekrar aşık olmak,

Sevgiliye tekrar aşık olmak,

Notalara tekrar aşık olmak,

Çiçeklere tekrar aşık olmak,

Güneşe, kuşlara tekrar aşık olmak,

Yağmura, kara tekrar aşık olmak,

Denize, rüzgara tekrar aşık olmak,

Aşka aşık olmak, tekrar tekrar...', 'Bir aşktır yaşamak;  -siz’li ama’larda dahi... Bir aşktır yaşamak;  Fonda çalan müziğin ritmini, Dalga dalga kokan nergislerle hissederek. B...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yasamak-141-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnadına', 'i-nadina-nurdan-elver-laib4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tersinmezliğinde hayatın 

İçtim yudum yudum hüzünleri. 

Dengesizliğinde özlemlerin 

Tattım alev alev acıları. 

Çırpıntısında bebek yüreğinin 

Döktüm damla damla gözyaşlarını. 

Ey ölümsüz gece! 

Ve ey karanlık sabah! 

Rüyalara mı gömmedin başımı! 

Yastıklara mı dayatmadın! 

Sırılsıklam yağmurlarla mı ıslatmadın gözpınarlarımı! 

Doğmasın güneş, 

Batmasın ay! 

Yıldızsız geceler çarpılsın! 

Devran dönsün tersine! 

Yıkılsın tüm umutlar! 

Mutsuzları uyandırsın 

En aydınlık gece! 

Kapkaranlık sabahlar umutlansın! 

Ay doğsun gündüze, 

Güneş batsın geceye! 

Tersinmezliğinde hayat, 

Tersinsin bana inat!', 'Tersinmezliğinde hayatın  İçtim yudum yudum hüzünleri.  Dengesizliğinde özlemlerin  Tattım alev alev acıları.  Çırpıntısında bebek yüreğinin...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/inadina-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirim Ben', 'bilirim-ben-hasan-cam-gzqnn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmurlu bir günün sabahı

Burkuldu yanık yüreğim

Sitemin ağır geldi gülüm

Bir şiir etmezsin deyişin

Bilirim ben, tesbih taşları gibi

Zikretmeyi ağzımda ismini

Bilirim, kalbime yazdığın adresi

Yirmi sekiz yıl, gurbet sokağını

Alacaklıydın aşktan, sevgiden

Yılların farkı, vadesi, zamanı vardı

Bende hacizliydim sana gönülden

Başka ifademi alacak varmıydı

Bilirim ben tesbih taşları gibi

Zikretmeyi ağzımda ismini

Bilirim kalbime yazdığın adresi

Yirmi sekiz yıl, gurbet sokağını

19,02,2005,

Ümraniye   İstanbul', 'Yağmurlu bir günün sabahı Burkuldu yanık yüreğim Sitemin ağır geldi gülüm Bir şiir etmezsin deyişin Bilirim ben, tesbih taşları gibi Zikretm...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bilirim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-nurdan-elver-9qntp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen...

Derin bir iz.

Sen...

Özlemim.

Sen...

Güneşim.

Sen...

Canım.

Sen...

Biricik.

Sen...

Aynadaki ben.', 'Sen... Derin bir iz. Sen... Özlemim. Sen... Güneşim. Sen... Canım. Sen... Biricik. Sen... Aynadaki ben....', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-579-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Kollardasın', 'baska-kollardasin-hasan-cam-kl6a4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgi, saygının varlığını anlattı bana

Aşksa, dünyada günahların engüzelini

Bir bahçe düşün, fidanların yeşerdiği

Körpe yavrular, kuzular ve ağaçlar

Bu gün sevgililer günü, on dört şubat

Soğuk, sıcaklığını ençok aradığım gün

Sen başka garlarda, ben başka gurbetim

Hasaret sarmış bİizi, başka kollardasın

Verdiğim kolyem, kasalarda tozlanmış

Verdiğim güller, odalarda solmuş şimdi

Yokluğunu anlattı, boş yollar bana bugün

Dalgalar yok, rüzğar yok, kuşlar ötmüyor şimdi

Sen gurbet, bense, sılaydım yıllar boyunca

Hasretini çektiğim en acı gün, bu gün

Uzatsanda, ellerini tutamam ben

Kaybolan yıllarım, başka kollardasın

14,02,1986,

Ümraniye  İstanbul

[email protected]', 'Sevgi, saygının varlığını anlattı bana Aşksa, dünyada günahların engüzelini Bir bahçe düşün, fidanların yeşerdiği Körpe yavrular, kuzular ve...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/baska-kollardasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz', 'yaz-nurdan-elver-i02wz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşini, ağacının yapraklarına yaz,

Yaz ki kaynaşmış güzelliklerini doya doya koklayabileyim.

Mutluluğunu, sesinin tellerine yaz,	

Yaz ki birlikteliklerini doya doya duyabileyim. 

İçindekileri, gözlerimin mührüne yaz, 

Yaz ki kalbindeki coşkuları doya doya görebileyim.

Sevgini, ruhunun derinliklerine yaz,

Yaz ki sonsuz samimiyetini doya doya hissedebileyim.

Doğruluğunu, denizinin dalgalarına yaz,

Yaz ki yükseklerde köpürdükçe doya doya yaşayabileyim.', 'Güneşini, ağacının yapraklarına yaz, Yaz ki kaynaşmış güzelliklerini doya doya koklayabileyim. Mutluluğunu, sesinin tellerine yaz,	 Yaz ki b...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Elver']::text[], 8.5, '{"poet":"Nurdan Elver","poet_slug":"nurdan-elver","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yaz-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet İle Sıla', 'gurbet-i-le-sila-hasan-cam-c5lmb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir özlem, bir hasrettir, gurbet ile sıla

Mecnunun leylası, keremin aslısı gibi

Efsaneleşir yaşadıkca, sığmaz sayfalara

Örnektir öykülere, şiirlere, seven gönüle

Sen gurbet, ben sıla, olmadı ortak noktamız

Yanan yüreğimiz, küllenen sevgimiz hariç

Boşa gelmedik bu sayfalara, değilmiyiz ki

Cumali, öznur,sevim, gönül, hasan, kera,laz kızı

Birer duygu yumağı, bu altın kalpli yürekler

Kimi sevda, kimi gurbet, sıla, özlemi yüklü

Bende sılan, gurbetine yanık, içi dolu ürkü

figen,ekremce,surpil,alize,binnur gibi şiir küpü

Selam şiir dostlara, selam gurbetime selam

Yirmi sekiz yıllık hasretim, özlemim ateşten kor

Taktığımız yüzük ayrılığa olsun idam halkam

Seviyorum dostlar, bu benim kara sevdam 

Artık sözüm mutluluğa, dağlara, kuşlara, dostlara

Veda olsun özleme, hasrete, içimde kanayan yaraya

Mutluluk şarkıları çalsın, çınlayan kulaklarımda

Selam dostlar, bu benim kara sevdam, kara sevdam

Teşekkürler, 

Teşekkürler, gurbetime..

08,06,2005,

Ümraniye   İstanbul', 'Bir özlem, bir hasrettir, gurbet ile sıla Mecnunun leylası, keremin aslısı gibi Efsaneleşir yaşadıkca, sığmaz sayfalara Örnektir öykülere, ş...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gurbet-ile-sila-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bence', 'bence-hasan-cam-gtr5k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'GÖNÜL  >    sevgi, istek, düşünüş...

                      yürekte var olan, duygu kaynagı...

AŞK       >    sevgi yumagı... 

                      bir arzulayış, bir arayış, baglılık tutku...

ŞEHVET>    günahların engüzeli, doyumsuzluk..

                      zevklerin verdigi, tat damagı...

DOGUŞ >    seçme hakkı olmayan..

                      atılan tohum, dünyaya geliş

KADER >     insana verilmiş.. 

                      çevrim dışı rota, bir yazı

YAŞAM >     iki ezan arası geçen zaman...

                      istemesende, okunur kulaga..

                      birisi, ismin verildiginde

                     digeri, musallaya kondugun an...

MAHŞER > dünyada, aklı barik yaşamın... 

                     günaklarını, sevaplarını, dogrucu ve

                     riyakarlarını, ayırıcı baki yol....

16,03,2005

Ümraniye   İstanbul', 'GÖNÜL  >    sevgi, istek, düşünüş...                       yürekte var olan, duygu kaynagı... AŞK       >    sevgi yumagı...                ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bence-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorulmadım', 'yorulmadim-i-brahim-halil-demir-iqhvu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana seni seviyorum demekten,

Verdiğin ağıları ölesiye içmekten,yorulmadım.

Gece gündüz seni düşünmekten,

Daim sana mısralarca şiir yazmaktan,yorulmadım.

Büyüleyici gözlerine bakmaktan,

Uzaktan seni adım adım takip etmekten,yorulmadım.

Aynalarda suretini aramaktan,

Sana güzel görünmek için saçlarımı taramaktan,yorulmadım. 

Gönderdiğin mektupları defalarca okumaktan,

En güzel cevapları yazmaya çalışmaktan,yorulmadım. 

Gördüğüm güzelleri sana benzetmekten,

Rengarenk gülleri senin için dermekten yorulmadım.

Saçlarına kır çiçekleri takmaktan

Geleceğimiz için mutlu hayaller kurmaktan,yorulmadım.

Issız ve sensiz gecelerde kalbimin sesini dinlemekten

Geceler boyu gözlerime uykunun girmeyişinden yorulmadım.

Seni sana sormaktan yolunu gözlemekten

Ulu dağların arkasında seni aramaktan,yorulmadım.

Hatırın için her olur olmaza boyun eğmekten,

Suya hasret çorak arazilere fidan dikmekten, yorulmadım.

Güneşin doğuşunu ayın batışını seyretmekten,

Yıldızlarla semaya ismini yazmaktan,yorulmadım.

Aklıma geldikçe evimin duvarlarına resmini çizmekten, 

Hazan mevsiminde patika yollarda sensiz yürümekten,yorulmadım. 

Sevdiklerimin çocuklarına adını vermekten,

Sana toz kondurmamak için kavga etmekten,yorulmadım. 

Falcılara gidip senin için fal baktırmaktan, 

Derviş meclislerine gidip seni dilemekten,yorulmadım. 

Seher vaktinde kuşların cıvıldaşmasını dinlemekten

Yorgun yüreğimin en güzel köşesinde seni ağırlamaktan yorulmadım.

Bir gün aniden kapımın tokmağını çalabilme olasılığından,

Evimin içine güneş gibi girip aydınlatma umudundan

yorulmadım.

Evimdeki reyhanlardan seni koklamaktan,

Onları sularken seninle konuşuyorcasına sohbet etmekten,yorulmadım.

Işıklar söndükten sonra hayalinle mutlu olmaktan,

Ve mutluluğumun resmini yapabilmekten,yorulmadım.

04.07.2005', 'Sana seni seviyorum demekten, Verdiğin ağıları ölesiye içmekten,yorulmadım. Gece gündüz seni düşünmekten, Daim sana mısralarca şiir yazmakta...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil Demir']::text[], 8.5, '{"poet":"İbrahim Halil Demir","poet_slug":"i-brahim-halil-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yorulmadim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincik Çiçekleri', 'gelincik-cicekleri-hasan-cam-t73bg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Değişmedi gönlümün sayfaları

Ne yazdınsa o var, virgülüne kadar

Bıraktığın hasretin, özlemin

Aşkının acı girdabı var dinmeyen...

Koşarım her baharda kırlara

On yedisinde kırmızılı prensesim

Al fistanlı, seni hatırlatır bana

Kırmızı, nadide, gelincik çiçekleri

Antoloji gibi dolduda şu gönlüm

Dokunamadım boş yapraklarına

Kiminde gözyaşın, kiminde gülün var

Çevirdikce sayfaları, hasretin kokar

Koşarım her baharda kırlara

On yedisinde, kırmızılı prensesim

Al fistanlı seni hatırlatır bana

Kırmızı, nadide, gelincik çiçekleri

22,06,2002

Ümraniye   İstanbul', 'Değişmedi gönlümün sayfaları Ne yazdınsa o var, virgülüne kadar Bıraktığın hasretin, özlemin Aşkının acı girdabı var dinmeyen... Koşarım her...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gelincik-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Coşup Gelen Rüzgarı', 'cosup-gelen-ruzgari-hasan-cam-y4irw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ömrümce, gönlümde, sensin demen yetmezki..

kader gülümsün, yıllarca gönül bahçemde..

setler, duvarlar, barajlar kurman yetmezki..

gönül sevdam bu gurbet, dagları delmezmi..

coşup gelen şu rüzgarı, durduramazsın..

depremler oldun gönlümde, yıkılacaksın..

sevdan ateşiyle yandım,yandım sel olup geldim..

aşklar yaşasanda, benle sarsılacaksın..

aşk gözyaşındı, sevda gülümü sulayan..

bu gönlümde çiçek açtın, baharlarımsın..

kuru yaprak misali, diyar, diyar uçsan..

kış olupta, karlar gibi üstüme yagsan..

coşup gelen şu rüzgarı, durduramazsın..

depremler oldun gönlümde, yıkılacaksın..

sevdan ateşiyle yandım, yandım sel olup geldim..

aşklar yaşasanda, benle sarsılacaksın..

20,04,2005,

Ümraniye  İstanbul', 'ömrümce, gönlümde, sensin demen yetmezki.. kader gülümsün, yıllarca gönül bahçemde.. setler, duvarlar, barajlar kurman yetmezki.. gönül sevd...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cosup-gelen-ruzgari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemezdim', 'i-stemezdim-hasan-cam-fwuoe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'senden ayrılmak istemezdim, asla..

ekini, biçtigim gibi aldım ben..

ne olur, anla artık kaderimi..

istemezdim, ayrılmayı gerçekten..

seni seviyorum, bunu unutma..

ezbere gittim, bu sevdada kızma.

varsay beni, heryerlerde ugruna..

ihanet etmek, istemezdim sana..

yoruldum artık, buraya kadarmış..

oyunun sonu geldi, kafam karışık..

rendele, bu umutları kalbinden..

umutlarını, kırmak istemezdim..

mutlulugumuzu, bende isterdim..

affet beni artık, herşey için geç..

şerbetim oldun, sen benim heran..

kırdım, hayallerini umudunu..

ışıldayan tekşey, sendin hayatta..

mızrakla, vurulmuşa döndü kalbim..

mızrakla,vurulmuşa döndü kalbim.

mızrakla, vurulmuşa döndü kalbim...

23,03,2005,

Ümraniye    İstanbul', 'senden ayrılmak istemezdim, asla.. ekini, biçtigim gibi aldım ben.. ne olur, anla artık kaderimi.. istemezdim, ayrılmayı gerçekten.. seni se...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/istemezdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Nasıl Doymalı', 'sana-nasil-doymali-hasan-cam-6u85n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Açlığım var gönlümde, gözümde, sözümde

Hasretim sevgine, idealim, tutkum içimde

Doyur beni sevgine, aşkına, şehvetine

Rüya değil gecemde, gerçek ol gözüme

''Sana nasıl doymalı''

Şiirler, şarkılar, nağmelermi yazmalı

Aldığın nefes, bastığın toprakmı olmalı

Baş koyduğun yastık, gözünde yaşmı olmalı

Sana nasıl, sana nasııl, sana nasıııl doymalı

Seni sevdim ömrümce, saymadım gün, gece

Seçemedim hayatmı, bizmi, bir bilmece

Olamadık kumrular, vermedin minik serçe

Bilki acım dinecek, ecelim gelince

''Sana nasıl doymalı''

Elinde gül, bahçende salıncakmı olmalı

Ettiğin dualar, yaptığın secdemi olmalı

Günahlarını alıp, cennetinmi olmalı

Sana nasıl, sana nasııl, sana nasıııl doymalı

02,04,2005,

Ümraniye  İstanbul', 'Açlığım var gönlümde, gözümde, sözümde Hasretim sevgine, idealim, tutkum içimde Doyur beni sevgine, aşkına, şehvetine Rüya değil gecemde, ge...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-nasil-doymali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tay dedim cız dediler', 'tay-dedim-ciz-dediler-suna-aras-hfkes', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çerçi yorgunu gülüş

Ve şiir

Turşunmuş tadı ağzımın.

Bir uçuk çalıntıydı şuramda sabır

Tükendi aldanışın sırtlığında

Kaldım

Akrep tadı bir zamanın

Patlak dudaklarında.

Al beni

Tanrı’nın aşkıyım ben

İsa’yı babasız doğuran Meryem

Yalan…

Bir avuç kül Aslı’dan

Leyla’dan sahra çaldım

Bir sevdayı kaç renge bölmemiz gerek daha

Yensik nöker dil bilmez

Üstüne çocukların

Mavi boncuklar astım.

Ağrı

İki memesidir anamın ağrılı

Tay dedim cız dediler

Koptu velvele

Koşup Kerbela’yı sildim tarihten

Ateşe haçlandı Musa

Kuşun yaktı dilime

Ruhumda ki jandarma.

Çamura kaçan topaç 

Dünya ki avuçların

Kan sıçratan saçımızı okşadık

Gül suretler düştük küflü kaldırımlara

Sırtımızdan yük attık.

Al yaramı tazele

Demli olsun sevdamızın kekresi

Hepimizin tırnağında

O çamurdan iz kaldı.

Al beni sevmek

Çoğul ekiyle

Siyah bir kedinin

Siyam gözlerine

Düğümle.

*Yensik(Azeri)  Düşüncesiz.

*Nöker(Azeri) Hizmet eden.', 'Çerçi yorgunu gülüş Ve şiir Turşunmuş tadı ağzımın. Bir uçuk çalıntıydı şuramda sabır Tükendi aldanışın sırtlığında Kaldım Akrep tadı bir za...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/tay-dedim-ciz-dediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O ve ben', 'o-ve-ben-abdulkadir-karaca-56r0g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Bilmediğim bir o''ya,tanımadığım bir ben''e-

O ve ben,tenden uzak ruhda birleşen peri

O ve ben sığınılan yalnızlığın siperi

Mahşere kaçan ruhun sığındığı noktada

O ve ben bulunuruz,varolanda yokta da

Kesişen çizgilerde ben yoksam da o vardır

Ben çiçeksem,o bana can verecek bahardır

O ve ben,Düş diyarı yalnızlık ülkesiyiz

Örümceğin muradı kuşun kanat sesiyiz

O ve ben raksederken bir nisan akşamıydı

Doğumu müjdeleyen bereket damarıydı

Sinmişti kundaklara süt ile misk kokusu

Gül eksik kalırmıydı,bendim onun uykusu

O ve ben,taş yollarda dikeni gül eyledik

Mecnun gibi çöllere aşkımızı söyledik

Onu arayan herkes bakınca gözlerime 

Demekki o bendeymiş,acıdım sözlerime

O ve ben kalbe geçen tılsımlı çengelleriz

Mutsuzluğun önüne çekilen engelleriz

Renklerin beldesinde renksizliğe mahkumuz

O ve ben aşk denilen sonsuzluktan mahrumuz

Gökte kuş,yerde insan,suda balık o ve ben

Dağda ateş,çölde su,rüzgarlarla danseden

O ve ben yıkıldığım noktanın dengi yalan

Zulüm köyü üstüne çöken azap,heyelan

O ve ben çiçeklere konan iki arıyız

O ve ben çile çektik artık bal almalıyız

O bende,ben ondayım,biz nerdeyiz bilmem ki

O benim can damarım ötesini sevmem ki

O ve ben,iki ayrı iki aynı o ve ben

İki yorgun,iki kalp tek sevgide birleşen

(19,04,2004)', '-Bilmediğim bir o''ya,tanımadığım bir ben''e- O ve ben,tenden uzak ruhda birleşen peri O ve ben sığınılan yalnızlığın siperi Mahşere kaçan ruh...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/o-ve-ben-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığınacaktı Gönlüm', 'siginacakti-gonlum-hasan-cam-hrh66', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varla yok arasında

Gidip geldi, şu gönlüm

Viraneyim, yıkık harabeyim

Genç yaşta soldu ömrüm

Beklediğim baharlar, yazlar gelmedi

Belki sığınacaktı, sana gönlüm

Gözlerim bakar, ama körüm

Kulağım duyar, ama sağırım

Ayağım yürür, yerinde sayarım

Aaah bilsen aah, ben yanaar, yanarım

Beklediğim baharlar, yazlar gelmedi

Belki sığınacaktı, sana gönlüm

Sılaydım, gurbetine daldım

Aşkın uğruna, ihtiyar kaldım

Ne yolum bitti, ne de geldi sonum

Yıllarıım ardına, baka kaldım

Beklediğim baharlar, yazlar gelmedi

Belki sığınacaktı, sana gönlüm

07,07,1992,

Ümraniye   İstanbul', 'Varla yok arasında Gidip geldi, şu gönlüm Viraneyim, yıkık harabeyim Genç yaşta soldu ömrüm Beklediğim baharlar, yazlar gelmedi Belki sığına...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siginacakti-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet Allahım', 'affet-allahim-hasan-cam-hx92m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hangi hakim kalem kırmış

Sevmek suç diye

Ürperiyor yüreğim yine bu gün

Tüylerim diken diken

Baş vurduğum savcılar almadı dilekçemi

Sevmenin cezası, aşkın içindedir diye

Sevmenin mahkemesi yokmuş

Ben nerden bileyim

Gözlerin sundu aşkı kalbime, suçmuş

Elimdemi, nasıl sileyim

Yokmuş yüksek merci, dolaştımda diyar diyar

Sende buldum hak, adalet, affet Allahım

Çevremde dostluklar, mutluluk var

Bendekiler riyakar, yada ben

Sevdamda anama, babama oldum isyankar

Tövbeler yetermi bilmem, seven kuluna

Secdelerimde, dualarımda, yine o var

Sende buldum hak, adalet, affet Allahım

03,04,2005,

Ümraniye   İstanbul', 'Hangi hakim kalem kırmış Sevmek suç diye Ürperiyor yüreğim yine bu gün Tüylerim diken diken Baş vurduğum savcılar almadı dilekçemi Sevmenin ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/affet-allahim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seller...', 'seller-i-brahim-ethem-bingul-06272', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benzerdi bendeki bitmez dertlere

Gökten damla damla indi yerlere

Damlalar birleşip döndü sellere

Göz yaşlarım gibi boşaldı sular...

Başlangıçta suskun, tık tık,kıpırtı

Akarken ne haşin, ne sert, ne katı

Dar buldu, garibim akarken arkı

Göz yaşlarım gibi boşaldı sular...

Kara bulutlarla geceye yanlı 

Göl etmiş yerleri, gözleri kanlı

O da ben misali ağlar, efkârlı

Göz yaşlarım gibi boşaldı sular...

www.iebingül.com', 'Benzerdi bendeki bitmez dertlere Gökten damla damla indi yerlere Damlalar birleşip döndü sellere Göz yaşlarım gibi boşaldı sular... Başlangı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seller-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğ Gönlümde', 'dog-gonlumde-hasan-cam-ns4g6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Titredi durdu bu gece, sana yüreğim 

Ne yanımdaydın, ne de rüyalarım da

Düşlerimde, gözyaşım da buldum seni

Buz gibi odamda, soğuk duvarlarda hayalin

Sabah güneşim ol ısıt beni, doğ gönlümde

Son ver, sensiz karanlık geceme, aydınlat

Bir gün, mutlu son bulsun, bitsin bu acılar

Bu son bizim, aşkımızın olsun mutlu yarınlar

Nakışlar, kilimler gibi işledin bu sevdama

Kan tutmuş yüreğimi, sen süsledin hasretinle

Bastığın halı, kilim, olamadım yer yüzün de

Yoksun yine, yerlerde yatmışım, ne olur şimdi 

Çiğneyip geçen başkası olmasın, doğ gönlümde 

Üşüdüm sensizliğime, kor tanesi ol, dol gönlüme 

Gideli dar geldi sokaklar, sar beni yanık yüreğine

Sensiz ahret im olmasın, gel, benle gir cennetine

14 02 2005

Ümraniye İstanbul', 'Titredi durdu bu gece, sana yüreğim  Ne yanımdaydın, ne de rüyalarım da Düşlerimde, gözyaşım da buldum seni Buz gibi odamda, soğuk duvarlard...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dog-gonlumde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecegin Babalarına', 'gelecegin-babalarina-hasan-cam-ryjoz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çamur balçık, ham maddesi toprak, su

Geldik, gidecegimiz yer aynı

Ötesini bilemiyorum, yada ögretmediler

Gerçek anamızı, babamızı, tanımalıyız önce

Adem ile Havva yı

Var olup gelen, damardan damara akan..

Dinlere, dillere, ırklara, meshep ve soylara

Taşınan daim, kıyamete erecek gen ler

Bugün babalar günü, şöylebir düşündüm

Önce ced di tanımak lazım aklıma yatan

Sınırlı kalmamalı sade anayla, babayla

Yarının ana babalarıda bilmeli nerden geldigini

Degilmiyiz ki, aynı candan, kandan

Önce insanı tanımak

İnsanlığı bilmek, kavramak kuşkusuz

Küçüklere sevgi, büyüklere saygı duymak

Düşünceler gibi! 

Ne fark eder dili, dini, ırkı, meshebi

Yaradanla arasıda herkesin, hepsi aynı can

Ana, baba sevgisi taşımıyormu yürekleri

Sosyal olmak lagzım böyle günlerde

Kimsesiz yaşlılara evlat, ellerini öpmek

Nice yetimlere, sahipsizlere de baba olmak

Da im, böyle oldu anlayışım

Sarmak, kucaklamak, doyurmak, giydirmek

Unuttum bugün aşkı, meşki, aklım almadı

Rahmetli yok babam

Ama etraf eli öpülecek, asa verilecek 

Ana, baba dolu,, geçmişi ne olursa olsun, insanya

Şiir ler yazamadım babama bugün

Toplumsal algı vardı içmde, paylaştım sizinle

Tüm babaların, anaların, ellerinden öperim

Nasihat olsun

Gelecegin babalarına

Üzülmesin babam yok diye, sevgiler hepinize..

19,06,2005,

Ümraniye  İstanbul', 'Çamur balçık, ham maddesi toprak, su Geldik, gidecegimiz yer aynı Ötesini bilemiyorum, yada ögretmediler Gerçek anamızı, babamızı, tanımalıy...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gelecegin-babalarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-hasan-cam-rdyyr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlıgı kazıyor beynimi, sensizim yine

Yıldızlar parlamıyor, hava puslu, ay tutuk bu gece

Ayaklarım dolaşıyor bir birine, sarhoşda degilim

Oysa bugün, heryer pırıl pırıl, günlük güneşlikti

Boş sessiz, sensiz, hanımeli kokulu sokakaklar

Yorgun ayaklarım ve duymuyor kulaklarım

Çekirgeler, havlayan sokak köpeklerinden başka

Bir farkım kaldı bu hayvanlardan, ısız gecemde.

Seni seviyorum diye, haykıramayıp ağlayışım

Uçmaktı sana, yarasa uçuşlarındaydı gönlüm

Umutlarım gibi, şimdi budandı bütün dallarım

Biz evlenemeyiz diyen sen, kanatlarımı aldın

Sen koynumda olmalıydın, odasında çocukların

Düğümlendi sözcüklerim bu gece, yutkunamadım

Söz bulamadım söyleyecek, sana ve yazdıklarıma

Nasıl diyebildin, yirmi sekiz yıl sonra ayrılalım

29,06,2005,

Ümraniye  İstanbul', 'Gecenin karanlıgı kazıyor beynimi, sensizim yine Yıldızlar parlamıyor, hava puslu, ay tutuk bu gece Ayaklarım dolaşıyor bir birine, sarhoşda...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sitem-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Boşlukta', 'zaman-boslukta-erdal-cevik-kws9v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman boşluğa düştü

Yağmur yağmıyor artık

Bayramlıklarınla dolaştığın

Bu uyuşuk dünyaya

En güzel yer değil artık

Kara bir yağmurun 

Altında ıslanan ülken

Bir şıklık istersen sen

Ya da ölmek istersen

Vaktinden önce

Başka bir yer bulmalısın birtanem

Kendine yabancı kalmalısın biraz da

Bak o zaman 

Nasıl kurtulacak ellerin

Seni evindeki yalnızlığa 

Çekmeye çalışan 

Saçına ak düşmüş annenden

Kendin giyeceksin ayakkabılarını

Hep kazanacak tuttuğun takım

Sevdiğin oyuncuya verecekler

Tüm ödülleri

Uzak bir şehirde 

Bırakacaksın böylece

Anımsadığın bütün yenilgileri', 'Zaman boşluğa düştü Yağmur yağmıyor artık Bayramlıklarınla dolaştığın Bu uyuşuk dünyaya En güzel yer değil artık Kara bir yağmurun  Altında ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Çevik']::text[], 8.5, '{"poet":"Erdal Çevik","poet_slug":"erdal-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zaman-boslukta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahlara Vahlara', 'ahlara-vahlara-hasan-cam-vkt38', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aldırma, yüzümdeki çizgilere

Aldırma, saçımdaki beyazlara

Benki seni, böylede seviyorum

Faydası olmadı, ne verdiki bize

Bırak, giderse gitsin, bitsin ömür

Ahlara, vahlara, sarılmadıkmı

Yıllarca hep, boşa ağlamadıkmı

Yine kalbimde, dikenli gülümsün

Bu aşkta, ikimizde solmadıkmı

Şu, yorgun ayaklarıma sarılm

Kalbim kırık diye, sen hiç alınma

Biliyorum, sende koşarsın bana

Mecal kaldımı, yıllardan bu yana

Bırak, aydınlanmasın ufuklarım

Ahlara, vahlara, sarılmadıkmı

Yıllarca hep, boşa ağlamadıkmı

Yine kalbimde, dikenli gülümsün

Bu aşkta ikimizde solmadıkmı

25,03,2005

Ümraniye  İstanbul', 'Aldırma, yüzümdeki çizgilere Aldırma, saçımdaki beyazlara Benki seni, böylede seviyorum Faydası olmadı, ne verdiki bize Bırak, giderse gitsi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çam']::text[], 8.5, '{"poet":"Hasan Çam","poet_slug":"hasan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ahlara-vahlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazım Koyuncu''ya', 'kazim-koyuncu-ya-erdal-cevik-m8mkv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanlar

Birer

Birer

Ölüyor

İnsanlar

Tarladan kaldırılmamış

Ekinler gibi

Doğdukları 

Yerlerde

Toprak oluyor', 'İnsanlar Birer Birer Ölüyor İnsanlar Tarladan kaldırılmamış Ekinler gibi Doğdukları  Yerlerde Toprak oluyor...', ARRAY['Türk Edebiyatı','Şiir','Erdal Çevik']::text[], 8.5, '{"poet":"Erdal Çevik","poet_slug":"erdal-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kazim-koyuncu-ya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silkelenme!', 'silkelenme-asima-azra-nrfiz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceyi mi arıyorsun ışığı mı

Denizi mi dalga kıranı mı? 

Cennet nerede aradığına bağlı…

Kaybettiklerine mi yanıyorsun

Kazanamadıklarına mı? 

Hayatın taban puanı esrarlı…

Pişmanlıkların mı ağır çekiyor

Hiç yaşayamadıkların mı? 

Darası mezar taşlarında saklı…

Beşiktaş

01.07.2005', 'Geceyi mi arıyorsun ışığı mı Denizi mi dalga kıranı mı?  Cennet nerede aradığına bağlı… Kaybettiklerine mi yanıyorsun Kazanamadıklarına mı? ...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/silkelenme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acil Servis', 'acil-servis-erdal-cevik-8wr7n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uyuyamadığım gecelerin 

Sabahlarında

Hep karamsar olurum

Açarım bütün yaralarımı

Nöbetçi doktoru olmayan 

Bir acil servis niyetine

Teninin dokunduğu

Yerlerde otururum', 'Uyuyamadığım gecelerin  Sabahlarında Hep karamsar olurum Açarım bütün yaralarımı Nöbetçi doktoru olmayan  Bir acil servis niyetine Teninin d...', ARRAY['Türk Edebiyatı','Şiir','Erdal Çevik']::text[], 8.5, '{"poet":"Erdal Çevik","poet_slug":"erdal-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/acil-servis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Ben Büyüyeceğim', 'baba-ben-buyuyecegim-sait-muharrem-say-e1qsg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Oğlum''dan-

Baba ben büyüyeceğim,

Kollarım uzayacak

Ve aya uzanıp sonra

Çekip yere indireceğim

Üzerine bineceğim 

Baba ben büyüyeceğim.

-Oğlum''a-

Oğlum büyüyeceksin 

Yüreğin büyüyecek

Sevgin büyüyecek

Öyle ışık saçacaksın ki

Ay seni davet edecek 

Sevineceksin

Bırak ay yerinde kalsın

Sen aya yükseleceksin

Ay gibi beyaz

Ay gibi ışıklı

Ay gibi eşsiz oğlum

(25.07.2004)', '-Oğlum''dan- Baba ben büyüyeceğim, Kollarım uzayacak Ve aya uzanıp sonra Çekip yere indireceğim Üzerine bineceğim  Baba ben büyüyeceğim. -Oğl...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baba-ben-buyuyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı', 'tanri-hekim-coskun-usqz7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin bana bıraktığın 

Loş bir hücrenin penceresinden bakar gibiyim

Tanrı dualarıma sağır ve dilsiz

Kafam bedenimden ağır

Yüreğimde bir yangın

Çığlık çığlığa bağırmak istiyorum

Korkuyorum

Bağırdıkça dağlanacak yüreğim

Ya ben istemesini bilmiyorum

Ya da tanrı terk etmiş bu diyarları.

Biz ikimiz

Yani ben ve benden daha ötesi

Yani tüm ezilmişlik

Hiçbir şey

Koca bir hiç tanrı nazarında olsa gerek,

Tanrıyı varsaydığımız da oldu

Yok saydığımız da,

Biz büyüdük dünya küçüldü gözlerimizde,', 'Senin bana bıraktığın  Loş bir hücrenin penceresinden bakar gibiyim Tanrı dualarıma sağır ve dilsiz Kafam bedenimden ağır Yüreğimde bir yang...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tanri-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Bekle beni hayat*', 'bekle-beni-hayat-dilek-eliagir-2r69a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir şarkı mırıldandım..

dün gece…

seni hatırlattı yine,

bu deli  yüreğime…….

bendeki seni anlattım..

boş odalara…..

yitik sevdamın….

yitik düşleri..

geldi aklıma….

gözyaşlarım….

yüreğime yağdı….

derler ki…

”Aşk söyletir”…adamı….

duy sesimi ey “yar”….

sevdim…

sevdim….

hem çok sevdim….

ne varki…

sensizliğe inat….

seninle yada sensiz…

yaşayacağım bu hayatı…

gülen gözlerle….

umutla….

İnatla….

sevgiyle….

kulaklarımda sevdamın 

ayak sesleri…

gözbebeklerimde…

geleceğin …

tebessüm eden düşleri….

Sırtımda umutlarım …..

…..hayallerimde bir dev adam….

İçimde mevlamın verdiği

inanç…..

Bekle beni hayat.... geliyorum…..', 'bir şarkı mırıldandım.. dün gece… seni hatırlattı yine, bu deli  yüreğime……. bendeki seni anlattım.. boş odalara….. yitik sevdamın…. yitik d...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eliağır']::text[], 8.5, '{"poet":"Dilek Eliağır","poet_slug":"dilek-eliagir","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bekle-beni-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizi Dinlerken-1', 'denizi-dinlerken-1-sait-muharrem-say-qs1x2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşı kadar zaman önce,

İçine üflenen ruh çıkıp gitmek isterken,

Ölüm hediyedir bazısına bazen

Ömürleri çevrilen uzun metrajlı bir komedi filmi değilde,

Dram olmuştur, hercai karanlık her baharında, her kışında.

Bak demek gelir içimden böylesine,

Bak şu deniz kıyısındaki iki çocukluk arkadaşına,

Gelecekleri, tutkuları uğruna,

Yaşam savaşına cephe açtıkları

Uzaklardan, 

Yalnız deniz sesi dinlemeye gelmişler,

Biralarını yudumlarken,

Gözleri nasılda sevinç sevinç ışıldıyor...', 'Yaşı kadar zaman önce, İçine üflenen ruh çıkıp gitmek isterken, Ölüm hediyedir bazısına bazen Ömürleri çevrilen uzun metrajlı bir komedi fil...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/denizi-dinlerken-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-taner-nisanci-yohvf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ahu zardayım ah,figan eylerim

Biçareyim dost dilinden söylerim

Gözyaşım kanlıdır nice ağlarım

Gelip de yaramı neden sarmazsın

Yaralarımı deştin hep kanıyor

Bülbülü şeyda,gül adın anıyor

Tutuştu sinede yürek yanıyor

Duy derim sesimi neden duymazsın

Sen gül, oyna,oynaş, şen ol, neşelen

Gurbet elde ben olayım üzülen

Alın yazımsın bağrıma çizilen

Görüp de halimi neden sormazsın

Bir Garip benim; Kul kölen olayım

Cemalin görüp menzile varayım

Canı canan ten kafese sarayım

Verdiğim selamı neden almazsın

	13/10/2004

NOT:Anadolu Sevdası adlı şiir kitabımızdan(Gündüz yayınları-2005)', 'Ahu zardayım ah,figan eylerim Biçareyim dost dilinden söylerim Gözyaşım kanlıdır nice ağlarım Gelip de yaramı neden sarmazsın Yaralarımı deş...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/neden-161-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu mu Ahde Vefa,Bu mu İnsanlık?', 'bu-mu-ahde-vefa-bu-mu-i-nsanlik-dursun-elmas-ovrp5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En hassas yerimden vurdun sen beni

Varlığımı inkâr ettin,payladın.

Rüsva ettin,elâleme sen beni

Bu mu ahde vefa,bu mu insanlık? 

Bu yüce dâvâya nasıl da kıydın? 

Sorumluluk bende dedin sıyrıldın.

Verdiğin sözlerin hepsinden caydın

Bu mu ahde vefa,bu mu insanlık? 

Ne belâlar açtın,garip başıma

Zehir kattın,tatlı iken aşıma.

Hangi yüzle çıkacaksın karşıma

Bu mu ahde vefa,bu mu insanlık? 

Dâvaya ihanet sizler ettiniz,

Sayayım da görün neler ettiniz

Bir titreği,baştacımız ettiniz

Bu mu ahde vefa,bu mu insanlık? 

Tahkime kabul de,ikize evet

Atmayın imzayı dedik; ihanet

Doğru söyleyene verdiniz zulmet

Bu mu ahde vefa,bu mu insanlık? 

Erciyes''te astın,mecliste sustun,

Zulüm karşısında,habire pustun,

Bütün şiddetini hep bize kustun,

Bu mu ahde vefa,bu mu insanlık? 

Af çıkardın hırsıza ve soysuza,

Teslim oldun kara yüzlü nursuza

Mahkum ettin Türk''ü bir namussuza

Bu mu ahde vefa,bu mu insanlık? 

Söyler misin lütfen Halûk ne yaptı,

Askere,polise mermi mi attı,

Vatanı mı sattı,bayrak mı yaktı? 

Bu mu ahde vefa,bu mu insanlık? 

Sizi o makama,biz getirdik biz,

Bizler olmasaydık,sizler kimdiniz

Hakkımızı haram ediyoruz hepimiz

Bu mu ahde vefa,bu mu insanlık?', 'En hassas yerimden vurdun sen beni Varlığımı inkâr ettin,payladın. Rüsva ettin,elâleme sen beni Bu mu ahde vefa,bu mu insanlık?  Bu yüce dâv...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bu-mu-ahde-vefa-bu-mu-insanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum Hey Dost', 'dostum-hey-dost-hasan-gorgu-8ivn2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kapandır yalnızlığım

Acıların batağında

Ben uğraştım açılmıyor

Açmaya gel dostum hey dost

Kör çamurlara bulandım

Akkor  ateşlerde yandım

Sular gibi seller gibi

Akmaya gel dostum hey dost

Etraf zifiri karanlık

Tufeylinin yatağında

Fenerim yok yakılmıyor

Yakmaya gel dostum hey dost

Gurbet elde vurgunlarda

Mapuslarda sürgünlerde

Yüzüme hiç bakılmıyor

Bakmaya gel dostum hey dost

Ömür biter dünya fani

Nerede kimseler hani

Mezarıma üç beş çivi

Çakmaya gel dostum hey dost', 'Bir kapandır yalnızlığım Acıların batağında Ben uğraştım açılmıyor Açmaya gel dostum hey dost Kör çamurlara bulandım Akkor  ateşlerde yandım...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dostum-hey-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolunayın Kızına', 'dolunayin-kizina-mustafa-dogan-kuzgun-kpjce', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sahile indim yanından ayrılınca

Kalbim halâ ilk dansı yaşıyordu

Yürüdüm biraz taşlı kumsalda

Rüzgar hafiften kokunu getiriyordu

Başım döndü oturdum bir banka.

Sanki anlamıştı hoşlandığımı,

Adını sorar bakıyordu dolunay

Kızın dedim, senin kızın

acıtmak istiyordu yüreğimi,

İnatla adını sordu.

Fısıldadım ismini dolunaya,

Kahır dolu bir fısıltıyla.

Duysun istemedim, deniz

Uyanıp ta kıskanç dalgalarını savurmasın,

Köpürmesin diye dolunaya

Sadece fısıldadım.

Duymazlıktan geldi inatçı,

Daha çok acı çektirmek içindi.

Fazla dayanamadı göz pınarlarım

Bir, sel edasıyla boşaldı.

Haykırdım o zaman adını.

Duysun dedim, uyansın deniz.

Dalgaları bile durduramadı gözyaşımı.

Tekrar haykırdım:

Kızın dedim, senin parçan

Senin en güzel yüzün.

Hoşlanıyorum ondan,

Belkide aşığım ona

Deniz dayanamadı, kabardıkça kabardı,

Yakamoz kıskançlığıyla tekne bırakmadı sahilde,

Hepsini karanlık sularına aldı.

Dolunay, yavrusunu kaybetmiş

Dişi ceylan misali koşturuyordu.

Ama yüreğim halâ seni istiyordu,

Çünkü; seni seviyordu.', 'Sahile indim yanından ayrılınca Kalbim halâ ilk dansı yaşıyordu Yürüdüm biraz taşlı kumsalda Rüzgar hafiften kokunu getiriyordu Başım döndü ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/dolunayin-kizina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce sızı', 'i-nce-sizi-i-lhami-arslantas-l6ro0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökte hüzün kaynıyor 

Ağladı ağlayacak

Benim de yüreğim aynı keza

 Hazin bir yaşamın 

Tutsaklığında 

Toprak anaya benziyor

Bahtım  ve kederim

Elleri

Babamın emekçi elleri gibi çatlak.

Toprak 

Hasretle açmış göğsünü göğe

Yüzü ağustos semeresi 

Yüreği  yanık 

Elleri, dudağı çatlak

Çatlak  dudaklarıyla

Keder emecek hasretin özsuyunu

Hani denir ya..

Acı acıyı su sancıyı giderir

İşte öyle

Yanık  yüreğini ferahlatacak

Ve  doğacak birazdan 

Ebem kuşağı tüm ahengiyle

Köprüsünü kuracak renklerinden

dostluğa sevgiye al yeşil mavi beyaz 

Bir  yandan.

Çatlak dudaklar ve göğsü

Ölük  öllük kapanırken gururla 

Gül yüzlü çiçekler doğuracak gün yüzüne

Börtü böcek ve tüm hayat uyanacak

Islak  dudaklarında toprağın

Yeşeren  bir çoban döşeğinin üstünde

Dinecek yüreğimin ince sızısı', 'Gökte hüzün kaynıyor  Ağladı ağlayacak Benim de yüreğim aynı keza  Hazin bir yaşamın  Tutsaklığında  Toprak anaya benziyor Bahtım  ve kederi...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ince-sizi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sevda Şiiri', 'son-sevda-siiri-mustafa-dogan-kuzgun-1fn9w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarımın toprağı öptüğü son gecede

Haykırdım varoluşumun nedenini

Seni ölümüne sevmekti sevgili.

Serçenin kanadındaki son tüylerle

Yazdım, son perdenin şiirini.

Dolunayın en parlak ışığında

Yıldızları bile karartan,

Dağları gümüşe boyayan,

Son beyazın altındaki,

En son şiiri yazdım,

Toprağın verdiği son anlarda...

Ve ben sevgili son rüya için daldım,

Uyku deryasındaki umutlara.

Tek can simidi, senin gözlerindi.

Şairin dediği gibi:

''''Gözlerinle yakılası bir şiire başladım''''

O zaman ışığa yaklaştım sevgili

Kara toprağın altından filizlenen

Sevgi şiirlerinin en son demi

En son dörtlük serpildi doğaya:

'''' Umut çimlerinin en yeşili

  Geceleyin açıldı en mavide

  Her tohumun can bulduğu

  Gözlerinden kokladığım sevgide. ''''', 'Gözyaşlarımın toprağı öptüğü son gecede Haykırdım varoluşumun nedenini Seni ölümüne sevmekti sevgili. Serçenin kanadındaki son tüylerle Yazd...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/son-sevda-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taksitle Sigara', 'taksitle-sigara-ozan-turk-jbaqc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Taksit taksit içiyorum son sigaramı

Bu senin beni son sevişini hatırlatıyor

Taksit taksit

Ama biliyorum

Hiçbir şeye değişilmez benim tadım

Mutluyum bu yüzden

Bir başka paket alana dek sen…', 'Taksit taksit içiyorum son sigaramı Bu senin beni son sevişini hatırlatıyor Taksit taksit Ama biliyorum Hiçbir şeye değişilmez benim tadım M...', ARRAY['Türk Edebiyatı','Şiir','Ozan Türk']::text[], 8.5, '{"poet":"Ozan Türk","poet_slug":"ozan-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/taksitle-sigara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-harun-akcan-ux9j5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu dünyanın derdi nedir? 

Anlaşılmaz,çözülmez

Bir bilmece gibi. 

Şu denizin dengi nedir? 

Büyümez,küçülmez

Bir resim gibi.

Şu yüce dağın

Yüceliği nerde? 

Neye sırtını vemişte bükülmez

Herşeyi besler eteğindede

Eteğindeki taşı döküp 

Yürümez', 'Şu dünyanın derdi nedir?  Anlaşılmaz,çözülmez Bir bilmece gibi.  Şu denizin dengi nedir?  Büyümez,küçülmez Bir resim gibi. Şu yüce dağın Yüc...', ARRAY['Türk Edebiyatı','Şiir','Harun Akcan']::text[], 8.5, '{"poet":"Harun Akcan","poet_slug":"harun-akcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dunya-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbrahim', 'i-brahim-i-lhami-arslantas-s718t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sadakat içinde sevip sayılsa

Nefse değil vicdanlara uyulsa

Dost dediğin erdem için koyulsa

Uçar namertlerin külü İbrahim

Sevgin ta baştadır özün sözün de 

Sen nadide gülsün gönül gözünde

Kemaline ermiş alim izinde

Doğruluktur aklın yolu İbrahim

Ne bilsin halini tuzu kurular

Çamur ile yıkar ziftte durular

Çiçeğin kıymetin bilen arılar

Taşır kovanına balı İbrahim

Muhabbet eyledik hal hatır sorduk

Güzel bir dostluğa damgayı vurduk

Gönülden gönüle bir köprü kurduk

Geçsin sevgilerin seli İbrahim

Geldik Trabzondan  Sivas ilinden

Konuştuk anlaştık sevgi dilinden

Türkü yaylasının şiir yolundan

Bağ bostan eyledik çölü İbrahim

İlhami’yim arz eylerim dostumu

Sererim yoluna gönül postumu

Nazik eller bam teline bastı mı

Nar çiçeği açar çalı İbrahim...

 Değerli şair dostum İbrahim Yavuz''a ithafen yazılmıştır.', 'Sadakat içinde sevip sayılsa Nefse değil vicdanlara uyulsa Dost dediğin erdem için koyulsa Uçar namertlerin külü İbrahim Sevgin ta baştadır ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ibrahim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sunam', 'sunam-abdulkadir-karaca-u0qzb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sunam çektirdiğin yetmezmiş gibi

Yine çektiririm diyorsun bana

Aşk bir kuyu sunam görünmez dibi

Kuyuda susuzum,muhtacım sana

Sunam öldür beni acı çektirme

Deli oldum düştüm halkın diline

Yeter verdin zehir,nazlı tenime

Artık beni güldür acı halime

Sunam yaram sarsan,zahmet olmazsa

Sunam yaram senden,kabuk tutmazsa

Acı çekermisin her dem kanarsa

Sen kanattın sunam,sen durdursana

Dosttun,düşman oldun öldürdün beni

Aşkta alev idim,söndürdün beni

Kara topraklara gömdürdün beni

Sunam revamıydı,bak gözlerime

Bana bir şans daha,bir avuç sevgi

Ötesi olmasın bir kere gelki

Yetişir verdiğin acılar gör ki

Sunam çok özledim,benim olsana

Sunam kötü halim yok ettim geldim

Açları doyurdum,tok ettim geldim

Azlar yoktur sende,çok ettim geldim

Gayrı perişanım bak bir yüzüme

Sunam ben imişim köle sattığın

Baharı özletip,kış arattığın

Sunam reva değil,günah yaptığın

Sunam ömrüm verdim,haydi alsana

Bizi çekemeyen yerde sürünsün

Sunam aşık bir ben,bak sende gördün

Sunam şiirlerin tükendiği gün

Sana yine yarım,inan sözüme

Sunam beni ateşlerde yaktın sen

Sunam dertlerimi sende bilmezsen

Kim acır halime böyle severken

Küskün olma bana,aşkla dolsana

Sunam gaflet sende,dert ise bende

Kırgın isen bana affet bu demde

Sunam hal kalmadı dertli bedende

Çileleri dost yapmışım sineme

Sana söylediğim herşey doğrudur

Aşk insanı dert çölünde yoğurur

Sunam yalanım yok,hallerim budur

Affet artık sunam,beni bulsana

(28,04,2004)', 'Sunam çektirdiğin yetmezmiş gibi Yine çektiririm diyorsun bana Aşk bir kuyu sunam görünmez dibi Kuyuda susuzum,muhtacım sana Sunam öldür ben...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sunam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitiş', 'bitis-harun-akcan-5nmx3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen öylesin ki! 

Adını hiç bir yere yazmıyorum.

Üstüne toz konmasın diye.

Sen öylesin ki! 

Kalbimi hiç durdurmuyorum

Sürekli benle yaşayasın diye.

Sen öylesin ki! 

Ben yaşıyorum

Birgün beni seversin diye.', 'Sen öylesin ki!  Adını hiç bir yere yazmıyorum. Üstüne toz konmasın diye. Sen öylesin ki!  Kalbimi hiç durdurmuyorum Sürekli benle yaşayasın...', ARRAY['Türk Edebiyatı','Şiir','Harun Akcan']::text[], 8.5, '{"poet":"Harun Akcan","poet_slug":"harun-akcan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bitis-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördün mü İstanbul', 'gordun-mu-i-stanbul-abdulkadir-karaca-ms2qs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen böyle acı gördün mü İstanbul

Sen böyle yalnızlık gördün mü

Öfke kusan,damar damar kan akan

Böyle ölüm gördün mü İstanbul

Geceleri bana mahrum ettin İstanbul

Geceleri beni mahkum ettin İstanbul

Sen böyle zulüm gördün mü İstanbul

Sen böyle aşk gördün mü İstanbul

Neler istiyorum İstanbul biliyormusun

Senden kaçmak değil

Seni sevmişim İstanbul başkalarının gözlerinde

Başkalarının saçlarında senin dalgalarını sevmişim

Yedi tepeni.yedi rengini,gök kuşağını,herşeyini

Seni sevmişim İstanbul...

Senden vazgeçebilirmiyim

Tadı tuzu sensin İstanbul hayatımın

Ve melekler,melekler üzerindeyken İstanbul

Son bir amaç,son bir gaye,son bir sevgi

Ama sana aşığım İstanbul

İstanbul kolla kendini

Tutarsız bir aşk benim ki,umarsız bir aşk İstanbul

En büyüğü sevmek,en iyiyi sevmek,en güzeli sevmek

Kısacası seni sevmek İstanbul

Kaçarak sevmek,bakmayarak sevmek

Affet İstanbul

Başkalarında arayarak sevmek

Ama döndüğüm baktığım her yerde seni görerek sevmek

Bir deli aşığım İstanbul

Surların mı,köprülerin mi,

Camilerin mi sahip çıkar bana bilmem

Kimsesizim İstanbul

Neden böyleyiz İstanbul

İkimizde ağır bedelleri sevmişiz

Aynı huylarımız var İstanbul

En büyüğü seviyoruz,en iyiyi seviyoruz

Sen Fatihi sevdin onun oldun

Ben onu sevdim

Senin oldum İstanbul! 

Bir avare gibi,bir deli gibi

İstanbul böyle aşk gördün mü İstanbul

Başkalarında seni seven bir deli gördün mü

İstanbul acı bana İstanbul

Yağmurlarda kavruldum

Yalnızlıkta kavruldum

Yanmış yüreğimle gidiyorum senden

Elveda İstanbul severek ayrılıyorum

Sana elveda İstanbul 

Son sözümü diyorum:

İstanbul seni seviyorum

(2 Nisan 2004)', 'Sen böyle acı gördün mü İstanbul Sen böyle yalnızlık gördün mü Öfke kusan,damar damar kan akan Böyle ölüm gördün mü İstanbul Geceleri bana m...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/gordun-mu-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doganý n Koynunda Yasamak', 'dogan-n-koynunda-yasamak-mehmet-sait-akkus-vvhxm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapatacað im

Bütün defterleri

Birer birer

Aska dair,Ihanete dair

Sehir kesmesligine dair

Strese dair ve

Olumsuzluklara dair ne varsa

Alip basimi gidecegim

Gök yüzünün mavi

Yer yüzünü yemyesil oldugu dogaya

Alacagim papuçlarimi ellerime

Siyiracagim paçalarimi

Dogayla direkt temas kuracagim

Ý çinde birtek doga ve dogallik

Hormonsuz bir yasam

Yasamak için

Hele lavas saç ekmegi

Uaninde peynir,yesil sogan

Dürüm yapip bir pinar basinda

Oturup yemek lazim

Bu yesil dogada

Kus civiltisi

Cir cir böcegi

Kurbaga sesleri

Degme müzik aletlerine tas çikarayor

Sanki ninni söylüyorlar

Kapatacaksin gözlerini

Misil,misil

Doganý n koynunda yatavaksin', 'Kapatacað im Bütün defterleri Birer birer Aska dair,Ihanete dair Sehir kesmesligine dair Strese dair ve Olumsuzluklara dair ne varsa Alip ba...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkus']::text[], 8.5, '{"poet":"Mehmet Sait Akkus","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dogan-253-n-koynunda-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne sırları var.', 'ne-sirlari-var-halil-colak-mdeo9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zahiri alemde gezme boşuna

Bak insan oğlunda,bak neler var.

Arşı alanın her bir katında

Hz.Muhameddin  miraca çıkışında

Yaratanın bilinmeyen,ne sırları var.

Cehennem ateşi insanı yakmaz boşuna

Yanacak  ateşi kul burdan götürür

Yedi adımda bir komşu hakkı sorulur.

Arasat meydanında hesap verilir.

Yaratanın bilinmeyen,ne sırları var.

Mahşer günü gelip çatınca

İnsan oğlu feryat figan edince

Sırat’ın  altında cehennemde olunca

İyi kullar sıratıda  kuş gibi geçince

Yaratanın bilinmeyen,sırları var.

Kim ağadır,kim paşadır sorulmaz.

 Fakır, zengin diye ayrı hüküm verilmez.

Gelişi güzel karar adaletsiz verilmez

Hesap gününde kimseye torpil geçilmez.

Yaratanın bilinmeyen, ne sırları var.

Haksızlığa uğrayan hakkı alınca

Müsrif duruma insan  düşünce

Yetim hakkından hesap gelince

Sonun da hak yemek  cehenneme gidince

Yaratanın bilinmeyen, ne sırları var

Güneş tepeye gelip durunca

Başta sıcaktan beyin kaynayınca

Arşın gölgesinde yer olmayınca

Kul olarak hakka yönelmeyince

Yaratanın bilinmeyen,ne sırları var.

Horasan ereniyim hak yolunda gezerim

Hak olmayan sözün üstünüde çizerim

Namert olan kula yoktur kelamım

Sadece Allah’a vardır sorgu sualim

Yaratanın bilinmeyen,ne sırları var.

Halil Çolak 4.7.2005 Ankara', 'Zahiri alemde gezme boşuna Bak insan oğlunda,bak neler var. Arşı alanın her bir katında Hz.Muhameddin  miraca çıkışında Yaratanın bilinmeyen...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ne-sirlari-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçecek', 'gececek-hatem-kardesler-auyhp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gencecik ömrümün şu ilk baharı,

Ne yazıkki acılarla geçecek…

Gönlüme düşen ilk kışın karı,

İlk ağrı ve ilk sancılarla geçecek…

Ağlamak sızlamak boşadır artık,

Üzüntüler sonsuz,neşe bir anlık,

Ve kapımı çaldı birgün ayrılık,

Artık gönlüm hancılarla,yolcularla geçecek…

Şimdi gözlerim gülmeye hasret,

Bir yanda sensizlik,bir yanda gurbet,

Bu ayrılık sona erecek elbet,

Ömrümün son baharı ümitlerle geçecek…

			         (Hasret İçimde Bir Dağ)  Kitabından', 'Gencecik ömrümün şu ilk baharı, Ne yazıkki acılarla geçecek… Gönlüme düşen ilk kışın karı, İlk ağrı ve ilk sancılarla geçecek… Ağlamak sızla...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gececek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkentliye Notlar-1', 'baskentliye-notlar-1-hatem-kardesler-8vrlz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceler beni korkutmuyor artık,

Çaresizliğimi de prangaya vurdum…

Yalnız özlemlerim var sana…

Ellerini tutabilmek özlemi,

Gözlerine bakabilmek özlemi,

Sesini duyabilmek özlemi…

Bilmezsin Başkentlim bilmezsin…

Bu ozan yüreğim ne acılar çekti…

Senden önce; 

“Sevmeler boş,sevilmeler yalan” dı…

Ama şimdi gel gör ki,

Ozan yüreğimde bir telaş,bir sevinç,

Sensiz günlerim geçmez oldu…

Şuracığımda bir şeyler var kıpır kıpır,

Düşlerimde güzel günler,

Düşlerimde sevmeler,

Düşlerimde umutlar var yığınla…

			         (Hasret İçimde Bir Dağ)  Kitabından', 'Geceler beni korkutmuyor artık, Çaresizliğimi de prangaya vurdum… Yalnız özlemlerim var sana… Ellerini tutabilmek özlemi, Gözlerine bakabilm...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/baskentliye-notlar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meczup', 'meczup-atif-okan-tn8xy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I

seslere kör

görünüşlere lâl

dağılmaz üstüne çullanan melâl

göllerde çölsün

sahrada damla

çoğalır yalnızlığın zamanla

     II

kırık aynalar 

ilahi vaat

hüzne kilitlendi saat

ve sen

ölü akrepler üstünde

hep genişleyen yelkovan

söyle nerede aşkı doğuran zaman

hangi cübbenin altında

     III

herşeyi ve kendini

gereksiz deyip içinden at

kanatsın gök/yüzünü

kalbleri sızlatan rikkat

yalnız

gül kokulu aşklar kalsın geri

    IV

ola ki bir gün

kürürse içindeki beyazlığı kar

söyle bundan ne çıkar

ateş bedenli kelebekler

uçmaz iken emekler

     V

sıyır kaygısızca

zaman denen cübbeyi

kelimelerin içine sız

anlam kovalamakta heceyi

     VI

aşk ateş/ten uçurum

emer karanlık göğsünden geceyi', 'I seslere kör görünüşlere lâl dağılmaz üstüne çullanan melâl göllerde çölsün sahrada damla çoğalır yalnızlığın zamanla      II kırık aynalar...', ARRAY['Türk Edebiyatı','Şiir','Atıf Okan']::text[], 8.5, '{"poet":"Atıf Okan","poet_slug":"atif-okan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/meczup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkentliye Notlar-2', 'baskentliye-notlar-2-hatem-kardesler-z7kv2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani sana; 

“Düşünce prangaya vurulmaz ki” demiştim…

Bazen onuda yapıyorlar birtanem,

Düşünme diyorlar…

Suç bende mi be birtanem…

Suç bende mi? ...

Hadi bir hasret şarkısı Çalsında düşünmeyeyim,

Hadi içli bir şiir okunsunda,

Gözlerim mıh gibi takılıp kalmasın bir noktaya…

Elde mi be birtanem,

Elde mi? ...

Elde olsaydı düşünmemek,

İnanki düşünmezdim…

Ayrılık şarkılarının beni kahretmesini

İster miydim sanki? ...

En oynak şarkıları koyardım dudaklarıma

En vurdumduymaz şiirleri okurdum…

Aşka boş verirdim anlayacağın,

Yaşamaya bakardım…

			         (Hasret İçimde Bir Dağ)  Kitabından', 'Hani sana;  “Düşünce prangaya vurulmaz ki” demiştim… Bazen onuda yapıyorlar birtanem, Düşünme diyorlar… Suç bende mi be birtanem… Suç bende ...', ARRAY['Türk Edebiyatı','Şiir','Hatem Kardeşler']::text[], 8.5, '{"poet":"Hatem Kardeşler","poet_slug":"hatem-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baskentliye-notlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teselli', 'teselli-sinan-karakas-6qsh3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir teselli isterim yıkılmadan umudum

Derdim bana zehirdir içerim yudum yudum

Umudumu yıkana gönlümü karartana

Nasıl sevgilim derim gidip elin olana

Ben seni unuttum desemde yalan olur

Ölürsem eğer gözüm arkada kalan olur.', 'Bir teselli isterim yıkılmadan umudum Derdim bana zehirdir içerim yudum yudum Umudumu yıkana gönlümü karartana Nasıl sevgilim derim gidip el...', ARRAY['Türk Edebiyatı','Şiir','Sinan Karakaş']::text[], 8.5, '{"poet":"Sinan Karakaş","poet_slug":"sinan-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/teselli-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğanın Koynunda Yaşamak', 'doganin-koynunda-yasamak-mehmet-sait-akkus-swqyb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapatacagim 

Bütün defterleri

Birer birer

Aska dair,ihanete dair

Strese dair

Olumsuzluklara dair ne varsa

Alip basimi gidecegim

Gök yüzünün mavi

Yer yüzünün yemyesil oldugu dogaya

Alacagim papuçlarimi ellerime

Siyiracagim paçalarimi

Dogayla direkt temas kuracagim

Içinde bir tek doga ve dogallik

Hormonsuz bir yasam

Yasamak ne güzel.

Lavas saç ekmegi

Yaninda peynir,yesil sogan

Dürüm yapip,bir pinar basinda

Oturup yemek lazim

Bu yesil dogada

Kus civiltisi,circir böcegi

Kurbaga sesleri

Degme müzik aletlerine tas çikartiyor

Sanki ninni söylüyorlar

Kapatacaksin gözlerini

Misil misil

Doganin koynunda yatacaksin', 'Kapatacagim  Bütün defterleri Birer birer Aska dair,ihanete dair Strese dair Olumsuzluklara dair ne varsa Alip basimi gidecegim Gök yüzünün ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/doganin-koynunda-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Beyaz', 'siyah-beyaz-mustafa-dogan-kuzgun-md5bl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dönüp te baktığında ardına

Yaşamına yön veren iki yol vardır.

Ya karanlığını aralayan aydınlık

Ya da aydınlığını kapatan karanlık.

Ama sonuçta hepsi bir varoluştur,

Yeniden ve şekilsiz bir yaradılış.

Şekli verip eskitense zamandır.

Acımasızca geçer üstünden göremezsin,

İnsafsızca durağanlaşır, bekleyemezsin.

Efkarlandığında zaman

Yaşayamaz ve ölemezsin.

Yola çıkma vakti gelmiştir artık.

Yaşam rengini taşımak zorundasın.

Seç birini neden bekliyorsun ki; 

Yüreğinde aydınlığı taşıyan bir gece

Veya karanlığını aydınlatan dolunay olacaksın.

İsyan etme, yaşamın başka rengi yok.

Aşkın kırmızısı, mutluluğun pembesi,

Sonbaharın sarısı, sevginin gökkuşağı...

Bunlar gece yaşayamaz, parlayamaz.

Hepsi siyaha mahkumdur.

Unutma, renkler gündoğumu varolur.

Umudun mavisi şafakla doğar,

Baharın yeşili güneş parladıkça yaşar.

Aydınlıktır korkuları uzaklaştıran,

Beyazın saflığıdır zamanı yaşanır kılan.

Evet! 

Karar senin; 

Ya figüran olarak yaşlanacaksın karanlıklarda

Ya da en güçlü karakteri canlandıracaksın aydınlık ışıklarda...', 'Dönüp te baktığında ardına Yaşamına yön veren iki yol vardır. Ya karanlığını aralayan aydınlık Ya da aydınlığını kapatan karanlık. Ama sonuç...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/siyah-beyaz-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğin yetermi güzelim?', 'yuregin-yetermi-guzelim-ali-osman-yilmaz-exytt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah Çekiyorum

Seni düşündükçe,

Kirpiklerim  ıslak,

Göz bebeklerimde yıldızlar,

Başımın üstünde ay,

Bütün gece parıldar,

Ve ben cam kenarında,

Seni ve geçen günlerimizi,

Düşündükçe vallahi,

Ah çekiyor,ve ağlıyorum,

biliyormusun.

Sorguluyorum bahtımı,

Ne kadar karalar bağlamış,

Tüm yaşamım boyunca,

Kahve rengi gözlerim,

Seni aramış,ve,

Senin için ağlamış.

Nerdesin ve niçin,

Bana gelmemektesin? 

Bak burada ben,

Sahil kenarında,

Evimin cam kenarında,

Seni ve gelecekte yaşayacağımız,

Güzel günleri  düşlemekteyim.

Ve ölüm denen şeyin,

Nöbetine başlamadan,

Sensizliğe bir veda,

Ama seninle cehenneme bile,

Senin cehenneminde yanmaya,

Koşulsuz gireceğim,

Uzat  elini gönlümün güzeli,

İşte benim cennetim,

İstersen cehennemim,

Yüreğin varsa eğer,

Gel beraber yanalım,

Ateşin harında kül olup,

Çamura karılalım,

Hayyamın kerpiçinde,

Bir meyhaneye,

Duvar olalım.', 'Ah Çekiyorum Seni düşündükçe, Kirpiklerim  ıslak, Göz bebeklerimde yıldızlar, Başımın üstünde ay, Bütün gece parıldar, Ve ben cam kenarında,...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yuregin-yetermi-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastayım Abi', 'hastayim-abi-durmus-karakus-fkt99', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle bir derinden baktıki bana

Divane gönlümü kaptırdım ona

Bilmeyen çok iyi  sanıyor ama

Ben ona yürekten hastayım abi

Gelip te bir hal hatır soruşuna

Veririm paramı ta kuruşuna

O yarin manken gibi duruşuna

Gördüğüm günden beri hastayım abi

Ne grip ne nezle ne de bronşit

Bendeki hastalık bir başka çeşit

Onun güzelliği güneşle eşit

Alevli yakışına hastayım abi

Adını hiç sorma boyu bir selvi

Sarmaya kıymazdım o ince beli

Duyunca şok oldum evliymiş evli

O günden bu güne yastayım abi.', 'Öyle bir derinden baktıki bana Divane gönlümü kaptırdım ona Bilmeyen çok iyi  sanıyor ama Ben ona yürekten hastayım abi Gelip te bir hal hat...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hastayim-abi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceye Geldim', 'geceye-geldim-fatih-gulumse-znqk9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aradığım sorduğum sen değildin,

Sessizliğe dalıp geceye geldim.

Ağlamaklı olduğuma kanmayasın,

Kalabalıklara isyandan beri böyleyim.

Her kapı çaldığında karşında sanma! 

Düşlerin gerçeğe karışıp dağılmışsın!  

Sevmeyi anlamak için şeytana kanma! 

Sevgini ruhunu bedeninde yakmışsın!', 'Aradığım sorduğum sen değildin, Sessizliğe dalıp geceye geldim. Ağlamaklı olduğuma kanmayasın, Kalabalıklara isyandan beri böyleyim. Her kap...', ARRAY['Türk Edebiyatı','Şiir','Fatih Gülümse']::text[], 8.5, '{"poet":"Fatih Gülümse","poet_slug":"fatih-gulumse","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/geceye-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Değilsin Artık', 'sen-benim-degilsin-artik-mustafa-dogan-kuzgun-2lub9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen benim son hasretimsin

Nefesinde boğulmayı özlerken

Gözlerine saatlerce bakabilmek için

Geceler boyu sabahı beklediğim.

Sen benim son ayrılığımsın,

Gurbet yollarında yapayalnız,

Yürek sızımsın içimde kanayan

Varlığını hissettiğim an başlayan.

Sen benim son haykırışımsın

Aynalar karşısında, çaresiz

Koparmak için kalbimden

Günlerce duvarlara bağırdığım.

Sen benim son ağlayışımsın

Bu aşkı bitirdiğinde başlayıp,

Vedalaşırken hıçkırıklara takılmıştı,

Gözlerinde gölgemi kaybettiğimde.

Sen benim son yalvarışımsın

Ezan sesleriyle düğümleyip adını

Tanrıya el açıp dua ederken

Benim olman için son yakarışımsın.

Sen benim son acımsın,

Hayat sahnesinde son dramım,

Canevimde tutunacak son dalımsın,

Gözlerimdeki son umut yaşımsın,

Son sevda pınarım, son baharımsın

Sen benim yaşamaya mahkum son yıllarımsın.', 'Sen benim son hasretimsin Nefesinde boğulmayı özlerken Gözlerine saatlerce bakabilmek için Geceler boyu sabahı beklediğim. Sen benim son ayr...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-benim-degilsin-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Ayrıldık', 'bugun-ayrildik-muammer-baydere-c0k20', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vefasız kadere boyun eğerek

Son defa buluştuk son kez sarıldık

“Sayılı gün çabuk geçer” diyerek

Yarimle biz daha bugün ayrıldık

“Beni anla” deyip özür diliyor

Ben nasıl özlerim o da biliyor

Sanki yıllar olmuş gibi geliyor

Yarimle biz daha bugün ayrıldık

Sevene vuracak darbeyi gurbet

Gönlüme dolacak kederle hasret

O kadar olacak ağlarım elbet

Yarimle biz daha bugün ayrıldık', 'Vefasız kadere boyun eğerek Son defa buluştuk son kez sarıldık “Sayılı gün çabuk geçer” diyerek Yarimle biz daha bugün ayrıldık “Beni anla” ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bugun-ayrildik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niyetim Yok ki...', 'niyetim-yok-ki-muammer-baydere-h7bux', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana bu şikayet bu sitem niye

Bir bilsen dertlerim o kadar çok ki

Ömrümü adadım ben bu sevgiye

Bırakıp gitmeye niyetim yok ki

Hakkım yok diyedir aramıyorsam

Sebep kim saçını taramıyorsam

Suçlama sen beni saramıyorsam

Bırakıp gitmeye niyetim yok ki

Bir şüphen var ise istersen dene

Hayalin tesellim her gün her sene

Sitemden vazgeçip bana gelsene

Bırakıp gitmeye niyetim yok ki

Sen bana geldin de “gelme” mi dedim

“Ağlamak çok güzel gülme”mi dedim

Her zaman seninle olmak istedim

Bırakıp gitmeye niyetim yok ki

Ben sana yakınım sen bana ırak

Arzuma şahitsin nedir bu merak

Hem suçlu hem güçlü olmayı bırak

Bırakıp gitmeye niyetim yok ki', 'Bana bu şikayet bu sitem niye Bir bilsen dertlerim o kadar çok ki Ömrümü adadım ben bu sevgiye Bırakıp gitmeye niyetim yok ki Hakkım yok diy...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/niyetim-yok-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okul Yolunda', 'okul-yolunda-muammer-baydere-rmxhp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbimden vuruldum görünce onu

Aklıma girmiyor başka bir konu

Sınıfta kalsam da bu sene sonu

Yine de mutluyum okul yolunda

Sevdiğim gözümde dünya güzeli

Kendimde değilim onu seveli

Bir ömür harcamak olsa bedeli

Yine de mutluyum okul yolunda

En güzel günümdür her pazartesi

Dünyama mutluluk veriyor sesi

Unuttum defteri, kalemi, dersi

Yine de mutluyum okul yolunda', 'Kalbimden vuruldum görünce onu Aklıma girmiyor başka bir konu Sınıfta kalsam da bu sene sonu Yine de mutluyum okul yolunda Sevdiğim gözümde ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/okul-yolunda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Öpüp Koklamak', 'seni-opup-koklamak-muammer-baydere-q01vn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“Bahçeme gel” diyorsun “ne çiçekler var bende”

Nerden geldi aklına bana güller saklamak

Biliyorum güzelim ayva sende nar sende

Benim bütün dileğim seni öpüp koklamak

Kalbim sevgi taşıyor başka neye yarasın

“Bana yetmez” diyenler ne ararsa arasın

Fazla bir şey istemem aşkın bana mirasın

Arzum yatıp dizine seni öpüp koklamak

İnkâr etmem gerçeği söyleyecek sözüm yok

Fazla uzun sürmedi aşk yolunda izim yok

Bal arısı değilim her çiçekte gözüm yok

Benim bütün hayalim seni öpüp koklamak

Hor görmedim kuş diye saygı duydum bülbüle

Gece gündüz ah çekip feryat etmiş hep güle

Dönüp bir kez bakmadım en değerli ödüle

Benim için hazine seni öpüp koklamak', '“Bahçeme gel” diyorsun “ne çiçekler var bende” Nerden geldi aklına bana güller saklamak Biliyorum güzelim ayva sende nar sende Benim bütün d...', ARRAY['Türk Edebiyatı','Şiir','Muammer Baydere']::text[], 8.5, '{"poet":"Muammer Baydere","poet_slug":"muammer-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-opup-koklamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hocam', 'hocam-durmus-karakus-tn39j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O kız viran etti gönül bağımı

Bütün filizleri döktü be Hocam

Kalp bendeki san ki Toros Dağı mı? 

Günlerce eritip yaktı be Hocam

O kız ya bir Dicle ya da Fırat''tı

Beni deryalarda yanlız bıraktı

Gönlüm okyanusta yüzen bir yattı

Şimdi marmarada battı be Hocam

Ben paraya pula değer vermezdim

Hep onu der başka bir şey demezdim

Çekipte vursaydı hiç gam yemezdim

Beni üç kuruşa sattı be Hocam

Hep ben çektim cilvesini nazını

Her telinden çaldım aşkın sazını

Unutmak mümkün mü zalim kızını

Yine sancılarım arttı be Hocam.', 'O kız viran etti gönül bağımı Bütün filizleri döktü be Hocam Kalp bendeki san ki Toros Dağı mı?  Günlerce eritip yaktı be Hocam O kız ya bir...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hocam-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayyam kerpiç duvarlardan bakıyor,', 'hayyam-kerpic-duvarlardan-bakiyor-ali-osman-yilmaz-omfza', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aylardan ağustos,

Güz mevsimi gelmekte,

Kızıl  kasırgalar esiyor,

Mavi sürgünlerden,

Güz çiçekleri boy vermekte.

Başım önümde utanırım billahi,

Ey hayyam ne olur bağışla beni,

Bu meyhaneye kimler giriyor? 

İnan hayyam bende bilmem ki,

Ne adam kalmış,nede kalender,

Herkes çıkarında,kendine ihanet eder,

Dalmışlar meyhaneye hep  beraber,

Neyzen duvar üstünden,

Küfürleriyle onlara selam eder,

Deymez hiç biri onlara, 

Sallar kıçını,deyyusu ekber,

Neyzenin selamı bile,

P.........kin yanından geçer', 'Aylardan ağustos, Güz mevsimi gelmekte, Kızıl  kasırgalar esiyor, Mavi sürgünlerden, Güz çiçekleri boy vermekte. Başım önümde utanırım billa...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayyam-kerpic-duvarlardan-bakiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A16 - Dil', 'a16-dil-tahir-gungor-y5fpe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağız denen haneye,

Yaşam denen sahneye,

İş görür her saniye,

..................................D i l.

Fır fır döner dolaşır,

Dır dır dalar, dalaşır,

Der der durur, delleşir,

..................................D i l.

Elden üstündür işde,

İş görür, içde dışda,

Gör bir eline düş de,

..................................D i l. 

Bir lokma et, diridir,

Çatal, uzun, sivridir,

Zehir desen yeridir,

..................................D i l. 

Nasipsizse ölçekten,

Boynuz yapar kılçıktan,

Alçak eder alçaktan,

..................................D i l.

Yakar, üter yalazı,

Yıkar, döker, talazı,

Kusar kini, garazı,

..................................D i l.

Irak, yakın ulaşır,

Derdini böler üleşir,

Baldan şeker söyleşir,

..................................D i l.

Zarzor anlatanı var,

Kendini dinleteni var,

Ağlatıp inleteni var,

..................................D i l.', 'Ağız denen haneye, Yaşam denen sahneye, İş görür her saniye, ..................................D i l. Fır fır döner dolaşır, Dır dır dalar, ...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/a16-dil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellere Düşürdün', 'ellere-dusurdun-durmus-karakus-2qnag', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bırakıp giderken sen bu nazınla

Bu şehri titrettim ben avazımla

Anlıma yazılmış kara yazımla

Dillere düşürdün beni dillere

İzin yok tozun yok in misin cin mi

Bu bana duyduğun nefret mi kin mi

Konya, Kars, Giresun derken Mardin mi? 

İllere düşürdün beni illere

Sana yaptığım bu en son besteyle

Serseri gönlünü dinle mest eyle

Dertli kemenımda bir gül desteyle

Tellere düşürdün beni tellere

Ne arşını koydum ne de miladı

Kime sorduysam beni kınadı

Bırak artık zalim sen bu inadı

Ellere düşürdün beni ellere.', 'Bırakıp giderken sen bu nazınla Bu şehri titrettim ben avazımla Anlıma yazılmış kara yazımla Dillere düşürdün beni dillere İzin yok tozun yo...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ellere-dusurdun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solacaksın', 'solacaksin-husnu-avci-uji7m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülde kusurmu olur, sen benim gülüm idin.

Gülü koparınca solar imiş, şimdi yazıksana 

Solacaksın gülüm bedbaht bir vazoda

Kalsaydın benimle açsaydık seninle daha nice baharlara

biliyorum seni zorla koparmadılar sol yanımdan

ben biliyorumki sen istemeden alamazlardı seni kollarımdan 

sen kendin gittin hemde usulca solyanımdan şimdi yazık sana 

solacaksın bedbaht bir adamın kollarında

belki birdaha gül olmayacak baharlarımda 

belki bahar olmayacak yaşadığım mevsimlerde

ama gülüm sende açamayacaksın bir daha kendini baharlara

şimdi yazık sana solacaksın bedbaht bir vazoda

BENDE AÇMAMIŞ GÜLÜME  Hüsnü AVCI', 'Gülde kusurmu olur, sen benim gülüm idin. Gülü koparınca solar imiş, şimdi yazıksana  Solacaksın gülüm bedbaht bir vazoda Kalsaydın benimle ...', ARRAY['Türk Edebiyatı','Şiir','Hüsnü Avcı']::text[], 8.5, '{"poet":"Hüsnü Avcı","poet_slug":"husnu-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/solacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A17 - Eller', 'a17-eller-tahir-gungor-xsa2b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'El var, elden üstün el,

El var ırak, destan el,

El var, özden dostun el,

................................Dostun el.

Hem tut, hem de ver eli,

Yer tut, yar tut, her eli,

Yar et sana, yar eli,

................................Y a r   eli.

Gez, dolaş elden ele,

Ununu ince ele,

Gönül verme her ele,

................................H e r  ele.

Gör diyar diyar, el el,

Selam ver tek tek, el el,

Gel, yaban durma el el,

................................El, el el. 

Yakın gel, dokun, elle,

Sarıl işe dört elle,

Düğün, bayram hep elle,

................................Hep elle.

Nasip elde bil elde,

Kısmetin belki elde,

Gör bak neler var elde,

................................Var, elde.

Ümidin yoksa elden, 

Bırak ne gelir elden,

Hak düşürmesin elden,

................................Hak elden.

Yavandır yavan eller,

Yabandır yaban eller,

Yamandır yaman eller,

................................O eller,

................................Bu eller,

................................E l l e r.', 'El var, elden üstün el, El var ırak, destan el, El var, özden dostun el, ................................Dostun el. Hem tut, hem de ver eli,...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/a17-eller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doldu çile.', 'doldu-cile-i-shak-ozlu-njlwp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevda yolu uzun ince bilinmez,

Aşka varış zaman ister inilmez,

Yazılınca Canan kalbe silinmez,

Vuslat için sabır Özden içeri.

Yarin yüzü ay parçası uzaktır,

Aşkın gözü kara nokta tuzaktır,

Çilemeden yakın olmak yasaktır,

Umut için ışık Gözden içeri.

Hamdı yürek yandı pişti bekliyor,

Doldu çile geçti ömür ekliyor,

Işık yandı kalan umut tekliyor,

Bahar için gelsin Güzden içeri.

Not:Şiir Perisi grubunun İÇERİ adlı çalışması için düzenlenmiştir.', 'Sevda yolu uzun ince bilinmez, Aşka varış zaman ister inilmez, Yazılınca Canan kalbe silinmez, Vuslat için sabır Özden içeri. Yarin yüzü ay ...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/doldu-cile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarıştırdım Günışığını', 'yaristirdim-gunisigini-ufuk-coban-kam0x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakışlarında yaşadım o gün, sen farkında olmadan,

Ben yeşile baktın, ben hasretine,

Sen tabiatın yavrularına baktın, ben özlemine,

Bir an bana baktın, ben ise uzaklara.

Ait olmadığın yerlere gittim daldığında,

Seni koparıp alacak kişiyi beklediğin hayale.

Sevgiye örülen duvarları yıkacak bütün gücüyle,

Ve seni sen olarak kilitleyecek sevgiye.

Bana olmasa da gülüşünde yaşadım ümidi,

Paylaşdım gizlice sen bilmeden,

Duymak sesini, birkaç kelimede,

Taşıdı hayali, tozlu raflardan pencereye.

Günışığını yarıştırdım saçlarında,

Galibi bir ben bildim, sen giderken bile,

Attım içime sendeki gülüşü, bendeki düşü,

Söylenmediklerinin ucu burada, kalanı işledi kalbime.

07/05/2000', 'Bakışlarında yaşadım o gün, sen farkında olmadan, Ben yeşile baktın, ben hasretine, Sen tabiatın yavrularına baktın, ben özlemine, Bir an ba...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yaristirdim-gunisigini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A18 - Düşünsel Dörtlükler', 'a18-dusunsel-dortlukler-tahir-gungor-0rmq1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıl var, yıllar var,

...............Gün doldurmaz.

Gün var, günler var,

...............Yıla sığmaz.

____________________

Kıtlık arttıkça uzar,

Uzadıkça da azar,

Yoksulu üzer, ezer,

...........................Kuyruk.

____________________

Ziyan olmasın damlası,

Taşa can verir damlasa,

Cana candır bir damla su,

..........................................S u.

____________________

Cüceler var yüceden yüce,

Boyumdan bosumdan utanırım,

Hünerlerini görünce,

Anladım boy bos ölçü değil,

İş görmeye gelince.

____________________

Ağlar gelir güldürürsün,

Susar gider ağlatırsın.

____________________

Başı, sonu ağlamalı,

Orta, gönül eğlemeli,

Neye umut bağlamalı,

..........................Yaşam.

____________________

İki dudak arası,

Aklanamaz karası,

İyi olmaz yarası,

..........................Dil. 

____________________

Bir kere soğursa yuvan,

Dolup, bir olsa yerle tavan,

Her şey yavandır yavan.', 'Yıl var, yıllar var, ...............Gün doldurmaz. Gün var, günler var, ...............Yıla sığmaz. ____________________ Kıtlık arttıkça uza...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/a18-dusunsel-dortlukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak gerek..', 'yasamak-gerek-osman-kilic-fzh7y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamak; kızyurdunun kapısında

Saatler son girişe beş kala

Sevgiliyi öper gibi

.................................şehvetle yaşamak..

Yaşamak; mahpus iken,radyo başında

Ve tahliyesine bir gün kalmış iken

Onüç yıl borcu olan arkadaşınla

Af heberini bekler gibi

.......................................kardeşçe yaşamak..

Yaşamak; bir ameliyathanenin bekleme salonunda

Masadayken refiklerin biriciği

Birinin çıkıp iyi gitti demesini bekler gibi

......................................................................umutla yaşamak

Yaşamak; kilim dokur gibi

Türkü türkü,ilmek ilmek

Türkü gibi gönülden,ilmek gibi işçi

Ve kilimdeki herbir motif gibi uyumlu

................................................................yaşamak gerek..', 'Yaşamak; kızyurdunun kapısında Saatler son girişe beş kala Sevgiliyi öper gibi .................................şehvetle yaşamak.. Yaşamak; ...', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasamak-gerek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaza yaza yoruldum', 'yaza-yaza-yoruldum-tuncay-akdeniz-9fs43', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kağıtlar üstünde çok kalem yordum

Arzu haller yaza,yaza yoruldum

Haksızı savundum haklıya vurdum

Vicdanları üze,üze yoruldum

Çok gördüm yüzlere gülen dönekler

Mazlumları soktu sivri sinekler

İçte dışta huzur bozan inekler

Sütlerini süze,süze yoruldum

Markaların olduk biz eğlencesi

Bozulmuş Türkçenin  güzel hecesi

Yabancı yazıyor em reçetesi

Üzerini çize,çize yoruldum

Asasız Musasız gidiyor tura 

Akıl hocasına ödüyor kira

Millete kesilir sahte fatura

Riyakara kıza,kıza yoruldum

İnsanda terbiye güzel ahlaktır

Cehalet işinin sonu helâktır

Haddini aşmak büyük günahtır

Yüreğimi eze,eze yoruldum

Düşünce duyguya sıra gelince

Bu işin sırrını çözmesi ince

Gönül bir deryadır dibi derince

Ummanın''da yüze,yüze yoruldum

Tuncayım insanda bulunur kusur 

Sevgi bilmezlerin yüreği nasır

Kalemler yazmıyor fikirler esir

Dertlerimi dize,dize yoruldum', 'Kağıtlar üstünde çok kalem yordum Arzu haller yaza,yaza yoruldum Haksızı savundum haklıya vurdum Vicdanları üze,üze yoruldum Çok gördüm yüzl...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/--yaza-yaza-yoruldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen nasıl dünyasın', 'sen-nasil-dunyasin-tuncay-akdeniz-1m244', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bizimle oynarsın her türlü oyun

Sen nasıl dünyasın nasıl zamansın

Var olduktan beri değişmez huyun

Sen nasıl dünyasın nasıl zamansın

Ömür bitirirsin dönen çarkında

Ettin eğlencelik oyun parkında

Gülen ağlayanın değil farkında

Sen nasıl dünyasın nasıl zamansın

Büyükler saygısız küçük sevgisiz

Unutmuş gülmeyi bendeki bu yüz

Hayale bakıyor bizdeki o göz

Sen nasılsın dünyasın nasıl zamansın

Gezdirdin peşinden yoldan yollara

Dalımızda diken oldun güllere

Sevdayı sır ettin saldın çöllere

Sen nasıl dünyasın nasıl zamansın

Bahar yaşamadan kış ettin yazı

Sen ayırdın benden sevdiğim kızı

Mutluluk yerine hep acı sızı

Sen nasıl dünyasın nasıl zamansın

Gezdirdin gurbette sen diyar,diyar

Garibi ezdirdin zalim bahtiyar

Sonunda toprağı ettin bize yar

Sen nasılsın dünyasın nasıl zamansın

Kul Tuncay’da sana çok sitem etti

Nice insanların gülmeden gitti

Çilen çeke,çeke hayatım bitti

Sen nasıl dünyasın nasıl zamansın', 'Bizimle oynarsın her türlü oyun Sen nasıl dünyasın nasıl zamansın Var olduktan beri değişmez huyun Sen nasıl dünyasın nasıl zamansın Ömür bi...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-nasil-dunyasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçti', 'gecti-halil-colak-1i6lu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatı bilmeden yaşamak niye

Ürpermeden geçen ömürde nerde

Size sevgide yeterde kim demiş

Acıya zihin yormayan dost kimmiş

Mabetler içinde sevgi mabedi

Ey dost dosta can kurban dedi

Beklentim daima mutluluk oldu

İşte bekleyerek ömür böyle geçti

Halil Çolak 03.02.1977 /Suadiye/İstanbul', 'Hayatı bilmeden yaşamak niye Ürpermeden geçen ömürde nerde Size sevgide yeterde kim demiş Acıya zihin yormayan dost kimmiş Mabetler içinde s...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gecti-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorma', 'yorma-halil-colak-wq4p3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat ne diye sorma

Ürpermesin tüylerin

Sana yeter bildiğin

Ağrıtıp zihin yorma

Halil Çolak  4.7.2005 Ankara', 'Hayat ne diye sorma Ürpermesin tüylerin Sana yeter bildiğin Ağrıtıp zihin yorma Halil Çolak  4.7.2005 Ankara...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yorma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Nefesten Çalınmıştır', 'son-nefesten-calinmistir-abdulkadir-karaca-tsm2p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kulaklarını kapama bu sefer

Çünkü bağıra bağıra sevdiğimi söyleyeceğim

Seni seviyorum,seni seviyorum,dinlemiyor anlamıyorsun

Adını azraile ezberlettirerek öleceğim

Gözlerinden masumluğu sil

Seni seviyorum biliyorsun acı çektirme

Sevdiğimi söylüyorum kalbine,haydi gül

Bugün,bu saat,bu anda beni sevdiğini söyle

İkimizde acı çekiyoruz,mutluluk için birbirimize muhtacız

Ben delice seni seviyorum,sense beni özlüyorsun

Ömrümü mutluluğuna adıyorum,kabul ediyormusun

Senin mutluluğunu yazmak istiyorum her şiirime

Seninle yaşamak istiyorum ömürboyu

O kadar doğruyum,o kadar dürüstüm ki bu şiirde

Seni inanmak zorunda bırakıyorum sevgime

Azraile karşı koymadan verirken canımı son nefesimde

Son sözümü sana söylüyorum

Anlamanı bekliyorum

Cevap ver seviyormusun

Bense son nefesimde bile

Seni seviyorum! seni seviyorum! 

Seni seviyorum! 

(6 Nisan 2005)', 'Kulaklarını kapama bu sefer Çünkü bağıra bağıra sevdiğimi söyleyeceğim Seni seviyorum,seni seviyorum,dinlemiyor anlamıyorsun Adını azraile e...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/son-nefesten-calinmistir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Semam sen', 'semam-sen-halil-colak-6y1wb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağlarda açan menekşe sümbül

Dallarda ötüşen o dertli bülbül

Arayayım sevgilimi o gonca 

Semam dersem, öpsem güllerini 

Güllerin içinde karanfil gülü

Açar gül bahçesinin lale sümbülü

Kızların içinde benim gün gülü

Solmadan öpsem açan güllerini

Sevmezdim kimseyi gülüm ben.

Ama sevdim gönül bahtını ben

Kalbimin tahtı, o gün gül sen

Gül ömür boyunca Semam sen

Horasan ereni sever gülleri

Günler geçer, kovar yılları

Bekliyorum yarab mutlu günleri

Gül bana Semam gece gündüz sen

Halil Çolak  6.4.1980 Erzurum', 'Dağlarda açan menekşe sümbül Dallarda ötüşen o dertli bülbül Arayayım sevgilimi o gonca  Semam dersem, öpsem güllerini  Güllerin içinde kara...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/semam-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanın', 'i-nanin-halil-colak-x21k4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayağın gidecek yol lazım bize

 İnsanın son yolculuğu inkâr etse ölüm

Korku bize Allah’tan tabiat bizde hiçe

Bizde gaflete yer yok buna iyice inanın

Halil Çolak 20.2.1977 /İstanb', 'Ayağın gidecek yol lazım bize  İnsanın son yolculuğu inkâr etse ölüm Korku bize Allah’tan tabiat bizde hiçe Bizde gaflete yer yok buna iyice...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/inanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B11 - Sevdam', 'b11-sevdam-tahir-gungor-tnubw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görmeyeli ıradı,

Gözüm seni aradı,

özlem nice üredi,

............................Gel, 

............................Bir göreyim.

Görmeyeli ıradı,

Gözüm seni aradı,

özlem nice üredi,

............................Sor, 

............................Ha bileyim.

Tutkum, kat kat iridi,

Yürek yandı eridi,

Tüm dünyamı bürüdü,

............................Gör, 

............................Ne doluyum.

Kimse geçmez yerine,

Yar yakışır yarine,

Umut gene yarına,

............................Yar, 

............................Var kalayım.

Dile destan halimiz,

Yalnız koydun yalınız,

Soldu kaldı alımız,

............................Sana sevdalı,

............................Sana deliyim.', 'Görmeyeli ıradı, Gözüm seni aradı, özlem nice üredi, ............................Gel,  ............................Bir göreyim. Görmeyeli ır...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/b11-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Tarifi', 'askin-tarifi-mehmet-demir-atmali-i0zad', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk; üç harf, sihirli kelime

Yalan dolamışlar dilime

Aşık oldum bak şu halime

Gel de aşkın tarifini yap...

Her ihanete aşk diyorlar,

Onlarca metres tutuyorlar,

Aşkın içine ediyorlar; 

Gel de aşkın tarifini yap...

Kavuşamazsan aşk oluyor.

Çilesi sana kar kalıyor...

Evlenince de aşk ölüyor; 

Gel de aşkın tarifini yap...

Leyla-Mecnun mazide kaldı.

Kerem-Aslı müzede kaldı...

Bu gün aşklar mezada geldi,

Gel de aşkın tarifini yap...

Sosyetenin aşkı Nostaljik,

Fukaranın aşkı Tırajik...

Orospunun aşkı Mekanik,

Gel de aşkın tarifini yap...

Aşk yenilir mi, içilir mi? 

Bir aşk-sevgiden seçilir mi? 

Asla aşk''tan vaz geçilir mi? 

Gel de aşkın tarifini yap...

Yunusun aşkı bir başkadır,

Mehmet''in aşkı bir başkadır.

Hakka giden yollar aşkadır.

Gel de aşkın tarifini yap...

                4.4.2003

Mehmet Demir Atmalı', 'Aşk; üç harf, sihirli kelime Yalan dolamışlar dilime Aşık oldum bak şu halime Gel de aşkın tarifini yap... Her ihanete aşk diyorlar, Onlarca...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/askin-tarifi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B12 - El dediğin', 'b12-el-dedigin-tahir-gungor-mvj5r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elinle itme eli,

Kendin el etme eli,

Yabana atma eli,

...........Yardır yarandır eller,

...........Darda varandır eller.

Hep elele ellerle,

El içinde allarlaa,

Ele yakın hallarla,

...........Dener sınardır eller,

...........Hüner sunardır eller.

Bir el versen can ılır,

El, haz heyecan alır,

Elele canan olur,

...........Sevip sarandır eller,

...........sayıp sorandır eller.

El üstünde tut eli,

Aktan yeğ tutma alı,

El elden üstün olu,

...........Vefa sefadır eller,

...........Deva şifadır eller.

El de olsa, el deme,

Yarım ağız gel deme,

Elin kıtsa, kal deme,

...........Aldan alınır eller,

...........Ala aldanır eller.

Öğün öğün yediğin,

Yamayan her gediğin,

Yedi kat el dediğin,

...........Baba anadır eller,

...........Dosttan yanadır eller.', 'Elinle itme eli, Kendin el etme eli, Yabana atma eli, ...........Yardır yarandır eller, ...........Darda varandır eller. Hep elele ellerle, ...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/b12-el-dedigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmiş', 'gitmis-halil-colak-zbc2b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömür gitmiş,hayat bitmiş

Gönül her zaman zararda etmiş

Söyleyin buna kim aldırış etmiş

Kervan bile dünden gitmiş

Halil Çolak 4.2.1974 Erzurum', 'Ömür gitmiş,hayat bitmiş Gönül her zaman zararda etmiş Söyleyin buna kim aldırış etmiş Kervan bile dünden gitmiş Halil Çolak 4.2.1974 Erzuru...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gitmis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B13 - Sevi', 'b13-sevi-tahir-gungor-c2r0p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dereler başka akışır,

Çiçekler türlü kokuşur,

Gönül gönüle okuşur,

...........................Sevip sezene.

Günler pırıl pırıl parlak,

Seven yüzler daha bir ak,

Seveni sevene bırak,

...........................Sevip sorana.

Olan, olağan haz olur,

Durağan zaman hız olur, 

Sabah akşamdan tez olur,

...........................Sevip sarana.

Bir dyerek, bir duyarak,

İki bedende tek yürek,

Kuru ekmek, ballı börek,

...........................Sevip sayana.

Yaşam seviyle ak ışır,

Svi seviye yakışır,

Sevi güvenle pekişir,

...........................Sevip sevene.', 'Dereler başka akışır, Çiçekler türlü kokuşur, Gönül gönüle okuşur, ...........................Sevip sezene. Günler pırıl pırıl parlak, Seven...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/b13-sevi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-ufuk-coban-nw5ri', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımla ağlıyorum bu gece,

Senin için bile diyebileceğim kimse yok.

Ne sesimi duyan ne nefesimi hissedeceğim,

Bir gölge dolaşmıyor duvarlarda bu gece.

Herkes kendi yalnızlığını çizer yüreğine,

Özgürlüğünün kenarında bakar uçurumlara,

Pes eder bir an gelir, bırakır kendini,

Yalnızlığın kör, karanlık boşluğuna.

Geçen yıllarımla hesaplaşıyorum bu gece,

Saymayı istemediğim, beni bu güne getiren yıllarla.

Ellerim çizgileri gizlemiyor, mum ışığında bu gece,

Senin çizgilerin diyebileceğim biri yok yine.

Gözlerimde uzun bakışlar var, ucu kimseye ulaşamayan,

Dalıp gitmelere söyleyecek bir kelime yok yine,

Kimi daha çok sevdi bilmiyor, bu aklı karışık gönül,

Sil baştanları harcayıp, zamanı sürüyor yaralara.

Sonunu kim bilir yalnızlığın, yalnız olmadan dört duvarda,

Bekleyen biri var mıdır, aynı yalnızlıkla karanlığı,

Gardiyan olmak ne kadar zormuş sessizliğe,

Bir cümlem bile yok, sonu biten sensizliğe.

Sen kimdin benim hayatımda, bir parça olamadın,

Sen diye kime diyorum, ben bile bilmiyorum.

Gelip geçtiniz, hep adın sen olarak kaldı,

Bir tane bile sen, yanımda bir ömürlük kalmadı.

Yeni bir sen daha girecek bir gün hayatıma,

Diğer senler gibi gülecek yüreğime,

İlk sen gibi olmuyor hiçbirşey gözlerime,

Bir sen daha ne fayda, ne güzellik, ne mutluluk ki bana? 

Yalnızlığıma eskilerden bir mum yaktım bu gece,

Hemen her senin yüzünde gölge olarak kalan bir ışık bu.

Bir daha, bir başka sen olmasın bu candaki küskünlüğe.

Son kez gel ve sen son ol, sensizliği senden koparıp bu ıssız köşeye.

04/07/2005 21:10', 'Yalnızlığımla ağlıyorum bu gece, Senin için bile diyebileceğim kimse yok. Ne sesimi duyan ne nefesimi hissedeceğim, Bir gölge dolaşmıyor duv...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bu-gece-136-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahmaranlar(26)', 'sahmaranlar-26-i-smet-barlioglu-5u9ci', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '4

‘Anacanlar… Söz isterim; söz içinde söz ola,

Ölçü-tartı, tamam noksan, mizana gel, gelelim.’

Delikanlı Tokat ‘a doksanbeş lirayla indi.

Tokat, Sivas ‘a göre küçüktü Küçük kentlerin tümünde olduğu gibi bir tek ana caddesi vardı. Caddenin her iki ucu ağaçlıklar, yeşillikler, bağlar, bahçeler arasında kayboluyordu. İşyerleri çoğunlukla önemsizdi. Ortalama ticaret, köylülere gereken bez-çaput satışından ibaretti. Bunun dışında bakır işleyen bir fabrikayla bazı lastik fabrikalarının sözü edilebilirdi. Sert ağaç sanayi de, kentin ticaret hayatında yeni yeni söz sahibi olmaya başlamıştı.

Binalar, göründüğü kadarıyla eski tipti ve iki katı aşanına çok rastlanmıyordu.  Yerleşme kesimleri kente doğudan ve batıdan bakan yüksek yamaçların üzeriydi. Ana cadde bu evlere bakarak ortadaki çukurluktan geçen bir ırmağı andırmaktaydı. Ama cansızlaşmış, ama sıcaklardan suyu çekilmiş, ama dayanıklığı tükenmiş bir ırmak.

Yapanlar sanki ölçmüş, biçmiş ve tam ortasını bularak buraya hükümet konağını yerleştirmişlerdi, tam ana caddenin ortasına. Konak büyük, görkemli ve modern bir yapıydı. İnsanın gözleri bu konağa takılınca devletin var olduğu, çok yetenekli olduğu, çok heybetli olduğu bir iyi anlaşılıyordu. Konağın önündeki alana büyük ve gösterişli bir Atatürk Anıtı ‘yla yüksek bayrak direkleri dikilmişti. Yanındaki konakla orantılı, altındaki dayanakla orantılı, bir anıttı bu. Alan, konağı arkada, ana caddeyi önde bırakarak basit baraka dükkanlarla çevrilmişti. Bunların arasındaki tek modern yapı, bir bankanın şube binasıydı.

İkinci derecede önem taşıyan arka caddeler, caddeden çok, sokakları, pazaryerlerini andırıyorlardı. Manavlar, bakkallar, metal işleriyle uğraşan küçük atölyeler, odunla, kamışla, yabani otla çalışan fırınlar, leblebiciler, berberler, lokantalar, çayevleri hep ayni çarşılarda, hepsi bir arada bulunuyorlardı. Bu yüzden ortada akıl karıştıran, insanı şaşkına çeviren bir sırasızlık mevcuttu. Branşlara göre bir tasnif yoktu.  Dolaşanlar, neyin nerede, kimin kimden sonra olduğunu anlamak için, bütün bir çarşıyı sora sora, baka baka arşınlamak zorundaydılar. Kentin günlük insan ağırlığını taşıyan bu sokaklarını, dar kaldırımlarda yolcu indirip bindiren büyük otobüsler, sahipleri çay içen, uyuyan, iş peşinde koşan, istediği yerde parketmiş faytonlar tıkamaktaydı. Kalabalığın çoğunluğunu meydana getiren omuzları heybeli, sırtları çuvallı, elleri sepetli köylüler, kendilerinin üretmesi gereken malları çarşılardan alıyorlardı.  Manavların sebze ve meyvelerine, sırtları kirli mavi parıldayan sinek bulutları konmuştu. Ekmek fırınları ve bakkallar arasına sıkışmış bir kepekçi, çevreyi sisli bir dumana boğarak kol gücüyle çevrilen bir makinede tahıl kırıyordu. Yakınlardan, aralıklı biryerlerden kazan döven bakırcıların çekiç sesleri yükseliyordu. Dükkanının içinde elleri, yüzleri alçılı birkaç sıvacının çalıştığı bir berber, kaldırım üzerinde, çırağının çeneye dayadığı gri bir leğene elini daldıra daldıra müşterisinin yüzünü yıkamaktaydı. Simitlerini halka halka bir çubuğa takmış olan simitçi bir çocuk köylüye parasının üstünü sayıyordu. Çarşının ortasında bir köylü kadının eşeği anırmaya başlamıştı. Kadın elindeki sopayla susturmak için vurdukça, hayvan susmuyor, daha bir bağırıyordu. İki belediye zabıta memuru, kepekçinin tozlarıyla lacivert üniformaları beneklene beneklene fırından sıcak ekmek, manavdan üzüm alıp kaldırıma masa atmış bir çayevinin önünde oturarak parmağı burnunun deliğini yoklayan peştemalsız-önlüksüz bir garsona çay ısmarlıyorlardı.

Tokat ‘ın insanlarıyla Sivas ‘ın insanları bir pencerenin iki kanadı gibi birbirlerine benzemekteydiler: Sıcakkanlı, sevimli, mert, erdemli, ayrı-gayrılık bilmez, konuksever insanlardı. Kime selam versen ‘Beem otur bi çayımı, gavemi iç, yemeğimi ye.’ Diye karşılıyorlardı.

Delikanlı ana caddedeki, ara sokaklardaki bütün otelleri dolaşıp üç yataklı, beş yataklı oda fiyatlarını soruşturdu. Sonra, önündeki bahçeye masalar atılmış, tek tük müşterili büyük bir çayevinde oturdu. Çay söyledi. Gözleri, her saniye biraz daha soğuyan çayına dikilmiş, dikildiği noktadan ayrılamıyorlardı.

‘En ucuz yatak yedibuçuk lira. Doksanbeş liradan otuzbeş-kırk kadarı teftişim için gerekli taşıma araçlarına gidecek. Kalanı altmış kabul edip ona bölsem; bir güne altı lira düşer. Oysa beş kişilik bir odada bir yatak tedibuçuk lira. Ben sokakta kalacağım… Ben sokakta kalacağım… Günde altı lirayla yaşanmaz… On gün yemek yemeden durulmaz… Bir bardak çay, bir tek simit yemeden durulmaz… Ben sokakta kalacağım… Ben gene sigaramdan, simidimden yoksun kalacağım… Ben Miniciğe para yollayamayacağım… Yollayabileceklerim onun ev kirasına yetmeyecek… İkimiz de yoksul olacağız… Eski yoksulluğumuzu da aratan büyük büyük, yeni yeni yoksulluklara düşeceğiz… Bu işten dönsem dönemem… Dönüşü olmayan bir akıntıda uçurumlu çağlayanlara doğru gidiyorum… Yele yele, ive ive gidiyorum… Benim istifa edeceğim gün, Miniciğin Sivas ‘a atanması çıkar… Bu şans bizdeyken bu böyle çıkar… Bu kere o Sivas ‘ta ben başka yerde… Gene ayni şey… Gene değişen hiçbir şey yok… Ayrılamam… Benim ayaklarımda paslı paslı zincirler, batman batman gülleler var… Muzaffer Abi ‘ye ikiyüzelli lira borçluyum, Nami Bey ‘e yüz lira, artık yatmadığım halde eski otele elli lira, manifaturacıya dörtyüz lira… Aylığımı peşin veren devletime aylığım kadar borcum var… Ayağımdaki ayakkabıya, sırtımdaki gömleğe, bacaklarımdaki pantalona, arkamdaki cekete, İstanbul ‘daki evin penceresinde perdeye borcum var… Beni okutan, sonra da arşivde memur vekili adayı yapmaya çalışan bankaya borcum var… Büyükçe işadamlarının başparası kadar borcum var… Bu ayakkabı, bu gömlek, bu pantolon, bu ceket, şu yüksek öğrenim, o perde, o entarilik, o bluz benim değil… O otelde yatıp borçlanan, o otobüsle bu Tokat ‘a gelen, bu dosyalarla şu teftişleri yapacak olan ben değilim… Sahipleri, edenleri, edilenleri ben değilim… Ben hiçbir şey değilim… Benim hiçbir şeyim yok… Benim sadece borcum var… Şerefim var…’

(Devam edecek…) 26', '4 ‘Anacanlar… Söz isterim; söz içinde söz ola, Ölçü-tartı, tamam noksan, mizana gel, gelelim.’ Delikanlı Tokat ‘a doksanbeş lirayla indi. To...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sahmaranlar-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafes Kuşları', 'kafes-kuslari-mehmet-demir-atmali-7sy67', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kafes kuşu derler bize,

Kaderde uçmamak varmış,

Nefes kuşu derler bize; 

Kederden içmemek varmış...

Dünyamız bir kafes içi,

Gidiyor kuşları göçü...

Bu mudur ötmenin suçu? 

Kaderde göçmemek varmış...

Altın kafes vatanmolur? 

Uçan kuşu tutanmolur? 

Hürriyetin satanmolur? 

Kaderde açmamak varmış...

Kafes seni icad eden,

Soyun sopun, atan deden...

Tutsak olsun leb demeden,

Kaderden kaçmamak varmış...

Mehmet uçmaz benim gibi,

Kanat açmaz benim gibi,

Yardan geçmez benim gibi,

Kaderden geçmemek varmış

                   8.1.1990', 'Kafes kuşu derler bize, Kaderde uçmamak varmış, Nefes kuşu derler bize;  Kederden içmemek varmış... Dünyamız bir kafes içi, Gidiyor kuşları ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kafes-kuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan konuşurdu / En çok yirmilerde...', 'kan-konusurdu-en-cok-yirmilerde-zafer-zengin-etnika-5x5v0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '~|

üşümedim hiç

bir kez belki

aşık dediler

üşür gibi oldum

sonra gibi

büyüdüm

sonra anladım

kolay sevdiğimden sıcaktım

çalındım bilmem kaç yıl

sonra gibi

küçüktüm

en çok yirmilerde öldüm

sayayım

bir o

iki o

üç o

adı yok

unuttum

sayarken uyurdum

kolay sevdim

sıcaktım

unut kandım

aşk sandım

kan konuşurdu

kusardım

konuşmazdım...

21 06 2005

~|', '~| üşümedim hiç bir kez belki aşık dediler üşür gibi oldum sonra gibi büyüdüm sonra anladım kolay sevdiğimden sıcaktım çalındım bilmem kaç y...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kan-konusurdu-en-cok-yirmilerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körebe', 'korebe-nusret-ege-velioglu-ma4ze', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hanidir bir türkü susuyor kulaklarımda...

Ve körebe oynuyorken insancıkların dünyasında...

Yalnızlığın silüeti ebeliyor çaresizliğimi...

Hanidir bir türkü susuyor kulaklarımda...

Söyleyin...

Hangi sazın çığlığıdır parça paça yok olan', 'Hanidir bir türkü susuyor kulaklarımda... Ve körebe oynuyorken insancıkların dünyasında... Yalnızlığın silüeti ebeliyor çaresizliğimi... Han...', ARRAY['Türk Edebiyatı','Şiir','Nusret Ege Velioğlu']::text[], 8.5, '{"poet":"Nusret Ege Velioğlu","poet_slug":"nusret-ege-velioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/korebe-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-olgun-keskin-gs64a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aslında donmak vardı o an, 

atlamak, asılı kalmak havada,

güzel olurdu

solmamak,

kurumamak,

buruşmamak,

ve en önemlisi unutulmaktan kurtulmak!', 'aslında donmak vardı o an,  atlamak, asılı kalmak havada, güzel olurdu solmamak, kurumamak, buruşmamak, ve en önemlisi unutulmaktan kurtulma...', ARRAY['Türk Edebiyatı','Şiir','Olgun Keskin']::text[], 8.5, '{"poet":"Olgun Keskin","poet_slug":"olgun-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hayal-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmasa', 'olmasa-mehmet-demir-atmali-m8s00', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dostum neler feda senin yoluna,

Şu insanın çirkin yüzü olmasa...

Dostum yıllar feda senin yoluna,

Şu insanın çirkin sözü olmasa...

Bunca yıldır delikanlı ararım,

İnsanlığa neler oldu, sorarım? 

Sözlerini yine hayra yorarım...

Şu insanın çirkin ağzı olmasa...

Nesli tükeniyor dürüst insanın,

Rağbet dalkavuğun, turist insanın,

Övgü boynuzlunun, artist insanın...

Şu insanın çirkin kozu olmasa...

Nice dost ile güldüm bir çırpıda,

Nice dost ile öldüm bir çırpıda,

Nice dostları sildim bir çırpıda,

Şu insanın çirkin tezi olmasa...

Hey Üftade! dostsuz da yaşanırmış,

Bazı dostun hep sırtı kaşınırmış...

Bu yolda nice topuk aşınırmış...

Şu insanın çirkin izi olmasa...

                    26.6.1991

                       Üftade', 'Dostum neler feda senin yoluna, Şu insanın çirkin yüzü olmasa... Dostum yıllar feda senin yoluna, Şu insanın çirkin sözü olmasa... Bunca yıl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/olmasa-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesiyorsa / Kelime kırmaca...', 'kesiyorsa-kelime-kirmaca-zafer-zengin-etnika-633tf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '~|

I.

çekilmiş perde ardında

çıplağım ki

geçiyorsun içimden

suskun yaralı yağma

yoksalarda

yine noksanlara

benziyor

yorma kendini

kaç ayrılık ellerin

büyümüyor

II.

dağılmış elim ayağım

uzansam

yüz koyup ağlarım

içimden geçiyorsun

yağma kaçmayla

alışmıyor insan boğulmaya

yağmur bir yere kadar

sevdiriyor kendini

deniz biliyorum

III.

şimdi bir şarkı

bir kulaç daha

kramplar kadar

sivri uçlarıyla

saplanıyorlar ayağıma

Ben sadece

kaça

mı

yorum

bedava şey



IIII.

öyle dalmışım

kıyamet kopuyor elimde

yazamıyorum

al kalemi elimden

yetiş dalga gelmeden

sökülüyorum

kelimeler de

anla

tamı

yorum

alaca sularda

tehlike yok 

di

yorum

ölç

ılığım

soğu

yorum

IIIII.

kesiyorsa

kendiri 

anlamı

yorum

size

değil

kendi

me

boğulu

IIIIII.

yorum...

30 06 2005

Ben  / Sevgili Kazim koyuncu ezgisi

~|', '~| I. çekilmiş perde ardında çıplağım ki geçiyorsun içimden suskun yaralı yağma yoksalarda yine noksanlara benziyor yorma kendini kaç ayrılı...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/kesiyorsa-kelime-kirmaca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Defa', 'son-defa-salim-erben-4dlzi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Son defa gözlerine baktığımda 

Başın öne eğik çehren yıkıktı

Ne selam verdin korku dan

Ne de yüzüme baktın utancından

Gözlerin kaçakçı 

Yanakların kırmızı ihbarcı

Kaşların çatık 

İşte o zaman anladım ki

Bana göre değilsin sen 

İşte o zaman anladım ki

Sana göre değilim ben

Boşver var mı yalandan ölen  

Sahte öpüş sahte gülüş 

Yalancı gösteriş 

Bir daha mı tövbeler olsun

Bunlara kinim bunlara öfkem 

İşte bunlara benim nefretim 

Üzülme sen ayrılık hasretim

Unutmaksa son ödevim

Ama hatıralara gücüm yetmedi

Kimselere söyleyemedim

Bir kaç not sıradan sevişmeler 

Onlar bıraktığımız yerde

Bıraktığımız gibi ter temizler 

Ne sen kirletebilirsin

Ne de senin gibiler

Unutma ki onlar zalımla 

Çoktan evlendiler', 'Son defa gözlerine baktığımda  Başın öne eğik çehren yıkıktı Ne selam verdin korku dan Ne de yüzüme baktın utancından Gözlerin kaçakçı  Yana...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/son-defa-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azapay', 'azapay-ahmet-durmus-7pruf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen yoksun diye azapay,

Yanlızlığı haykırıyor mısralar

Kader gergefini dokuyor zamana

Ve günler geçmekte

Yüreğim hala yanlız; şarkımızı söylüyor

Ne vuslat rüzgarları esiyor

Ne de kafkasyadan bir haber

Ulu kayaların ezildiği bir yerde

Senin hayalini arıyorum,bulamıyorum

Fidanlar boy vermiyor; 

Gerçekler,sanki sana ulaşmama bir geçit

Gökyüzünün ışıksızlığını hissediyorum

Sensiz,kuşlar bile ağlamaklı ezgi tadınca

Analar; boynu bükük

Yetimler; sessiz

Taze gelinlerin duvağı bile açılmamış

Babalar ise tümden çökmüş

Ama,nedir bu sessizlik

Bu bitmeyen çile neden? 

Mutluluğu hep masallarda mı duyacak çocuklar

Kafkasya’ya hep karmı yağacak

Kartallar gökyüzünde ne zaman uçacak? 

Tanrı dağları beni çağırmış sanki

Her yerde senden izler taşıyor

Bu vatan bizimmiydi yoksa

Şu ağlayan kız,eskiden gülüyormuydu

Dört nala toz koparıyormuydu kısraklar

Vey ırmağı ihtilaldede böyle hüzünlü mü akıyordu

Nerdesin Azapay binbir bilinmezlerdeyim

Bu yoldan dönüş yok,ben hep senin peşindeyim

İşte Azapay seni hep bu yitik anılarda arıyorum

Döneceğin günlerin özlemiyle

Kafkasya’ya boy boy fidanlar ekiyorum

Taze gelinlerin yüreğine su serpip; 

Güçlü ol anam,güçlü ol

Mutlu yarınlara  bizi bekliyorum diyorum

"Seni kaybettiğim mısralarda ararken 

Eski bir sahafçının,tozlu raflarında buluyorum

Okudukça kayboluyorsun 

Tozları sildikçe yüreğime kazınıyorsun"

Ve sonra uzanıyorum Asya bozkırlarına

Bozkırın değişmez yasası

Sevdanın üstüne kan damlarmış

Yasaya boyun eğmek bana göre değil

Ben seni yasaya kurban etmem Azapay

Kögmen dağı kadar büyük sevdama 

Sülemişin keskin kılıcıda diş bilese

Bu yoldan dönüş yok ben yine seni ararım

Birde bakmışsın kulaç atıyorum zamana

Manş denizinin ortasında seni arıyorum

Ne köpek balıklarının dişleri

Ne den sayısız adam boyu kadar dalgalar

Dindiremiyor içimdeki fırtana''yı

İçimde engin denizleri kıskandıracak fırtına varken

Bu yoldan dönüş var mı Azapay? 

Ama nedeir bu sessizlik

Bu bitmeyen çile neden

Mutluluğu hep masallardamı duyacak çocuklar

Kafkasya’ya hep karmı yağacak

Kartallar gökyüzünde ne zamn uçacak

Tibette gün sayıyorum vuslata 

Dalay lama da haykırıyorum özgürlüğe

Çin seddinde zafere koşan orduyu bekliyorum

Yasak kentte semayı inleten şarkılar dinliyorum

Güneş doğmadan şarkımı bölüyor

Semeyden yükselen feryatlar

Nerdesin Azapay

Alp teginler seni bekliyor; feyz almak için emrine amade

Ozanlarım susmuş; 

“Üç dal güle arzuhal edemiyor”

Kopuzlar çalmasada 

Orada ki benim “TÜRKÜM”

Nerdesin Azapay 

Mızrap seni bekliyor,tel seni

Irkım seni bekliyor,soyum seni

                                2003/ Muğla/kötekli

Gün onların olsun; gelecek bizim Azapay

                         mutlu yarınlara azkaldı

karanlıkların biteciği gün

gün niyetine senin doğacağın

özgürlükler saçacağın gündür...', 'Sen yoksun diye azapay, Yanlızlığı haykırıyor mısralar Kader gergefini dokuyor zamana Ve günler geçmekte Yüreğim hala yanlız; şarkımızı söyl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Durmuş']::text[], 8.5, '{"poet":"Ahmet Durmuş","poet_slug":"ahmet-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/azapay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok oldun', 'yok-oldun-ahmet-durmus-9rj8q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldızlar feryad ederken geceye

Ben seni düşündüm durdum

Rab’bime bilmem bu kaçıncı secde

Dua’larım da niyazımda hep sen oldun.

Hava soğuk pencerem buğulu

Pencereme yazdım yüreğimle adını

Sen bilmessin içimdeki düğümü

Gel çöz desem,sen hep yok oldun.

Aşk tan firar olmaz be sevdiğim

Bu kaçısın nicedir,hele de ki bileyim

Bulamıyorum ki elimdeki gülleri vereyim

Nerdesin ciğer parem sesimi duymaz olsun.

Ben hep burdayım sen gelmez oldun

Ağlayan benim çile çeken ben gülen sensin

Ahmet’i düşürden ya dilden dillere

Olsanda fark etmez; zaten yok oldun...', 'Yıldızlar feryad ederken geceye Ben seni düşündüm durdum Rab’bime bilmem bu kaçıncı secde Dua’larım da niyazımda hep sen oldun. Hava soğuk p...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Durmuş']::text[], 8.5, '{"poet":"Ahmet Durmuş","poet_slug":"ahmet-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yok-oldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tiren', 'tiren-cetin-hacifettahoglu-pwjuw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'T İle R Arasına Giren

Metal Soğukluğuna Nispet

Kendi Raylarımda Yürüttüğüm

Tirenimle Başladım,

Bu Mutlu Ve Dik Rampalarla Dolu Yolculuğuma…', 'T İle R Arasına Giren Metal Soğukluğuna Nispet Kendi Raylarımda Yürüttüğüm Tirenimle Başladım, Bu Mutlu Ve Dik Rampalarla Dolu Yolculuğuma…...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tiren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boştur Şimdi', 'bostur-simdi-ozcan-erden-f0nf7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boştur Şimdi

Bir Bardak Su İçsem Şimdi Yaralarımdan Dökülür

Gün''ki

Yıkımlar Günü Ne Yapsanız Boştur Şimdi

Evvel Ahir Gören Kimdi

Günki Yıkımlar Günü Ağlasanız Boştur Şimdi.....', 'Boştur Şimdi Bir Bardak Su İçsem Şimdi Yaralarımdan Dökülür Gün''ki Yıkımlar Günü Ne Yapsanız Boştur Şimdi Evvel Ahir Gören Kimdi Günki Yıkım...', ARRAY['Türk Edebiyatı','Şiir','Özcan Erden']::text[], 8.5, '{"poet":"Özcan Erden","poet_slug":"ozcan-erden","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bostur-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sefa gelmişsin', 'sefa-gelmissin-halil-colak-mlwd6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canan elinden, can yoldaşına

Dostlar meclisine, safa gelmişsin

Mecnun olmuşum, hak peygamberine

Erenler meclisine, sefa gelmişsin.

Gül bahçesinin eşsiz güzellerinden

Hak yolundan şaşmaz gidenlerinden

Yunus peygamber gibi güzellerinden

Erenler meclisine, sefa gelmişsin.

Hakkın huzurunda elini bağlayıp duran

Beş vakit namazda huzura varan

Allah korkusundan ağlayıp duran

Erenler meclisine sefa gelmişsin.

Ömerlerin hak için adaletine

Abubekir sıtdık gibi cömertlerine

Osman gibi ahlak güzellerine

Erenler meclisine sefa gelmişsin

Allah’ın aslanı cengaver,Ali’lerine

Hasan, Hüseyin gibi mazlumlarına

Kerbela’da şehit düşenlerine

Erenler meclisine sefa gelmişsin.

Horasan ereni yalvarır kalpten

Ayırmasın Mevla, kimseyi hakan 

Hakkın kelamı kuranı kerimden

Erenler meclisine sefa gelmişsin

Halil Çolak 4.7.2005 Yenimahalle/Ankara

Saat 22.30', 'Canan elinden, can yoldaşına Dostlar meclisine, safa gelmişsin Mecnun olmuşum, hak peygamberine Erenler meclisine, sefa gelmişsin. Gül bahçe...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sefa-gelmissin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''tan Korkmasam', 'allah-tan-korkmasam-yucel-karakilic-h9s3m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkın ordu gibi saldırdı bana,

Çiğnendi toprağım, dağıldı yurdum.

Yaşıma, başıma bakmadan sana,

Allah''tan korkmasam, aşık olurdum.

Bir anda değişti ömrümün şekli,

Şimdi yaşamanın farkına vardım.

Yol verdim duyguma, fesh ettim aklı,

Allah''tan korkmasam, aşık olurdum.

Sustum birileri bilecek diye,

Her gece gizlice hayaler kurdum.

El alem laf edip gülecek diye,

Allah''tan korkmasam, aşık olurdum.

Görünme gözüme sevda dağında,

Sen körpe bir kuzu, ben de bir kurdum.

Yağmalardım seni gençlik çağımda,

Allah''tan korkmasam, aşık olurdum.

Kavuşmak imkansız, her engel cefa,

Sonunda kendimi çöllere vurdum.

İmanlı ömrümde, belki ilk defa,

Allah''tan korkmasam, aşık olurdum.

Bakındım, tarihin sevenlerine,

Kader, hiç birine etmemiş yardım.

Kaptırmazdım devrin civanlarına,

Allah''tan korkmasam, aşık olurdum.', 'Aşkın ordu gibi saldırdı bana, Çiğnendi toprağım, dağıldı yurdum. Yaşıma, başıma bakmadan sana, Allah''tan korkmasam, aşık olurdum. Bir anda ...', ARRAY['Türk Edebiyatı','Şiir','Yücel Karakılıç']::text[], 8.5, '{"poet":"Yücel Karakılıç","poet_slug":"yucel-karakilic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/allah-tan-korkmasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kofti sohbetler', 'kofti-sohbetler-sair-shimalwest-vzhvt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kofti sohbetler gecemin

içine etti

siktirin gidin diyemedim

kibarlığım depreşti

çay bardağı ile

içilir rakı

anlamaz onunla içmeyen

kadın bellinin şanını

kofti sohbetler gecemin

içine etti

karşımda kokona 

şerefe dedi

kaldırdı bardağını burnuma

rakının tadı gelmedi

asortik bardakta

tabure olmalı altımda

alçak masa

balığı yeni atmışım ızgaraya

ellerim kirli

kömürün isi	

radyo çalmalı memleket türküsü

ama cızırtılı

küfür sallamalıyım arada çınlamalı

kulaklar	

kofti sohbetler gecemin

içine etti

kokona iyice yılıştı

sıvışma zamanı geldi

deniz beni çağırdı

köhne iskele işaret verdi

taka pırpırı çalıştı

yürüdüm

ardımda sahte dünya

kofti sohbetler gecemin

içine etti

martının kanadına yükledim

hepsini', 'kofti sohbetler gecemin içine etti siktirin gidin diyemedim kibarlığım depreşti çay bardağı ile içilir rakı anlamaz onunla içmeyen kadın bel...', ARRAY['Türk Edebiyatı','Şiir','Şair Shimalwest']::text[], 8.5, '{"poet":"Şair Shimalwest","poet_slug":"sair-shimalwest","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kofti-sohbetler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'C13 - Susmasan', 'c13-susmasan-tahir-gungor-oqc0o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç gün gördün mü dününde,

Hep bal mı vardı önünde,

Çok mu güzel bugünün de,

.....................................Bir susuyor,

.....................................Susuyorsun.

Ruhca, bedence, hep açız,

Can, maldan çok daha ucuz,

Beşik, tabut, hepsi haciz,

.....................................Hep pusuyor,

.....................................Susuyorsun.

Ezgin ezik ağıt gibi,

Sözde kalmış öğüt gibi,

Alnın ak mı yiğit gibi,

.....................................Yüz asıyor,

.....................................Susuyorsun.

Ülkem diye canın ver de,

Neden böyle yüzün yerde,

Hak, hukuk, saygı nerde,

.....................................Ne küsüyor,

.....................................Susuyorsun. 

Töre mi kalır azınca,

Kimi el atmış kazanca,

Kimi göz dikmiş inanca,

.....................................Kan kusuyor,

.....................................Susuyorsun.

Varın koydun emrinde,

Bir gün görmedin ömründe,

Can feda, kimin umrunda,

.....................................Taş basıyor,

.....................................Susuyorsun.

Bora olup da esmesen,

Kesip biçip de asmasan,

Kırıp döküp de yasmasan,

.....................................Bir silkinsen,

.....................................Bir uyansan da,

.....................................Bari susmasan.', 'Hiç gün gördün mü dününde, Hep bal mı vardı önünde, Çok mu güzel bugünün de, .....................................Bir susuyor, ................', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/c13-susmasan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'C14 - Doğru', 'c14-dogru-tahir-gungor-tjfvd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki noktaya has bilgi,

Arada düz bir çizgi,

En kısa yola,

Eşit.

Yamuk, yılık oluşa,

Yalana yanlışa,

Hepten aykırı,

Karşıt.

Düzgüne düzene,

İtina özene,

Yakın, benzer,

Koşut.

Hak ka gerçeğe,

Karara ölçeğe,

Varışta kural,

Taşıt.

Biçilemez değeri de,

Bir haller var doğruda,

Çok eski, ezelle,

Yaşıt.

Nedense değeri,

Erine, yerine göre,

Ağarı, göveri,

Çeşit çeşit.

Doğrunun da doğrusu,

Kimin ötüyorsa borusu,

Onunkli şimdi,

İyi gör,

İyice işit.', 'İki noktaya has bilgi, Arada düz bir çizgi, En kısa yola, Eşit. Yamuk, yılık oluşa, Yalana yanlışa, Hepten aykırı, Karşıt. Düzgüne düzene, İ...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/c14-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayın!', 'mayin-zekeriya-yeniyol-y3lnj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çakılır kalırsın olduğun yerde,

Korku titretirken dizlerini; 

Çaresiz esirlik ezer yüreğini..

Ne bir adım ileri,

Ne geri! ...

Sonsuz bir sonun kapısına 

Kaderini bağlar ayağın! 

Kan çöker gözüne,

Tüter sevdiklerin...

Yanardağlar gibi patlar aşkın doruklarda...

Çatlak dudaklarına yapışır adı

Dişlerin kenetlenir...

Ve...

Bir adım! 

Geçerim dersin; 

Belki,

Ama Yarım! ...

Bir parçan kalır geride! ..

Sen hiç  mayına bastın mı? ...

                                     29.05.03', 'Çakılır kalırsın olduğun yerde, Korku titretirken dizlerini;  Çaresiz esirlik ezer yüreğini.. Ne bir adım ileri, Ne geri! ... Sonsuz bir son...', ARRAY['Türk Edebiyatı','Şiir','Zekeriya Yeniyol']::text[], 8.5, '{"poet":"Zekeriya Yeniyol","poet_slug":"zekeriya-yeniyol","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mayin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Marş Denemesi (İşçi Marşı)', 'bir-mars-denemesi-i-sci-marsi-metin-yalti-ll08p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelin üzerimize, bu kenetler bizi

Çağdışılıklarınız  yıldırmaz bizi

Atatürk''çü işçileriz,halkız biz

İnancımız çoğaltır gücümüzü

Birer ikişer atılsakta her gün

Büyüyecek örgütlenmemiz gün be gün

Bir durdurulmaz oluşumdur bu

Tarih utkumuzu yazacak bir gün.

Bizim her çabamız halk içindir 

Yaşanılası bir dünya kurmak içindir

Ne varsa seviye,sevgiye   düşman

Emeğe düşmanlığı yıkmak içindir.

Haksızın,hırsızın devri bitecek

Yepyeni bir düzen kuracak işçim

Sevinç gönüllerden hıncı silecek

Yaşamayı onurlu kılacak işçim.', 'Gelin üzerimize, bu kenetler bizi Çağdışılıklarınız  yıldırmaz bizi Atatürk''çü işçileriz,halkız biz İnancımız çoğaltır gücümüzü Birer ikişer...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-mars-denemesi-isci-marsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç bir şey böyle olmazdı inan...', 'hic-bir-sey-boyle-olmazdi-inan-soner-demir-xtj30', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'senin için rahat olsun diye; 

arabanın aynalarını ben kırmıştım sen gitmeden...

önüne bak,

geleceğini gör,

ve aklın ardında kalmasın diye....

deniz daha mavi 

ve hava böylesi güzel olurmuydu dersin? ..

yada şu batan güneş; 

yarın doğduğunda burada olmayacağını bilseydi

bukadar huzurlu girebilirbiydi kızıl yatağında uykuya? ...

gözlerim öylesine açken gözlerine,

uykum katıksız resimlerinle avutamazdı onu elbette...

ellerim titremekten acizken açmaya tuş kilidini telefonumun,

telefonum dışardan kapısının çalınmasını bekledi umutsuz...

ay''ı hiçbir gece bukadar mat,

yıldızları hiçbir gece bukadar isteksiz görmemiştim inan

belki biten gün değil ama

bu gece bal gibide biliyor işte gideceğini...

gecenin kendinin bile farkında olmadığı bir vakti,

sıcagı bile üşütüyor ruhumu sanki...

irkiliyorum...

biraz hap,

biraz sarap ve sigara...

olmuyor aşamıyorum kendimi..

yine içimde seninle başbaşayım...

senin için rahat olsun diye; 

arabanın aynalarını ben kırmıştım sen gitmeden...

önüne bak,

geleceğini gör,

ve aklın ardında kalmasın diye..

ben,

büyüyeceğim bir gün

belkide döndüğünde karşında

içindeki sevginle büyümüş bir delikanlı göreceksin karşında...

o gün gelirse şayet! 

o güne dek hoşçakal...

seni çok 

seviyorum...

zamanın ve mekanın neresinde olursan ol! ....', 'senin için rahat olsun diye;  arabanın aynalarını ben kırmıştım sen gitmeden... önüne bak, geleceğini gör, ve aklın ardında kalmasın diye......', ARRAY['Türk Edebiyatı','Şiir','Soner Demir']::text[], 8.5, '{"poet":"Soner Demir","poet_slug":"soner-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/hic-bir-sey-boyle-olmazdi-inan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutuldum', 'unutuldum-ufuk-coban-j7ge3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutuldum bir köşede, suskun kaldım sevgime,

Gelmedi ne bir haber, ne de bir kelime.

Meğer yalanmış, inandım söylenen bunca söze,

Gördüğümde söylenecek sözüm var o gözlere.

Bilseydi hissedileni yalnızlığa söyleneni,

Açardı bakmak için değil, görmek için gözlerini.

Uzatmazdı elini yakalamak için sessizliği,

O zaman anlardı, istememeyi bensizliği.

30/05/2000', 'Unutuldum bir köşede, suskun kaldım sevgime, Gelmedi ne bir haber, ne de bir kelime. Meğer yalanmış, inandım söylenen bunca söze, Gördüğümde...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/unutuldum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz''in Mavi Boynu', 'deniz-in-mavi-boynu-yelda-karatas-igt35', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'DENİZ''İN MAVİ BOYNU, Deniz Gezmiş ve arkadaşları için yazılmıştı. 

Ne gariptir ki Haziran''da bir başka Deniz yürekli bir devrimciyi yitirdik. 

Onu asmadılar, ama ''asmalayım da besleyelim mi'' zihniyetindeki bu sistemin açık kurbanı oldu sevgili KAZIM KOYUNCU. 

Gizli bir cinayetin kurbanı olduğunu düşünüyorum: Umursamazlık ve ihmalkarlık. Sevgili Harun Karadeniz''e, hala içimin yandığı canım Ruhi Su''ya pasaport vermeyen bu sistem, Karadenizde''ki binlerce insanımızı sorumsuzca ölümün kucağına atmaya devam ediyor. 

KAZIM KOYUNCU, aynı merdiven basamaklarını tırmandı. Kanseri dirençle karşılayan ''ha konser, ha kanser'' diyen o gencecik kalbin, karşısında saygı duymamak olanaksız. 

Arkadaşlığını, çok kısa bir süre de olsa, kesik kesik yaşayabildiğim 

O KAHRAMAN çocuğa bu öyküyü armağan etmek istiyorum. Özgür pencere ve kendi adıma. 

Öykümün bir değeri yoktur: Ama O''nun ve onların yaşamı çok değerliydi, çok değerlidir. 

Kırk bir basamaklı merdivenden iner gibi terleyen 

Turgut Uyar 

Terleyen’e 

Divan 

DENİZ''İN MAVİ BOYNU 

Sevgili Kazım Koyuncu''nun anısına 

-özgür penceredeki bütün arkadaşlarımla birlikte- 

Bir basamak: 

Önümde ne var hep bildim. Arkamı kollamayı bilemedim. Güneş esirgemezliği bu. Ayırmaksızın sevmenin bedeli. Toprak, yeşilin boy attığı yer değil ki sadece. 

İnsanım ben baba, topraktan türkü yükselir bildim. Avucunda parçalanan tane, yalın bir geleceğin özlemi. Böyle bildim. Sorgu sual toprağa değil, toprağa ihanet edene. 

Bilemediler baba. Yaşamak daha mı kolaydı sence? 

İkinci basamak: 

Burada durmalıyım.uzun bir soluk ama.ne kadar uzun. Zamanın göreceliğini zamanı kullanırken anlıyor insan. Ölüm yaklaşınca yaşamın değeri artıyor derlerdi inanmazdım.her ölüm erken ölüm diyor bazıları. Bazı ölümler genç ölüm bunu niye sormadılar baba. 

Güneşi içerken karınca topraktan.gümüşi kanadını açarken bir deli kuş.kendini anlatamamanın ağır kederi erken inen karanlık gibi ranzaya.hayatın bir yolculuk anlıyorsun. 

Gözlerimden başka sığınacak yer kalmamıştı. 

Kırmızı bir bayrağın onurunu bizden başka taşıyan kalmamıştı. 

Zorla mı sıkıştırdılar elimize. Asla. Biz de kaldırmazsak onu yerden toprak onursuz kalır ve yarın olmazdı. Gecenin penceresi hep açık kalırdı. 

Beni esirgemek ölümden değil, hayattan olmalıydı değil mi baba? 

Bir başka basamak: 

Terliyorum, sadece terliyorum, güneş daha yaklaşıyor. 

Basamaklar bitmese: Kısa yaşadığım için bana kızma.çok uzun sürecek bir onurdu yaşamı dersin. 

Bitmeyen masal gibi. Beni görememenin acısı gönlüne bıçak gibi saplandığında. 

Bazı ayrılıklar vuslattır baba.ben kavuşma diyordum. Kızma. Sırasız terk-i diyarlara yürüdüğüm için ömründen. Sevmediklerimi de esirgemeyi neden öğrettin. 

...daha: 

Baba yüreğim kanıyor bak, bunu ben istemedim. Onlar istedi. Onlar istedi diye de yapmadım. Ben istediklerimi yaptım, çünkü böyle gördüm senden. 

Bir fotoğraf kalacak elinde biliyorum. Ne anlatır, hüzünden başka, artık nefes almayan birinin fotoğrafı. An, ne kadar saklı kalır bir yürekte. Son seveni de bakmaz olunca mı ölür fotoğraflar? 

Ölüm haklı çıkarmaz biliyorsun. 

Ölümsüzlük çok daha zor baba. Bunu öğretmedin. 

Bir basamak daha: 

Okuduğum bütün şiirler geçiyor şimdi aklımdan. Ölüme yaklaşınca hayatın geçer film şeridi gibi diyenlere bunu söylemek isterdim. Kendi yüzüm bu şiirlerin içinde geziniyor. En sevdiğim şarkıyı söylüyorum içimden. Birileri şimdi kahvaltı yapıyor diye düşünüyorum aile sofrasında. çocuğu bıçağı kirletti diye bir anne yüzünü ekşitiyor. bir kadın eteğini kaldırıyor bir başka şehvetli güneşin altında. Antartika’ da, Afrika’ da neler oluyor. Hindistan’ da daha kaç kadın ölecek sistem yaşasın diye. Ya bu topraklarda. Kaç türkü daha söylenecek zulüm adına. Türküler zulmün önünü kesmiyor, sadece anlatıyor baba... 

Son basamak: 

Var mı sahi son basamak. Asıl, bu basamaklardan inerken düşünüyorum kendimi ter içinde. Çıkarken döktüğüm terden daha çok ter içinde. Ellerimde değil terin yumuşak taneleri. gönlümde tek tek.dökülüyor. Yağmur sesi gibi geliyor kulağıma kendi terimin sesi. Sanki kırmızı kan ter taneleri. Yüzümü silmeliyim ama utanıyorum. Ölümün emeği terimden utanıyorum. Yukarıda bekliyor terimi silecek olan. Ebedi gençliğimi. Göz gözeyiz onunla. 

Utançla bakışıyoruz. Ben ölümümü armağan ettiğim için ona, daha çok utanıyorum. Bunu fark ettiğini hissediyorum. Ömrümün son saniyeleri de bir utanç yarışı işte. 

Halkım benden hep utanacak mı baba. Haksızlığa sesini çıkaramayan bir insan korosu Türkçe bir Requem söyleyecek mi bir gün papatyalara karşı. Ter içinde. 

Kaçıncı ölümün kurban görüntüsüyüm acaba. Kendinden şüphe etmeyen kalbimin duruşu kendinden şüphe ettirecek mi sokaktaki birini. Yarın bir çocuğu. Kirpiğimdeki tek ter tanesi yanıtlıyor: Evet! 

Umudum, korkumu öldürüyor. Kendimi hep yaşayacak hissettiriyor bana.ölümsüzlüğün bir başka sırrı olmalı giden için de kalan kadar. Bunu bütün bedenimde hissediyorum. Bedenim baştan sona hayat.nefesi dursa da hayat. 

Hayata inanmayı ölürken de bilmenin huzuru şimdi ikimizin de gözlerinde. onun yanına gidiyorum. 

Duruş: Deniz''in mavi boynuna geçirirken yuvarlak ipi: Elleri titriyor hayatın. 

6 Mayıs - 25 Haziran 2005', 'DENİZ''İN MAVİ BOYNU, Deniz Gezmiş ve arkadaşları için yazılmıştı.  Ne gariptir ki Haziran''da bir başka Deniz yürekli bir devrimciyi yitirdik...', ARRAY['Türk Edebiyatı','Şiir','Yelda Karataş']::text[], 8.5, '{"poet":"Yelda Karataş","poet_slug":"yelda-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/deniz-in-mavi-boynu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Resmi', 'askin-resmi-sahin-karakulunc-07uww', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üç şiir yazdım

Birini aşka,

Birini özleme,

Birini yalnızlığa

Sonra hepsini topladım

Kestim kıtır kıtır 

Dizeleri cümleye

Kelimeleri heceye böldüm 

Satır satır.

Kırpıkları topladım avucuma

Karıştırdım, karıştırdım.

Biirr üfledim…

Saçıldılar tüy gibi havaya.

Yavaş yavaş uçuştular

Kar taneleri gibi konuştular yere.

Her parçası şiirin

Kendi içinde sözleşmiş gibi

Toplandılar bir araya.

Kelimeler buluştu.

Siyah- beyaz bir resim oluştu.

İki seven yürek,

İki sıcak el, 

İki güzel yüz,

İki çift derin göz.

Ve kenarında yazılı kaldı 

İki kelimelik söz

“İnadına sevmek”

Aşkın içinde varsa,

Bir tutkuysa

İnadına sevmek,

İşte bu aşkın resmidir.

Koy palete boyayı

Al eline fırçayı

İnadına sev,

İnadına boyala

04.06.2005, Devrek', 'Üç şiir yazdım Birini aşka, Birini özleme, Birini yalnızlığa Sonra hepsini topladım Kestim kıtır kıtır  Dizeleri cümleye Kelimeleri heceye b...', ARRAY['Türk Edebiyatı','Şiir','Şahin Karakulunç']::text[], 8.5, '{"poet":"Şahin Karakulunç","poet_slug":"sahin-karakulunc","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/askin-resmi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne tuhaf bir adamım ben', 'ne-tuhaf-bir-adamim-ben-rahim-recep-akdora-9fgc5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok özgün bir adamım ben

Görseniz kaba saba biriyim

ama ruhum var ya 

duygusallığın bu kadarı da fazla gayrı

daldım mı eski anılara

ağlamaklı olurum anında

hele de Kartanem geldi mi aklıma

ezilirim şüpheci gözlerin ağırlığında

coşarım onun güzelliğinde

ateş yakarım utancın göbeğine

topların tüm hayvan alemini

mutlu olurum arasında onların

sonra

bir garip olurum gözlerim söner

ağlar yüreğim.

Hep lanet okurum onunla ilk seviştiğim geceye

Bir düş gibi girmişti yaşamıma

Henüz yanağına yeni kırmızılık düşmüş vişneye benziyordu

Pişmanlığımda uyandım,arzularında uyudum

Uyandıkça uyudum bu düşü sürdürmeye

Uyandıkça uyudum

Artıları toplardım, eksileri toplardım

düşümü sürdürmeye uyurdum yine

zamanla utançlar ölmüştü. ölmüştü kurallar

bir görseydiniz ne kadın olmuştu? ! 

ırgalanırdı bastığı her  yer 

kıskanırdı onu benden bize bakan tüm gözler

ne var ki 

zamanla uzaklaştırdı bizi bizden gelişen olaylar

engeller var artık onu bana getiren yollarda

nankörlüğünden sustular telefonlar

beklemekten usandım, ölmek üzere umutlar da

gözlerini ararım gece boyu kahvemin telvesinde

ne derindi gözleri tüm ışıkları toplar hediye ederdi bana

aldım mı onu kollarıma sönerdi gökte yıldızlar

böcekler susardı

donardı rüzgarlar

biterdi üstümdeki kabalık 

sadece seven bir yürek kalırdım

onunla geceyi uyumadan uyanırdım.

Hiç hatırlamıyorum 

Ona “seni seviyorum” dediğimi

O da hiç sormazdı zaten

Sadece kirpiklerinden sızan bakışlarıyla yudumlardı

.................................................Yüreğimden damıttığım sevgimi

Ne tuhaf bir adamım ben değil mi? !', 'Çok özgün bir adamım ben Görseniz kaba saba biriyim ama ruhum var ya  duygusallığın bu kadarı da fazla gayrı daldım mı eski anılara ağlamakl...', ARRAY['Türk Edebiyatı','Şiir','Rahim Recep Akdora']::text[], 8.5, '{"poet":"Rahim Recep Akdora","poet_slug":"rahim-recep-akdora","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ne-tuhaf-bir-adamim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-sevi-tuncel-tk7yi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve bahar gelip geçti zalim rüzgarlar gibi...Şimdi uzaklarda, istirapli gece yürüyüşlerine ve ince aşk şarkilarina eşlik edecek yildizlarin var mi bilmiyorum.Oradan, uzaklardan gelen mektuplarin beni teselli edecek yerde, biraktigin derin boşlugu büsbütün çogaltiyor içimde. Mektuplarina dokundukça küçülüyorum.Bana yeniden, yeniden sevda dersleri veriyor; aşkin imkansiz denizlerine atiyorsun....', 'Ve bahar gelip geçti zalim rüzgarlar gibi...Şimdi uzaklarda, istirapli gece yürüyüşlerine ve ince aşk şarkilarina eşlik edecek yildizlarin v...', ARRAY['Türk Edebiyatı','Şiir','Sevi Tuncel']::text[], 8.5, '{"poet":"Sevi Tuncel","poet_slug":"sevi-tuncel","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/yeniden-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kalp', 'bu-kalp-alaaddin-kulcuoglu-dh8f1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kalp yüklü vagonları çeken 

Bir lokomotif  gibi güçlüdür belki 

Ve bir çelik kadar dayanıklıdır 

Ama dostların darbelerine 

Bir o kadar dayanıksızdır. 

Kırılır paramparça olur 

Cam gibi', 'Bu kalp yüklü vagonları çeken  Bir lokomotif  gibi güçlüdür belki  Ve bir çelik kadar dayanıklıdır  Ama dostların darbelerine  Bir o kadar d...', ARRAY['Türk Edebiyatı','Şiir','Alaaddin Külcüoğlu']::text[], 8.5, '{"poet":"Alaaddin Külcüoğlu","poet_slug":"alaaddin-kulcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-kalp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-alaaddin-kulcuoglu-264hp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiç sormadım 

Nasıl yaşanılır umutlar 

Demir parmaklıklar ardında 

Özgürlük

Ne  anlatır 

Dört duvar arkasında 

El ele nasıl tutuşulur 

Kelepçeler arasında 

Bilmiyorum yalnızlık nedir 

Kalabalığın ortasında 

Ne düşünür bir balık akvaryumda 

Ve kafeste bülbül 

Nasıl öter', 'Hiç sormadım  Nasıl yaşanılır umutlar  Demir parmaklıklar ardında  Özgürlük Ne  anlatır  Dört duvar arkasında  El ele nasıl tutuşulur  Kelep...', ARRAY['Türk Edebiyatı','Şiir','Alaaddin Külcüoğlu']::text[], 8.5, '{"poet":"Alaaddin Külcüoğlu","poet_slug":"alaaddin-kulcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilmiyorum-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğe Ağladım', 'sensizlige-agladim-mehmet-bicik-zeyb6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece ilk kez 

Sensizliğe ağladım…

Verdiğin acıları,

Çektirdiğin sancıları,

Döktürdüğün gözyaşlarını

Bıraktım bir yana; 

Sıcaklığını,

Saflığını,

Geleceğe dâir umutlarını 

Düşünüp,

Bu gece ilk kez 

Sensizliğe ağladım… 

Bu gece ilk kez 

Sensizliğe ağladım…

Yıktığın yuvamı,

Bitirdiğin havamı,

Kafama vurduğun tavamı

Bıraktım bir yana; 

Beraber döktüğümüz yaşı,

Gezdiğimiz dağı-taşı,

Yediğimiz aşı 

Düşünüp,

Bu gece ilk kez 

Sensizliğe ağladım…

Bu gece ilk kez 

Sensizliğe ağladım…

Evden çekip gitmeni,

Bedduâlar etmeni,

Izdırap çekmeyi öğretmeni

Bıraktım bir yana; 

Kesilmeyen hızımızı,

Boynu bükük kızımızı,

Kötü yazılmış yazımızı

Düşünüp,

Bu gece ilk kez 

Sensizliğe ağladım…

4 Temmuz, 2005 Pazartesi

Burhaniye  20:05', 'Bu gece ilk kez  Sensizliğe ağladım… Verdiğin acıları, Çektirdiğin sancıları, Döktürdüğün gözyaşlarını Bıraktım bir yana;  Sıcaklığını, Safl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sensizlige-agladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım Sana', 'asigim-sana-mehmet-unal-ju3ti', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay parçası gibi güzel yüzünle

Ateş gibi yakan gözlerinle

Misler gibi kokan saçlarınla

Aşığım sana bir tanem

O narin ve soğuk ellerinle

Sarıp sarmalayan kollarınla

Beni ısıtan soğuk teninle

Aşığım sana bir tanem

Dudaklarından düsen kelimelerinle

Kendinden emin tavırlarınla

Beni hayran bırakan dobralığınla

Aşığım sana bir tanem

Beni seven yüreğinle

Hiç bitmeyecek olan sevginle

Bana seni seviyorum demenle

Aşığım sana bir tanem', 'Ay parçası gibi güzel yüzünle Ateş gibi yakan gözlerinle Misler gibi kokan saçlarınla Aşığım sana bir tanem O narin ve soğuk ellerinle Sarıp...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Unal']::text[], 8.5, '{"poet":"Mehmet Unal","poet_slug":"mehmet-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asigim-sana-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Yerin', 'senin-yerin-mehmet-unal-fhrcb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalbimi kaplıyorsun sonsuzluk gibi

Perde çekiyorsun gözlerime peri gibi

Akıyorsun vücudumda su gibi

Dağılıyorsun bedenimde hava gibi

Sen nasıl birşeysin güzel sevdiğim

Seninle, her günümü seninle geçiriyorum

Sırf bu nedenle geçiyor günlerim ve sensizliğin

Kalmıyor umutsuzluğum,kalmıyor üzerime çöken karabasan

Gidiyor ağrılar bırakan acılar.

Doldursanda vücudumu,ruhumu,benliğimi

Görünce çok mutlu oluyorum seni

Sana kavuşupta tuttuğumda elini,

Oksayınca saçını söyleyince seni sevdiğimi

Atıyor kalbim hiç yavaşlamayacak gibi.', 'Kalbimi kaplıyorsun sonsuzluk gibi Perde çekiyorsun gözlerime peri gibi Akıyorsun vücudumda su gibi Dağılıyorsun bedenimde hava gibi Sen nas...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Unal']::text[], 8.5, '{"poet":"Mehmet Unal","poet_slug":"mehmet-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/senin-yerin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Olmayı Düşlüyorum', 'yagmur-olmayi-dusluyorum-mehmet-unal-wo8z5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor bardaktan boşanırcasına

Kendi halinde sessiz sessiz

Her taraf alabildiğince su

Çok ama çok  güzel görünüyor.

Yağmur olmayı düşlüyorum bencilce

Havada bulutlar halinde dolaşmak

Şimşekleri ışığım yapmak istiyor

Önüne geçilmez duygularım.

Ardından yağmak istiyorum

Toprağa dağlara ve nehirlere

Akmak istiyor bedenim nehirde

Alabildiğince hızlı ve özgürce

Sonra denizle kavuşmak istiyorum

Güneş beni havaya Çekmeden

Deniz olup yanına gelmek

Kıyında dalga olup Kayalıklara

Hasretinin verdiği hüzünle çarpmak istiyorum

Taa ki sana ulaşıncaya dek

Ulaşamazsam sana eğer

Güneşle anlaşma yapıp buhar

Buhardan bulut

Bulut tanda yağmur olup 

Yağmayı düşlüyorum üstüne

Seni sarmayı soğukluğumla

Beni içinde hissetmeni istiyorum

Sen kuruyana dek.', 'Yağmur yağıyor bardaktan boşanırcasına Kendi halinde sessiz sessiz Her taraf alabildiğince su Çok ama çok  güzel görünüyor. Yağmur olmayı dü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Unal']::text[], 8.5, '{"poet":"Mehmet Unal","poet_slug":"mehmet-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yagmur-olmayi-dusluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Ayrılık', 'yine-ayrilik-mehmet-unal-dgqgi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine bir tren yine bir ayrılık

Gidiyorum senden

Umudum kırık

Gece ışıkları yok etmeye başladı bile

Uzaklaşıyorum şehrinden aşkın ve sevginle.

Tren seslerini sevmez oldum

Ayrılığı haykırır

Adeta hiç susmayacakmış gibi

Sanki hiç kavuşamazsınız der gibi

Bende haykırıyorum ona:

Sevdigime kavusacagim

Sen ne kadar mani olsan da.

Gidiyorum yine bir trenle

Aklim kalbim vücudum sende

Geçirdiğim muhteşem anlar kalıyor gerimde

Geride kalsa da o anlar

Sen benim her zaman içimde...', 'Yine bir tren yine bir ayrılık Gidiyorum senden Umudum kırık Gece ışıkları yok etmeye başladı bile Uzaklaşıyorum şehrinden aşkın ve sevginle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Unal']::text[], 8.5, '{"poet":"Mehmet Unal","poet_slug":"mehmet-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yine-ayrilik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taksici', 'taksici-ali-dilki-un363', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onikide randevum var sahilde

Çabuk koltuğuna otur taksici

Solmasın çiçekler yazık elimde

Beni bir an önce götür taksici

İşim çok acele zamanım kısa

Sevgilim bekliyor boş kaldı masa

Biraz daha basın ne olur gaza

Beni bir an önce götür taksici

Acelen ne diye sorma ne olur

Daha çok kalbimi yorma ne olur

Kırmızı ışıkta durma ne olur

Beni bir an önce götür taksici.

''''İki Gönül Bir Olunca'''' Sh.42', 'Onikide randevum var sahilde Çabuk koltuğuna otur taksici Solmasın çiçekler yazık elimde Beni bir an önce götür taksici İşim çok acele zaman...', ARRAY['Türk Edebiyatı','Şiir','Ali Dilki']::text[], 8.5, '{"poet":"Ali Dilki","poet_slug":"ali-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/taksici-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-fazli-coban-98224', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlamak ve

 Haykırmak adını  gök maviye

 Büyür  yüreğim 

 Taze kar sıcaklığı  ellerinde 

  

 Balçık kokusu  yalnızlığım  yarılır

  

    Batır tırnaklarını yüreğime

    Kanasın solukla, bedenimde

    Bu sevgi ne şey    böyle

    Uykular uykusuz kalır  gecelerde', 'Ağlamak ve  Haykırmak adını  gök maviye  Büyür  yüreğim   Taze kar sıcaklığı  ellerinde      Balçık kokusu  yalnızlığım  yarılır        Batı...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sensiz-116-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğime İndi', 'yuregime-i-ndi-ali-dilki-6izcf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir dosta rasladım tesadüf bugün

Oturup konuştuk söz ettik senden

O çoktan evlendi dediği zaman

Yüreğime indi duyunca birden

Beynime bir kurşun sıkıldı sanki

Dünyalar başıma yıkıldı sanki

Duyunca kahrımdan öldü inanki

Yüreğime indi duyunca birden

Başımı ömüme eğipte gittim

Bunu nasıl yaptı deyipte gittim

O anda tükendim o anda bittim

Yüreğime indi duyunca birden.

''''İki Gönül Bir Olunca'''' Sh.68', 'Bir dosta rasladım tesadüf bugün Oturup konuştuk söz ettik senden O çoktan evlendi dediği zaman Yüreğime indi duyunca birden Beynime bir kur...', ARRAY['Türk Edebiyatı','Şiir','Ali Dilki']::text[], 8.5, '{"poet":"Ali Dilki","poet_slug":"ali-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yuregime-indi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-fazli-coban-dggns', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sahiplenmediğin  sesin yalandı

Yalandı kaldırımların üşengeçliği

Yalandı yüreğinde ki

Yalandın …

Saçlarını  al

Ses söze ulanmadan  unutulur  zaten

Birde bende kalan hayalini silebilsem 

Yalandın ve ….

Kimler geldi kimler geçti buralardan

Sadece o  mavide kalan

Yada 

Yalan', 'Sahiplenmediğin  sesin yalandı Yalandı kaldırımların üşengeçliği Yalandı yüreğinde ki Yalandın … Saçlarını  al Ses söze ulanmadan  unutulur ...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalan-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaren', 'yaren-fazli-coban-lv6k8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman izini sürerek kirli bir sabahla soluklanıyor.Tenim su tomurcuklarında ıslanıyor.

          Yaşlıydı bu kent ve rüzgar.İnsanlar yalanlarla yıkanıyordu.Yangına durmuştu  yürek ve bu yangında su suçsuzdu.

          Yaren zaman yeşile dokundukça sarartıp döküyordu. Acılar tozlu raflarda yerlerinden alınıp tozları silinip yerlerine konuluyordu. Denizler, dalgaları gizlenerek seviliyordu. 

          Giyinmiş kuşanmış ağaçlar dayamış alnını güne, dallarında kuşları dinliyordu.Sesler geçiyordu kıyılarımdan.Tanıdık değildi çoğu. Ve kimliksizdi.

          Nendeler niçinler  yaren. Bir baykuş yalnızlığında öterken, yıldızlar tutuşuyordu gök tavanında. 

          Koyu karanlıktı. Karanlıkta tanınmıyordu gül. Yaren karanlık gizliyor kirlenen her şeyi. Çocukları düşündüm.Süt kokan ağızlarında taşıyorlardı sevgilerini.Ve istedim yürek yurtlarına girmesin yokluğun elleri

         Yaren bu kimlikler neden kimsesiz.. Bu nedenler niçin siz.Yarınlar neden bensiz. Dağ doruklarında soluklanıyorum yaren. Esen duru yellere söylüyorum düşlerimi. Düşlerim de bitti yaren. Düş satıcıları da gelmez oldu.Bekliyorum. Beklemek boşlatıyor yüreği. 

        Gözlerim gördükçe ağlıyor. Uykular kokuyor gecelerde. Ayaklarımda toprağın izi çoğalıyor.

        Düşündüm yaren her taze gün batımında bir kıyıya atıp yüklerimi gitmeyi. Yurtlar yurtsuz yaren.Hangi deltaların yüreği sıcak. 

       Bilmek nedir ey bilge. Suskunluğum saklanmaz oldu artık bende.Gül veriyorum yaren güle.Gül benzemiyor güldekine. Ağırım yaren hem de çok ağır.   Bir kumru ötüyor az ötede sesi kimliğinde yaren.

       Puşttu ağızda kokan soluklar. Satıcılar bekliyordu omuzlarda. Haindi. Gizli kıyıların da yılanlar tıslıyordu. Yaren bu yolculuk çok uzun be. Soluk yeter mi bilmiyorum. 

      Öfkeliyim kinliyim yaren. Kendini bilmeyen  haldan bilmeze. Tutunmağa çabalıyorum  solmadan yediverenlere. Direniyorum yaren. Yaşamak bu ise. 

      Sırça köşklerinde oturuyor yağ yığınları. Benim kınalı kuzumun sütü yok be yaren. Ellerim çıldırıyor. Kırıyor kapıları. Kapılar neden yapılır yaren. Su önüne koça dağlar neden kalır. Koça kartal neden uçmaz artık mavide.

     Yaren neyi tartışır bu insanlar. Neden soluklarını tüketirler. Neden zamanı harcarlar kendileri gibi. Ömürlerine taktıkları keser her gün yontuyor onları yaren.

      Küflü odalarda zamanın son  notasını bekliyor yaşlılar.Ve bebeler ilk notaya konarken.   Sırlıyım yaren. Yokluğum göçmen kuşlar olacak her şeyde. Mekanlar var yaren. Tuzu kokmuş mekanlar. 

     Yaren ucuz değil hiçbir mısra. Ucuz değil  bir kan damlası.Yürüyen ayak. Sallanan kol olmak var kaldırım suskunluğunda. Yazmak yalnızlığıma vurduğum bir neşter yaren. Yazdıkça kanıyor sol göğsümün altındaki yumru  et parçası. 

     Gitme yaren. Sen gidersen yıkılır bu kent.Ölü kuşlar satılır çiçekçilerde. Fesleğen kokusuz kalır. Gülde güneş batmaz olur. Gitme yaren. 

    Daha yan yana gelecek kelimler var. Ve anlatacak çok şeyleri olan kelimeler.

   Yaren şimdilik hoşça kal sen bana demeden.', 'Zaman izini sürerek kirli bir sabahla soluklanıyor.Tenim su tomurcuklarında ıslanıyor.           Yaşlıydı bu kent ve rüzgar.İnsanlar yalanla...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yaren-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir mi?', 'siir-mi-fazli-coban-a8fhn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uykuları uyandıran ay ışığı 

Buzu eriten söz

Issız kumsalda iz

Denizi coşturan  rüzgar

Uykuları uyandıran ay ışığı 

Buzu eriten söz

Issız kumsalda iz

Denizi coşturan  rüzgar

Bebelerde süt kokusu

Ruhu  terk etme kaygısı

Sol göğsün altında  göz kurşunları

Göçe duran turnalar

Acıyı gül kokusuna çeviren ses dalgaları

Ölümü ölümsüzleştiren mısra

Yan yana gelmemiş kelimelerdir şiir', 'Uykuları uyandıran ay ışığı  Buzu eriten söz Issız kumsalda iz Denizi coşturan  rüzgar Uykuları uyandıran ay ışığı  Buzu eriten söz Issız ku...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siir-mi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Uyanacak', 'gun-uyanacak-fazli-coban-ndhxj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Koyu  karanlık   gece

Uzanmış iniler yatağında

Gün   tutsak kirpikleri  arasında

 	

Koca su,

Uyanır  uykusundan 

İsyan edip, öfke kusar  kumlara 

Mekan  satmış beni

Sende kokusu var mı 

Sevdiğimi saran  rüzgar  eli

Çakıl taşları göz kırpar  birazdan

Kuşlar da sevmek  der

Balıkçı takasına umut yükler

Cigarasını yakar düş kurar

Motoru öksürür içini çeker

Sevinci hüznü dinler

Yeri gelince küfür de yer

Şu sevgi ne menem şey böyle

Gün uyanmadan uyanır 

Ayrılınca günden önce

Uzaklar göçmen kuşlar

Gök mavi ayağım mavi

Yokluğun külün   rengi', 'Koyu  karanlık   gece Uzanmış iniler yatağında Gün   tutsak kirpikleri  arasında  	 Koca su, Uyanır  uykusundan  İsyan edip, öfke kusar  kum...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gun-uyanacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Bilge', 'ey-bilge-fazli-coban-4yo4b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuşanmış yalnızlığı 

Ve ölüleri yıkıyor kent ışıkları

Çocuklar ağlıyor

Kimin bu  kimlik

Terk ederken sınırları 

Kuşlar mavi eteği yırtıyor

Sol göğsümün altında 

Geceye  asılmış gün sırıtır

Uykusuz  baykuş

Kime ne desem

Bilmek nedir ey bilge

Tanrıyı sorgulamaya 

Kuşların beyni yeter mi

Hey  kadın sana kollarımı açtım

Gel bütünleştirelim yalnızlıkları

Bütün yalnızlıklar olsun ikimizin yalnızlığı

Ölüm soğukluğuna 

İhanet dedi duygular

İhanetin anlamı 

Sus ve suskunluğunu kendine sakla', 'Kuşanmış yalnızlığı  Ve ölüleri yıkıyor kent ışıkları Çocuklar ağlıyor Kimin bu  kimlik Terk ederken sınırları  Kuşlar mavi eteği yırtıyor S...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ey-bilge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaren 2', 'yaren-2-fazli-coban-a46ca', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaren yüreğimde kalan  yılların kırıntıları ile yazıyorum sana. Biliyor musun?   Uçurumlar çok derin. 

                               Kar yağdığında yediverenler büyürdü kucağımızda. Sisler kalkardı öbek öbek dağ yamaçlarından. 

                              Bir kartal yarardı maviyi. Öperdim seni. Ve soluğun sıcağında uyurduk. Sana dokununca kan tutardı beni. Yürek yavru güvercindi. 

                 Sıcak ve ürkek bir ceylandın. 

                 Kuş satıcılarından alırdık özgürlüğümüzü. Kaldırımlar da bizimdi.  Kaldırımlardı onlar.Biz bastıkça ayaklarımıza kediler gibi  sokulan.

                 Anımsar mısın?  Dağ lalelerini ilk biz uyandırırdık.  Güneş küserdi günde bize. Ne kadar da kıskançmış güneş.  Oysa biz dokunmazdık onun olan güle.

                 Biz bize benzeyenlerin kokusunu taşırdık.  Aslında biz de benzemezdik bize. Ama seviyorduk. Sensiz sen ya da bensiz ben olmuyordu. 

                 Unuturduk zamanı masaya koyduğumuzda yüreklerimizi. Masa dil verirdi. Kimse bilmezdi. Sırlı sırlarımızı.

                 Bir yudum su serinliğiyle dinlerdim seni. Sen de beni. Zaman çok çabuk tüketti her şey gibi bizi. Zamanın değdiği yerlerde arıyorum izini. Oysa rüzgarlar çoktan almış koynuna bizden arta kalanları.

                  Dün gezindim bizi bize sunan mekanlarda, koca çınarın dallarında kuşlar da vardı ve yabancıydı bana. Kimseler de yoktu. Solmuş yaprakların  sesleri ağlattı beni. Gözyaşlarımı da sakladılar. 

                  Yorgundum. Yataklar da batıyordu bana. 

                  Kitapları karıştırdım. Bana verdiğin gül, arasında solmuş kalmıştı. Düşündüm. Beynimin hangi kuytularında saklamışım o anı. 

                   Kitaplara öfkelendim. Kimisini yırttım attım. Biliyor musun onlar da suçsuz aslında. 

                  Yaren, ak kağıtlar solmuştu. Anda kalanlara bakındım. Gerçek  ne kadar soğuk. Tıpkı sıcakları üşüten karlar gibi.

                  Yaren kendimde değilim. Ruhun yaralarını dinlendirecek bir şey de bulamadım. Avareler gibi geziniyorum sensiz. 

                                                                                          30 Haziran 2005', 'Yaren yüreğimde kalan  yılların kırıntıları ile yazıyorum sana. Biliyor musun?   Uçurumlar çok derin.                                 Kar ya...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaren-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-fazli-coban-oq0vq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaren yüreğimde kalan  yılların kırıntıları ile yazıyorum sana. Biliyor musun?   Uçurumlar çok derin. 

                               Kar yağdığında yediverenler büyürdü kucağımızda. Sisler kalkardı öbek öbek dağ yamaçlarından. 

                              Bir kartal yarardı maviyi. Öperdim seni. Ve soluğun sıcağında uyurduk. Sana dokununca kan tutardı beni. Yürek yavru güvercindi. 

                 Sıcak ve ürkek bir ceylandın. 

                 Kuş satıcılarından alırdık özgürlüğümüzü. Kaldırımlar da bizimdi.  Kaldırımlardı onlar.Biz bastıkça ayaklarımıza kediler gibi  sokulan.

                 Anımsar mısın?  Dağ lalelerini ilk biz uyandırırdık.  Güneş küserdi günde bize. Ne kadar da kıskançmış güneş.  Oysa biz dokunmazdık onun olan güle.

                 Biz bize benzeyenlerin kokusunu taşırdık.  Aslında biz de benzemezdik bize. Ama seviyorduk. Sensiz sen ya da bensiz ben olmuyordu. 

                 Unuturduk zamanı masaya koyduğumuzda yüreklerimizi. Masa dil verirdi. Kimse bilmezdi. Sırlı sırlarımızı.

                 Bir yudum su serinliğiyle dinlerdim seni. Sen de beni. Zaman çok çabuk tüketti her şey gibi bizi. Zamanın değdiği yerlerde arıyorum izini. Oysa rüzgarlar çoktan almış koynuna bizden arta kalanları.

                  Dün gezindim bizi bize sunan mekanlarda, koca çınarın dallarında kuşlar da vardı ve yabancıydı bana. Kimseler de yoktu. Solmuş yaprakların  sesleri ağlattı beni. Gözyaşlarımı da sakladılar. 

                  Yorgundum. Yataklar da batıyordu bana. 

                  Kitapları karıştırdım. Bana verdiğin gül, arasında solmuş kalmıştı. Düşündüm. Beynimin hangi kuytularında saklamışım o anı. 

                   Kitaplara öfkelendim. Kimisini yırttım attım. Biliyor musun onlar da suçsuz aslında. 

                  Yaren, ak kağıtlar solmuştu. Anda kalanlara bakındım. Gerçek  ne kadar soğuk. Tıpkı sıcakları üşüten karlar gibi.

                  Yaren kendimde değilim. Ruhun yaralarını dinlendirecek bir şey de bulamadım. Avareler gibi geziniyorum sensiz. 

                                                                                          30 Haziran 2005', 'Yaren yüreğimde kalan  yılların kırıntıları ile yazıyorum sana. Biliyor musun?   Uçurumlar çok derin.                                 Kar ya...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yar-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güne Bakan', 'gune-bakan-meral-vurgun-l00oz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ufuk’uma

güne bakan 

zeytin gözlerin ışıltısıyla

gün öptü onu yanağından

uyandım... 

her yanı gül kokusu

tutup iki kolundan

çektim bağrımın üstüne

taze karanfil gibi kokladım

öptüm mercan dişinde gülüşlerini

ay kahvemi getiren güzel adamım 

gözlerinde gök damlaların çiyliği

ellerinde baharın tazeliği

teninde bütün çiçeklerin kokusu var

içerim içerim de doyamam

ki, ben sana bilsen nasıl vurgunum

uyur(dun) sun yüzünde gözlerimle

uyanır(dın) sın gözlerimde gülüşünle

bakmaya bile kıyamam ki...

adamım 

sen varsın ya

çok canım var dayanacak

ve bin can verseler de 

bini de yine sana adanacak... 

seni kıpır kıpır ilk duyumsadığım 

gün gibi mutluyum bu gün... 

25.06.2005', 'Ufuk’uma güne bakan  zeytin gözlerin ışıltısıyla gün öptü onu yanağından uyandım...  her yanı gül kokusu tutup iki kolundan çektim bağrımın ...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gune-bakan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemem', 'i-stemem-fazli-coban-z2tt2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstemem kimseden,

Sadece mutluluk  resminden başka

Ya da, 

Fırtınaya, rüzgara inat  sesimden  başka 

İstemem,

Ak ve  duru gökten  başka

Yalnız doğmuşum ölümü de karşılarım bir başıma

Şükür şimdilik,

Ayaklarım toprakla. 

Acılar bedenimi tutuştursa da,

Yaşam   sonuna.

Sevgi de  paylaşımdır zaman öğretti bana .

İstemem ,

İstemem,yeterim  bir  başıma.', 'İstemem kimseden, Sadece mutluluk  resminden başka Ya da,  Fırtınaya, rüzgara inat  sesimden  başka  İstemem, Ak ve  duru gökten  başka Yaln...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istemem-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürekte Yakılan Şehir', 'yurekte-yakilan-sehir-fazli-coban-pr4ir', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Diyar,  ürkek yıldızlar

 Sustu dolunay

 Engerekler, çıyanlar 

Ve zehirler … 

Güvercin kanadıyla  geldi canlar 

Kentler  taşındı kente 

Bağlama ozan ömrü 

Kalem  usta öykü

Yaktı kin ateşini  iki ayaklı

Ateş  köpüklerine  karıştı

Kalemin çığlıkları

Kentte

Ozanın sazı

Ustamın ak yazısı  kaldı

Koca dağlar 

İndi   toprağa 

Temmuz sıcağında', 'Diyar,  ürkek yıldızlar  Sustu dolunay  Engerekler, çıyanlar  Ve zehirler …  Güvercin kanadıyla  geldi canlar  Kentler  taşındı kente  Bağla...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yurekte-yakilan-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
