INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'D11 - Günlerimiz', 'd11-gunlerimiz-tahir-gungor-y589m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sofra bakır bir çanak,

Biz de edrafa çönek,

Hepsi bu, yok seçenek,

............................Yiyecek aş,

............................Aşımızdı.

Sana has bir odan yok,

Bugünkü varlar, dün yok,

Yalın bir gömlek, don yok,

............................Giyimdi,

............................Kuşamımızde.

Köy dışına çıkamak,

İşten gizli kaçamak,

Az biraz, çelik çomak, 

............................Eğlence,

............................Oyunumuzdu.

Dayı, amca, dedeler,

Oyun yasak dediler,

Şamar, çırpak dövdüler,

............................A c ı l ı,

............................Öğünümüzdü.

Gün öğleye kavuşa,

Yayvan yatar gevişe,

Yan gel yat, gevşe,

............................En candan,

............................Sevincimizdi.

Her gün tarla, kır bayır,

Günü günden zor ayır,

Yılda bir kez panayır.

............................Merakla,

............................Beklentimizdi.

Azlı, zorlu yıllara,

Yazlı tozlu yollara,

Varsak, konsak orlara,

............................Varamayız,

............................Eremeyiz,

............................Özler, özleriz.', 'Sofra bakır bir çanak, Biz de edrafa çönek, Hepsi bu, yok seçenek, ............................Yiyecek aş, ............................Aşımı...', ARRAY['Türk Edebiyatı','Şiir','Tahir Güngör']::text[], 8.5, '{"poet":"Tahir Güngör","poet_slug":"tahir-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/d11-gunlerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nefeslik Bir Düş', 'bir-nefeslik-bir-dus-arzu-dincer-vyvkt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kapat gözlerini,

Bir nefes doldur ciğerlerine! 

Düşle! 

Vazgeçemem dediğin şeyleri…

Bir gün düşle,

Gözlerini açtığında..

Uyanan bedenine

Veremediğin lokmayı…

Ve onun isyanını..

Düşün ki, susuz kalmışsın,

40’ları aşmış sıcaklık…

Çatın yok sığınacağın…

Tükenmeye hazır…

Çaresiz bekliyorsun..

Az ötende yitenler gibi! 

Urban yok serin tutacak…

Potinin ayağını,

Kızgın topraktan ayıracak …

Dünyan bulundugun yer kadar…

Aç gözlerini,

Boşalt ciğerlerini..

Dünyan aynı dünya mı?', 'Kapat gözlerini, Bir nefes doldur ciğerlerine!  Düşle!  Vazgeçemem dediğin şeyleri… Bir gün düşle, Gözlerini açtığında.. Uyanan bedenine Ver...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-nefeslik-bir-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-rahmi-aksoy-il31c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıkarın...

Verdiğinizi 

Aldığınız nefesten

Söylediğiniz sözü

İşittiğiniz sesten

Çıkarın 

gecelerinizi gündüzlerinizden

bilmediklerinizi bildiklerinizden 

Görmediklerinizi gördüklerinizden

Çıkarın 

Ne kaldı geriye? 

Lüzum var mı başka veriye

Hayat 

Mutluluğu hüzne bölmektir

En sonunda hayat 

Geldiğin yere geri dönmektir.', 'Çıkarın... Verdiğinizi  Aldığınız nefesten Söylediğiniz sözü İşittiğiniz sesten Çıkarın  gecelerinizi gündüzlerinizden bilmediklerinizi bild...', ARRAY['Türk Edebiyatı','Şiir','Rahmi Aksoy']::text[], 8.5, '{"poet":"Rahmi Aksoy","poet_slug":"rahmi-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayat-223-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıradan Birisin', 'siradan-birisin-abdulkadir-karaca-wt6uo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin de saçların sarı

Senin de gözlerin yeşil artık

Sende basit duyguları mühürlemişsin yüreğine

Sende terketmeyi maharet bildin değil mi? 

Yazık değil mi ağlarken gözlerine? 

Senin de dudaklarından kelimeler silinmiş

Kirletmişsin yine en temiz ümitlerini

Sende üç beş kuruşun peşine düşmüşsün

Kızgın değilim inan ki

Bilirim sen sahte sevdalar elinde büyümüşsün

Sen artık benim için sıradan birisin

Sokakta gördüğüm güzel kızdan farksızsın

Senin gibiler kuşlara aşıktır

Senin gibiler mutluluk bekler

Ama senin yüzünden aylardır ödediğim bu bedel

Tüketti,bitirdi,yıktı beni

Belki hala beni istemektesin

Ama çok geç

sen artık kalbime sıradan birisin

(1 Ekim 2005)', 'Senin de saçların sarı Senin de gözlerin yeşil artık Sende basit duyguları mühürlemişsin yüreğine Sende terketmeyi maharet bildin değil mi? ...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siradan-birisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Yapamıyorum', 'sensiz-yapamiyorum-pinar-bulduk-2yqep', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gün yine sensiz uyandım yenidoğan güne

Çok zor inan sensizlik

Nasıl yaptım bunu sana bilmiyorum

Bir anlık heves için kaybettim seni

Bilirim gururlusun affetmezsin beni

Her yerde sen varsın

Odanın duvarlarında yastığımda

Kokun sinmiş her yere 

Bir nefes çektim içime kendimden geçtim

Ben bu kötülüğü sana nasıl yaptım

Dışarı çıktım seninle dolaştığımız yerlerde dolaştım 

Caddelerde yürüdüm umarsızca

Oturduğumuz banka oturdum ama bu kez sensiz yapayalnız

Güneşin batışını seyretttim

Farkettimde bi akşam daha oldu sensiz

Eve döndün tam zile uzandığım o an

Aklıma boynuma sarılışın geldi

Lanet ettim kendime benliğime

Nasıl yapardı insan bunu sevdiğine

Şimdi nasıl derim dön bana geri

Ama bil hala çılgınlar gibi seviyor seni bu deli', 'Bu gün yine sensiz uyandım yenidoğan güne Çok zor inan sensizlik Nasıl yaptım bunu sana bilmiyorum Bir anlık heves için kaybettim seni Bilir...', ARRAY['Türk Edebiyatı','Şiir','Pınar Bulduk']::text[], 8.5, '{"poet":"Pınar Bulduk","poet_slug":"pinar-bulduk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sensiz-yapamiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıktım', 'biktim-ertan-akbayrak-rmbr2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kadar benzetmiştim seni,sevgiye,sevgiliye...

Ne kadar benzetmiştim ben seni,herşeye...

Bıktım artık acı çekmekten...

Kendimi avutmaktan...

Güneşin,her sabah doğudan doğup...

Yüreğimde batmasından bıktım...

Geceleri yüreğimin bulutlar ile çarpışmasından...

Gözlerimden akan yağmurdan bıktım...

Bastığım toprağın renginden,kokladığım çiçeklerin hüznünden

BIKTIM...

Öyle bir hale getirdin ki beni,ben bıkmaktan bile bıktım

Daha nelerden bıkmadım ki...

Geceleri şiir yazmaktan...

Seni hatırlatan şarkı sözlerinden...

Ve tam demlenip kafayı bulunca...

Seni arayan bu gözlerden bıktım...

Geceler sen olmayınca çok uzun...

Çok kısa gündüzler,sen aranınca...

Bulutlara bakınca,yağmurlarla sitemimi...

Güneşe darılınca,gözlerimi hatırla...

Ve Bebek  Kokusu şunu sakın unutma:

Ben sensiz olan herşeyden bıktım...

Öyle bir hale getirdin ki beni...

BEN BIKMAKTAN BİLE BIKTIM...', 'Ne kadar benzetmiştim seni,sevgiye,sevgiliye... Ne kadar benzetmiştim ben seni,herşeye... Bıktım artık acı çekmekten... Kendimi avutmaktan.....', ARRAY['Türk Edebiyatı','Şiir','Ertan Akbayrak']::text[], 8.5, '{"poet":"Ertan Akbayrak","poet_slug":"ertan-akbayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/biktim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erek ve Özveri', 'erek-ve-ozveri-hasan-kaplan-v6zmb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'EREK VE ÖZVERİ

Spartaküs yürüyor en önde

Spartaküs ölür müydü

sonunda köleliğin sonu olmasa

Ferhat deler miydi dağları

dağların sonunda Şirin olmasa

ya ben ya ben

ölür müydüm böyle kısa günde bin kez

sonunda sana kavuşmak olmasa', 'EREK VE ÖZVERİ Spartaküs yürüyor en önde Spartaküs ölür müydü sonunda köleliğin sonu olmasa Ferhat deler miydi dağları dağların sonunda Şiri...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaplan']::text[], 8.5, '{"poet":"Hasan Kaplan","poet_slug":"hasan-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/erek-ve-ozveri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nemelazımcı', 'nemelazimci-hasan-kaplan-du92e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'NEMELAZIMCI

ateş düştüğü yeri yakarmış 

yanan benim yüreğim

öyleyse bakmadan geçebilirsin

geç bakalım

daha ne kadar kaçacaksın bu yangından', 'NEMELAZIMCI ateş düştüğü yeri yakarmış  yanan benim yüreğim öyleyse bakmadan geçebilirsin geç bakalım daha ne kadar kaçacaksın bu yangından...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaplan']::text[], 8.5, '{"poet":"Hasan Kaplan","poet_slug":"hasan-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nemelazimci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak', 'korkak-hasan-kaplan-l5zfn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KORKAK

kapattın gözlerini

karanlıktan korktun

açtın

gördüklerinden korktun

kapattın korktun

açtın korktun

ne korkak şeysin be kardeşim', 'KORKAK kapattın gözlerini karanlıktan korktun açtın gördüklerinden korktun kapattın korktun açtın korktun ne korkak şeysin be kardeşim...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaplan']::text[], 8.5, '{"poet":"Hasan Kaplan","poet_slug":"hasan-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/korkak-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Çocukları', 'gunesin-cocuklari-hasan-kaplan-myykn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GÜNEŞİN ÇOCUKLARI

tutkuyla koyulduk 

uzunca bir yürüyüşün yollarına

yüreğimizle kuşatıp fethederek kentleri

doklarda çekiç sesleriyle açıldık

maceralı deniz yolculuklarına 

alnımızı dağlara verip

yağız bir atlı gibi dolaştık bozkırlarda 

ayı gümüş bir tepsi gibi önümüze serip 

kadehlerde yudumladık güneşi

o gün bugündür

damarlarımızda ateş dolaşır

güneşin çocukları derler bize', 'GÜNEŞİN ÇOCUKLARI tutkuyla koyulduk  uzunca bir yürüyüşün yollarına yüreğimizle kuşatıp fethederek kentleri doklarda çekiç sesleriyle açıldı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaplan']::text[], 8.5, '{"poet":"Hasan Kaplan","poet_slug":"hasan-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gunesin-cocuklari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık,Uzak Ve Sen', 'karanlik-uzak-ve-sen-abdulkadir-karaca-t0wc5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlık

Gece ve gündüz karanlık

Ruhumda kanıksayıp,özünü kanıtlayamadığım sensiz

Kelimeler,düşünceler,sesler,günler karanlık

Uzak

Yokluğu benimseyip seni kaybettiğimden beri

Harflerim isyan çıkarıp yıkınca kelimeleri

Biliyorum artık

Mutluluk deme,isteme benden

Bu ardışığı bol yalan

Bana uzak

Karanlık,uzak ve sen

Şimdi benden uzakta her nerdeysen

Ben kesik kesik ağlarken sen bütün işvenle gülüyormusun? 

Benimşe birlikte ağlayan bir evren biliyorum

Mekanı yok,zamanı senin bitişinle başlar

Eminim ne kadar taştan da olsa

Senin kalbin de birgün ağlar

Dönmek istersen bana

Adresim

Gel gelebilirsen:

Karanlık,uzak ve sen

(04,10,2004)', 'Karanlık Gece ve gündüz karanlık Ruhumda kanıksayıp,özünü kanıtlayamadığım sensiz Kelimeler,düşünceler,sesler,günler karanlık Uzak Yokluğu b...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/karanlik-uzak-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevdiğim', 'benim-sevdigim-hasan-kaplan-6p359', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SEVDİĞİM

benim sevdiğim 

özlem uyutur

sevda büyütür

	saksılarında yüreğinin

benim sevdiğim 

mutluluk düşler

umut işler

	gergeflerine yüzünün

benim sevdiğim 

sevgi arar

hüzün tarar saçlarında

benim sevdiğim 

sahi nerede benim sevdiğim', 'SEVDİĞİM benim sevdiğim  özlem uyutur sevda büyütür 	saksılarında yüreğinin benim sevdiğim  mutluluk düşler umut işler 	gergeflerine yüzünün...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaplan']::text[], 8.5, '{"poet":"Hasan Kaplan","poet_slug":"hasan-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/benim-sevdigim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Sana', 'hep-sana-hasan-kaplan-chxrf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'HEP SANA

hep sana çıkıyor yollarım

ne kadar bağlasalar da düğüm düğüm

hep sana takılıyor düşlerim

sende son buluyor korkularım

ne kadar çökerse çöksün karabasanlar

hep sen söndürüyorsun

yüreğimdeki ateşi

sen dağıtıyorsun

yüreğime çöken sisi

bu yangın 

bu timsah barındırmaz bataklıklar içinde

haydi tut elimi

götür beni ışık huzmesine

öyle çok kaldım ki karanlıkta 

korkuyorum bu bir ılgım mı

haydi yaklaş 

başımı omzuna koyayım

- “serde erkeklik var”mış boş ver

ağlamak istiyorum dizlerinde sırılsıklam

belki çorak toprağı deler çekirdek

	           gözyaşlarımın gücüyle

haydi okşa ayaz yanığı yanaklarımı

öp kızıl kan içindeki patlak dudaklarımı

sil ki gözyaşlarımı gülsün çocuklar', 'HEP SANA hep sana çıkıyor yollarım ne kadar bağlasalar da düğüm düğüm hep sana takılıyor düşlerim sende son buluyor korkularım ne kadar çöke...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaplan']::text[], 8.5, '{"poet":"Hasan Kaplan","poet_slug":"hasan-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hep-sana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleniş', 'seslenis-hasan-kaplan-tx65u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SESLENİŞ 

güneş olayım

	      ışıt 

                         ısıt

                          yak beni

	            kıpkızıl kor ateşlerle alev alev

deniz olayım yut 

          dalga dalga

	     köpük köpük

		hırçın ve sakin

ana olayım doğur

        sıcak sevecen

özgürlük olayım 

               ak güvercin misali

		    sana tutsak

ki

  anlaşıla

	ne kutsal

		ne yüce

			erişilmesi ne güç olduğun', 'SESLENİŞ  güneş olayım 	      ışıt                           ısıt                           yak beni 	            kıpkızıl kor ateşlerle ale...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaplan']::text[], 8.5, '{"poet":"Hasan Kaplan","poet_slug":"hasan-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seslenis-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martı', 'marti-hasan-kaplan-k2pcz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'MARTI

	- Martılarla tutkun Hülya’ya -

martı olmak isterdim

bir mevsimlik

altımda mavi deniz

üstümde mavi gök 

kanat çırpmak isterdim

mavilikler içinde

martı olmak isterdim

bir mevsimlik

yaşamın sonsuz maviliklerinde

mavi göklerde süzülürken ölüp

mavi denizin

lacivert balıklarına yem olmak isterdim

martı olmak isterdim 

yalnızca bir mevsimlik 

bir mevsim martı olmak 

bir ömre bedel', 'MARTI 	- Martılarla tutkun Hülya’ya - martı olmak isterdim bir mevsimlik altımda mavi deniz üstümde mavi gök  kanat çırpmak isterdim mavilik...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaplan']::text[], 8.5, '{"poet":"Hasan Kaplan","poet_slug":"hasan-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/marti-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altın Şehir', 'altin-sehir-ayhan-isin-tfaqi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu hikaye nerede başladı

Bir şehir mi anlatmalı

Bu vatanın hangi şehri

Dillere destan değil ki? 

Bir tren düdüğünde başladı hikaye

Bozkırların,çayırların,dağların arasından

Ateşi körükleyen ateşçiler

Kara trenin doymak bilmeyen karnını doyurur.

Önce derya göründü

Sol tarafta.

Sonra evler,bahçeler

Sağ tarafta.

Laleler,güller,hanımelleri

Kara tren tarihe dalar gibi geçti

Taş binalı istasyonlardan

Sonra dağ gibi binaların önünde durdu,

Oflayarak puflayarak yorulmuş gibi

Sonra insanlarda telaşe

Ağlayanlar,gülüşenler,kavuşanlar,

Deniz kokusu martı çığlıkları.

Tarihin içinden geçtim

Renkli camlar,

Cıvıl cıvıl güneş ışınları.

Durdum baktım; 

Deniz derya martılar yosun kokusu

Gemiler gelin kızlar gibi

Ya çığlıkları! 

İleride mendirek deniz feneri,

Taa uzaklarda

Sisin buğusunda

Füzeler gibi yükselmiş camiler

Simitçiler,taksiciler

Teleşla koşuşan insanlar.

İşte özlenen altın şehir,

Sevinçle korkunun birleştiği yer,

İçimde duyulmamiş duygular.

Bir gelin kız geliyor çiğlık atarak

Boğazı köpük köpük yararak

Beni alıyor bağrına Asyadan,

Götürecek memleketim Avrupaya.

Bir düdük sesi,

Homurdanarak silkelenerek kalkıyor.

Martı çığlıkları masmavi deniz

Yarıyor suları vapur; 

Bir martının kanadında süzülür gibi.

Boğazın suları akıyor sanki git dercesine

Denizin ortasında bir nöbetçi gibi; 

Kız kulesi

Hangi şaire konu olmamış ki? 

Vapur varıyor. 

İskelede halatçilar

Bağlıyorlar Hırçın gelini.

Yürüyorum

Bir köprüden geçmek gibi

Geçmişi geleceğe bağlayan

Oltacılar sıra sıra

İstavritler oynaşıyor oltalarda

Yosun kokusu,tavada balık kokusu,

Anason kokusuna karışıyor.

Şen kahkahalar köprü altı lokantalar,

Balık ekmekçiler,

Yeni camide uçuşan güvercinler,

Baharat kokuları,hayvan çığlıkları

Renk renk çiçekler,laleler,

İşportada çeşit çeşit giysiler,

Şipşakçilarda İstanbul hatırası resimler. 

Tarihin buluştuğu yer; 

Kapalı çarşıda mücevherciler

Altınlar,gümüşler,şiracılar,

İngilizler,Almanlar,Fransızlar,

Japonlar,Zenciler, Araplar,

Sultan Ahmet''te buluşmuş; 

Tüm Dünyalılar.

Şortlular,çarşaflılar,mini etekliler

Köylüler,kentliler

Mahşer yeri deyil de ne? 

Adını anmadan kentin 

Cennet koysan,Cehennem koysan ismini

Yakışmaz mı bu kente? 

Neresinden bahsetmeli bu altın kentin.

Alınmasın benden bahsetmedi diye

Boğazın erguvan ağaçları,

Çamlıcanın manzaraları,

Şilenin kumları,

Adaların mimozaları,

Beykozun paçası,

İstiklal caddesinin büyüsü,

Varoşların kırmizi tuğlalı evleri,

Şairleri,şarkıcıları,

Bahsi geçmemiş nice yerleri.

Bir hoş seda yükselen; 

Camileri, meyhaneleri

Bir resim,bir tablo anlatmaya yetmez 

Bir mozaik rengarenk

Dünyanın çümbü işte burası

Başı olan,Sonu olmayan 

Tek hikaye,Tek şiir İSTANBUL.

(12-07-2005)', 'Bu hikaye nerede başladı Bir şehir mi anlatmalı Bu vatanın hangi şehri Dillere destan değil ki?  Bir tren düdüğünde başladı hikaye Bozkırlar...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Işın']::text[], 8.5, '{"poet":"Ayhan Işın","poet_slug":"ayhan-isin","theme":"Türk Şiiri","is_hero":false,"total_lines":98,"source_url":"https://www.antoloji.com/altin-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Bir Yaşam', 'boyle-bir-yasam-hasan-kaplan-bmp51', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BÖYLE BİR YAŞAM

bir şafak vakti düştük yola

kuşlar uyanmamıştı

yorgun geçen gecenin ardından

çiçekler üşümüş

ağlıyordu kırlarda

pusudaydı ölüm zamanlı zamansız 

ay’ı perdelemişti bir bulut 

tazeliğini yitirmişti

yapraklardaki çiğ damlası

şaşmamak elde mi 

ne kadar anlamsızlaştığına yaşamın

bir kadın açmıştı güneşe kapısını

süpürüyordu şafağa

gecenin lanetli kalıntılarını

yüzünde yorgunluğu gecenin 

saçları yerlerde sürünüyor

bir bebek ağlıyordu bir yerlerde

aldatılmayı kabullenmeyip

atarak ağzından yalancı memeyi

kızmamak elde mi

soğuk dudaklarıyla ölümün

her gece alnımdan öpüp 

yüreğimi yoklayışına', 'BÖYLE BİR YAŞAM bir şafak vakti düştük yola kuşlar uyanmamıştı yorgun geçen gecenin ardından çiçekler üşümüş ağlıyordu kırlarda pusudaydı öl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaplan']::text[], 8.5, '{"poet":"Hasan Kaplan","poet_slug":"hasan-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/boyle-bir-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benzeş', 'benzes-hasan-kaplan-pn047', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BENZEŞ

neden

her çarmıha gerilişimde

hep İsa’ya benzetirler beni

oysa ben 

Spartaküs gibi hissederim kendimi', 'BENZEŞ neden her çarmıha gerilişimde hep İsa’ya benzetirler beni oysa ben  Spartaküs gibi hissederim kendimi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaplan']::text[], 8.5, '{"poet":"Hasan Kaplan","poet_slug":"hasan-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/benzes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek ve Düş', 'gercek-ve-dus-hasan-kaplan-bcaqk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'DÜŞ VE GERÇEK

her gece

neler görmem ki düşümde

hiç bitmese diyorum

bu güzel düşler

sabah uyanıp ta

yüzyüze geldiğimde acı gerçekle

safkan Arap Altından inip

Merzifon Eşeğine binmişe dönüyorum', 'DÜŞ VE GERÇEK her gece neler görmem ki düşümde hiç bitmese diyorum bu güzel düşler sabah uyanıp ta yüzyüze geldiğimde acı gerçekle safkan Ar...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaplan']::text[], 8.5, '{"poet":"Hasan Kaplan","poet_slug":"hasan-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gercek-ve-dus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Atfettiğim Herşey', 'sana-atfettigim-hersey-abdulkadir-karaca-2t4o0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Satırlarımda umut buluyorum yosun tutmuş mercanlara dair

Ne kadar kum kaçsa da gözlerime inci inci gözyaşlarım değersiz

Onun için bu düşmanlık istiridyeye

Su beklerken serap görmenin hayal kırıklığını yaşatma bana

En adi yalanları bilirim ve yalan söyleyen insanların bakışlarını

Bu yüzden sakın bir daha seversin deme

Kıvılcımın boşluğu yakması felaketmiş

Sensizliğin acısını tatmamış günahkarlar onlar

Bir ömrü feda farzdır sevgiye

Seni düşündüğümde uykusuzluğumun feryatlarını bir duyabilsen

Amaçsızca sabaha kadar adını tekrarlamanın mutluluğu

Değer uykusuzluğu tükenene kadar çekmeye

Adından öte dünyada ne var ayyüzlüm

Yollar düşman olsun umrumda değil

Yeter ki bir kere yanıma gel de

(27,12,2004)', 'Satırlarımda umut buluyorum yosun tutmuş mercanlara dair Ne kadar kum kaçsa da gözlerime inci inci gözyaşlarım değersiz Onun için bu düşmanl...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sana-atfettigim-hersey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortasındayım Bir Yıkıntının', 'ortasindayim-bir-yikintinin-hasan-kaplan-30vke', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ORTASINDAYIM BİR YIKINTININ

ortasındayım bir yıkıntının

bir yanım tarih

bir yanım gelecek

her yanım zafer

her yanım yenilgi

yüzümü dönüp tarihe

yürüdüm yıkıntılar içinde geleceğe 

gözlerim yanıyor

               gözlerin nerede

               gözlerin hani

ortasındayım bir yıkıntının

bir yanım teslimiyet

bir yanım direnç

kitabına uydurulmuş cinayetler

yaldızlı sözcüklere gizlenmiş büyük dönüşler

ihanetler “Sudaki İz”ler

		     “Gece Dersleri”

ve çirkef yığını içinde bir pırlantadır onur

hey onur silkiniş nerede

		     silkiniş hani

ortasındayım bir yıkıntının

şöyle bir karıştırıp sayfalarını anıların 

yürürken bir hançer gibi

	    deşmek için karanlığın bağrına

geçtiğimi gördüm birkaç kez kıyıcığından ölümün

vur emirleri ölüm fermanları

kurşun sağanakları ve darağaçları

ve her gerilişimde İsa gibi çarmıha 

hep Spartaküs gibi indiğimi gördüm çarmıhtan

hey neredesin hümanizm

		insanlık hani 

ortasındayım bir yıkıntının

karlara çıkartıyorum

Yürüdüğüm yollarda ayak izlerimi

belki 

buz üstüne yazılan yazı kadar kısadır ömrü izlerimin

belki buzullardaki kadar uzun

yüzyıllar sonra bir gün 

araştırmacılar bulup çıkartırlarsa

kar altındaki ayak izlerimi

en büyük ödülüm olacaktır benim

bir gün çocukların ders kitaplarının

     bir köşesinde konuk olmak

şimdi ortasındayım bir yıkıntının', 'ORTASINDAYIM BİR YIKINTININ ortasındayım bir yıkıntının bir yanım tarih bir yanım gelecek her yanım zafer her yanım yenilgi yüzümü dönüp tar...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaplan']::text[], 8.5, '{"poet":"Hasan Kaplan","poet_slug":"hasan-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ortasindayim-bir-yikintinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Aynı', 'hep-ayni-efsun-aydin-6ktpt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sanki kimsesiz kaldım sen gidince,

Elim ayağımmışsın benim.

Kendimi taşıyamaz oldum artık.

Hep bir fazla var benden şimdilerde.

Durmuyor eski sen gözlerimde,

Kalbim bir başka seni yaşatıyor içinde.

Zaman Unutma zamanıdır artık 

Nedeninde nasıllığında en son durulacak 

Ve sade bir yalnızlık hayatıma renk katacak…

Kalkıp gitmek gerek oturduğun koltuktan,

Ve seni  unutmak gerek…

Ve öylece bir durmak 

Sadece bakmak…

Ve görmek istediklerini görmek! 

Ve tam o noktada tekrarını yaşamak…

Sanki kimsesiz kaldım…….,

Elim ayağımmışsın benim……..

……..

……….', 'Sanki kimsesiz kaldım sen gidince, Elim ayağımmışsın benim. Kendimi taşıyamaz oldum artık. Hep bir fazla var benden şimdilerde. Durmuyor esk...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hep-ayni-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Güzel', 'seninle-guzel-huseyin-pelit-j82nk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seninle yaşamak her anın güzel

Mutluluk paylaşmak her yanın güzel

Aşkımız sevgimiz her günün özel

Sevgilim bu aşkın baharı güzel

Canıma can katan sözlerin güzel

Bir anda hüzünlenen gözlerin güzel

Seninde benimde bahtımız özel

Sevgilim bu aşkın zamanı güzel

Her şeyim sadece seninle güzel

Sevgimizi saran gönüller güzel

Umutla yaşanan yarınlar özel

Sevgilim bu aşkın her yanı güzel', 'Seninle yaşamak her anın güzel Mutluluk paylaşmak her yanın güzel Aşkımız sevgimiz her günün özel Sevgilim bu aşkın baharı güzel Canıma can ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Pelit']::text[], 8.5, '{"poet":"Hüseyin Pelit","poet_slug":"huseyin-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seninle-guzel-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan', 'hazan-mehmet-bulut-f90bu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Olur olmaz saatlerin ani pil bitimlerindeydi hep

Yani ne vakit düşlesem uçsuz bucaksız bir ova

Tamda o zaman dururdu zaman...

Ne bahtsiz gecelerde sesinin sedasinda kayboldum.

Gerçi bilmiyorum hiçbir bahtli gecede de olmayacaksin.

Sana ''''Seni......'''' diye baslayan bir kelime asla söylenmeyecek.

Ama dokunmak teninin tuzunda,

Konusmak sesinin tınısında,

Görmek en güzel bakışında..........

Olmayacaklardı aslında bunlar ve bunun gibi birçok vesaireler....

En acısı bunu bilmek belkide.

Yani bu siiri okumayacağını bile bile sana ithaf etmek.

Gene (her dem)   mevsimidir sevdanın..

Ve her sene (mevsim)   aynı sevdayı yasarım........', 'Olur olmaz saatlerin ani pil bitimlerindeydi hep Yani ne vakit düşlesem uçsuz bucaksız bir ova Tamda o zaman dururdu zaman... Ne bahtsiz gec...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bulut']::text[], 8.5, '{"poet":"Mehmet Bulut","poet_slug":"mehmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hazan-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Mor Günler', 'mor-gunler-yildiz-yildiz-syjky', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siyah dantel duvaklar bürünür ay

yıldızlar yerle yeksan...

Mutedil ömrüm kıyılarını

hırçın dalgalar döver

deli, hoyrat

Mahçup gözaltlarına düşer,

kirpiklerin yalan gölgesi; 

Sabaha ağarır da

mor geceler...

Hangi kuytuda saklı

ferah haber

Damlamaz serin tek damla,

yağmur duasına durmuş

mor lekeli yürekler..', 'Siyah dantel duvaklar bürünür ay yıldızlar yerle yeksan... Mutedil ömrüm kıyılarını hırçın dalgalar döver deli, hoyrat Mahçup gözaltlarına d...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mor-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayis', 'mayis-mehmet-bulut-vbmw7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mayıstı....

Olması gerektiği gibiydi hazan...

Nereden bilebilirdikki? 

Mayısta hazan olmazdı....

Ama bize hazanı yaşamak,

Mayısta kısmetti...', 'Mayıstı.... Olması gerektiği gibiydi hazan... Nereden bilebilirdikki?  Mayısta hazan olmazdı.... Ama bize hazanı yaşamak, Mayısta kısmetti.....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bulut']::text[], 8.5, '{"poet":"Mehmet Bulut","poet_slug":"mehmet-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mayis-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap Gibi...', 'sarap-gibi-suleyman-saylan-jfggq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ŞARAP  GİBİ...

Şarap gibiyim güzelim,

Kırk yıllık, tortulaşmış, sıcak şarap gibi...

Sevme güzelim beni; 

Başını döndürürüm,

Sevme beni,

Sevgimle öldürürüm.

Dost masalarındaki sohbet,

Güvercinlerdeki muhabbet 

Gibiyim; 

Doyulmaz...

Kırk yıllık şaraba güzelim,

Güven olmaz.

Dalındaki meyve gibi alımlı,

Yediveren gülü gibi çalımlı...

Görünüşe aldanma,

Dokunma güzelim

Batar dikenim...

Şarap gibiyim; 

Kırk yıllık, tortulaşmış, sıcak şarap gibi...

Sevme güzelim beni

Başını döndürürüm,

Sevme beni; 

Sevginle çıldırır, 

Sevgimle sarhoş eder,

Öldürürüm...

Değer mi,

Benim için

Ölür müsün? ..

Süleyman SAYLAN

İstanbul, 14.03.1990, Saat: 01.15', 'ŞARAP  GİBİ... Şarap gibiyim güzelim, Kırk yıllık, tortulaşmış, sıcak şarap gibi... Sevme güzelim beni;  Başını döndürürüm, Sevme beni, Sevg...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sarap-gibi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Anadolu Çocuğu', 'gercek-anadolu-cocugu-huseyin-pelit-kiat5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biz doğarken olduğumuz gibi

Delikanlı büyüdük

Biz anadolu çocuğuyduk

Ninnilerle büyümesek de

Baykuş sesleriyle büyüdük

Biz anadolu çocuğuyduk

Yamalı pantolonla gezmesek de

Fermuarsız pantolonla gezdik

Biz anadolu çocuğuyduk

Kardeşçe büyüdük

Harmanlar otağında

Biz anadolu çocuğuyduk

Kalleşçe vurmadık arkadan

Hep yüz yüze çarpıştık

Biz anadolu çocuğuyduk

Çok şeyimiz olmadı

Hep hayallerle büyüdük

Biz anadolu çocuğuyduk

Hiçbir zaman namussuzluk etmedik

Ailede yuvada ve ülkede

Biz anadolu çocuğuyduk

Hiçbir zaman sevgiliyle gezmedik

Küçüklere örnek olalım diye

Biz anadolu çocuğuyduk

Ve de ihanet etmedik

Vatana toprağa ve bayrağa

Biz anadolu çocuğuyduk

Biz böyle geldik

Böyle gideceğiz toprağa

Bizler gerçek anadolu çocuklarıyız', 'Biz doğarken olduğumuz gibi Delikanlı büyüdük Biz anadolu çocuğuyduk Ninnilerle büyümesek de Baykuş sesleriyle büyüdük Biz anadolu çocuğuydu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Pelit']::text[], 8.5, '{"poet":"Hüseyin Pelit","poet_slug":"huseyin-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gercek-anadolu-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Kızıyorum!', 'artik-kiziyorum-efsun-aydin-906vr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana kızıyorum…

Bazen tarif edilemez bir ihanet etme isteği yerleşiyor içime…

Aldatsam hakkımmış gibi geliyor…

Çoğu zaman öylece dururken dahi aslında hep bir içime işleyişi var duygularının…Yaşam mücadelesi içindeymişsin gibi sanki de yine de büyük bir keyifle seyrediyorsun dışardan olayları…İstediğin hep bu senin…Konulara bir o kadar hakim oluyormuş gibi gözüküp sadece yüzeyde çözmek, dil dökmek ve konu kapatmak.Çözüm için sonuç için hiçbirşey yok.Sadece Sabretmesini dilemek karşındakinin.Sonra olmadı mı hep O tarafı suçlamak…Çünkü sen elinden geleni yapmış göreceksin kendini hep yaa…

Neyin sabrı…

Yok öyle yağma, işi oldu – bittiye getirmek! 

Başta ne dediysen teker taker olmazken ve hatta iyiye değilde kötüye giderken benden sabrı bekleyecek en son insansın sen! 

Son noktalarımdayım sabrımın sana ve bize karşı.

Taş olsa çatlardı derler yaa…

Benim kalbim asla taş değil arkadaş!', 'Sana kızıyorum… Bazen tarif edilemez bir ihanet etme isteği yerleşiyor içime… Aldatsam hakkımmış gibi geliyor… Çoğu zaman öylece dururken da...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/artik-kiziyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemedim', 'soyleyemedim-suleyman-saylan-78ij6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SÖYLEYEMEDİM

Yüreğimde düğümlendi duygularım,

Yumruk oldu,

Büyüdü, büyüdü,

Tıkadı beynime hükmeden damarlarımı.

Dilim kelimeleri unuttu,

Tutuldu; 

Seni sevdiğimi söyleyemedim,

“Seni seviyorum” diyemedim.

Yalancı pehlivan gibi

Ortalıkta kalakaldım,

Aczim yüzüme vurdu,

Utancımdan kızardım.

Ucundan yakılmış bir sigara gibi,

Bir nefes bile çekilmeden

Kül oldum yana yana,

İçin için...

İlk kez duydum bu ateşi,

Bu duyguyu ilk kez tattım,

İlk kez yaşadım.

Gözlerim bağlandı sanki,

Başka hiçbir şeyi görmüyorum,

Kulaklarım sağır,

Başka ses duymuyorum... 

Aldığım nefes seninle dolu,

Bu hantal evren seninle güzel,

Seninle çekilir bu bayat yaşam.

Oysa; 

Sen gözümün önünde,

Iraklardasın,

Yüreğimin içindesin ama,

Başka dünyalardasın.

Yüreğim düğümlendi,

Yumruk oldu duygularım,

Dilim tutuldu; 

“Seni seviyorum” diyemedim,

Sevdiğimi söyleyemedim.

    Süleyman SAYLAN

    Ankara, 16.07.2000  Saat:03.12', 'SÖYLEYEMEDİM Yüreğimde düğümlendi duygularım, Yumruk oldu, Büyüdü, büyüdü, Tıkadı beynime hükmeden damarlarımı. Dilim kelimeleri unuttu, Tut...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/soyleyemedim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç Seviştin mi', 'sen-hic-sevistin-mi-ahmet-nural-ozturk-1coh9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hiç seviştin mi sen deniz kızlarıyla

ben seviştim kızdılar bozuldular

hiç seviştin mi sen akdeniz sularında

ben seviştim tuzlu geldi

hiç seviştin mi kara kara bulutlarla

ben seviştim yağmur oldu

hiç seviştin mi sen şimşekler çakarken

ben seviştim ödü koptu şımşeğin değil dileğin

hiç seviştin mi sen renk renk güller arasında

ben seviştim bülbül fıtık oldu

hiç seviştin mi sen bir gece vakti azraille

ben seviştim öldü gitti zaten azrail sevgilim değildi', 'hiç seviştin mi sen deniz kızlarıyla ben seviştim kızdılar bozuldular hiç seviştin mi sen akdeniz sularında ben seviştim tuzlu geldi hiç sev...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-hic-sevistin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yarim, Ben Yarim…', 'sen-yarim-ben-yarim-suleyman-saylan-kbtb1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SEN  YARIM,  BEN  YARIM…

Bir tümün yarimşariyiz

Sen ve ben…

Bir anlam taşimayiz

Sen olmadan ben,

Ben olmadan sen,

Mutluluğa hasretken…

Öyleyse,

Niye kaçiyoruz birbirirmizden; 

Bana hasretken sen,

Sana hasretken ben? ..

Yaşamin 

Ayricaliği kalmiyor

Ö l ü m d e n! ..

Süleyman SAYLAN

Ankara, 19 Aralık 1971, Saat: 22.35', 'SEN  YARIM,  BEN  YARIM… Bir tümün yarimşariyiz Sen ve ben… Bir anlam taşimayiz Sen olmadan ben, Ben olmadan sen, Mutluluğa hasretken… Öyley...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-yarim-ben-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Kalmaz Masalar..!', 'bos-kalmaz-masalar-hulya-topcuoglu-rvg8u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gidince hayatın duracağını sanırsın

Sevdiğin ölecektir belki sen gidince 

Senin yokluğun bir çok kişiyi yasa boğacak 

Günlerce tek konu sen olacaksın 

Bunu düşünerek gözlerin yaşaracak 

Kendine acıyıp ağlayacaksın 

Masan boş kalacak belki bir süre

Tüm bunlar kısa bir süre sonra unutulup

Zamanın içinde yok olacak

Sevdiğin ölmeyip hayatta kalacak 

Yasa girenler allar morlar giyecek 

Artık başka konular oturacak gündeme 

Sen bile şaşıracak çok istediğin halde ağlamayı 

Ağlayamayacaksın 

Ve bir gün öğreneceksin ki

Boş kalmaz masalar, gidenin yeri dolar

Belki aynı kalır vazolar …

Sadece vazolarda unutulan çiçekler solar...', 'Sen gidince hayatın duracağını sanırsın Sevdiğin ölecektir belki sen gidince  Senin yokluğun bir çok kişiyi yasa boğacak  Günlerce tek konu ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Topçuoğlu']::text[], 8.5, '{"poet":"Hülya Topçuoğlu","poet_slug":"hulya-topcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bos-kalmaz-masalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Çığlık', 'sessiz-ciglik-sahin-karakulunc-fny5l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle bakmak sana

Öylece bakmak….

Ama kıpırdayamamak.

Uzanmak,

Ama tutamamak ellerini

Haykırmak,

Ama duyuramamak sesini

Dinlemek,

Ama duyamamak yankısını

Sevdayı taşımak yürekte

Ama taşıramamak.

İşte bu, en büyük acı

Aşkın duyulara verdiği

En büyük sancı

15 Haziran 2005, Devrek', 'Öyle bakmak sana Öylece bakmak…. Ama kıpırdayamamak. Uzanmak, Ama tutamamak ellerini Haykırmak, Ama duyuramamak sesini Dinlemek, Ama duyamam...', ARRAY['Türk Edebiyatı','Şiir','Şahin Karakulunç']::text[], 8.5, '{"poet":"Şahin Karakulunç","poet_slug":"sahin-karakulunc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sessiz-ciglik-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükürmek Geliyor...', 'tukurmek-geliyor-suleyman-saylan-k6071', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'TÜKÜRMEK  GELİYOR...

Söyledikleri

Küçük beyinlerine sığmayan insanlar; 

Bakarlar

Dar, dar,

Dardır yürüdükleri yollar,

Çıkmazdır sokaklar...

Kıpırtısızmış gibi duran bunlar; 

Yampiri bir yengeç kurnazlığıyla,

Akrep gibi sokarlar

Sinsice,

İmansızca...

Hep çıkarlar çıkmış

Sırtı görünen buzullar gibi,

Suyun yüzüne.

Suyun altında neler var, daha neler; 

Çalışmadan kazanmak,

Yorulmadan yükselmek,

Yemek, içmek, eğlenmek

Hırs olmuş çoğunda...

Çalması, çırpması caba...

İkinci binin simgesi; 

“benim ne çıkarım var bu işten,

Kazancım ne? ”

Olsa gerek.

Tükürmek geliyor içimden,

Yüzlerine, yüzlerine...

                         ...

Anlatamam yüreğimde çıkan yangını; 

Yüreğim tutuşmuşsa yanacak,

Yanmalıdır üstelik.

Bunu anlatmak zor; 

Gücüme gidiyor anlatamamak,

Anlayan kalmadı.

Sinelerinde karanfiller açmışsa yarimin,

Öğrendik kokusuyla yetinmeyi,

Koparmak gerekmez illa ki.

Elini tuttuğumda içimi saran,

Beni depremlere götüren sıcaklık 

Yetiyor bana.           

Yıkılacaksam; 

Bırakın bu depremlerle yıkılayım.

Kanayacaksa yüreğimde

Saniye görememenin özlem yüklü yarası,

Karışmayın, kanasın.

Bu yaranın umarı

Sevgilimin dudağındaki baldadır,

Yarama sargıdır saçları...

Sevmeyi ucuzlattılar oysa; 

Aşkı üç kuruşa sattılar.

İkinci binin simgesi; 

Çalışmadan kazanmak,

Yorulmadan yükselmek,

Yemek, içmek, eğlenmek

Hırs olmuş çoğunda...

Çalması, çırpması caba...

Tükürmek geliyor içimden,

Yüzlerine, yüzlerine...

    Süleyman  SAYLAN

    Ankara,  04 – 05.01.2001 Saat: 23.50 – 00.15', 'TÜKÜRMEK  GELİYOR... Söyledikleri Küçük beyinlerine sığmayan insanlar;  Bakarlar Dar, dar, Dardır yürüdükleri yollar, Çıkmazdır sokaklar... ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/tukurmek-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapı Açık', 'kapi-acik-efsun-aydin-znni6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Diyelim ki beni kaybetmek istemiyorsun,

O zaman isteklerimi biliyorsun.

Bunları vermek elbette zorunluluğun değil,

Ama veremezsen beni kaybedeceğini hissetmelisin.

Ne zorlamak isterim seni

Ne de darda bırakmak.

Doğru olanın farkındalığındayken ben,

Yalanı seçip gülemem hiç.

Sen tuhaf sızınla dolaşırken etrafta

Ben yaralarını sarmak yerine

O yarayı açacak şeyleri ortadan kaldırmayı yeğliyorum.

Belki de herşeyin en zorunu seçiyorum ama,

Ben aşkımı işte böyle yaşıyorum.', 'Diyelim ki beni kaybetmek istemiyorsun, O zaman isteklerimi biliyorsun. Bunları vermek elbette zorunluluğun değil, Ama veremezsen beni kaybe...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kapi-acik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandığımı Sanmıyorum.', 'uyandigimi-sanmiyorum-suleyman-saylan-d83pb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'UYANDIĞIMI  SANMIYORUM.

Doğarken ağlattı beni 

kadersiz kaderim; 

belki hüngür hüngür, 

belki ciyak ciyak 

ağlamışım...

Çocuktum bilemem ki.

Anımsadığım tek şey,

tek mutluluğum; 

“Her meyvanın tadı bundadır,

hangi meyva niyetine yersen

onun tadını verir” diye

birkaç muz yemiştim doğduğum köyde,

o toprak damlı evimizde.

Babam öyle söylerdi, 

doğruydu sözde...

İnanasınız gelmeyecek,

şaşıracaksınız belki,

üniversitede tanıştım ben çikolatayla,

greyfurtu limon azmanı sandım.

Yalan bile olsa; 

sevdiğim kadar 

sevildiğimi söyleyemem. 

Ben çocukluğumu yaşayamadım ki...

Çapıttan yapılmış

yakan top bilirim,

cam bilyayla düğme ütmece oynadım,

saklambaç oynadım,

onları bilirim; 

hep ebe olsam,

çok kandırılsam da uzun eşekte...                                         

Güzel kızları düşümde gördüm; 

birini bırakıp birini sevdim.

Nedense; 

sonra

utanıp başımı önüme eğdim...

Tombul, tombul memeli,

dev gibiydi benim kızlarım.

Düşüm son buldu,                                   

yaşayan kızları görünce.

Ben çocukluğumu yaşayamadım ki...

                                    

Çok ağlattılar beni                                

daha doğarken,

sonra da; 

salladılar beşikte

susayım diye...

Başardılar,

susturdular beni,

uyuttular.

Hoş,

halen uyandığımı da sanmıyorum ya,

neyse...

Ben çocukluğumu yaşayamadım ki...

   Süleyman SAYLAN

   Ankara, 14.03.2001 Saat: 17.07', 'UYANDIĞIMI  SANMIYORUM. Doğarken ağlattı beni  kadersiz kaderim;  belki hüngür hüngür,  belki ciyak ciyak  ağlamışım... Çocuktum bilemem ki....', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/uyandigimi-sanmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usulca', 'usulca-murat-oz2-xkcvz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayalinle hüzünlenir bazen gece

Sis dağının perdesinde 

Tel tel savrulur rüzgarla

Kar tenesine eş olur bazen

Bazen de minik bir serçeciğe

Kapalı gözlerin ardında

Ve

Sözcüklerin arasında 

Usulca,

Seni seviyorum der', 'Hayalinle hüzünlenir bazen gece Sis dağının perdesinde  Tel tel savrulur rüzgarla Kar tenesine eş olur bazen Bazen de minik bir serçeciğe Ka...', ARRAY['Türk Edebiyatı','Şiir','Murat Öz2']::text[], 8.5, '{"poet":"Murat Öz2","poet_slug":"murat-oz2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/usulca-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayalım Gör', 'yasayalim-gor-suleyman-saylan-ks59e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YAŞAYALIM  GÖR

Sevginin tanımı olmaz,

anlatılmaz,

yaşanır...

Kuşku duyuyorsan sevgimden,

yaşayalım

gör.

   Süleyman SAYLAN

   Ankara, 09.08.2001, Saat: 00.46', 'YAŞAYALIM  GÖR Sevginin tanımı olmaz, anlatılmaz, yaşanır... Kuşku duyuyorsan sevgimden, yaşayalım gör.    Süleyman SAYLAN    Ankara, 09.08....', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasayalim-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak Gibi...', 'tutsak-gibi-suleyman-saylan-tlfda', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'TUTSAK  GİBİ...

        (Biricik eşim, Öznur’uma.)

Ö ksüz yüreğimi tutuşturur bir kıvılcım; 

     Ö zbenliğimde şimşekler çakar,

          Ö lüme atılmış mızrak gibi...

Z amanın durağanlığı nallanır sanki;        

     Z amanla yarışır, dört nala koşar,

          Z avallı, sahipsiz kısrak gibi...

N efesim düğümlenir, heyecan boğazımı tıkar; 

     N utkum tutulur, unuturum sözcükleri,

          N efessiz, sözcüksüz kitap gibi...

U mutsuz umutlarım coşar yüreğimde,       

     U çurur beni kanatsız, göklere,

          U yanır su yürümüş tabiat gibi...

 R enk renk gülücükler açar dudağında; 

     R uhumu tutsak alır, çelik kelepçeler takar

          R ahmetine muhtaç idamlık tutsak gibi...

                         Süleyman SAYLAN

                         Ankara, 25.06.1972, Saat: 01.42', 'TUTSAK  GİBİ...         (Biricik eşim, Öznur’uma.) Ö ksüz yüreğimi tutuşturur bir kıvılcım;       Ö zbenliğimde şimşekler çakar,           Ö...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tutsak-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebessüm', 'tebessum-nihat-malkoc-mv5i7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öğütür yılları gam değirmeni

Bir sevdalı yüzde donar tebessüm

Kaldırmaz bu yürek onca dümeni

Hicran ateşinde yanar tebessüm

Yürek yaraları kabuk bağlarken

Gönül şelâlesi taşıp çağlarken

Kalemler gözyaşı döküp ağlarken

Nefreti sevgiye banar tebessüm

Yâr deyip de zehir doğrar aşıma

Keyiflenir durur hicran yaşıma

Selâmsız sabahsız girer düşüme

Düşmanımı dostum sanar tebessüm

Gülşenimde elvan elvan  açarken

Ceylan gibi sekip benden kaçarken

Yüreğimi viran koyup göçerken

Mâziyi hüzünle anar tebessüm

Ömür kâsesinden boşalır zaman

Hayaller geceden diliyor aman

Muhabbet gönülde olurken harman

Kalbin yamacına siner tebessüm

Dalından dökülür son kuru yaprak

Sele karışıyor bastığım toprak

Ruh nasıl yeşersin kururken ırmak? 

Çölleşir umutlar diner tebessüm

Bozulur tuttuğum sevda orucu

Hasret tünelinin görünmez ucu

Mâziye sığınıp ederken rücu

Yakar, hıçkırığa döner tebessüm

Eser fırtınalar,karlanır dağın

Biter ayrık otu,bozulur bağın

Yıllara yenilir,geçer de çağın

Dudakların titrer,söner tebessüm

                        12 Temmuz 2005/TRABZON', 'Öğütür yılları gam değirmeni Bir sevdalı yüzde donar tebessüm Kaldırmaz bu yürek onca dümeni Hicran ateşinde yanar tebessüm Yürek yaraları k...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/tebessum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığındım Yalnızlıklara', 'sigindim-yalnizliklara-suleyman-saylan-ph7s9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SIĞINDIM  YALNIZLIKLARA

Çürük bir yelkenli gibi,

salıverdin denizlere...

Sevgilerde

yalnız başıma koydun beni.

Nasıl dayanır fırtınalara

küf kokan yelkenlerim,

nasıl direnir azgın dalgalara

çürümeye yüz tutmuş bedenim? 

Hiç düşünmedin...

Balıklara yuva bile olamadan

amansız bir fırtına aldı, 

savurdu beni hoyrat elleriyle,

ayrılık kayalıklarına,

acımasızca...

Paramparça olmak üzereyken,

bir imbat tuttu elimden; 

acıdı,

yalnızlık koylarına götürdü beni.

Sığındım,

uçsuz bucaksız yalnızlıklara...

     Süleyman  SAYŞLAN

     Ankara, 12.07.2000  Saat: 02.22', 'SIĞINDIM  YALNIZLIKLARA Çürük bir yelkenli gibi, salıverdin denizlere... Sevgilerde yalnız başıma koydun beni. Nasıl dayanır fırtınalara küf...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sigindim-yalnizliklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ürperir Tenin! -I', 'urperir-tenin-i-muharrem-cetinkaya-2xi1e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiir kelimelerle,oynaşmak,

Ya da

Ustanın taşlarla kubbe yapmasıdır.

Sevmektir,

Sevişmektir,

Sırçadan köşk yapmaktır.

.

Paylaş köşklerini,

Yaşasın eserlerin; 

Bazen bir saray kur,

Darağacı kur bazen de…

Bütün duygular senin.

Hançer yap kelimelerle

………………..Vur! ...

.

Kelimeler:

Annedir

Dosttur

Hasrettir

Hayaldir

Sevgilidir…

Yıllar sürer bir kelimeyi duymak:

_duyunca 

Dünya senin! 

Rengine

Tadına doyum olmaz…

Manası çoktur bir kelimenin…

Bazen bir kelime; 

Kurşun gibi işler,

_o zaman

Ürperir tenin…

.

Kuşların ötüşü,

Böceklerin sesi,

Hislerini uyandırır senin.

Duyunca bir selam

Güneşin doğuşudur

_o zaman

Ürperir tenin…

.

Ama sevmek lazım kelimeleri; 

Okşamak,

Yan yana getirmek.

Seviştirmek,

Vuslattır,

_ o zaman; 

Islanır gözlerin,

Ürperir tenin! ...

.

İşte

Bütün kelimeler senin.

Kur saraylarını,

Dokun

Kucakla

Sarıl

Öp

Doyum vaktidir,

_o zaman,

Ürperir tenin! ...', 'Şiir kelimelerle,oynaşmak, Ya da Ustanın taşlarla kubbe yapmasıdır. Sevmektir, Sevişmektir, Sırçadan köşk yapmaktır. . Paylaş köşklerini, Ya...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/urperir-tenin-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğarken Ağlamazdık Her Bebek Gibi', 'dogarken-aglamazdik-her-bebek-gibi-murat-oz2-cyg2e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne umutlarla doğmuştuk

Ne güzel sevilmiştik

Nur tanem bir tanem 

Vefasız kalmıştı hayat

Güzel olsaydı zaten dünya

Doğarken ağlamazdık her bebek gibi...

Bebek halimiz biliyorduda

Olgunluğumuzun işine gelmiyordu

Her şeyin bir hesabının olduğunun işte

Nasıl her sabahın akşamı 

Her akşamın bir sabahı varsa

Her beninde bir senliği vardı

Sevgi karşılıksız olmaz derler ama

Neden benim sevgilerim karşılıksızdı

Tabiatımızda bu var bizim

Sefilliğimizde bundandı işte

Rengarenk çingenelik değil de ne

Yoksulsan sevmeye hakkın yok

Göreceli olsun peki yoksulluk

Belki maddi belki manevi

Eğer çirkinsen yoksulsun güzellikten

Zengin değilsen iyi yaşamdan

Kötüysen iyi huydan 

Her durumda da benim gibiysen yoksunsun 

Yoksulsun bir şeylerden

Karşılıksız sevmeye hakkın var 

Ama 

Karşılıklı sevilmeye hakkın yok', 'Ne umutlarla doğmuştuk Ne güzel sevilmiştik Nur tanem bir tanem  Vefasız kalmıştı hayat Güzel olsaydı zaten dünya Doğarken ağlamazdık her be...', ARRAY['Türk Edebiyatı','Şiir','Murat Öz2']::text[], 8.5, '{"poet":"Murat Öz2","poet_slug":"murat-oz2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dogarken-aglamazdik-her-bebek-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Aynı Benim', 'ben-ayni-benim-emin-eren-c9lzx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uğruna ölünecek aşk bu demiştin

İşte kul olunacak biri demiştin

Hani hatalarımı bile sevmiştin

Nasıl olduda böyle birden değiştin

Söyle bu kadar mıydı o büyük sevgin

İlk sarsıntıda yerle yeksan eyledin

Yıllar önce yoluma mumlar yaktığın

Kardeş elini  tutsam kaş göz ettiğin

Sevgisini yüreğine nakşeylediğin

Hani  nikah masasında evet dediğin

Şimdi bir el süzüyle  kin beslediğin

Hiç değişmedim  gülüm ben aynı benim', 'Uğruna ölünecek aşk bu demiştin İşte kul olunacak biri demiştin Hani hatalarımı bile sevmiştin Nasıl olduda böyle birden değiştin Söyle bu k...', ARRAY['Türk Edebiyatı','Şiir','Emin Eren']::text[], 8.5, '{"poet":"Emin Eren","poet_slug":"emin-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-ayni-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Nokta (...)', 'uc-nokta-murat-oz2-jqmhg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üzüntü anlıktır yalancı sevmelerin ardında

Bülbülün gülü sevmesi

Benim seni karşılıksız sevmem

İkisinde de mevzu bahis ıraklık

Bir araya gelipte denklik kuramamak

Değerlerin ve sevmelerin göreceli olması

Tezatlık bu ya

Üşürsek soğuktan sıcağı

Bunalırsak sıcaktan serinliği

Yanlızken dosta

yoğunsak ilişkilerde sessizliğe

Hasret değilmiyiz...

Bazı şeyler vardır anlatılmaz

Yada anlatılamaz

Gizleriz duyguları hüzünlü gözlerin ardında

Kimi zaman bir gök kuşağında

Kimi zaman rutbe düşen kar tanesinde

Yazarların düşüncelerini gizlediği gibi üç noktada

Düşünceler kişiye bırakılmıştır

Bende çoğu gibi ne şair ne yazarım

Ama senin için...', 'Üzüntü anlıktır yalancı sevmelerin ardında Bülbülün gülü sevmesi Benim seni karşılıksız sevmem İkisinde de mevzu bahis ıraklık Bir araya gel...', ARRAY['Türk Edebiyatı','Şiir','Murat Öz2']::text[], 8.5, '{"poet":"Murat Öz2","poet_slug":"murat-oz2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uc-nokta-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Adam! I', 'kor-adam-i-muharrem-cetinkaya-crp8g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün yürüyorduk

Yanımda

Kör bir adam..

“Canım bir bardak süt istedi”dedim.

“Süt nedir” dedi,kör adam.

“süt,beyaz bir sıvıdır”dedim.

“Sıvıyı biliyorum ama beyaz nedir? ”dedi,

Kör adam.

“Kuğu kuşunun rengidir”dedim.

Bana da öğretmişti babam.

“Kuğu kuşu nedir? ”dedi

Kör adam.

“Boynu bükük bir kuş “dedim.

“Boynu anladım ama bükük nedir? ”dedi

……………….

“Sabret oğlum daima”derdi babam,

Ama taşmıştı artık sabrım; 

Kolunu tutup dümdüz uzattım…

“İşte büküktür”dedim.

Memnun oldu,

Kör adam 

“Görecelik aldatır “derdi babam,

“Tamam! ” 

 “Sütün ne olduğunu şimdi anladım”

Dedi

Kör adam! ...', 'Bir gün yürüyorduk Yanımda Kör bir adam.. “Canım bir bardak süt istedi”dedim. “Süt nedir” dedi,kör adam. “süt,beyaz bir sıvıdır”dedim. “Sıvı...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kor-adam-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın İlaç Sanıyor.', 'askin-i-lac-saniyor-suleyman-saylan-ozkdl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'AŞKIN  İLAÇ  SANIYOR

Sıkılmış yumruk oldun, senle dolu içimde,

Kalbimdeki kuşunun kafesi daralıyor...

Alev alev yanıyor duygular benliğimde,

Damarımda ördüğün heyecenlar kanıyor.

Kanser midir, verem mi? Aşkın ilaç sanıyor.

Aşkının zincirinde, kulun değil, kölenim.

Gözüne baka baka sensizlikten ölenim.

Sana hasret kalsam da, deli gibi sevenim.

Kavuşmak umuduyla gönlüm hep aldanıyor,

Kanser midir, verem mi? Aşkın ilaç sanıyor.

Nefesim tıkanıyor/daralıyor, sözcükler emekliyor,

Sevginle güm! Güm! Vuran kalbim artık tekliyor.

Tanrıya yalvararak, biraz huzur istiyor.

Sana hasta bu ömrüm bir mucize arıyor,

Kanser midir, verem mi? Aşkın ilaç sanıyor.

     Süleyman  SAYLAN

     İzmir,02.09.2004, Saat: 23.13', 'AŞKIN  İLAÇ  SANIYOR Sıkılmış yumruk oldun, senle dolu içimde, Kalbimdeki kuşunun kafesi daralıyor... Alev alev yanıyor duygular benliğimde,...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/askin-ilac-saniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak Çıktın', 'korkak-ciktin-suleyman-saylan-oa5a7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KORKAK  ÇIKTIN

Kurduğum düşlere yazık olmadı; 

Sen hayırsız, ruhsuz, vefasız çıktın.

Ardından üzülüp, neşem solmadı; 

Hani sen benimdin, çok çabuk bıktın.

Sevgi bulutları göğü kapladı,

Sen anlamadın ki sevda yağmadı.

Ayrılık kapını boşa çalmadı,

Mutlu dünyamızı yok yere yıktın.

Sevgi karşılıklı anlayış ister,

Vefakar olmayan yıkılır gider,

Dipte zıpkın yemiş balığa döner.

İşte sen böylesin, çok korkak çıktın.

    Süleyman SAYLAN

    Ankara, 10.01.1992  Saat: 02.05     (Şarkı sözü olabilir.)', 'KORKAK  ÇIKTIN Kurduğum düşlere yazık olmadı;  Sen hayırsız, ruhsuz, vefasız çıktın. Ardından üzülüp, neşem solmadı;  Hani sen benimdin, çok...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/korkak-ciktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Külüne Kaldın', 'kulune-kaldin-suleyman-saylan-gmadt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KÜLÜNE  KALDIN

Sevdamın çiçeği olmadan daha,

Kendini solmayan güllerden sandın.

Razıydım gövdenden dikenin batsa,

Aşkımı yakarak külüne kaldın.

Önüne gelene koklatıp durdun,

İhanet okuyla beni hep vurdun,

Kendine sorumsuz bir dünya kurdun,

Aşkımı yakarak külüne kaldın.

Dünyayı döndüren eksensin sandın,

Elden ele gezdin, hep ele kandın,

Saman aleviydin çok çabuk söndün,

Aşkımı yakarak külüne kaldın.

Sevmeyi beklerken harcadım ömrü,

Pörsüdü duygular, düşler pörsüdü,

Yana yana soldu, kalbim çürüdü,

Aşkımı yakarak külüne kaldın.

   Süleyman  SAYLAN

   Ankara, 03.04.1999  Saat: 03.42   (Şarkı sözü olabilir.)', 'KÜLÜNE  KALDIN Sevdamın çiçeği olmadan daha, Kendini solmayan güllerden sandın. Razıydım gövdenden dikenin batsa, Aşkımı yakarak külüne kald...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kulune-kaldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oynama Kalbimle...', 'oynama-kalbimle-suleyman-saylan-yb978', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'OYNAMA  KALBİMLE...

Sevmeyi bilmezsin, henüz çok gençsin; 

Sevda dağ yoludur, yürüyemezsin...

Yarı yolda beni sen terkedersin.

          Oynama kalbimle, sakın oynama.

          Oynama benimle, sakın oynama.

Aşkı oyun sanıp, asla aldanma,

Duygular hep böyle sürecek sanma,

Ayrılık kapını çalarsa, yanma...

          Oynama kalbimle, sakın oynama.

          Oynama benimle, sakın oynama.

Esen rüzgar bile şarkı sevene,

Denizler duygudur gönül verene.

Her sevgi sazların telinde nağme...

          Oynama kalbimle, sakın oynama.

          Oynama benimle, sakın oynama.

                        Süleyman SAYLAN

    Ankara, 09.01.1994, Saat: 18.05  (Şarkı sözü olabilir.)', 'OYNAMA  KALBİMLE... Sevmeyi bilmezsin, henüz çok gençsin;  Sevda dağ yoludur, yürüyemezsin... Yarı yolda beni sen terkedersin.           Oyn...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/oynama-kalbimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öde Sevdamın Cezasını', 'ode-sevdamin-cezasini-suleyman-saylan-axcxj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ÖDE  SEVDAMIN  CEZASINI

Uzanırsın selvi boyunla,

Kalbimin sevda göklerinde.

Kanadı kırık bir kuş olsa

Yüreğim narin ellerinde.

İlacı önünde hastayım,

Yüzüm gülse bile yastayım,

Kendi kendimle savaştayım,

Aşık oldum göz göre, göre.

Nazına kurban gitti sevdam,

Hiç durmadı kanayan yaram.

Üzsen de, gönlüm sana hayran,

Tahtın sağlam düş evrenimde.

Dilerim çalsın senin de,

Aşk hırsızı bir gün kapını:

Oyuncak ol aşkın elinde,

Öde sevdamın cezasını...

     Süleyman  SAYLAN

     Ankara, 02.06.1998  Saat: 16.35', 'ÖDE  SEVDAMIN  CEZASINI Uzanırsın selvi boyunla, Kalbimin sevda göklerinde. Kanadı kırık bir kuş olsa Yüreğim narin ellerinde. İlacı önünde ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ode-sevdamin-cezasini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül bu ne diyebilirim ki', 'gonul-bu-ne-diyebilirim-ki-ahmet-nural-ozturk-1dcgo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gönül bu ne yapacağı belli olmaz

ota da konar boka da

ne diyebilirim ki

şaşkın ikilem

her seher rüzgarı

düşlerimi uyutup

beni hep yanıltır gider', 'gönül bu ne yapacağı belli olmaz ota da konar boka da ne diyebilirim ki şaşkın ikilem her seher rüzgarı düşlerimi uyutup beni hep yanıltır g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gonul-bu-ne-diyebilirim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönlüm', 'deli-gonlum-dilek-ozdemir-6pkr0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'asırlık bir çınardır deli gönlüm

devrilir mi acemi oduncunun

birkaç balta vuruşuyla

direnir deli gönlüm

sen bakma gözüm yaşına

dağ iklimidir deli gönlüm

kaybolur mu çiçek kokuları

gecenin karanlığında

direnir deli gönlüm

sen bakma gözüm yaşına

sevda diyarıdır deli gönlüm

sevdi mi sunar bal kaymağı

incinirse kekik yağı tadında

direnir deli gönlüm

sen bakma gözüm yaşına

zor yüklerin kısrağıdır deli gönlüm

gem vurulur mu şahlanışına

acılar kırbaçlayınca

direnir deli gönlüm

sen bakma gözüm yaşına', 'asırlık bir çınardır deli gönlüm devrilir mi acemi oduncunun birkaç balta vuruşuyla direnir deli gönlüm sen bakma gözüm yaşına dağ iklimidir...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deli-gonlum-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On İki', 'on-i-ki-mehmet-demir-atmali-ke3el', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'On iki, 

Evet.., On iki neki? 

Bir''in yanında iki... 

Veya; 

On''un üstüne iki... 

Yani; 

On iki deyince aklıma; 

İmamlar, Katliamlar, 

Kerbelalar, 

Türbelalar gelirdi... 

Üç Oklar-Boz Oklar, 

Şerefeli mızraklar,(1) 

Sinanlar, 

Kutlu anlar gelirdi... 

Peki ya şimdi on iki? 

Çocukluk yaşım, 

Belalı başım, 

Zehirli aşım, 

Deyince aklıma; 

Şefler, Kıratlar, 

Azgın suratlar gelir... 

Erimler, haremler; 

Martlar, dertler gelir... 

Şimdi on iki; 

Uğursuz rakamım; 

Sehpalı makamım, 

Deyince aklıma; 

Eylüller, Behlüller, 

Evrenler, Devrimler, 

Sefiller, Gafiller gelir... 

Zindanlar, 

Gardiyanlar, 

İşkenceler, 

İşkembeciler gelir... 

Arılar, Karılar, 

Özallar,Güzeller, 

Zanalar, Erdallar, 

Hardallı bayramlar gelir... 

Şimdi on iki; 

Ortak Pazar, 

Bölücü hızar, 

Global mezar, 

Sakın söyleme! ! ! 

Sam amca kızar... 

Kızarsa kızar... 

Artık ne yazar, 

Deliye mezar... 

Oysa şimdi, 

Tek merakım; 

On ikileri sormak... 

On ikileri yermek... 

Tek hedefim; 

On ikiden vurmak... 

20.4.1992

Mehmet Demir Atmalı', 'On iki,  Evet.., On iki neki?  Bir''in yanında iki...  Veya;  On''un üstüne iki...  Yani;  On iki deyince aklıma;  İmamlar, Katliamlar,  Kerbe...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/on-iki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgündeki Adam', 'surgundeki-adam-dilek-ozdemir-xk6wb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir adam tanımıştım bir yarıgecede

nasıl da titremedeydi sesi

küskündü ve kinliydi seçtiği sözcükler

ama ne yapsa saklayamıyordu

yüreğinin sevgi dolu köşeciklerini

tükenmişti ve kararsızdı yaşamakta

kendi bedeninde sürgün bir pranga mahkumu

kendini aramaktaydı kadeh diplerinde

çırpındıkça bedenini kanatan

bir yaralı kuştu yüreği

göğsüne bastırırken kırdı en sevdiklerini

ve sonra da cezalandırdı ellerini', 'Bir adam tanımıştım bir yarıgecede nasıl da titremedeydi sesi küskündü ve kinliydi seçtiği sözcükler ama ne yapsa saklayamıyordu yüreğinin s...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/surgundeki-adam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana Ecelsin', 'sen-bana-ecelsin-suleyman-saylan-1tqye', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SEN  BANA  ECELSİN

Beni baştan çıkardın, ömrüme bedelsin.

Duyguma ateş saldın, gönlüme özelsin.

Aklımı baştan aldın, sen ömre değersin...

Nasıl anlatsam bilmem, bir suskun güzelsin,

Dünya yıkılsa bile sen bana ecelsin.

Duygu yüklü, kor gözler bakışlar atıyor,

Sarı sarı saçların aklımı alıyor.

Her gülüşün kalbime masumca dalıyor...

Nasıl anlatsam bilmem, bir suskun güzelsin,

Dünya yıkılsa bile sen bana ecelsin.

Kadeh kadeh içkisin, içmeden duramam,

Bir tomurcuk tazesin, öpüp solduramam.

Arzu oldun içimde, sevmeden doyamam...

Nasıl anlatsam bilmem, bir suskun güzelsin,

Dünya yıkılsa bile sen bana ecelsin.

Süleyman SAYLAN

Ankara, 20.11.1990, Saat: 23.40    (Şarkı sözü olabilir.)', 'SEN  BANA  ECELSİN Beni baştan çıkardın, ömrüme bedelsin. Duyguma ateş saldın, gönlüme özelsin. Aklımı baştan aldın, sen ömre değersin... Na...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-bana-ecelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şanlı Cumhuriyet', 'sanli-cumhuriyet-suleyman-saylan-fhgly', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ŞANLI  CUMHURİYET

Kurtuluş savaşı’nda

Nice canlar can verdi,

Benim şanlı milletim

Son muradına erdi.

Kandan, aydan, yıldızdan

Bayrak yaptı kendine,

Can vererek ulaştı

Şanlı Cumhuriyet’e.

Tam yetmişbeş yıl önce

Atatürk’ten emanet,

Çağdaşlığa kapımız

Bu şanlı Cumhuriyet.

Cumhuriyet şanımız,

Yıkılamaz imkansız.

Her savaşa biz varız

Yaşasın Cumhuriyet.

          Süleyman  Saylan

          Ankara, 29.10.1999    (Çocuk şarkısı sözü olabilir.)', 'ŞANLI  CUMHURİYET Kurtuluş savaşı’nda Nice canlar can verdi, Benim şanlı milletim Son muradına erdi. Kandan, aydan, yıldızdan Bayrak yaptı k...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sanli-cumhuriyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Pınarı', 'huzun-pinari-kadir-kaya-myvlf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Evlat: Rabbim böyle yazmış benim yazımı,

           Babam, vasiyetim okut kızımı,

           Ateşimi söndür, dindir sızımı,

           Her yanım dumansız yanıyor baba.

Baba: Özümden acını inan duyarım,

            Bir tane kızıma nasıl kıyarım,

            Senin dileğini emir sayarım,

            Yüreğime ateş attın ya kızım.

Evlat:   Babam,kızım sana emanet olsun,

             Yılmasın, okusun doğruyu bulsun,

             Bahtsız anasına duayı salsın,

             İçim parça parça kanıyor baba.

Baba:   Hayatın baharı kırkbir yaşında,

             Mürveti görecek yolun başında,

             Kanser belasıyla gelen kışında,

             Gülerek ölüme gittin ya kızım.

             Torunum okusun evi satarım,

              Ben artık nerede olsa yatarım,

              Yavrumun elini hemen tutarım,

              Sevgini sevgime kattın ya kızım.

              Yıllar torunumla su gibi geçti,

               Diş doktoru oldu, eşini seçti,

               Kadirde  sevginin gülleri açtı,

               Beni en mutlu Dede ettin ya kızım.

Not: Gerçek hayat hikayesidir,Dede bunları anlatırken ağlıyordu,

Ben sadece duygumu katmaya çalıştım.böyle sevgilere can kurban.', 'Evlat: Rabbim böyle yazmış benim yazımı,            Babam, vasiyetim okut kızımı,            Ateşimi söndür, dindir sızımı,            Her y...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/huzun-pinari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtfaiyeci', 'i-tfaiyeci-kadir-kaya-vluwh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Görevini bekler hazır can ile,

Korkuyu hissetmez o, bir an bile,

Can figan haykırış gelirse dile,

Yangınlara koşar İtfaiyeci.

Onları yıldırmaz sis ile duman,

Hemen gelmek için önemli zaman,

Gözü kara,cesur yamanmı yaman,

Hazır kıta yaşar İtfaiyeci.

Yiğitçe ölüme meydan okuyan,

Tertemiz sevgiyi kalbinde duyan,

Tek bir can uğruna canını koyan,

Engelleri aşar İtfaiyeci.

Yangın harareti uzaktan yakar,

Herkes can derdinde çaresiz bakar,

Ateşin içinde suyunu sıkar,

Sıcaklarda pişer İtfaiyeci.

Afet,kaza, deprem koşar yardıma,

Görev bilinciyle bağlı Yurduna,

Kadirim çareler  bulur  derdine,

Sevgisiyle taşar İtfaiyeci.', 'Görevini bekler hazır can ile, Korkuyu hissetmez o, bir an bile, Can figan haykırış gelirse dile, Yangınlara koşar İtfaiyeci. Onları yıldırm...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/itfaiyeci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarılalım Yumak Gibi', 'sarilalim-yumak-gibi-suleyman-saylan-bs71g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SARILALIM  YUMAK  GİBİ

İçimdeki son kıpırtı,

Dalda açan çiçek gibi.

Duygularda bir mırıltı,

Bende çarpan yürek gibi...

Aşık oldum bil ki sana,

Özlüyorum kıyasıya.

Koklasaydım doyasıya,

Soldurmadan, çiçek gibi...

Mutlu olmak elimizde; 

Sen benimle, ben seninle,                         

Sarmaş, dolaş ikimiz de,

Sarılalım yumak gibi...

Sakın kaçma ne olursun,                                      

Aşkım güçlü, boğulursun.

Başkasına yar olursun; 

Sürünürsün, ölmek gibi...

   Süleyman  SAYLAN

   Ankara, 19.12.1991 Saat: 01.15      (Şarkı sözü olabilir.)', 'SARILALIM  YUMAK  GİBİ İçimdeki son kıpırtı, Dalda açan çiçek gibi. Duygularda bir mırıltı, Bende çarpan yürek gibi... Aşık oldum bil ki san...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sarilalim-yumak-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fısılda', 'fisilda-bekir-mutlu-gokcesu-y29ab', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabah sensiz, gece sensiz

Gelir geçer mevsimler

Uçar için, uçar gençliğin...

Güneş açsa güldün sanırım

Yağmur yağsa, ya ağlıyorsa? 

Her şarkı seni söyler bana...

Çıkıp gelecekmişim gibi hani

Nasıldı resmin? 

Beni düşünürken aynalarda...

Bir ezgisi mutlaka olmalı sende 

Sensizliğimin

Hadi bana fısılda...', 'Sabah sensiz, gece sensiz Gelir geçer mevsimler Uçar için, uçar gençliğin... Güneş açsa güldün sanırım Yağmur yağsa, ya ağlıyorsa?  Her şark...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fisilda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğundaki Varlığım', 'yoklugundaki-varligim-mustafa-dogan-kuzgun-h87xy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yokluğunla dolu gecenin sonundaki

Şafaksız gecelerin alışılmış hali; 

Pas tutmuş yüreğime bağladığın,

Yitik duygulardan kalma,

İhanet telleriyle ördüğün,

Esaret zincirlerini giyinip

Dolaşmaya çıkıyorum, prangalarınla

Sensizliğinin beni kendine bağlamışlığıyla...

Yürüdüğüm yollar her zamanki gibi tozlu,

Gölgesine sığındıkların çoktan kurumuş,

Rüzgar her köşe başında nöbette; 

Yalnızlığınla patlatacağı tokatlar için.

Hiç biri kabullenemiyor sensizliği.

Oysa ben; 

Gittiğinden beri haykırıyorum çaresizliği,

Amansız feryatları ıslıklıyorum geceleri,

Toprağa attığım her adımda

Yokluğunu kazıyorum, karanlık, zifiri...

Yoksun diyorum; 

Varolduğun kadar, yokluğunlayım

Ve yokluğun kadar, varolmaya çalışacağım

Yokluğunu varlığımla dolduracağım,

Varolduğuma inat, varlığını yaşayacağım.', 'Yokluğunla dolu gecenin sonundaki Şafaksız gecelerin alışılmış hali;  Pas tutmuş yüreğime bağladığın, Yitik duygulardan kalma, İhanet teller...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yoklugundaki-varligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Sevseydin Beni', 'sevseydin-beni-nurten-altinok-ky98q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hoşgeldiniz 

                      

                                 

Sevseydin beni

Daha mı çok severdim seni

Daha mı az yanardım

Daha mı çok üşürdüm

Sevseydin beni

Bilemezsin sancısını

Kendine söz geçirememenin 

Bilemezsin acizliğini

Nasıl dolanır kelimeler boğazına yağlı kaytan

Söylemek isteyip de yutkunduğun

Yazmak isteyip de yazamadığın

Nasıl yığılır üstüne şiirler çığ misali

Ezilip kaldığın

Bilemezsin 

Kalemler kırdı kalemleri

Yıldızlar yağıyor her gece üzerime 

Parmaklarımla tarıyorum 

Saçların niyetine

Yolcular uğurluyorum otogarlarda

Hepsinin adı sen oluyor

Sesleniyorum

Hiç biri dönüp bakmıyor

Bir benzerini bulsam gidip sarılacağım ya boynuna

El sallıyorum 

Kelimeler kırdı kelimeleri

Sevseydin beni

Daha mı çok özlerdim seni

Bilemiyorum...', 'Hoşgeldiniz                                                           Sevseydin beni Daha mı çok severdim seni Daha mı az yanardım Daha mı ç...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevseydin-beni-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir-Üç Nöbeti', 'bir-uc-nobeti-mehmet-demir-atmali-ig4s2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine sıla düştü aklıma bu gece,

Vukuat işledim, Bir-Üç nöbetinde...

Sevgilimi andım, harf harf, hece hece; 

Kalbine işledim, Bir-Üç nöbetinde...

Kar-Yağmur karışık, durulmak bilmiyor.

Yare mektup yazdım, cevabı gelmiyor...

Yitirdim uykuyu, gözlerim dalmıyor; 

Yarınan kışladım, Bir-Üç nöbetinde...

Ayaklarım ıslak, botlarımsa delik,

Parmaklarım üşür, dişler kemanelik.

Omuzlarım çökük, nöbet cephanelik; 

Feryada başladım, Bir-Üç nöbetinde...

Mehmet Aşıkmısın, yoksa Askermisin? 

Yarden mektup yoksa, acep küsermisin? 

Divan-ı Harbe veseler, asarmısın? 

Asanı taşladım, Bir-Üç nöbetinde...

                            5.1.1979', 'Yine sıla düştü aklıma bu gece, Vukuat işledim, Bir-Üç nöbetinde... Sevgilimi andım, harf harf, hece hece;  Kalbine işledim, Bir-Üç nöbetind...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-uc-nobeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Düşen Ağlamaz', 'kendi-dusen-aglamaz-ahmet-nural-ozturk-qmarw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendi düşen ağlamaz vardır bir hikayesi 

Uçurumun ortasında dönüş yolu nafile 

Senin gönlün hoş olsun diye kandıramam kulları 

Benim yolum ateşlerin üstünde 

Kendim düştüm elbette yanmak ta bana düşer 

Yanımda istemem bir itfaiye...', 'Kendi düşen ağlamaz vardır bir hikayesi  Uçurumun ortasında dönüş yolu nafile  Senin gönlün hoş olsun diye kandıramam kulları  Benim yolum a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kendi-dusen-aglamaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuluğun Gözyaşları', 'korkulugun-gozyaslari-mustafa-dogan-kuzgun-sxz29', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden suskunsun bu gece korkuluk? 

Yoksa kuşlara mı kızgınsın? 

Ama suç bende; 

Senin samanlarına duygusallık,

Kollarına şefkat serptim.

Ne yapyım? 

Söyle...

Olmuyor bir türlü,

Korkuluğu bile çirkinleştiremiyorum.

Benim yüzümden ağlıyorsun,

Hepsi benim suçum.

Olmuyor, denedim ama

Hep bir şeyler eksik kalıyor.

Ürkütmek için korkuluk yaptım

Kahrolası duygusallık en önde.

Öyle suçlar gibi bakma,

Sil şu yüreğinden gelen kanları,

Gördükçe dayanamıyorum,

İçim burkuluyor.

Ben de üzülüyorum ama

Elimden bir şey gelmiyor.

Seni sökmeye de kıyamam.

Evet... Haklısın.

Ayağı kırılan atı vururlar.

Ama ben seni parçalayamam.

Ne olur yalvarma...

Yapamam...

Allah kahretsin! ..

Yaptım...

Söz veriyorum:

Seneye en korkunç sen olacaksın.

Seni gören kuşlar,

Korkudan uçmayı hatırlayacak.

İnsanoğlunun en büyük korkuları

Sayende korkunun tadına varacaklar.

Güneşi bile ürküttüğün bir gecede

Dolunayını ve yıldızlarını senden saklayacak.

O anda bir masal perisi seni canlandırıp; 

İnsanlığın rüyalarına bir karabasan gibi gireceksin.

Gecenin bir vakti baykuş sesleriyle,

Kan-ter içinde, soluk soluğa uyanacaklar.

Bunun için, Tanrı beni cezalandıracak,

Seninle karşılaştırıp

Yüz yüze gelmemizi sağlayacak.

O zaman; 

Karşındakinin sen olduğunun farkına varacak,

Yüreğindeki son merhamet zerresiyle ağlayacaksın.

Ve en büyük korkunun,

Korkutmak olduğunu anlayacaksın.', 'Neden suskunsun bu gece korkuluk?  Yoksa kuşlara mı kızgınsın?  Ama suç bende;  Senin samanlarına duygusallık, Kollarına şefkat serptim. Ne ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan Kuzgun']::text[], 8.5, '{"poet":"Mustafa Doğan Kuzgun","poet_slug":"mustafa-dogan-kuzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/korkulugun-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolun Sonu', 'yolun-sonu-mehmet-demir-atmali-ven7f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Elif Ninenin akıbeti...

Gençlik meyvasına henüz doymadan,

Yasak meyvaları soyan ben oldum...

Adem ile Havva henüz soymadan; 

Armut''u-Ayva''yı yiyen ben oldum...

Küçücük hücreme kapandım kaldım,

Yıllar öncesine destursuz daldım...

Modası geçmeyen köynekten aldım; 

Gökteki yıldızdım, kayan ben oldum...

Terkedilmiş anı yaşadınız mı? 

Yola sabır taşı, döşediniz mi? 

Kocayıp gençliği boşadınız mı? 

Üflenen SUR''u duyan ben oldum...

Mehmet, sen de bir gün yaşlanacaksın,

Gerçekler acıdır, dışlanacaksın...

Kimbilir belki de suçlanacaksın; 

Elif, hakikati diyen ben oldum...

                         22.3.1987', '-Elif Ninenin akıbeti... Gençlik meyvasına henüz doymadan, Yasak meyvaları soyan ben oldum... Adem ile Havva henüz soymadan;  Armut''u-Ayva''y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yolun-sonu-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Hep Tutsaktım Sana', 'ben-hep-tutsaktim-sana-ahmet-nural-ozturk-315dj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ben hep tutsaktım sana

şimşekler çakarken görürdüm yüzünü

ve gecenin tenhasına dalar

dudağındaki benle yatardım

yanardın

ben hep tutsaktım sana

bazen düşümde bile yitirirdim seni

sonra dumanına rastlardım bir dağın doruğunda

sığara içerdin efkarlıydın besbelli

tüterdin

ben hep tutsaktım sana

şeytan kayalıklarında seke seke koşar

saklanbaç oynardın balıklarla

yakamoz yalnızlığında görürdüm seni

titrerdin

ben hep tutsaktım sana

yorgun gecelerimi uyuturken yorgun bir bankta

serin bir rüzgar okşardı yüzümü

savrulurdu saçların şafakla

anlardım sen gelirdin gizlice

severdin

ben hep tutsaktım sana

bulutların hüznünde görürdüm gözlerini

gökyüzü buğulu yıldızlar sönük

sabaha kadar seyrederdim seni ağlardın

ağlardım ağlardım

ben bir daha ağlardım

ben hep sana prangada tutsaktım...', 'ben hep tutsaktım sana şimşekler çakarken görürdüm yüzünü ve gecenin tenhasına dalar dudağındaki benle yatardım yanardın ben hep tutsaktım s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-hep-tutsaktim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün birer birer', 'gun-birer-birer-tuncay-akdeniz-puiyo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sayısı bilinmez her geçen günün

Zamanı geçiyor gün birer,birer

Değeri kalmıyor o giden ömrün

Her gün sayılıyor on birer,birer

Bir gün tutmaz olur elin ayağın

Kandilin sönerse bitmiştir yağın

Topraktan ötesi var mı durağın 

Çekilir bedenden can birer,birer

Geçen güne bakma düşün yarını

Karun da yığmıştı dünya varını

Sağlam temellere ör duvarını

Her gün yıkılıyor han birer,birer

Tuncayım kendini ateşe yakma 

Hakikat yolundan kenara çıkma

Riyakarın tatlı sözüne bakma

Yanlış hatalardan dön birer,birer', 'Sayısı bilinmez her geçen günün Zamanı geçiyor gün birer,birer Değeri kalmıyor o giden ömrün Her gün sayılıyor on birer,birer Bir gün tutmaz...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-birer-birer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolsuzluk', 'yolsuzluk-mikdat-bal-gmo4u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yetimin hakkını helal saydırır

Her türllü erdemi yıkar yolsuzluk

İnsanlığın ayağını kaydırır

Ahlaksıza kazanç, çıkar yolsuzluk

Bu bir hastalıktır, çare bulmalı

İnsanda ilk önce ahlak olmalı

Rüşvet alan zalim, haramdır malı

Kan irin, cerahat kokar yolsuzluk

Haksız kazanç alan yesin zıkkımı

Helal etmem asla kendi hakkımı

Hafif değil yolsuzluğun, yıkımı

Nice ocakları yıkar yolsuzluk

En tehlike iltimaslı tayindir

Her değeri yok eden bir mayındır

Rüşvet alan rüşvet veren haindir

Mutlaka ateşe sokar yolsuzluk

Size anlatayım bu kızmam niçin

Bir yumurtasını pişirmek için

Bir ev yakar insafı yok bu piçin

Evet yakar, canlar yakar yolsuzluk', 'Yetimin hakkını helal saydırır Her türllü erdemi yıkar yolsuzluk İnsanlığın ayağını kaydırır Ahlaksıza kazanç, çıkar yolsuzluk Bu bir hastal...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yolsuzluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvardaki Resim', 'duvardaki-resim-mehmet-osman-erol-unal-bsiqn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uçup gidiyor ilâhî zaman sonsuza doğru, kolsuz, kanatsız

Sükût içinde suâl ediyor dil-beste olmuş kadîm şarkılar

Dolaşırken gökkubbede ruhlar vecd ile sessiz, elsiz, ayaksız

Sesini arar şimdi kâse-i fağfurda bîzâr eski fasıllar

Sanki geçmişi arıyor duvarda asılı şu sahipsiz resim

Perde çekilmiş, tel susmuş heyhat, kalmamış sâkî, sönmüş ışıklar

Bir hicâz taksim çalıyor hâlâ hem şûh, hem mağrur ve biraz elîm

Sazını arar şimdi kâse-i fağfurda bîzâr eski fasıllar', 'Uçup gidiyor ilâhî zaman sonsuza doğru, kolsuz, kanatsız Sükût içinde suâl ediyor dil-beste olmuş kadîm şarkılar Dolaşırken gökkubbede ruhla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Osman Erol Ünal']::text[], 8.5, '{"poet":"Mehmet Osman Erol Ünal","poet_slug":"mehmet-osman-erol-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/duvardaki-resim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gömleği', 'deli-gomlegi-ahmet-aykol-03c1p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir deli gömleği ruhumu sıkan 

İçimdeki hüzün yüzümü yere çalan 

Bir kaç resim geçmişten somut kalan

Ve daim karanlık o günden itibaren yaşanan

Müşterisiyim her türlü günahın

Dilencisi olmuşum anlık gülüşün

Sınırı çizilmiş düşümün

Katmerlisi yaşanmış hergün hergün ölümün', 'Bir deli gömleği ruhumu sıkan  İçimdeki hüzün yüzümü yere çalan  Bir kaç resim geçmişten somut kalan Ve daim karanlık o günden itibaren yaşa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aykol']::text[], 8.5, '{"poet":"Ahmet Aykol","poet_slug":"ahmet-aykol","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/deli-gomlegi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-ahmet-aykol-i0zq7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir dolu kelime kafiyeyle yontulmuş

Utanmasın diye duygu giydirilmiş üstüne

Sıra sıra dizilmiş uyak ile dize ile

Hayat anlatılmış zaman ile en realite

Ölüm anlatmış biriaşkı nakletmiş diğeri

Ruh vermiş canından sıralarken harfleri

Kimi ağlatmış kimi coşturmuş sevenleri

Kimide karanlıktan bahsetmiş benim gibi', 'Bir dolu kelime kafiyeyle yontulmuş Utanmasın diye duygu giydirilmiş üstüne Sıra sıra dizilmiş uyak ile dize ile Hayat anlatılmış zaman ile ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aykol']::text[], 8.5, '{"poet":"Ahmet Aykol","poet_slug":"ahmet-aykol","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siir-125-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belli mi olur', 'belli-mi-olur-nedim-saatcioglu-8jwi0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatı tozpembe bir görebilsem

Karanlık geceler teselli bulur

Acı çekmek için henüz çok erken

Gün neler gösterir belli mi olur

Ağlamak dertlere çözüm getirmez

Acının izleri yaşla silinmez

Kader bu ne zaman güler bilinmez

Gün neler gösterir belli mi olur

Karanlık dünyana güneşte doğar

Sevgi sağnak olup ömrüne yağar

Gönlüne dağlardan büyük aşk sığar

Gün neler gösterir belli mi olur

O eski günlere dönemem deme

Gururum engeller gülemem deme

Kaybettim neşemi bulamam deme

Gün neler gösterir belli mi olur

Nice nice aşklar çıkar karşına

Vurulur kalırsın kara kaşına

Hiç kimse kalmamış yalnız başına

Gün neler gösterir belli mi olur

Ayrılık çözülmez bir düğüm değil

Tanrı’nın verdiği bir zulüm değil

Yalnızlık sevgiye bir ölüm değil

Gün neler gösterir belli mi olur

Gözlerin maziye dalıp durmasın

Boş yere ümitsiz hayal kurmasın

Anılar kalbime hesap sormasın

Gün neler gösterir belli mi olur

Zamanla bulursun aşkın yolunu

Ummadığın anda tutar kolunu

Yaratan incitmez garip kulunu

Gün neler gösterir belli mi olur', 'Hayatı tozpembe bir görebilsem Karanlık geceler teselli bulur Acı çekmek için henüz çok erken Gün neler gösterir belli mi olur Ağlamak dertl...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/belli-mi-olur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1.1.1.5.Vasati 1 Ayrılık', '1-1-1-5-vasati-1-ayrilik-his-kaybi-mk-rhsyb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vasati: 1 ayrılık 

Düş kuran genç 

Umutla bekleyen alkolik

Kan''ı Bitlenen nankör 

arkandan ağlar yarım bıraktığın her şarkı

vetfa''yı veren şeytan 

Boynu bükük mısra

nakarat nakarata küsmüş

sevgi ile hasret ahenk içinde 

kelepir aşklar revaç''ta eşantiyon tebessümlerle...

Tanrı''nın bildiği kul''un görmek istemediği 

Rakı''nın kokusu, yanında peynirin tadı 

Sevda hasret''e gebe

Doğum sancısıdır artık bekleyişler ömre 

Vasati bir ayrılık 

Kul nankör 

Tanrı vefalı 

Yamalı çorap ömrün 

Sen hep ayakkabını çıkarmaktan çekinirdin... 

Utancın Çorabı yamadığın gün değil ki 

Nasıl anlatmalı... Üsküdar...! ! ! Versac (M.K)     12/07/2005', 'Vasati: 1 ayrılık  Düş kuran genç  Umutla bekleyen alkolik Kan''ı Bitlenen nankör  arkandan ağlar yarım bıraktığın her şarkı vetfa''yı veren ş...', ARRAY['Türk Edebiyatı','Şiir','His Kaybı Mk']::text[], 8.5, '{"poet":"His Kaybı Mk","poet_slug":"his-kaybi-mk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/1-1-1-5-vasati-1-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahmaran(Son)', 'sahmaran-son-i-smet-barlioglu-10e8s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Delikanlı arabaya tırmanıp bindikten sonra kapıyı çarparak kapattı. Araba sallana sallana yola çıktı. Kafasındaki eski fötrü tamamen geriye itmiş olan kalın bıyıklı, sert kemikli, kalın kaşlı, ciddi görünüşlü şoför, gür bir sesle ve yüzüne bakmadan sordu:

- Sigaran var mı? 

- Birinci.

- Ver.

Sigarayı arabadan çektiği çakmakla yakan şoför derin bir nefes aldı:

- Niye filtreli içmiyorsun? 

- Alışkanlık.

- Değil. Bu laf maske. Korunak. Sığınak. Düzünden git. ‘İçemem’ de. İçemezsin; memursun. Çantandan belli. Üstünden-başından belli. Temiz fakat eski. Büyük memur değilsin. Olsan; araban olur. Ortanca memur değilsin. Olaydın; taksiyle yaylana yaylana giderdin, gaz tübü yüklü pis bir kamyondan yardım ummazdın. Küçük memur değilsin. Yanılsaydım; sana dolmuşta rastlar, her zamanki birilerine yaptığım gibi tanımadan geçerdim. Sen en minik memursun. Kontrolör falan, tahsildar falan. Düz konuşuyorum, kızma. Kızsan kızamasın. Durdurur kamyonu, seni indiririm, yıllarca taban tepsen Niksar ‘ı bulamazsın. Bozuk çeksen; iki yumruk atar küstürürüm. Sen Niksar ‘ın az sonraki gereğisin, ben senin şimdiki gereğinim. Koklama derin derin. Duygularım çok kuvvetlidir: Duydum içeriyi kokladığını, içmiş miytim diye. Ben tüm yaşantımda ağzıma vurmadım. Senin gibi. Sen de vurmuş olsan; koklamadan tanırsın onu. Bilirsin. Oysa kokluyorsun, et kokusu almış itler gibi. Şu kamyonlara doldurduğum tüblere ‘Şişe’ de derler. Ters dokundunmu, aman inlemeyen şişeler. Adamı beter eden şişeler. Tıpkı Obirileri gibi. Obirilerine yakın. Ben bunları taşıyorum. Yaftam cebimde. Sok elini al. Sağ cebimde, sana yakın. Dörde katlı. Sekize onaltıya katlı. Ne kadar katlasam doyamam. Mühürlere, büyük etiketli imzalara güvenin varsa; hiç kuşkun olmasın ki; ben doktorum, hukuk doktoru. Gerçekten bir doktor. Hukuk doktoru. Fotoğraftaki, bıyığının üstündeki iri benli adam benim. Ben, direksiyondaki bıyığının üstü iri benli adamım. Amansız tüb taşıyan bıyığının üstü iri benli adam… Yaşantı ne ki? .. Ben bulamadım, ben anlayamadım. Sen bana anlatabilir misin? Sanmam. Zira, sen yaşantıyı bilemezsin. Çantan elinde, düşmüşsün yağmurlu yollara, amansız tübler taşıyan kamyonlardan aman dileniyorsun… Ben yaşantıyı iplemiyorum. Bağışlama bilmeyen, yalvarsa dinlemeyen şişe taşıyorum. Çöp bidonlarını karıştırıp yiyorum. Koleradan doktorsuz giden iki öksüzümü, yamaçların otları arasındaki uykularında öpüyorum. Kurtulmaları için paralarını ve savunmalarını reddettiğim, anılarımda yıllanmış namussuzları, yıllardır vicdanımda ipe çekiyorum. Uzak, güvenli, minare boyunda taş duvarlara sırtlarını dayayıp dayayıp  gözlerini bağlamadan kurşuna diziyorum, bana, beni kazandıramayan, bana gerçek varlığımı armağan edemeyen kuru kuru, yüce yüce unvanları. Ben namussuzlara gerekiyordum. İyice namussuzlara. Şimdi namuslular bana mecburlar. İyice namuslular. Ocaklarında gazları tükenmiş namuslular. Faydalıyım. Varım. Gerekliyim birilerine, birkimselere.

Niksar ‘ a geldik. Seni çarşıda indirmeyeceğim. Çarşıları sevmem. Kirlilikler, karanlıklar pazarlanır.Seni evlerde indireceğim. Kendi istediğim yerde. Evlerde. Gazı tükenmiş evler, benim kamyonluk geçtikçe aydınlanacak, ısınacak, sıcacık bir güçle dolacak, tazelenecek. Seni aydınlıklarda indireceğim. Öz aydınlıklarda. Kök aydınlıklarda. Gerçek aydınlıklarda. Mızrak gibi gerçek aydınlıklarda.

Ve sen… Yaya gideceksin, aydınlıkları meşale gibi ellerine alıp karanlıkların üstüne. Üstüne üstüne. Adımlarını rap rap vura vura. Hançerende balyoz balyoz nağralar. Sertçe babam, erkekçe… Gerçekçe…

Delikanlı arabadan aydınlıklarda indi ve adımlarını rap rap vura vura karanlıkların üstüne üstüne gitti. Akşamlar iyice kararırken, daha bir iyice, daha daha bir iyice kararırken, avuçları alev alev yana yana, ayakları alev alev tutuşa tutuşa geri döndü.

İlk durakta son minibüs, ilk ve son yolcusunu bekliyordu. Delikanlı direksiyon yanına oturur oturmaz, araba bir şoförü ve bir yolcusuyla hareket etti.

‘Tek yolculu şoför bol bol konuşuyor, adamın için açıyor, mutsuzluğunu dağıtıyor.’ du.

Arabanın farları karanlık geceyi elek elek delmekteydi. Pikapta laçkalaşan ses gecelerin türkülerinden birini söylüyordu. Önlerinde dayanıksızlaşıp eriyen ağaçların kuru gölgeleri gerilere kayarken soğuk ve karanlık hışırtılar çıkarıyorlardı. Toprak, arabanın kuvvetli farları önünde, biryerlerde bembeyazdı, apaydınlıktı. Araba öfkeli motor sesleriyle kendi ışığını, kendi aydınlığını yutmaya koşuyordu.

Tokat ‘ın ışıkları görünmeye başlamıştı. Halsiz halsiz, benek benek. Yardım dilenen mum ışıkları gibi karanlığın ortasında.

Araba bir virajı döndükten az sonra, parketmiş tankerin viraj dibindeki ışıksız, demir karaltısını gördüler. Şoför sol kapıyı açarak kendini savurdu. Delikanlının dudaklarından tek bir ses çıktı:

- Minicik…

Sonra, öfkeli demirler, saclar, camlar, zerreler birbirine girdi.

Gürültü, yaylanan, kaynayan, nabız gibi atan dalgalar halinde uzaklara yayıldı, gitti. Her şey başladığı kadar çabuk sustu. Ne bir inilti, ne bir ses.

Sadece uzak böceklerin cırlamaları…

Nicelerden ve nicelerden sonra birileri geldiler. İnsan kalıntılarını, parçalanmış vücutları buldular, saptadılar, birşeyler yaptılar.

Dudakta belirmeye başlayan gülücük ikiliydi. Ölüm, birini kendinden kaçarken, birini umutları başında yakalamıştı.

Bir siyah yol çantası buldular. İçinde düzenli, ağzı-dili temiz tutanaklar, birkaç ince pelür kağıt, birkaç karbonlu kağıt tabakası, bir İş Kanunu, devlete ait bir tükenmez kalemle yarısı yenmiş bir simit ve astara dökülmüş susam taneleri buldular. Daha ötesi; kimlik kartı büyüklüğünde bir beyaz karton.

‘Ben ölmüşsem’ falan yerde çalışan ‘eşime durumu böylece duyurun. Teşekkürler ederim.’ Diyen bir beyaz karton. Batan denizatlıların su yüzünde kalan şamandıralarındaki duyurular gibi bir şey… ‘Dumlupınar burada battı’ gibi bir şey.

Üzerinde eski bir uzun ceket bulunan karısını, darmadağın olmuş kalıntıların başına, gecenin şafağa devrildiği alacalıkta getirdiler. ‘Bakmasanız daha iyi olur.’ Dediler.

Genç kadın bakmadı bile… Görmedi bile… Ellerini, uzun uzun asıldığı yanlarından çekmedi bile…

Kranlık gecenin can çekiştiği sınırda, omuzlarına püskül püskül dökülen saçlarıyla, düz eski geceliğiyle, yanlarından cansız sarkan elleriyle, tırnakları kırılmış zayıf parmaklarıyla ve titrek, dolgun yalınayaklarıyla daha bir uzun, daha b,r görkemli, daha bir erdemli, daha bir yüce görünüyordu.

Dipleri aşağılarda daha bir derinleşen, başları gecenin karanlığından yukarılardaki fecirin aydınlığına daha bir yükselen yalçın kayalara doğru gitti, gitti, gitti. Körpe otlar üzerinde kayarak uzaklaşan, uzaklaştıkça yücelen bir hayal gibi. İlerilerde biryerlerde durdu. Çıplak ayaklarını bahara susamış kadife çiçekler okşuyordu. Eğildi. Biryerlere uzandı.

Yeniden doğrulduğunda, ince parmakları arasında tek bir çiçek vardı. Çiçeği yüzüne yanaştırdı. Avuçlarını kıymazcasına üzerine kapadı. Küçücük bir serçeyi gagasından öper gibi sevgiyle, narin bir kelebeği kanadından öper gibi dikkatle öptü. Sevdi. Solgun yanaklarıyla okşadı. ‘Kubicik’ diyerek gene öptü. Küçük küçük, minik minik, yumuşak yumuşak öptü. Sonra kollarını ileri uzattı. Avuçlarını görünmeyen ılık yağmurların sularına açtı:

- Tanrı ‘m, bana artık yardım etme… Bana artık yardım etme… Artık bana yardım etme Tanrı ‘m… Benim yardıma gereğim kalmadı… Hiç kalmadı… Tükendim… Yaman yerde tükendim… Kötü yerde tükendim… Tanrım, bana artık yardım etme… Benim artık umutlu baharlarım kalmadı… Baharlarım hem ilkbaharlarım, hem sonbaharlarım oldu… Umutlu baharlarım böyle tükendi… Birdenbire tükendi… Böyle tükendi… Böyle tükendi… Böyle… Böyle…

İki elinin parmakları arasında, teker teker kopardığı körpe çiçeklerin incecik yaprakları, ışıksız geceler gibi karanlık karanlık, kuş tüyleri gibi hafif hafif, isli çiğ damlacıkları gibi uçuşa uçuşa düştüler.

Boş kalan avuçlarını havalara açtı:

- Benim artık gereğim kalmadı… Bana yardım etme Tanrım…

Çiçekler üzerinde kayarak başında rüzgarların uğuldadığı kayalıklara ulaştı. Başını daha bir yukarılara, daha bir enginlere kaldırarak bağırdı:

- Şahmaranlar…

Uzak derinliklerden arka arkaya ve yücele yücele gelen yankılar, tükenmemeye savaşan gecenin suratına tükrük gibi savruldu:

- Şahmaranlar… Şahmaranlar… Şahmaranlar…

BİTTİ

(Sonraki hikaye türü düzyazı eser ‘Parmak Çocuk.’

Bu hikaye, bir süreden beri okuduğunuz Şahmaranlar isimli romanın kahramanlarının daha sonraki dönemlerine ait –yine gerçek- bir yaşam öyküsüdür.

İlgileneceğinizi umuyorum.

Paylaşmama katkı sağladığınız ve izleyerek beni yüreklendirip devam etmemi sağladığınız için hepinize gönülden teşekkürler ediyor, kalbi sevgilerimi bölüşüyorum.

İzleyin, pişman olmazsınız…', 'Delikanlı arabaya tırmanıp bindikten sonra kapıyı çarparak kapattı. Araba sallana sallana yola çıktı. Kafasındaki eski fötrü tamamen geriye ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sahmaran-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-mehmet-akif-gulhan-7hi8x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'git istemiyorum seni artık

bunca bekleyişten sonra

seni beklemek

senle vuslata ermekten güzelmiş

al pembe pabuçlarını

ayak ucuna basarak git', 'git istemiyorum seni artık bunca bekleyişten sonra seni beklemek senle vuslata ermekten güzelmiş al pembe pabuçlarını ayak ucuna basarak git...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/git-120-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağır Adam-II', 'sagir-adam-ii-muharrem-cetinkaya-de0dn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün yürüyorduk,

Yanımda

 Sağır bir adam.

 “Canım bir bardak süt istedi”dedim.

Tarif ettim ineği,işaretle

“….. nedir” dedi,sağır adam.

Herhalde anladı,

…………Madam

“Sağır işitmezse yakıştırır”derdi,babam

“Madam değil,”dedim.

“Biliyorum,anladım”dedi sağır adam,

Şaşırdım kaldım,sütü nasıl anlatsam…

“İneği biliyorum ama …… nedir? ”dedi,

Sağır adam.

“Avucumu açtım,içilir”dedim

Sağılır inekten..”,işaretle.

Bunu da  öğretmişti babam.

“anladım,yağmur? ”dedi,işaretle

Sağır adam.

“Bizi de sağarlar,bütün ömrümüzce “dedim.

“Sağılmayı anladım ama,seni niye? ”dedi

……………….

“Sabret oğlum daima”derdi babam,

Ama taşmıştı artık sabrım; 

Kolunu tutup; cebine bak”-bomboş-

“İşte sağılmak”dedim.

Memnun oldu,

Sağır adam 

“Görecelik aldatır “derdi babam.

.

“Tamam! ” 

 “Sütün ne olduğunu şimdi anladım”

Dedi,

Sağır adam! ...', 'Bir gün yürüyorduk, Yanımda  Sağır bir adam.  “Canım bir bardak süt istedi”dedim. Tarif ettim ineği,işaretle “….. nedir” dedi,sağır adam. He...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sagir-adam-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapsettiğin Ruhum muydu?', 'hapsettigin-ruhum-muydu-birsen-ates-m04lg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sesin sesinle buluştuğunda

ılık bir rüzgar esti

yüreğimde

derinlerde depremler

yıkıldı şehrimin duvarları tek tek

inanmıştım

seninle gelecek güne

ağırdı yüklerim

biraz da sen yükledin

kabus oldun

hapsettiğin ruhum muydu

z i n c i r l e n m i ş

anlamadın

oysa

geniş vadilerde

dört nala koşuyor

gem vurulamamış

r u h u m', 'sesin sesinle buluştuğunda ılık bir rüzgar esti yüreğimde derinlerde depremler yıkıldı şehrimin duvarları tek tek inanmıştım seninle gelecek...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hapsettigin-ruhum-muydu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen sustukça', 'sen-sustukca-mehmet-halil-yckrd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat akıyor, bir ırmak gibi,

Bir taraf durgun, bir taraf hızlı.

Bir kısmı temiz, bir kısmı kirli,

Kenarda durmayın içine girin.

Durgun sular biriktirir zehiri.

Durgun su, da, bir gün kirlenir,

Dışında durmayın, içine girin.

Suya da dokunun, sabuna da,

Sizde..! akıntıya bir hız verin.

Hareket her şeyden daha temizdir.

Üsteki ister ki stotuko korunsun,

Sen  mevcut durumda, en alttasın

Devinim olmazsa, alta kalırsın,

Kaybedecek neyin varki durursun? 

Mutlu yaşamak senin de hakkın.

‘’işleyen demir pas tutmaz’’

Uyanın ey dostlar, uyanın,

Çalışanı düşman korkutamaz,

Sizde artık hakkınızı  arayın.

Mücadele etmeden hak alınmaz

Üstüne üstüne gelirken felaket

Kaçmak kurtuluş olurmu hiç? 

Hayat, mücadeleden ibaret…

Kazanacağın, kendi emeğin.

Alacağın, kendi hakın nihayet.

Her şey suyun üstünde yüzüyor,

Altaki, çoğunluk bunu görmüyor.

Kaldır da başını, şöyle bir bak.

Sen sustukça, sırtında duranlar,

Kanının, son damlasını alacak.

Stotukocular susturacak seni,

Hakim olan, onlar değil mi? 

Susma, inadına yükselt sesini.

Seni yönetenler, senden değil ki,

Yönet artık, kendi kendini.', 'Hayat akıyor, bir ırmak gibi, Bir taraf durgun, bir taraf hızlı. Bir kısmı temiz, bir kısmı kirli, Kenarda durmayın içine girin. Durgun sula...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sen-sustukca-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutunamadım', 'tutunamadim-birsen-ates-3zb15', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'tutunmaksa amaç yıldızlara

denedim olmuyor

t u t u n a m a d ı m...

bozuk bir plak gibi takıldım

k a l d ı m

hayatın bir karesinde

bir gece vakti

boğuldum marmara denizinde

yüreğim buz kesti

buz  mavi

üşüdüm

sessizce geldim

gidiyorum

yaşam

t u t u n a m a d ı m

acılarım kız kulesinde

bedenim marmara denizinde', 'tutunmaksa amaç yıldızlara denedim olmuyor t u t u n a m a d ı m... bozuk bir plak gibi takıldım k a l d ı m hayatın bir karesinde bir gece ...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tutunamadim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Bugün', 'belki-bugun-humeyra-yilmaz-suyq4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'belki bugün umutlarımı siyaha boyarım 

kendime daha yakın hissetmek için

gün kızıl bir tepside sunarken akşamı

gecesefası kokar tenim

göz göz yaralarımı ellerimle

yüreğime gömer

acısını saklarım 

aklımın senden uzak bir köşesine

belki bugün her şeye rağmen sana gelirim habersiz

kokumu unutmana yardımcı olması için

kimsesiz göllerde açmış 	

birkaç nilüfer getiririm gelirken

biraz bakışırız 

sen tutarsın kendini ağlamazsın

ben deniz deryaya karışırım alabildiğine

derin bir sessizliğin içine düşeriz

gitmek zamanı gelmiştir ama 

alçakta olsa “kal” diyen bir ses değil midir? 

birbirimizden beklediğimiz…

belki bugün yarınlarımı senden alıp

yine düne koyulurum yorgun ve çaresiz

kendime güzel bir mevsim seçip yaşlanırım

gelmesen de güneşim olur musun? 	

inan ben bununla da yetinirim…', 'belki bugün umutlarımı siyaha boyarım  kendime daha yakın hissetmek için gün kızıl bir tepside sunarken akşamı gecesefası kokar tenim göz gö...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/belki-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
