INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hira bir dağ gönül', 'hira-bir-dag-gonul-hamdi-oruc-fdg0j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hira Bir Dağ Gönül 

Hira bir dağ gönül 

Dağ olurum Hira için

Bana dağdır aşkı bilen gönül

Ve Hira bir dağ gönül…

Kavrulmuş taşları bile

Aşkın çölünde

Dağında bir gönlü vardır

Bulutlar dağların başında taç

Güneşi ilk dağlar görür 

Ay dağların avuçlarında çiçek

Pınarlar dağların göz yaşı

Ağaçlar göklere özlemleri

Hey gönül Hiraya  nasıl bakarsın toprak diye

Hira bir dağ gönül…

Aşkla yanan gönül...

Sevinci dağ Hiranın

Selam 

En kaygan zamanda

Depremlerde

Gönüllerimizi sıkı tutan dağlara...

Sevgileri bizde dağ olanlara

Selam 

Aşkın çölünde dağ olan gönüllere

Hira bir dağ gönül…

Aşkla yanan gönül...

Zikir akar ırmaklardan

Etrafında ağlar rüzğar

Türbeye benzer dağlarımız var

Kuşları dayanıklı dağların

Kış onların pençesinde can verir...

Aşkın  çölünde kum taneciği olsan yeter gönlüm', 'Hira Bir Dağ Gönül  Hira bir dağ gönül  Dağ olurum Hira için Bana dağdır aşkı bilen gönül Ve Hira bir dağ gönül… Kavrulmuş taşları bile Aşkı...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Oruç']::text[], 8.5, '{"poet":"Hamdi Oruç","poet_slug":"hamdi-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hira-bir-dag-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabirden', 'kabirden-tarhan-simsek-xyoxg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zifiri bir karanlık

Gece

Yine

Çok kaçırdım galiba.

Uykuya yenik düştüm.

Tatlı bir uyku

Sonrası 

Sana dair pusulu düşler.

Uyanmak ne de zor

Seni bulmuşken düşlerde

Bırakmak ne de zor.

Uyumalı yine

Yeniden uyumalı

Sana ulaşmanın tek yolu bu.

Bedenim kaskatı

Etraf neden bu kadar karanlık

Ay ışığı

Neden süzülmüyor penceremden? 

Uyumalı

Hayır hayır 

Kalkıp seni dizmeli satırlara

Ama

Neden bu yorgunluk

Bedenim benle değil gibi.

Çok kaçırdım belli.

Yukarıda 

Komşular

Mevlit okutuyor

Neden ki? 

Biri mi öldü yoksa? 

Nuri amca vefat mı etti acaba? 

İyi adamdı.

Yazık oldu fukara

Çok kaçırdım belli

Kargaşayı bile duyamadım.

Kalkıp gitmeli

Bir başsağlığı dilemeli

Ama

Bedenim benle değil sanki

Bu kaskatılık neden? 

İmam ne de iyi okuyor

Kim öldü acaba

Çok kaçırdım belli.

Ne gereği vardı

Bu kadar içmenin

Ne demeli bilmem ki sana

Ayyaş selim

Bu kadar içirtecek ne vardı.

Fondip fondip

Tükettirdin bana koca meyhaneyi.

Hesabı kim ödedi acaba

Çok içmişim belli.

Ama bu karanlık niye

Kapılardan süzülen ışık da yok

Yine elektrikler mi gitti

Çokk içmişim belli.

Garip

Üst kattan

Tanıdık sesler

Annemin sesi sanki

Ağlaması ne acı

Garip

Hep tanıdık sesler

Ne de acı okuyor imam

Garip

İmamın ne işi var evde

İmam dediğin mezarda olur

Garip ki ne garip

Bir kadeh bir kadeh daha

Çok içmişim belli

Puslu meyhane yeri

Gülüşmeler ağlamaklı

Çok içmişim belli.

Ey Selim efendi

Ne gereği vardı.

Bir kadeh daha getir hancı

Doldur be hancı

Donat masayı hancı

Çok içirttin belli.

Hancı doldurdu

Efkar içirtti

Bana Selim değil

Sen içirttin sevgilim

Ne gereği vardı

Ayrılığın

Oysa ne de mutluyduk

Aşka inat sevdim

Ne gereği vardı

Ayrılığın

Ah sevgilim

Bana 

Efkar değil 

Sen içirttin

Garip

Ağlamalar arttı

Annemin sesi sanki

Garip

Toprak sesi

Toprak kokusu 

Kürek şakırtısı

Ah sevgilim

Bana efkâr değil

Sen içirttin.

Kollarım

Ayaklarım

Göz kapaklarım

Benle değiller sanki

Garip

Kundaktaki çocuk misali

Sarmalanmışım sanki

Çok ama çok içmişim belli

Ah sevgilim

Ne gereği vardı

Mutlu düşlerimize

Bir anda

Tırpan çektin

Bahçıvanlık sana göre değil

Sana orak, tırpan değil

Benim ellerim yakışır

Toprak kokusu

Sanki yağmur

Vurmuş gibi

Garip

Yağmur yağmadı gece

Çok içmişim kevelli

Kadehler 

Meyi değil

Seni döktü içime

Her içmelerim sen

Ah sevgilim

Beni mey değil

Sen sarhoş ettin.

Ağlamalar arttı

Kim öldü, garip

Tatlı uyku

İmam ninni söylüyor sanki

Uyumalı

Sana dalmalı

Seni sarmalı



Şafak

Senle güzel

Ama

Bu şafak sensiz geçti

Ah sevgilim

Bana sen değil

Sensizlik içirtti

Çok içmişim belli

Son hatırladığım

Kıyıya yakın

Sana uzak sahillerde

Bir uçurum

Dönen başım

Başımı döndüren

Sarhoşluk değildi

Sen döndürdün sevgilim.

Garip

Sesler kesildi

Ağlamalar durdu

Garip

Boşaldı ortalık

S

So

Son

Sonr 

Sonra

Ah sevgilim

O uçurumdan 

Kuşlar misali

Uçuşum

Ah sevgilim

Ben ölüyüm

Korkmak yersiz

Hayat senle güzel

Sevgilim

Beni sen değil

Sensizlik öldürdü sevgilim…', 'Zifiri bir karanlık Gece Yine Çok kaçırdım galiba. Uykuya yenik düştüm. Tatlı bir uyku Sonrası  Sana dair pusulu düşler. Uyanmak ne de zor S...', ARRAY['Türk Edebiyatı','Şiir','Tarhan Şimşek']::text[], 8.5, '{"poet":"Tarhan Şimşek","poet_slug":"tarhan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":176,"source_url":"https://www.antoloji.com/kabirden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pisice', 'pisice-fidan-bulut-b7w7y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kedi sen hiç üşümezmisin

Hayalde kurmazsın sen

Yatsam yanına hırlarmısın

Tırmalar kovar mısın beni

Alsan yanına

Çöpleri karıştırsak

Kirlenip kirlenip bir köşede yalansak

Damlara da çıkarız belki

Seni sevgilinle seyrederim

Uslu uslu söz sana

Bahçeleri talan etsek

Komşu evlerden kıyma tavuk yürütsek

Farelerle kafa bulup gün boyu

Kaçsak itlerden onları delirte delirte

Sen iyi bilirsin buraları

Her deliğini her yenilen naneyi

Döksek bir bir çamaşırları utanmadan

Allahına kadar sevsek pisliği

Kıskansak ev kedilerini ölümüne

Ama ait olmadan kimseye

Arkaya bakmadan yaşasak sen ve ben

Üşüsek,bir kadın bacağına sürtünsek parkta

Tekmeyle kovalansak kuyruğumuzda tenekeler olsa

Al beni de kedicik al yanına

Sorgusuz dibine kadar yaşasak kedi olmayı

          arkaya bakmadan........', 'Kedi sen hiç üşümezmisin Hayalde kurmazsın sen Yatsam yanına hırlarmısın Tırmalar kovar mısın beni Alsan yanına Çöpleri karıştırsak Kirlenip...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/pisice-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zifiri Aşk...', 'zifiri-ask-ugur-deniz-ulkegul-uuons', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani gün biter 

Yüreğimde özlemine yanarım 

Ben ki devrik cümlelerin şairi 

Yüreğim yangın yeri sözlerim eksik 

Baş ucumda yarım kalır sensizlik 

Bensizliğe tamamlarım................... 

Zaman 

Yosma sevdalar devri ya 

Kravatlı dolaşır soytarılar 

-Adam dediğin- ''dilsiz'' 

Beriki çıkar gazeteye, dergiye 

Konuştukça konuşur namussuz 

Ayyaş bilgeliğinden 

Kadınsa kadınlığından 

Değilse erkekliğinden yanına varılmaz 

Yağmur diye yüzüne tükürsen ayılmaz 

Laf ebesi, 

''Dönüşmüş'' alfabesi, 

Karanlık çağın ''Aydın tiplemesi'' 

İmgesi, kusursuz.... 

Aydın deyince aklıma geldi 

Dün gece yine elektrik kesildi 

Derler ya hani, vakitsiz.... 

Tam da sana bir şiir yazacaktım, 

Sevişmek yoktu içinde 

Vakit dardı, belki ondan 

Ne bileyim işte 

Sabahın bilmem kaçında 

Yeni uyanmıştım uykudan... 

Yağmur vardı 

Bir de ansızın gelen 

O gök gürlemesi 

Az kaldı 

Ödüm patlıyordu korkudan 

Mübarek iyi çaktı ha! 

Sanki ''yeni bir ihtilal '' in sesi! 

Sana bir şiir yazacaktım 

Baktım 

- Özlemek iyi hoş da - 

Tedavülden kalkmış bütün duygularım 

Yüreğim tıka basa dolu, aklım boşta... 

Yine sigara yaktım 

İlk nefeste can verdi hüzün 

Rahatladım, hafifledim derken 

Aynaya takıldı bakışlarım... 

Ayna da yüzün.... 

Düşündüm sonra 

Bazı yaralar kapanmıyorsa eğer 

Bir nedeni olmalı... 

Yani böyle gitmeli insan gidecekse 

Ardında bir iz bırakmalı... 

Hani memleket kokmalı şair 

Düşse, geceyse, karanlıksa sokak 

Yolu aydınlatacak bir ateş yakmalı... 

Şair deyince aklıma geldi 

Dün gece sana bir şiir yazacaktım 

Ne kadar berraktı duygularım 

Kahretsin! 

Elektrik kesildi.....', 'Hani gün biter  Yüreğimde özlemine yanarım  Ben ki devrik cümlelerin şairi  Yüreğim yangın yeri sözlerim eksik  Baş ucumda yarım kalır sensi...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/zifiri-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharsın bana gül davam', 'baharsin-bana-gul-davam-hamdi-oruc-omdcv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baharsın bana gül davam

Mertçe öl diyor bu mart gecesi

Ay sözler aksın avuçlarından...

Gül davam sen buna da kadirsin

Gül davam sen baharsın bana

Bahar sen buna da kadirsin

Ayağa kalkıyor içimde sakarya

Fırat Nil

Zikreden  dil

Beni gül ölüme çağırıyorlar

Gül ölüm bana

Bahar sen buna da kadirsin

Çiçeklendim iğde ağacı gibi

Bahar habercileri gözlerim

Duadaki ellerim

Secdedeki alnım

Beni gül ölüme çağırıyorlar

Gül ölüm bana

Kanım güle susuz

Gel bana gül ölüm

Gel bana gül ölüm

Seccadem gül habercisi

Beni gül ölüme çağırıyor

Kefenlere sarılı  çiçekler

Şu çiçekler bahar habercileri

Beni gül ölüme çağırıyor

Gül davam sen buna da kadirsin

Tükürmeli suratına kirli hayatın

Geç bile kalındı

Bahar müjdeleri gibi 

Şu papatyalar gibi gözlerim

Seccadem tuttu elimden

Şu çiçekli  kefenler

Beni gül ölüme çağırıyor

Hiç gül takmadım yakama...

Bahçenin gülleri gül dilleri

Beni gül ölüme çağırıyor

Mezarıma koşuyor güller 

Gül davam sen buna da kadirsin

Tükürmenin zamanı kirli korkulara...

Geç bile kalındı

Beni gül ölüme çağırıyor

Tarihin her altın sayfası

Zamanda dost ses

Beni gül ölüme çağırıyor

Öleyim ve uyanayım gül bahçelerine

Ve nisan yağmurları 

Beni gül ölüme çağırıyor

Gül ölüm bana

Hiç gül bitirmedi gönül bahçem...

Bahçeler boyun bükmüş

Beni gül ölüme çağırıyor

Bahar sen buna da kadirsin

Uhut dağının etekleri...

Açıyor papatyalar

Beni gül ölüme çağırıyor

Tarihteki bahar müjdeleri... 

Fatihler Alpaslanlar

Beni gül ölüme çağırıyor

Gül ölüm bana

Bende gül gül sorular

Gül sorular...unutulan gül tarih

Beni gül ölüme çağırıyor

Karşılaştığım bahar dereleri 

Beni gül ölüme çağırıyor

Gül davam sen buna da kadirsin

İnci kimin göz yaşıdır

Boyunlarda akışı yıllarca sürmüş...

İncilerin beyazlığı

Beni gül ölüme çağırıyor

Ve elif görsem vurulsam...diyorum

Kainat döner elif diye…

Her elif dikiliyor karşıma

Beni gül ölüme çağırıyor

Hiç elifi anmadı dilim

Ah hiç yanmadı dilim...

Her elif minare minare

Beni gül ölüme çağırıyor

Gül ölüm bana

İnci kimin göz yaşısın

Bitmesin bende yakasına gül takmış sorular...

İçim içime sığmıyor ey kirli hayat

Gönlümde bahar müjdeleri

Kutlu izin gül kokusu

Beni gül ölüme çağırıyor

Gül davam sen buna da kadirsin

Yarışa başlasın yollar.

Kanlı gömlekle çıksam 

Affım yazılsa...

Nurlu yollar 

Beni gül ölüme çağırıyor

Bir ses diyor ki:

Mertçe öl bu mart gecesi

Ay sözler aksın avuçlarından...

Gökte ay

Bayrağımda ay

Beni gül ölüme çağırıyor

Gül davam sen buna da kadirsin

Beni gül ölüme çağırıyor

Mezar olmuş güller

Bilinmeyeni haykıran bülbüller

Şu mart gecesi...

Bana  bin  bahar habercisi

Şanlı tarihin her altın sayfası

Göklerin maviliği

Beni gül ölüme çağırıyor

Gül davam sen buna da kadirsin

Çanakkale gibi Uhut gibi bahçelerim...

Uhutlar Hamzalar

Beni gül ölüme çağırıyor

Gül ölüm bana', 'Baharsın bana gül davam Mertçe öl diyor bu mart gecesi Ay sözler aksın avuçlarından... Gül davam sen buna da kadirsin Gül davam sen baharsın...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Oruç']::text[], 8.5, '{"poet":"Hamdi Oruç","poet_slug":"hamdi-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":111,"source_url":"https://www.antoloji.com/baharsin-bana-gul-davam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadı şiirim', 'olmadi-siirim-fidan-bulut-pyg39', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiirde doğmak vardı

Kafiyelerde kaybolmak

Mısralarda oyun oynamak

Şiirde büyümek

Ve yine şiirde bulmak aşkı

Ve yine aramak yarım sevdaları

Şiirde yaşamak hayatı

Şiir tadında sevda acısında

Şiirde ölmek ölüme meydan okuyarak

Benim şiirim olmadı hiç

Şiirim olamadın

Şiirde kaybolup ağlamadım

Aşkı yaşayıp şiir tadında

Arayacak yarım sevdalarım da olmadı

Seni şiir tadında ateşini kanımda

Canımı canında bulamadım hiç

Kanım tutuşmadı

Sen hep uzak hep yok

Ben cansız nefessiz

Ne geldin şiir oldu

Ne terkettin dünya durdu

Olmadı be güzelim

Tek bir satır şiir

Tek bir nefes

Bir fasıl hayat 

        olmadı be gülüm ben yaşamadım.................', 'Şiirde doğmak vardı Kafiyelerde kaybolmak Mısralarda oyun oynamak Şiirde büyümek Ve yine şiirde bulmak aşkı Ve yine aramak yarım sevdaları Ş...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olmadi-siirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzaltmışlık 30 - 45', 'yuzaltmislik-30-45-koray-ergul-gjq62', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-	31 –

Kaçak göçek yaşanmış sevdaların yaralısıyım

Hasret vuslatta daha bir acı

Kavuşmak pişman edici

Karanlık…

Bu saatten sonra 

Söylenecek her söz

Kan akıtır! 

		

-	32 -

Gece üstüne üstüne gelir…

Yalnızlıkla yollarını ayırdın ayıralı

Gülmek canını acıtır

Ağlayamamaya hasret beklersin aydınlığı

Şafak gelmez

Gelmek bilmez…

-	33 –

Evimin arkasındaki cevizler yağmur kokuyor…

Uzaklarda

Artık bir yabancı kadar tanıdığım Ankara’nın

Yanıp sönen ışıklarında

Öylesine süren hayatlar…

Seni seviyorum! 

-	34 -	

Elimde değildi

Zamansız bir istilayla esir etti beni kendine

Zapt etti kalelerimi bir bir

Artık senle yaşayamam

Yalnızlığım beni affet

Seni terk ediyorum…

-	35-

Atlılar gelir geçer

Sevdalar görürüm

Gün yanığı hasretlere yürürüm

Kelimeler keser dilimi

Koşar ruhum bildik bir ateşe

Dizgininden boşanmış

Ve dörtnala! 

-	36 –

Yine divane faslındasın…

Adın gibi bilirsin

Kıyamet uzakta değil! 

Bir yanın kaçıp gitmeye meyilli; 

Bir yanın ateşperest, yangın delisi! 

Eni sonu

Bir kör sevda

-	37 –

Tam ortamızda bir tanrı heykeli yükselmekte, 

Bütün azametiyle…

Seni ateşiyle besleyen, 

Beni sana aşık eden…

Üzgünüm…

Onun sana bahşettiği nimetlerden değilim! 

-	38 -

Cehenneminin kapıları açılıverir ard arda…

Hüznün bir köşede, vakur, oturmaktadır…

Bayraklaşmış sevdalarından kalan

Karanlık ve keskin

Sevinçlerdir yalnızca! 

-	39 –

Ezildim

Yokluğunun yedi kat altında

Ve üstünde

Çektim tüm sancılarını gözlerindeki bulutların

Yandığım kadar yakınında

Ölümün ucundaydım! 

Ve yağmur yağdı…

-	40 –

Seni turnalı türkülerde sevdim

Kuzey rüzgarlarında üşürken

Umudum esir pazarlarına düştü

Kalmadı senden gayrı

Ne hayat ne ölüm

Yalnızlığa da dönemem artık…

-	41 –

Kanar durur

Yüreğimin ıssız bir köşesinde

Destanlardan arta kalan

Amansız sevdam…

İhanetine değil

Kaçaklığına değil

Çocuğunun öksüzlüğüne! 

-	42 –

Bir şehir daha yıkıldı

Gözlerinden süzülen...

Keşke ateşin daha cılız,

Vazgeçmek

Daha kolay olsaydı…

Unutmaya hükmedebilseydim

Keşke…

Ve ferman buyurunca

Gelseydi...

-	43 –

Depremlerinden sonra

Hala bir medeniyet durmakta

Sapasağlam…

Bakmaktan korktuğum gözlerinde

Bir sevda destanı yazılmakta! 

Çünkü

Uzak diyarların kızı:

Seni sevdim! 

-	44 –

Sevdam gizli bir antik şehir

Her adımında üstünden geçeceksin

Kayıvereceksin,

Kaypak akşamlarına Ankara’nın

Alınyazım kentin

Sokaklarını

Alnından vuracağım! 

-	45 –

Adilbank’ a oturmuşuz

Dil – Tarih’ e nazır

Evvelce söylenmemiş sevda dizeleri

Dolanır durur dilimin ucunda

Mikelanj’ı çağırırım’

Koca Sinan’ı! 

Yalvarırım zamana...', '-	31 – Kaçak göçek yaşanmış sevdaların yaralısıyım Hasret vuslatta daha bir acı Kavuşmak pişman edici Karanlık… Bu saatten sonra  Söylenecek...', ARRAY['Türk Edebiyatı','Şiir','Koray Ergül']::text[], 8.5, '{"poet":"Koray Ergül","poet_slug":"koray-ergul","theme":"Türk Şiiri","is_hero":false,"total_lines":116,"source_url":"https://www.antoloji.com/yuzaltmislik-30-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıyınca O gülü', 'taniyinca-o-gulu-hamdi-oruc-tzcrj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanıyınca O gülü

Tanıyınca onu sevmeyi öğrendim

Gülü tanıdım

Kim dese yalandır 

Sevmedi Hamdi

Veyseldi şu gönlüm 

İz iz güllere düştü

Gülü tanıyınca

Hasreti dağ oldu bende

Herkesin var bir leylası

Leyla arayan 

Mecnun bende 

Yıllar yılı çöllere düştü...

Gülü tanıyınca

Sevgin gül 

Gönlün gül

Seherlerde gönlüm

Ateşten güllere düştü

Gülü tanıyınca

Hasreti İsanın eli gibi dermanlı

Hasreti tuzlu su gibi iyileştirdi gönlümün yaralarını

Ateş kor kor bende

Yıllara düştü

Yusufu ararken Zeliham 

Kuyudan derin kollara düştü

Gülü tanıyınca

O güle hasret güller eker gönle

Şehit gömleği giymiş evlatları

Bir ana yüreğim

Çığlıkları tozlu yollara düştü

Gülü tanıyınca

Ümit karanfil çiçeğimdir

Yıllarca

Sellere düştü.

Bir ah çekti ferhat

Benim ahım 

Dillere düştü

Gülü tanıyınca

Gülden gafil olan bahar görmesin

Gülden gafil olan cennet görmesin

Sevginle mutlu 

Bu asrın çöllerinde

Develeri önünde

Veyseldi şu gönlüm 

İz iz güllere düştü

Gülü tanıyınca', 'Tanıyınca O gülü Tanıyınca onu sevmeyi öğrendim Gülü tanıdım Kim dese yalandır  Sevmedi Hamdi Veyseldi şu gönlüm  İz iz güllere düştü Gülü t...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Oruç']::text[], 8.5, '{"poet":"Hamdi Oruç","poet_slug":"hamdi-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/taniyinca-o-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-bahri-yildirim-yboip', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba yeni doğan Güneş

Işığa merhaba,sese merhaba

Mevsim bahar yazmış farketmez asla

Doğaya can veren güce merhaba

Sabah  kalkıp günaydınla uyanan

Günah,kusur neymiş ondan arınan

Bir tohuma bin bir çeşit can koyan

Ağaca merhaba,dala merhaba

Adaleti yüreğinde taşıyan

Haksızlığa,zulme hep karşı koyan

Barış diyen,sevgi diyen.hak diyen

Bir köşede kalmış kula merhaba

Doğruyu söyleyip doğruyu yazan

Sevda çeken,acı çeken bunalan

Her insandan ayrı ayrı haz alan

Oğula merhaba,kıza merhaba

Güzellik insanda,insansa güzel

Doğruyu yanlışı her insan sezer

Sezenler oturur bir şiir yazar

Ozana merhaba,söze merhaba

Okudum şiirim,yazdım romanım

Ben de bir faniyim,ben de insanım

İnanırım,insanlar iyi şeylere lâyık

Canlara merhaba,sana merhaba', 'Merhaba yeni doğan Güneş Işığa merhaba,sese merhaba Mevsim bahar yazmış farketmez asla Doğaya can veren güce merhaba Sabah  kalkıp günaydınl...', ARRAY['Türk Edebiyatı','Şiir','Bahri Yıldırım']::text[], 8.5, '{"poet":"Bahri Yıldırım","poet_slug":"bahri-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/merhaba-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimbilir', 'kimbilir-baris-kayar-ihqig', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'belkilerin içinde kayboldum

 belki bulurum diye kendimi

 kimbilir

 belki! ..', 'belkilerin içinde kayboldum  belki bulurum diye kendimi  kimbilir  belki! .....', ARRAY['Türk Edebiyatı','Şiir','Barış Kayar']::text[], 8.5, '{"poet":"Barış Kayar","poet_slug":"baris-kayar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kimbilir-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur oynasın, çal patlasın', 'vur-oynasin-cal-patlasin-mikdat-bal-apbtw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçten gülen yüz kalmadı

Mutluluktan iz kalmadı

Işıl ışıl göz kalmadı

Vur oynasın, çal patlasın

Akrabadır, ailedir

Görünüşte el eledir

Aklı fikri ne iledir

Vur oynasın, çal patlasın

Düğün, dernekler kurulur

Ne hâl, ne hatır sorulur

Bu insanlar ne yorulur! 

Vur oynasın, çal patlasın

Ne poz kalmış, ne de caka

Ne latife, ne de şaka

Alttan gizli, baka baka

Vur oynasın, çal patlasın

Şu düğün bitse de çıksak

Bu sefer bir şey takmasak

Kendi işimize baksak

Vur oynasın, çal patlasın

Yüz karanlık, göz karanlık

Kinayeli söz karanlık

Davul, zurna, saz karanlık

Vur oynasın, çal patlasın

Mikdat der ki işte düğün

Kalabalık, yığın yığın

Haset, nefret, kalpler yoğun

Vur oynasın, çal patlasın', 'İçten gülen yüz kalmadı Mutluluktan iz kalmadı Işıl ışıl göz kalmadı Vur oynasın, çal patlasın Akrabadır, ailedir Görünüşte el eledir Aklı f...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vur-oynasin-cal-patlasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca bir güneş o', 'koca-bir-gunes-o-hamdi-oruc-wvli4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kardeş bin güneş bana 

Kardeşim Selim öldü

Getirseniz razı değilim bin güneş bana

Dövünür  gönlüm

Hatırlayıp o günü

Şimdi güneş batarken  ufukta 

Gözlerin binası viran

Sanki  bir göçmen kuş ölüsü

Çığlık çığlık sılayı çağırıyor 

Sesinin binası viran

Bir balık 

Ağda çırpınıyor

Deniz dalgalarıyla emziriyor balığı

Dalgaların binası viran 

Baykuşlar gelir

Düştükçe binamın taşları...

Zamanın binası viran

Akıt gözüm kanlı yaşları

O çocuk için hep 

Bir çocuk ki adı kardeş

Bir çocuk ki adı güneş

Battı gitti o koca güneş

Ağlayanı hiç olmadı o  koca güneşin...

Hala ufkun binası viran', 'Bir kardeş bin güneş bana  Kardeşim Selim öldü Getirseniz razı değilim bin güneş bana Dövünür  gönlüm Hatırlayıp o günü Şimdi güneş batarken...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Oruç']::text[], 8.5, '{"poet":"Hamdi Oruç","poet_slug":"hamdi-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/koca-bir-gunes-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuhaf bişey', 'tuhaf-bisey-fidan-bulut-2z8io', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan güzelliklerin içinde de yaşarmış çirkini

Mutlu çehrelerde de boğuşurmuş yalnızlıkla

Hayatını dolduran huzur da cefa olurmuş meğer

Çiçek bahçesinde de yaşanırmış bozkır

Büsbütün eksiksiz yaşamakta da eksilebilirmiş

Var oluşuna inat yok olurmuş

Sevgilere boğulup sevgisiz kalır

Ruhu okşandıkça ruhsuzlaşırmış

       Ne garip...............', 'İnsan güzelliklerin içinde de yaşarmış çirkini Mutlu çehrelerde de boğuşurmuş yalnızlıkla Hayatını dolduran huzur da cefa olurmuş meğer Çiçe...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tuhaf-bisey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğreti...', 'ogreti-efsun-aydin-d68p4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayata dair her ne varsa yaşanacak,

Ve  bizler o hayatta yaşamak zorunda isek,

En koşuşturmalı anlarımızda farkına varamasakta,

Etrafımıza şöyle bir baktığımızda  seven gözlerle izleniyorsak,

Ve arkamızda güzel anılar bırakıp iyi insanları hayatımıza dahil ettiysek,

Belki tecrübe belki deneyim belki de HAYAT bu işte demek her zaman doğru olandır.', 'Hayata dair her ne varsa yaşanacak, Ve  bizler o hayatta yaşamak zorunda isek, En koşuşturmalı anlarımızda farkına varamasakta, Etrafımıza ş...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ogreti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bacalar', 'bacalar-akin-akca-oti9f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göğün yükselttiği dağın tepesinde bacalar 

var arkaplandaki kıpkızıl bulut geçişlerinin …

Orda biri var, ama ne insan, ne hayvan.

Bitki sever ve onu yer.

Su içer de ama üstüne.

Bilir, yağmur yağdığında ot üstüne, büyür orman.

Bir fazladan daha tetiklemeyi sever:

ve su içen bitkiyi yedikten

sonra bir bardak su içmeyi sever.

Böylece çıkarır ortaya gizil hışımını

Gölün Hanımefendisi’nin:

Sessiz karışımlar yine ışıldıyor.

Dev bacalar tütüyor; 

Eteklerdeki insanlar uyurken, çalışırken.

Nadiren durur bacaların tütüşü.

Böyle olduğunda, emekleyen sabahlarda

çalışmaktadır çiftçi insanlar.

*

Nexus’la Xaran, ölümsüzlüğe ulaşmak istemiş,

başaramamıştı; hayaller çünkü elde ettiği

gerçek değildi, bir uyuşturucuydu.

Bunun için su içti, ek olarak ‘su içen bitkiler’e

- mideye indirirken onları, Xoran.

Böylece gerçeğin sarmalı değişmedi:

Aynı dantel; Xoran olmuştu Xaran.

Ama zaten saran dokuydu; 

Kirk, öldüğü yerden kalkıp bu uçan

radyoaktif şeride sızmıştı

Xaran’ı durdurmak için.

*

Dağın eteğinde yaşamını sürdürenler ise 

bilmiyor bunu -sürdürdükleri yaşamların

keşmekeşinde yakınıp duranlar

- hala tek tük

işleyen bacalar sayesinde yaşıyorlar.

Nefes aldıklarında bakışıyorlar.

Bazılarıysa var ki yeryüzünde manen çokça,

Yaşarlar dağın da tepesininin yukarısında.

Hem bundan habersiz etekte çapalayanlar; 

Bacaların işleyişinden sorumlu dantelin

Ördüğü galaksi sarmalının dış kolundan da.

-

2. bölüm’de geçen Xoran karakteri ve Nexus, ‘Star Trek Generations’la alakalı

Sözü geçen bacalar; Bilim ve Teknik, Haziran 2005, s 41’deki bir resimden esin.', 'Göğün yükselttiği dağın tepesinde bacalar  var arkaplandaki kıpkızıl bulut geçişlerinin … Orda biri var, ama ne insan, ne hayvan. Bitki seve...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bacalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün 14.Temmuz', 'bugun-14-temmuz-efsun-aydin-v04nz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün içimde bir sızı var,

Yokluğun varlığınla çakışıyor ya işte,

Seni yok gibi göremem ki ben aslında.

Gözümün önünde durma artık n’ olur! 

Çektirme onca elemi çaresiz kalbime 

Sen nerde ve nasıl yaşarken umarsız kalabalığınla

Bir de sen söyle nicedir sensiz kalan günlerimde ki yanlızlığımı şöyle …

Tam şehrin göbeğine yazmıştım ayrılığı,

Ve kalbimin 12sinde ki yerini,

Tarih bugünün tarihiydi çok belli…

Sen bensiz kalmıştın yıllarca,

Ben hayata dair iyi olan şeylerin peşindeydim.

Bir koşuşturmayla geçiyordu zaman.

Seni tanıdığımda anlamıştım taa en baştan.

SEvginin yıllar sonra terk edeceğini bizi…

Bugün tarih yine o eski tarih…

Hani demiştin yaa sen

Bizim doğum günümüz olsun 14. Temmuz diye…

Doğum günün kutlu olsun

Ben bir yaş daha senlendim.

İşte bu da benim sana doğum günü hediyem olsun!', 'Bugün içimde bir sızı var, Yokluğun varlığınla çakışıyor ya işte, Seni yok gibi göremem ki ben aslında. Gözümün önünde durma artık n’ olur! ...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bugun-14-temmuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılacağım', 'ayrilacagim-durmus-karakus-yyltn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anladık güzelsin,bu nazın niye? 

Canımı verirdim bir damla sevgine

Kahredip  hayatın kahpeliğine

Birgün bu şehirden ayrılacağım.

Hep ben mi arayıp,hep ben mi soracağım

Hasretinle hep ben mi kavrulacağım

Anladım kaldıkça kahrolacağım

Birgün bu şehirden ayrılacağım.

Git gide büyüyor dertlerim acım

Dilim söylemesede kalbim davacın

Sen beddua etsende eller duacım

Birgün bu şehirden ayrılacağım

Üstüne yıkılsa evin,ocağın

hazana dönsede bağın bucağın

Kararlıyım fazla kalmayacağım

Birgün bu şehirden ayrılacağım', 'Anladık güzelsin,bu nazın niye?  Canımı verirdim bir damla sevgine Kahredip  hayatın kahpeliğine Birgün bu şehirden ayrılacağım. Hep ben mi ...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilacagim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle Aşkım', 'gule-gule-askim-akin-tekin-uhz44', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güle güle aşkım! ..

Gözlerinde güneşler olsun

ellerinde firari bir sevda...

Dimdik,mağrur bir komutan gibi

meydan okuyarak dünyaya

bastığın yeri sarsarak yürü! ..

Sana en çok bu yakışır çünkü...

Ve gittiğin her yerde

kanat sesleri duyarsan eğer

sakın dönüp bakma; 

O bir fırtınakuşudur,bil yeter...

Çok sıkılır bunalırsan

kaldır başını gökyüzüne bak

kılıç balığına benzer bir bulut göreceksin...

Ve ellerinde,ellerimin sıcaklığını duyacaksın...

Güle güle aşkım! ..

Güle güle...', 'Güle güle aşkım! .. Gözlerinde güneşler olsun ellerinde firari bir sevda... Dimdik,mağrur bir komutan gibi meydan okuyarak dünyaya bastığın ...', ARRAY['Türk Edebiyatı','Şiir','Akın Tekin']::text[], 8.5, '{"poet":"Akın Tekin","poet_slug":"akin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gule-gule-askim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim', 'memleketim-durmus-karakus-irj16', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensin esen rüzgarlara

Yaprak yaprak fısıldayan

Sensin yıldız gibi parıldayan

Gecemi aydınlatan ay

Kuşları sohbet edercesine

Dinlediğim ilkbahar

Nefes nefes ciğerime çektiğim

Sensin üzerimde yaşayıpta 

Kıymetini bilmediğimiz

Canım memleketim

Sen türkü türkü dillerde

Bir efsanesin gönüllerde

Sen salkım söğütlerin dalı

Sen arının petekteki balı

Sensin üzerine ismini yazıp

Özenle dokuduğum halı

Sensin bu gözlerimin

Pınar gibi akan yaşı

Sensin bu dört mevsimin

Yazı baharı kışı

Dünyalara değişmem

Sana bir tek bakışı

Sensin bize atamızın

En değerli mirası

Ta ezelden beri diktir

Eğilmez Türk''ün başı

Hep okundu susmadı

Suzmazda İstiklal Marşı

Çünkü sensin kalbimizin

Ay yıldızlı nakışı', 'Sensin esen rüzgarlara Yaprak yaprak fısıldayan Sensin yıldız gibi parıldayan Gecemi aydınlatan ay Kuşları sohbet edercesine Dinlediğim ilkb...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/memleketim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmazsa Olmaz Değil', 'olmazsa-olmaz-degil-cafer-tayyar-ozkan-4rzyw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne tadı ne tuzu kaldı yediklerimin

Maziye gıpta etti sevda denen gerçeğim

Bir yudum sevgiyi içemez oldu bedenim

Kaybolup gitti kaderin çarkında sevdiklerim

En tatlı özlemler dile gelirdi eskiden

Yokluğum ölüm, bensizlikse yaralardı derinden

Şimdilerde varlığımla yokluğum belli değil

Bir sevgi bile çok zor akar oldu dillerden

Dilersen bir gece ansızın gelebilirim

Hayatında görmediğin sevdayı yaşatabilirim

Sen yeter ki sevdiğini dile gönülden

Bir ömür boyu sinende yatabilirim

Olmazsa olmaz değil artık varlığım

Sardığın umutlarsa, benim son durağım

Sevgini yaşamak mahşere kaldıysa

Bilirim ki anılardaki sinen benim yatağım

Allah’ım yalvarıyorum ne olur al yüreğimi

Canımı alda herkes toprak bilsin bedenimi

Yaban ellere kalacak en değerli dileğimi

İçimdeki ukdemle koy kollarıma ne olur

25 Mayıs 2005 Ankara 13.30', 'Ne tadı ne tuzu kaldı yediklerimin Maziye gıpta etti sevda denen gerçeğim Bir yudum sevgiyi içemez oldu bedenim Kaybolup gitti kaderin çarkı...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olmazsa-olmaz-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönülmez Yollar', 'donulmez-yollar-zekeriya-yeniyol-56l6u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dönülmez yollarda kalınca; 

Ne sonu görünür,

Ne başı hatırlanır.

Ortasındasındır bir meçhulün...

Artık:

ya ilhamın kucağına bırakır seni acılar; 

Ya da 

Son bilinmez yolculuğun kapısına! ...

                                            25.12.04', 'Dönülmez yollarda kalınca;  Ne sonu görünür, Ne başı hatırlanır. Ortasındasındır bir meçhulün... Artık: ya ilhamın kucağına bırakır seni acı...', ARRAY['Türk Edebiyatı','Şiir','Zekeriya Yeniyol']::text[], 8.5, '{"poet":"Zekeriya Yeniyol","poet_slug":"zekeriya-yeniyol","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/donulmez-yollar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular', 'duygular-nihal-cinar-t7t1e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duygular

Korktuğum anlarda kaplumbağa gibi kabuğuma kaçarım çoğu zaman

Bir umutla, yada engelleyemediğim merak duygusu ile

''belki sandığım gibi kötü değildi bana uzanan el''deyip

Yeniden çıkarım kabuğumun dışına

Bazen öyle yoğundur ki acım,orda olduğunu bilsem de

Görmemek için deve kuşu gibi gömerim başımı kuma

Yiğitliğim tutmazmı? tutar elbet

Köşeye sıkıştımı kedi nin gösterdiği gibi bir cesaret

Av olmak yara almak hoş olsaydı

Ürkerek kaçarmıydı güzel gözlü ceylan,kendini korumaya alana dek

Bazen güzel hayallere dalar gökyüzünde uçan kuş olurum

Gerçeği görene dek

Bazen hamaratlığım tutar bir çalışırım bir çalışırım arı gibi

Her taraf bal börek

Ama çoğunlukta miskin miskin sürünen sümüklü böcek

Mazlumu savunmak gerektiğinde,kesin panter olmam gerek

''hep hayvan mı olunmalı? '' derseniz

O kadar kolay olmuyor,insan gibi İNSAN olmak', 'Duygular Korktuğum anlarda kaplumbağa gibi kabuğuma kaçarım çoğu zaman Bir umutla, yada engelleyemediğim merak duygusu ile ''belki sandığım g...', ARRAY['Türk Edebiyatı','Şiir','Nihal Çınar']::text[], 8.5, '{"poet":"Nihal Çınar","poet_slug":"nihal-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/duygular-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esrarengiz Birisi', 'esrarengiz-birisi-sebnem-sengun-ctse5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlık gecenin getirdiği esrarengiz biriydin

Gün geçtikçe vazgeçilmez oluyorsun.

Seni hep bir hayal gibi görürken

Hergeçen gün bana çok daha yakın oluyorsun

Karanlık gece her ne kadar korkutucu olsada

Senin gözlerindeki muzip pırıltı o geceyi aydınlatıyor

Söylediğin o tatlı sözler yokmu

Aklımdan bir an olsun çıkmıyor

Sana gün geçtikçe alışıyorum desemde ben

Alışmak kelimesi anlamsız kalıyor', 'Karanlık gecenin getirdiği esrarengiz biriydin Gün geçtikçe vazgeçilmez oluyorsun. Seni hep bir hayal gibi görürken Hergeçen gün bana çok da...', ARRAY['Türk Edebiyatı','Şiir','Şebnem Şengün']::text[], 8.5, '{"poet":"Şebnem Şengün","poet_slug":"sebnem-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/esrarengiz-birisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraz Ediyorum', 'i-tiraz-ediyorum-sebnem-sengun-dhus5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamın ötesinde

Kırılganlıklar peşimde

Ben bir kadınım desemde

Aslında ben bir kadın hiç olmadım.

Bedenim geçen senelere

Dur diyemesede

Nefesim zaman zaman tükensede

Aslında ben bir kadın hiç olmadım.

İtiraz ediyorum büyümeye

İtiraz ediyorum içimdeki çocuğu öldürmeye', 'Yaşamın ötesinde Kırılganlıklar peşimde Ben bir kadınım desemde Aslında ben bir kadın hiç olmadım. Bedenim geçen senelere Dur diyemesede Nef...', ARRAY['Türk Edebiyatı','Şiir','Şebnem Şengün']::text[], 8.5, '{"poet":"Şebnem Şengün","poet_slug":"sebnem-sengun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/itiraz-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Çocuklar!', 'hey-cocuklar-suleyman-saylan-ltatt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'HEY  ÇOCUKLAR! 

Hey çocuklar! Hey çocuklar! 

Önce sabah, sonra öğle,

Arkasından gelir akşam,

Karanlıklar çöker gece,

Bir gün böyle biter inan.

Hey çocuklar! Hey çocuklar! 

Yedi günle olur hafta,

Bir ay dolar dört haftayla.

Üç ayda bir mevsim gelir,

Dört mevsim var sırasıyla.

Hey çocuklar! Hey çocuklar! 

Mevsimlerin ilki bahar,

Yaz, sonbahar sonra kış var.

Boş oturmaz çalışırsan,

Mutlulukla geçer yıllar.

Hey çocuklar! Hey çocuklar! 

Hem çalışın, hem dinlenin,

Eğlenceye değer-zaman verin,

Başta gelir sağlığınız

Uykunuza dikkat edin.

Hey çocuklar! Hey çocuklar! 

Değerlensin geçen günler,

Kardeş olun hep beraber.

Zorlukları yenersiniz

Sabırla siz birer birer.

Hey çocuklar! Hey çocuklar! 

Hem sevilin, hem de sevin,

İnsan olmak zordur, bilin.

Güzel olsun bu dünyamız

Gelecekte dünya sizin.

Hey çocuklar! Hey çocuklar! 

Süleyman SAYLAN

İstanbul-Ankara yolu (varan bistro) , 27.03.1995, saat: 19.10', 'HEY  ÇOCUKLAR!  Hey çocuklar! Hey çocuklar!  Önce sabah, sonra öğle, Arkasından gelir akşam, Karanlıklar çöker gece, Bir gün böyle biter ina...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/hey-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne İstiyorum Biliyormusun?', 'ne-i-stiyorum-biliyormusun-ali-demir-96fj3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne istiyorum biliyormusun? 

Yakamozların pırıltısını seyretmek gözlerinde

Öpmek dudaklarından nefesim tükeninceye kadar

Sarmak sımsıkı kollarımla bedenini

Sabah oluncaya güneş doğuncaya kadar

Ne istiyorum biliyormusun? 

Sarhoş olmak hemde körkütük aşktan sevgiden sarhoş

Bir nefes sigara gibi çekmek ciğerlerime derin derin

Keşfetmek bilinmeyenlerini dünyanın el ele diz dize

Sabah oluncaya güneş doğuncaya kadar

Ne istiyorum biliyormusun? 

Kapanmasın kanasın gönlüme açtığın yaram

Seni hayal etmediğim geceler bana haram

Bitmesin bardakta çayım tükenmesin sigaram

Sabah oluncaya güneş doğuncaya kadar

Ne istiyorum biliyormusun? 

Bütün bunları düşünürken bir de yanımda olsan

Ah bir de yanımda olsan...', 'Ne istiyorum biliyormusun?  Yakamozların pırıltısını seyretmek gözlerinde Öpmek dudaklarından nefesim tükeninceye kadar Sarmak sımsıkı kolla...', ARRAY['Türk Edebiyatı','Şiir','Ali Demir']::text[], 8.5, '{"poet":"Ali Demir","poet_slug":"ali-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ne-istiyorum-biliyormusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Deprem,', 'i-cimdeki-deprem-suleyman-saylan-us753', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İÇİMDEKİ  DEPREM,

İlmek ilmek örüyor,

Ruhuma can veriyor,

Esir olmuş, eriyor…

   Mutluluk kapımı çaldı seninle,

   Takmışım aklımı güzelliğine.

Kalbim deli, divane,

Sevdi seni biçare,

Duysun eller, bana ne? …

   Kor oldum yeniden, küllenmişken ben,

   Kopuyor içimde azgın bir deprem.

   Süleyman SAYLAN

   İzmir, 19 Ağustos 2004, Saat: 18.40', 'İÇİMDEKİ  DEPREM, İlmek ilmek örüyor, Ruhuma can veriyor, Esir olmuş, eriyor…    Mutluluk kapımı çaldı seninle,    Takmışım aklımı güzelliği...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icimdeki-deprem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susa(r) mış Kirpikler', 'susa-r-mis-kirpikler-aycan-kose-dnx89', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“Susamış kirpikleri ve esmer teni var gözlerinin

Bak daha yeni uyandım bu şehirden der gibi.”

Ben seninle:

Eğer yaşarsam seni seviyorum biliyorsun

Eğer yaşayamazsam seni severmiyim bilemiyorum

Çünkü ben sensiz yaşamamayı bilmiyorum.

Çünkü ben seni ellerimle anlatıp gözlerimle dinliyorum

Bu sabah son defa yokluğunu ekiyorum içime

Artık varlığını çekmek istiyorum içime

Ve yazmak istiyorum soğuk yapraklara adını

Bütün nehirlerde yıkamak sonra,

Sonra dolunay örtsün üstümüzü.

Bütün güzel rüyalar içerisinde:

Sen bende kiracısın nehirdeki dallar gibi 

Ben sende ev sahibiyim akıntıya giden güller gibi

Seni taşıyorum

Beni taşıyorsun

İşte böyle olmalı aşkın tarifi

Ben senin mutluluk koydum adını

Unutma:MUTLULUK ve MUTLULUKLAR,

MUTLULUKLAR da MUTLULUK var

''Susarmış kirpikler, hiç konuşmazmış yüzü(n)   olmayınca.''

Belki de yağmur,

Kalbimde yağmur yada 

Biz  seninle yağmur olduk

Nöbet tutuyor avuçlarım ve 

Seni bekliyorum:

Hadi yağalım şu bencil şehre

Hazır mısın?', '“Susamış kirpikleri ve esmer teni var gözlerinin Bak daha yeni uyandım bu şehirden der gibi.” Ben seninle: Eğer yaşarsam seni seviyorum bili...', ARRAY['Türk Edebiyatı','Şiir','Aycan Köse']::text[], 8.5, '{"poet":"Aycan Köse","poet_slug":"aycan-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/susa-r-mis-kirpikler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Bir Deprem..', 'i-cimde-bir-deprem-suleyman-saylan-rlpvu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İÇİMDE  BİR  DEPREM..

Tohumlar patladı, çiçek taçlandı,

Seni gördüğümde dünya uyandı...

Aşkınla dopdolu oldum ben şimdi; 

İçimde bir deprem kalbim şahlandı.

Bir çift çağla göze fena bağlandım,

Sevemem sanırdım, aşkınla yandım.

Damarımda duygu yakıyor sandım...

İçimde bir deprem kalbim şahlandı.

Umurumda değil, ölmek vız gelir.

Gözlerine baksam, bana güç verir.

Aşığım sana ben, yüreğim erir...

İçimde bir deprem kalbim şahlandı.

Süleyman SAYLAN

Ankara, 22 aralık 1990  saat: 19.04    Şarkı sözü olabilir.', 'İÇİMDE  BİR  DEPREM.. Tohumlar patladı, çiçek taçlandı, Seni gördüğümde dünya uyandı... Aşkınla dopdolu oldum ben şimdi;  İçimde bir deprem ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/icimde-bir-deprem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En....', 'en-ugur-deniz-ulkegul-dq00u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '- I -

- En mavi -

Gözlerinle baktım oysa

Bu sabah Gökyüzüne

- Neden hiç uçurtma yok? -

Başımın üstünden geçip giden

Bulutları kıskandım yine

Tükenirdi zaman

Aşk''tı kanayan

Sızım çok

.....................................................

- II -

- En uzak -

Yolun sonunda bırakmıştım

Henüz geç kalmıştım oysa

Yüzüne

Nasılda tanıdık gelirdim

- Bir zamanlar -

Her düşüm şiir olurdu

Şairim mahpus, sevdam dört duvar

Sonunda yenildim yar...Yenildim...

Sözüne...

........................................................

- III -

- En Siyah -

Gecemde bir yıldız

Kayar gibi düştün

An/sızın

- Gülümdü -

Gövdem vuruldu

Gölgem düştü

Kurşundu

Namlusu kahpe bir

Kan/sızın

Hangisi ölüm dü? 

.........................................................

- IV -

- En Yakın -

Can yakan bakışların

Adı -gitmek- olan

Hükmü sabit

Tutanaksız, kimliksiz

Sorgulanan...

Sevdik biz

Öyle yazmışız

Okudum sevişmeleri

Bütün gece...

Sonradan farkettim

Sevdikçe

-Azalmışız-', '- I - - En mavi - Gözlerinle baktım oysa Bu sabah Gökyüzüne - Neden hiç uçurtma yok? - Başımın üstünden geçip giden Bulutları kıskandım yine...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/en-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncecik', 'i-ncecik-akin-akca-4bxpv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İncecik bir köprü var 

nöronlarından beynin, temeline.

Sorarlar sana duygusalken

niye epik yazmadın diye …

Her şey burada başlar, 

başlayan bir şey sona erer.

Ama sonuç alamayacak bir şey

de değildir ki eğer

o şey, sona ermeyecek 

olan, başlamamış ise.

Şimdi duyar gibiyim; 

zaten açıklamak istediğimi

açıklayamadığımı düşünüyor

gibisin. Ama yine de bazenleri

doğmuş olsak da, ve gidecek 

olsak da, asla bitmeyecek

bazı şeyler ve bunlar öyle şeyler

ki; duygunun yön verdiği

akılla irtifasını ufaltıyor

ayrılıkların verdiği acının.

Mangal düşünülenleri kaynatıyor; 

ortaya çıkanları al,

fokurduyor.

Fazla buharlaşan 

gene yağmur düşer.

Ve hayat böyle sona ermez.

Öz güdüsünde

başlamış olan bir başlamamış,

zaten bitemez.

Sen fikri sarmaladığında; 

düşün, yaka bırakmaz

duygu sağanaklarında.', 'İncecik bir köprü var  nöronlarından beynin, temeline. Sorarlar sana duygusalken niye epik yazmadın diye … Her şey burada başlar,  başlayan ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/incecik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kadeh Rakıya...', 'i-ki-kadeh-rakiya-suleyman-saylan-1n9hp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İKİ  KADEH  RAKIYA...

Bir dostun masasında dumanlanınca başım,

İki kadeh rakıya, onu Bodrum’da sattım...

Haklı bir tesellim var; zaten biraz yaşlıydı,

Yoksa öyle düşünüp kendimi mi aldattım? 

Kim kabahatli  bilmem, kim düzgündü çözmek zor,

Yakarsa diye korktum, o küllenmiş, yaşlı kor.

Yalvarsam bile artık geriye gelmesi zor...

Çözemedim, içimde bir devasa yarattım.

Bu dünyaya bir daha, tekrar gelecek gibi,

Gelsem bile yürekten sevebilecek gibi,

Belki  de beni benden çok sevecek birini

Hiç farkına varmadan eski bir pula sattım.

Pişman mıyım yoksa ben, şimdi bilemem amma; 

Bir düş gibi, sessizce girdi anılarıma.

Oysa nasıl sızmıştı  bomboş damarlarıma...

İki kadeh rakıyla belki aşkımı yaktım.

   Süleyman SAYLAN

   İzmir (Dalyan Plaza Hotel-Çeşme) , 

   28.08.2004, saat: 23.25   Şarkı sözü olabilir.', 'İKİ  KADEH  RAKIYA... Bir dostun masasında dumanlanınca başım, İki kadeh rakıya, onu Bodrum’da sattım... Haklı bir tesellim var; zaten biraz...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iki-kadeh-rakiya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemilerim', 'gemilerim-zuhal-aksulu-gu4lv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevda yüklü gemilerimi 

Hayat denen okyanusa saldım hep 

Öyle ağırdı ki gemilerim, sevdamla dolu 

Hepsi, dayanamadı bir bir battı 

Bakakaldım ben arkalarından 

Yetişemedim, kurtaramadım bir yudum bile sevgi... 

Son gemimi de uğurladım geçenlerde 

Açık denizlere 

Yine oluyor 

O da batıyor iste... 

Yok artık bundan sonra kimseye bir damla bile sevgi 

Yakıyorum bundan sonraki tüm gemilerimi...', 'Sevda yüklü gemilerimi  Hayat denen okyanusa saldım hep  Öyle ağırdı ki gemilerim, sevdamla dolu  Hepsi, dayanamadı bir bir battı  Bakakaldı...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gemilerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz', 'yaz-zuhal-aksulu-gotlg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gokyuzu kasvetli ve gergin

sevismenin oncesinde....

sevismenin oncesinde

yeryuzu bekliyor goge vurgun

sesleri birbirine karisiyor

her yildirimda

birden bir simsek cakiyor

gok zevkten yarilacak durumda

iste o muthis an geliyor

yagmur damlalari yerle bulusuyor

yeryuzu en hos kokusunu salmakta

gok yeryuzune bosalmakta...

sonra hersey duruyor

gokyuzu yorgun ve neseli

bir sigara yakiyor besbelli

gunes aciyor

tarlalara bakacagiz

toprak ana mutlu yagmurdan

bu sevismenin mahsullerini alacagiz

bir kac aya kalmadan...

06/06/1999', 'gokyuzu kasvetli ve gergin sevismenin oncesinde.... sevismenin oncesinde yeryuzu bekliyor goge vurgun sesleri birbirine karisiyor her yildir...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yaz-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin Yalnızlığım', 'hosgeldin-yalnizligim-zuhal-aksulu-4op7m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hoş geldin yalnızlığım 

Benim kara alın yazım 

Başaramadık değil mi yine ayrı kalmayı... 

Hoş geldin yalnızlığım 

Gel otur simdi yanı başıma 

Otur da sen de halime ağla 

Sevmek gibi bir günah işlemiş şu günahkarı 

Gel istersen sen de taşla... 

Hoş geldin yalnızlığım 

Hayat yolunda benim en sadık yoldaşım 

Hoş geldin 

Her şey bir bir giderken bari sen çok yaşa...', 'Hoş geldin yalnızlığım  Benim kara alın yazım  Başaramadık değil mi yine ayrı kalmayı...  Hoş geldin yalnızlığım  Gel otur simdi yanı başıma...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hosgeldin-yalnizligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımın En Kısa Gerçek Aşkı', 'hayatimin-en-kisa-gercek-aski-zuhal-aksulu-sd75n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatimin en kısa gerçek aşkı 

Bir kus kanadını çırpmadan 

Yağmur damlası çatıya çarpmadan 

Daha ben sana, sen bana, biz kavuşmadan 

Başladı ve bitti iste 

Biz bu yolda hiç savaşmadan....', 'Hayatimin en kısa gerçek aşkı  Bir kus kanadını çırpmadan  Yağmur damlası çatıya çarpmadan  Daha ben sana, sen bana, biz kavuşmadan  Başladı...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hayatimin-en-kisa-gercek-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enayi', 'enayi-zuhal-aksulu-p9p7e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasıl anlatacağımı bilmiyorum 

Kelimeler yetersiz gelecek 

Bir enayi daha var midir bu dünyada 

Seni benim kadar sevecek 

Sen ki kalbimin derinlerinde yaralar açmışsın 

Sen ki beni kendini bilmez divane sanmışsın 

Sen ki gözümü açıp beni hayata bağlamışsın 

Allah’ım bu kulunu sen ne güzel yaratmışsın...', 'Nasıl anlatacağımı bilmiyorum  Kelimeler yetersiz gelecek  Bir enayi daha var midir bu dünyada  Seni benim kadar sevecek  Sen ki kalbimin de...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/enayi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Yazmak', 'siir-yazmak-zuhal-aksulu-2wii9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün bir yerde okudum 

Şiir şeytan işiymiş 

Ne yapayım? 

Şiir yazdıran sevgiymiş... 

Ben seni sevdiğim müddetçe 

Yani sonsuza kadar 

Şiir yazacağım 

Şeytana uyacağım... 

Sen ki beni öldüren 

Sen ki beni görmeyen 

Sen ki beni sinir eden 

Adamı günaha sokar 

Yoldan çıkarttırırsın... 

Ama razıyım ben 

Yoldan da çıkarım 

Şeytana da uyarım 

Değil mi ki seni seven ben 

Ben her şeyi göze alacağım... 

Ben seni sevdiğim müddetçe 

Yani sonsuza kadar 

Şiir yazacağım 

Şeytana uyacağım 

Varsın olsun yakışıklım 

Cehennemde yanacağım...', 'Bugün bir yerde okudum  Şiir şeytan işiymiş  Ne yapayım?  Şiir yazdıran sevgiymiş...  Ben seni sevdiğim müddetçe  Yani sonsuza kadar  Şiir y...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/siir-yazmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güllerin En Kırmızısı Solarken Ellerimde', 'gullerin-en-kirmizisi-solarken-ellerimde-zuhal-aksulu-u7whi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güllerin en kırmızısı solarken ellerimde 

Kırmızısı süzülüyor kalbimden 

Dikenlerinin batti yerden... 

Aşkim bu aşk bitmiş gibi görünse de 

Ben asla vazgecemem senden...', 'Güllerin en kırmızısı solarken ellerimde  Kırmızısı süzülüyor kalbimden  Dikenlerinin batti yerden...  Aşkim bu aşk bitmiş gibi görünse de  ...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gullerin-en-kirmizisi-solarken-ellerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Üç Nokta...', 'uc-nokta-zuhal-aksulu-lzqve', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '...

Noktalarım tükendi artık

Sonu hep ünlem işareti yaşadıklarımın

Virgülsüz geçen bu hayatta noktaladım ben herşeyi

Elimde avucumda kalan tek şey bir sürü soru işareti

Daha cok sinirleneceğim

Belki daha çok şaşıracağım olanlara

Bolca bağırıp cağırıp küfredeceğim hayata

Sonunda ünlem işaretlerim de bitecek biliyorum

Yaşanacak birşey kalmayacak

Koyacağım üç nokta

...', '... Noktalarım tükendi artık Sonu hep ünlem işareti yaşadıklarımın Virgülsüz geçen bu hayatta noktaladım ben herşeyi Elimde avucumda kalan t...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uc-nokta-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanardağ', 'yanardag-zuhal-aksulu-r5kgu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüzyıllardır uykuda olan

Kızgın bir yanardağ gibiyim

Sessiz, sakin, verimli

Hatta yanına yaklaşılabilecek kadar sevimli

Ama işte aniden patlıyorum

Sadece kendimi değil

Etrafımdaki herkesi yakıyorum...', 'Yüzyıllardır uykuda olan Kızgın bir yanardağ gibiyim Sessiz, sakin, verimli Hatta yanına yaklaşılabilecek kadar sevimli Ama işte aniden patl...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yanardag-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu', 'suclu-zuhal-aksulu-tirsz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbim küt küt

Herşeyi hesaba çekiyor

Eller diyor

''Ben dokunmadım, dokunamadım''

Dudaklar ''tattım, doyamadım...''

Beynim diyor

''Neler oluyor? ben birşey anlamadım...''

Susuyor hepsi birden

Sadece kalp atışlarım sessizlikte

''Tamam neyse.. ben suçluyu bildim,

Hiçbiriniz suçlu değil

Suçlu benim, ben sevdim...''

Sonrasi sessizlik...

...', 'Kalbim küt küt Herşeyi hesaba çekiyor Eller diyor ''Ben dokunmadım, dokunamadım'' Dudaklar ''tattım, doyamadım...'' Beynim diyor ''Neler oluyor? ...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Aksulu']::text[], 8.5, '{"poet":"Zuhal Aksulu","poet_slug":"zuhal-aksulu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/suclu-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Never let me down again', 'never-let-me-down-again-akin-akca-qt84m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I''m taking a ride 

Bir sürüş alıyorum 

With my best friend 

En iyi arkadaşımla 

I hope he never lets me down again 

Umarım ki asla düşürmez bir daha beni 

He knows where he''s taking me 

O biliyor nerede aldığını beni 

Taking me where I want to be 

Aldığını, olmamı istediğim yerde 

I''m taking a ride 

Bir sürüş alıyorum 

With my best friend 

En iyi arkadaşımla 

We''re flying high 

Yüksek uçuyoruz 

We''re watching the world pass us by 

Bizimle geçip giden dünyayı seyrediyoruz 

Never want to come down 

Asla aşağıya inmek istemezsin 

Never want to put my feet back down 

Asla ayaklarını temele koymayı istemezsin 

On the ground 

I''m taking a ride 

Bir sürüşteyim 

With my best friend 

En iyi arkadaşımla 

I hope he never lets me down again 

Umarım ki asla aşağı bırakmaz beni 

Promises me I''m as safe as houses 

Söz verir bana güvenliyim ben evler kadar 

As long as I remember who''s wearing the trousers 

Hatırladığımca, kim giyiyor pantolonları. 

I hope he never lets me down again 

Umarım ki asla aşağı bırakmaz beni. 

Never let me down 

Asla düşürme 

See the stars they''re shining bright 

Görüyorum yıldızlar parlıyor parlak 

Everything''s alright tonight 

Her şey yolunda bu gece 

kendimce bir şarkı çeviri

depehe mode', 'I''m taking a ride  Bir sürüş alıyorum  With my best friend  En iyi arkadaşımla  I hope he never lets me down again  Umarım ki asla düşürmez ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/never-let-me-down-again-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılmasın Sakın', 'kirilmasin-sakin-suleyman-saylan-8s02z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KIRILMASIN  SAKIN

Ağaçta tüneyen kuşun yüreği,

Kalbimi ısıtan bir sevgi gibi...

Mutluluk çiçeğim gönülden narin; 

Kırılmasın sakın, dikkat et e mi? 

Kırılırsa eğer, toplanmaz geri

Yılları harcarsın boşu boşuna,

Çırpınır durursun aşkım uğruna.

Kırınca varırsın ancak farkına...

Kırılmasın sakın, dikkat et e mi? 

Kırılırsa eğer, toplanmaz geri.

İhtiras uğruna kalpler kırarsın,

Bir hiç için bile gönül yıkarsın.

Kaybettiğin zaman belki anlarsın...

Kırılmasın sakın, dikkat et e mi? 

Kırılırsa eğer, toplanmaz geri.

Süleyman  SAYLAN

Ankara, 08.12.1993 saat: 09.13   (Şarkı sözü olabilir.)', 'KIRILMASIN  SAKIN Ağaçta tüneyen kuşun yüreği, Kalbimi ısıtan bir sevgi gibi... Mutluluk çiçeğim gönülden narin;  Kırılmasın sakın, dikkat e...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kirilmasin-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşere Kaldık', 'mahsere-kaldik-suleyman-saylan-czyyf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'MAHŞERE  KALDIK

Şimşekler çakardı seni görünce,

İçimde ateşin sönüyor artık...

Bekleye, bekleye yiten günlerde,

Kalbimde arzunla hasrete kaldık,

Uzaktan sevmeyi yeterli sandık...

Seni çok sevdim ben, söyleyemedim.

Belki sen de sevdin, belli etmedin.

Çok mu zor geldi ki, ümit vermedin.

Kalbimde arzunla hasrete kaldık,

Uzaktan sevmeyi yeterli sandık...

Üstü küllense de, sevdan yakıyor,

İçimde bir his var, sana tapıyor,

Senin kalbin korkak, aşktan kaçıyor.

Sen bana, ben sana, mahşere kaldık,

Uzaktan sevmeyi yeterli sandık...

Süleyman  SAYLAN

Ankara, 27.11.1991 saat: 23.40   (Şarkı sözü olabilir.)', 'MAHŞERE  KALDIK Şimşekler çakardı seni görünce, İçimde ateşin sönüyor artık... Bekleye, bekleye yiten günlerde, Kalbimde arzunla hasrete kal...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mahsere-kaldik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kredi Kartı', 'kredi-karti-muharrem-cetinkaya-0erf1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'En zor zamanımızda yetişir,

Muhannete muhtaç etmez.

Geciktirirsen; 

O’na güç yetmez.

Bir de  ödeyemezsen,

Allah affeder,

O affetmez…

.

Dürter bizi,

Yumuşacık elleriyle.

Gülümser,

Hep,

Son ödeme günü hariç…

Hesapta olmayan şeyler alırız,

Arkamızda koskoca

………..var! 

Ödeme günü gelince,

Canımız yanar,

Faizler,diğer giderler vs vs….

Arkamızda………….

…………var! 

.

Sanki; 

Biz toz şekeriz,

Onun yanında,

Eritir bizi.

Ona göre çok tatlıyız,şekeriz,

Biz ise yok oluruz,

Çoğumuz almadığı maaştan çekeriz.

O bizi eritir,

Ağır ağır,

Bir kaşık suda…

.

Nasıl olacak halimiz,

Biz bu işe gebeyiz…

Dokuz doğururuz her seferinde,

Tanımayız dokuzunu da…

Anlayacağınız dostum; 

Biz bu işin o…..suyuz,

Koynumuzda taşıdıkça,

Her zaman hamileyiz.

Üstelikte; 

Hem gebe,hem ebe,

Hem bebeğiz! ...

.

Aman sakın ha; 

_ödeyelim borcumuzu,

İhmal etmeyelim.

Ödeyemedik diye de; 

_boğazdan atlayıp,

……kefensiz gitmeyelim! ...', 'En zor zamanımızda yetişir, Muhannete muhtaç etmez. Geciktirirsen;  O’na güç yetmez. Bir de  ödeyemezsen, Allah affeder, O affetmez… . Dürte...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/kredi-karti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-oğul!', 'a-ogul-mikdat-bal-z75ey', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oğul

Güvenme gücüne bu senin değil

Alınır elinden, düşersin oğul!

Her şey Allah’ındır, kimsenin değil

Sırrına erince şaşarsın oğul!

En ufak tasarruf yoktur insanda

Emanettir her şey beden de can da

Sana hayat veren kalbin de kan da

Kalp durur kan donar şişersin oğul!

Allah’a teslim ol Hak yoldan çıkma

Hesabı sorulur, bir gönül yıkma

Mağrur bir edayla, tepeden bakma

Haddini bil sen bir beşersin oğul!

Bir belaya çatıp hapse girmeden

Kendine, çevrene hasar vermeden

Dostça ikazımı hafif görmeden

Sen bu badireyi aşarsın oğul

Geniş olan dünya kimine dardır

Her şeyin sayısız hikmeti vardır

Sabredersen başa gelenler kârdır

İmtihan güzeldir pişersin oğul

Mikdadi dünyada her şey geçici

Hayır yolda kullan, sende ki gücü

Hicreti sorarsan hayra et göcü

Artık insan gibi yaşarsın oğul!

Şair Mikdat Bal', 'Oğul Güvenme gücüne bu senin değil Alınır elinden, düşersin oğul! Her şey Allah’ındır, kimsenin değil Sırrına erince şaşarsın oğul! En ufak ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ogul-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '... Sen Hürsün.', 'sen-hursun-suleyman-saylan-acg9k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '... SEN  HÜRSÜN.

Güle güle sevgilim,

Unut artık sen beni.

Tüm ömrümü verdiğim,

Unuttum gül tenini.

Yüreğimde yarasın,

Bırak kalbim kanasın.

Tüm ömrümü verdiğim,

Sevdiğini arasın.

Sönsün yıldız, ay sönsün.

Arzum gitsin düş görsün.

Tüm ömrümü verdiğim,

Unut beni, sen hürsün.

Süleyman  SAYLAN

Ankara, 23.11.1990, saat: 23.23', '... SEN  HÜRSÜN. Güle güle sevgilim, Unut artık sen beni. Tüm ömrümü verdiğim, Unuttum gül tenini. Yüreğimde yarasın, Bırak kalbim kanasın. ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Saylan']::text[], 8.5, '{"poet":"Süleyman Saylan","poet_slug":"suleyman-saylan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-hursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğma Bebek! ! !', 'dogma-bebek-mehmet-demir-atmali-tepyu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğma bebek doğma! 

Yetim kalacaksın...

Açma çiçek açma! 

Bir gün solacaksın...

Doğma bebek doğma! 

Doğarken ağlayacaksın,

Yaşarken ağlayacaksın,

Ölürken ağlayacaksın...

Doğma yetim doğma! 

Hakkını yiyecekler,

Çoculara kıyacaklar,

Kanlı savaşlar olacak; 

Hep çocuklar ölecek...

Doğma bebek doğma! 

Kaderin sürünmektir...

Hırkalara bürünmektir,

Herkesçe yerinmektir....

Ağlama bebek ağlama! 

Gözyaşın dökülmesin,

Yüreğim sökülmesin...

''Arş-ı Ala titremesin'',

Tanrı gazaba gelmesin...

Dalma bebek dalma! 

Hayali çok görürler...

Gülme bebek gülme! 

Gülmeyi çok görürler...

Ölme bebek ölme! 

Ölmeyi çok görürler...

Yalnız ve yalnız; 

Siyonistler gülecek...

Hümanistler(!)  gülecek,

Feministler(!)  gülecek...

Yine de çocuklar ölecek...

        20.2.1993', 'Doğma bebek doğma!  Yetim kalacaksın... Açma çiçek açma!  Bir gün solacaksın... Doğma bebek doğma!  Doğarken ağlayacaksın, Yaşarken ağlayaca...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/dogma-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir Yalnız Kaldı Bu Gece Bana', 'bu-sehir-yalniz-kaldi-bu-gece-bana-burcu-karakaya-xrd90', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu şehir yalnız kaldı bu gece bana...

Esen rüzgar sessiz ve sakin çaldı bu gece

Peceremi! ..

Sen miydin melek sessizce giren içeri.

Sigaramdan bir nefes çektim,

Yine sensizim.tek başıma...

Sadece cırcır böcekleri aşklarını yaşayan.

Şu saatte bilinmeyenlere öfkem...

Beni bağlayan bir yol.bir kol olsa keşke sana,

Safsın,tertemiz bir yürek...

Seni incitecekler diye ödüm kopuyor,

Kanıyorum...

Akıttığın göz yaşların

Göz bebeklerimi deldi...Çağlayanım...Ve yine

Bu şehir yalnız kaldı bu gece bana...

Seni bırakacağım diye sana korkuyorum,

O kadar korkak ve ürkeksin ki,

Kaçırmamak için çırpınışlarım.

Seni yüreğimde, en derinlerimde yaşadım

Tanıdığım ilk günden de önce...

B.B.B', 'Bu şehir yalnız kaldı bu gece bana... Esen rüzgar sessiz ve sakin çaldı bu gece Peceremi! .. Sen miydin melek sessizce giren içeri. Sigaramd...', ARRAY['Türk Edebiyatı','Şiir','Burcu Karakaya']::text[], 8.5, '{"poet":"Burcu Karakaya","poet_slug":"burcu-karakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-sehir-yalniz-kaldi-bu-gece-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Doğunun kızıdır', 'o-dogunun-kizidir-aydin-babayev-lowst', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şaire adamış ömrünü

Kıskanıyor herkesten kendi kendini

Yok sabaha umudu

Geleceğe bakışı kırık,

Tek tessellisi, sevdiği şairin sesi

Felsefeli şiirleri ve kolondan gelen suni nefesi.

Ama o sesde susuyor birkaç saat sonra

Yine ruhu ıssız bir kasabanın eski istasyonu gibi yapayanlız

Çaresi; uçmak hayallerde geçmişe

Görmek istiyor ebediyete kavuşmuş annesini bulanık zihni ile

Haram olmuş uykular

Geceleri anne diye bağırıp kalkmaktan

Mutluluk arıyor sigara dallarında

Onlarda nafile üç dakikalık

ve.... ve yine yanlızlık

İnanmıyor bir gün seveceğine

Zebbalı olup gelin göçeceğine

Nefretle bakıyor kainatın gerçeklerine

Kabullenmek istemiyor yaşadıklarını

Güvensiz yaşıyor yaşasa bile

Çünkü birini sevmiş

Gerçeği söylememişti

Çektiği acılar, o günlerin meyvesidir ona

O Doğunun kızıdır

Kürt dilberi

O doğunun kızıdır....', 'Bir şaire adamış ömrünü Kıskanıyor herkesten kendi kendini Yok sabaha umudu Geleceğe bakışı kırık, Tek tessellisi, sevdiği şairin sesi Felse...', ARRAY['Türk Edebiyatı','Şiir','Aydın Babayev']::text[], 8.5, '{"poet":"Aydın Babayev","poet_slug":"aydin-babayev","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/o-dogunun-kizidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek', 'bebek-durdane-demirkoparan-uwnlc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyaya neden geldin BEBEK

O fotoğraftaki senmisin

Annenin şefkatli kollarına nasıl da kurulmuşsun

Baban nerede? 

Küçük bir fotoğraf karesinde bile yok mu? 

Büyümeseydin BEBEK

Başına gelecekleri kimse söylemedi mi? 

Anlatmadı mı kimse

Hayatın acımasız olduğunu

Baban nerede BEBEK? 

Büyümüş kocaman olmuşsun

Annen fotoğraftaki gibi şefkatli kollarını açmış yine

Baban nerede? 

Öldümü? 

Ölmedi mi öyleyse nerede 

Böylesi daha acı değil mi? 

Acıdım sana BEBEK

Şimdi de hayatta tek başına mı kaldın bu hayatta

Hayatı taşımak zordur BEBEK

Kimse söylemedi mi? 

Niye geldin dünyaya BEBEK

Dünya kötü

Dünya acımasız

Annenin kanatları altına sığın

Dünya kötü BEBEK

Dünya acımasız

Keşke hiç büyümeseydin

Büyümeseydin BEBEK...', 'Dünyaya neden geldin BEBEK O fotoğraftaki senmisin Annenin şefkatli kollarına nasıl da kurulmuşsun Baban nerede?  Küçük bir fotoğraf karesin...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bebek-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıyorum Sana', 'aciyorum-sana-dilek-ozdemir-maj19', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acıyorum sana

açlık, lağımdan çıkmış bir fare gibi

kemirirken gövdeni

uzanamıyorsun ekmeğe

zehir midir acep diye

küçük şeylerin tanrısına dizçökerken

ve teslim olup kehanetlerine

yatarken kendi içinde hapisliği

taammüden sevgisel cinayetten hükümlü

bir de bakarsın ki güzelim

sen bir kambur gibi taşırken korkularını

ve düşünüp dururken hala kara kara

yürüyüp geçmiş hayat sürtünerek omuzuna', 'Acıyorum sana açlık, lağımdan çıkmış bir fare gibi kemirirken gövdeni uzanamıyorsun ekmeğe zehir midir acep diye küçük şeylerin tanrısına di...', ARRAY['Türk Edebiyatı','Şiir','Dilek Özdemir']::text[], 8.5, '{"poet":"Dilek Özdemir","poet_slug":"dilek-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aciyorum-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-durdane-demirkoparan-ifzuj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soğuktan buz gibi olup

Kollarının arasında uyumayı

Teninin kokusunu

Uzun ellerini

Gözlerini

Gözlüğünü

Sıcacık yatağını

Ter kokunu

Ve

Sadece bana ait olan dudaklarını

Özledim

Elimi uzatsam dokunabilirim sana

Biliyorum

Ama

Çok uzaksın bana

Çok özledim seni...', 'Soğuktan buz gibi olup Kollarının arasında uyumayı Teninin kokusunu Uzun ellerini Gözlerini Gözlüğünü Sıcacık yatağını Ter kokunu Ve Sadece ...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozledim-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktan Sevgili', 'uzaktan-sevgili-sait-muharrem-say-fjxkr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzaktan sevmeliyim ben,

Elindeki simidin dökülen susamlarını

Karşı kaldırımdan seyretmeliyim

Her yeni günde sana dair umutsuzluğum olmalı

Göz yaşların çaresizliklerin

Çok sık konuk olmamalı zihnime,

Ben seni hep güçlü hayal etmeliyim

En güzel halinde gelmelisin yanıma

Saçında rengarenk tokalar

Renklendirmeli beni geldiğinde

Kır soğuğun yüzüme vurmalı

Uzaktan sevmeliyim ben

Ellerinin yarısını da örten pardösün 

sana sevimlilik verirken

Karşı kaldırımdan seyretmeliyim seni.', 'Uzaktan sevmeliyim ben, Elindeki simidin dökülen susamlarını Karşı kaldırımdan seyretmeliyim Her yeni günde sana dair umutsuzluğum olmalı Gö...', ARRAY['Türk Edebiyatı','Şiir','Sait Muharrem Say']::text[], 8.5, '{"poet":"Sait Muharrem Say","poet_slug":"sait-muharrem-say","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uzaktan-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam olmak', 'adam-olmak-tevfik-karinca-6gt2u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bin kere çıkardılar benden beni bir adam etmedim

yüzüme vurdular ihanetlerimi dinlemedim

bilirmisiniz ben ağlarken hiç gülemedim

yaşım geçti yolun yarısını bir hayli

hani nerde beni anlayan sevgilim

dizginlemesem  kendimi

çizdiğim o anlaşılmaz profili

boşvermeden yaşamak istiyorum

mutluluk mu uzak ülke

hadi bir giriver de bak düşüme

nerede olursam olayım

bu gece soğuk,mevsim yaz

içimde bildik, sevgiden ayaz

beni gönül defterinden hem sil hem de yaz

bin kere çıkardılar benden beni bir adam etmedim

yüzüme vurdular ihanetlerimi dinlemedim

bilirmisiniz ben ağlarken hiç gülemedim', 'bin kere çıkardılar benden beni bir adam etmedim yüzüme vurdular ihanetlerimi dinlemedim bilirmisiniz ben ağlarken hiç gülemedim yaşım geçti...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/adam-olmak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Madam Butterfly', 'madam-butterfly-yildiz-yildiz-dwhj0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uçuramaz ki günahlarını.

Bir çift ipek kanadın hafifliğine

yükleyemez onca dünya yükünü...

Sığamaz dar alanlara da; sınır boylarının 

dikenli tellerinde yırtılır uçuşan hayalleri

Bu yüzden kelebek olamaz rüyada bile...

Halel gelmesin diye ipeğin tek teline

Yasaklı kozasının hapsinde

Bir tek gelincik yaprağından kanar da

ölüme yatar ipek böceği', 'Uçuramaz ki günahlarını. Bir çift ipek kanadın hafifliğine yükleyemez onca dünya yükünü... Sığamaz dar alanlara da; sınır boylarının  dikenl...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yıldız']::text[], 8.5, '{"poet":"Yıldız Yıldız","poet_slug":"yildiz-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/madam-butterfly-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Eşşek Destanı', 'bir-essek-destani-mehmet-demir-atmali-hlgw7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Sevmeyenin akibetine bak...

Bir gün Hüsso eşşeğini kaybeder,

İlan etmek için Cami''ye gider.

      İmam''dan ister kayıp ilanını,

      Hep düşünür Eşşeğin palanını...

İmamın hutbesi sevgi hakkında,

Bir soru yöneltir, sevgi şıkkından; 

    ''Ömründe hiç sevmeyeniniz var mı? 

      Parmak kaldırsın, bir görelim zor mu? ''

Biri kalktı; ''hocam ben hiç sevmedim,

Sevenim olmadı, ben de sevmedim.''

     Eşşeği kaybolanı çağırdı İmam; 

   ''Gel; senin Eşşek bulundu, iş tamam.

Artık ilana gerek yok, insaf et! 

Şimdilik bu Eşşek''le idare et...''

     Kulağından teslim etti adamı; 

    ''Dişine bak, belli olur kıdemi...''

Sevmeyene haktır bu muamele,

Sevmeyeni düşürürler bu hale...

     Sakın! hiç sevmedim, demeyin sakın! ...

     Önce bir güzelce etrafa bakın...

Eşşeğini kaybeden biri olur; 

Sevmeyeni hemen gözünden bilir...

4.8.1994', '-Sevmeyenin akibetine bak... Bir gün Hüsso eşşeğini kaybeder, İlan etmek için Cami''ye gider.       İmam''dan ister kayıp ilanını,       Hep d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-essek-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimle Çatıştım, Kazanan Siz mi Oldunuz?', 'kendimle-catistim-kazanan-siz-mi-oldunuz-ahmet-turan-altunsu-4brz3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sahi! .. neydi biz şairlerin, 

siz “neme lâzımcı türevler” den farkımız? ... 

siz zaten silahlarınızı kuşanmıştınız; 

biz demet demet karanfil,

biraz da sivrice bir dil! ..

aramıza sıkışmış bir sessiz “yığın”,

hakim felsefe: YAŞASIN KÖTÜLÜK! ..

siz o zaman kazanmıştınız! 

biz, dolu tarafı bardağın; 

siz yudumladınız, 

-biz 

-azaldık 

-her yudumda! ..

beklerken yanlış yaptık 

içimizde yaşarken bunca sülük! 

bana şiir gelmesin! 

kahırlar, 

-denk tutulup 

-yüklenmesin omzuma,

gelmesin bana esin! 

bana ne, insanların aymazlığından,

üç kâğıdından, 

-yalanından, 

-dolanından,

bölüp parçalamasından / talanından? ..

kimsenin derdi beni germesin! 

gelmesin bana esin! 

bana şiir gelmesin! 

iki büklüm, deve boynu bir yürek,

ipotek konulmuş bir irade,

iğdiş edilmiş bir gelecek,

iğfal edilmiş ülküler…

ve neler, neler….

gelip ne etsin şiir? 

bunca çirkeflik içinde

kendini mi kirletsin şiir? ..

bana şiir gelmesin,

gelmesin bana esin! 

çekilip inzivaya

-bir köşede sessizce

-ruhumu dinlemeliyim…

ve ardımdan,

-ervahıma yapılan

-küfürlerle serinlemeliyim! ..

gurur, onur hak getire; 

zevk alıp inlemeliyim! ..

bana şiir gelmesin,

bana gelmesin esin! 

………………14.07.2005 / Ankara

-Ahmet Turan Altunsu', 'sahi! .. neydi biz şairlerin,  siz “neme lâzımcı türevler” den farkımız? ...  siz zaten silahlarınızı kuşanmıştınız;  biz demet demet karanf...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/kendimle-catistim-kazanan-siz-mi-oldunuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dardayım', 'dardayim-mehmet-bicik-0ebl0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Olmamak için nâmerde muhtaç,

Duymamak için başkalarına ihtiyaç,

Çalışmayı edindim kendime amaç,

Yine de başaramadım, dardayım…

10 Kasım 1994, Kumkapı', 'Olmamak için nâmerde muhtaç, Duymamak için başkalarına ihtiyaç, Çalışmayı edindim kendime amaç, Yine de başaramadım, dardayım… 10 Kasım 1994...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dardayim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Afganistan', 'afganistan-rabia-deveci-qi8jc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağlanır dünyaya el

Ölüme evlat büyüten ana

Gelsen geceye türkü söylet

Ve öyle çağır ki beni

Kaldırıp ırmakları yatağından

Dağlara kaçıralım…

Sulansın bozkır… 

Gelin olmamış gelincik

Bir tek yeşile yakışır

Beyaz neyine…! 

Bozkır incinir en çok

Orda karanlık

Burada gece

Gene yatağım dar

Kasım – 2001', 'Dağlanır dünyaya el Ölüme evlat büyüten ana Gelsen geceye türkü söylet Ve öyle çağır ki beni Kaldırıp ırmakları yatağından Dağlara kaçıralım...', ARRAY['Türk Edebiyatı','Şiir','Rabia Deveci']::text[], 8.5, '{"poet":"Rabia Deveci","poet_slug":"rabia-deveci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/afganistan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm - 2', 'olum-2-elazigli-mustafa-kaya-tuszy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir eskimiş  fotoğraf  benimkisi

bir  kırgın  gönül  bendeki

sararmış kenarı resmimin

sararmışım  öyle mi..? 

bu  ben miyim..

bu ben miyim..

bir ayağı kabirde bedenim

bir ayağı fotoğrafdaki resmim

ben eskidim..

ben eskidim..

beni ölüm güzelleştirir

beni ölüm sevecektir

alsın beni ölüm

beni bir çınar altına gömün..

                                                        

10.07.2005 / ç.köy', 'bir eskimiş  fotoğraf  benimkisi bir  kırgın  gönül  bendeki sararmış kenarı resmimin sararmışım  öyle mi..?  bu  ben miyim.. bu ben miyim.....', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olum-2-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıklar Olsun', 'yaziklar-olsun-salim-erben-vai16', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güldürmedin son günümde

Diz çöküp yalvarttın önünde

Yaklaşma rahatsızım dediğinde

Sokuldum yanına yazıklar olsun

Çok mu seviyordum bilmem ki

Aksın göz yaşlarım silmem ki

Sensiz şu dünyada gülmem ki

Bensiz gülersen yazıklar olsun

Tutmadın elimi neden niçin

Suçladım kendimi taptığım için

Tutup elini öptüm dudağından

Yazıklar olsun öptüğüm için

Okşadım saçlarını koklayarak

Gözyaşlarımı kendime saklayarak

Dökülüyorum sanki yaprak yaprak

Gazel olup savrulursam yazıklar olsun', 'Güldürmedin son günümde Diz çöküp yalvarttın önünde Yaklaşma rahatsızım dediğinde Sokuldum yanına yazıklar olsun Çok mu seviyordum bilmem ki...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaziklar-olsun-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tezatlar Ülkesi', 'tezatlar-ulkesi-mehmet-demir-atmali-tqhrq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir varmış, biri de yokmuş,

Bir ''Tezatlar Ülkesi'' varmış...

     Aç''ı çok aç, içler acısı...

     Onbeş defa gider hacısı...

Çoğunluğu sözde Müslüman,

Soyun bilmez, soyuna düşman...

     Anası örtük, kızı sürtük; 

     Kızı örtük, anası sürtük...

Rüşvet, zina, faiz can yakar.

Tele kanaldan lağım akar...

     Hayır bereket  uğramazmış,

     Şükür kanaat hiç yazmazmış...

Doğru insanlar, yanlış yerde; 

Yanlış insanlar, doğru yerde...

     İşler ehline verilmemiş; 

     Böyle ülke görülmemiş...

Kafanın dışına bakarlar; 

Baştaki örtüye takarlar...

     Siyasisi Seyis''e benzer; 

     Yalancısı Deyyus''a benzer...

Biliniz bu ülke neresi? 

Ülke Manukyan''ın ülkesi...

   18.9.2000', 'Bir varmış, biri de yokmuş, Bir ''Tezatlar Ülkesi'' varmış...      Aç''ı çok aç, içler acısı...      Onbeş defa gider hacısı... Çoğunluğu sözde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tezatlar-ulkesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar Bırakıyoruz Geride', 'cocuklar-birakiyoruz-geride-humeyra-yilmaz-9sryi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çocuklar bırakıyoruz geride 

gözleri yaşlı 

ellerinde kan kırmızı acılar 

yüreklerinde sorgusuz kurşunlar 

ölüm yazıyor alınlarında 

yaşanmamış renkli karanlıklarla 

çocuklar bırakıyoruz geride 

şafak kızılı tenlerinde 

güneş yanıkları

yağmur delikleri

ve babasından arta kalan intikamın 

inadına soğuk, inadına sahipsiz izleri

çocuklar bırakıyoruz geride

adını sormuyor kimse

kimse bilmiyor yaşını 

kurşunlar kalem oluyor ama

yazamıyor barışı 

tarih defterinin 

ne başına ne de sonuna 

çocuklar bırakıyoruz geride 

annesinin ruhundan damlayan

bir yudum şefkati bulsa

dolanacak damarlarında hayat

ve özgür martılara kanat olacak yüreği

şimdi bilmediği, tanımadığı öfkenin cesaretini 

sürüyor yüzüne iki parmağıyla 

soyut mutluluklar resmediyor akıllara

çocuklar bırakıyoruz geride

uykuları gecenin karanlığına aç 

ekmediği umutları bahçeye muhtaç

oysa parmak uçlarında gidiyor 

adının yarın olduğunu bilmediği geleceğe

tırnak diplerinde kararıyor topraklar 

ve yasemin kokuyor ölümler

canlara damladıkça

çocuklar bırakıyoruz geride

elleri kolları bağlı 

omuzlarında kesik bir baş

sırtlarında dünya denen ağır taş 

belki de çaresizliğimizi bırakıyoruz geride

elimizden gelen sadece yürekten bir dua

ve iki damla yaş...!', 'çocuklar bırakıyoruz geride  gözleri yaşlı  ellerinde kan kırmızı acılar  yüreklerinde sorgusuz kurşunlar  ölüm yazıyor alınlarında  yaşanma...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/cocuklar-birakiyoruz-geride-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönlüm', 'deli-gonlum-salim-erben-gry2s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vuramadım şu gönlümü zincire

Bazen ağladım bazen yalvardım

Sıktım dişimi ısırdım dilimi

Bazen sustum bazen bağırdım

Elimi oğuşturup kapadım agzımı

Zehir eti hem kışımı hem yazımı

Tıkadı kelimeleri sıktı boğazımı

Bazen ağladım bazen yalvardım 

Zalımın dizinde koymadın derman

Tükettin ömrümü hala uslanman

Dert bir değil hangisine yanam

Bazen dert verdin bazen derman', 'Vuramadım şu gönlümü zincire Bazen ağladım bazen yalvardım Sıktım dişimi ısırdım dilimi Bazen sustum bazen bağırdım Elimi oğuşturup kapadım ...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deli-gonlum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beter Ol Sanal Dünya', 'beter-ol-sanal-dunya-suheyla-kurnaz-mr3t8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beter ol sanal dünya

Zehir gibi girdin hücrelerimize

Panzehiri yok.

Virüs saldın beyinlerimize

Anti virüs programı yok

Elimizi verdik koldan olduk. 

Sayende bin bir çeşit insan gördük...

Chat programları ful safhada,

Sabah akşam her çeşit insan dolu...

Kimi var monitör arkasında, 

Aslan kesilmiş küfür dolu

Kimi  var kamera  arkasında

Ar namus yok, kurmuş aşk okulu

Kimi var yalın dostluk kurmuş

Yalan,  riya menfaat kolu

Kimi aşklar var,  ihanet ve iftira sonu

Ehh… istisnasız olmaz

Arada bir kaç insan sevgi dolu,

Bu sevginin de nesli tükenecek eni sonu…

Kimi kaldı, kimi gitti listeden

Kalan sevgi ve dostluk adına kaldı

Giden aradığı aşkı bulamadı kaçtı

Kimi yaşça büyük ama,''''bana abi deme’''der

Kimi  sanki gelinlik kız, yaşını gizler

Eee vardır bunun arkasında başka hisler

Kimi yalan aşklarını kopya yapar aleni,

Kimi dedikodu yapar geleni gideni.

Hele birde dost deyip de düşman olanlar,  deme gitsin…

Yağ bağlamış göbecikler, esir olmuş beyincikler

Elif kocasını unuttu; sanal aşk derdinde,

Yusuf  hatunu unuttu, sanal kaçamak peşinde,

Gözün kör olmaya hatçeee

Sende oyun derdine, ocakta yemeği mi unuttun kız? ..

Hele bir de o 

İnternet cafelerdeki körpecikler yok mu? 

Defteri kalemi atıp, okulu unuttu.

Vah halimize vah içler acısı.

Öyle esir ettin ki bizi

Konuyu komşuyu, eşi dostu ve hatta çocuğu unuttuk

Git melun fare, çık şu beynimden

Kemirme yeter artik 

Her şeyimi aldın benden.

Yetmedi mi?

Kuru bir canım kaldı.

Simdi gözün onda mı? Git.

SuheylaKurnaz.com - Kişisel Web Sitem', 'Beter ol sanal dünya Zehir gibi girdin hücrelerimize Panzehiri yok. Virüs saldın beyinlerimize Anti virüs programı yok Elimizi verdik koldan...', ARRAY['Türk Edebiyatı','Şiir','Süheyla Kurnaz']::text[], 8.5, '{"poet":"Süheyla Kurnaz","poet_slug":"suheyla-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/beter-ol-sanal-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Çığlık…', 'sessiz-ciglik-dundar-sansur-itwsd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siz, hiç denizin ortasında yalnızlığınıza susadınız mı? 

Bağırarak şarkı söylediniz mi sessizce? 

Haykırdınız mı suskunluğunuzla? 

Yağmurları ıslattığınız oldu mu eylül düşlerde? 

Gömdünüz mü bugünlerinizi dünler mezarlığına? 

Yarınlara aldırmadan,      

Hatıralar sakladınız mı kanlı bıçaklı? 

Dosta sitem ettiniz mi dost yanınızdayken?

İliklerinizde hissettiniz mi kalabalıklarda yalnızlığınızı?   

Sahi siz hiç nefretinizdeki sevgiyi yaşadınız mı? 

Veya kendinizi terk ettiğiniz oldu mu müntehirlerde? 

İdam ettiniz mi duygularınızın çoğul halini bir çırpıda? 

Korsan yolculuklara çıktınız mı yoğun trafiklerde? 

Bir tutam sevgiyi özlediniz mi sevdalar ülkesinde? 

Gece kuytularında mehtapsız kaldınız mı ay ışığında? 

Sahi üşüdünüz mü hiç güneş ülkesinde aşk peydahlarken

Mutluluklar dilendiniz mi yıldızlardan

                                                   hüzünlü gecelerde? 

Yaşamın orta yerinde bir başınıza kaldınız mı hoyratça? 

Sahi siz dokunmadan,okşamadan,seviştiniz mi                     

yalanlarınızla,

             korkularınızla,

                      cesur korkaklığınızla,

                                             veya maskelerinizle? 

Bir kurşunla öldürdüğünüz oldu mu dünlerinizi? 

Peki ya kahkaha atabildiniz mi yalnız başınızayken? 

Ve herkes gülüyorken siz ağladınız mı, 

onlara aldırmadan yalnız başınıza?

Yok yok siz beni anlayamazsınız, çünkü bir ben bilirim

Şu güzelim hayatımın ne denli talan olduğunu…', 'Siz, hiç denizin ortasında yalnızlığınıza susadınız mı?  Bağırarak şarkı söylediniz mi sessizce?  Haykırdınız mı suskunluğunuzla?  Yağmurlar...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sessiz-ciglik-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezopotamya...', 'mezopotamya-dundar-sansur-zqszb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cudi’nin yüceliğindedir özlemler

Fırat’ın öfkesi gibi çağlar umutlar

Gabar’ın inadındadır hep mazi

Ve Dicle’nin sakinliğiyle akar  yaşam 

Faili meçhuldür mazi kırıklıklarının

Gözlerde saklanıverir sevdalar 

Bir kardelendir yarınlar boranlara inat

Ve Mezopotamya kokar tüm soluklar….

Dicle’yle Fırat’ın hasretidir sevdayla yürek

Ve bu coğrafya da Yasaklı bir şiirdir aşk, 

Amed’in surlarında saklıdır efsanelerin suskun dili,

Mardin’de bir kartal bakışıdır tarihin yağmalanan gözleri. 

Çolemerg’te kayıp kentlerin şahididir dağların koynunda   yatan isimsiz mezarlar…

Rıha’da İbrahim’ler doğar, güneş kızıl dağılır dört bir yana 

Sarsılan putların gölgelerinde gün açar yeni ufuklara

Şehri Çezire’de Kırmızı Medrese hala maviyi barındırır

Siyah demlerde,ebemkuşağı olur avlusunda renklerindili.. 

Ve Girikamoda  (Silopi)  yüreğidir Nuh’un gemisinden kalan Sevda çiçekleri,krizantem ve asminler, bağrında şairin…

Mitolojik tılsımlar peydahlanır günübirlik yaşamlardan 

Nemrut’un kutsallığına özenir

                                 Taze sevgiler…', 'Cudi’nin yüceliğindedir özlemler Fırat’ın öfkesi gibi çağlar umutlar Gabar’ın inadındadır hep mazi Ve Dicle’nin sakinliğiyle akar  yaşam  Fa...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mezopotamya-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olağan-Üstü Akşamlar', 'olagan-ustu-aksamlar-dundar-sansur-4zs9v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yitik bir sevdanın ardından hüzünlü şarkısını çalar, 

Buğulanmış bir güz mevsiminde

Sisli bir Doğu Akşamında radyolar.

	

Geceleri bir başkadır seni düşünmek, 

Sensizliklerde şehrimin,

Karanlık çöker şakaklarıma, çırılçıplak bir aydınlıkta,

Uzak köylerin çoban ateşleri görünür ufuklarda, 

Bakar bakar ısınırım,

Seni düşündükçe üşüyorum çünkü

Dağ eteklerinde avuntulara dönüşür 

Gözlerinin sıcak demi, 

Nafile bir umut mahmurluğunda kürek çekerim şafaklara,

Yastığım yorganım kâr etmez düşlerimi beslemeye

Kaç bin yıl oldu toplamıyorum onları,

onlar beni, 

             biz bizi.... 

Sırrına eriyorum sabahların gizemli demlerinde,

Şafaklarda, kaç bin kez güneşi doğurduk çocuk yüzlerde,

Çocukça düşleri savurduk rüzgarlara

Rüzgarlar savurdu yüzümüze, 

bayram sabahlarının taze demini.....

Ve kaybolduk o demlerde, 

dirildik binlerce kez derin hazların doruklarında...! 

Başı dik karşıladık idam sehpasında, 

göz yaşlarımızla besledik düşlerimizi....

Düşlerimiz onurla karşıladı canın canda yanışını.....

Yarınlara bıraktıklarımızın dünlere savrulan zamanları   yaşadık.....

Bir Doğu Akşamında, sessiz bir çığlık yükselir arşa,

Arş sarsılır, göçmen kuşlar uçuşur geri dönüşlerde,

Sana hiç bahsetmedim akşamlarımızdan.....

Evlere çekilen ürkek ve donuk yüzlerde ben vardım                                

	                                                         çünkü,

Bikes yüreklerin özlemi içlerine çekilişinde sen yoktun 

	                                                         çünkü, 

Olağan   doğmadım,

                        olağan yaşamadım çünkü.....

Olağan anılarım olmadı, 

                        olağan aşklarım hep zindanla bitti.....

Olağan şarkılarımı çalamadım, 

                        olağan ezgilerim yanıktı çünkü.

Kaç bin fidan tanıdım olağan ölümleri yaşamayan..... 

Ve kaç bin yüz tanıdım hiç olağan gülemeyen......

Çocukluğumda olağan oyuncaklarımı hep saklardım,

Gençliğimde ise olağan ve de sevda yüklü kitaplarımı,

Ben olağan duygunun anlamını bilmiyorum..... 

Senin gibi sevemiyorum, yeniden öğret bana 

Sevmenin olağan boyutunu. 

Hiç olağan sevişmelerim olmadı, bunu da öğret bana,

Dudaklardaki özgürce, kaygısızca öpüşleri..... 

Güneşler, olağan doğmadı benim doğumlarımda.

Uzatmalardayım, kaç asır oldu,

Sancılarım da, acılarım da, sevinçlerim de olağan değildi.

Doğu Akşamlarını anlatamadım sana olağan bir hisle,

Çünkü sen farklı bir gezegenin benden öte                                     

                                                               yaşamındaydın

Yaşamın da olduğunca olağancaydı benden öte, 

                                                       üstten öte yaşamlar. 

Sevgim çocukluğumda, sevgisizliğim de zindanda                   

	bırakılmıştı çünkü

Ne sevgiyi ne de sevgisizliği, 

                                     senin gibi olağan yaşamadım.

Ya benden bin yıl önceydi,

                               ya da benden bir gün sonraydı hep.

Beden dansını bilmem, 

                               ellerin dansını bilirim nasırlı akışlarda.

Ondan diyorum Doğu Akşamlarını anlatmadım sana,

Nasıl anlatılır? 

Onu da olağan bilmiyorum,

Ya seni ürkütürüm, 

                          ya da senden ürkerim. 

Dedim ya, bilinmeyende bilineni yaşamadım olağan.

Hadi! Sen anlat bana olağan akşamlarını,

                                              olağan sevgilerini, 

                                                 olağan sevdalarını, 

                                                     olağan anılarını anlat...

Olağan rüzgarların papatyalara nasıl renk verdiğini  anlat...

Ben, poyrazların uçurum çiçeklerine nasıl renk verdiğini    bilirim.

            Hadi! Anlat bana olağan sevişmelerin beden dansını,

Dudaklarım varsın hazzına

                              geçsin çatlaklığı bin yılların acısında…

Hadi! Anlat bana şehrini, 

Şehrindeki evlerde yanan milyarlarca olağan ışıkları,

Benim şehrimde ışıklar olağan yanmaz,

                                            dışıdır aydınlıklarım! 

Hadi! Anlat şehrindeki özgürce parlayan yıldızları.....

Nasıl görünürler oradan, onu da bilmiyorum.

Benim şehrimde baktığım yıldızlar hiç olağan kaymadı 

	                  çünkü…

Anlat hadi, bekletme beni, olağanlaştır beni kendinde

Benim seni olağan sevmemi bekleme,

Mülteci bir bakışın derinliğidir yalın sevmelerim,

Ya beni yeniden yarat,

                               ya da kal olağanlığınla..

Olağanlığı iki şeyde yaşadım gülüm,

Allah’ına kadar yürek dansım

                         ve çırılçıplak işkencelerim olağandı hep...

Hadi! Anlat bana umudun ikilemsiz profilini 

özgürlüğün çocukça düşünü,

Barışın koyu rengini 

Sevdanın melankolik boyutunu,

Şarkıların yasaksız ahengini, 

Şiirlerin sessiz çığlığını hadi anlat bana..... 

Ya anlat, 

          ya da beni bana bırak, 

                               olağanlaştıramadıklarımla kalayım….. 

Ya da git,

         belki başka bir zaman paranoyasında bulurum seni.

Olağanlığımla ve tüm çıplaklığıyla kucaklarım gözlerini  

	                                                              alev alev

Ama şimdi ya öğret,

                         ya da git sonsuzluklar ülkesine…. 

Sisli bir Doğu Akşamında radyo frekanslarından

Tropikal iklimlerin ılıman seyrinde,

Akdeniz’e, Ege’ye dönük olağan, şarkılar yankılanır.....

Ürkek yüzlerde,

                 çocuk kalabalıklarında

                                     ve de kurulan yer sofralarında

Umudun paylaşıldığı,

                        bir kulağın da dışarıya kilitlendiği,

Yüreklerin sus-pusluğuna pusuların kurulduğu evlerde…..', 'Yitik bir sevdanın ardından hüzünlü şarkısını çalar,  Buğulanmış bir güz mevsiminde Sisli bir Doğu Akşamında radyolar. 	 Geceleri bir başkad...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":120,"source_url":"https://www.antoloji.com/olagan-ustu-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda İklimi…', 'sevda-i-klimi-dundar-sansur-o6iky', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İkilemlerin  deltasıdır aslında aşklar

Gönüllerse veryansın eder durur yaşama

Bir tılsım gibidir anlık hüzünler

Öylesine yaşamanın acısıyla kıvranır beden 

Belki’lerin,

         mutlaka bir gün’lerin

                     ve illaki’lerin öfkesini taşır yürekler

Umuda dairdir hep hayaller 

                               anılarsa acıya… 

Bir bir yetişir mi ki o demli baharlar? 

O kardelenler mi büyür fırtınalarda, boranların ayazında? Filizler mi tomurcuk açar çorak topraklarda

Bir  ömür  tüketirsin sevda iklimlerinde 

Yürek olursun 

          aşk olursun 

                 yar olursun

                         canda can olursun

                                         ve yaşam olursun ….', 'İkilemlerin  deltasıdır aslında aşklar Gönüllerse veryansın eder durur yaşama Bir tılsım gibidir anlık hüzünler Öylesine yaşamanın acısıyla ...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevda-iklimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Peri Pembe Değildir', 'her-peri-pembe-degildir-volkan-yoruc-forzb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her peri pembe değildir

Uçması güzele işaretmidir

Yoksa gafletemidir

Her peri pembe değildir

Olmayan ülkelerdemidir

Hepsi sanki sihirlimidir

Şu bir gerçektir

Her peri pembe değildir

Ormanlar evlerimidir

Yoksa eğlencelerdemidir

Kaçı gerçekten gülümsemelerdedir

Lakin her peri pembe değildir', 'Her peri pembe değildir Uçması güzele işaretmidir Yoksa gafletemidir Her peri pembe değildir Olmayan ülkelerdemidir Hepsi sanki sihirlimidir...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-peri-pembe-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmeli...', 'gitmeli-dundar-sansur-5sr0i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu kentin ötesi yok

Bu yaşantının da

Bu günlerinde 

Gitmeli bu kentten

Gitmeli bu diyardan

Kaçmalı bu paradokslardan

Çıkmalı bu günlerden

Tez elden kurmalı yeni bir yaşamı

Yeni bir diyarda, 

yeni bir mekanda

Yeni bir doğayla

Aynı düş güzelliğinde…

Ve belki de yeni bir elveda’ıyla

Acının, nefretin tadındadır yaşam

Bir yüreğin burukluğundadır 

ve mısralar buram buram hüzündür

Dilin ucunda öfke, umut’sa  yarınsızdır. 

Dün, bugün, ötesi ve dünün ötesindeki yarın

Koskoca bir kentin nefretini yaşadım bugün

Her kaldırım taşı 

Her çay bahçesi

Her telefon kulübesi

                     Ve her neyse..

Bir kendime yanarım

Bir sevdama 

Bir de o güzelim düşlerin tazeliğine

Yaşamın o acı yüzünü 

Beynin bir köşesindeki

Saklı hançeri hissetim.

Meğer ne zormuş

Bir düşün

Bir yarının 

Bir yaşamın üstünü çizebilmek 

Ne zormuş katran gecelerin ihanetine 

                       acıyı yudumlamak ne zormuş…', 'Bu kentin ötesi yok Bu yaşantının da Bu günlerinde  Gitmeli bu kentten Gitmeli bu diyardan Kaçmalı bu paradokslardan Çıkmalı bu günlerden Te...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gitmeli-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Sokağı...', 'dus-sokagi-dundar-sansur-jga66', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir efsanedir yüreğimizde ektiğimiz yarınlara dair 

                                                                      düşlerimiz...

Sen gibi bir parıltıdır barıştan, aşktan yana,

Ehmed-i Xane’nin,  Melay-e Cezeri’nin divanlarında 

Otantik bir gizemdir bizim sevdamız..

Mezopotamya’nın mavi bakan esmer gecelerinde

Yakar alemi, yanar yürekler düşler mizanseninde

Sokağında düşlerin alevler yükselir arşa   

Parlak yıldızlardı gün ortası güneşe inat gülen yüzümüz, 

Günün ışıklarıyla gökyüzünden bize göz kırparlardı, 

Gönül kıyılarımızda doğan yıldızlar.

Uzatır ellerimizi  tutabilecekmişiz gibi oracıkta

Ama, bir o kadar da uzaktı yüreğimize

Her yakalayacağımızı sandığımızda  daha da uzaklaşırlardı,     

Düş sokağının büyülü havasında... 

Ve biz seninle soğuklar gibi yoksul.....

“Garip aşkın öyküsü” ilişmiş yüreğimize,

Hüzün bulutları sarmış sokağımızı, 

Sokağımıza saçlarının lavanta kokusu sinmiş      

Avuçlarında beslediğin düşlerin gizemi dolaşır.

Sensizliğin dayanılmaz çığlıkları yükselir arşa,

Ama, yine de umudumuz tükenmedi 

Hala gökyüzündeki yıldızlara bakarım...

Onlar da bana bakar nacizane bir edayla,        

Sesimi soluğumu kesen bu sensiz gecelerde, 

Düş sokağının efsunlu havasında... 

Mitolojik aşkların ruhu canlanır nefesimde

Açan direnç çiçeklerinin kokuları genzimi yakar,

Eylül düşlerde karanfilleri büyütürüm koynumda,

Nasıl da ağulu bir şarap içmiş gibi olurum... 

Nasıl da kan düşer göz bebeklerime...

Nasıl da göğsüme düşer deli sevdan...

Nasıl da solar şebnemler, papatyalar yokluğunda...

Nasıl da öksüz kalırım sensizliğin dehlizlerinde...

Geceler karanlık, sen ırak, aşklar dağınık           

“Her şey bitti” diye dalmışken maviliklere, 

Serin rüzgar okşar bedenimi usulca 

Bedenim tekrar canlanır düşlenen gözlerinin maviliğinde,

Her şeyin bitmediğini hissederim büyük bir umutla...

Umutsuz iklimlerin militanca haykırışında

Yasaklanmış bir ben varım, deli isyanlarda

Bir gürz yaratan Spartaküs olur yürek, bu demlerde

İhanete bayrak açılır, faili meçhul zamanlarda

Ve zindanda büyüyen bir kardelen olduk, 

Ama yılmadık özgür demlerde...

Hüznün  anlamsızlaşan derinliklerinde

Senle tazelediğim umutların umutsuzluğunda 

Ve zorbanın tüfenginde bir zeytin dalı olduk

Renklerin maviye çaldığı esmer gecede,

Geldik yalın ayak düşlerle düş sokağınıza...

Sokağınız sisli, bulutlu ve nemli bir akış

Kaldırımlarda sararmış anıların ayak izleri,

Duvarlarda aşklardan arta kalan buğulanmış gölgeler 

Tekrar aynı sokakta, aynı kaldırımda, aynı duvar dibinde

Elemli  saatler içimi sızlatır, hüznün sarısı yanı başımda,  

Yüreğim mavi, düşlerim mavi, akışlarım mavi, 

Sen, siyah ve -yokluğun rengi-...', 'Bir efsanedir yüreğimizde ektiğimiz yarınlara dair                                                                        düşlerimiz... Sen ...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/dus-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Geldin İki Gözüm…', 'hos-geldin-i-ki-gozum-dundar-sansur-ksrtx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Hazal''a''

Öteki coğrafyalara, apayrı yolculuklara bilet keserken

Bensel paradoksların sensel yanılsamaların orta yerinde 

Senleşirken ve sen benleşirken 

Sevdaya dair mısralar dudaklarımızın ucundayken 

Geldin,

Hoş geldin iki gözüm,

                      sol yanım, 

                              öfkem, 

                                 kardelenim,

                                     öteki yüzüm,

                                              öte düşüm,

                                                       yarınım, 

                                                          belki de dünüm. 

Ve en önemlisi de bugünüm,

                                  hoş geldin! 

Sözcüklerin çaresizliğine sığınır tüm aşıklar 

Gecenin orta yerine sofra kurar yasaklı şiirler 

Öpücükler ve sarılmalar… 

Bir yaşamın kırmızı ışığında dinlenir yaralı yürek

Bir aşk sevdaya dair bir çift göze sığınır bütün anarşik 

	   duygularla

Ve” belki”lerin umarsızlığına inat,

Avuçlarımda fideler, sevda fideleri 

Günübirlik sulanır gönül ateşiyle düne aldırmadan Bugünün farkındalığında ve yarının umarsızlığında Büyütülüverilir aşk…

Tüm yaşam kardelenleri bir gülümsemenin sıcaklığında

                                                                          keşfedilir 

Sınırsız coğrafyaların sınır tanımayan aşkların gazabına Uğramıştır bu yürek

“nerden inceliyorsa kopsun” muhabbetindedir gönül Yüreğin o faili meçhul müntehirlerini yaşar

                                                              yazgılara inat

Aşklar peydahlanmıştır yaşamdan

Hüznün de bir tadı vardır artık sevdanın da sevincin de 

Ve belki de ayrılığın da…! 

Mezopotamya’nın sınırlarını zorlar bütün düşler

Yüreğin, umudun yaşama dair mısralarına hapsolurum 

Bir gece vakti 

      

 Öylesine dalmaların

                    öylesine sözcüklerin 

                          yani “öylesine”lerin zindanlarına giriverir      

                                                                                      aşk! 

Ve duldalar çaresizdir artık

                                bu yürek

                                       bu düş

                                             bu baharlar 

                                                     bu güzler

                                                          bu cehennem

                                                                         bu…

en’lerine sınırsızlığına yanaşıvermişiz yurtsuz aşkların

yanıbaşımdasın 

              öfkemdesin,

                   yarınımdasın

                          anlamımdasın 

                                 ve en önemlisi de 

                                              yüreğimdesin 

 Hoş geldin iki gözüm hoş geldin…!', '''Hazal''a'' Öteki coğrafyalara, apayrı yolculuklara bilet keserken Bensel paradoksların sensel yanılsamaların orta yerinde  Senleşirken ve sen...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/hos-geldin-iki-gozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sordum Gecelerden', 'seni-sordum-gecelerden-salim-erben-t0s8c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oturdum çimenlerin üstüne

Elimde bir bardak çay

Bir sigara

Gökyüzüne baktım

Bir ay bir de yıldız

Bölük bölük göç eden

Parça parça bulutlara

Başı dumanlı dağlara 

Seni sordum

Ser verdi sır vermediler

Kara bulutların gözyaşına

Sel olup akışına

Şu Ankara''nın toprağına taşına

Seni sordum

Sordum geceleğin ay ışığına

Dört mevsimin yazına kışına

Kayıp giden gök taşına

Ser verip sır vermediler

Beni deli etme gel nolur

Nedesin Allah aşkına

Güler yüzlüm tatlı dillim

Buralar olmuyor sensiz

Olmuyor ki tek başına

Dağlardan taşlardan

Gözümdeki yaşlardan

Resimlerdeki bakışlardan

Pek nadir öten kuşlardan

Seni sordum söylemediler

Zalım der ki ben hep böyleyim

Derdimi ne sen sor

Ne de ben söyleyim

Çağır gel de hemen geleyim

Bırakma burda yapayalnız

Ben sensiz ne yaparım n''eylerim', 'Oturdum çimenlerin üstüne Elimde bir bardak çay Bir sigara Gökyüzüne baktım Bir ay bir de yıldız Bölük bölük göç eden Parça parça bulutlara ...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/seni-sordum-gecelerden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun.', 'suskun-dundar-sansur-5ihe0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kabarıyor hüznün suları çocukların gözünden

Ölürken bir yaşam güzlerin duldalarında… 

Ürkütülürken yarınlar yorgun düşer gece,

Eteklerine dökülür Cudi’nin bir bir yıldızlar, 

Sabır taşı zir ü zeber olur.

Kelepçelenmiş bir aşkın kanayan ellerinden

Kaç bahar daha suskun kalacak

Soluksuz kalan mevsimlerin kıyam çiçekleri? 

Örtülürken bir sevdanın üzeri zifiri karanlıkla

Kaç beden daha büyüterek can alacak? 

Suskun güneşin çiçekleri ne zaman boy verir bilinmez

Kan damıtılan  bir miladın suskun yüreğinden…

Talan edilen bir hayatın adı olur şerha,

Yoksa işin topla bütün ölümleri,

Suskunluğun işgal ettiği dünlerden. 

Kavganın ortasında adını yitirir hayat,

Cellatlara teslim edilirken  mimlenir gülüşler,

Uyanmaz sevgilim özgürlük

Acının kuşattığı  şehirlerden… 

Sevda da, kuşlar da gider yetim kalır türküler…

Bir sonun başlangıcına tanıklık eder şair

Ve suskunluğu bozan bir tek şiirdir artık 

Esir düşerken bir aşkın ketum çığlığı…', 'Kabarıyor hüznün suları çocukların gözünden Ölürken bir yaşam güzlerin duldalarında…  Ürkütülürken yarınlar yorgun düşer gece, Eteklerine dö...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/suskun-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşuyorum...', 'usuyorum-dundar-sansur-evg96', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kentin kaldırımlarına  yağarsın diye,

Bir bir dolaştım üryan karanlıklarda.

Daralan sokaklarda çıkmazlarımın ayak izleri vardı, 

Sırılsıklam bir sen yeridir artık yürek…

Hasret bulutları gibi toplanmış yer gök

Dağılmaz mı bu kasvetli zemheri, bu ayaz, 

Ruhumu kelepçeleyen bu kederli ezgiler, 

Yüreğimi çarmıha geren sensizliğin zincirleri,

Gülistana dönüşmez mi hiç bu perişan iklim,

Bitmez mi bu  sürgünlerim, çocuk tebessümlerinden… 

Bütün gece, bütün gün, senle bütünleşen ne varsa 

Sığdırmaya çabalarken bıçak yüzlü gözlerime, 

Ağır gelir bu kasvetli havalar, yaram deşilir yine 

Bağdaş kurarken buzul  şafaklarda yokluğun,

Yangınlar başlar -bu havalarda-

Tenime dokunacak, ellerime tutunacak, düşlerime ısınacak, 

Yüreğimde barınacak tüm mekanlar işgal yeridir  bu kentte.

Mülteci bir çocuğun bakışları gibisin üşürken umut! …', 'Kentin kaldırımlarına  yağarsın diye, Bir bir dolaştım üryan karanlıklarda. Daralan sokaklarda çıkmazlarımın ayak izleri vardı,  Sırılsıklam...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/usuyorum-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezopotamya’da Seni Yaşamak...', 'mezopotamya-da-seni-yasamak-dundar-sansur-2sfe8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mezopotamya’da Seni Yaşamak...    

Anlatamadım seni Fırat’a, 

o da sen gibi akar yüreğime derinden derine... 

Haykıramadım Cudi’ye seni, 

o da sen gibi çatar kaşlarını sevdama...

Sığdıramadım sevdanı Mezopotamya’ya, 

o da sen gibi isyanlarda ansızın... 

Durduramadım zamanı, 

o da sen gibi çeker gider saçlarıma yıldız bırakarak... 

Söyletemedim Zin’e seni, 

o da sen gibi saklar buseleri bir güne Mem''e... 

Gözlerimde Dicle, dudaklarımda senli türküler,

Ne zordur bilir misin be sevgili…

Mezopotamya’da seni yaşamak?         

O deniz gözlerin, pusu kurmuş uykuma apansız, 

Bir vaktinde gecenin senli anında haince...

Bilir misin pencerelere hayalini çizebilmek? 

Ayaz kışta tenimden akan buharlarla sensizliğe inat, 

Ne zordur yokluğuna dayanmak,

Gelecekten umutsuz geçmişlerde.seni aramak 

umutsuzluk ikliminde,

O kadar kolay mı sanırsın 

Mezopotamya’da seni yaşamak…

Ne zordur, bilir misin be sevgili…! 

Öyle zor ki; katran gecelere sormak seni böyle hoyratça...

Kara gölgelerde hayalini aramak ne zordur bilir misin? 

Poyrazlarda çırpınan yüreğim yüreğine eser seherlerde,

Nostaljik bir melodiye dönüşür rüzgarın o ıslık sesi,

Karışır sevginin avareliği deli başımda, 

dört dönerim sensizliğe. 

Sevgi istasyonlarında yalnızlığı oynamak

ne zordur bilir misin be sevgili

Mezopotamya’da seni yaşamak …

Bir çırpıntı duyulur karanlık sularımda, 

depremler geçiririm, 

Bulutlara dönüşürsün eteklerinde Cudi’nin, 

bulutlar sana dönüşür. 

Şimşekler çakar gözlerimde yağmurlara dönüşürüm,

Yağmurlar bana dönüşür 

Ve gökkuşağı olursun gözlerimde, 

Gözlerim gökkuşağı olur gözlerinde. 

Usul usul doğar güneşin 

sırılsıklamlığıma sıcaklık, sevdama can gelir.

Bir adım ötede ölüm,

Bir adım ötede kefen, 

Bir adım ötede hayalin sesi 

Hayallerimde sana kavuşmak... 

Kavuşma tutkusu; nefesimde nefesin, 

Yüreğimde sen, sen, sen, delicesine

ne zordur bilir misin be sevgili…! 

Mezopotamya da seni yaşamak...', 'Mezopotamya’da Seni Yaşamak...     Anlatamadım seni Fırat’a,  o da sen gibi akar yüreğime derinden derine...  Haykıramadım Cudi’ye seni,  o ...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/mezopotamya-da-seni-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara', 'yara-dundar-sansur-2dpoy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir hançer yarasının derinliğidir yalnızlık 

Kanayan bir tarihin gözlerinden 

Çarmıha gerilmiştir, takvimlerin 

Can çekişen mitolojik sayfaları

Dicle ve Fırat İştar’ a akar

Kızıllığında ironi bir akşamın

Seyrine bir tebessüm belirir, 

Silahların gölgesinde Mezopotamya’da 

Ateştir artık  yüreğin ve aşkın coğrafyası

Zincirlere vurulmuştur, aşka vurulan yüreğin dili

Prangaya vurulmuştur yarınlara uzanan umut

Yakılır, bütün aşkların arşivleri bir bir… 

Yok sayılmış 

                  Mem, 

                         Siyabend,

                                      Derweş…

Bir kez daha ölür 

                      Zin, 

                           Xêce 

                                   Âdulê…

Ve dinmez bir yaradır

Sevdanın kalbine saplanan 

                       bu yitik, 

                                   bu yetim, 

                                                 bu yok sayılış…', 'Bir hançer yarasının derinliğidir yalnızlık  Kanayan bir tarihin gözlerinden  Çarmıha gerilmiştir, takvimlerin  Can çekişen mitolojik sayfal...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yara-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Atölyesi', 'gun-atolyesi-mutlu-ayar-lbda0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzak gibi gözükse de Batı her ne kadar

                              Hiçbir Doğu uzak değil Elif’ten

Dal uzunsu bilgileri sıvadım öğleyin 

Kül gibi dağıldı akşama güneş, göğsünden 

Çıkartıp el fenerlerini ışığını sağdım hepsinin 

Tadını çıkarttım gündüzün sandık dibinden 

Ben hep denizleri kıskandım Elif’ten 

Anımsarım, demiştim bir gün gül öbeklerini 

Koklamayı severim ben bir çocuk elinden 

Eleştirdikçe bitmiyor o uzun saçları ki

Bitmiyor bir de bacakları çıkarınca geceyi 

Dün bir dekor yaptık yaşama Elif’ten 

O zamanlar kuru bir bahardı üzerinde 

ben onu sevdiğim kadar şiirime güvendim

Öylece yayılmıştı diğerleri güneşe ah ne keyif

Aldım bütün ayaklarımı ona gittim 

Türkçenin kuşlarıyla göğüne düştüm Elif...', 'Uzak gibi gözükse de Batı her ne kadar                               Hiçbir Doğu uzak değil Elif’ten Dal uzunsu bilgileri sıvadım öğleyin  K...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gun-atolyesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Giderken…', 'sen-giderken-dundar-sansur-duh3e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hazal''a

Ne kaldı geriye, acılarından  başka

Bir çölün orta yerine  bîkes  bıraktığın

Benden geriye ne kaldı; 

Bir balyoz vuruşuydu feleğin bana biçtiği

Çarmıha gerilen yüreğimdi, sen giderken

Kal diyemezdim, kalmazdın biliyordum

Çocuk gözleri gülüşün gözlerimde

Umutlarımı da götürdün, gece yarısı

Mezara dönüştürülen bedenimdi

Ayazdı, dudakları sözcüklerin 

Ölüm kusuyordu çıplak bir feryat, 

Duygularım, bir bir mızraklanıyordu 

Budanıyordu çarkı ayrılığın kıvıl kıvıl

Gidişinden beri kalan bir tek  uçurumdu

Ne kaldı geriye, toprağa düşen göz yaşlarımdan başka…

Yağmur da, eski yağmur değil bu kentte

Bir hançerin kalbe vuruşuydu gidişinin ayak sesleri…

Ne çare; yoksunluk anlatılmaz haldan anlamayana

Filizlenen acılarda, boy verir hüsran

Yanık bir türkü çalınır, bağrında şafağın

Parsellenen yarınlara gebedir; 

U-mutsuzluğun lal dili…

Yarasalarla izlenir, yasaklanan doğuşu güneşin

Ne kalır geriye, yoksa bu kente -nefes verişin-

Hüzün alır kaldırımlarda, yürür yetimliğim

İzleri de silinir bütün aşkların ketumluğu

Bir militan olur, ihanetlere uğrar bu yürek

Bileti kesilir bir hayatın, bir baharın,  bir yarının

Yoksan bu kentte kar düşer saçlarına çocukların...', 'Hazal''a Ne kaldı geriye, acılarından  başka Bir çölün orta yerine  bîkes  bıraktığın Benden geriye ne kaldı;  Bir balyoz vuruşuydu feleğin b...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-giderken-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Botan’ da Sevdalar Yanıktır Gülüm', 'botan-da-sevdalar-yaniktir-gulum-dundar-sansur-c00sf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben, çorak toprakların çöl kokan kıraç yaylalarında           

                                                                doğdum gülüm..

Nasırlıdır ellerim, uzattığın ellerinde izi kalır bir yaşam 

                                                              boyu çokça bilesin.         

Güneşler, doğduğun yerin güneşlerine benzemez, 

                                                             yakar adamı gülüm,

Dört mevsim dört dünya yanıktır tenim yüreğim gibi 

                                                                yanarsın bilesin...

Ben, akşamlarında fırtınaların koptuğu memleketin  

                                        şafaklarında doğdum gülüm...

Bilmem seherleri; hep poyraz, hep şimal eserim gözlerine,  

                                                          çatar kaşların bilesin.

Yıldızlar doğduğun yerin yıldızlarına benzemez; 

                                    adı umuttur, adı sevdadır gülüm...

Ufuklarında gecenin en aydınlık deminde pusular kurulur,     

          kayarlar bir bir (yıldızlar) , 

                        göremezsin bilesin.

Ben, eteklerinde kardelenlerin göğe yükseldiği toprakların 

                                               dağlarında doğdum gülüm... 

Mayındır, çıyandır, yılandır dört yanı “Gülün” zindandır, 

                                       ölümdür, koklayamazsın, bilesin.

Yasak bir tütün arzusudur yanaklarında düşlemek 

                                  bahar  tadında bir gamzeyi gülüm…

                                                          

Bir çocuk dudağıyla dokunabilmek gamzelerine ne zor, 

                                             can düşer çukurlarına  bilesin.

Ben, taşı yastık, döşeği toprak, yürekleri köz köz 

mangal insanların diyarında doğdum gülüm...

Tanımam kuş tüyü uykuları,

izi vardır yanık sevdaların uykularımda 

                                              kabustur rüyalarım bilesin…

Türkülerim ezgidir, özlemdir, sevdadır, 

Kerpiç duvarların ıssız kuytularında çalınır hep gülüm...

Hasretlik çokça işlenir nağmelerde, 

sürgünlere dönüşür, sana kavuşma tutkusu çalamazsın   

                                                                                 bilesin.

Ben, sevdaların mitolojik diyarı, 

medeniyetlerin mistik yatağı Mezopotamya’da doğdum 

                                                                                gülüm...

Nakış nakıştır Mem’in Zin’e destansı tutkusu 

Bir efsanedir dilden dile dolanan bir acı ayrılıktır,bilesin...

Arzularım, coşkundur  Hizil gibi deli,denizlere ulaşamam,

Denizler ulaşmaz bana boğulurum, gülüm...

Eteklerinde Cudi’nin yağmurlara dönüşürsün gözlerimde,

  filizlenir koynumda deli sevdan, bilesin.

Ben, ekmeği dört öğün,dört parça, dört bin yürek sevdayla paylaşılan mekanlarda doğdum, gülüm...

Alın teridir kavgamın adı, 

tanımam konforlu mekanlarda yavan lezzetleri, 

                                                   tuzludur ekmeğim bilesin.

Buğday sarısıdır umut, şafaklarında boy verir yaşam, 

avuçlarımda hep düşle gezerim gülüm...

Düşlerimde bereketli toprakların yaylalarında, seninle sonsuzluklarda olabilme aşkı yatar bilesin…

Ben, güvercinlerin duvarlarda silahların açtığı deliklerde yuva yaptığı Botan’da doğdum gülüm...

Sevmem sessizliği, mavzer sesleridir türkülerim, 

melodiler eşliğinde ecel ile dans ederim, bilesin.

Karanlık çöker şakaklarıma, zindanlarında 

Bırc-a Belek’in, 

       ay Dicle’ye, 

              sen yüreğime düşersin gülüm...

Mültecidir duygularım, iltica ederim gözlerine gökkuşağını bırakır, 

                         öylece yüreğine düşerim, bilesin.', 'Ben, çorak toprakların çöl kokan kıraç yaylalarında                                                                            doğdum gülüm....', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/botan-da-sevdalar-yaniktir-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme...', 'gitme-dundar-sansur-2hqks', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dizginlenemeyen kör talih uyanır 

Sığınacak yer bulunmaz kaçış

Dört bir yana ölüm fermanları yayılır

Kalem kırılır paranoyak meclislerde

Varoşları yakılır büyütemediğim yüreğimin

Sebebidir gidişin aşkların fermanına 

Yoksa gülüşlerin, yoksa dudaklarına dokunuş

Göç eder güneş, meçhul kıyılara…

Bulutlara dönüşür, eylül düşlerim

Öfke olur yağarım, bu kentin üzerine

Kepenklerine kilit vurulur İstasyonların

Matem yelleri eser vebası sarar şehri

Çıkışları tutulur sokakların bir bir 

Kaldırımlarda çıplak oynaşır rüzgar

İşgale uğrar, yüreği dipçiklenir bu kentin  

Bilenir bıçaklar, aman vermez cellatlar

Caddelerine kurulur üryan sehpalar 

Yer gök sarsılır, gadabımın şiddetinden 

Çocuklar ağlaşır perde arkasından 

Yıldırımlara dönüşür çığlıklarım

Ölüm olur, yağarım bu kentin üzerine

Linç edilir yıldızları kayar korkusundan 

Ayrılığın kavgasına kan verir gece

Yenik düşmez kıyamdaki emeller

Dağların şahikasında, karanlık dağılmaz bu kentin 

Silahlı bir militan olur varılmaz yarınlara

Aşiret kuralları belirler bu çıkmazları

Yasaklanır vuslat güneşlere

Artık hükmü kalmamıştır umudun 

Şarkılar susar bağrında şafağın

Kızıl bir düş gibi düş-tün gözlerimden

Gidiyorsan, gideceksen, 

Kal deyişlerimi öpmüyorsa gülüşlerin 

Toprağa dönüşür bu beden

İntihar olur yağarım bu “lanet” kentin üzerine…', 'Dizginlenemeyen kör talih uyanır  Sığınacak yer bulunmaz kaçış Dört bir yana ölüm fermanları yayılır Kalem kırılır paranoyak meclislerde Var...', ARRAY['Türk Edebiyatı','Şiir','Dündar Sansur']::text[], 8.5, '{"poet":"Dündar Sansur","poet_slug":"dundar-sansur","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gitme-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
